// COLUMN METADATA (keyed by asset name)
// ─────────────────────────────────────────────
const ASSET_COLUMNS = {
  // ── orders_archive (Solix CDP) ──
  "orders_archive":    ["order_id","customer_id","product_id","order_date","status","amount","currency","region","archived_at"],
  // ── customers_archive (Solix CDP) ──
  "customers_archive": ["customer_id","email","phone","first_name","last_name","date_of_birth","address","country","legal_hold_flag","archived_at"],
  // ── orders (Snowflake) ──
  "orders":          ["order_id","customer_id","product_id","order_date","status","amount","currency","discount","region","shipping_address","created_at","updated_at"],
  // -- AWS Glue. raw_clickstream is deliberately NESTED: Glue tables over S3 carry STRUCT
  //    and ARRAY types, which Atlan supports to 15 levels. A dotted name here is a nested
  //    path within one column, not a separate asset. --
  "raw_clickstream":   ["event_id","event_ts","user_id","device.type","device.os","device.os_version","payload.page","payload.referrer","payload.utm.source","payload.utm.campaign","items[].sku","items[].qty"],
  "sessions_enriched": ["session_id","user_id","started_at","ended_at","event_count","device_type","utm_source","landing_page"],
  "vw_daily_sessions": ["session_date","sessions","users","avg_events_per_session"],
  // -- orders_fact (Snowflake, built by the fct_revenue dbt model) --
  "orders_fact":       ["order_id","customer_id","revenue","order_status","order_date","region"],
  // ── customers (Snowflake) ──
  "customers":       ["customer_id","email","phone","first_name","last_name","date_of_birth","address","city","country","segment","created_at","updated_at"],
  // ── dim_products (Snowflake) ──
  "dim_products":    ["product_id","sku","name","category","sub_category","brand","unit_price","cost","is_active","created_at"],
  // ── transactions (Snowflake / Finance) ──
  "transactions":    ["transaction_id","account_id","counterparty_id","amount","currency","exchange_rate","type","status","date","reference","created_at"],
  // ── vw_order_summary (Snowflake View) ──
  "vw_order_summary":["order_id","customer_id","customer_name","product_id","total_amount","discount_pct","region","order_date"],
  // ── product_events (PostgreSQL) ──
  "product_events":  ["event_id","user_id","session_id","event_type","event_name","page","properties","platform","timestamp","ip_address"],
  // ── user_sessions (PostgreSQL) ──
  "user_sessions":   ["session_id","user_id","start_time","end_time","duration_sec","page_views","bounce","device_type","browser","ip_address"],
  // ── users (PostgreSQL) ──
  "users":           ["user_id","email","password_hash","phone","first_name","last_name","role","status","created_at","last_login","email_verified"],
  // ── vw_active_users (PostgreSQL View) ──
  "vw_active_users": ["user_id","email","session_count","last_login","days_active"],
  // ── user_events (Databricks) ──
  "user_events":     ["event_id","user_id","event_type","event_name","session_id","device","os","app_version","properties","timestamp"],
  // ── feature_store (Databricks) ──
  "feature_store":   ["user_id","churn_score","ltv_score","recommendation_score","days_since_purchase","avg_order_value","purchase_count","updated_at"],
  // ── vw_daily_active (Databricks View) ──
  "vw_daily_active": ["date","dau","wau","mau","new_users","churned_users"],
  // ── employees (Oracle) ──
  "employees":       ["employee_id","first_name","last_name","email","phone","hire_date","department_id","job_title","salary","manager_id","status","national_id"],
  // ── departments (Oracle) ──
  "departments":     ["department_id","name","parent_department_id","cost_center","manager_id","location"],
  // ── gl_accounts (Oracle) ──
  "gl_accounts":     ["account_id","account_code","account_name","account_type","balance","currency","parent_account_id","is_active","created_at"],
  // ── vw_headcount (Oracle View) ──
  "vw_headcount":    ["department_id","department_name","headcount","avg_salary","open_positions"],
  // ── app_orders (MySQL) ──
  "app_orders":      ["order_id","user_id","product_id","quantity","unit_price","total","status","created_at","fulfilled_at"],
  // ── app_users (MySQL) ──
  "app_users":       ["user_id","email","phone","first_name","last_name","address","city","signup_source","created_at"],
  // ── app_products (MySQL) ──
  "app_products":    ["product_id","name","sku","description","price","cost","stock_qty","category","is_active"],
  // ── vw_recent_orders (MySQL View) ──
  "vw_recent_orders":["order_id","user_id","product_name","quantity","total","status","order_date"],
};

// ─────────────────────────────────────────────
// LEGAL HOLD — held-records mock + partial unhold
// ─────────────────────────────────────────────
// Held rows are defined by a hold rule's criteria, not an enumerated list, so for the
// prototype we deterministically materialize a plausible record set from the table +
// criteria. A partial unhold never deletes the rule — it adds the selected record keys
// to the rule's releasedKeys (an exclusion list). A row is "held" when it matches the
// criteria AND its key is not released. Row-pick and criteria-group release both funnel
// through the same releasedKeys mechanism; criteria release just selects a whole group.
const _lhHash = (s)=>{ let h=0; const str=String(s); for(let i=0;i<str.length;i++){ h=(h*31+str.charCodeAt(i))>>>0; } return h; };
const _LH_FIRST=["Rowan","Priya","Marco","Dana","Sam","Lena","Ivan","Mona","Carlos","Nadia","Theo","Aisha","Bruno","Elsa","Omar","Yuki","Hana","Diego"];
const _LH_LAST =["Ellis","Nair","Bianchi","Whitfield","Okafor","Vogel","Petrov","Haddad","Reyes","Costa","Lang","Khan","Moreau","Berg","Farah","Tan","Silva","Roy"];
const heldRecordsFor = (tableName, holdCriteria) => {
  const crit = (holdCriteria||[]).filter(c=>c&&c.column);
  const groupCol = (crit[0]&&crit[0].column) || "custodian";
  let vals = Array.from(new Set(crit.map(c=>c.value).filter(Boolean)))
    .flatMap(v=>String(v).split(/[,;]/).map(x=>x.trim().replace(/^["']|["']$/g,"")).filter(Boolean));
  if(vals.length<2) vals = vals.concat(["Matter-2211","Matter-3480"]);
  vals = Array.from(new Set(vals)).slice(0,4);
  const seed = _lhHash(tableName||"tbl");
  const prefix = ((tableName||"REC").replace(/[^a-z]/gi,"").slice(0,4).toUpperCase()) || "REC";
  const n = 10 + (seed%6);
  const rows = [];
  for(let i=0;i<n;i++){
    const r = _lhHash((tableName||"t")+"#"+i);
    rows.push({
      key: prefix+"-"+(10000+i),
      person: _LH_FIRST[r%_LH_FIRST.length]+" "+_LH_LAST[(r>>5)%_LH_LAST.length],
      groupCol,
      groupVal: vals[i%vals.length],
      opened: "2026-"+String(1+(r%9)).padStart(2,"0")+"-"+String(10+(r%18)).padStart(2,"0"),
    });
  }
  return rows;
};

// Inline SVG spinner (SMIL so it animates without any global @keyframes).
const _Spinner = ({ size=12, color }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" style={{flexShrink:0,display:"block"}}>
    <circle cx="12" cy="12" r="9" stroke={`${color}33`} strokeWidth="3"/>
    <path d="M12 3a9 9 0 0 1 9 9" stroke={color} strokeWidth="3" strokeLinecap="round">
      <animateTransform attributeName="transform" type="rotate" from="0 12 12" to="360 12 12" dur="0.8s" repeatCount="indefinite"/>
    </path>
  </svg>
);

// An unhold isn't an instant action — it's a short approval workflow (the requester files it,
// the table owner signs off). Showing it as a 3-step tracker lets the requester (rule card) and
// the approver (inbox) both see exactly where the request stands. The in-flight step shows a
// spinner ("loading") until the owner signs off; then it flips to a green "Records released".
// status: "pending" (awaiting owner) | "approved"/"released" | "rejected". variant flips the
// final label full vs partial.
const UnholdStepper = ({ status="pending", variant="full", compact=false }) => {
  const done = status==="approved" || status==="released";
  const rejected = status==="rejected";
  const finalLabel = rejected ? "Rejected" : (variant==="partial" ? "Records released" : "Hold released");
  const steps = [
    { label:"Requested",    st:"done" },
    { label:"Owner review", st: (done||rejected) ? "done" : "current" },
    { label: finalLabel,    st: done ? "done" : (rejected ? "loading" : "loading") },
  ];
  const clr = st => st==="done" ? T.green : st==="current"||st==="loading" ? T.amber : st==="rejected" ? T.rose : T.textMuted;
  const dot = compact?7:9, fs = compact?10:11, lineW = compact?12:22, sp = compact?12:14;
  // The final step is "loading" only while genuinely in flight; rejected recolors it rose.
  const realStep = (s,i) => (i===2 && rejected) ? {...s, st:"rejected", label:"Rejected"} : s;
  const indicator = (st) => {
    if(st==="current"||st==="loading") return <_Spinner size={sp} color={T.amber}/>;
    if(st==="done") return (
      <span style={{width:sp,height:sp,borderRadius:"50%",background:T.green,display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
        <svg width={compact?7:8} height={compact?7:8} viewBox="0 0 10 10" fill="none"><path d="M2 5l2 2 4-5" stroke="#fff" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round"/></svg>
      </span>
    );
    return <span style={{width:dot,height:dot,borderRadius:"50%",background: st==="rejected"?T.rose:"transparent",border:`1.5px solid ${clr(st)}`,display:"inline-block",flexShrink:0}}/>;
  };
  return (
    <div style={{display:"flex",alignItems:"center",flexWrap:"wrap",rowGap:4}}>
      {steps.map((s0,i)=>{ const s=realStep(s0,i); return (
        <div key={i} style={{display:"flex",alignItems:"center"}}>
          {i>0 && <span style={{width:lineW,height:1.5,background: (s.st==="loading")?T.border:clr(s.st),opacity:0.55,margin:"0 6px"}}/>}
          <span style={{display:"flex",alignItems:"center",gap:5}}>
            {indicator(s.st)}
            <span style={{fontSize:fs,fontWeight: (s.st==="current"||s.st==="loading"||s.st==="rejected")?700:600,color:clr(s.st),whiteSpace:"nowrap"}}>{s.label}</span>
          </span>
        </div>
      );})}
    </div>
  );
};

// Panel launched from the legal-hold rule row (edit mode, hold approved). Presentational +
// local selection state; store writes go through the module-level addEnfApproval/pushNotif.
// Released keys (approved) come from rule.releasedKeys; pending keys are read live from the
// enfApprovals store so a request shows "Release pending" the instant it's filed.
const ManageHoldModal = ({ rule, policyId, policyName, approver, meHandle, enfApprovals, onClose, onToast }) => {
  const [selected, setSelected] = useState(()=>new Set());
  const [reason, setReason] = useState("");
  const records = heldRecordsFor(rule.table, rule.holdCriteria);
  const releasedSet = new Set(rule.releasedKeys||[]);
  const pendingSet = new Set(
    (enfApprovals||[])
      .filter(a=>a.policyId===policyId && a.baseRuleId===rule.id && a.action==="Partial Unhold" && a.status==="pending")
      .flatMap(a=>a.keys||[])
  );
  const stateOf = k => releasedSet.has(k) ? "released" : pendingSet.has(k) ? "pending" : "held";
  const heldRecords = records.filter(r=>stateOf(r.key)==="held");
  const selectableKeys = heldRecords.map(r=>r.key);
  const allSel = selectableKeys.length>0 && selectableKeys.every(k=>selected.has(k));
  const crit = (rule.holdCriteria||[]).filter(c=>c&&c.column);
  const critStr = crit.length
    ? crit.map(c=>`${c.column} ${c.operator||"="} ${c.value||"…"}`).join(" and ")
    : "all rows in the table";

  const toggle = k => setSelected(prev=>{ const n=new Set(prev); n.has(k)?n.delete(k):n.add(k); return n; });
  const toggleAll = () => setSelected(allSel ? new Set() : new Set(selectableKeys));

  const fileRequest = (keys, reasonText, label) => {
    if(!keys.length) return;
    addEnfApproval({ policyId, policyName, ruleId:rule.id+"-punhold-"+Date.now(), baseRuleId:rule.id,
      action:"Partial Unhold", table:rule.table||"—", approver, requestedBy:meHandle,
      keys, reason:reasonText||"", count:keys.length, groupLabel:label||null });
    pushNotif({ category:"Policy", type:"alert", title:`Partial unhold requested · ${rule.table||"table"}`,
      body:`${meHandle} requested to release ${keys.length} record${keys.length>1?"s":""} from the legal hold on ${rule.table||"the target table"}${label?` (${label})`:""} — awaiting approval from ${approver}.`,
      nav:"policymanager", navArg:{policyId} });
    onToast(`Partial unhold requested — ${keys.length} record${keys.length>1?"s":""} pending approval from ${approver}`,"success");
    setSelected(new Set());
    setReason("");
  };

  const totalHeld = records.filter(r=>stateOf(r.key)!=="released").length;
  const pendCount = records.filter(r=>stateOf(r.key)==="pending").length;
  const relCount  = releasedSet.size;
  // Selecting records is enough to file the request — the reason is captured for the audit
  // trail but isn't a hard gate (an empty-reason request used to silently do nothing).
  const canUnholdSel = selected.size>0;

  const badge = totalHeld===0
    ? { txt:"Fully released", bg:`${T.green}18`, fg:T.green }
    : pendCount>0
      ? { txt:`${pendCount} release pending`, bg:`${T.amber}18`, fg:T.amber }
      : { txt:"Hold active", bg:`${T.rose}14`, fg:T.rose };

  const sel_s = { padding:"7px 9px", background:T.bgElevated, border:`1px solid ${T.border}`, borderRadius:7, color:T.text, fontSize:12, outline:"none", boxSizing:"border-box" };

  return (
    <div onClick={onClose} style={{position:"fixed",inset:0,background:"rgba(0,0,0,.45)",zIndex:1000,display:"flex",justifyContent:"flex-end"}}>
      <div onClick={e=>e.stopPropagation()} style={{width:520,maxWidth:"92vw",height:"100vh",background:T.bgSurface,borderLeft:`1px solid ${T.border}`,display:"flex",flexDirection:"column",overflow:"hidden",boxShadow:"-24px 0 80px rgba(0,0,0,.4)"}}>
        {/* Header */}
        <div style={{padding:"18px 22px 14px",borderBottom:`1px solid ${T.border}`,display:"flex",alignItems:"flex-start",justifyContent:"space-between",gap:12}}>
          <div>
            <div style={{display:"flex",alignItems:"center",gap:8}}>
              <svg width="16" height="16" viewBox="0 0 16 16" fill="none"><rect x="3" y="7" width="10" height="7" rx="1.5" stroke={T.rose} strokeWidth="1.4"/><path d="M5.5 7V5a2.5 2.5 0 0 1 5 0v2" stroke={T.rose} strokeWidth="1.4"/></svg>
              <span style={{fontSize:15,fontWeight:700,color:T.text}}>Partial unhold — release records</span>
            </div>
            <div style={{fontSize:12,color:T.textMuted,marginTop:4}}>{rule.table||"—"} · legal hold · {policyName}</div>
          </div>
          <div style={{display:"flex",alignItems:"center",gap:8}}>
            <span style={{fontSize:11,fontWeight:700,padding:"3px 10px",borderRadius:10,background:badge.bg,color:badge.fg,whiteSpace:"nowrap"}}>{badge.txt}</span>
            <button onClick={onClose} style={{background:"none",border:"none",color:T.textMuted,cursor:"pointer",fontSize:20,lineHeight:1,padding:"0 2px"}}>×</button>
          </div>
        </div>
        {/* Criteria summary */}
        <div style={{padding:"9px 22px",borderBottom:`1px solid ${T.border}`,background:`${T.accent}06`,fontSize:11.5,color:T.textSub}}>
          <span style={{color:T.textMuted}}>Hold criteria: </span>
          <span style={{fontFamily:"monospace",color:T.text}}>{critStr}</span>
          <span style={{color:T.textMuted}}>  ·  {totalHeld} held{relCount?` · ${relCount} released`:""}</span>
        </div>
        {/* Release status — a partial unhold is an owner-approved request, not an instant edit.
            While a request is in flight the stepper spins ("loading"); it flips to a green
            "Records released" once the owner signs off. */}
        <div style={{padding:"10px 22px",borderBottom:`1px solid ${T.border}`,display:"flex",alignItems:"center",gap:12,flexWrap:"wrap"}}>
          <span style={{fontSize:10.5,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.05em"}}>Release status</span>
          {pendCount>0
            ? <UnholdStepper status="pending" variant="partial" compact/>
            : relCount>0
              ? <UnholdStepper status="released" variant="partial" compact/>
              : <span style={{fontSize:11.5,color:T.textMuted}}>No release requested yet</span>}
          <span style={{fontSize:11,color:T.textMuted,marginLeft:"auto"}}>Approver: <span style={{color:T.textSub,fontWeight:600}}>{approver}</span></span>
        </div>
        <div style={{overflowY:"auto",padding:"16px 22px",display:"flex",flexDirection:"column",gap:18}}>
          {/* ── Release specific records (row-pick) ── */}
          <div>
            <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:10,marginBottom:8}}>
              <div>
                <div style={{fontSize:11,fontWeight:700,color:T.textSub}}>Release specific records</div>
                <div style={{fontSize:11,color:T.textMuted}}>Hand-pick the rows to release from the hold. Add a reason for the audit trail. The rest of the hold stays active.</div>
              </div>
              <label style={{display:"flex",alignItems:"center",gap:6,fontSize:11,color:T.textSub,cursor:selectableKeys.length?"pointer":"default",whiteSpace:"nowrap"}}>
                <input type="checkbox" checked={allSel} disabled={!selectableKeys.length} onChange={toggleAll}/> Select all
              </label>
            </div>
            <div style={{border:`1px solid ${T.border}`,borderRadius:8,overflow:"hidden"}}>
              {records.map((rec,i)=>{
                const st = stateOf(rec.key);
                const disabled = st!=="held";
                return (
                  <div key={rec.key} style={{display:"flex",alignItems:"center",gap:10,padding:"8px 11px",borderTop:i?`1px solid ${T.border}`:"none",opacity:disabled?0.55:1,background:selected.has(rec.key)?`${T.accent}0d`:"transparent"}}>
                    <input type="checkbox" disabled={disabled} checked={selected.has(rec.key)} onChange={()=>toggle(rec.key)} style={{cursor:disabled?"default":"pointer"}}/>
                    <div style={{flex:1,minWidth:0}}>
                      <div style={{fontSize:12,color:T.text}}>{rec.person} <span style={{fontFamily:"monospace",fontSize:11,color:T.textMuted}}>{rec.key}</span></div>
                      <div style={{fontSize:11,color:T.textMuted}}>{rec.groupCol} {rec.groupVal} · opened {rec.opened}</div>
                    </div>
                    <span style={{fontSize:10,fontWeight:700,padding:"2px 8px",borderRadius:9,whiteSpace:"nowrap",
                      background: st==="released"?`${T.green}18`:st==="pending"?`${T.amber}18`:`${T.rose}14`,
                      color: st==="released"?T.green:st==="pending"?T.amber:T.rose}}>
                      {st==="released"?"Released":st==="pending"?"Release pending":"Held"}
                    </span>
                  </div>
                );
              })}
            </div>
            <div style={{marginTop:10}}>
              <input value={reason} onChange={e=>setReason(e.target.value)} placeholder="Reason for release (optional) — e.g. custodian no longer relevant to matter"
                style={{...sel_s,width:"100%",cursor:"text"}}/>
            </div>
          </div>
        </div>
        {/* Footer */}
        <div style={{padding:"13px 22px",borderTop:`1px solid ${T.border}`,display:"flex",alignItems:"center",justifyContent:"space-between",gap:10}}>
          <span style={{fontSize:11,color:T.textMuted}}>{selected.size} selected</span>
          <div style={{display:"flex",gap:9}}>
            <button onClick={onClose} style={{padding:"8px 16px",borderRadius:8,background:"transparent",border:`1px solid ${T.border}`,color:T.textSub,fontSize:12,cursor:"pointer",fontWeight:500}}>Close</button>
            <button disabled={!canUnholdSel} onClick={()=>fileRequest(Array.from(selected), reason.trim(), null)}
              style={{padding:"8px 16px",borderRadius:8,background:canUnholdSel?T.amber:`${T.amber}33`,border:"none",color:canUnholdSel?"#1a1200":`${T.amber}`,fontSize:12,fontWeight:700,cursor:canUnholdSel?"pointer":"default"}}>
              Request unhold ({selected.size})
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

// Removing an active, approved legal hold releases records, so the rule's remove control opens a
// small dropdown — Full unhold (release everything, rule goes away) or Partial unhold (pick
// records, hold stays), both owner-approved — instead of deleting outright. asX renders the same
// "×" as every other rule (so legal hold looks identical); otherwise a labelled button.
// Self-contained: owns its open state, closes on outside click.
const HoldRemoveMenu = ({ onFull, onPartial, style, asX=false }) => {
  const [open, setOpen] = useState(false);
  const Item = ({ accent, title, desc, icon, onClick }) => (
    <button onClick={onClick}
      style={{display:"flex",alignItems:"flex-start",gap:10,textAlign:"left",width:"100%",padding:"10px 11px",borderRadius:7,background:"none",border:"none",cursor:"pointer",transition:"background .1s"}}
      onMouseEnter={e=>e.currentTarget.style.background=`${accent}12`}
      onMouseLeave={e=>e.currentTarget.style.background="none"}>
      <span style={{width:24,height:24,borderRadius:6,background:`${accent}18`,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,marginTop:1}}>{icon}</span>
      <span style={{flex:1,minWidth:0}}>
        <span style={{display:"block",fontSize:12.5,fontWeight:700,color:T.text}}>{title}</span>
        <span style={{display:"block",fontSize:11,color:T.textMuted,lineHeight:1.45,marginTop:2}}>{desc}</span>
      </span>
    </button>
  );
  return (
    <div style={{position:"relative",display:"inline-flex",flexShrink:0,...(style||{})}}>
      {asX ? (
        <button onClick={()=>setOpen(o=>!o)} title="Remove rule"
          style={{background:"none",border:"none",cursor:"pointer",color:open?T.amber:T.textMuted,fontSize:15,padding:"0 2px",lineHeight:1,flexShrink:0}}>×</button>
      ) : (
        <button onClick={()=>setOpen(o=>!o)}
          style={{display:"flex",alignItems:"center",gap:6,fontSize:11,fontWeight:600,padding:"6px 11px",borderRadius:7,border:`1px solid ${T.amber}55`,background:`${T.amber}0d`,color:T.amber,cursor:"pointer"}}>
          <svg width="12" height="12" viewBox="0 0 16 16" fill="none"><rect x="3" y="7" width="10" height="7" rx="1.5" stroke="currentColor" strokeWidth="1.4"/><path d="M5.5 7V4.8a2.5 2.5 0 0 1 4.9-.6" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round"/></svg>
          Remove rule
          <svg width="9" height="9" viewBox="0 0 10 10" fill="none" style={{transform:open?"rotate(180deg)":"none",transition:"transform .12s"}}><path d="M2 3.5l3 3 3-3" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round" strokeLinejoin="round"/></svg>
        </button>
      )}
      {open && (
        <>
          <div onClick={()=>setOpen(false)} style={{position:"fixed",inset:0,zIndex:40}}/>
          <div style={{position:"absolute",top:"calc(100% + 5px)",[asX?"right":"left"]:0,zIndex:50,width:252,background:T.bgSurface,border:`1px solid ${T.border}`,borderRadius:10,boxShadow:"0 14px 44px rgba(0,0,0,.3)",overflow:"hidden",padding:4}}>
            <Item accent={T.rose} title="Full unhold" desc="Release all records and delete this rule"
              onClick={()=>{setOpen(false); onFull&&onFull();}}
              icon={<svg width="13" height="13" viewBox="0 0 16 16" fill="none"><rect x="3" y="7" width="10" height="7" rx="1.5" stroke={T.rose} strokeWidth="1.4"/><path d="M5.5 7V4.8a2.5 2.5 0 0 1 4.9-.6" stroke={T.rose} strokeWidth="1.4" strokeLinecap="round"/></svg>}/>
            <Item accent={T.amber} title="Partial unhold" desc="Release specific records; the hold stays active"
              onClick={()=>{setOpen(false); onPartial&&onPartial();}}
              icon={<svg width="13" height="13" viewBox="0 0 16 16" fill="none"><path d="M3 8h7M3 5h10M3 11h5" stroke={T.amber} strokeWidth="1.4" strokeLinecap="round"/></svg>}/>
          </div>
        </>
      )}
    </div>
  );
};

// ─────────────────────────────────────────────
// TAG MANAGEMENT MOCK DATA
// ─────────────────────────────────────────────
