// ─────────────────────────────────────────────
// TAG PROVIDER
// ─────────────────────────────────────────────
function TagProvider({ children }) {
  const [tagDefs,          setTagDefs]          = useState(INITIAL_TAG_DEFS);
  const [assignments,      setAssignments]      = useState(INITIAL_ASSIGNMENTS);
  const [connectorConfigs, setConnectorConfigs] = useState(INITIAL_CONNECTOR_CONFIGS);
  const [inbox,            setInbox]            = useState(INITIAL_INBOX);
  const [tagPolicies,      setTagPolicies]      = useState(INITIAL_TAG_POLICIES);
  const [propagationJobs,  setPropagationJobs]  = useState(INITIAL_PROP_JOBS);
  const [reverseSyncRuns,  setReverseSyncRuns]  = useState(INITIAL_REVERSE_SYNC_RUNS);

  const unresolvedCount = inbox.filter(i => !i.resolvedAt).length;
  const conflictCount   = Object.values(assignments).flat().filter(a => a.status==='conflict').length;
  const pendingCount    = Object.values(assignments).flat().filter(a => a.status==='pending').length;

  const getAssetAssignments = (assetId) => assignments[assetId] || [];
  const getTagDef           = (tagId)   => tagDefs.find(t => t.id===tagId);

  const applyTag = (assetId, tagId, options={}) => {
    const { origin='manual', sourceSystem=null, appliedBy='Current User' } = options;
    const tagDef = tagDefs.find(t=>t.id===tagId);
    if (!tagDef) return;
    const existing = (assignments[assetId]||[]).find(a=>a.tagId===tagId && a.status!=='rejected');
    if (existing) return;
    const status = tagDef.governanceRequired ? 'pending' : 'active';
    const newA = { id:'a'+Date.now(), tagId, assetId, origin, sourceSystem, sourceSystems:sourceSystem?[sourceSystem]:[], status, appliedBy, appliedAt:new Date().toISOString(), stewardNote:'', propagationChain:[] };
    setAssignments(prev=>({...prev,[assetId]:[...(prev[assetId]||[]),newA]}));
    if (status==='pending') {
      setInbox(prev=>[{ id:'i'+Date.now(), type:'pending_approval', tagName:tagDef.name, assetId, assetName:String(assetId), domain:'Unknown', sourceSystem:null, note:`Applied by ${appliedBy}. Awaiting steward approval.`, metadata:{appliedBy, propagationMode:tagDef.propagationMode, downstreamCount:0}, createdAt:new Date().toISOString(), resolvedAt:null, resolvedBy:null, resolution:null },...prev]);
    }
    setTagDefs(prev=>prev.map(t=>t.id===tagId?{...t,usageCount:t.usageCount+1}:t));
  };

  const removeTag = (assetId, assignmentId, stewardNote='') => {
    setAssignments(prev=>({...prev,[assetId]:(prev[assetId]||[]).map(a=>a.id===assignmentId?{...a,status:'rejected',stewardNote}:a)}));
  };

  const resolveInboxItem = (itemId, resolution, note='') => {
    const item = inbox.find(i=>i.id===itemId);
    if (!item) return;
    setInbox(prev=>prev.map(i=>i.id===itemId?{...i,resolvedAt:new Date().toISOString(),resolvedBy:'Current User',resolution}:i));
    if (item.type==='pending_approval') {
      setAssignments(prev=>({...prev,[item.assetId]:(prev[item.assetId]||[]).map(a=>{
        const def=tagDefs.find(t=>t.id===a.tagId);
        if(!def||def.name!==item.tagName) return a;
        if(resolution==='approve'||resolution==='approve_propagate') return {...a,status:'active'};
        if(resolution==='reject') return {...a,status:'rejected',stewardNote:note};
        return a;
      })}));
    }
    if (item.type==='sync_conflict') {
      setAssignments(prev=>({...prev,[item.assetId]:(prev[item.assetId]||[]).map(a=>{
        const def=tagDefs.find(t=>t.id===a.tagId);
        if(!def||def.name!==item.tagName) return a;
        if(resolution==='accept_source') return {...a,status:'active',stewardNote:''};
        if(resolution==='keep_override') return {...a,status:'rejected',stewardNote:note||item.metadata?.stewardNote||''};
        return a;
      })}));
    }
  };

  const createTagDef = (def) => {
    setTagDefs(prev=>[...prev,{cert:'Draft',...def,id:'t'+Date.now(),usageCount:0,sourceAliases:def.sourceAliases||[],createdAt:new Date().toISOString(),createdBy:'Current User'}]);
  };

  const updateTagDef = (id, patch) => setTagDefs(prev=>prev.map(t=>t.id===id?{...t,...patch,name:(patch.name??t.name)}:t));

  const deleteTagDef = (id) => setTagDefs(prev=>prev.filter(x=>x.id!==id));

  const updateConnectorConfig = (connectorId, patch) => setConnectorConfigs(prev=>({...prev,[connectorId]:{...prev[connectorId],...patch}}));

  const upsertNameMapping = (connectorId, mapping) => {
    setConnectorConfigs(prev=>{
      const cfg=prev[connectorId];
      const exists=cfg.nameMappings.find(m=>m.id===mapping.id);
      const newMappings=exists
        ? cfg.nameMappings.map(m=>m.id===mapping.id?{...m,...mapping}:m)
        : [...cfg.nameMappings,{...mapping,id:'m'+Date.now(),status:mapping.edgTagId?'mapped':'unmapped'}];
      return {...prev,[connectorId]:{...cfg,nameMappings:newMappings}};
    });
  };

  const updateTagPolicies = (patch) => setTagPolicies(prev=>({...prev,...patch}));

  // ── Propagation as a tracked background job ──
  const getPropagationJobs = (assetId, tagId) =>
    propagationJobs
      .filter(j => j.assetId===assetId && (tagId ? j.tagId===tagId : true))
      .sort((a,b)=> (b.startedAt||'').localeCompare(a.startedAt||''));

  // ── Reverse-sync observability ──
  const getReverseSyncRuns = (filter={}) => reverseSyncRuns
    .filter(r => (filter.tagId?r.tagId===filter.tagId:true) && (filter.connId?r.connId===filter.connId:true))
    .sort((a,b)=> (b.startedAt||'').localeCompare(a.startedAt||''));

  // Which connectors this tag actively reverse-syncs to (push-enabled connection + an on source-tag mapping).
  const pushTargetsForTag = (tagId) => {
    const def = tagDefs.find(t=>t.id===tagId); if(!def) return [];
    const tagDefault = def.reverseSyncEnabled ?? (def.category==='sensitivity'||def.category==='regulatory');
    const out=[];
    Object.entries(connectorConfigs).forEach(([connId,cfg])=>{
      if(!cfg.reverseSyncEnabled) return;
      const ms=(cfg.nameMappings||[]).filter(m=>m.edgTagId===tagId);
      const onM=ms.find(m=>(m.reverseSync ?? tagDefault));
      if(onM) out.push({connId, alias: onM.reverseSyncAlias||onM.sourceTagName});
    });
    return out;
  };

  // Rollup for provenance chips: how many objects pushed for a tag (optionally to one connector) + last push time.
  const pushSummaryForTag = (tagId, connId=null) => {
    const runs = reverseSyncRuns.filter(r=>r.tagId===tagId && (connId?r.connId===connId:true));
    const objects = runs.reduce((n,r)=>n+(r.objects||[]).length,0);
    const lastAt = runs.map(r=>r.finishedAt||r.startedAt).filter(Boolean).sort().slice(-1)[0]||null;
    return { objects, lastAt, runs:runs.length };
  };

  // Record a reverse-sync execution (one run per push-enabled connector for this tag).
  const logReverseSync = (tagId, objectNames=[], trigger='manual', connIdFilter=null) => {
    const tgts = pushTargetsForTag(tagId).filter(t=>!connIdFilter||t.connId===connIdFilter);
    if(!tgts.length || !objectNames.length) return 0;
    const now = new Date().toISOString();
    const runs = tgts.map(t=>({ id:'rs'+Date.now()+'_'+t.connId, connId:t.connId, tagId, trigger, startedAt:now, finishedAt:now, status:'done', objects:objectNames.map(n=>({name:n, alias:t.alias, result:'success'})) }));
    setReverseSyncRuns(prev=>[...runs,...prev]);
    return runs.reduce((n,r)=>n+r.objects.length,0);
  };

  const startPropagation = (assetId, tagId, scope, meta={}) => {
    const id = 'pj'+Date.now();
    const target = meta.target ?? 0;
    const job = { id, assetId, tagId, scope, status:'queued', startedAt:new Date().toISOString(), finishedAt:null, updated:0, target, by: meta.by||'Current User', targets: meta.targets||[] };
    setPropagationJobs(prev=>[job,...prev]);
    // Simulate the async background worker: queued → running → done.
    setTimeout(()=>setPropagationJobs(prev=>prev.map(j=>j.id===id?{...j,status:'running',updated:Math.ceil(target/2)}:j)), 600);
    setTimeout(()=>{
      setPropagationJobs(prev=>prev.map(j=>j.id===id?{...j,status:'done',updated:target,finishedAt:new Date().toISOString()}:j));
      // ── Incremental chain: newly-propagated objects that carry a reverse-sync tag get pushed back automatically (event-driven) ──
      const base = meta.baseName || 'object';
      const names = (meta.targets&&meta.targets.length) ? meta.targets : Array.from({length:Math.min(target,4)},(_,i)=>`${base}.downstream_${i+1}`);
      logReverseSync(tagId, names, 'scheduled');
    }, 1500);
    return id;
  };

  // Reverse-sync intent lives on the tag (one toggle); connector-level capability gates whether it actually pushes.
  const setTagReverseSync = (tagId, enabled) => setTagDefs(prev=>prev.map(t=>t.id===tagId?{...t,reverseSyncEnabled:enabled}:t));

  return (
    <TagContext.Provider value={{ tagDefs, assignments, connectorConfigs, inbox, tagPolicies, propagationJobs, reverseSyncRuns, unresolvedCount, conflictCount, pendingCount, getAssetAssignments, getTagDef, applyTag, removeTag, resolveInboxItem, createTagDef, updateTagDef, deleteTagDef, updateConnectorConfig, upsertNameMapping, updateTagPolicies, getPropagationJobs, startPropagation, setTagReverseSync, getReverseSyncRuns, pushSummaryForTag, logReverseSync }}>
      {children}
    </TagContext.Provider>
  );
}

