// ── Shared reactive store for contract approval inbox items ──
const _contractApprovalSubs = new Set();
let _contractApprovalItems = [];
const addContractApprovalItem = (item) => {
  _contractApprovalItems = [item, ..._contractApprovalItems];
  _contractApprovalSubs.forEach(fn => fn());
};
const useContractApprovals = () => {
  const [, force] = useState(0);
  useEffect(() => { const fn = () => force(n => n + 1); _contractApprovalSubs.add(fn); return () => { _contractApprovalSubs.delete(fn); }; }, []);
  return _contractApprovalItems;
};

// ── Shared reactive store for DQ incidents ──
// One source the Data Quality view and the Inbox share, so resolving a dq_alert
// from the inbox actually closes the matching incident in the Data Quality section.
const _dqiSubs = new Set();
let _dqiState = DQ_INCIDENTS.map(i => ({...i}));
const dqiSet = (updater) => {
  _dqiState = typeof updater === "function" ? updater(_dqiState) : updater;
  _dqiSubs.forEach(fn => fn());
};
const resolveIncidentsForAsset = (assetPath, assetName, note="") => dqiSet(prev => prev.map(i =>
  ((i.table === assetPath || (assetName && i.table.endsWith("." + assetName))) && (i.status === "Open" || i.status === "In Progress"))
    ? {...i, status:"Resolved", resolutionReason: note || i.resolutionReason || "Resolved from Inbox", resolved:"just now",
        timeline:[...(i.timeline||[]), {action:"Resolved from Inbox", by:"You", at:"Just now", note: note || undefined}]}
    : i));
const useDQIncidents = () => {
  const [, force] = useState(0);
  useEffect(() => { const fn = () => force(n => n + 1); _dqiSubs.add(fn); return () => { _dqiSubs.delete(fn); }; }, []);
  return [_dqiState, dqiSet];
};

