const CERT_META = {
  Draft:       {color:"#6b7280",bg:"rgba(107,114,128,.1)",border:"rgba(107,114,128,.25)",icon:"◐"},
  "In Review": {color:"#d97706",bg:"rgba(217,119,6,.1)",  border:"rgba(217,119,6,.25)",  icon:"⏳"},
  Approved:    {color:"#16a34a",bg:"rgba(22,163,74,.1)",  border:"rgba(22,163,74,.25)",  icon:"✓"},
  Rejected:    {color:"#e11d48",bg:"rgba(225,29,72,.1)",  border:"rgba(225,29,72,.25)",  icon:"✕"},
  Deprecated:  {color:"#7c3aed",bg:"rgba(124,58,237,.1)", border:"rgba(124,58,237,.25)", icon:"—"},
};
const STATUS_META = CERT_META;

// ── Shared reactive store for glossary terms ──
// One source the Glossary view and the Inbox share, so approving a submitted term
// from the inbox publishes it (status → Approved) in the Glossary section.
const _gtSubs = new Set();
let _gtState = GLOSSARY_TERMS.map(t => ({...t}));
const gtSet = (updater) => {
  _gtState = typeof updater === "function" ? updater(_gtState) : updater;
  _gtSubs.forEach(fn => fn());
};
const setTermStatus = (termId, status) => gtSet(prev => prev.map(t => t.id === termId ? {...t, cert:status, status} : t));
const useGlossaryTerms = () => {
  const [, force] = useState(0);
  useEffect(() => { const fn = () => force(n => n + 1); _gtSubs.add(fn); return () => { _gtSubs.delete(fn); }; }, []);
  return [_gtState, gtSet];
};

// Term lifecycle valid transitions — Draft → In Review → Approved → Deprecated
// Rejected is a terminal state from In Review only
const LIFECYCLE_TRANSITIONS = {
  Draft:       ["In Review"],
  "In Review": ["Approved","Rejected","Draft"],
  Approved:    ["Deprecated","In Review"],
  Rejected:    [],
  Deprecated:  [],
};

const GlossaryView = ({onToast, deepLinkTermId}) => {
  const {role:gvRole, roleCfg:gvRoleCfg} = useRole();
  const meHandle = ((gvRoleCfg&&gvRoleCfg.email)||"you@jnj").split("@")[0];
  const [glossaries, setGlossaries] = useState(GLOSSARY_DATA);
  const [terms,      setTerms]      = useGlossaryTerms(); // shared store — synced with Inbox
  const [selG,       setSelG]       = useState("g1");
  const [selCat,     setSelCat]     = useState(null);
  const [selTerm,    setSelTerm]    = useState(null);
  useEffect(()=>{
    if(!deepLinkTermId) return;
    const t = terms.find(x=>x.id===deepLinkTermId);
    if(t){ setSelG(t.glossary); setSelCat(null); setSelTerm(deepLinkTermId); setTermTab("overview"); }
  },[deepLinkTermId]);
  const [expG,       setExpG]       = useState({"g1":true});
  const [expCat,     setExpCat]     = useState({"c1":true,"c2":true});
  const [q,          setQ]          = useState("");
  const [termTab,    setTermTab]    = useState("overview");
  const [commentText,setCommentText]= useState("");
  const [aiLoading,  setAiLoading]  = useState(false);
  const [hovered,    setHovered]    = useState(null);
  const [modal,      setModal]      = useState(null);
  const [form,       setForm]       = useState({});
  const [addingRef,  setAddingRef]  = useState(false);
  const [refForm,    setRefForm]    = useState({label:"",url:""});
  const [addingRelated,setAddingRelated] = useState(false);
  const [ctxMenu,      setCtxMenu]       = useState(null);
  const [gTab,         setGTab]          = useState("overview");
  const [auditModal,   setAuditModal]    = useState(null);
  const [rejectReason, setRejectReason]  = useState("");
  const [deprecateReason,setDeprecateReason] = useState("");
  const [showHealth,   setShowHealth]    = useState(false);
  const [transitionModal,setTransitionModal] = useState(null);
  const [synonymInput, setSynonymInput]  = useState("");
  const [glossEditModal,setGlossEditModal] = useState(null);
  const [glossModalSearch,setGlossModalSearch] = useState("");
  const [showAllGlossOwners,  setShowAllGlossOwners]   = useState(false);
  const [showAllGlossStewards,setShowAllGlossStewards] = useState(false);
  const [termMenuOpen,        setTermMenuOpen]         = useState(false);

  useEffect(()=>{
    if(!ctxMenu) return;
    const close=()=>{setCtxMenu(null);};
    document.addEventListener("mousedown",close);
    return ()=>document.removeEventListener("mousedown",close);
  },[ctxMenu]);

  useEffect(()=>{ setShowAllGlossOwners(false); setShowAllGlossStewards(false); },[selTerm]);

  const glossary  = glossaries.find(g=>g.id===selG);
  const category  = glossary?.categories.find(c=>c.id===selCat);
  const term      = selTerm ? terms.find(t=>t.id===selTerm) : null;
  const catTerms  = selCat ? terms.filter(t=>t.glossary===selG&&t.category===selCat) : [];
  const allTermsInGlossary = terms.filter(t=>t.glossary===selG);
  const searchResults = q.trim().length>1
    ? terms.filter(t=>t.term.toLowerCase().includes(q.toLowerCase())||t.definition?.toLowerCase().includes(q.toLowerCase()))
    : [];

  const USERS   = ["maya.chen","sarah.kim","alex.wu","dev.patel","lisa.ray","priya.nair","james.oh"];
  const DOMAINS = ["Commerce","Finance","Product","Marketing","ML","Engineering"];
  const ava     = name => name.split(".").map(s=>s[0].toUpperCase()).join("");
  const TAG_COLORS_GLOSS = {
    PII:{bg:"rgba(225,29,72,.1)",color:"#e11d48",border:"rgba(225,29,72,.25)"},
    revenue:{bg:"rgba(37,99,235,.08)",color:"#2563eb",border:"rgba(37,99,235,.2)"},
    finance:{bg:"rgba(37,99,235,.08)",color:"#2563eb",border:"rgba(37,99,235,.2)"},
    KPI:{bg:"rgba(22,163,74,.08)",color:"#16a34a",border:"rgba(22,163,74,.2)"},
    sensitive:{bg:"rgba(124,58,237,.08)",color:"#7c3aed",border:"rgba(124,58,237,.2)"},
    events:{bg:"rgba(6,182,212,.08)",color:"#0891b2",border:"rgba(6,182,212,.2)"},
    model:{bg:"rgba(99,102,241,.08)",color:"#6366f1",border:"rgba(99,102,241,.2)"},
    etl:{bg:"rgba(245,158,11,.08)",color:"#d97706",border:"rgba(245,158,11,.2)"},
    marketing:{bg:"rgba(236,72,153,.08)",color:"#db2777",border:"rgba(236,72,153,.2)"},
    dimension:{bg:"rgba(20,184,166,.08)",color:"#0d9488",border:"rgba(20,184,166,.2)"},
  };

  const openModal = (type,data={}) => { setModal({type,data}); setForm({...data}); };
  const closeModal = () => { setModal(null); setForm({}); };

  const goToTerm = id => {
    const t = terms.find(x=>x.id===id);
    if(!t) return;
    setSelG(t.glossary); setSelCat(null); setSelTerm(id); setTermTab("overview");
    setExpG(p=>({...p,[t.glossary]:true}));
    if(t.category) setExpCat(p=>({...p,[t.category]:true}));
  };

  // ── Glossary CRUD ──
  const doCreateGlossary = () => {
    if(!form.name?.trim()) return;
    const g = {id:`g${Date.now()}`,name:form.name.trim(),icon:form.icon||"📘",desc:form.desc||"",categories:[]};
    setGlossaries(p=>[...p,g]);
    setSelG(g.id); setSelCat(null); setSelTerm(null);
    setExpG(p=>({...p,[g.id]:true}));
    closeModal(); onToast(`Glossary "${g.name}" created`,"success");
  };
  const doUpdateGlossary = () => {
    if(!form.name?.trim()) return;
    setGlossaries(p=>p.map(g=>g.id===modal.data.id?{...g,name:form.name.trim(),icon:form.icon||g.icon,desc:form.desc??g.desc}:g));
    closeModal(); onToast("Glossary updated","success");
  };
  const doDeleteGlossary = id => {
    setTerms(p=>p.filter(t=>t.glossary!==id));
    const rest = glossaries.filter(g=>g.id!==id);
    setGlossaries(rest);
    if(selG===id){ setSelG(rest[0]?.id||null); setSelCat(null); setSelTerm(null); }
    closeModal(); onToast("Glossary deleted","success");
  };

  // ── Category CRUD ──
  const doCreateCategory = () => {
    if(!form.name?.trim()) return;
    const cat = {id:`cat${Date.now()}`,name:form.name.trim()};
    setGlossaries(p=>p.map(g=>g.id===selG?{...g,categories:[...g.categories,cat]}:g));
    setSelCat(cat.id); setSelTerm(null);
    setExpCat(p=>({...p,[cat.id]:true}));
    setExpG(p=>({...p,[selG]:true}));
    closeModal(); onToast(`Category "${cat.name}" created`,"success");
  };
  const doUpdateCategory = () => {
    if(!form.name?.trim()) return;
    setGlossaries(p=>p.map(g=>g.id===selG?{...g,categories:g.categories.map(c=>c.id===modal.data.id?{...c,name:form.name.trim()}:c)}:g));
    closeModal(); onToast("Category updated","success");
  };
  const doDeleteCategory = id => {
    setTerms(p=>p.map(t=>t.category===id?{...t,category:""}:t));
    setGlossaries(p=>p.map(g=>g.id===selG?{...g,categories:g.categories.filter(c=>c.id!==id)}:g));
    if(selCat===id){ setSelCat(null); setSelTerm(null); }
    closeModal(); onToast("Category deleted","success");
  };

  // ── Term CRUD ──
  const doCreateTerm = () => {
    if(!form.term?.trim()) return;
    const t = {
      id:`t${Date.now()}`,term:form.term.trim(),abbr:form.abbr||"—",
      glossary:form.glossary||selG,category:form.category||selCat||"",
      domain:form.domain||"Commerce",owner:form.owner||"maya.chen",
      steward:form.owner||"maya.chen",linked:0,
      cert:form.cert||"Draft",
      definition:form.definition||"",relatedTerms:[],tags:[],refs:[],
      linkedAssets:[],readme:"",
      activity:[{user:form.owner||"maya.chen",avatar:ava(form.owner||"maya.chen"),action:"Created term",time:"Just now"}],
    };
    setTerms(p=>[...p,t]);
    goToTerm(t.id);
    closeModal(); onToast(`Term "${t.term}" created`,"success");
  };
  const doUpdateTerm = () => {
    if(!form.term?.trim()) return;
    setTerms(p=>p.map(t=>t.id===modal.data.id?{...t,term:form.term.trim(),abbr:form.abbr||t.abbr,definition:form.definition??t.definition,domain:form.domain||t.domain,owner:form.owner||t.owner,category:form.category||t.category,cert:form.cert||t.cert}:t));
    closeModal(); onToast("Term updated","success");
  };
  const canSetTermStatus = t => gvRole==="admin" || (t&&(t.owner===meHandle||t.steward===meHandle));
  const doDeleteTerm = id => {
    const t = terms.find(x=>x.id===id);
    if(t && !canSetTermStatus(t)){
      requestDeletion({kind:"term", targetId:id, name:t.term, requestedBy:meHandle, note:"Requested via glossary", owner:t.owner||t.steward||null});
      pushNotif({category:"Ownership", type:"alert", title:`Deletion requested · ${t.term} (term)`, body:`${meHandle} requested to delete this term`, nav:"glossary", navArg:{termId:id}});
      closeModal(); onToast("Deletion requested — pending owner approval","success");
      return;
    }
    setTerms(p=>p.filter(t=>t.id!==id));
    if(selTerm===id) setSelTerm(null);
    closeModal(); onToast("Term deleted","success");
  };

  // ── Term metadata ──
  const patchTerm = (id,fields) => setTerms(p=>p.map(t=>t.id===id?{...t,...fields}:t));
  // (an addTag helper lived here, referencing a tagInput state that does not exist in
  //  this component and calling nothing. Deleted rather than wired to a phantom input.)
  const doAddRef = id => {
    if(!refForm.url.trim()) return;
    patchTerm(id,{refs:[...(term?.refs||[]),{label:refForm.label||refForm.url,url:refForm.url}]});
    setRefForm({label:"",url:""}); setAddingRef(false);
    onToast("Reference added","success");
  };
  const doAddRelated = (id,rid) => {
    if(!rid||(term?.relatedTerms||[]).includes(rid)) return;
    patchTerm(id,{relatedTerms:[...(term?.relatedTerms||[]),rid]});
    setAddingRelated(false); onToast("Related term linked","success");
  };

  // ── Workflow / Lifecycle ──
  const CURRENT_USER = meHandle;
  const CURRENT_DOMAIN = "Commerce";

  const canTransition = (t, toStatus) => {
    const allowed = LIFECYCLE_TRANSITIONS[t.status||t.cert]||[];
    return allowed.includes(toStatus);
  };

  const transitionTerm = (id, toStatus, note="") => {
    const t = terms.find(x=>x.id===id);
    if(!t) return;
    // Submitting your own draft for review needs no permission — but every other transition
    // (approve/reject/deprecate/return-to-draft) is a real decision, gated like Tags/Domains:
    // owner/steward/admin act directly, everyone else's click becomes a real request routed
    // to the term's steward.
    if(toStatus!=="In Review" && !canSetTermStatus(t)){
      requestStatusChange({kind:"term", targetId:id, name:t.term, requestedStatus:toStatus, requestedBy:meHandle, note, steward:t.steward||t.owner||null});
      patchTerm(id,{cert:"In Review", status:"In Review"});
      pushNotif({category:"Status", type:"field_updated", title:`Status change requested · ${t.term}`, body:`${meHandle} requested ${toStatus} — awaiting review as steward`, nav:"glossary", navArg:{termId:id}});
      setTransitionModal(null); setRejectReason(""); setDeprecateReason("");
      onToast("Status change requested — pending steward approval","success");
      return;
    }
    const now = new Date().toISOString().slice(0,10);
    const logEntry = {action:toStatus==="Approved"?"Approved":toStatus==="In Review"?"Submitted for Review":toStatus==="Deprecated"?"Deprecated":toStatus==="Draft"?"Returned to Draft":toStatus==="Rejected"?"Rejected":"Status changed to "+toStatus, by:CURRENT_USER, at:now, note};
    const actEntry = {user:CURRENT_USER, avatar:ava(CURRENT_USER), action:logEntry.action+(note?`: ${note}`:""), time:"Just now"};
    const updates = {
      cert:toStatus, status:toStatus,
      auditLog:[logEntry,...(t.auditLog||[])],
      activity:[actEntry,...(t.activity||[])],
    };
    if(toStatus==="Approved")    updates.reviewedAt = now;
    if(toStatus==="Deprecated")  updates.deprecationReason = note||"Deprecated by steward";
    if(toStatus==="Rejected")    updates.rejectionReason = note||"Rejected by steward";
    patchTerm(id, updates);
    const pendingReq = _statusReqs.find(r=>r.kind==="term"&&r.targetId===id&&r.status==="pending");
    if(pendingReq) resolveStatusRequest(pendingReq.id, toStatus==="Rejected"?"rejected":"approved");
    setTransitionModal(null); setRejectReason(""); setDeprecateReason("");
    const toastMsg = toStatus==="Approved"?"Term approved":toStatus==="In Review"?"Term submitted for review":toStatus==="Deprecated"?"Term deprecated":toStatus==="Rejected"?"Term rejected":toStatus==="Draft"?"Term returned to draft":"Term updated";
    onToast(toastMsg, toStatus==="Rejected"?"error":"success");
  };

  const addSynonym = id => {
    const s = synonymInput.trim();
    if(!s) return;
    const t = terms.find(x=>x.id===id);
    if((t?.synonyms||[]).includes(s)) return;
    patchTerm(id,{synonyms:[...(t?.synonyms||[]),s]});
    setSynonymInput(""); onToast("Synonym added","success");
  };
  const removeSynonym = (id,s) => {
    const t = terms.find(x=>x.id===id);
    patchTerm(id,{synonyms:(t?.synonyms||[]).filter(x=>x!==s)});
  };

  // legacy shims kept for any callers
  const submitForReview = id => transitionTerm(id,"In Review");
  const approveTerm = id => transitionTerm(id,"Approved");

  const addComment = id => {
    if(!commentText.trim()) return;
    const t = terms.find(x=>x.id===id);
    patchTerm(id,{activity:[{user:CURRENT_USER,avatar:ava(CURRENT_USER),action:commentText,time:"Just now",isComment:true},...(t?.activity||[])]});
    setCommentText(""); onToast("Comment added","success");
  };

  // ── AI suggest ──
  const aiSuggestDefinition = async name => {
    if(!name?.trim()) return;
    setAiLoading(true);
    try {
      const res = await fetch("https://api.anthropic.com/v1/messages",{
        method:"POST",headers:{"Content-Type":"application/json"},
        body:JSON.stringify({model:"claude-sonnet-4-20250514",max_tokens:200,
          system:"You are a data governance expert. Write a concise business definition for a data glossary term. 1-3 sentences. No preamble.",
          messages:[{role:"user",content:`Write a business glossary definition for: "${name}"`}]
        })
      });
      const data = await res.json();
      setForm(f=>({...f,definition:data.content?.[0]?.text||""}));
    } catch(e){}
    setAiLoading(false);
  };

  // ── Inline icon helpers ──
  const IcEdit  = () => <svg width="11" height="11" viewBox="0 0 12 12" fill="none"><path d="M8.5 1.5l2 2L4 10H2v-2L8.5 1.5z" stroke="currentColor" strokeWidth="1.1" strokeLinejoin="round"/></svg>;
  const IcTrash = () => <svg width="11" height="11" viewBox="0 0 12 12" fill="none"><path d="M2 3h8M5 3V2h2v1M4 3l.5 7.5h3L8 3" stroke="currentColor" strokeWidth="1.1" strokeLinecap="round"/></svg>;
  const IcPlus  = () => <svg width="10" height="10" viewBox="0 0 12 12" fill="none"><path d="M6 2v8M2 6h8" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round"/></svg>;
  const IcChev  = ({deg=0}) => <svg width="9" height="9" viewBox="0 0 10 10" fill="none" style={{transform:`rotate(${deg}deg)`,transition:"transform .15s",flexShrink:0}}><path d="M1.5 3.5l3.5 3.5 3.5-3.5" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round"/></svg>;
  const IcBack  = () => <svg width="14" height="14" viewBox="0 0 16 16" fill="none"><path d="M10 3L5 8l5 5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round"/></svg>;
  const IcLink  = () => <svg width="11" height="11" viewBox="0 0 12 12" fill="none"><path d="M5 6a2.5 2.5 0 003.5.4l1.5-1.5A2.5 2.5 0 006.5 1.4L5.8 2" stroke="currentColor" strokeWidth="1.2" strokeLinecap="round"/><path d="M7 6a2.5 2.5 0 00-3.5-.4L2 7.1A2.5 2.5 0 005.5 10.6l.7-.7" stroke="currentColor" strokeWidth="1.2" strokeLinecap="round"/></svg>;
  const IcX     = ({s=10}) => <svg width={s} height={s} viewBox="0 0 10 10" fill="none"><path d="M2 2l6 6M8 2l-6 6" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round"/></svg>;

  const NavBtn = ({children,title,...props}) => (
    <button title={title} {...props} style={{width:22,height:22,display:"flex",alignItems:"center",justifyContent:"center",background:"transparent",border:"none",color:T.textMuted,cursor:"pointer",borderRadius:4,...(props.style||{})}}
      onMouseEnter={e=>{e.currentTarget.style.background=T.bgHover;e.currentTarget.style.color=T.text;}}
      onMouseLeave={e=>{e.currentTarget.style.background="transparent";e.currentTarget.style.color=T.textMuted;}}>{children}</button>
  );

  const TermCard = ({t}) => {
    const cm = CERT_META[t.cert]||CERT_META.Draft;
    const sm = STATUS_META[t.status]||STATUS_META.Draft;
    return (
      <div onClick={()=>goToTerm(t.id)} style={{padding:"14px 16px",background:selTerm===t.id?T.accentDim:T.bg,border:`1px solid ${selTerm===t.id?T.accent:T.border}`,borderRadius:10,cursor:"pointer",transition:"all .15s"}}
        onMouseEnter={e=>{if(selTerm!==t.id){e.currentTarget.style.borderColor=T.accent+"66";e.currentTarget.style.transform="translateY(-1px)";}}}
        onMouseLeave={e=>{if(selTerm!==t.id){e.currentTarget.style.borderColor=T.border;e.currentTarget.style.transform="none";}}}>
        <div style={{display:"flex",alignItems:"flex-start",justifyContent:"space-between",gap:8,marginBottom:5}}>
          <div>
            <div style={{fontSize:13,fontWeight:700,color:T.text}}>{t.term}</div>
            {t.abbr&&t.abbr!=="—"&&<div style={{fontSize:10.5,color:T.textMuted,fontFamily:"'Geist Mono',monospace",marginTop:1}}>{t.abbr}</div>}
          </div>
          <span style={{fontSize:10,fontWeight:700,padding:"2px 7px",borderRadius:99,background:cm.bg,color:cm.color,border:`1px solid ${cm.border}`,flexShrink:0}}>{cm.icon} {t.cert}</span>
        </div>
        <div style={{fontSize:11.5,color:T.textSub,lineHeight:1.5,marginBottom:9,overflow:"hidden",display:"-webkit-box",WebkitLineClamp:2,WebkitBoxOrient:"vertical"}}>{t.definition||<span style={{fontStyle:"italic",color:T.textMuted}}>No definition yet.</span>}</div>
        <div style={{display:"flex",alignItems:"center",gap:6,fontSize:10.5,flexWrap:"wrap"}}>
          <span style={{width:6,height:6,borderRadius:"50%",background:sm.color,display:"inline-block",flexShrink:0}}/>
          <span style={{color:sm.color,fontWeight:600}}>{t.status}</span>
          {(t.tags||[]).slice(0,2).map(tag=>{const tc_=TAG_COLORS_GLOSS[tag]||{bg:T.bgElevated,color:T.textSub,border:T.border};return <span key={tag} style={{padding:"2px 8px 2px 7px",borderRadius:4,background:tc_.bg,borderTop:`1px solid ${tc_.border}`,borderRight:`1px solid ${tc_.border}`,borderBottom:`1px solid ${tc_.border}`,borderLeft:`3px solid ${tc_.color}`,color:tc_.color,fontSize:10.5,fontWeight:600}}>{tag}</span>;})}
          <span style={{marginLeft:"auto",color:T.textMuted}}>{t.linked} assets</span>
        </div>
      </div>
    );
  };

  const MetaRow = ({label,children}) => (
    <div style={{marginBottom:16}}>
      <div style={{fontSize:10.5,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.08em",marginBottom:7}}>{label}</div>
      {children}
    </div>
  );
  const GlInput  = ({...p}) => <input {...p} style={{width:"100%",padding:"9px 12px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:8,color:T.text,fontSize:13,outline:"none",boxSizing:"border-box",...(p.style||{})}} onFocus={e=>e.target.style.borderColor=T.accent} onBlur={e=>e.target.style.borderColor=T.border}/>;
  const GlSelect = ({children,...p}) => <select {...p} style={{width:"100%",padding:"8px 10px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:8,color:T.text,fontSize:12,outline:"none",...(p.style||{})}}>{children}</select>;
  const GlTA     = ({...p}) => <textarea {...p} style={{width:"100%",padding:"9px 12px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:8,color:T.text,fontSize:12.5,resize:"vertical",outline:"none",fontFamily:"inherit",lineHeight:1.55,boxSizing:"border-box",...(p.style||{})}} onFocus={e=>e.target.style.borderColor=T.accent} onBlur={e=>e.target.style.borderColor=T.border}/>;
  const GlLabel  = ({children,req}) => <label style={{display:"block",fontSize:11,fontWeight:600,color:T.textSub,marginBottom:5}}>{children}{req&&<span style={{color:T.rose,marginLeft:2}}>*</span>}</label>;

  // ─── CONTEXT MENU ───
  const renderCtxMenu = () => {
    if(!ctxMenu) return null;
    const {type,id,name,x,y} = ctxMenu;
    const close = ()=>setCtxMenu(null);
    const items = type==="glossary" ? [
      {l:"Rename",       fn:()=>{close();openModal("editGlossary",{id,name,icon:glossaries.find(g=>g.id===id)?.icon,desc:glossaries.find(g=>g.id===id)?.desc});}},
      {l:"Add Category", fn:()=>{close();setSelG(id);openModal("newCategory");}},
      {l:"Add Term",     fn:()=>{close();setSelG(id);openModal("newTerm",{});}},
      {l:"Copy Link",    fn:()=>{close();onToast("Link copied","success");}},
      {l:"Delete",       fn:()=>{close();openModal("deleteGlossary",{id,name});}, danger:true},
    ] : type==="category" ? [
      {l:"Rename",    fn:()=>{close();openModal("editCategory",{id,name});}},
      {l:"Add Term",  fn:()=>{close();openModal("newTerm",{category:id});}},
      {l:"Copy Link", fn:()=>{close();onToast("Link copied","success");}},
      {l:"Delete",    fn:()=>{close();openModal("deleteCategory",{id,name});}, danger:true},
    ] : [
      {l:"Edit",      fn:()=>{const t=terms.find(x=>x.id===id);close();openModal("editTerm",{id,term:t?.term,abbr:t?.abbr,definition:t?.definition,domain:t?.domain,owner:t?.owner,category:t?.category,cert:t?.cert});}},
      {l:"Copy Link", fn:()=>{close();onToast("Link copied","success");}},
      {l:"Delete",    fn:()=>{close();openModal("deleteTerm",{id,term:name});}, danger:true},
    ];
    return createPortal(
      <div onMouseDown={e=>e.stopPropagation()} style={{position:"fixed",top:y,left:x,zIndex:9999,background:T.bgSurface,border:`1px solid ${T.border}`,borderRadius:9,boxShadow:"0 8px 28px rgba(0,0,0,.18)",minWidth:168,padding:"4px 0",animation:"scaleIn .1s ease"}}>
        {items.map((item,i)=>(
          <button key={i} onClick={item.fn} style={{width:"100%",padding:"7px 14px",background:"none",border:"none",textAlign:"left",cursor:"pointer",fontSize:12.5,color:item.danger?T.rose:T.text,display:"block"}}
            onMouseEnter={e=>e.currentTarget.style.background=T.bgHover}
            onMouseLeave={e=>e.currentTarget.style.background="none"}>
            {item.l}
          </button>
        ))}
      </div>,
      document.body
    );
  };

  // ─── SIDEBAR ───
  const renderSidebar = () => (
    <div style={{width:240,flexShrink:0,borderRight:`1px solid ${T.border}`,background:T.bgSurface,display:"flex",flexDirection:"column",overflow:"hidden"}}>
      <div style={{padding:"12px 14px 10px",borderBottom:`1px solid ${T.border}`,flexShrink:0}}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:10}}>
          <span style={{fontSize:11,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.08em"}}>Glossaries</span>
          <button onClick={()=>openModal("newGlossary")} title="New Glossary"
            style={{width:22,height:22,borderRadius:5,background:T.bgElevated,border:`1px solid ${T.border}`,color:T.textSub,display:"flex",alignItems:"center",justifyContent:"center",cursor:"pointer"}}
            onMouseEnter={e=>{e.currentTarget.style.background=T.accentDim;e.currentTarget.style.color=T.accent;}}
            onMouseLeave={e=>{e.currentTarget.style.background=T.bgElevated;e.currentTarget.style.color=T.textSub;}}>
            <IcPlus/>
          </button>
        </div>
        <div style={{position:"relative"}}>
          <svg width="13" height="13" viewBox="0 0 14 14" fill="none" style={{position:"absolute",left:9,top:"50%",transform:"translateY(-50%)",color:T.textMuted,pointerEvents:"none"}}><circle cx="6" cy="6" r="4" stroke="currentColor" strokeWidth="1.3"/><path d="M9.5 9.5L13 13" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round"/></svg>
          <input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search terms…"
            style={{width:"100%",padding:"6px 8px 6px 28px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:7,color:T.text,fontSize:12,outline:"none",boxSizing:"border-box"}}
            onFocus={e=>e.target.style.borderColor=T.accent} onBlur={e=>e.target.style.borderColor=T.border}/>
        </div>
      </div>
      <div style={{flex:1,overflowY:"auto",padding:"4px 0"}}>
        {q.trim().length>1 ? (
          <div>
            <div style={{padding:"6px 14px",fontSize:10.5,color:T.textMuted}}>{searchResults.length} result{searchResults.length!==1?"s":""}</div>
            {searchResults.length===0&&<div style={{padding:"16px 14px",textAlign:"center",fontSize:12,color:T.textMuted}}>No terms found.</div>}
            {searchResults.map(t=>(
              <div key={t.id} onClick={()=>{goToTerm(t.id);setQ("");}} style={{display:"flex",alignItems:"center",gap:8,padding:"6px 14px",cursor:"pointer",borderLeft:`2px solid ${selTerm===t.id?T.accent:"transparent"}`,background:selTerm===t.id?T.accentDim:"transparent"}}
                onMouseEnter={e=>{if(selTerm!==t.id)e.currentTarget.style.background=T.bgHover;}}
                onMouseLeave={e=>{if(selTerm!==t.id)e.currentTarget.style.background="transparent";}}>
                <svg width="13" height="13" viewBox="0 0 14 14" fill="none" style={{flexShrink:0,color:T.textMuted}}><rect x="2" y="1.5" width="10" height="11" rx="1.5" stroke="currentColor" strokeWidth="1.2"/><path d="M4.5 5.5h5M4.5 8h3.5" stroke="currentColor" strokeWidth="1.1" strokeLinecap="round"/></svg>
                <div style={{flex:1,minWidth:0}}>
                  <div style={{fontSize:12.5,fontWeight:500,color:selTerm===t.id?T.accent:T.text,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{t.term}</div>
                  <div style={{fontSize:10.5,color:T.textMuted,marginTop:1}}>{glossaries.find(g=>g.id===t.glossary)?.name}</div>
                </div>
              </div>
            ))}
          </div>
        ) : (
          glossaries.map(g=>{
            const isSelG=selG===g.id&&!selCat&&!selTerm;
            const gCount=terms.filter(t=>t.glossary===g.id).length;
            const hovG=hovered===`g:${g.id}`;
            return (
              <div key={g.id}>
                <div onMouseEnter={()=>setHovered(`g:${g.id}`)} onMouseLeave={()=>setHovered(null)}
                  style={{display:"flex",alignItems:"center",padding:"4px 8px 4px 10px",borderLeft:`2px solid ${isSelG?T.accent:"transparent"}`,background:isSelG?T.accentDim:"transparent"}}>
                  <button onClick={()=>{setSelG(g.id);setSelCat(null);setSelTerm(null);setExpG(p=>({...p,[g.id]:!p[g.id]}));}}
                    style={{flex:1,display:"flex",alignItems:"center",gap:6,background:"none",border:"none",cursor:"pointer",padding:"2px 0",minWidth:0}}>
                    <span style={{color:T.textMuted,flexShrink:0,display:"inline-block",transition:"transform .15s",transform:expG[g.id]?"rotate(90deg)":"rotate(0deg)"}}>
                      <svg width="8" height="8" viewBox="0 0 8 8" fill="none"><path d="M2 1.5l3 2.5-3 2.5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/></svg>
                    </span>
                    <svg width="14" height="14" viewBox="0 0 16 16" fill="none" style={{flexShrink:0,color:isSelG?T.accent:T.textSub}}><path d="M2 4h4l1.5 2H14a1 1 0 011 1v6a1 1 0 01-1 1H2a1 1 0 01-1-1V5a1 1 0 011-1z" stroke="currentColor" strokeWidth="1.3" strokeLinejoin="round"/></svg>
                    <span style={{flex:1,fontSize:12.5,fontWeight:600,color:isSelG?T.accent:T.text,textAlign:"left",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{g.name}</span>
                    <span style={{fontSize:10,color:T.textMuted,flexShrink:0}}>{gCount}</span>
                  </button>
                  {hovG&&<button onMouseDown={e=>{e.stopPropagation();const r=e.currentTarget.getBoundingClientRect();setCtxMenu({type:"glossary",id:g.id,name:g.name,x:r.right+4,y:r.top});}}
                    style={{width:20,height:20,borderRadius:4,background:"transparent",border:"none",color:T.textMuted,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,fontSize:14,letterSpacing:1}}
                    onMouseEnter={e=>{e.currentTarget.style.background=T.bgHover;e.currentTarget.style.color=T.text;}}
                    onMouseLeave={e=>{e.currentTarget.style.background="transparent";e.currentTarget.style.color=T.textMuted;}}>···</button>}
                </div>
                {expG[g.id]&&<>
                  {g.categories.map(cat=>{
                    const isSelCat=selCat===cat.id&&!selTerm;
                    const hovCat=hovered===`cat:${cat.id}`;
                    const cCount=terms.filter(t=>t.glossary===g.id&&t.category===cat.id).length;
                    return (
                      <div key={cat.id}>
                        <div onMouseEnter={()=>setHovered(`cat:${cat.id}`)} onMouseLeave={()=>setHovered(null)}
                          style={{display:"flex",alignItems:"center",padding:"3px 8px 3px 26px",borderLeft:`2px solid ${isSelCat?T.accent:"transparent"}`,background:isSelCat?T.accentDim:"transparent"}}>
                          <button onClick={()=>{setSelG(g.id);setSelCat(cat.id);setSelTerm(null);setExpCat(p=>({...p,[cat.id]:!p[cat.id]}));}}
                            style={{flex:1,display:"flex",alignItems:"center",gap:6,background:"none",border:"none",cursor:"pointer",padding:"2px 0",minWidth:0}}>
                            <span style={{color:T.textMuted,flexShrink:0,display:"inline-block",transition:"transform .15s",transform:expCat[cat.id]?"rotate(90deg)":"rotate(0deg)"}}>
                              <svg width="7" height="7" viewBox="0 0 8 8" fill="none"><path d="M2 1.5l3 2.5-3 2.5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/></svg>
                            </span>
                            <svg width="13" height="13" viewBox="0 0 14 14" fill="none" style={{flexShrink:0,color:isSelCat?T.accent:T.textMuted}}><path d="M1.5 3h3.8l.9 1.3H12.5a.7.7 0 01.7.7v5.8a.7.7 0 01-.7.7H1.5a.7.7 0 01-.7-.7V3.7a.7.7 0 01.7-.7z" stroke="currentColor" strokeWidth="1.1" strokeLinejoin="round"/></svg>
                            <span style={{flex:1,fontSize:12,fontWeight:isSelCat?600:500,color:isSelCat?T.accent:T.textSub,textAlign:"left",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{cat.name}</span>
                            <span style={{fontSize:10,color:T.textMuted,flexShrink:0}}>{cCount}</span>
                          </button>
                          {hovCat&&<button onMouseDown={e=>{e.stopPropagation();const r=e.currentTarget.getBoundingClientRect();setCtxMenu({type:"category",id:cat.id,name:cat.name,x:r.right+4,y:r.top});}}
                            style={{width:20,height:20,borderRadius:4,background:"transparent",border:"none",color:T.textMuted,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,fontSize:14,letterSpacing:1}}
                            onMouseEnter={e=>{e.currentTarget.style.background=T.bgHover;e.currentTarget.style.color=T.text;}}
                            onMouseLeave={e=>{e.currentTarget.style.background="transparent";e.currentTarget.style.color=T.textMuted;}}>···</button>}
                        </div>
                        {expCat[cat.id]&&terms.filter(t=>t.glossary===g.id&&t.category===cat.id).map(t=>{
                          const isSelT=selTerm===t.id;
                          const hovT=hovered===`t:${t.id}`;
                          const cm=CERT_META[t.cert]||CERT_META.Draft;
                          return (
                            <div key={t.id} onMouseEnter={()=>setHovered(`t:${t.id}`)} onMouseLeave={()=>setHovered(null)}
                              style={{display:"flex",alignItems:"center",gap:0,padding:"3px 8px 3px 44px",cursor:"pointer",borderLeft:`2px solid ${isSelT?T.accent:"transparent"}`,background:isSelT?T.accentDim:"transparent"}}
                              onMouseEnter2={e=>{if(!isSelT)e.currentTarget.style.background=T.bgHover;}}
                              onMouseLeave2={e=>{if(!isSelT)e.currentTarget.style.background="transparent";}}>
                              <button onClick={()=>goToTerm(t.id)} style={{flex:1,display:"flex",alignItems:"center",gap:6,background:"none",border:"none",cursor:"pointer",padding:"2px 0",minWidth:0}}>
                                <svg width="12" height="12" viewBox="0 0 14 14" fill="none" style={{flexShrink:0,color:isSelT?T.accent:T.textMuted}}><rect x="2" y="1.5" width="10" height="11" rx="1.5" stroke="currentColor" strokeWidth="1.2"/><path d="M4.5 5.5h5M4.5 8h3.5" stroke="currentColor" strokeWidth="1.1" strokeLinecap="round"/></svg>
                                <span style={{flex:1,fontSize:12,fontWeight:isSelT?600:400,color:isSelT?T.accent:T.text,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{t.term}</span>
                                <span style={{width:6,height:6,borderRadius:"50%",background:cm.color,flexShrink:0}}/>
                              </button>
                              {hovT&&<button onMouseDown={e=>{e.stopPropagation();const r=e.currentTarget.getBoundingClientRect();setCtxMenu({type:"term",id:t.id,name:t.term,x:r.right+4,y:r.top});}}
                                style={{width:20,height:20,borderRadius:4,background:"transparent",border:"none",color:T.textMuted,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,fontSize:14,letterSpacing:1,marginLeft:2}}
                                onMouseEnter={e=>{e.currentTarget.style.background=T.bgHover;e.currentTarget.style.color=T.text;}}
                                onMouseLeave={e=>{e.currentTarget.style.background="transparent";e.currentTarget.style.color=T.textMuted;}}>···</button>}
                            </div>
                          );
                        })}
                      </div>
                    );
                  })}
                  {selG===g.id&&(
                    <button onClick={()=>openModal("newCategory")} style={{display:"flex",alignItems:"center",gap:5,padding:"3px 10px 5px 26px",background:"transparent",border:"none",cursor:"pointer",color:T.textMuted,fontSize:11,width:"100%"}}
                      onMouseEnter={e=>e.currentTarget.style.color=T.accent} onMouseLeave={e=>e.currentTarget.style.color=T.textMuted}>
                      <IcPlus/> New Category
                    </button>
                  )}
                </>}
              </div>
            );
          })
        )}
      </div>
    </div>
  );

  // ─── GLOSSARY OVERVIEW ───
  const renderGlossaryOverview = () => {
    if(!glossary) return null;
    const uncategorized=allTermsInGlossary.filter(t=>!glossary.categories.some(c=>c.id===t.category));
    const allOwners=[...new Set(allTermsInGlossary.map(t=>t.owner).filter(Boolean))];
    const TermRow=({t})=>{
      const cm=CERT_META[t.cert]||CERT_META.Draft;
      return (
        <div onClick={()=>goToTerm(t.id)} style={{display:"flex",alignItems:"center",padding:"10px 20px",borderBottom:`1px solid ${T.border}`,cursor:"pointer",transition:"background .1s"}}
          onMouseEnter={e=>e.currentTarget.style.background=T.bgHover}
          onMouseLeave={e=>e.currentTarget.style.background="transparent"}>
          <div style={{flex:1,minWidth:0,display:"flex",alignItems:"center",gap:8}}>
            <svg width="13" height="13" viewBox="0 0 14 14" fill="none" style={{flexShrink:0,color:T.textMuted}}><rect x="2" y="1.5" width="10" height="11" rx="1.5" stroke="currentColor" strokeWidth="1.2"/><path d="M4.5 5.5h5M4.5 8h3.5" stroke="currentColor" strokeWidth="1.1" strokeLinecap="round"/></svg>
            <span style={{fontSize:13,fontWeight:600,color:T.text,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{t.term}</span>
            {t.abbr&&t.abbr!=="—"&&<span style={{fontSize:10.5,color:T.textMuted,fontFamily:"'Geist Mono',monospace",background:T.bgElevated,padding:"1px 6px",borderRadius:4,border:`1px solid ${T.border}`,flexShrink:0}}>{t.abbr}</span>}
          </div>
          <span style={{width:130,flexShrink:0,fontSize:12,color:T.textMuted}}>{glossary.categories.find(c=>c.id===t.category)?.name||"Uncategorized"}</span>
          <span style={{width:110,flexShrink:0,fontSize:10.5,fontWeight:700,padding:"2px 9px",borderRadius:99,background:cm.bg,color:cm.color,border:`1px solid ${cm.border}`,display:"inline-flex",alignItems:"center",gap:4}}>{cm.icon} {t.cert}</span>
          <div style={{width:120,flexShrink:0,display:"flex",alignItems:"center",gap:6}}>
            <div style={{width:22,height:22,borderRadius:6,background:T.accentDim,display:"flex",alignItems:"center",justifyContent:"center",fontSize:8,fontWeight:700,color:T.accent,flexShrink:0}}>{ava(t.owner)}</div>
            <span style={{fontSize:11.5,color:T.textSub,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{t.owner}</span>
          </div>
        </div>
      );
    };
    return (
      <div style={{flex:1,display:"flex",flexDirection:"column",overflow:"hidden"}}>
        <div style={{padding:"24px 28px 0",background:T.bgSurface,borderBottom:`1px solid ${T.border}`,flexShrink:0}}>
          <div style={{display:"flex",alignItems:"flex-start",justifyContent:"space-between",marginBottom:18}}>
            <div style={{display:"flex",alignItems:"center",gap:16}}>
              <div style={{width:56,height:56,borderRadius:16,background:T.bgElevated,border:`1px solid ${T.border}`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:28,flexShrink:0}}>{glossary.icon}</div>
              <div>
                <div style={{fontSize:22,fontWeight:700,color:T.text,letterSpacing:"-0.3px",marginBottom:4}}>{glossary.name}</div>
                {glossary.desc&&<div style={{fontSize:13,color:T.textSub,lineHeight:1.5,maxWidth:520,marginBottom:8}}>{glossary.desc}</div>}
                <div style={{display:"flex",alignItems:"center",gap:16}}>
                  <span style={{display:"flex",alignItems:"center",gap:5,fontSize:12,color:T.textMuted}}><svg width="12" height="12" viewBox="0 0 14 14" fill="none"><rect x="2" y="1.5" width="10" height="11" rx="1.5" stroke="currentColor" strokeWidth="1.2"/><path d="M4.5 5.5h5M4.5 8h3.5" stroke="currentColor" strokeWidth="1.1" strokeLinecap="round"/></svg><strong style={{color:T.text}}>{allTermsInGlossary.length}</strong> terms</span>
                  <span style={{display:"flex",alignItems:"center",gap:5,fontSize:12,color:T.textMuted}}><svg width="12" height="12" viewBox="0 0 14 14" fill="none"><path d="M1.5 3h3.8l.9 1.3H12.5a.7.7 0 01.7.7v5.8a.7.7 0 01-.7.7H1.5a.7.7 0 01-.7-.7V3.7a.7.7 0 01.7-.7z" stroke="currentColor" strokeWidth="1.1" strokeLinejoin="round"/></svg><strong style={{color:T.text}}>{glossary.categories.length}</strong> categories</span>
                  {allOwners.length>0&&<span style={{display:"flex",alignItems:"center",gap:5,fontSize:12,color:T.textMuted}}><svg width="12" height="12" viewBox="0 0 14 14" fill="none"><circle cx="7" cy="5" r="2.5" stroke="currentColor" strokeWidth="1.2"/><path d="M2 12c0-2.5 2.2-4 5-4s5 1.5 5 4" stroke="currentColor" strokeWidth="1.2" strokeLinecap="round"/></svg><strong style={{color:T.text}}>{allOwners.length}</strong> owners</span>}
                </div>
              </div>
            </div>
            <div style={{display:"flex",gap:6,flexShrink:0}}>
              <Btn small ghost onClick={()=>openModal("editGlossary",{id:glossary.id,name:glossary.name,icon:glossary.icon,desc:glossary.desc})}>Edit</Btn>
              <Btn small ghost onClick={()=>openModal("newCategory")}>+ Category</Btn>
              <Btn small variant="primary" onClick={()=>openModal("newTerm",{category:selCat||""})}>+ Term</Btn>
            </div>
          </div>
        </div>
        <div style={{flex:1,overflowY:"auto"}}>
          {(()=>{
            const allT=allTermsInGlossary;
            const totalTerms=allT.length;
            const approved=allT.filter(t=>t.status==="Approved").length;
            const inReview=allT.filter(t=>t.status==="In Review").length;
            const draft=allT.filter(t=>t.status==="Draft").length;
            const deprecated=allT.filter(t=>t.status==="Deprecated").length;
            const rejected=allT.filter(t=>t.status==="Rejected").length;
            const coveragePct=totalTerms>0?Math.round((approved/totalTerms)*100):0;
            const catStats=glossary.categories.map(cat=>{const ct=allT.filter(t=>t.category===cat.id);const ca=ct.filter(t=>t.status==="Approved").length;return{name:cat.name,id:cat.id,total:ct.length,approved:ca,pct:ct.length>0?Math.round((ca/ct.length)*100):0};});
            const unlinked=allT.filter(t=>(t.linkedAssets||[]).length===0&&t.status!=="Deprecated");
            const noDefn=allT.filter(t=>(!t.definition||t.definition.length<10)&&t.status!=="Deprecated");
            const hasData=glossary.categories.length>0||totalTerms>0;
            if(!hasData) return(
              <div style={{textAlign:"center",padding:"72px 20px"}}>
                <div style={{width:52,height:52,borderRadius:14,background:T.bgElevated,border:`1px solid ${T.border}`,display:"flex",alignItems:"center",justifyContent:"center",margin:"0 auto 16px",color:T.textSub}}>
                  <svg width="22" height="22" viewBox="0 0 14 14" fill="none"><path d="M1.5 3h3.8l.9 1.3H12.5a.7.7 0 01.7.7v5.8a.7.7 0 01-.7.7H1.5a.7.7 0 01-.7-.7V3.7a.7.7 0 01.7-.7z" stroke="currentColor" strokeWidth="1.1" strokeLinejoin="round"/></svg>
                </div>
                <div style={{fontSize:15,fontWeight:700,color:T.text,marginBottom:6}}>No categories or terms yet</div>
                <div style={{fontSize:13,color:T.textMuted,marginBottom:20}}>Create a category to start organizing your business terms.</div>
                <div style={{display:"flex",gap:8,justifyContent:"center"}}>
                  <Btn small ghost onClick={()=>openModal("newCategory")}>+ New Category</Btn>
                  <Btn small variant="primary" onClick={()=>openModal("newTerm",{})}>+ New Term</Btn>
                </div>
              </div>
            );
            const coverageColor=coveragePct>=80?"#16a34a":coveragePct>=50?"#d97706":"#e11d48";
            return(
              <div style={{padding:"24px 28px",display:"flex",flexDirection:"column",gap:24}}>

                {/* ── SECTION 1: Stats ── */}
                {totalTerms>0&&(
                  <div style={{display:"grid",gridTemplateColumns:"repeat(5,1fr)",gap:10}}>
                    {[
                      {label:"Total Terms", value:totalTerms,  sub:"in glossary",      color:T.text,    dimColor:T.textMuted, bg:T.bgSurface, border:T.border},
                      {label:"Approved",    value:approved,    sub:"ready to use",      color:"#16a34a", dimColor:"#86efac",   bg:"#f0fdf4",   border:"#bbf7d0"},
                      {label:"In Review",   value:inReview,    sub:"pending sign-off",  color:"#d97706", dimColor:"#fcd34d",   bg:"#fffbeb",   border:"#fde68a"},
                      {label:"Rejected",    value:rejected,    sub:"needs revision",    color:"#e11d48", dimColor:"#fca5a5",   bg:"#fff1f2",   border:"#fecdd3"},
                      {label:"Coverage",    value:`${coveragePct}%`,sub:"approved ratio",color:coverageColor,dimColor:coverageColor,bg:coveragePct>=80?"#f0fdf4":coveragePct>=50?"#fffbeb":"#fff1f2",border:coveragePct>=80?"#bbf7d0":coveragePct>=50?"#fde68a":"#fecdd3"},
                    ].map(m=>(
                      <div key={m.label} style={{padding:"14px 16px",background:m.bg,border:`1px solid ${m.border}`,borderRadius:10}}>
                        <div style={{fontSize:28,fontWeight:800,color:m.color,fontFamily:"'Geist Mono',monospace",lineHeight:1,marginBottom:4}}>{m.value}</div>
                        <div style={{fontSize:12,fontWeight:600,color:m.color,marginBottom:2}}>{m.label}</div>
                        <div style={{fontSize:11,color:m.dimColor,opacity:.75}}>{m.sub}</div>
                      </div>
                    ))}
                  </div>
                )}

                {/* ── SECTION 2: Needs Attention (only shown when issues exist) ── */}
                {(unlinked.length>0||noDefn.length>0)&&(
                  <div>
                    <div style={{fontSize:13,fontWeight:700,color:T.text,marginBottom:12}}>Needs Attention</div>
                    <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12}}>
                      {/* Unlinked terms */}
                      <div style={{background:"#fffbeb",border:"1px solid #fde68a",borderRadius:10,padding:"14px 16px"}}>
                        <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:10}}>
                          <span style={{fontSize:16,lineHeight:1}}>⚠</span>
                          <span style={{fontSize:13,fontWeight:700,color:"#92400e"}}>Unlinked Terms</span>
                          <span style={{marginLeft:"auto",fontSize:11,fontWeight:700,padding:"2px 8px",borderRadius:99,background:"#fef3c7",color:"#d97706",border:"1px solid #fde68a"}}>{unlinked.length}</span>
                        </div>
                        <div style={{fontSize:12,color:"#78350f",marginBottom:10}}>These terms are not linked to any data asset yet.</div>
                        {unlinked.slice(0,5).map(t=>(
                          <div key={t.id} onClick={()=>goToTerm(t.id)}
                            style={{display:"flex",alignItems:"center",gap:8,padding:"6px 0",borderTop:"1px solid #fde68a",cursor:"pointer"}}
                            onMouseEnter={e=>e.currentTarget.style.opacity=".7"} onMouseLeave={e=>e.currentTarget.style.opacity="1"}>
                            <span style={{fontSize:12.5,fontWeight:600,color:"#d97706",flex:1,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{t.term}</span>
                            <span style={{fontSize:10.5,color:"#92400e",flexShrink:0}}>{glossary.categories.find(c=>c.id===t.category)?.name||"Uncategorized"}</span>
                          </div>
                        ))}
                        {unlinked.length>5&&<div style={{fontSize:11,color:"#92400e",paddingTop:6}}>+{unlinked.length-5} more</div>}
                      </div>
                      {/* Missing definitions */}
                      <div style={{background:"#fff1f2",border:"1px solid #fecdd3",borderRadius:10,padding:"14px 16px"}}>
                        <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:10}}>
                          <span style={{fontSize:16,lineHeight:1}}>✕</span>
                          <span style={{fontSize:13,fontWeight:700,color:"#881337"}}>Missing Definitions</span>
                          <span style={{marginLeft:"auto",fontSize:11,fontWeight:700,padding:"2px 8px",borderRadius:99,background:"#ffe4e6",color:"#e11d48",border:"1px solid #fecdd3"}}>{noDefn.length}</span>
                        </div>
                        <div style={{fontSize:12,color:"#9f1239",marginBottom:10}}>These terms have no definition or a very short one.</div>
                        {noDefn.slice(0,5).map(t=>(
                          <div key={t.id} onClick={()=>goToTerm(t.id)}
                            style={{display:"flex",alignItems:"center",gap:8,padding:"6px 0",borderTop:"1px solid #fecdd3",cursor:"pointer"}}
                            onMouseEnter={e=>e.currentTarget.style.opacity=".7"} onMouseLeave={e=>e.currentTarget.style.opacity="1"}>
                            <span style={{fontSize:12.5,fontWeight:600,color:"#e11d48",flex:1,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{t.term}</span>
                            <span style={{fontSize:10.5,color:"#881337",flexShrink:0}}>{glossary.categories.find(c=>c.id===t.category)?.name||"Uncategorized"}</span>
                          </div>
                        ))}
                        {noDefn.length>5&&<div style={{fontSize:11,color:"#9f1239",paddingTop:6}}>+{noDefn.length-5} more</div>}
                      </div>
                    </div>
                  </div>
                )}

              </div>
            );
          })()}
          {allTermsInGlossary.length===0?(
            <div style={{textAlign:"center",padding:"32px 20px",color:T.textMuted}}><div style={{fontSize:15,fontWeight:600,color:T.textSub,marginBottom:8}}>No terms yet</div><Btn small variant="primary" onClick={()=>openModal("newTerm",{})}>+ New Term</Btn></div>
          ):(
            <div style={{padding:"0 28px 28px",display:"flex",flexDirection:"column",gap:16}}>
              {glossary.categories.map(cat=>{
                const cts=allTermsInGlossary.filter(t=>t.category===cat.id);
                if(cts.length===0) return null;
                return (
                  <div key={cat.id} style={{border:`1px solid ${T.border}`,borderRadius:10,overflow:"hidden"}}>
                    {/* Category header */}
                    <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",padding:"10px 16px",background:T.bgElevated,borderBottom:`1px solid ${T.border}`}}>
                      <div style={{display:"flex",alignItems:"center",gap:8}}>
                        <svg width="14" height="14" viewBox="0 0 14 14" fill="none" style={{color:T.textMuted,flexShrink:0}}><path d="M1.5 3h3.8l.9 1.3H12.5a.7.7 0 01.7.7v5.8a.7.7 0 01-.7.7H1.5a.7.7 0 01-.7-.7V3.7a.7.7 0 01.7-.7z" stroke="currentColor" strokeWidth="1.1" strokeLinejoin="round"/></svg>
                        <span style={{fontSize:13,fontWeight:700,color:T.text}}>{cat.name}</span>
                        <span style={{fontSize:11,color:T.textMuted,background:T.bgSurface,border:`1px solid ${T.border}`,borderRadius:99,padding:"1px 7px"}}>{cts.length} term{cts.length!==1?"s":""}</span>
                      </div>
                      <button onClick={e=>{e.stopPropagation();openModal("newTerm",{category:cat.id});}}
                        style={{padding:"3px 10px",borderRadius:5,background:"transparent",border:`1px solid ${T.border}`,color:T.textMuted,fontSize:11,cursor:"pointer"}}
                        onMouseEnter={e=>{e.currentTarget.style.background=T.accentDim;e.currentTarget.style.color=T.accent;e.currentTarget.style.borderColor=T.accent+"55";}}
                        onMouseLeave={e=>{e.currentTarget.style.background="transparent";e.currentTarget.style.color=T.textMuted;e.currentTarget.style.borderColor=T.border;}}>+ Term</button>
                    </div>
                    {/* Terms rows */}
                    {cts.map((t,i)=>{
                      const cm=CERT_META[t.cert]||CERT_META.Draft;
                      return (
                        <div key={t.id} onClick={()=>goToTerm(t.id)}
                          style={{display:"flex",alignItems:"center",padding:"10px 16px",borderBottom:i<cts.length-1?`1px solid ${T.border}`:"none",cursor:"pointer",transition:"background .1s"}}
                          onMouseEnter={e=>e.currentTarget.style.background=T.bgHover} onMouseLeave={e=>e.currentTarget.style.background="transparent"}>
                          <div style={{flex:1,minWidth:0,display:"flex",alignItems:"center",gap:8}}>
                            <svg width="13" height="13" viewBox="0 0 14 14" fill="none" style={{flexShrink:0,color:T.textMuted}}><rect x="2" y="1.5" width="10" height="11" rx="1.5" stroke="currentColor" strokeWidth="1.2"/><path d="M4.5 5.5h5M4.5 8h3.5" stroke="currentColor" strokeWidth="1.1" strokeLinecap="round"/></svg>
                            <span style={{fontSize:13,fontWeight:600,color:T.text,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{t.term}</span>
                            {t.abbr&&t.abbr!=="—"&&<span style={{fontSize:10.5,color:T.textMuted,fontFamily:"'Geist Mono',monospace",background:T.bgElevated,padding:"1px 5px",borderRadius:4,border:`1px solid ${T.border}`,flexShrink:0}}>{t.abbr}</span>}
                          </div>
                          <div style={{width:130,flexShrink:0,paddingLeft:12}}>
                            <span style={{fontSize:10.5,fontWeight:700,padding:"3px 10px",borderRadius:99,background:cm.bg,color:cm.color,border:`1px solid ${cm.border}`,display:"inline-flex",alignItems:"center",gap:4}}>{cm.icon} {t.cert}</span>
                          </div>
                          <div style={{width:150,flexShrink:0,display:"flex",alignItems:"center",gap:6,paddingLeft:8}}>
                            <div style={{width:22,height:22,borderRadius:6,background:T.accentDim,display:"flex",alignItems:"center",justifyContent:"center",fontSize:8,fontWeight:700,color:T.accent,flexShrink:0}}>{ava(t.owner)}</div>
                            <span style={{fontSize:11.5,color:T.textSub,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{t.owner}</span>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                );
              })}
              {(()=>{const unc=allTermsInGlossary.filter(t=>!t.category||!glossary.categories.find(c=>c.id===t.category));return unc.length>0&&(
                <div style={{border:`1px solid ${T.border}`,borderRadius:10,overflow:"hidden"}}>
                  <div style={{display:"flex",alignItems:"center",gap:8,padding:"10px 16px",background:T.bgElevated,borderBottom:`1px solid ${T.border}`}}>
                    <span style={{fontSize:13,fontWeight:700,color:T.textMuted}}>Uncategorized</span>
                    <span style={{fontSize:11,color:T.textMuted,background:T.bgSurface,border:`1px solid ${T.border}`,borderRadius:99,padding:"1px 7px"}}>{unc.length}</span>
                  </div>
                  {unc.map((t,i)=>{const cm=CERT_META[t.cert]||CERT_META.Draft;return(
                    <div key={t.id} onClick={()=>goToTerm(t.id)}
                      style={{display:"flex",alignItems:"center",padding:"10px 16px",borderBottom:i<unc.length-1?`1px solid ${T.border}`:"none",cursor:"pointer",transition:"background .1s"}}
                      onMouseEnter={e=>e.currentTarget.style.background=T.bgHover} onMouseLeave={e=>e.currentTarget.style.background="transparent"}>
                      <div style={{flex:1,minWidth:0,display:"flex",alignItems:"center",gap:8}}>
                        <svg width="13" height="13" viewBox="0 0 14 14" fill="none" style={{flexShrink:0,color:T.textMuted}}><rect x="2" y="1.5" width="10" height="11" rx="1.5" stroke="currentColor" strokeWidth="1.2"/><path d="M4.5 5.5h5M4.5 8h3.5" stroke="currentColor" strokeWidth="1.1" strokeLinecap="round"/></svg>
                        <span style={{fontSize:13,fontWeight:600,color:T.text,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{t.term}</span>
                      </div>
                      <div style={{width:130,flexShrink:0,paddingLeft:12}}>
                        <span style={{fontSize:10.5,fontWeight:700,padding:"3px 10px",borderRadius:99,background:cm.bg,color:cm.color,border:`1px solid ${cm.border}`,display:"inline-flex",alignItems:"center",gap:4}}>{cm.icon} {t.cert}</span>
                      </div>
                      <div style={{width:150,flexShrink:0,display:"flex",alignItems:"center",gap:6,paddingLeft:8}}>
                        <div style={{width:22,height:22,borderRadius:6,background:T.accentDim,display:"flex",alignItems:"center",justifyContent:"center",fontSize:8,fontWeight:700,color:T.accent,flexShrink:0}}>{ava(t.owner)}</div>
                        <span style={{fontSize:11.5,color:T.textSub,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{t.owner}</span>
                      </div>
                    </div>
                  );})}
                </div>
              );})()}
            </div>
          )}
        </div>
      </div>
    );
  };

  // ─── CATEGORY DETAIL ───
  const renderCategoryDetail = () => {
    if(!category||!glossary) return null;
    const certCounts = {};
    catTerms.forEach(t=>{certCounts[t.cert]=(certCounts[t.cert]||0)+1;});
    return (
      <div style={{flex:1,display:"flex",flexDirection:"column",overflow:"hidden"}}>
        <div style={{padding:"20px 28px 0",background:T.bgSurface,borderBottom:`1px solid ${T.border}`,flexShrink:0}}>
          <div style={{display:"flex",alignItems:"center",gap:6,marginBottom:14,fontSize:12,color:T.textMuted}}>
            <button onClick={()=>{setSelCat(null);setSelTerm(null);}} style={{display:"flex",alignItems:"center",gap:5,background:"none",border:"none",cursor:"pointer",color:T.textMuted,padding:0,fontSize:12}}
              onMouseEnter={e=>e.currentTarget.style.color=T.accent} onMouseLeave={e=>e.currentTarget.style.color=T.textMuted}>
              <span style={{fontSize:15}}>{glossary.icon}</span> {glossary.name}
            </button>
            <span style={{color:T.borderLight}}>/</span>
            <span style={{color:T.textSub,fontWeight:600}}>{category.name}</span>
          </div>
          <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:18}}>
            <div style={{display:"flex",alignItems:"center",gap:12}}>
              <div style={{width:44,height:44,borderRadius:12,background:T.bgElevated,border:`1px solid ${T.border}`,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                <svg width="20" height="20" viewBox="0 0 14 14" fill="none" style={{color:T.textSub}}><path d="M1.5 3h3.8l.9 1.3H12.5a.7.7 0 01.7.7v5.8a.7.7 0 01-.7.7H1.5a.7.7 0 01-.7-.7V3.7a.7.7 0 01.7-.7z" stroke="currentColor" strokeWidth="1.1" strokeLinejoin="round"/></svg>
              </div>
              <div>
                <div style={{fontSize:20,fontWeight:700,color:T.text,letterSpacing:"-0.3px"}}>{category.name}</div>
                <div style={{fontSize:12,color:T.textMuted,marginTop:2}}>{catTerms.length} terms · {glossary.name}</div>
              </div>
            </div>
            <div style={{display:"flex",gap:6}}>
              <Btn small ghost onClick={()=>openModal("editCategory",{id:category.id,name:category.name})}>Edit</Btn>
              <Btn small ghost onClick={()=>openModal("deleteCategory",{id:category.id,name:category.name})} style={{color:T.rose,borderColor:T.rose+"44"}}>Delete</Btn>
              <Btn small variant="primary" onClick={()=>openModal("newTerm",{category:selCat})}>+ Term</Btn>
            </div>
          </div>
        </div>
        <div style={{flex:1,overflowY:"auto"}}>
          {catTerms.length===0?(
            <div style={{textAlign:"center",padding:"64px 20px",color:T.textMuted}}>
              <div style={{fontSize:32,marginBottom:10}}>📝</div>
              <div style={{fontSize:14,fontWeight:600,color:T.textSub,marginBottom:6}}>No terms in this category</div>
              <div style={{fontSize:12,marginBottom:16}}>Add terms to build out your business vocabulary.</div>
              <Btn small variant="primary" onClick={()=>openModal("newTerm",{category:selCat})}>+ New Term</Btn>
            </div>
          ):(
            <div>
              <div style={{display:"flex",alignItems:"center",padding:"8px 20px",borderBottom:`1px solid ${T.border}`,background:T.bgSurface,position:"sticky",top:0,zIndex:1}}>
                <span style={{flex:1,fontSize:11,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.06em"}}>Term</span>
                <span style={{width:110,flexShrink:0,fontSize:11,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.06em"}}>Status</span>
                <span style={{width:150,flexShrink:0,paddingLeft:12,fontSize:11,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.06em"}}>Owner</span>
              </div>
              {catTerms.map(t=>{
                const cm=CERT_META[t.cert]||CERT_META.Draft;
                return (
                  <div key={t.id} onClick={()=>goToTerm(t.id)} style={{display:"flex",alignItems:"center",padding:"10px 20px",borderBottom:`1px solid ${T.border}`,cursor:"pointer",transition:"background .1s"}}
                    onMouseEnter={e=>e.currentTarget.style.background=T.bgHover}
                    onMouseLeave={e=>e.currentTarget.style.background="transparent"}>
                    <div style={{flex:1,minWidth:0,display:"flex",alignItems:"center",gap:8}}>
                      <svg width="13" height="13" viewBox="0 0 14 14" fill="none" style={{flexShrink:0,color:T.textMuted}}><rect x="2" y="1.5" width="10" height="11" rx="1.5" stroke="currentColor" strokeWidth="1.2"/><path d="M4.5 5.5h5M4.5 8h3.5" stroke="currentColor" strokeWidth="1.1" strokeLinecap="round"/></svg>
                      <span style={{fontSize:13,fontWeight:600,color:T.text}}>{t.term}</span>
                      {t.abbr&&t.abbr!=="—"&&<span style={{fontSize:10.5,color:T.textMuted,fontFamily:"'Geist Mono',monospace",background:T.bgElevated,padding:"1px 5px",borderRadius:4,border:`1px solid ${T.border}`,flexShrink:0}}>{t.abbr}</span>}
                    </div>
                    <span style={{width:110,flexShrink:0,fontSize:10.5,fontWeight:700,padding:"2px 9px",borderRadius:99,background:cm.bg,color:cm.color,border:`1px solid ${cm.border}`,display:"inline-flex",alignItems:"center",gap:4}}>{cm.icon} {t.cert}</span>
                    <div style={{width:150,flexShrink:0,paddingLeft:12,display:"flex",alignItems:"center",gap:6}}>
                      <div style={{width:22,height:22,borderRadius:6,background:T.accentDim,display:"flex",alignItems:"center",justifyContent:"center",fontSize:8,fontWeight:700,color:T.accent,flexShrink:0}}>{ava(t.owner)}</div>
                      <span style={{fontSize:11.5,color:T.textSub,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{t.owner}</span>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>
    );
  };

  // ─── TERM DETAIL ───
  const renderTermDetail = () => {
    if(!term) return null;
    const cm=CERT_META[term.cert]||CERT_META.Draft;
    const termGlossary=glossaries.find(g=>g.id===term.glossary);
    const termCat=termGlossary?.categories.find(c=>c.id===term.category);
    const Divider=()=><div style={{height:1,background:T.border,margin:"22px 0"}}/>;
    const SectionLabel=({label,action})=>(
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:10}}>
        <span style={{fontSize:13,fontWeight:600,color:T.textSub}}>{label}</span>{action}
      </div>
    );
    const owners = Array.isArray(term.owners) ? term.owners : (term.owner ? [term.owner] : []);
    const stewardsG = Array.isArray(term.stewards)?term.stewards:(term.steward?[term.steward]:[]);
    const ALL_TAGS_GLOSS = ["PII","revenue","finance","KPI","events","sensitive","dimension","model","etl","marketing"];
    const gTagColor = t => TAG_COLORS_GLOSS[t]||{bg:T.bgElevated,color:T.textSub,border:T.border};
    return (
      <><div style={{flex:1,display:"flex",overflow:"hidden",minWidth:0}}>
        <div style={{flex:1,display:"flex",flexDirection:"column",overflow:"hidden"}}>
          <div style={{padding:"16px 28px 0",background:T.bgSurface,borderBottom:`1px solid ${T.border}`,flexShrink:0}}>
            <div style={{display:"flex",alignItems:"center",gap:6,marginBottom:12,fontSize:12,color:T.textMuted,flexWrap:"wrap"}}>
              <button onClick={()=>{setSelCat(null);setSelTerm(null);}} style={{display:"flex",alignItems:"center",gap:5,background:"none",border:"none",cursor:"pointer",color:T.textMuted,padding:0,fontSize:12}}
                onMouseEnter={e=>e.currentTarget.style.color=T.accent} onMouseLeave={e=>e.currentTarget.style.color=T.textMuted}>
                <span style={{fontSize:15}}>{termGlossary?.icon}</span> {termGlossary?.name}
              </button>
              {termCat&&<><span style={{color:T.borderLight}}>/</span><button onClick={()=>{setSelCat(term.category);setSelTerm(null);}} style={{background:"none",border:"none",cursor:"pointer",color:T.textMuted,fontSize:12,padding:0}} onMouseEnter={e=>e.currentTarget.style.color=T.accent} onMouseLeave={e=>e.currentTarget.style.color=T.textMuted}>{termCat.name}</button></>}
              <span style={{color:T.borderLight}}>/</span><span style={{color:T.textSub,fontWeight:600}}>{term.term}</span>
            </div>
            <div style={{display:"flex",alignItems:"flex-start",justifyContent:"space-between",marginBottom:14,gap:12}}>
              <div>
                <div style={{display:"flex",alignItems:"center",gap:10,flexWrap:"wrap",marginBottom:8}}>
                  <span style={{fontSize:22,fontWeight:700,color:T.text,letterSpacing:"-0.4px"}}>{term.term}</span>
                  {term.abbr&&term.abbr!=="—"&&<span style={{fontSize:12.5,color:T.textMuted,fontFamily:"'Geist Mono',monospace",background:T.bgElevated,padding:"3px 10px",borderRadius:6,border:`1px solid ${T.border}`}}>{term.abbr}</span>}
                </div>
                <div style={{display:"flex",alignItems:"center",gap:8,flexWrap:"wrap"}}>
                  <span style={{fontSize:11.5,fontWeight:700,padding:"3px 10px",borderRadius:99,background:cm.bg,color:cm.color,border:`1px solid ${cm.border}`,display:"inline-flex",alignItems:"center",gap:5}}>{cm.icon} {term.cert}</span>
                  <span style={{fontSize:11.5,padding:"3px 10px",borderRadius:99,background:T.accentDim,color:T.accent,border:`1px solid ${T.accent}33`,fontWeight:600}}>{term.domain}</span>
                </div>
              </div>
              <div style={{display:"flex",gap:5,flexShrink:0,position:"relative"}} onClick={e=>e.stopPropagation()}>
                <button onClick={()=>setTermMenuOpen(p=>!p)}
                  style={{width:34,height:34,borderRadius:8,background:T.bgElevated,border:`1px solid ${T.border}`,color:T.text,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",fontSize:18,fontWeight:700,transition:"all .15s"}}
                  onMouseEnter={e=>e.currentTarget.style.borderColor=T.accent} onMouseLeave={e=>e.currentTarget.style.borderColor=T.border}>⋮</button>
                {termMenuOpen&&(
                  <div style={{position:"absolute",top:"calc(100% + 6px)",right:0,zIndex:500,background:T.bgSurface,border:`1px solid ${T.border}`,borderRadius:10,boxShadow:"0 12px 36px rgba(0,0,0,.28)",minWidth:210,overflow:"hidden"}}>
                    <button onClick={()=>{openModal("editTerm",{id:term.id,term:term.term,abbr:term.abbr,definition:term.definition,domain:term.domain,owner:term.owner,category:term.category,cert:term.cert});setTermMenuOpen(false);}}
                      style={{width:"100%",display:"flex",alignItems:"flex-start",gap:10,padding:"11px 14px",background:"none",border:"none",cursor:"pointer",textAlign:"left",borderBottom:`1px solid ${T.border}`}}
                      onMouseEnter={e=>e.currentTarget.style.background=T.bgHover} onMouseLeave={e=>e.currentTarget.style.background="none"}>
                      <span style={{fontSize:14,marginTop:1}}>🖊️</span>
                      <div><div style={{fontSize:12,fontWeight:600,color:T.text}}>Bulk Edit</div><div style={{fontSize:11,color:T.textMuted,marginTop:1}}>Edit all term fields</div></div>
                    </button>
                    <button onClick={()=>{openModal("deleteTerm",{id:term.id,term:term.term});setTermMenuOpen(false);}}
                      style={{width:"100%",display:"flex",alignItems:"flex-start",gap:10,padding:"11px 14px",background:"none",border:"none",cursor:"pointer",textAlign:"left"}}
                      onMouseEnter={e=>e.currentTarget.style.background="rgba(239,68,68,.07)"} onMouseLeave={e=>e.currentTarget.style.background="none"}>
                      <span style={{fontSize:14,marginTop:1}}>🗑️</span>
                      <div><div style={{fontSize:12,fontWeight:600,color:T.rose}}>Delete Term</div><div style={{fontSize:11,color:T.textMuted,marginTop:1}}>Permanently remove this term</div></div>
                    </button>
                  </div>
                )}
              </div>
            </div>
            {/* Rejected banner */}
            {term.status==="Rejected"&&term.rejectionReason&&(<div style={{margin:"0 0 8px",padding:"8px 14px",background:"rgba(225,29,72,.06)",border:"1px solid rgba(225,29,72,.25)",borderRadius:8,fontSize:12.5,color:"#e11d48",lineHeight:1.5}}><strong>Rejected: </strong>{term.rejectionReason}</div>)}
            {/* Deprecation banner */}
            {term.status==="Deprecated"&&term.deprecationReason&&(<div style={{margin:"0 0 8px",padding:"8px 14px",background:"rgba(124,58,237,.06)",border:"1px solid rgba(124,58,237,.25)",borderRadius:8,fontSize:12.5,color:"#7c3aed",lineHeight:1.5}}><strong>Deprecated: </strong>{term.deprecationReason}</div>)}
            <div style={{display:"flex",gap:0,marginBottom:-1}}>
              {[{id:"overview",l:"Overview"},{id:"assets",l:`Linked Assets (${term.linkedAssets.length})`},{id:"activity",l:`Activity (${term.activity.length})`},{id:"auditlog",l:`Audit Log (${(term.auditLog||[]).length})`}].map(tab=>(
                <button key={tab.id} onClick={()=>setTermTab(tab.id)} style={{padding:"8px 18px",background:"transparent",border:"none",borderBottom:`2px solid ${termTab===tab.id?T.accent:"transparent"}`,color:termTab===tab.id?T.text:T.textMuted,fontSize:13,fontWeight:termTab===tab.id?600:400,cursor:"pointer",transition:"all .12s"}}>{tab.l}</button>
              ))}
            </div>
          </div>
          <div style={{flex:1,display:"flex",overflow:"hidden"}}>
          <div style={{flex:1,overflowY:"auto",padding:"28px"}}>
            {termTab==="overview"&&(
              <div style={{maxWidth:720}}>
                <SectionLabel label="Definition" action={<button onClick={()=>openModal("editTerm",{id:term.id,term:term.term,abbr:term.abbr,definition:term.definition||"",domain:term.domain,owner:term.owner,category:term.category,cert:term.cert})} style={{fontSize:12,color:T.accent,background:"none",border:"none",cursor:"pointer"}}>Edit</button>}/>
                {term.definition?<p style={{fontSize:14,color:T.text,lineHeight:1.8,margin:0}}>{term.definition}</p>:<div style={{padding:"16px",background:T.bgElevated,border:`1px dashed ${T.border}`,borderRadius:8,fontSize:13,color:T.textMuted,fontStyle:"italic",display:"flex",alignItems:"center",justifyContent:"space-between"}}><span>No definition yet.</span><button onClick={()=>openModal("editTerm",{id:term.id,term:term.term,abbr:term.abbr,definition:"",domain:term.domain,owner:term.owner,category:term.category,cert:term.cert})} style={{background:"none",border:"none",color:T.accent,cursor:"pointer",fontSize:12,fontWeight:600}}>+ Add</button></div>}
                <Divider/>
                <SectionLabel label="Related Terms" action={<button onClick={()=>setAddingRelated(p=>!p)} style={{fontSize:12,color:T.accent,background:"none",border:"none",cursor:"pointer",display:"flex",alignItems:"center",gap:4}}><IcPlus/> Link Term</button>}/>
                {addingRelated&&<div style={{marginBottom:12}}><GlSelect onChange={e=>{if(e.target.value)doAddRelated(term.id,e.target.value);}} defaultValue=""><option value="" disabled>Select a term to link…</option>{terms.filter(t=>t.id!==term.id&&!(term.relatedTerms||[]).includes(t.id)).map(t=>(<option key={t.id} value={t.id}>{t.term} ({glossaries.find(g=>g.id===t.glossary)?.name})</option>))}</GlSelect></div>}
                {(term.relatedTerms||[]).length===0&&!addingRelated&&<div style={{fontSize:13,color:T.textMuted,fontStyle:"italic"}}>No related terms linked.</div>}
                <div style={{display:"flex",flexWrap:"wrap",gap:8}}>
                  {(term.relatedTerms||[]).map(rid=>{
                    const rel=terms.find(t=>t.id===rid);if(!rel)return null;
                    const rcm=CERT_META[rel.cert]||CERT_META.Draft;
                    return (<div key={rid} style={{display:"inline-flex",alignItems:"center",gap:6,padding:"6px 10px",background:T.bgSurface,border:`1px solid ${T.border}`,borderRadius:8,transition:"border-color .1s"}} onMouseEnter={e=>e.currentTarget.style.borderColor=T.accent+"55"} onMouseLeave={e=>e.currentTarget.style.borderColor=T.border}>
                      <button onClick={()=>goToTerm(rid)} style={{display:"flex",alignItems:"center",gap:6,background:"none",border:"none",cursor:"pointer",padding:0}}><span style={{fontSize:12.5,fontWeight:600,color:T.accent}}>{rel.term}</span><span style={{fontSize:9.5,fontWeight:700,padding:"1px 5px",borderRadius:99,background:rcm.bg,color:rcm.color,border:`1px solid ${rcm.border}`}}>{rcm.icon}</span></button>
                      <button onClick={()=>patchTerm(term.id,{relatedTerms:(term.relatedTerms||[]).filter(id=>id!==rid)})} style={{background:"none",border:"none",color:T.textMuted,cursor:"pointer",padding:0,display:"flex",marginLeft:2}} onMouseEnter={e=>e.currentTarget.style.color=T.rose} onMouseLeave={e=>e.currentTarget.style.color=T.textMuted}><IcX s={9}/></button>
                    </div>);
                  })}
                </div>
                <Divider/>
                <SectionLabel label="References" action={<button onClick={()=>setAddingRef(p=>!p)} style={{fontSize:12,color:T.accent,background:"none",border:"none",cursor:"pointer",display:"flex",alignItems:"center",gap:4}}><IcPlus/> Add Link</button>}/>
                {addingRef&&(<div style={{padding:"12px",background:T.bgElevated,borderRadius:8,border:`1px solid ${T.border}`,marginBottom:12,display:"flex",flexDirection:"column",gap:8}}><GlInput placeholder="Label" value={refForm.label} onChange={e=>setRefForm(f=>({...f,label:e.target.value}))} style={{fontSize:12}}/><GlInput placeholder="URL https://…" value={refForm.url} onChange={e=>setRefForm(f=>({...f,url:e.target.value}))} style={{fontSize:12}}/><div style={{display:"flex",gap:6,justifyContent:"flex-end"}}><button onClick={()=>{setAddingRef(false);setRefForm({label:"",url:""}); }} style={{padding:"5px 12px",borderRadius:6,background:"transparent",border:`1px solid ${T.border}`,color:T.textSub,fontSize:11.5,cursor:"pointer"}}>Cancel</button><button onClick={()=>doAddRef(term.id)} disabled={!refForm.url.trim()} style={{padding:"5px 12px",borderRadius:6,background:refForm.url.trim()?T.accent:"rgba(238,36,36,.2)",border:"none",color:"#fff",fontSize:11.5,fontWeight:600,cursor:refForm.url.trim()?"pointer":"default"}}>Add</button></div></div>)}
                {(term.refs||[]).length===0&&!addingRef&&<div style={{fontSize:13,color:T.textMuted,fontStyle:"italic"}}>No external references yet.</div>}
                <div style={{display:"flex",flexDirection:"column",gap:8}}>{(term.refs||[]).map((ref,i)=>(<div key={i} style={{display:"flex",alignItems:"center",gap:10,padding:"10px 14px",background:T.bgSurface,border:`1px solid ${T.border}`,borderRadius:8,transition:"border-color .1s"}} onMouseEnter={e=>e.currentTarget.style.borderColor=T.accent+"55"} onMouseLeave={e=>e.currentTarget.style.borderColor=T.border}><span style={{color:T.accent,flexShrink:0}}><IcLink/></span><div style={{flex:1,minWidth:0}}><div style={{fontSize:13,fontWeight:600,color:T.text}}>{ref.label}</div><div style={{fontSize:11.5,color:T.textMuted,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{ref.url}</div></div><a href={ref.url} target="_blank" rel="noopener noreferrer" style={{fontSize:11,color:T.accent,background:T.accentDim,padding:"3px 9px",borderRadius:5,border:`1px solid ${T.accent}33`,textDecoration:"none",flexShrink:0}}>Open ↗</a><button onClick={()=>patchTerm(term.id,{refs:(term.refs||[]).filter((_,j)=>j!==i)})} style={{background:"none",border:"none",color:T.textMuted,cursor:"pointer",padding:2,display:"flex",borderRadius:4}} onMouseEnter={e=>e.currentTarget.style.color=T.rose} onMouseLeave={e=>e.currentTarget.style.color=T.textMuted}><IcX/></button></div>))}</div>
                <Divider/>
                <SectionLabel label="Synonyms & Alternate Names" action={null}/>
                <div style={{display:"flex",flexWrap:"wrap",gap:6,marginBottom:8}}>
                  {(term.synonyms||[]).map(s=><span key={s} style={{display:"inline-flex",alignItems:"center",gap:5,padding:"3px 9px",borderRadius:99,background:T.bgElevated,border:`1px solid ${T.border}`,fontSize:12,color:T.textSub}}>{s}<button onClick={()=>removeSynonym(term.id,s)} style={{background:"none",border:"none",cursor:"pointer",color:T.textMuted,padding:0,display:"flex",marginLeft:1}} onMouseEnter={e=>e.currentTarget.style.color=T.rose} onMouseLeave={e=>e.currentTarget.style.color=T.textMuted}><IcX s={8}/></button></span>)}
                </div>
                <div style={{display:"flex",gap:6}}>
                  <input value={synonymInput} onChange={e=>setSynonymInput(e.target.value)} onKeyDown={e=>{if(e.key==="Enter")addSynonym(term.id);}} placeholder="Add synonym and press Enter…" style={{flex:1,padding:"6px 10px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:7,color:T.text,fontSize:12.5,outline:"none"}} onFocus={e=>e.target.style.borderColor=T.accent} onBlur={e=>e.target.style.borderColor=T.border}/>
                  <button onClick={()=>addSynonym(term.id)} disabled={!synonymInput.trim()} style={{padding:"6px 14px",borderRadius:7,background:synonymInput.trim()?T.accent:"rgba(238,36,36,.2)",border:"none",color:"#fff",fontSize:12,fontWeight:600,cursor:synonymInput.trim()?"pointer":"default"}}>Add</button>
                </div>
                <Divider/>
                <SectionLabel label="Notes" action={<button style={{fontSize:12,color:T.accent,background:"none",border:"none",cursor:"pointer"}}>Edit</button>}/>
                {term.readme?<p style={{fontSize:13.5,color:T.textSub,lineHeight:1.75,margin:0}}>{term.readme}</p>:<div style={{fontSize:13,color:T.textMuted,fontStyle:"italic"}}>No notes yet.</div>}
              </div>
            )}
            {termTab==="assets"&&(<div><div style={{display:"flex",gap:6,marginBottom:16,flexWrap:"wrap"}}>{["All",...new Set(term.linkedAssets.map(a=>a.type))].map(type=>(<span key={type} style={{fontSize:12,padding:"4px 12px",borderRadius:99,background:T.bgElevated,border:`1px solid ${T.border}`,color:T.textSub,cursor:"pointer"}}>{type}{type==="All"?` (${term.linkedAssets.length})`:""}</span>))}</div>{term.linkedAssets.length===0?<div style={{padding:"40px 0",textAlign:"center",color:T.textMuted,fontSize:13}}>No linked assets yet.</div>:(<div style={{background:T.bgSurface,border:`1px solid ${T.border}`,borderRadius:10,overflow:"hidden"}}>{term.linkedAssets.map((a,i)=>(<div key={i} style={{display:"flex",alignItems:"center",gap:12,padding:"12px 16px",borderBottom:i<term.linkedAssets.length-1?`1px solid ${T.border}`:"none",transition:"background .1s"}} onMouseEnter={e=>e.currentTarget.style.background=T.bgHover} onMouseLeave={e=>e.currentTarget.style.background="transparent"}><div style={{width:32,height:32,borderRadius:8,background:T.bgElevated,border:`1px solid ${T.border}`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:14,color:T.accent,flexShrink:0}}>{{"Table":"⊞","Dashboard":"⊟","Pipeline":"⇢","ML Model":"◈"}[a.type]||"○"}</div><div style={{flex:1}}><div style={{fontSize:13.5,fontWeight:600,color:T.text,fontFamily:"'Geist Mono',monospace"}}>{a.name}</div><div style={{fontSize:11.5,color:T.textMuted,marginTop:1}}>{a.type}</div></div><svg width="10" height="10" viewBox="0 0 10 10" fill="none"><path d="M3 2l4 3-4 3" stroke={T.textMuted} strokeWidth="1.3" strokeLinecap="round"/></svg></div>))}</div>)}<button onClick={()=>onToast("Open catalog to link assets","success")} style={{marginTop:12,display:"flex",alignItems:"center",gap:6,padding:"7px 14px",borderRadius:8,background:"transparent",border:`1px solid ${T.border}`,color:T.textSub,fontSize:12,cursor:"pointer"}} onMouseEnter={e=>{e.currentTarget.style.borderColor=T.accent;e.currentTarget.style.color=T.accent;}} onMouseLeave={e=>{e.currentTarget.style.borderColor=T.border;e.currentTarget.style.color=T.textSub;}}><IcPlus/> Link Asset</button></div>)}
            {termTab==="activity"&&(<div style={{maxWidth:680}}><div style={{background:T.bgSurface,border:`1px solid ${T.border}`,borderRadius:10,padding:"14px",marginBottom:16}}><div style={{fontSize:12.5,fontWeight:600,color:T.textSub,marginBottom:8}}>Add a comment</div><textarea value={commentText} onChange={e=>setCommentText(e.target.value)} placeholder="Use @mention to tag teammates…" rows={3} style={{width:"100%",padding:"8px 10px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:7,color:T.text,fontSize:12.5,resize:"none",outline:"none",fontFamily:"inherit",lineHeight:1.55,boxSizing:"border-box"}} onFocus={e=>e.target.style.borderColor=T.accent} onBlur={e=>e.target.style.borderColor=T.border}/><div style={{display:"flex",justifyContent:"flex-end",marginTop:8}}><button onClick={()=>addComment(term.id)} disabled={!commentText.trim()} style={{padding:"6px 16px",borderRadius:7,background:commentText.trim()?T.accent:"rgba(238,36,36,.2)",border:"none",color:"#fff",fontSize:12,fontWeight:600,cursor:commentText.trim()?"pointer":"default"}}>Post</button></div></div><div style={{display:"flex",flexDirection:"column",gap:8}}>{term.activity.map((act,i)=>(<div key={i} style={{display:"flex",gap:12,padding:"12px 14px",background:T.bgSurface,border:`1px solid ${T.border}`,borderRadius:9}}><div style={{width:30,height:30,borderRadius:8,background:T.accentDim,border:`1px solid ${T.accent}33`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:9.5,fontWeight:700,color:T.accent,flexShrink:0}}>{act.avatar}</div><div style={{flex:1}}><div style={{display:"flex",alignItems:"baseline",gap:6}}><span style={{fontSize:13,fontWeight:600,color:T.text}}>{act.user}</span><span style={{fontSize:11,color:T.textMuted}}>{act.time}</span></div><div style={{fontSize:13,color:act.isComment?T.text:T.textSub,marginTop:3,lineHeight:1.55}}>{act.action}</div></div></div>))}{term.activity.length===0&&<div style={{textAlign:"center",padding:"32px 0",color:T.textMuted,fontSize:13}}>No activity yet.</div>}</div></div>)}
            {termTab==="auditlog"&&(
              <div style={{maxWidth:900}}>
                <AuditLogTable entries={glossAuditToEntries(term.auditLog)}/>
              </div>
            )}
          </div>
        {/* RIGHT metadata panel — Overview tab only */}
        {termTab==="overview"&&(()=>{
          const stewards = stewardsG;
          const tagColor = gTagColor;
          const SideLabel = ({ch,onEdit})=>(
            <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:9}}>
              <div style={{fontSize:10.5,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.08em"}}>{ch}</div>
              {onEdit&&<button onClick={onEdit} style={{background:"none",border:"none",cursor:"pointer",color:T.textMuted,padding:"2px 3px",display:"flex",borderRadius:4,transition:"all .12s"}}
                onMouseEnter={e=>{e.currentTarget.style.color=T.accent;e.currentTarget.style.background=T.accentDim;}}
                onMouseLeave={e=>{e.currentTarget.style.color=T.textMuted;e.currentTarget.style.background="none";}}>
                <svg width="11" height="11" viewBox="0 0 14 14" fill="none"><path d="M9.5 2.5l2 2L4 12H2v-2L9.5 2.5z" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round" strokeLinejoin="round"/></svg>
              </button>}
            </div>
          );
          return (
          <div style={{width:272,flexShrink:0,borderLeft:`1px solid ${T.border}`,background:T.bgSurface,overflowY:"auto"}}>

            {/* CERTIFICATE */}
            <div style={{padding:"16px",borderBottom:`1px solid ${T.border}`}}>
              <SideLabel ch="Status" onEdit={()=>{setGlossEditModal("cert");setGlossModalSearch("");}}/>
              <div style={{display:"inline-flex",alignItems:"center",gap:6,padding:"4px 12px 4px 9px",borderRadius:5,background:cm.bg,borderTop:`1px solid ${cm.border}`,borderRight:`1px solid ${cm.border}`,borderBottom:`1px solid ${cm.border}`,borderLeft:`3px solid ${cm.color}`}}>
                <span style={{fontSize:13}}>{cm.icon}</span>
                <span style={{fontSize:12,color:cm.color,fontWeight:600}}>{term.cert||"Draft"}</span>
              </div>
            </div>

            {/* DOMAIN */}
            <div style={{padding:"16px",borderBottom:`1px solid ${T.border}`}}>
              <SideLabel ch="Domain" onEdit={()=>{setGlossEditModal("domain");setGlossModalSearch("");}}/>
              {term.domain?(
                <div style={{display:"inline-flex",alignItems:"center",padding:"4px 12px 4px 9px",borderRadius:5,background:`${T.accent}0f`,borderTop:`1px solid ${T.accent}20`,borderRight:`1px solid ${T.accent}20`,borderBottom:`1px solid ${T.accent}20`,borderLeft:`3px solid ${T.accent}`}}>
                  <span style={{fontSize:12,color:T.accent,fontWeight:600}}>{term.domain}</span>
                </div>
              ):(
                <span style={{fontSize:12,color:T.textMuted,fontStyle:"italic"}}>No domain set</span>
              )}
            </div>

            {/* OWNERS */}
            <div style={{padding:"16px",borderBottom:`1px solid ${T.border}`}}>
              <SideLabel ch="Owners" onEdit={()=>{setGlossEditModal("owners");setGlossModalSearch("");}}/>
              <div style={{display:"flex",flexWrap:"wrap",gap:5}}>
                {owners.length===0&&<span style={{fontSize:12,color:T.textMuted,fontStyle:"italic"}}>No owners set</span>}
                {(showAllGlossOwners?owners:owners.slice(0,3)).map((o,i)=>(
                  <div key={i} style={{display:"inline-flex",alignItems:"center",gap:5,padding:"3px 10px 3px 6px",borderRadius:5,background:`${T.accent}0f`,borderTop:`1px solid ${T.accent}20`,borderRight:`1px solid ${T.accent}20`,borderBottom:`1px solid ${T.accent}20`,borderLeft:`3px solid ${T.accent}`}}>
                    <div style={{width:18,height:18,borderRadius:3,background:T.accentDim,display:"flex",alignItems:"center",justifyContent:"center",fontSize:7,fontWeight:700,color:T.accent,flexShrink:0}}>{ava(o)}</div>
                    <span style={{fontSize:12,color:T.accent,fontWeight:500}}>{o}</span>
                  </div>
                ))}
                {owners.length>3&&!showAllGlossOwners&&<span onClick={()=>setShowAllGlossOwners(true)} style={{display:"inline-flex",alignItems:"center",fontSize:11.5,padding:"3px 10px",borderRadius:5,background:T.bgElevated,border:`1px solid ${T.border}`,color:T.textMuted,cursor:"pointer",fontWeight:600}}>+{owners.length-3} more</span>}
                {owners.length>3&&showAllGlossOwners&&<span onClick={()=>setShowAllGlossOwners(false)} style={{display:"inline-flex",alignItems:"center",fontSize:11.5,padding:"3px 10px",borderRadius:5,background:T.bgElevated,border:`1px solid ${T.border}`,color:T.textMuted,cursor:"pointer",fontWeight:600}}>− less</span>}
              </div>
            </div>

            {/* STEWARDS */}
            <div style={{padding:"16px",borderBottom:`1px solid ${T.border}`}}>
              <SideLabel ch="Stewards" onEdit={()=>{setGlossEditModal("stewards");setGlossModalSearch("");}}/>
              <div style={{display:"flex",flexWrap:"wrap",gap:5}}>
                {stewards.length===0&&<span style={{fontSize:12,color:T.textMuted,fontStyle:"italic"}}>No stewards set</span>}
                {(showAllGlossStewards?stewards:stewards.slice(0,3)).map((s,i)=>(
                  <div key={i} style={{display:"inline-flex",alignItems:"center",gap:5,padding:"3px 10px 3px 6px",borderRadius:5,background:"rgba(217,119,6,.08)",borderTop:"1px solid rgba(217,119,6,.2)",borderRight:"1px solid rgba(217,119,6,.2)",borderBottom:"1px solid rgba(217,119,6,.2)",borderLeft:"3px solid #d97706"}}>
                    <div style={{width:18,height:18,borderRadius:"50%",background:"rgba(217,119,6,.15)",display:"flex",alignItems:"center",justifyContent:"center",fontSize:7,fontWeight:700,color:"#d97706",flexShrink:0}}>{ava(s)}</div>
                    <span style={{fontSize:12,color:"#d97706",fontWeight:500}}>{s}</span>
                  </div>
                ))}
                {stewards.length>3&&!showAllGlossStewards&&<span onClick={()=>setShowAllGlossStewards(true)} style={{display:"inline-flex",alignItems:"center",fontSize:11.5,padding:"3px 10px",borderRadius:5,background:T.bgElevated,border:`1px solid ${T.border}`,color:T.textMuted,cursor:"pointer",fontWeight:600}}>+{stewards.length-3} more</span>}
                {stewards.length>3&&showAllGlossStewards&&<span onClick={()=>setShowAllGlossStewards(false)} style={{display:"inline-flex",alignItems:"center",fontSize:11.5,padding:"3px 10px",borderRadius:5,background:T.bgElevated,border:`1px solid ${T.border}`,color:T.textMuted,cursor:"pointer",fontWeight:600}}>− less</span>}
              </div>
            </div>

            {/* TAGS */}
            <div style={{padding:"16px",borderBottom:`1px solid ${T.border}`}}>
              <SideLabel ch="Tags" onEdit={()=>{setGlossEditModal("tags");setGlossModalSearch("");}}/>
              <div style={{display:"flex",flexWrap:"wrap",gap:5}}>
                {(term.tags||[]).length>0?(term.tags||[]).map(tag=>{
                  const tc=tagColor(tag);
                  return (
                    <span key={tag} style={{display:"inline-flex",alignItems:"center",fontSize:11.5,padding:"4px 10px 4px 9px",borderRadius:5,background:tc.bg,borderTop:`1px solid ${tc.border}`,borderRight:`1px solid ${tc.border}`,borderBottom:`1px solid ${tc.border}`,borderLeft:`3px solid ${tc.color}`,color:tc.color,fontWeight:600}}>{tag}</span>
                  );
                }):<span style={{fontSize:12,color:T.textMuted,fontStyle:"italic"}}>No tags set</span>}
              </div>
            </div>

            {/* GLOSSARY */}
            <div style={{padding:"16px",borderBottom:`1px solid ${T.border}`}}>
              <SideLabel ch="Glossary"/>
              <div style={{display:"inline-flex",alignItems:"center",gap:7,padding:"4px 12px 4px 9px",borderRadius:5,background:`${T.accent}0f`,borderTop:`1px solid ${T.accent}20`,borderRight:`1px solid ${T.accent}20`,borderBottom:`1px solid ${T.accent}20`,borderLeft:`3px solid ${T.accent}`}}>
                <span style={{fontSize:13}}>{termGlossary?.icon}</span>
                <span style={{fontSize:12,fontWeight:600,color:T.accent}}>{termGlossary?.name||term.domain}</span>
              </div>
            </div>

            {/* LINKED ASSETS */}
            <div style={{padding:"16px",borderBottom:`1px solid ${T.border}`}}>
              <SideLabel ch="Linked Assets"/>
              <button onClick={()=>setTermTab("assets")} style={{fontSize:13,fontWeight:700,color:T.accent,background:"none",border:"none",cursor:"pointer",padding:0}}>
                {term.linked} assets →
              </button>
            </div>

            {/* ACTIONS */}
            <div style={{padding:"16px"}}>
              <SideLabel ch="Actions"/>
              {[{l:"Request Changes",action:()=>onToast("Review request sent","success")},{l:"Copy Link",action:()=>onToast("Link copied","success")},{l:"View in Catalog",action:()=>onToast("Opening catalog…","success")}].map((a,i)=>(
                <button key={i} onClick={a.action} style={{width:"100%",display:"flex",alignItems:"center",justifyContent:"space-between",padding:"8px 0",background:"none",border:"none",borderBottom:i<2?`1px solid ${T.border}`:"none",color:T.textSub,fontSize:12.5,cursor:"pointer"}}
                  onMouseEnter={e=>e.currentTarget.style.color=T.accent} onMouseLeave={e=>e.currentTarget.style.color=T.textSub}>
                  {a.l}<svg width="9" height="9" viewBox="0 0 10 10" fill="none"><path d="M3 2l4 3-4 3" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round"/></svg>
                </button>
              ))}
            </div>

          </div>
          );
        })()}
          </div>
        </div>
      </div>
      {/* GLOSS EDIT MODAL */}
      {glossEditModal&&(
        <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,.45)",display:"flex",alignItems:"center",justifyContent:"center",zIndex:1200,backdropFilter:"blur(3px)"}} onClick={()=>setGlossEditModal(null)}>
          <div className="scaleIn" style={{background:T.bgSurface,border:`1px solid ${T.border}`,borderRadius:14,width:360,maxHeight:"80vh",overflow:"auto",boxShadow:"0 24px 60px rgba(0,0,0,.35)"}} onClick={e=>e.stopPropagation()}>
            <div style={{padding:"14px 18px",borderBottom:`1px solid ${T.border}`,display:"flex",alignItems:"center",justifyContent:"space-between"}}>
              <div style={{fontSize:13,fontWeight:700,color:T.text}}>Edit {glossEditModal==="cert"?"Status":glossEditModal==="domain"?"Domain":glossEditModal==="owners"?"Owners":glossEditModal==="stewards"?"Stewards":"Tags"}</div>
              <button onClick={()=>setGlossEditModal(null)} style={{background:T.bgHover,border:`1px solid ${T.border}`,borderRadius:6,color:T.textMuted,cursor:"pointer",padding:"3px 6px",display:"flex"}}><IcX/></button>
            </div>
            {(glossEditModal==="owners"||glossEditModal==="stewards"||glossEditModal==="tags")&&(
              <div style={{padding:"10px 14px",borderBottom:`1px solid ${T.border}`}}>
                <input autoFocus placeholder={`Search ${glossEditModal}…`} value={glossModalSearch} onChange={e=>setGlossModalSearch(e.target.value)}
                  style={{width:"100%",padding:"7px 11px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:8,color:T.text,fontSize:12.5,outline:"none",boxSizing:"border-box"}}
                  onFocus={e=>e.target.style.borderColor=T.accent} onBlur={e=>e.target.style.borderColor=T.border}/>
              </div>
            )}
            <div style={{padding:"6px 0"}}>
              {glossEditModal==="cert"&&Object.keys(CERT_META).map(c=>{
                const m=CERT_META[c];
                const isCurrent=c===(term.cert||"Draft");
                return (
                  <button key={c} onClick={()=>{if(!isCurrent){transitionTerm(term.id,c);setGlossEditModal(null);}}}
                    style={{width:"100%",display:"flex",alignItems:"center",gap:12,padding:"11px 16px",background:isCurrent?T.accentDim:"transparent",border:"none",cursor:isCurrent?"default":"pointer",transition:"background .1s"}}
                    onMouseEnter={e=>{if(!isCurrent)e.currentTarget.style.background=T.bgHover;}} onMouseLeave={e=>{if(!isCurrent)e.currentTarget.style.background="transparent";}}>
                    <span style={{fontSize:16,flexShrink:0}}>{m.icon}</span>
                    <span style={{flex:1,fontSize:13,fontWeight:600,color:m.color}}>{c}</span>
                    {isCurrent&&<span style={{fontSize:10,padding:"1px 6px",borderRadius:4,background:m.bg,color:m.color,border:`1px solid ${m.border}`,fontWeight:700}}>current</span>}
                  </button>
                );
              })}
              {glossEditModal==="domain"&&DOMAINS.filter(d=>!glossModalSearch||d.toLowerCase().includes(glossModalSearch.toLowerCase())).map(d=>(
                <button key={d} onClick={()=>{patchTerm(term.id,{domain:d});setGlossEditModal(null);}}
                  style={{width:"100%",display:"flex",alignItems:"center",justifyContent:"space-between",padding:"10px 16px",background:term.domain===d?T.accentDim:"transparent",border:"none",cursor:"pointer"}}
                  onMouseEnter={e=>{if(term.domain!==d)e.currentTarget.style.background=T.bgHover;}} onMouseLeave={e=>{if(term.domain!==d)e.currentTarget.style.background="transparent";}}>
                  <span style={{fontSize:13,fontWeight:600,color:term.domain===d?T.accent:T.text}}>{d}</span>
                  {term.domain===d&&<svg width="13" height="13" viewBox="0 0 14 14" fill="none"><path d="M2.5 7.5l3 3 6-6" stroke={T.accent} strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"/></svg>}
                </button>
              ))}
              {(glossEditModal==="owners"||glossEditModal==="stewards")&&(()=>{
                const isSt = glossEditModal==="stewards";
                const list = isSt ? stewardsG : owners;
                return USERS.filter(u=>!glossModalSearch||u.toLowerCase().includes(glossModalSearch.toLowerCase())).map(u=>{
                  const sel=list.includes(u);
                  return (
                    <button key={u} onClick={()=>{
                      if(isSt){const ns=sel?list.filter(x=>x!==u):[...list,u];patchTerm(term.id,{stewards:ns,steward:ns[0]||""});}
                      else{const no=sel?list.filter(x=>x!==u):[...list,u];patchTerm(term.id,{owners:no,owner:no[0]||""});}
                    }}
                      style={{width:"100%",display:"flex",alignItems:"center",gap:10,padding:"9px 14px",background:sel?T.bgElevated:"transparent",border:"none",cursor:"pointer",transition:"background .1s"}}
                      onMouseEnter={e=>{if(!sel)e.currentTarget.style.background=T.bgHover;}} onMouseLeave={e=>{if(!sel)e.currentTarget.style.background="transparent";}}>
                      <div style={{width:26,height:26,borderRadius:isSt?"50%":4,background:isSt?"rgba(217,119,6,.15)":T.accentDim,display:"flex",alignItems:"center",justifyContent:"center",fontSize:9,fontWeight:700,color:isSt?"#d97706":T.accent,flexShrink:0}}>{ava(u)}</div>
                      <span style={{flex:1,fontSize:13,color:T.text}}>{u}</span>
                      {sel&&<svg width="13" height="13" viewBox="0 0 14 14" fill="none"><path d="M2.5 7.5l3 3 6-6" stroke={isSt?"#d97706":T.accent} strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"/></svg>}
                    </button>
                  );
                });
              })()}
              {glossEditModal==="tags"&&(()=>{
                const filtered = ALL_TAGS_GLOSS.filter(s=>!glossModalSearch||s.toLowerCase().includes(glossModalSearch.toLowerCase()));
                return filtered.map(s=>{
                  const sel=(term.tags||[]).includes(s);
                  const c=gTagColor(s);
                  return (
                    <button key={s} onClick={()=>patchTerm(term.id,{tags:sel?(term.tags||[]).filter(x=>x!==s):[...(term.tags||[]),s]})}
                      style={{width:"100%",display:"flex",alignItems:"center",gap:10,padding:"8px 14px",background:"transparent",border:"none",cursor:"pointer",transition:"background .1s"}}
                      onMouseEnter={e=>e.currentTarget.style.background=T.bgHover} onMouseLeave={e=>e.currentTarget.style.background="transparent"}>
                      <span style={{display:"inline-flex",alignItems:"center",fontSize:11.5,padding:"3px 9px 3px 8px",borderRadius:5,background:sel?c.bg:T.bgElevated,borderTop:`1px solid ${sel?c.border:T.border}`,borderRight:`1px solid ${sel?c.border:T.border}`,borderBottom:`1px solid ${sel?c.border:T.border}`,borderLeft:`3px solid ${sel?c.color:T.borderLight}`,color:sel?c.color:T.textSub,fontWeight:sel?600:400}}>{s}</span>
                      {sel&&<svg width="13" height="13" viewBox="0 0 14 14" fill="none" style={{marginLeft:"auto"}}><path d="M2.5 7.5l3 3 6-6" stroke={c.color} strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"/></svg>}
                    </button>
                  );
                });
              })()}
            </div>
          </div>
        </div>
      )}
      </>
    );
  };

    // ─── MODALS ───
  const renderModal = () => {
    if(!modal) return null;
    const {type,data} = modal;
    const ICONS = ["📘","🛒","💰","📱","📣","🔬","🏭","📊","🌐","⚙️","🔑","📋"];

    if(type==="deleteGlossary"||type==="deleteCategory"||type==="deleteTerm"){
      const label = type==="deleteGlossary"?`glossary "${data.name}"`:type==="deleteCategory"?`category "${data.name}"`:type==="deleteTerm"?`term "${data.term||data.name}"`:"item";
      const extra = type==="deleteGlossary"?" All terms and categories will be removed.":type==="deleteCategory"?" Terms will become uncategorized.":"";
      const onConfirm = type==="deleteGlossary"?()=>doDeleteGlossary(data.id):type==="deleteCategory"?()=>doDeleteCategory(data.id):()=>doDeleteTerm(data.id);
      return (
        <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,.5)",display:"flex",alignItems:"center",justifyContent:"center",zIndex:900,backdropFilter:"blur(4px)"}}>
          <div className="scaleIn" style={{background:T.bgSurface,border:`1px solid ${T.border}`,borderRadius:12,width:380,padding:"24px",boxShadow:"0 20px 50px rgba(0,0,0,.3)"}}>
            <div style={{fontSize:15,fontWeight:700,color:T.text,marginBottom:8}}>Delete {type.replace("delete","")}</div>
            <p style={{fontSize:13,color:T.textSub,lineHeight:1.6,margin:"0 0 20px"}}>Are you sure you want to delete the {label}?{extra} This cannot be undone.</p>
            <div style={{display:"flex",gap:8,justifyContent:"flex-end"}}>
              <button onClick={closeModal} style={{padding:"8px 16px",borderRadius:8,background:"transparent",border:`1px solid ${T.border}`,color:T.textSub,fontSize:12.5,cursor:"pointer"}}>Cancel</button>
              <button onClick={onConfirm} style={{padding:"8px 16px",borderRadius:8,background:T.rose,border:"none",color:"#fff",fontSize:12.5,fontWeight:700,cursor:"pointer"}}>Delete</button>
            </div>
          </div>
        </div>
      );
    }
    if(type==="newGlossary"||type==="editGlossary"){
      const isEdit = type==="editGlossary";
      return (
        <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,.5)",display:"flex",alignItems:"center",justifyContent:"center",zIndex:900,backdropFilter:"blur(4px)"}}>
          <div className="scaleIn" style={{background:T.bgSurface,border:`1px solid ${T.border}`,borderRadius:14,width:460,maxHeight:"85vh",overflow:"auto",boxShadow:"0 24px 60px rgba(0,0,0,.35)"}}>
            <div style={{padding:"18px 22px",borderBottom:`1px solid ${T.border}`,display:"flex",alignItems:"center",justifyContent:"space-between"}}>
              <div style={{fontSize:15,fontWeight:700,color:T.text}}>{isEdit?"Edit Glossary":"New Glossary"}</div>
              <button onClick={closeModal} style={{background:T.bgHover,border:`1px solid ${T.border}`,borderRadius:6,color:T.textMuted,cursor:"pointer",padding:"3px 6px",display:"flex"}}><IcX/></button>
            </div>
            <div style={{padding:"18px 22px",display:"flex",flexDirection:"column",gap:14}}>
              <div><GlLabel req>Name</GlLabel><GlInput value={form.name||""} onChange={e=>setForm(f=>({...f,name:e.target.value}))} placeholder="e.g. Commerce Glossary"/></div>
              <div>
                <GlLabel>Icon</GlLabel>
                <div style={{display:"flex",flexWrap:"wrap",gap:6,marginTop:2}}>
                  {ICONS.map(ic=>(
                    <button key={ic} onClick={()=>setForm(f=>({...f,icon:ic}))} style={{width:34,height:34,borderRadius:8,fontSize:16,border:`2px solid ${(form.icon||"📘")===ic?T.accent:T.border}`,background:(form.icon||"📘")===ic?T.accentDim:T.bgElevated,cursor:"pointer"}}>{ic}</button>
                  ))}
                </div>
              </div>
              <div><GlLabel>Description</GlLabel><GlTA value={form.desc||""} onChange={e=>setForm(f=>({...f,desc:e.target.value}))} placeholder="Brief description of this glossary's scope…" rows={3}/></div>
              <div style={{display:"flex",gap:8,justifyContent:"flex-end",paddingTop:4}}>
                <button onClick={closeModal} style={{padding:"8px 16px",borderRadius:8,background:"transparent",border:`1px solid ${T.border}`,color:T.textSub,fontSize:12,cursor:"pointer"}}>Cancel</button>
                <button onClick={isEdit?doUpdateGlossary:doCreateGlossary} disabled={!form.name?.trim()} style={{padding:"8px 20px",borderRadius:8,background:form.name?.trim()?T.accent:"rgba(238,36,36,.25)",border:"none",color:"#fff",fontSize:12,fontWeight:700,cursor:form.name?.trim()?"pointer":"default"}}>{isEdit?"Save Changes":"Create Glossary"}</button>
              </div>
            </div>
          </div>
        </div>
      );
    }
    if(type==="newCategory"||type==="editCategory"){
      const isEdit = type==="editCategory";
      return (
        <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,.5)",display:"flex",alignItems:"center",justifyContent:"center",zIndex:900,backdropFilter:"blur(4px)"}}>
          <div className="scaleIn" style={{background:T.bgSurface,border:`1px solid ${T.border}`,borderRadius:12,width:400,boxShadow:"0 24px 60px rgba(0,0,0,.35)"}}>
            <div style={{padding:"16px 20px",borderBottom:`1px solid ${T.border}`,display:"flex",alignItems:"center",justifyContent:"space-between"}}>
              <div>
                <div style={{fontSize:14,fontWeight:700,color:T.text}}>{isEdit?"Edit Category":"New Category"}</div>
                {!isEdit&&glossary&&<div style={{fontSize:11,color:T.textMuted,marginTop:2}}>in {glossary.name}</div>}
              </div>
              <button onClick={closeModal} style={{background:T.bgHover,border:`1px solid ${T.border}`,borderRadius:6,color:T.textMuted,cursor:"pointer",padding:"3px 6px",display:"flex"}}><IcX/></button>
            </div>
            <div style={{padding:"16px 20px",display:"flex",flexDirection:"column",gap:14}}>
              <div><GlLabel req>Category Name</GlLabel><GlInput value={form.name||""} onChange={e=>setForm(f=>({...f,name:e.target.value}))} placeholder="e.g. Revenue Metrics"/></div>
              <div style={{display:"flex",gap:8,justifyContent:"flex-end"}}>
                <button onClick={closeModal} style={{padding:"7px 14px",borderRadius:8,background:"transparent",border:`1px solid ${T.border}`,color:T.textSub,fontSize:12,cursor:"pointer"}}>Cancel</button>
                <button onClick={isEdit?doUpdateCategory:doCreateCategory} disabled={!form.name?.trim()} style={{padding:"7px 18px",borderRadius:8,background:form.name?.trim()?T.accent:"rgba(238,36,36,.25)",border:"none",color:"#fff",fontSize:12,fontWeight:700,cursor:form.name?.trim()?"pointer":"default"}}>{isEdit?"Save":"Create"}</button>
              </div>
            </div>
          </div>
        </div>
      );
    }
    if(type==="newTerm"||type==="editTerm"){
      const isEdit = type==="editTerm";
      return (
        <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,.5)",display:"flex",alignItems:"center",justifyContent:"center",zIndex:900,backdropFilter:"blur(4px)"}}>
          <div className="scaleIn" style={{background:T.bgSurface,border:`1px solid ${T.border}`,borderRadius:14,width:540,maxHeight:"88vh",overflow:"auto",boxShadow:"0 24px 60px rgba(0,0,0,.35)"}}>
            <div style={{padding:"18px 22px",borderBottom:`1px solid ${T.border}`,display:"flex",alignItems:"center",justifyContent:"space-between"}}>
              <div>
                <div style={{fontSize:15,fontWeight:700,color:T.text}}>{isEdit?"Edit Term":"New Term"}</div>
                {!isEdit&&glossary&&<div style={{fontSize:11,color:T.textMuted,marginTop:2}}>{glossary.name}</div>}
              </div>
              <button onClick={closeModal} style={{background:T.bgHover,border:`1px solid ${T.border}`,borderRadius:6,color:T.textMuted,cursor:"pointer",padding:"3px 6px",display:"flex"}}><IcX/></button>
            </div>
            <div style={{padding:"18px 22px",display:"flex",flexDirection:"column",gap:14}}>
              <div style={{display:"grid",gridTemplateColumns:"1fr 100px",gap:10}}>
                <div><GlLabel req>Term Name</GlLabel><GlInput value={form.term||""} onChange={e=>setForm(f=>({...f,term:e.target.value}))} placeholder="e.g. Gross Margin"/></div>
                <div><GlLabel>Abbreviation</GlLabel><GlInput value={form.abbr||""} onChange={e=>setForm(f=>({...f,abbr:e.target.value}))} placeholder="e.g. GM" maxLength={8}/></div>
              </div>
              <div>
                <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:5}}>
                  <GlLabel>Definition</GlLabel>
                  <button onClick={()=>aiSuggestDefinition(form.term)} disabled={!form.term?.trim()||aiLoading}
                    style={{display:"flex",alignItems:"center",gap:5,padding:"3px 10px",borderRadius:6,background:form.term?.trim()&&!aiLoading?T.accentDim:"transparent",border:`1px solid ${form.term?.trim()&&!aiLoading?T.accent:T.border}`,color:form.term?.trim()&&!aiLoading?T.accent:T.textMuted,fontSize:11,fontWeight:600,cursor:form.term?.trim()&&!aiLoading?"pointer":"default",transition:"all .12s"}}>
                    <svg width="10" height="10" viewBox="0 0 12 12" fill="none"><path d="M6 1l1.5 3.5L11 6l-3.5 1.5L6 11 4.5 7.5 1 6l3.5-1.5L6 1z" stroke="currentColor" strokeWidth="1.2" strokeLinejoin="round"/></svg>
                    {aiLoading?"Generating…":"AI Suggest"}
                  </button>
                </div>
                <GlTA value={form.definition||""} onChange={e=>setForm(f=>({...f,definition:e.target.value}))} placeholder="Clear, precise business definition…" rows={4}/>
              </div>
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12}}>
                <div>
                  <GlLabel>Category</GlLabel>
                  <GlSelect value={form.category||""} onChange={e=>setForm(f=>({...f,category:e.target.value}))}>
                    <option value="">Uncategorized</option>
                    {glossary?.categories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}
                  </GlSelect>
                </div>
                <div><GlLabel>Glossary</GlLabel><GlSelect value={form.glossary||selG||"g1"} onChange={e=>setForm(f=>({...f,glossary:e.target.value}))}>{glossaries.map(g=><option key={g.id} value={g.id}>{g.name}</option>)}</GlSelect></div>
                <div><GlLabel>Owner</GlLabel><GlSelect value={form.owner||"maya.chen"} onChange={e=>setForm(f=>({...f,owner:e.target.value}))}>{USERS.map(u=><option key={u} value={u}>{u}</option>)}</GlSelect></div>
                <div><GlLabel>Status</GlLabel><GlSelect value={form.cert||"Draft"} onChange={e=>setForm(f=>({...f,cert:e.target.value}))}>{["Draft","In Review"].map(c=><option key={c}>{c}</option>)}</GlSelect></div>
              </div>
              <div style={{display:"flex",gap:8,justifyContent:"flex-end",paddingTop:4}}>
                <button onClick={closeModal} style={{padding:"8px 16px",borderRadius:8,background:"transparent",border:`1px solid ${T.border}`,color:T.textSub,fontSize:12,cursor:"pointer"}}>Cancel</button>
                <button onClick={isEdit?doUpdateTerm:doCreateTerm} disabled={!form.term?.trim()} style={{padding:"8px 20px",borderRadius:8,background:form.term?.trim()?T.accent:"rgba(238,36,36,.25)",border:"none",color:"#fff",fontSize:12,fontWeight:700,cursor:form.term?.trim()?"pointer":"default"}}>{isEdit?"Save Changes":"Create Term"}</button>
              </div>
            </div>
          </div>
        </div>
      );
    }
    return null;
  };

  // ─── TRANSITION CONFIRM MODAL ───
  const renderTransitionModal = () => {
    if(!transitionModal) return null;
    const {id,to,label} = transitionModal;
    const t = terms.find(x=>x.id===id);
    if(!t) return null;
    const isDeprecate = to==="Deprecated";
    const isReject    = to==="Rejected";
    const needsReason = isDeprecate || isReject;
    const reasonValue = isDeprecate ? deprecateReason : rejectReason;
    const reasonSetter = isDeprecate ? setDeprecateReason : setRejectReason;
    const btnColor = isReject ? "#e11d48" : T.rose;
    return (
      <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,.55)",display:"flex",alignItems:"center",justifyContent:"center",zIndex:1000,backdropFilter:"blur(4px)"}}>
        <div className="scaleIn" style={{background:T.bgSurface,border:`1px solid ${T.border}`,borderRadius:14,width:440,boxShadow:"0 24px 60px rgba(0,0,0,.3)"}}>
          <div style={{padding:"18px 22px",borderBottom:`1px solid ${T.border}`,display:"flex",alignItems:"center",justifyContent:"space-between"}}>
            <div style={{fontSize:14,fontWeight:700,color:T.text}}>{label}: {t.term}</div>
            <button onClick={()=>setTransitionModal(null)} style={{background:T.bgHover,border:`1px solid ${T.border}`,borderRadius:6,color:T.textMuted,cursor:"pointer",padding:"3px 6px",display:"flex"}}><IcX/></button>
          </div>
          <div style={{padding:"18px 22px",display:"flex",flexDirection:"column",gap:12}}>
            {isDeprecate&&(<>
              <div style={{fontSize:13,color:T.textSub}}>Provide a reason for deprecation. This will be shown to anyone who references this term.</div>
              <div><GlLabel req>Deprecation Reason</GlLabel><GlTA value={deprecateReason} onChange={e=>setDeprecateReason(e.target.value)} placeholder="e.g. Superseded by Gross Revenue Retention per CFO directive Q1 2026" rows={3}/></div>
            </>)}
            {isReject&&(<>
              <div style={{fontSize:13,color:T.textSub}}>Provide a reason for rejection. The submitter will be notified and the term will be marked <strong>Rejected</strong>.</div>
              <div><GlLabel req>Rejection Reason</GlLabel><GlTA value={rejectReason} onChange={e=>setRejectReason(e.target.value)} placeholder="e.g. Definition conflicts with existing approved term CLV. Please resubmit with a narrower scope." rows={3}/></div>
            </>)}
            {!needsReason&&<div style={{fontSize:13,color:T.textSub}}>Are you sure you want to move <strong>{t.term}</strong> back to <strong>{to}</strong>? Add an optional note.</div>}
            {!needsReason&&<div><GlLabel>Note (optional)</GlLabel><GlInput value={rejectReason} onChange={e=>setRejectReason(e.target.value)} placeholder="Reason for returning to draft…"/></div>}
            <div style={{display:"flex",gap:8,justifyContent:"flex-end",paddingTop:4}}>
              <button onClick={()=>setTransitionModal(null)} style={{padding:"8px 16px",borderRadius:8,background:"transparent",border:`1px solid ${T.border}`,color:T.textSub,fontSize:12,cursor:"pointer"}}>Cancel</button>
              <button onClick={()=>transitionTerm(id,to,reasonValue)} disabled={needsReason&&!reasonValue.trim()} style={{padding:"8px 20px",borderRadius:8,background:(needsReason&&!reasonValue.trim())?"rgba(107,114,128,.2)":btnColor,border:"none",color:"#fff",fontSize:12,fontWeight:700,cursor:(needsReason&&!reasonValue.trim())?"default":"pointer"}}>{label}</button>
            </div>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="fadeUp" style={{height:"100%",display:"flex",flexDirection:"column"}}>
      <Topbar breadcrumb={[{label:"Glossary"}]}/>
      <div style={{flex:1,display:"flex",overflow:"hidden"}}>
        {renderSidebar()}
        {selTerm ? renderTermDetail() : selCat ? renderCategoryDetail() : renderGlossaryOverview()}
      </div>
      {renderModal()}
      {renderCtxMenu()}
      {renderTransitionModal()}
    </div>
  );
};

