const TypeBadge = ({type})=>{
  const s = TYPE_META[type]||{c:T.textMuted,bg:T.bgHover,icon:"▪"};
  return <span style={{fontSize:11,fontWeight:600,padding:"2px 8px",borderRadius:4,background:s.bg,color:s.c,border:`1px solid ${s.c}33`,display:"inline-flex",alignItems:"center",gap:4,whiteSpace:"nowrap"}}><span style={{fontSize:9.5}}>{s.icon}</span>{type}</span>;
};

const CertBadge = ({cert})=>{
  const map = {
    Draft:       {c:"#6b7280", bg:"rgba(107,114,128,.1)"},
    "In Review": {c:"#d97706", bg:"rgba(217,119,6,.1)"},
    Approved:    {c:"#16a34a", bg:"rgba(22,163,74,.1)"},
    Rejected:    {c:"#e11d48", bg:"rgba(225,29,72,.1)"},
    Deprecated:  {c:"#7c3aed", bg:"rgba(124,58,237,.1)"},
  };
  const s = map[cert]||{c:T.textMuted,bg:T.bgHover};
  return <span style={{fontSize:11,fontWeight:600,padding:"2px 8px",borderRadius:4,background:s.bg,color:s.c,border:`1px solid ${s.c}33`,display:"inline-flex",alignItems:"center",whiteSpace:"nowrap"}}>{cert||"No status"}</span>;
};

const QScore = ({score})=>{
  // A quality score is something EDG computes by profiling data it can read. A BI report, a
  // dbt model and a container have none, and the seeds say so with 0 - so a zero means "not
  // scored", never "scored zero". Rendering it as a red 0 was the worst of both readings.
  if(!Number.isFinite(score) || score<=0)
    return <span style={{fontSize:11,color:T.textMuted}}>&mdash;</span>;
  const c = score>=90?"#16a34a":score>=70?"#d97706":"#dc2626";
  const bg = score>=90?"rgba(22,163,74,.1)":score>=70?"rgba(217,119,6,.1)":"rgba(220,38,38,.1)";
  return (
    <span style={{display:"inline-flex",alignItems:"center",gap:7}}>
      <span style={{position:"relative",display:"inline-block",width:48,height:5,borderRadius:3,background:T.bgHover,overflow:"hidden",flexShrink:0}}>
        <span style={{display:"block",width:`${score}%`,height:"100%",background:c,borderRadius:3,transition:"width .3s"}}/>
      </span>
      <span style={{fontSize:11,fontWeight:700,fontFamily:"'Geist Mono',monospace",color:c,background:bg,padding:"1px 5px",borderRadius:4,minWidth:28,textAlign:"center"}}>{score}</span>
    </span>
  );
};

const Btn = ({children,variant,ghost,small,icon,onClick,disabled})=>{
  const base = {display:"inline-flex",alignItems:"center",gap:5,padding:small?"4px 10px":"7px 14px",borderRadius:7,fontSize:small?11:12.5,fontWeight:600,cursor:disabled?"not-allowed":"pointer",border:"none",transition:"all .12s",opacity:disabled?.5:1,whiteSpace:"nowrap"};
  const styles = variant==="primary"?{...base,background:T.accent,color:"#fff"}:variant==="danger"?{...base,background:T.roseDim,color:T.rose,border:`1px solid ${T.rose}33`}:ghost?{...base,background:"transparent",color:T.textSub,border:`1px solid ${T.border}`}:{...base,background:T.bgElevated,color:T.text,border:`1px solid ${T.border}`};
  return <button style={styles} onClick={onClick} disabled={disabled}>{icon&&<span style={{display:"flex"}}>{icon}</span>}{children}</button>;
};

const Input2 = ({value,onChange,placeholder,icon,style,multiline,rows=3})=>{
  const s = {width:"100%",padding:"7px 10px 7px"+(icon?" 10px":" 10px"),background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:8,color:T.text,fontSize:12.5,outline:"none",...style};
  if(multiline) return <textarea value={value} onChange={onChange} placeholder={placeholder} rows={rows} style={{...s,resize:"vertical",fontFamily:"inherit",lineHeight:1.5}}/>;
  return (
    <div style={{position:"relative",width:"100%",...style}}>
      {icon&&<span style={{position:"absolute",left:9,top:"50%",transform:"translateY(-50%)",color:T.textMuted,display:"flex",pointerEvents:"none"}}>{icon}</span>}
      <input value={value} onChange={onChange} placeholder={placeholder} style={{...s,paddingLeft:icon?"30px":"10px",width:"100%",boxSizing:"border-box"}}
        onFocus={e=>e.target.style.borderColor=T.accent} onBlur={e=>e.target.style.borderColor=T.border}/>
    </div>
  );
};

const Card2 = ({children,style})=>(
  <div style={{background:T.bgSurface,border:`1px solid ${T.border}`,borderRadius:10,...style}}>{children}</div>
);

const DataTable = ({cols,rows,onRowClick,emptyMsg="No data",rowStyle})=>(
  <div style={{background:T.bgSurface,border:`1px solid ${T.border}`,borderRadius:10,overflow:"hidden"}}>
    <div style={{overflowX:"auto"}}>
      {rows.length===0
        ? <div style={{padding:"40px 20px",textAlign:"center",color:T.textMuted,fontSize:13}}>{emptyMsg}</div>
        : <table style={{width:"100%",borderCollapse:"collapse"}}>
            <thead>
              <tr style={{background:T.bgElevated}}>
                {cols.map(c=><th key={c.key} style={{padding:"9px 14px",fontSize:10.5,fontWeight:600,color:T.textMuted,textAlign:"left",borderBottom:`1px solid ${T.border}`,whiteSpace:"nowrap",textTransform:"uppercase",letterSpacing:"0.07em"}}>{c.label}</th>)}
              </tr>
            </thead>
            <tbody>
              {rows.map((row,i)=>(
                <tr key={i} className={onRowClick?"row-hover":""} onClick={()=>onRowClick&&onRowClick(row)}
                  style={{borderBottom:i<rows.length-1?`1px solid ${T.border}`:"none",transition:"background .1s",...(rowStyle?rowStyle(row):null)}}>
                  {cols.map(c=><td key={c.key} style={{padding:"11px 14px",fontSize:12,color:T.text,verticalAlign:"middle"}}>{c.render?c.render(row[c.key],row):row[c.key]}</td>)}
                </tr>
              ))}
            </tbody>
          </table>}
    </div>
  </div>
);

const Modal = ({open,onClose,title,children,width=540})=>{
  if(!open)return null;
  return <div className="fadeIn" style={{position:"fixed",inset:0,zIndex:1000,background:"rgba(0,0,0,.7)",display:"flex",alignItems:"center",justifyContent:"center",padding:20}} onClick={onClose}>
    <div className="scaleIn" style={{background:T.bgSurface,border:`1px solid ${T.border}`,borderRadius:14,width:"100%",maxWidth:width,maxHeight:"90vh",overflow:"auto"}} onClick={e=>e.stopPropagation()}>
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",padding:"18px 22px",borderBottom:`1px solid ${T.border}`}}>
        <span style={{fontSize:14,fontWeight:600,color:T.text}}>{title}</span>
        <button onClick={onClose} style={{background:"transparent",border:"none",color:T.textMuted,cursor:"pointer",display:"flex"}}>{Ic.x(14)}</button>
      </div>
      <div style={{padding:22}}>{children}</div>
    </div>
  </div>;
};

const Toast = ({msg,type="success",onDone})=>{
  useEffect(()=>{const t=setTimeout(onDone,3000);return()=>clearTimeout(t);},[]);
  const c = type==="success"?T.accent:type==="error"?T.rose:T.amber;
  return <div className="slideIn" style={{position:"fixed",bottom:24,right:24,zIndex:2000,padding:"12px 18px",background:T.bgSurface,border:`1px solid ${c}44`,borderRadius:10,boxShadow:"0 8px 24px rgba(0,0,0,.3)",display:"flex",alignItems:"center",gap:10,fontSize:13,color:T.text,maxWidth:320}}>
    <span style={{width:8,height:8,borderRadius:"50%",background:c,flexShrink:0}}/>
    {msg}
  </div>;
};

const Topbar = ({breadcrumb,actions})=>{
  const {isDark,toggleTheme} = useTheme();
  return (
  <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",padding:"0 20px 0 24px",height:52,borderBottom:`1px solid ${T.border}`,background:T.bgSurface,flexShrink:0}}>
    {/* Left: breadcrumb */}
    <div style={{display:"flex",alignItems:"center",gap:6}}>
      {breadcrumb.map((b,i)=>(
        <React.Fragment key={i}>
          {i>0&&<span style={{color:T.textMuted,fontSize:12}}>/</span>}
          {b.onClick
            ? <button onClick={b.onClick} style={{background:"transparent",border:"none",color:T.textMuted,cursor:"pointer",fontSize:13,padding:0,fontFamily:"inherit"}}>{b.label}</button>
            : <span style={{fontSize:13,fontWeight:i===breadcrumb.length-1?600:400,color:i===breadcrumb.length-1?T.text:T.textMuted}}>{b.label}</span>}
        </React.Fragment>
      ))}
    </div>
    {/* Right: page actions + global controls */}
    <div style={{display:"flex",gap:6,alignItems:"center"}}>
      {actions&&<div style={{display:"flex",gap:6,alignItems:"center",marginRight:8,paddingRight:8,borderRight:`1px solid ${T.border}`}}>{actions}</div>}
      {/* Theme toggle */}
      <button onClick={()=>toggleTheme()} title={isDark?"Switch to light":"Switch to dark"}
        style={{width:32,height:32,borderRadius:8,background:"transparent",border:`1px solid ${T.border}`,color:T.textSub,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",transition:"all .15s"}}
        onMouseEnter={e=>{e.currentTarget.style.background=T.bgHover;e.currentTarget.style.color=T.text;}}
        onMouseLeave={e=>{e.currentTarget.style.background="transparent";e.currentTarget.style.color=T.textSub;}}>
        {isDark
          ? <svg width="14" height="14" viewBox="0 0 20 20" fill="currentColor"><path d="M10 2a1 1 0 011 1v1a1 1 0 11-2 0V3a1 1 0 011-1zm4 8a4 4 0 11-8 0 4 4 0 018 0zm-.464 4.95l.707.707a1 1 0 001.414-1.414l-.707-.707a1 1 0 00-1.414 1.414zm2.12-10.607a1 1 0 010 1.414l-.706.707a1 1 0 11-1.414-1.414l.707-.707a1 1 0 011.414 0zM17 11a1 1 0 100-2h-1a1 1 0 100 2h1zm-7 4a1 1 0 011 1v1a1 1 0 11-2 0v-1a1 1 0 011-1zM5.05 6.464A1 1 0 106.465 5.05l-.708-.707a1 1 0 00-1.414 1.414l.707.707zm1.414 8.486l-.707.707a1 1 0 01-1.414-1.414l.707-.707a1 1 0 011.414 1.414zM4 11a1 1 0 100-2H3a1 1 0 000 2h1z"/></svg>
          : <svg width="14" height="14" viewBox="0 0 20 20" fill="currentColor"><path d="M17.293 13.293A8 8 0 016.707 2.707a8.001 8.001 0 1010.586 10.586z"/></svg>}
      </button>
      {/* Notifications */}
      <NotifBtn/>
      {/* User menu */}
      <UserMenu/>
    </div>
  </div>
  );
};

const Metric = ({label,value,sub,delta,color})=>(
  <div style={{padding:"14px 16px",background:T.bgSurface,border:`1px solid ${T.border}`,borderRadius:10}}>
    <div style={{fontSize:11,color:T.textMuted,marginBottom:4,fontWeight:500}}>{label}</div>
    <div style={{fontSize:22,fontWeight:700,color:color||T.text,fontFamily:"'Geist Mono',monospace"}}>{value}</div>
    {delta&&<div style={{fontSize:11,color:delta.startsWith("-")?T.red:T.green,marginTop:2,fontFamily:"'Geist Mono',monospace"}}>{delta}</div>}
    {sub&&<div style={{fontSize:11,color:T.textMuted,marginTop:2}}>{sub}</div>}
  </div>
);

const SH = ({title,sub,action})=>(
  <div style={{marginBottom:12,display:"flex",alignItems:"center",justifyContent:"space-between"}}>
    <div>
      <div style={{fontSize:13,fontWeight:600,color:T.text}}>{title}</div>
      {sub&&<div style={{fontSize:11,color:T.textMuted,marginTop:2}}>{sub}</div>}
    </div>
    {action&&<div>{action}</div>}
  </div>
);

// Tabs2: accepts either string[] or {key,label}[] arrays
const Tabs2 = ({tabs,active,onChange,pill})=>{
  const items = tabs.map(t=>typeof t==="string"?{key:t,label:t}:t);
  if(pill) return (
    <div style={{display:"flex",gap:4}}>
      {items.map(t=>(
        <button key={t.key} onClick={()=>onChange(t.key)} style={{padding:"4px 12px",borderRadius:99,background:active===t.key?T.accent:T.bgElevated,color:active===t.key?"#fff":T.textSub,border:`1px solid ${active===t.key?T.accent:T.border}`,fontSize:11.5,fontWeight:active===t.key?600:400,cursor:"pointer",transition:"all .12s"}}>{t.label}</button>
      ))}
    </div>
  );
  return (
    <div style={{display:"flex",borderBottom:`1px solid ${T.border}`,marginBottom:20,overflowX:"auto",flexShrink:0}}>
      {items.map(t=>(
        <button key={t.key} onClick={()=>onChange(t.key)} style={{padding:"8px 16px",background:"transparent",border:"none",borderBottom:`2px solid ${active===t.key?T.accent:"transparent"}`,color:active===t.key?T.text:T.textMuted,fontSize:13,fontWeight:active===t.key?600:400,cursor:"pointer",transition:"all .12s",marginBottom:-1,whiteSpace:"nowrap",flexShrink:0}}>{t.label}</button>
      ))}
    </div>
  );
};


// Segmented control tabs — same style as Settings › Teams & Users
const SegTabs = ({tabs,active,onChange})=>(
  <div style={{display:"flex",gap:2,padding:3,background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:9,width:"fit-content",flexWrap:"wrap"}}>
    {tabs.map(t=>{
      const k=typeof t==="string"?t:t.key;
      const label=typeof t==="string"?t:t.label;
      const on=active===k;
      return (
        <button key={k} onClick={()=>onChange(k)} style={{display:"flex",alignItems:"center",gap:6,padding:"5px 14px",borderRadius:6,fontSize:12,fontWeight:on?700:500,cursor:"pointer",transition:"all .12s",background:on?T.bgSurface:"transparent",border:on?`1px solid ${T.border}`:"1px solid transparent",color:on?T.text:T.textMuted,boxShadow:on?"0 1px 3px rgba(0,0,0,.08)":"none",whiteSpace:"nowrap"}}>
          {label}
          {t.count!=null&&<span style={{fontSize:10,background:on?T.accent:T.bgHover,color:on?"#fff":T.textMuted,padding:"0 5px",borderRadius:99,minWidth:16,textAlign:"center"}}>{t.count}</span>}
        </button>
      );
    })}
  </div>
);

// ─────────────────────────────────────────────
// NOTIFICATIONS + USER MENU + DOCBOT DATA
// ─────────────────────────────────────────────
// Notifications = awareness feed. Standard template per category: "{what happened} · {subject}".
// Seeds map to the agreed catalog's event keys so the bell and Settings stay in sync.
const NOTIFS = [
  // ── Catalog — changes on an asset you own/steward ──
  {id:1, type:"alert",        event:"quality_failed",     asset:"orders",       unread:true, title:"Quality check failed · orders",             body:"Rule 'orders.amount_not_null' failed on 847 rows (1.8%)",            time:"2m ago",  nav:"quality"},
  {id:2, type:"cert",         event:"status_changed",     asset:"customers",    unread:true, title:"Status changed to Approved · customers",    body:"Approved by dev.patel (steward)",                                    time:"1h ago",  nav:"catalog"},
  {id:3, type:"field_updated",event:"description_changed",asset:"orders",       unread:true, title:"Description updated · orders",              body:"priya.nair updated the description",                                 time:"2h ago",  nav:"catalog"},
  {id:4, type:"assigned",     event:"owner_assigned",     asset:"dim_customer", unread:true, forMe:true, title:"Assigned as steward · dim_customer",  body:"james.oh assigned you",                                    time:"1d ago",  nav:"catalog"},
  {id:5, type:"tag",          event:"tag_changed",        asset:"orders",       unread:false,title:"Tag added · orders",                        body:"'Tier 1' attached by maya.chen",                                     time:"5h ago",  nav:"catalog"},
  {id:6, type:"field_updated",event:"glossary_linked",    asset:"orders",       unread:false,title:"Glossary term linked · orders",             body:"'Net Revenue' linked by dev.patel",                                  time:"7h ago",  nav:"catalog"},
  {id:7, type:"policy",       event:"policy_attached",    asset:"orders",       unread:false,title:"Policy attached · orders",                  body:"'PII Masking' policy now applies to orders",                         time:"8h ago",  nav:"catalog"},
  {id:8, type:"contract",     event:"contract_failed",    asset:"orders",       unread:true, title:"Contract validation failed · orders",       body:"orders_contract — status not in the allowed set",                    time:"14m ago", nav:"catalog"},
  // ── Policies — scoped to the target asset's owner / the policy owner ──
  {id:9, type:"policy",       event:"policy_violation",   asset:"transactions", unread:true, title:"Policy violation · transactions",           body:"Status gate — transactions is queryable without an Approved status", time:"6m ago",  nav:"policymanager"},
  {id:10,type:"policy",       event:"enf_requested",      asset:"orders",       unread:true, forMe:true, title:"Enforcement approval requested · orders", body:"dev.patel asks you to approve the Masking rule", time:"20m ago", nav:"policymanager"},
  {id:11,type:"cert",         event:"enf_decided",        asset:"orders",       unread:false,title:"Enforcement approved · orders",             body:"maya.chen approved the Masking rule — now active",                   time:"6h ago",  nav:"policymanager"},
  {id:12,type:"policy",       event:"hold_release",       asset:"payments",     unread:false,forMe:true, title:"Legal-hold release requested · payments", body:"alex.wu requested to release 3,412 records", time:"3h ago",  nav:"policymanager"},
  {id:13,type:"alert",        event:"run_blocked",        asset:null,           unread:true, title:"Run blocked · PII Masking",                 body:"Masking rule pending owner approval — evaluation blocked",           time:"25m ago", nav:"policymanager"},
  // ── Classifications (tag governance) ──
  {id:14,type:"tag",          event:"tag_review",         asset:null,           unread:true, title:"Source tag submitted for review · financial_forecast", body:"From dbt sync — promote or reject as steward",           time:"18m ago", nav:"tags"},
  {id:15,type:"alert",        event:"tag_deleted",        asset:null,           unread:true, forMe:true, title:"Deletion requested · Tier 1 (tag)",   body:"alex.wu requested to delete the 'Tier 1' tag — 42 assets affected",  time:"30m ago", nav:"tags"},
  // ── Glossary ──
  {id:16,type:"term_submitted",event:"term_review",       asset:null,           unread:true, title:"Term submitted for review · Churn Rate",    body:"dev.patel submitted it — awaiting your approval as steward",          time:"22m ago", nav:"glossary"},
  {id:17,type:"alert",        event:"term_deleted",       asset:null,           unread:false,forMe:true, title:"Deletion requested · Legacy Metric (term)", body:"priya.nair requested to delete this term",    time:"4h ago",  nav:"glossary"},
  // ── Domains ──
  {id:18,type:"cert",         event:"domain_review",      asset:null,           unread:true, forMe:true, title:"Domain submitted for review · Commerce", body:"maya.chen asks you to review the Commerce domain", time:"40m ago", nav:"domains"},
  {id:19,type:"alert",        event:"domain_deleted",     asset:null,           unread:false,forMe:true, title:"Deletion requested · Product (domain)", body:"james.oh requested to delete the Product domain",  time:"5h ago",  nav:"domains"},
  // ── Data Products ──
  {id:20,type:"new_dataset",  event:"dp_review",          asset:null,           unread:true, forMe:true, title:"Data product submitted for review · Customer 360", body:"priya.nair asks you to review it", time:"50m ago", nav:"dataproducts"},
  {id:21,type:"alert",        event:"dp_deleted",         asset:null,           unread:false,forMe:true, title:"Deletion requested · Sales Cube (product)", body:"dev.patel requested to delete this product",  time:"6h ago",  nav:"dataproducts"},
  // ── Connections — routed to the Connection Admin ──
  {id:22,type:"alert",        event:"workflow_failed",    asset:null,           unread:true, title:"Workflow failed · Snowflake DWH",           body:"Ingestion workflow aborted — source unreachable",                    time:"9m ago",  nav:"integrations"},
  {id:23,type:"pipeline",     event:"schedule_paused",    asset:null,           unread:false,title:"Schedule paused · Postgres CRM",            body:"Automatic sync turned off by admin",                                 time:"12h ago", nav:"integrations"},
];
// Scope: you only get a notification if it's a personal one, has no asset (platform-wide),
// you own/steward the asset — or you're an admin (oversight). ASSETS defined above.
const _respFor = (assetName, me) => { const a=(typeof ASSETS!=="undefined"?ASSETS:[]).find(x=>x.name===assetName); if(!a) return false; const own=(Array.isArray(a.owners)?a.owners:[a.owner]).filter(Boolean); const stw=(Array.isArray(a.stewards)?a.stewards:[a.steward]).filter(Boolean); return own.includes(me)||stw.includes(me); };
// ── Notification event catalog ──────────────────────────────────────────────
// Two-level preference model: preferences are stored per EVENT TYPE (the leaf).
// The menu is ONLY a display grouping with a master toggle that fans out to its
// events — it is never a stored setting of its own. The event is the single
// source of truth; both the settings UI and notifVisible key off n.event, never
// the menu. (In-app is the only channel today; email/Slack are a later step.)
// Agreed catalog (product-grounded, owner/steward-scoped). 7 active menus.
// Admin · My Tasks · Access & Roles are PARKED for now (no producing engine /
// out of scope this pass). Recipient routing per event: [O] object owner/steward,
// [P] personal (requester/assignee), [R] role (Connection Admin).
const NOTIF_CATALOG = [
  {menu:"Catalog",         key:"catalog",      events:[
    {ev:"description_changed", label:"Description / metadata changed"},
    {ev:"status_changed",      label:"Status changed"},
    {ev:"owner_assigned",      label:"Owner / steward assigned"},
    {ev:"tag_changed",         label:"Tag added / removed"},
    {ev:"glossary_linked",     label:"Glossary term linked / unlinked"},
    {ev:"policy_attached",     label:"Policy attached / removed"},
    {ev:"quality_failed",      label:"Quality check failed / incident opened"},
    {ev:"contract_failed",     label:"Data contract validation failed"},
  ]},
  {menu:"Policies",        key:"policy",       events:[
    {ev:"enf_requested",    label:"Enforcement approval requested → owner"},
    {ev:"enf_decided",      label:"Enforcement approved / rejected → submitter"},
    {ev:"hold_release",     label:"Legal-hold release requested / released"},
    {ev:"run_blocked",      label:"Run blocked (pending approval)"},
    {ev:"policy_review",    label:"Policy submitted for review → steward"},
    {ev:"policy_violation", label:"Policy violation → remediate"},
  ]},
  {menu:"Classifications", key:"tags",         events:[
    {ev:"tag_review",   label:"Source tag submitted for review → steward"},
    {ev:"tag_deleted",  label:"Tag deleted / deletion requested → owner"},
  ]},
  {menu:"Glossary",        key:"glossary",     events:[
    {ev:"term_review",  label:"Term submitted for review → steward"},
    {ev:"term_deleted", label:"Term deleted / deletion requested → owner"},
  ]},
  {menu:"Domains",         key:"domains",      events:[
    {ev:"domain_review",  label:"Submitted for review → steward"},
    {ev:"domain_deleted", label:"Deleted → owner"},
  ]},
  {menu:"Data Products",   key:"dataproducts", events:[
    {ev:"dp_review",  label:"Submitted for review → steward"},
    {ev:"dp_deleted", label:"Deleted → owner"},
  ]},
  {menu:"Data Ask",        key:"dataask",      events:[
    {ev:"da_answer_reported", label:"Answer reported as wrong → space steward"},
    {ev:"da_space_review",    label:"Answer Space submitted for review → steward"},
    {ev:"da_space_published", label:"Answer Space published / unpublished → owner"},
    {ev:"da_access_denied",   label:"Question refused by the classification blocklist → Admin"},
    {ev:"da_index_failed",    label:"Index build failed → space owner"},
    {ev:"da_drift_detected",  label:"New tables / columns / files not yet indexed → space owner"},
    {ev:"da_credit_threshold",label:"Credit cap threshold reached → Admin & space owner"},
  ]},
  {menu:"Connections",     key:"integrations", events:[
    {ev:"workflow_failed", label:"Workflow failed → Connection Admin"},
    {ev:"schedule_paused", label:"Schedule paused → Connection Admin"},
  ]},
];
const NOTIF_EV_MENU = {}; NOTIF_CATALOG.forEach(g=>g.events.forEach(e=>{NOTIF_EV_MENU[e.ev]=g.key;}));
let _notifPrefs = NOTIF_CATALOG.reduce((o,g)=>{g.events.forEach(e=>{o[e.ev]=true;});return o;},{});
const _npSubs = new Set();
const _npNotify = ()=>_npSubs.forEach(f=>f());
const npSet = (ev,on)=>{ _notifPrefs={..._notifPrefs,[ev]:on}; _npNotify(); };
const npSetMenu = (menuKey,on)=>{ const g=NOTIF_CATALOG.find(x=>x.key===menuKey); if(!g)return; const next={..._notifPrefs}; g.events.forEach(e=>{next[e.ev]=on;}); _notifPrefs=next; _npNotify(); };
const useNotifPrefs = ()=>{ const [,f]=useState(0); useEffect(()=>{const fn=()=>f(n=>n+1);_npSubs.add(fn);return()=>{_npSubs.delete(fn);};},[]); return _notifPrefs; };
// Visible = this event type not muted AND (admin, personal, platform-wide, or you own/steward the asset).
const notifVisible = (n, me, isAdmin) => (!n.event || _notifPrefs[n.event]!==false) && (isAdmin || n.forMe || !n.asset || _respFor(n.asset, me));

// ── Shared reactive store for the notification bell ──
// NOTIFS was static seed data duplicated into local state by both NotificationsPanel
// and NotificationsDrawer; neither reflected real app activity. Lifted to a module
// store + pushNotif() so status-change and deletion request/approve/reject events
// generate a real bell entry (standard template "{what happened} · {subject}"),
// not just a toast.
const _notifSubs = new Set();
let _notifState = NOTIFS.map(n => ({...n}));
let _notifIdSeq = NOTIFS.length;
const notifSet = (updater) => { _notifState = typeof updater==="function"?updater(_notifState):updater; _notifSubs.forEach(fn=>fn()); };
const useNotifs = () => {
  const [,force] = useState(0);
  useEffect(()=>{ const fn=()=>force(n=>n+1); _notifSubs.add(fn); return ()=>_notifSubs.delete(fn); },[]);
  return [_notifState, notifSet];
};
const pushNotif = (entry) => { _notifIdSeq += 1; notifSet(prev=>[{id:_notifIdSeq, unread:true, time:"just now", asset:null, forMe:true, ...entry}, ...prev]); };

// Reusable notification-preferences UI — lives in Settings → Notifications (the proper home).
// Per-category in-app mute toggles + honest channel status. Wired to the shared _notifPrefs store.
const NotifPrefsSettings = ()=>{
  const prefs = useNotifPrefs();
  const [open,setOpen] = useState({});
  const toggleOpen = (k)=>setOpen(o=>({...o,[k]:!o[k]}));
  return (
    <div style={{display:"flex",flexDirection:"column",gap:22}}>
      {/* In-app alerts — menu groups (collapsed) with a master toggle; expand to tune individual events */}
      <div>
        <div style={{fontSize:12,fontWeight:600,color:T.textSub,marginBottom:4}}>In-app alerts</div>
        <div style={{fontSize:11.5,color:T.textMuted,marginBottom:12}}>Toggle a whole menu, or expand it to tune individual events. You only receive alerts for assets you own or steward; these switches mute event types on top of that. In-app is the only channel today — email &amp; Slack are coming.</div>
        <div style={{display:"flex",flexDirection:"column",gap:8}}>
          {NOTIF_CATALOG.map(g=>{
            const total = g.events.length;
            const onCount = g.events.filter(e=>prefs[e.ev]!==false).length;
            const anyOn = onCount>0; const allOn = onCount===total; const isOpen = !!open[g.key];
            return (
              <div key={g.key} style={{background:T.bgSurface,border:`1px solid ${T.border}`,borderRadius:10,overflow:"hidden"}}>
                {/* Group header — menu-level master control */}
                <div style={{display:"flex",alignItems:"center",gap:10,padding:"11px 14px"}}>
                  <button onClick={()=>toggleOpen(g.key)} style={{background:"none",border:"none",cursor:"pointer",color:T.textMuted,display:"flex",alignItems:"center",padding:0,width:14,flexShrink:0}}>
                    <svg width="10" height="10" viewBox="0 0 10 10" fill="none" style={{transform:isOpen?"rotate(90deg)":"none",transition:"transform .15s"}}><path d="M3 2l4 3-4 3" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/></svg>
                  </button>
                  <span onClick={()=>toggleOpen(g.key)} style={{flex:1,fontSize:13,fontWeight:600,color:T.text,cursor:"pointer"}}>{g.menu}</span>
                  <span style={{fontSize:10.5,color:T.textMuted,fontWeight:500}}>{allOn?`All ${total}`:!anyOn?"Off":`${onCount} of ${total}`}</span>
                  <div onClick={()=>npSetMenu(g.key,!anyOn)} title={anyOn?"Turn all off":"Turn all on"} style={{width:34,height:19,borderRadius:10,background:anyOn?T.accent:T.border,cursor:"pointer",position:"relative",transition:"background .2s",flexShrink:0,opacity:allOn||!anyOn?1:0.8}}>
                    <div style={{position:"absolute",top:2,left:anyOn?17:2,width:15,height:15,borderRadius:"50%",background:"#fff",transition:"left .2s",boxShadow:"0 1px 2px rgba(0,0,0,.2)"}}/>
                  </div>
                </div>
                {/* Per-event toggles (progressive disclosure — the attribute level) */}
                {isOpen&&<div style={{borderTop:`1px solid ${T.border}`,padding:"3px 14px 8px 38px"}}>
                  {g.events.map(e=>{const on=prefs[e.ev]!==false;return(
                    <div key={e.ev} style={{display:"flex",alignItems:"center",justifyContent:"space-between",padding:"8px 0"}}>
                      <span style={{fontSize:12,color:on?T.textSub:T.textMuted}}>{e.label}</span>
                      <div onClick={()=>npSet(e.ev,!on)} style={{width:30,height:17,borderRadius:9,background:on?T.accent:T.border,cursor:"pointer",position:"relative",transition:"background .2s",flexShrink:0}}>
                        <div style={{position:"absolute",top:2,left:on?15:2,width:13,height:13,borderRadius:"50%",background:"#fff",transition:"left .2s",boxShadow:"0 1px 2px rgba(0,0,0,.2)"}}/>
                      </div>
                    </div>
                  );})}
                </div>}
              </div>
            );
          })}
        </div>
      </div>
      {/* Channels — honest about what's live today */}
      <div>
        <div style={{fontSize:12,fontWeight:600,color:T.textSub,marginBottom:10}}>Delivery channels</div>
        <div style={{display:"flex",flexDirection:"column",gap:8}}>
          {[["In-app","Active",true],["Email","Coming soon",false],["Slack","Coming soon",false]].map(([c,st,live])=>(
            <div key={c} style={{display:"flex",alignItems:"center",justifyContent:"space-between",padding:"12px 16px",background:T.bgSurface,border:`1px solid ${T.border}`,borderRadius:9,opacity:live?1:0.7}}>
              <span style={{fontSize:13,fontWeight:500,color:live?T.text:T.textMuted}}>{c}</span>
              {live
                ? <span style={{fontSize:11,color:"#16a34a",fontWeight:600,display:"inline-flex",alignItems:"center",gap:5}}><span style={{width:6,height:6,borderRadius:"50%",background:"#16a34a"}}/>{st}</span>
                : <span style={{fontSize:10.5,color:T.textMuted,background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:5,padding:"2px 8px",fontWeight:600}}>{st}</span>}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

