    setWizardRules(rules);
    setWizardSqlRules(sqlBack);
    setWizardRuleTab("preset");
    setCreateStep(opts.step||1);
    setSoloRuleId(solo);
    setSoloAdd(!!opts.addBlank);
    setIsEditMode(true);
