// Resolve every node's display metadata from the catalog once. A warehouse table
// borrows the columns of the dbt source or model that mirrors it, so the graph and
// the Schema tab cannot disagree.
// Resolved lazily, not at module-eval time: DBT_MODEL_COLUMNS and ASSET_COLUMNS are
// declared further down the file, so touching them during evaluation would throw.
let _dbtDagMeta = null;
const dbtDagMeta = ()=>{
  if(_dbtDagMeta) return _dbtDagMeta;
  const all = (typeof ASSETS!=="undefined"?ASSETS:[]);
  const colsOf = (a)=>{
    const key = a.dbtSource || a.dbtModel || a.name;
    const dc = DBT_MODEL_COLUMNS[key];
    if(dc) return dc.map(c=>({n:c.name,t:c.dataType}));
    const ac = (typeof ASSET_COLUMNS!=="undefined" && ASSET_COLUMNS[a.name]) || [];
    return ac.map(n=>({n,t:"column"}));
  };
  const meta = {};
  Object.entries(DBT_DAG_NODES).forEach(([id,n])=>{
    const a = all.find(x=>x.name===n.asset);
    if(!a) return;   // a node whose asset was removed simply drops out of the graph
    meta[id] = {
      assetType:a.type, service:a.service, db:a.db, domain:a.domain,
      owner:a.owner, steward:a.steward, quality:a.quality, cert:a.cert,
      tags:a.tags||[], description:a.description, label:a.name, assetName:a.name,
      cols: n.cols!==undefined ? n.cols : colsOf(a),
    };
  });
  return (_dbtDagMeta = meta);
};

// asset name -> node id, so an asset's Lineage tab knows where it sits. Lazy for the
// same reason as the metadata above.
let _dbtNodeByAsset = null;
const dbtNodeByAsset = ()=>{
  if(_dbtNodeByAsset) return _dbtNodeByAsset;
  const meta = dbtDagMeta(), m = {};
  Object.entries(DBT_DAG_NODES).forEach(([id,n])=>{ if(n.asset && meta[id]) m[n.asset] = id; });
  return (_dbtNodeByAsset = m);
};

// Focused subgraph: the node's full ancestry + descendancy, laid out by depth.
// Columns are packed left to right on a 310px grid; siblings at the same depth
// stack vertically around the centre line.
function dbtFocusedGraph(activeId){
  const upOf   = id => DBT_DAG_EDGES.filter(e=>e.t===id).map(e=>e.s);
  const downOf = id => DBT_DAG_EDGES.filter(e=>e.s===id).map(e=>e.t);
  const walk = (id,step,acc)=>step(id).forEach(n=>{ if(!acc.has(n)){ acc.add(n); walk(n,step,acc); } });
  const anc=new Set(), desc=new Set();
  walk(activeId,upOf,anc); walk(activeId,downOf,desc);
  const META = dbtDagMeta();
  const keep = new Set([activeId,...anc,...desc].filter(id=>META[id]));
  const edges = DBT_DAG_EDGES.filter(e=>keep.has(e.s)&&keep.has(e.t));

  // Longest-path depth. The graph is a DAG, so relaxing |keep| times settles it.
  const depth = {}; keep.forEach(id=>depth[id]=0);
  for(let pass=0; pass<keep.size; pass++){
    let moved=false;
    edges.forEach(e=>{ if(depth[e.t] < depth[e.s]+1){ depth[e.t]=depth[e.s]+1; moved=true; } });
    if(!moved) break;
  }

  // Then pull every non-sink rightwards until it sits directly before its earliest
  // consumer. Longest-path alone parks each branch input in the first column it is
  // allowed to occupy, which leaves a seed or a source stranded columns away from the
  // model that reads it - and the connecting edge then flies across the canvas behind
  // unrelated node cards. Walking in reverse depth order means a node is only moved
  // once its consumers are final, and moving right can never break the left-to-right
  // rule, so the layout stays valid while most edges shorten to a single hop.
  [...keep].sort((a,b)=>depth[b]-depth[a]).forEach(id=>{
    const outs = DBT_DAG_EDGES.filter(e=>e.s===id&&keep.has(e.t)).map(e=>e.t);
    if(outs.length) depth[id] = Math.min(...outs.map(t=>depth[t])) - 1;
  });

  // Group by depth, then stack. Sorting by id keeps the layout stable across renders.
  const byDepth = {};
  [...keep].sort().forEach(id=>{ (byDepth[depth[id]] = byDepth[depth[id]]||[]).push(id); });
  const topo = {};
  Object.entries(byDepth).forEach(([d,ids])=>{
    ids.forEach((id,k)=>{
      topo[id] = {
        x: Number(d)*310,
        y: Math.round(210 + (k - (ids.length-1)/2) * 185),
        label: META[id].label,
        upstream:   upOf(id).filter(n=>keep.has(n)),
        downstream: downOf(id).filter(n=>keep.has(n)),
        active: id===activeId,
      };
    });
  });
  // Span in columns, so the renderer can skip labelling an edge whose midpoint would
  // land on top of an unrelated node.
  const spanned = edges.map(e=>({...e, span:(topo[e.t].x-topo[e.s].x)/310}));
  const colMaps = DBT_DAG_COLMAPS.filter(m=>keep.has(m.s)&&keep.has(m.t));
  const hasDbt = [...keep].some(id=>String(META[id].assetType||"").startsWith("dbt "));
  return {topo, meta:META, colMaps, edges:spanned, hasDbt};
}

// Collapse the dbt layer out of a graph: dbt nodes are removed, their upstreams wired
// straight to their downstreams (transitively), column maps composed across the gap, and
// the surviving nodes re-spaced so no hole is left behind. This is what the "Show dbt
// models" toggle turns off - the same lineage read as business flow instead of engineering
// flow, exactly the choice Atlan gives you.
function collapseDbtNodes(G){
  const isDbt=id=>String(G.meta[id]&&G.meta[id].assetType||"").startsWith("dbt ");
  const dropped=Object.keys(G.topo).filter(isDbt);
  if(!dropped.length) return G;
  const keep=Object.keys(G.topo).filter(id=>!isDbt(id));
  const dropSet=new Set(dropped);

  // Resolve a node to the nearest surviving ancestors / descendants.
  const upKept=(id,seen)=>{
    seen=seen||new Set();
    return (G.topo[id].upstream||[]).flatMap(u=>{
      if(seen.has(u)) return []; seen.add(u);
      return dropSet.has(u)?upKept(u,seen):[u];
    });
  };
  const downKept=(id,seen)=>{
    seen=seen||new Set();
    return (G.topo[id].downstream||[]).flatMap(d=>{
      if(seen.has(d)) return []; seen.add(d);
      return dropSet.has(d)?downKept(d,seen):[d];
    });
  };

  // Bridged links, before cleanup.
  const down={},up={};
  keep.forEach(id=>{ down[id]=[...new Set(downKept(id))]; up[id]=[...new Set(upKept(id))]; });

  // Transitive reduction. Bridging a branch out (the exposure, say) can imply a shortcut
  // that duplicates a path already on screen - postgres straight to the dashboard, leaping
  // over Snowflake and Tableau. Drop any link that a longer surviving path already tells.
  const reachable=(from,to,viaOnly)=>{
    const stack=(down[from]||[]).filter(n=>!(viaOnly&&n===to));
    const seen=new Set();
    while(stack.length){
      const n=stack.pop();
      if(n===to) return true;
      if(seen.has(n)) continue; seen.add(n);
      (down[n]||[]).forEach(x=>stack.push(x));
    }
    return false;
  };
  keep.forEach(id=>{
    down[id]=(down[id]||[]).filter(d=>!reachable(id,d,true));
  });
  keep.forEach(id=>{ up[id]=keep.filter(u=>(down[u]||[]).includes(id)); });

  // Re-space surviving nodes: distinct original x values collapse to an even 310px grid.
  const xs=[...new Set(keep.map(id=>G.topo[id].x))].sort((a,b)=>a-b);
  const topo={};
  keep.forEach(id=>{
    const t=G.topo[id];
    topo[id]={...t, x:xs.indexOf(t.x)*310, upstream:up[id], downstream:down[id]};
  });

  // Edges: one per surviving pair, labelled by whether dbt was bridged out.
  const edges=[];const seenE=new Set();
  keep.forEach(id=>topo[id].downstream.forEach(d=>{
    const k=id+">"+d; if(seenE.has(k))return; seenE.add(k);
    const direct=(G.edges||[]).find(e=>e.s===id&&e.t===d);
    edges.push({id:"c_"+id+"_"+d,s:id,t:d,tk:direct?direct.tk:"dbt model"});
  }));

  // Column maps: compose s->[dbt...]->t by joining on the intermediate column name.
  const colMaps=[];
  const compose=(originId,fromId,cols,seen)=>{
    (G.colMaps||[]).filter(m=>m.s===fromId).forEach(m=>{
      const joined=cols.map(c=>{
        const hop=m.cols.find(x=>x.sc===c.tc);
        return hop?{sc:c.sc,tc:hop.tc}:null;
      }).filter(Boolean);
      if(!joined.length) return;
      if(dropSet.has(m.t)){ if(!seen.has(m.t)) compose(originId,m.t,joined,new Set([...seen,m.t])); }
      else colMaps.push({s:originId,t:m.t,cols:joined});
    });
  };
  (G.colMaps||[]).forEach(m=>{
    if(dropSet.has(m.s)) return;
    if(!dropSet.has(m.t)){ colMaps.push(m); return; }
    compose(m.s,m.t,m.cols.map(c=>({sc:c.sc,tc:c.tc})),new Set([m.t]));
  });

  // A column map is only meaningful if its edge survived the reduction above.
  const live=new Set(edges.map(e=>e.s+">"+e.t));
  return {topo,meta:G.meta,colMaps:colMaps.filter(m=>live.has(m.s+">"+m.t)),edges};
}

// Narrow a graph to one source. Everything the asset's own connector reported stays; hops
// into another product are dropped, along with any edge or column map that touched them.
// The asset's own node always survives, so the graph can never come back empty.
function inSourceOnly(G, service, activeId){
  if(!service) return G;
  const keep = new Set(Object.keys(G.topo).filter(id =>
    id===activeId || !G.meta[id] || G.meta[id].service===service));
  if(keep.size===0) return G;
  const topo={};
  Object.entries(G.topo).forEach(([id,t])=>{
    if(!keep.has(id)) return;
    topo[id]={...t,
      upstream:  (t.upstream  ||[]).filter(u=>keep.has(u)),
      downstream:(t.downstream||[]).filter(d=>keep.has(d))};
  });
  return {...G, topo,
    edges:   (G.edges  ||[]).filter(e=>keep.has(e.s)&&keep.has(e.t)),
    colMaps: (G.colMaps||[]).filter(m=>keep.has(m.s)&&keep.has(m.t))};
}

// How many hops in a graph belong to another source. Drives the control's label, and tells
// the honest story when the answer is none.
function crossSourceCount(G, service){
  if(!service) return 0;
  return Object.entries(G.topo||{}).filter(([id]) =>
    G.meta[id] && G.meta[id].service && G.meta[id].service!==service).length;
}

// Resolve which lineage graph an asset's Lineage tab renders. dbt assets (and the Snowflake
// table a dbt model materializes) get the full Postgres -> dbt -> Snowflake -> Tableau path;
// Tableau assets get the BI path; everything else keeps the default graph. The matching node
// is marked CURRENT.
function pickLineageGraph(asset){
  // The unified graph FIRST, wherever the asset appears in it. It spans Snowflake sources ->
  // dbt models -> the table they materialize -> the Tableau and Power BI objects that read
  // it, so a Power BI dataset and the dbt model that feeds it now answer with the same
  // chain. Resolving the connector graph first was the whole bug: it returned a nine-node
  // slice with one stub node standing in for everything upstream.
  if(asset){
    const byAsset = dbtNodeByAsset();
    const nodeId = byAsset[asset.name] || (asset.dbtTestOn ? byAsset[asset.dbtTestOn] : null);
    if(nodeId) return dbtFocusedGraph(nodeId);
  }
  // Below here: objects the unified graph has no node for, which fall back to their own
  // connector's graph. Glue is an island - S3 prefix -> crawled table -> job -> view, with
  // no hop into the warehouse - so it lives here by nature rather than as a fallback.
  if(asset&&asset.service==="glue"){
    const activeId=GLUE_NODE_BY_ASSET[asset.name];
    // Databases and schemas are containers and are absent from the map.
    if(!activeId) return {topo:{},meta:{},colMaps:[],edges:[],empty:true};
    const topo={};
    Object.entries(GLUE_TOPO).forEach(([id,t])=>{ topo[id]={...t,active:id===activeId}; });
    return {topo,meta:GLUE_NODE_META,colMaps:GLUE_COL_MAPS,edges:GLUE_EDGES_DEF};
  }
  if(asset&&asset.service==="powerbi"){
    const activeId=POWERBI_NODE_BY_ASSET[asset.name];
    if(!activeId) return {topo:{},meta:{},colMaps:[],edges:[],empty:true};
    const topo={};
    Object.entries(POWERBI_TOPO).forEach(([id,t])=>{ topo[id]={...t,active:id===activeId}; });
    return {topo,meta:POWERBI_NODE_META,colMaps:POWERBI_COL_MAPS,edges:POWERBI_EDGES_DEF};
  }
  if(asset&&asset.service==="tableau"){
    const activeId=TABLEAU_NODE_BY_ASSET[asset.name];
    // No node means no lineage for this object type - say so rather than highlighting
    // an unrelated node, which is what the old type-keyed lookup did.
    if(!activeId) return {topo:{},meta:{},colMaps:[],edges:[],empty:true};
    const topo={};
    Object.entries(TABLEAU_TOPO).forEach(([id,t])=>{ topo[id]={...t,active:id===activeId}; });
    return {topo,meta:TABLEAU_NODE_META,colMaps:TABLEAU_COL_MAPS,edges:TABLEAU_EDGES_DEF};
  }
  // No connector has contributed lineage for this asset. Say that, rather than drawing
  // a chain that belongs to something else.
  return {topo:LINEAGE_TOPO,meta:LINEAGE_NODE_META,colMaps:LINEAGE_COL_MAPS,edges:LINEAGE_EDGES_DEF,empty:true};
}

// ─── AssetLineageFull ─────────────────────────────────────────────────────────
const AssetLineageFull=({asset})=>{
  // Asset-aware lineage graph (dbt transformation path vs. Tableau BI path vs. default).
  // Stable per asset. On a dbt graph the model layer can be collapsed out - see below.
  const _Graw=useMemo(()=>pickLineageGraph(asset),[asset]);
  const [showDbt,setShowDbt]=useState(true);
  // "all" spans every source that reported a hop; "source" keeps only this connector's own.
  const [lineageScope,setLineageScope]=useState("all");
  const _Gdbt=useMemo(()=>(_Graw.hasDbt&&!showDbt)?collapseDbtNodes(_Graw):_Graw,[_Graw,showDbt]);
  const _activeId=useMemo(()=>Object.entries(_Gdbt.topo||{}).find(([,t])=>t.active)?.[0]||null,[_Gdbt]);
  const _crossCount=useMemo(()=>crossSourceCount(_Gdbt,asset?.service),[_Gdbt,asset]);
  const _G=useMemo(()=>lineageScope==="source"
    ? inSourceOnly(_Gdbt,asset?.service,_activeId)
    : _Gdbt,[_Gdbt,lineageScope,asset,_activeId]);
  const LINEAGE_TOPO=_G.topo, LINEAGE_NODE_META=_G.meta, LINEAGE_COL_MAPS=_G.colMaps, LINEAGE_EDGES_DEF=_G.edges;
  const aName=asset?.name||"orders_fact";
  const [hiddenNodes,  setHiddenNodes] =useState(new Set());
  const [expandedCols, setExpandedCols]=useState(new Set());
  const [selectedId,   setSelectedId]  =useState(null);
  const [selectedCol,  setSelectedCol] =useState(null); // {nodeId, colName}
  const [nodeInfoTab,  setNodeInfoTab] =useState("overview"); // "overview"|"upstream"|"downstream"
  const [colInfoTab,   setColInfoTab]  =useState("overview"); // "overview"|"upstream"|"downstream"
  const [rf,           setRf]          =useState(null);

  // Reset tabs when selection changes
  useEffect(()=>{ setNodeInfoTab("overview"); },[selectedId]);
  useEffect(()=>{ setColInfoTab("overview"); },[selectedCol]);
  // Clear any node/column selection when the asset (and thus its lineage graph) changes,
  // so a node id from the previous graph can never linger in the info panel.
  useEffect(()=>{ setSelectedId(null); setSelectedCol(null); setHiddenNodes(new Set()); setExpandedCols(new Set()); },[aName]);
  // Same when the dbt layer is collapsed or restored - the node ids change under us, so any
  // held selection or hidden/expanded id would point at a node that no longer exists.
  useEffect(()=>{
    setSelectedId(null); setSelectedCol(null); setHiddenNodes(new Set()); setExpandedCols(new Set());
    setTimeout(()=>rf?.fitView({padding:0.15,duration:350}),60);
  },[showDbt]);

  const callbacks=useMemo(()=>({
    toggleExpand:(id)=>{
      setExpandedCols(p=>{const n=new Set(p);n.has(id)?n.delete(id):n.add(id);return n;});
      setTimeout(()=>rf?.fitView({padding:0.15,duration:350}),60);
    },
    toggleUpstream:(id,parents,open)=>{
      setHiddenNodes(p=>{
        const n=new Set(p);
        if(open){linAncestors(id,LINEAGE_TOPO).forEach(a=>n.add(a));}
        else{linAncestors(id,LINEAGE_TOPO).forEach(a=>n.delete(a));}
        return n;
      });
      setTimeout(()=>rf?.fitView({padding:0.15,duration:350}),60);
    },
    toggleDownstream:(id,children,open)=>{
      setHiddenNodes(p=>{
        const n=new Set(p);
        if(open){linDescendants(id,LINEAGE_TOPO).forEach(d=>n.add(d));}
        else{linDescendants(id,LINEAGE_TOPO).forEach(d=>n.delete(d));}
        return n;
      });
      setTimeout(()=>rf?.fitView({padding:0.15,duration:350}),60);
    },
    colClick:(nodeId,colName)=>{
      setSelectedId(null);
      setSelectedCol(p=>p?.nodeId===nodeId&&p?.colName===colName?null:{nodeId,colName});
    },
  }),[rf,LINEAGE_TOPO]);

  // Compute which columns to highlight across all nodes when a column is selected
  const colHighlights=useMemo(()=>{
    if(!selectedCol)return{};
    const paths=colPathEdges(selectedCol.nodeId,selectedCol.colName,LINEAGE_COL_MAPS);
    const r={};
    r[selectedCol.nodeId]=new Set([selectedCol.colName]);
    paths.forEach(p=>{
      if(!r[p.s])r[p.s]=new Set();r[p.s].add(p.sc);
      if(!r[p.t])r[p.t]=new Set();r[p.t].add(p.tc);
    });
    return r;
  },[selectedCol,LINEAGE_COL_MAPS]);

  const nodes=useMemo(()=>buildLinNodes(aName,hiddenNodes,expandedCols,colHighlights,callbacks,LINEAGE_TOPO,LINEAGE_NODE_META),[aName,hiddenNodes,expandedCols,colHighlights,callbacks,LINEAGE_TOPO,LINEAGE_NODE_META]);

  // When a column is selected: show dimmed node-edges + animated column-level edges
  const edges=useMemo(()=>{
    if(selectedCol){
      const base=buildLinEdges(hiddenNodes,LINEAGE_EDGES_DEF).map(e=>({...e,
        style:{stroke:"#e2e8f0",strokeWidth:1.2,strokeDasharray:"5 4"},
        markerEnd:{type:MarkerType.ArrowClosed,color:"#e2e8f0",width:10,height:10},
        // Column trace takes over the canvas — drop the edge-kind labels so they don't
        // compete with the highlighted column path.
        label:null,labelShowBg:false,
        animated:false,
      }));
      const colPaths=colPathEdges(selectedCol.nodeId,selectedCol.colName,LINEAGE_COL_MAPS);
      const colEdges=colPaths
        .filter(p=>!hiddenNodes.has(p.s)&&!hiddenNodes.has(p.t))
        .map(p=>({
          id:`ce-${p.s}.${p.sc}-${p.t}.${p.tc}`,
          source:p.s,target:p.t,
          sourceHandle:`so-${p.sc}`,targetHandle:`ti-${p.tc}`,
          type:"smoothstep",animated:true,
          markerEnd:{type:MarkerType.ArrowClosed,color:"#2563eb",width:12,height:12},
          style:{stroke:"#2563eb",strokeWidth:2},
        }));
      return[...base,...colEdges];
    }
    return buildLinEdges(hiddenNodes,LINEAGE_EDGES_DEF);
  },[hiddenNodes,selectedCol,LINEAGE_EDGES_DEF,LINEAGE_COL_MAPS]);

  const [rfNodes,setRfNodes,onNodesChange]=useNodesState(nodes);
  const [rfEdges,setRfEdges,onEdgesChange]=useEdgesState(edges);

  useEffect(()=>{setRfNodes(nodes);},[nodes]);
  useEffect(()=>{setRfEdges(edges);},[edges]);

  // Auto-expand nodes that are part of the selected column's path
  useEffect(()=>{
    if(!selectedCol)return;
    const paths=colPathEdges(selectedCol.nodeId,selectedCol.colName,LINEAGE_COL_MAPS);
    const toExpand=new Set([selectedCol.nodeId]);
    paths.forEach(p=>{toExpand.add(p.s);toExpand.add(p.t);});
    setExpandedCols(p=>{const n=new Set(p);toExpand.forEach(id=>n.add(id));return n;});
    setTimeout(()=>rf?.fitView({padding:0.15,duration:350}),80);
  },[selectedCol,LINEAGE_COL_MAPS]);

  const selMeta=selectedId?LINEAGE_NODE_META[selectedId]:null;
  const selLabel=selectedId?(LINEAGE_TOPO[selectedId]?.active?aName:LINEAGE_TOPO[selectedId]?.label):null;

  // cert colour helper (hardcoded, no T)
  const certC=(c)=>c==="Approved"?"#16a34a":c==="In Review"?"#d97706":"#6b7280";
  const qualC=(q)=>q>=90?"#16a34a":q>=75?"#d97706":"#e11d48";

  // Nothing ingested for this asset - an honest empty state beats an invented graph.
  if(_G.empty||Object.keys(LINEAGE_TOPO).length===0){
    const svc=asset?.connectionLabel||asset?.service||"this source";
    return (
      <div className="fadeIn" style={{display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",
        gap:12,height:340,background:T.bgSurface,border:`1px dashed ${T.border}`,borderRadius:10,padding:32,textAlign:"center"}}>
        <div style={{width:44,height:44,borderRadius:11,background:T.bgElevated,border:`1px solid ${T.border}`,
          display:"flex",alignItems:"center",justifyContent:"center",color:T.textMuted}}>{Ic.lineage(22)}</div>
        <div style={{fontSize:14.5,fontWeight:600,color:T.text}}>No lineage ingested for this asset</div>
        <div style={{fontSize:12.5,color:T.textSub,lineHeight:1.65,maxWidth:460}}>
          EDG draws lineage only from what a connector actually reports &mdash; a dbt manifest,
          Tableau&rsquo;s metadata API, or warehouse query-log parsing. Nothing has been ingested for{" "}
          <span style={{fontFamily:"'Geist Mono',monospace",color:T.text}}>{svc}</span> yet, so there is
          nothing to draw. Rather than show a placeholder chain, this stays empty until a run populates it.
        </div>
        {asset?.archived&&<div style={{fontSize:12,color:T.textMuted,fontStyle:"italic"}}>
          This asset is archived &mdash; it was deleted at source, so its lineage is no longer refreshed.
        </div>}
      </div>
    );
  }

  return(
    <div className="fadeIn" style={{display:"flex",flexDirection:"column",gap:0,height:520}}>
      {/* Toolbar */}
      <div style={{display:"flex",alignItems:"center",gap:12,padding:"10px 16px",
        background:"#f8fafc",border:"1px solid #e2e8f0",borderRadius:"10px 10px 0 0",
        borderBottom:"none",flexShrink:0,flexWrap:"wrap"}}>
        {/* Legend */}
        <div style={{display:"flex",gap:10,flexWrap:"wrap",flex:1}}>
          {/* Legend follows the nodes actually on the canvas, not the whole meta map — with the
              dbt layer collapsed, a "dbt Model" swatch would name a type nothing is drawn for. */}
          {[...new Set(Object.keys(LINEAGE_TOPO).map(id=>LINEAGE_NODE_META[id]?.assetType).filter(Boolean))].map(type=>(
            <span key={type} style={{display:"inline-flex",alignItems:"center",gap:5,fontSize:11,color:"#64748b"}}>
              <span style={{width:8,height:8,borderRadius:2,background:LINEAGE_TYPE_COLOR[type]||"#94a3b8",display:"inline-block"}}/>
              {type}
            </span>
          ))}
        </div>
        {/* Hint */}
        <span style={{fontSize:10.5,color:"#94a3b8",display:"flex",alignItems:"center",gap:4}}>
          <span style={{width:14,height:14,borderRadius:3,background:"#fff",border:"1.5px solid #3b82f6",display:"inline-flex",alignItems:"center",justifyContent:"center",fontSize:10,color:"#3b82f6",fontWeight:700,lineHeight:1}}>+</span>
          upstream&nbsp;
          <span style={{width:14,height:14,borderRadius:3,background:"#fff",border:"1.5px solid #8b5cf6",display:"inline-flex",alignItems:"center",justifyContent:"center",fontSize:10,color:"#8b5cf6",fontWeight:700,lineHeight:1}}>+</span>
          downstream&nbsp;·&nbsp;click node for details
        </span>
        {/* Scope. Only offered when the graph actually leaves this source — a control that
            cannot change anything is worse than no control. */}
        {_crossCount>0&&(
          <div style={{display:"inline-flex",border:"1px solid #e2e8f0",borderRadius:6,overflow:"hidden"}}>
            {[{k:"all",l:`All sources (+${_crossCount})`,t:`Include the ${_crossCount} hop(s) another source reported`},
              {k:"source",l:"This source",t:"Only what this connector reported"}].map(o=>(
              <button key={o.k} onClick={()=>setLineageScope(o.k)} title={o.t}
                style={{padding:"4px 10px",background:lineageScope===o.k?"rgba(99,102,241,.1)":"#fff",
                  border:"none",borderRight:o.k==="all"?"1px solid #e2e8f0":"none",
                  color:lineageScope===o.k?"#4338ca":"#64748b",
                  fontSize:11.5,fontWeight:lineageScope===o.k?600:400,cursor:"pointer",
                  fontFamily:"inherit",whiteSpace:"nowrap"}}>
                {o.l}
              </button>
            ))}
          </div>
        )}
        {/* dbt layer toggle — read the graph as engineering flow (every model drawn) or
            as business flow (models collapsed, source wired straight to target). */}
        {_Graw.hasDbt&&(
          <button onClick={()=>setShowDbt(v=>!v)} title={showDbt?"Collapse the dbt model layer out of the graph":"Draw every dbt model in the graph"}
            style={{padding:"4px 10px",borderRadius:6,background:showDbt?"rgba(255,105,75,.1)":"#fff",
              border:`1px solid ${showDbt?"#ff694b":"#e2e8f0"}`,color:showDbt?"#c2410c":"#64748b",
              fontSize:11.5,fontWeight:600,cursor:"pointer",fontFamily:"inherit",display:"inline-flex",alignItems:"center",gap:6,whiteSpace:"nowrap"}}>
            <span style={{width:8,height:8,borderRadius:2,background:showDbt?"#ff694b":"#cbd5e1",display:"inline-block"}}/>
            Show dbt models
          </button>
        )}
        <button onClick={()=>rf?.fitView({padding:0.15,duration:400})}
          style={{padding:"4px 12px",borderRadius:6,background:"#fff",border:"1px solid #e2e8f0",color:"#64748b",fontSize:11.5,cursor:"pointer",fontFamily:"inherit"}}>
          Fit
        </button>
      </div>

      {/* Canvas + info panel row */}
      <div style={{display:"flex",flex:1,minHeight:0,border:"1px solid #e2e8f0",borderRadius:"0 0 10px 10px",overflow:"hidden"}}>
        {/* ReactFlow */}
        <div style={{flex:1,minWidth:0,position:"relative",background:"#f8fafc"}}>
          <ReactFlow
            nodes={rfNodes} edges={rfEdges}
            onNodesChange={onNodesChange} onEdgesChange={onEdgesChange}
            nodeTypes={LIN_NODE_TYPES}
            onInit={inst=>{setRf(inst);inst.fitView({padding:0.18});}}
            onNodeClick={(_e,node)=>{setSelectedCol(null);setSelectedId(p=>p===node.id?null:node.id);}}
            minZoom={0.15} maxZoom={3}
            proOptions={{hideAttribution:true}}
            colorMode="light"
            style={{background:"#f8fafc"}}
          >
            <Background color="#cbd5e1" gap={22} size={1.2} variant="dots"/>
            <Controls showInteractive={false}
              style={{background:"#fff",border:"1px solid #e2e8f0",borderRadius:8,overflow:"hidden"}}/>
            <MiniMap nodeColor={n=>LINEAGE_TYPE_COLOR[n.data?.assetType]||"#94a3b8"}
              style={{background:"#f1f5f9",border:"1px solid #e2e8f0",borderRadius:8}}
              maskColor="rgba(248,250,252,0.7)" position="bottom-right"/>
          </ReactFlow>
        </div>

        {/* Info panel — column lineage OR node info (tabbed) */}
        {(selectedCol||(selectedId&&selMeta))&&(()=>{
          const CMETA_L={"Draft":{color:"#6b7280",bg:"rgba(107,114,128,.1)",border:"rgba(107,114,128,.25)"},"In Review":{color:"#d97706",bg:"rgba(217,119,6,.12)",border:"rgba(217,119,6,.3)"},"Approved":{color:"#16a34a",bg:"rgba(22,163,74,.12)",border:"rgba(22,163,74,.3)"}};
          const TAG_C_L={PII:{bg:"rgba(225,29,72,.1)",color:"#e11d48",border:"rgba(225,29,72,.25)"},finance:{bg:"rgba(37,99,235,.08)",color:"#2563eb",border:"rgba(37,99,235,.2)"},KPI:{bg:"rgba(22,163,74,.08)",color:"#16a34a",border:"rgba(22,163,74,.2)"},etl:{bg:"rgba(245,158,11,.08)",color:"#d97706",border:"rgba(245,158,11,.2)"},model:{bg:"rgba(99,102,241,.08)",color:"#6366f1",border:"rgba(99,102,241,.2)"}};
          const SLabel=({children})=><div style={{fontSize:10,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.08em",marginBottom:8}}>{children}</div>;

          // ── COLUMN LINEAGE PANEL ──────────────────────────────────────────────
          if(selectedCol){
            const cMeta=LINEAGE_NODE_META[selectedCol.nodeId];
            const colDef=cMeta?.cols.find(c=>c.n===selectedCol.colName);

            // Collect all upstream column hops (BFS)
            const gatherUpstream=(nid,cname)=>{
              const result=[];const visited=new Set();
              const queue=[[nid,cname,0]];
              while(queue.length){
                const[cn,cc,depth]=queue.shift();
                LINEAGE_COL_MAPS.forEach(m=>{
                  if(m.t===cn)m.cols.forEach(c=>{
                    if(c.tc===cc){
                      const key=`${m.s}.${c.sc}`;
                      if(!visited.has(key)){visited.add(key);result.push({nodeId:m.s,colName:c.sc,depth:depth+1});queue.push([m.s,c.sc,depth+1]);}
                    }
                  });
                });
              }
              return result;
            };
            // Collect all downstream column hops (BFS)
            const gatherDownstream=(nid,cname)=>{
              const result=[];const visited=new Set();
              const queue=[[nid,cname,0]];
              while(queue.length){
                const[cn,cc,depth]=queue.shift();
                LINEAGE_COL_MAPS.forEach(m=>{
                  if(m.s===cn)m.cols.forEach(c=>{
                    if(c.sc===cc){
                      const key=`${m.t}.${c.tc}`;
                      if(!visited.has(key)){visited.add(key);result.push({nodeId:m.t,colName:c.tc,depth:depth+1});queue.push([m.t,c.tc,depth+1]);}
                    }
                  });
                });
              }
              return result;
            };

            const upstreamCols=gatherUpstream(selectedCol.nodeId,selectedCol.colName);
            const downstreamCols=gatherDownstream(selectedCol.nodeId,selectedCol.colName);

            // Column step card (shared by overview path + up/down tabs)
            const ColStepCard=({nodeId,colName,isCurrent,badge,badgeColor})=>{
              const nm=LINEAGE_NODE_META[nodeId];
              const nt=LINEAGE_TOPO[nodeId];
              const nl=nt?.active?aName:nt?.label;
              const ct=nm?.cols.find(c=>c.n===colName)?.t;
              return(
                <div style={{position:"relative",padding:"11px 13px",background:isCurrent?T.accentDim:T.bgElevated,border:`1.5px solid ${isCurrent?T.accent:T.border}`,borderRadius:10}}>
                  {badge&&<div style={{position:"absolute",top:-8,left:10,fontSize:8.5,fontWeight:700,padding:"0 6px",background:T.bgSurface,letterSpacing:"0.06em",textTransform:"uppercase",color:badgeColor||T.accent}}>{badge}</div>}
                  <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:8}}>
                    <ServiceIcon service={nm?.service} size={20}/>
                    <div style={{flex:1,minWidth:0}}>
                      <div style={{display:"flex",alignItems:"center",gap:5,marginBottom:2}}>
                        <TypeBadge type={nm?.assetType}/>
                        {nt?.active&&<span style={{fontSize:8,fontWeight:700,color:"#ee2424",background:"rgba(238,36,36,.1)",padding:"1px 5px",borderRadius:3}}>CURRENT</span>}
                      </div>
                      <div style={{fontSize:11,fontFamily:"'Geist Mono',monospace",color:isCurrent?T.accent:T.text,fontWeight:600,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{nl}</div>
                    </div>
                  </div>
                  <div style={{display:"flex",alignItems:"center",gap:6,padding:"5px 9px",background:T.bgSurface,borderRadius:6,border:`1px solid ${isCurrent?T.accent+"55":T.border}`}}>
                    <span style={{width:5,height:5,borderRadius:"50%",background:isCurrent?"#2563eb":"#94a3b8",flexShrink:0}}/>
                    <span style={{fontFamily:"'Geist Mono',monospace",fontSize:11,fontWeight:isCurrent?700:500,color:isCurrent?T.accent:T.text,flex:1,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{colName}</span>
                    {ct&&<span style={{fontSize:9,padding:"1px 5px",borderRadius:3,background:`${T.blue}15`,color:T.blue,border:`1px solid ${T.blue}20`,fontFamily:"'Geist Mono',monospace",flexShrink:0}}>{ct}</span>}
                  </div>
                </div>
              );
            };

            // Arrow divider
            const Arrow=()=>(
              <div style={{display:"flex",justifyContent:"center",alignItems:"center",height:22,position:"relative"}}>
                <div style={{position:"absolute",top:0,bottom:0,left:"50%",width:1,background:T.accent+"35"}}/>
                <div style={{background:T.bgSurface,zIndex:1,padding:"0 4px",color:T.accent,fontSize:13,lineHeight:1}}>↓</div>
              </div>
            );

            return(
              <div className="slideInRight" style={{width:300,flexShrink:0,borderLeft:`1px solid ${T.border}`,background:T.bgSurface,display:"flex",flexDirection:"column",overflow:"hidden"}}>
                {/* Header + tabs */}
                <div style={{padding:"14px 16px 0",borderBottom:`1px solid ${T.border}`,flexShrink:0}}>
                  <div style={{display:"flex",alignItems:"flex-start",gap:10,marginBottom:10}}>
                    <div style={{flex:1,minWidth:0}}>
                      <div style={{fontSize:9,fontWeight:700,color:T.accent,textTransform:"uppercase",letterSpacing:"0.09em",marginBottom:4,display:"flex",alignItems:"center",gap:4}}>
                        <svg width="10" height="10" viewBox="0 0 14 14" fill="none"><path d="M2 7h10M9 4l3 3-3 3" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"/></svg>
                        Column Lineage
                      </div>
                      <div style={{fontSize:15,fontWeight:700,color:T.text,fontFamily:"'Geist Mono',monospace"}}>{selectedCol.colName}</div>
                      <div style={{display:"flex",alignItems:"center",gap:6,marginTop:5,flexWrap:"wrap"}}>
                        <TypeBadge type={cMeta?.assetType}/>
                        <span style={{fontSize:10,padding:"1px 7px",borderRadius:4,background:`${T.blue}15`,color:T.blue,border:`1px solid ${T.blue}25`,fontFamily:"'Geist Mono',monospace",fontWeight:600}}>{colDef?.t||"—"}</span>
                      </div>
                    </div>
                    <button onClick={()=>setSelectedCol(null)} style={{width:26,height:26,borderRadius:7,background:T.bgHover,border:`1px solid ${T.border}`,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",color:T.textMuted,flexShrink:0,padding:0}}>{Ic.x(10)}</button>
                  </div>
                  {/* Tabs */}
                  <div style={{display:"flex"}}>
                    {[{k:"overview",l:"Overview"},{k:"upstream",l:`Upstream (${upstreamCols.length})`},{k:"downstream",l:`Downstream (${downstreamCols.length})`}].map(tab=>(
                      <button key={tab.k} onClick={()=>setColInfoTab(tab.k)}
                        style={{padding:"7px 10px",background:"none",border:"none",borderBottom:`2px solid ${colInfoTab===tab.k?T.accent:"transparent"}`,
                          color:colInfoTab===tab.k?T.text:T.textMuted,fontSize:11.5,fontWeight:colInfoTab===tab.k?600:400,
                          cursor:"pointer",whiteSpace:"nowrap",transition:"all .12s"}}>
                        {tab.l}
                      </button>
                    ))}
                  </div>
                </div>

                {/* Tab body */}
                <div style={{flex:1,overflowY:"auto",padding:"16px"}}>

                  {/* ── OVERVIEW: column metadata (mirrors Schema tab column panel) ── */}
                  {colInfoTab==="overview"&&(()=>{
                    const prof=COL_PROFILES[selectedCol.colName]||null;
                    const ava=name=>(name||"").split(".").map(s=>s[0]?.toUpperCase()||"").join("");
                    const cm2=CMETA_L[cMeta?.cert]||CMETA_L["Draft"];
                    const StatBar=({pct,color})=>(
                      <div style={{height:4,background:"#f1f5f9",borderRadius:2,overflow:"hidden",marginTop:4}}>
                        <div style={{width:`${Math.min(100,pct||0)}%`,height:"100%",background:color,borderRadius:2}}/>
                      </div>
                    );
                    return(
                      <div style={{display:"flex",flexDirection:"column",gap:14}}>

                        {/* Description */}
                        <div>
                          <div style={{fontSize:10,fontWeight:700,color:"#94a3b8",textTransform:"uppercase",letterSpacing:"0.07em",marginBottom:6}}>Description</div>
                          <p style={{fontSize:12,color:"#64748b",fontStyle:"italic",margin:0}}>No description provided.</p>
                        </div>

                        {/* Details */}
                        <div>
                          <div style={{fontSize:10,fontWeight:700,color:"#94a3b8",textTransform:"uppercase",letterSpacing:"0.07em",marginBottom:6}}>Details</div>
                          <div style={{background:"#f8fafc",borderRadius:8,border:"1px solid #e2e8f0",overflow:"hidden"}}>
                            {[
                              {l:"Data Type",   v:<span style={{fontFamily:"'Geist Mono',monospace",fontSize:12,color:"#2563eb",fontWeight:600}}>{colDef?.t||"—"}</span>},
                              {l:"Nullable",    v:<span style={{fontSize:11,color:"#64748b",fontWeight:600}}>—</span>},
                              {l:"Primary Key", v:<span style={{fontSize:11,color:"#64748b",fontWeight:600}}>—</span>},
                            ].map((r,i)=>(
                              <div key={r.l} style={{display:"flex",alignItems:"center",justifyContent:"space-between",padding:"8px 12px",borderBottom:i<2?"1px solid #e2e8f0":"none"}}>
                                <span style={{fontSize:11.5,color:"#94a3b8"}}>{r.l}</span>{r.v}
                              </div>
                            ))}
                          </div>
                        </div>

                        {/* Stats */}
                        {prof&&(
                          <div>
                            <div style={{fontSize:10,fontWeight:700,color:"#94a3b8",textTransform:"uppercase",letterSpacing:"0.07em",marginBottom:8}}>Stats</div>
                            <div style={{background:"#f8fafc",borderRadius:8,border:"1px solid #e2e8f0",overflow:"hidden"}}>
                              <div style={{padding:"9px 12px",borderBottom:"1px solid #e2e8f0"}}>
                                <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:5}}>
                                  <span style={{fontSize:11,color:"#94a3b8"}}>Null %</span>
                                  <div style={{display:"flex",alignItems:"baseline",gap:5}}>
                                    <span style={{fontSize:11,fontWeight:700,color:prof.nullPct>5?"#e11d48":"#16a34a"}}>{prof.nullPct}%</span>
                                    {prof.nullCount&&prof.nullCount!=="0"&&<span style={{fontSize:9.5,color:"#94a3b8"}}>{prof.nullCount} rows</span>}
                                  </div>
                                </div>
                                <StatBar pct={prof.nullPct} color={prof.nullPct>5?"#e11d48":"#16a34a"}/>
                              </div>
                              <div style={{padding:"9px 12px",borderBottom:(prof.dataType==="numeric"&&prof.min!=null)||prof.topValues||prof.samples?"1px solid #e2e8f0":"none"}}>
                                <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:5}}>
                                  <span style={{fontSize:11,color:"#94a3b8"}}>Distinct %</span>
                                  <div style={{display:"flex",alignItems:"baseline",gap:5}}>
                                    <span style={{fontSize:11,fontWeight:700,color:"#2563eb"}}>{prof.distinctPct}%</span>
                                    {prof.distinctCount&&<span style={{fontSize:9.5,color:"#94a3b8"}}>{prof.distinctCount} values</span>}
                                  </div>
                                </div>
                                <StatBar pct={prof.distinctPct} color="#2563eb"/>
                              </div>
                              {prof.dataType==="numeric"&&prof.min!=null&&(
                                <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",borderBottom:prof.topValues?"1px solid #e2e8f0":"none"}}>
                                  {[{l:"Min",v:prof.min},{l:"Max",v:prof.max},{l:"Avg",v:prof.avg||"—"}].map((s,i)=>(
                                    <div key={s.l} style={{padding:"9px 10px",borderRight:i<2?"1px solid #e2e8f0":"none",textAlign:"center"}}>
                                      <div style={{fontSize:9,color:"#94a3b8",textTransform:"uppercase",letterSpacing:"0.06em",marginBottom:3}}>{s.l}</div>
                                      <div style={{fontSize:11,fontFamily:"'Geist Mono',monospace",color:"#1e293b",fontWeight:600}}>{s.v}</div>
                                    </div>
                                  ))}
                                </div>
                              )}
                              {prof.topValues&&(
                                <div style={{padding:"9px 12px",borderBottom:prof.samples?"1px solid #e2e8f0":"none"}}>
                                  <div style={{fontSize:9,color:"#94a3b8",textTransform:"uppercase",letterSpacing:"0.06em",marginBottom:8}}>Top Values</div>
                                  {prof.topValues.map((v,i)=>{
                                    const pct=parseFloat(v.match(/\((\d+)/)?.[1]||0);
                                    const label=v.replace(/\s*\(.*\)/,"");
                                    return(
                                      <div key={i} style={{marginBottom:i<prof.topValues.length-1?7:0}}>
                                        <div style={{display:"flex",justifyContent:"space-between",marginBottom:3}}>
                                          <span style={{fontSize:10.5,color:"#475569",fontWeight:500}}>{label}</span>
                                          <span style={{fontSize:10,color:"#94a3b8"}}>{pct}%</span>
                                        </div>
                                        <div style={{height:3,background:"#f1f5f9",borderRadius:2,overflow:"hidden"}}>
                                          <div style={{width:`${pct}%`,height:"100%",background:"#8b5cf6",borderRadius:2}}/>
                                        </div>
                                      </div>
                                    );
                                  })}
                                </div>
                              )}
                              {prof.samples&&(
                                <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",borderBottom:"1px solid #e2e8f0"}}>
                                  {[{l:"Min Len",v:prof.minLen},{l:"Max Len",v:prof.maxLen},{l:"Avg Len",v:prof.avgLen}].map((s,i)=>(
                                    <div key={s.l} style={{padding:"9px 10px",borderRight:i<2?"1px solid #e2e8f0":"none",textAlign:"center"}}>
                                      <div style={{fontSize:9,color:"#94a3b8",textTransform:"uppercase",letterSpacing:"0.06em",marginBottom:3}}>{s.l}</div>
                                      <div style={{fontSize:11,fontFamily:"'Geist Mono',monospace",color:"#1e293b",fontWeight:600}}>{s.v}</div>
                                    </div>
                                  ))}
                                </div>
                              )}
                              {prof.samples&&(
                                <div style={{padding:"9px 12px"}}>
                                  <div style={{fontSize:9,color:"#94a3b8",textTransform:"uppercase",letterSpacing:"0.06em",marginBottom:8}}>Sample Values</div>
                                  <div style={{display:"flex",flexWrap:"wrap",gap:5}}>
                                    {prof.samples.map((s,i)=>(
                                      <span key={i} style={{fontSize:10.5,padding:"3px 9px",borderRadius:5,background:"#f1f5f9",border:"1px solid #e2e8f0",color:"#475569",fontFamily:"'Geist Mono',monospace"}}>{s}</span>
                                    ))}
                                  </div>
                                </div>
                              )}
                            </div>
                          </div>
                        )}

                        {/* Status — inherited from parent node */}
                        <div>
                          <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:6}}>
                            <div style={{fontSize:10,fontWeight:700,color:"#94a3b8",textTransform:"uppercase",letterSpacing:"0.07em"}}>Status</div>
                            <span style={{fontSize:9.5,color:"#94a3b8",fontStyle:"italic"}}>Inherited</span>
                          </div>
                          <div style={{display:"inline-flex",alignItems:"center",gap:6,padding:"4px 12px 4px 9px",borderRadius:5,background:cm2.bg,borderTop:`1px solid ${cm2.border}`,borderRight:`1px solid ${cm2.border}`,borderBottom:`1px solid ${cm2.border}`,borderLeft:`3px solid ${cm2.color}`}}>
                            <span style={{fontSize:12,color:cm2.color,fontWeight:600}}>{cMeta?.cert||"Draft"}</span>
                          </div>
                        </div>

                        {/* Domain — inherited */}
                        {cMeta?.domain&&(
                          <div>
                            <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:6}}>
                              <div style={{fontSize:10,fontWeight:700,color:"#94a3b8",textTransform:"uppercase",letterSpacing:"0.07em"}}>Domain</div>
                              <span style={{fontSize:9.5,color:"#94a3b8",fontStyle:"italic"}}>Inherited</span>
                            </div>
                            <div style={{display:"inline-flex",alignItems:"center",padding:"4px 12px 4px 9px",borderRadius:5,background:"rgba(238,36,36,.06)",borderTop:"1px solid rgba(238,36,36,.15)",borderRight:"1px solid rgba(238,36,36,.15)",borderBottom:"1px solid rgba(238,36,36,.15)",borderLeft:"3px solid #ee2424"}}>
                              <span style={{fontSize:12,color:"#ee2424",fontWeight:600}}>{cMeta.domain}</span>
                            </div>
                          </div>
                        )}

                        {/* Owner — inherited */}
                        {cMeta?.owner&&(
                          <div>
                            <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:6}}>
                              <div style={{fontSize:10,fontWeight:700,color:"#94a3b8",textTransform:"uppercase",letterSpacing:"0.07em"}}>Owner</div>
                              <span style={{fontSize:9.5,color:"#94a3b8",fontStyle:"italic"}}>Inherited</span>
                            </div>
                            <div style={{display:"inline-flex",alignItems:"center",gap:5,padding:"3px 10px 3px 6px",borderRadius:5,background:"rgba(238,36,36,.06)",borderTop:"1px solid rgba(238,36,36,.15)",borderRight:"1px solid rgba(238,36,36,.15)",borderBottom:"1px solid rgba(238,36,36,.15)",borderLeft:"3px solid #ee2424"}}>
                              <div style={{width:18,height:18,borderRadius:3,background:"rgba(238,36,36,.12)",display:"flex",alignItems:"center",justifyContent:"center",fontSize:7,fontWeight:700,color:"#ee2424",flexShrink:0}}>{ava(cMeta.owner)}</div>
                              <span style={{fontSize:12,color:"#ee2424",fontWeight:500}}>{cMeta.owner}</span>
                            </div>
                          </div>
                        )}

                        {/* Steward — inherited */}
                        {cMeta?.steward&&(
                          <div>
                            <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:6}}>
                              <div style={{fontSize:10,fontWeight:700,color:"#94a3b8",textTransform:"uppercase",letterSpacing:"0.07em"}}>Steward</div>
                              <span style={{fontSize:9.5,color:"#94a3b8",fontStyle:"italic"}}>Inherited</span>
                            </div>
                            <div style={{display:"inline-flex",alignItems:"center",gap:5,padding:"3px 10px 3px 6px",borderRadius:5,background:"rgba(217,119,6,.08)",borderTop:"1px solid rgba(217,119,6,.2)",borderRight:"1px solid rgba(217,119,6,.2)",borderBottom:"1px solid rgba(217,119,6,.2)",borderLeft:"3px solid #d97706"}}>
                              <div style={{width:18,height:18,borderRadius:"50%",background:"rgba(217,119,6,.15)",display:"flex",alignItems:"center",justifyContent:"center",fontSize:7,fontWeight:700,color:"#d97706",flexShrink:0}}>{ava(cMeta.steward)}</div>
                              <span style={{fontSize:12,color:"#d97706",fontWeight:500}}>{cMeta.steward}</span>
                            </div>
                          </div>
                        )}

                        {/* Tags */}
                        {cMeta?.tags&&cMeta.tags.length>0&&(
                          <div>
                            <div style={{fontSize:10,fontWeight:700,color:"#94a3b8",textTransform:"uppercase",letterSpacing:"0.07em",marginBottom:8}}>Tags</div>
                            <div style={{display:"flex",flexWrap:"wrap",gap:5}}>
                              {cMeta.tags.map(t=>{const c=TAG_C_L[t]||{bg:"#f1f5f9",color:"#64748b",border:"#e2e8f0"};return(
                                <span key={t} style={{display:"inline-flex",alignItems:"center",fontSize:11.5,padding:"4px 10px 4px 9px",borderRadius:5,background:c.bg,borderTop:`1px solid ${c.border}`,borderRight:`1px solid ${c.border}`,borderBottom:`1px solid ${c.border}`,borderLeft:`3px solid ${c.color}`,color:c.color,fontWeight:600}}>{t}</span>
                              );})}
                            </div>
                          </div>
                        )}

                      </div>
                    );
                  })()}

                  {/* ── UPSTREAM tab ── */}
                  {colInfoTab==="upstream"&&(
                    upstreamCols.length===0?(
                      <div style={{textAlign:"center",padding:"32px 0"}}>
                        <div style={{fontSize:22,marginBottom:8,color:T.textMuted}}>◁</div>
                        <div style={{fontSize:12,color:T.textMuted,lineHeight:1.6}}>No upstream columns<br/><span style={{fontFamily:"'Geist Mono',monospace",color:T.textSub}}>{selectedCol.colName}</span> is a source</div>
                      </div>
                    ):(
                      <>
                        <div style={{fontSize:10,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.08em",marginBottom:14}}>Upstream Columns</div>
                        {upstreamCols.map((col,i)=>(
                          <React.Fragment key={`up-${col.nodeId}.${col.colName}.${i}`}>
                            <ColStepCard nodeId={col.nodeId} colName={col.colName} isCurrent={false}
                              badge={col.depth===1?"Direct":"Transitive"}
                              badgeColor={col.depth===1?T.accent:"#8b5cf6"}/>
                            {i<upstreamCols.length-1&&<div style={{height:8}}/>}
                          </React.Fragment>
                        ))}
                      </>
                    )
                  )}

                  {/* ── DOWNSTREAM tab ── */}
                  {colInfoTab==="downstream"&&(
                    downstreamCols.length===0?(
                      <div style={{textAlign:"center",padding:"32px 0"}}>
                        <div style={{fontSize:22,marginBottom:8,color:T.textMuted}}>▷</div>
                        <div style={{fontSize:12,color:T.textMuted,lineHeight:1.6}}>No downstream columns<br/><span style={{fontFamily:"'Geist Mono',monospace",color:T.textSub}}>{selectedCol.colName}</span> is a sink</div>
                      </div>
                    ):(
                      <>
                        <div style={{fontSize:10,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.08em",marginBottom:14}}>Downstream Columns</div>
                        {downstreamCols.map((col,i)=>(
                          <React.Fragment key={`dn-${col.nodeId}.${col.colName}.${i}`}>
                            <ColStepCard nodeId={col.nodeId} colName={col.colName} isCurrent={false}
                              badge={col.depth===1?"Direct":"Transitive"}
                              badgeColor={col.depth===1?T.accent:"#8b5cf6"}/>
                            {i<downstreamCols.length-1&&<div style={{height:8}}/>}
                          </React.Fragment>
                        ))}
                      </>
                    )
                  )}

                </div>
              </div>
            );
          }

          // ── NODE INFO PANEL (tabbed) ──────────────────────────────────────────
          const cm=CMETA_L[selMeta.cert]||CMETA_L["Draft"];
          const tagC=t=>TAG_C_L[t]||{bg:T.bgElevated,color:T.textSub,border:T.border};
          const directUp=LINEAGE_TOPO[selectedId]?.upstream||[];
          const directDown=LINEAGE_TOPO[selectedId]?.downstream||[];
          const allUp=[...linAncestors(selectedId,LINEAGE_TOPO)];
          const allDown=[...linDescendants(selectedId,LINEAGE_TOPO)];
          const upOrdered=[...directUp,...allUp.filter(id=>!directUp.includes(id))];
          const downOrdered=[...directDown,...allDown.filter(id=>!directDown.includes(id))];

          const LineageNodeCard=({nodeId,direct})=>{
            const nm=LINEAGE_NODE_META[nodeId];
            const nt=LINEAGE_TOPO[nodeId];
            const nl=nt?.active?aName:nt?.label;
            return(
              <div style={{display:"flex",alignItems:"center",gap:10,padding:"11px 13px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:9,marginBottom:8}}>
                <ServiceIcon service={nm?.service} size={24}/>
                <div style={{flex:1,minWidth:0}}>
                  <div style={{display:"flex",alignItems:"center",gap:5,marginBottom:3}}>
                    <TypeBadge type={nm?.assetType}/>
                    {direct&&<span style={{fontSize:8.5,fontWeight:700,padding:"1px 5px",borderRadius:3,background:T.accentDim,color:T.accent,letterSpacing:"0.04em"}}>DIRECT</span>}
                  </div>
                  <div style={{fontSize:12,fontFamily:"'Geist Mono',monospace",fontWeight:600,color:T.text,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{nl}</div>
                  <div style={{fontSize:10,color:T.textMuted,marginTop:1}}>{nm?.service}</div>
                </div>
                <div style={{textAlign:"right",flexShrink:0}}>
                  <div style={{fontSize:14,fontWeight:700,fontFamily:"'Geist Mono',monospace",color:qualC(nm?.quality||0)}}>{nm?.quality}</div>
                  <div style={{width:30,height:3,background:T.border,borderRadius:2,overflow:"hidden",marginTop:3}}>
                    <div style={{width:`${nm?.quality||0}%`,height:"100%",background:qualC(nm?.quality||0)}}/>
                  </div>
                </div>
              </div>
            );
          };

          return(
            <div className="slideInRight" style={{width:300,flexShrink:0,borderLeft:`1px solid ${T.border}`,background:T.bgSurface,display:"flex",flexDirection:"column",overflow:"hidden"}}>
              {/* Header + tab bar */}
              <div style={{padding:"14px 16px 0",borderBottom:`1px solid ${T.border}`,flexShrink:0}}>
                <div style={{display:"flex",alignItems:"flex-start",gap:10,marginBottom:12}}>
                  <div style={{flex:1,minWidth:0}}>
                    <div style={{display:"flex",alignItems:"center",gap:7,marginBottom:5,flexWrap:"wrap"}}>
                      <TypeBadge type={selMeta.assetType}/>
                      {LINEAGE_TOPO[selectedId].active&&<span style={{fontSize:9,fontWeight:700,color:"#ee2424",background:"rgba(238,36,36,0.1)",padding:"2px 6px",borderRadius:4}}>CURRENT</span>}
                    </div>
                    <div style={{fontSize:13,fontWeight:700,color:T.text,fontFamily:"'Geist Mono',monospace",wordBreak:"break-all",lineHeight:1.35}}>{selLabel}</div>
                    <div style={{fontSize:10.5,color:T.textMuted,marginTop:2,fontFamily:"'Geist Mono',monospace"}}>{selMeta.db}</div>
                  </div>
                  <button onClick={()=>setSelectedId(null)} style={{width:26,height:26,borderRadius:7,background:T.bgHover,border:`1px solid ${T.border}`,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",color:T.textMuted,flexShrink:0,padding:0}}>{Ic.x(10)}</button>
                </div>
                {/* Tabs */}
                <div style={{display:"flex"}}>
                  {[{k:"overview",l:"Overview"},{k:"upstream",l:`Upstream (${upOrdered.length})`},{k:"downstream",l:`Downstream (${downOrdered.length})`}].map(tab=>(
                    <button key={tab.k} onClick={()=>setNodeInfoTab(tab.k)}
                      style={{padding:"7px 10px",background:"none",border:"none",borderBottom:`2px solid ${nodeInfoTab===tab.k?T.accent:"transparent"}`,
                        color:nodeInfoTab===tab.k?T.text:T.textMuted,fontSize:11.5,fontWeight:nodeInfoTab===tab.k?600:400,
                        cursor:"pointer",whiteSpace:"nowrap",transition:"all .12s"}}>
                      {tab.l}
                    </button>
                  ))}
                </div>
              </div>

              {/* Tab content */}
              <div style={{flex:1,overflowY:"auto"}}>
                {/* OVERVIEW TAB */}
                {nodeInfoTab==="overview"&&<div>
                  <div style={{padding:"14px 16px",borderBottom:`1px solid ${T.border}`}}>
                    <SLabel>Details</SLabel>
                    {[
                      {l:"Quality",v:<div style={{display:"flex",alignItems:"center",gap:7}}><span style={{fontSize:13,fontWeight:700,color:qualC(selMeta.quality),fontFamily:"'Geist Mono',monospace"}}>{selMeta.quality}</span><div style={{width:44,height:4,background:T.border,borderRadius:2,overflow:"hidden"}}><div style={{width:`${selMeta.quality}%`,height:"100%",background:qualC(selMeta.quality),borderRadius:2}}/></div></div>},
                      {l:"Service",v:<div style={{display:"flex",alignItems:"center",gap:5}}><ServiceIcon service={selMeta.service} size={14}/><span style={{fontSize:12,color:T.textSub}}>{selMeta.service}</span></div>},
                    ].map(m=>(
                      <div key={m.l} style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:8,fontSize:12}}>
                        <span style={{color:T.textMuted}}>{m.l}</span>{m.v}
                      </div>
                    ))}
                  </div>
                  <div style={{padding:"14px 16px",borderBottom:`1px solid ${T.border}`}}>
                    <SLabel>Description</SLabel>
                    <p style={{fontSize:12,color:T.textSub,lineHeight:1.7,margin:0}}>{selMeta.description}</p>
                  </div>
                  <div style={{padding:"14px 16px",borderBottom:`1px solid ${T.border}`}}>
                    <SLabel>Status</SLabel>
                    <div style={{display:"inline-flex",alignItems:"center",gap:6,padding:"4px 12px 4px 9px",borderRadius:5,background:cm.bg,borderTop:`1px solid ${cm.border}`,borderRight:`1px solid ${cm.border}`,borderBottom:`1px solid ${cm.border}`,borderLeft:`3px solid ${cm.color}`}}>
                      <span style={{fontSize:12,color:cm.color,fontWeight:600}}>{selMeta.cert}</span>
                    </div>
                  </div>
                  {selMeta.domain&&<div style={{padding:"14px 16px",borderBottom:`1px solid ${T.border}`}}>
                    <SLabel>Domain</SLabel>
                    <div style={{display:"inline-flex",alignItems:"center",padding:"4px 12px 4px 9px",borderRadius:5,background:`${T.accent}0f`,borderTop:`1px solid ${T.accent}20`,borderRight:`1px solid ${T.accent}20`,borderBottom:`1px solid ${T.accent}20`,borderLeft:`3px solid ${T.accent}`}}>
                      <span style={{fontSize:12,color:T.accent,fontWeight:600}}>{selMeta.domain}</span>
                    </div>
                  </div>}
                  <div style={{padding:"14px 16px",borderBottom:`1px solid ${T.border}`}}>
                    <SLabel>Owner</SLabel>
                    <div style={{display:"inline-flex",alignItems:"center",gap:5,padding:"3px 10px 3px 6px",borderRadius:5,background:`${T.accent}0f`,borderTop:`1px solid ${T.accent}20`,borderRight:`1px solid ${T.accent}20`,borderBottom:`1px solid ${T.accent}20`,borderLeft:`3px solid ${T.accent}`}}>
                      <div style={{width:18,height:18,borderRadius:3,background:T.accentDim,display:"flex",alignItems:"center",justifyContent:"center",fontSize:7,fontWeight:700,color:T.accent,flexShrink:0}}>{selMeta.owner.split(".").map(s=>s[0]?.toUpperCase()||"").join("")}</div>
                      <span style={{fontSize:12,color:T.accent,fontWeight:500}}>{selMeta.owner}</span>
                    </div>
                  </div>
                  {selMeta.steward&&<div style={{padding:"14px 16px",borderBottom:`1px solid ${T.border}`}}>
                    <SLabel>Steward</SLabel>
                    <div style={{display:"inline-flex",alignItems:"center",gap:5,padding:"3px 10px 3px 6px",borderRadius:5,background:"rgba(217,119,6,.08)",borderTop:"1px solid rgba(217,119,6,.2)",borderRight:"1px solid rgba(217,119,6,.2)",borderBottom:"1px solid rgba(217,119,6,.2)",borderLeft:"3px solid #d97706"}}>
                      <div style={{width:18,height:18,borderRadius:"50%",background:"rgba(217,119,6,.15)",display:"flex",alignItems:"center",justifyContent:"center",fontSize:7,fontWeight:700,color:"#d97706",flexShrink:0}}>{selMeta.steward.split(".").map(s=>s[0]?.toUpperCase()||"").join("")}</div>
                      <span style={{fontSize:12,color:"#d97706",fontWeight:500}}>{selMeta.steward}</span>
                    </div>
                  </div>}
                  {selMeta.tags&&selMeta.tags.length>0&&<div style={{padding:"14px 16px"}}>
                    <SLabel>Tags</SLabel>
                    <div style={{display:"flex",flexWrap:"wrap",gap:5}}>
                      {selMeta.tags.map(t=>{const c=tagC(t);return(
                        <span key={t} style={{display:"inline-flex",alignItems:"center",fontSize:11.5,padding:"4px 10px 4px 9px",borderRadius:5,background:c.bg,borderTop:`1px solid ${c.border}`,borderRight:`1px solid ${c.border}`,borderBottom:`1px solid ${c.border}`,borderLeft:`3px solid ${c.color}`,color:c.color,fontWeight:600}}>{t}</span>
                      );})}
                    </div>
                  </div>}
                </div>}

                {/* UPSTREAM TAB */}
                {nodeInfoTab==="upstream"&&<div style={{padding:"14px 16px"}}>
                  {upOrdered.length===0?(
                    <div style={{textAlign:"center",padding:"36px 0"}}>
                      <div style={{fontSize:28,marginBottom:8,color:T.textMuted}}>◁</div>
                      <div style={{fontSize:13,fontWeight:600,color:T.textSub,marginBottom:4}}>No Upstream</div>
                      <div style={{fontSize:11,color:T.textMuted}}>This is a source asset</div>
                    </div>
                  ):upOrdered.map(id=><LineageNodeCard key={id} nodeId={id} direct={directUp.includes(id)}/>)}
                </div>}

                {/* DOWNSTREAM TAB */}
                {nodeInfoTab==="downstream"&&<div style={{padding:"14px 16px"}}>
                  {downOrdered.length===0?(
                    <div style={{textAlign:"center",padding:"36px 0"}}>
                      <div style={{fontSize:28,marginBottom:8,color:T.textMuted}}>▷</div>
                      <div style={{fontSize:13,fontWeight:600,color:T.textSub,marginBottom:4}}>No Downstream</div>
                      <div style={{fontSize:11,color:T.textMuted}}>This is a sink asset</div>
                    </div>
                  ):downOrdered.map(id=><LineageNodeCard key={id} nodeId={id} direct={directDown.includes(id)}/>)}
                </div>}
              </div>
            </div>
          );
        })()}
      </div>
    </div>
  );
};

