// Human-readable diff between two contract definition snapshots
function diffContracts(prev,cur){
  const ch=[];
  const setOf=(arr,k)=>new Set((arr||[]).map(x=>typeof x==="string"?x:x[k]));
  const addrem=(prevArr,curArr,k,label)=>{
    const ps=setOf(prevArr,k),cs=setOf(curArr,k);
    [...cs].filter(x=>!ps.has(x)).forEach(x=>ch.push({t:"add",label:`${label} added: ${x}`}));
    [...ps].filter(x=>!cs.has(x)).forEach(x=>ch.push({t:"remove",label:`${label} removed: ${x}`}));
  };
  addrem(prev.schema,cur.schema,"name","Column");
  addrem(prev.semantics,cur.semantics,"rule","Rule");
  addrem(prev.quality,cur.quality,"name","Quality test");
  addrem(prev.policies,cur.policies,"name","Policy");
  [["refreshInterval","Refresh interval"],["refreshUnit","Refresh unit"],["latencyValue","Max latency"],["latencyUnit","Latency unit"],["availabilityTime","Availability time"],["availabilityTz","Timezone"],["retentionPeriod","Retention period"],["retentionUnit","Retention unit"],["refreshColumn","Refresh column"]].forEach(([k,label])=>{ if((prev.sla?.[k])!==(cur.sla?.[k])) ch.push({t:"change",label:`${label}: ${prev.sla?.[k]??"—"} → ${cur.sla?.[k]??"—"}`}); });
  return ch;
}
// Semantic-version bump: breaking change → major, otherwise → minor.
function bumpVersion(v,breaking){
  const p=String(v||"1.0.0").split(".").map(n=>parseInt(n,10)||0);
  while(p.length<3) p.push(0);
  if(breaking){ p[0]+=1; p[1]=0; p[2]=0; } else { p[1]+=1; p[2]=0; }
  return p.join(".");
}
// Short human summary of a version's changes, for the Version History note.
function summarizeChanges(structural,otherChanged,breaking){
  const n=t=>structural.filter(c=>c.t===t).length;
  const bits=[];
  if(n("add"))    bits.push(`${n("add")} added`);
  if(n("remove")) bits.push(`${n("remove")} removed`);
  if(n("change")) bits.push(`${n("change")} changed`);
  if(otherChanged) bits.push("metadata updated");
  return `${breaking?"Breaking change — ":""}${bits.join(", ")||"minor update"}`;
}
// Given the previous contract and the newly-built one, produce the next contract
// state with a bumped version + a snapshot of the previous definition pushed into
// versions[]. Returns {next, changed, breaking, version}. No structural/metadata
// change → version and history are left untouched.
function computeContractEdit(prev,built,newStatus,editor){
  const structural=diffContracts(prev,built);
  const otherChanged= (prev.description||"")!==(built.description||"")
    || JSON.stringify(prev.terms||{})!==JSON.stringify(built.terms||{})
    || JSON.stringify(prev.consumers||[])!==JSON.stringify(built.consumers||[]);
  const changed=structural.length>0||otherChanged;
  const base={...built,status:newStatus,schedule:built.schedule??prev.schedule,updated:"Just now"};
  if(!changed){
    return {next:{...base,version:prev.version,versions:prev.versions,versionNote:prev.versionNote}, changed:false, breaking:false, version:prev.version};
  }
  const breaking=structural.some(c=>c.t==="remove"&&/^Column/.test(c.label));
  const version=bumpVersion(prev.version,breaking);
  const snap={version:prev.version,at:prev.updated||"—",by:(prev.owners||[])[0]||editor,note:prev.versionNote,
    schema:prev.schema,semantics:prev.semantics,quality:prev.quality,policies:prev.policies,sla:prev.sla};
  return {next:{...base,version,versions:[snap,...(prev.versions||[])],versionNote:summarizeChanges(structural,otherChanged,breaking)}, changed:true, breaking, version};
}

// ── Session persistence: contracts live in a module store, seeded from the mocks ──
const CONTRACT_STORE = {};
const getStoredContract = (name)=>{
  if(!(name in CONTRACT_STORE)) CONTRACT_STORE[name]=CONTRACT_BY_ASSET[name]?JSON.parse(JSON.stringify(CONTRACT_BY_ASSET[name])):null;
  return CONTRACT_STORE[name];
};

// ── Freshness helpers (SLA validation) ──
// Parse a relative "updated" label ("2h ago", "30m ago", "1d ago", "2w ago", "Just now") → hours.
function relAgeHours(label){
  if(!label) return null;
  const s=String(label).toLowerCase();
  if(s.includes("just now")) return 0;
  const m=s.match(/(\d+(?:\.\d+)?)\s*(mo|months?|mins?|minutes?|m|hrs?|hours?|h|days?|d|wks?|weeks?|w|yrs?|years?|y)\b/);
  if(!m) return null;
  const n=parseFloat(m[1]), u=m[2];
  if(u==="mo"||u.startsWith("month")) return n*24*30;
  if(u==="m"||u.startsWith("min"))    return n/60;
  if(u.startsWith("h"))               return n;
  if(u.startsWith("d"))               return n*24;
  if(u.startsWith("w"))               return n*24*7;
  if(u.startsWith("y"))               return n*24*365;
  return null;
}
// Convert a contract SLA latency (value + unit) → hours.
function slaLatencyHours(sla){
  if(!sla||sla.latencyValue==null||sla.latencyValue==="") return null;
  const v=Number(sla.latencyValue); if(isNaN(v)) return null;
  const u=(sla.latencyUnit||"Hours").toLowerCase();
  if(u.startsWith("min")) return v/60;
  if(u.startsWith("day")) return v*24;
  if(u.startsWith("week")) return v*24*7;
  return v; // hours (default)
}
// Round hours to a short human label ("3h", "1.5d", "45m").
function humanHours(h){
  if(h==null) return "—";
  if(h<1) return `${Math.round(h*60)}m`;
  if(h<48) return `${h%1===0?h:h.toFixed(1)}h`;
  return `${(h/24)%1===0?h/24:(h/24).toFixed(1)}d`;
}

// ── Live validation: checks the contract against the asset's real metadata + tests ──
function validateContract(contract,asset){
  const assetCols=(typeof ASSET_COLUMNS!=="undefined" && ASSET_COLUMNS[asset.name])||[];
  const liveCases=(typeof DQ_TEST_CASES!=="undefined"?DQ_TEST_CASES:[]).filter(t=>t.table.endsWith("."+asset.name)||t.table===asset.name);
  const schema=(contract.schema||[]).map(c=>({...c,exists:assetCols.length===0||assetCols.includes(c.name)}));
  const schemaPass=schema.every(c=>!c.required||c.exists);
  const semantics=(contract.semantics||[]).map(s=>{
    let pass=s.pass!==false;
    if(s.key==="owners")      pass=!!((asset.owners&&asset.owners.length)||asset.owner);
    else if(s.key==="stewards") pass=!!((asset.stewards&&asset.stewards.length)||asset.steward);
    else if(s.key==="description") pass=!!(asset.description&&asset.description.length>5);
    else if(s.key==="domain") pass=!!asset.domain;
    else if(s.key==="tier")   pass=asset.tier!=null;
    else if(s.key==="tags")   pass=!!(asset.tags&&asset.tags.length);
    return {...s,pass};
  });
  const quality=(contract.quality||[]).map(q=>{
    const tc=q.tcId&&liveCases.find(t=>t.id===q.tcId);
    return {...q, pass: tc ? tc.status==="Success" : (q.pass!==false), status: tc?tc.status:null};
  });
  const allPolicies=(typeof POLICIES!=="undefined"?POLICIES:[]);
  const policies=(contract.policies||[]).map(p=>{
    const pol=allPolicies.find(x=>x.id===p.policyId);
    const pass=pol?((pol.violations||0)===0&&pol.lifecycle!=="Deprecated"):true;
    return {...p,pass,category:pol?.category,lifecycle:pol?.lifecycle,violations:pol?.violations||0};
  });
  // SLA freshness: compare the asset's data age against the contract's max latency.
  // Only evaluable when a refresh column is declared AND both ages are parseable —
  // otherwise we can't measure freshness, so we don't fail the check.
  const ageH=relAgeHours(asset.updated);
  const maxH=slaLatencyHours(contract.sla);
  const hasRefreshCol=!!(contract.sla&&contract.sla.refreshColumn&&String(contract.sla.refreshColumn).trim());
  const slaEvaluable=ageH!=null&&maxH!=null&&hasRefreshCol;
  const slaPass=slaEvaluable?ageH<=maxH:true;
  const sla={
    pass:slaPass, evaluable:slaEvaluable, ageHours:ageH, maxHours:maxH,
    ageLabel:asset.updated||"—",
    latencyLabel:(contract.sla&&contract.sla.latencyValue!=null&&contract.sla.latencyValue!=="")?`${contract.sla.latencyValue} ${contract.sla.latencyUnit}`:"—",
    refreshColumn:contract.sla&&contract.sla.refreshColumn,
    reason: !hasRefreshCol ? "No refresh column declared — freshness not evaluated"
          : ageH==null ? "Asset age unknown — freshness not evaluated"
          : maxH==null ? "No max latency set — freshness not evaluated"
          : slaPass ? `Fresh — data age ${humanHours(ageH)} within ${humanHours(maxH)} SLA`
          : `Stale — data age ${humanHours(ageH)} exceeds ${humanHours(maxH)} max latency`,
  };
  const sections={Schema:schemaPass,Semantics:semantics.every(s=>s.pass),Quality:quality.every(q=>q.pass),Policies:policies.every(p=>p.pass),SLA:slaPass};
  const failedSections=Object.entries(sections).filter(([,v])=>!v).map(([k])=>k);
  return {schema,semantics,quality,policies,sla,sections,failedSections,allPass:failedSections.length===0};
}

const AssetContractTab = ({asset,onToast})=>{
  const mono={fontFamily:"'Geist Mono',monospace"};
  const {role:_role, roleCfg:_rcfg} = useRole();
  const meHandle = ((_rcfg&&_rcfg.email)||"you@jnj").split("@")[0];
  const isStewardOrAdmin = _role==="steward"||_role==="admin";

  // Push a contract approval request into the shared inbox store
  const pushContractApprovalInbox = (contractName, action="created") => {
    const id = "inb_ca_"+Date.now();
    addContractApprovalItem({
      id, type:"contract_approval", severity:"medium", section:"catalog", timeAgo:"Just now",
      title:`Contract approval needed · ${contractName}`,
      asset:{name:asset.name, path:asset.db||asset.name, type:"Table"},
      body:`${meHandle} ${action} the contract "${contractName}" on ${asset.name}. Review and approve to make it Active.`,
      contractName, assetName:asset.name, requestedBy:meHandle, action,
      readAt:null,
    });
  };

  const [contract,setContractState]=useState(()=>getStoredContract(asset.name));
  const [wizard,setWizard]=useState(false);   // false | "create" | "edit"
  const [tab,setTab]=useState("contract");    // contract | runs | versions
  const [statusOpen,setStatusOpen]=useState(false);
  const [settingsOpen,setSettingsOpen]=useState(false);
  const [scheduleModal,setScheduleModal]=useState(false);
  const [deleteConfirm,setDeleteConfirm]=useState(false);
  const [expandedRun,setExpandedRun]=useState(null);
  const [validating,setValidating]=useState(false);   // true while a validation run is in flight
  const setContract=(u)=>setContractState(prev=>{const next=typeof u==="function"?u(prev):u; CONTRACT_STORE[asset.name]=next; return next;});

  // Status can only be changed by steward/admin — connection admins go through approval flow
  const changeStatus=(st)=>{ setStatusOpen(false); if(st===contract.status) return; if(!isStewardOrAdmin){onToast&&onToast("Only a steward or admin can change contract status","error");return;} setContract(c=>({...c,status:st,updated:"Just now"})); onToast&&onToast(`Status set to ${st}`,"success"); };
  const runNow=(contractArg)=>{
    setSettingsOpen(false);
    if(validating) return;   // already in flight
    const target=(contractArg&&contractArg.name)?contractArg:contract;
    // ── 1) show the running state immediately: a live "Running" row + Health spinner ──
    setValidating(true);
    setContract(c=>({...c,runs:[{at:"Just now",by:"You",trigger:"Manual",result:"Running",running:true},...(c.runs||[])]}));
    setTab("runs");
    // ── 2) compute + finalize after a short delay ──
    setTimeout(()=>{
    const res=validateContract(target,asset);
    const total=Object.keys(res.sections).length, passed=total-res.failedSections.length;
    const status=contractRunStatus(res);
    // per-section detail (OpenMetadata-style failedFields/failedRules)
    const detail={
      Schema:{pass:res.sections.Schema,items:(res.schema||[]).filter(c=>c.required&&!c.exists).map(c=>`${c.name} missing`)},
      Semantics:{pass:res.sections.Semantics,items:(res.semantics||[]).filter(s=>!s.pass).map(s=>s.rule)},
      Quality:{pass:res.sections.Quality,items:(res.quality||[]).filter(q=>!q.pass).map(q=>q.name)},
      Policies:{pass:res.sections.Policies,items:(res.policies||[]).filter(p=>!p.pass).map(p=>`${p.name}${p.violations?` — ${p.violations} violations`:""}`)},
      SLA:{pass:res.sections.SLA,items:(res.sla&&!res.sla.pass)?[res.sla.reason]:[]},
    };
    const run={at:"Just now",by:"You",trigger:"Manual",result:status,total,passed,failed:res.failedSections,detail};
    let incidentOpened=false;
    setContract(c=>{
      // replace the leading "Running" placeholder with the finalized run
      const rest=(c.runs||[]).filter(r=>!r.running);
      const next={...c,lastRun:"Just now",runs:[run,...rest]};
      // ── violation → auto-open an incident + alert (only if not already open) ──
      if(status!=="Success" && typeof DQ_INCIDENTS!=="undefined"){
        const fqTable=(c.schema&&asset.name)?`commerce.${asset.name}`:asset.name;
        const tname=(DQ_INCIDENTS[0]&&asset.name)?asset.name:asset.name;
        const already=DQ_INCIDENTS.some(i=>i.contractFqn===c.name && i.status!=="Resolved" && i.status!=="Dismissed");
        if(!already){
          incidentOpened=true;
          DQ_INCIDENTS.unshift({
            id:"inc_c"+Date.now(), title:`Contract violation — ${c.name}`, severity:status==="Failed"?"Critical":"High",
            table:(asset.db&&asset.db.includes("/")?asset.db.split("/").slice(-2,-1)[0].trim()+"."+asset.name:asset.name), col:null, tcId:null, contractFqn:c.name,
            opened:"Just now", assignee:null, rootCause:"", resolutionReason:"", resolved:null, affectedRows:null,
            timeline:[{action:`Contract ${c.name} failed validation — ${res.failedSections.join(", ")}`,by:"system",at:"Just now"}],
            comments:[],
            desc:`Data contract "${c.name}" validation ${status==="Failed"?"failed":"partially failed"}. Failing checks: ${res.failedSections.join(", ")}.`,
          });
        }
      }
      return next;
    });
    setValidating(false);
    if(res.allPass) onToast&&onToast("Validation passed — all checks green","success");
    else onToast&&onToast(`Validation ${status==="Failed"?"failed":"partially failed"} — ${res.failedSections.length} check(s) failing${incidentOpened?" · incident opened + alert sent":""}`,"error");
    },1500);
  };
  // How many registered consumers get notified when the contract changes
  const notifyCount=(c)=>(c&&c.consumers?c.consumers.length:0);
  const notifySuffix=(c)=>{const n=notifyCount(c);return n?` · ${n} consumer${n>1?"s":""} notified`:"";};
  const saveEdit=(updated)=>{
    // Steward/admin edits → stay Active. Connection admin edits → drop to Draft for re-approval.
    const newStatus = isStewardOrAdmin ? (contract.status||"Active") : "Draft";
    const ed=computeContractEdit(contract,updated,newStatus,meHandle);
    setContract(ed.next);
    setWizard(false);
    if(!isStewardOrAdmin){ pushContractApprovalInbox(updated.name,"updated"); onToast&&onToast("Contract updated — pending steward approval to go Active","info"); }
    else { onToast&&onToast(ed.changed?`Contract updated → v${ed.version}${ed.breaking?" · breaking change":""}${notifySuffix(updated)}`:"No changes to save","success"); }
  };
  // Wizard submit — the two footer buttons (Run now / Schedule) both finalize creation/edit, then act.
  const submitWizard=(built,action)=>{
    const editing = wizard==="edit";
    // Steward/Admin → auto-Active. Connection Admin → Draft, needs steward approval.
    const newStatus = isStewardOrAdmin ? "Active" : "Draft";
    // On edit: bump version + snapshot the prior definition into history. On create: seed v1.0.0.
    const ed = editing ? computeContractEdit(contract,built,newStatus,meHandle) : null;
    if(editing) setContract(ed.next);
    else setContract({...built,status:newStatus,versions:[],versionNote:"Initial contract"});
    setWizard(false);
    if(!isStewardOrAdmin){ pushContractApprovalInbox(built.name, editing?"updated":"created"); onToast&&onToast(editing?"Contract updated — pending steward approval":"Contract created — pending steward approval to go Active","info"); return; }
    const editMsg = ed ? (ed.changed?`Contract updated → v${ed.version}${ed.breaking?" · breaking change":""}${notifySuffix(built)}`:"No changes to save") : `Contract "${built.name}" created`;
    if(action==="schedule"){ onToast&&onToast(editMsg,"success"); setScheduleModal(true); }
    else { if(editing) onToast&&onToast(editMsg,"success"); runNow(built); }
  };
  const doDelete=()=>{
    if(!isStewardOrAdmin){
      // Connection admin requesting delete → send approval request to steward
      setDeleteConfirm(false);
      pushContractApprovalInbox(contract.name,"requested deletion of");
      onToast&&onToast("Delete request sent to steward for approval","info");
      return;
    }
    setContractState(null); CONTRACT_STORE[asset.name]=null; setDeleteConfirm(false); onToast&&onToast("Contract deleted","error");
  };
  const saveSchedule=(sched)=>{ setContract(c=>({...c,schedule:sched,validationMode:sched.freq==="once"?"ondemand":"scheduled"})); setScheduleModal(false); onToast&&onToast(sched.enabled===false?"Validation schedule saved (paused)":"Validation schedule updated","success"); };
  const removeSchedule=()=>{ setContract(c=>({...c,schedule:null,validationMode:"ondemand"})); setScheduleModal(false); onToast&&onToast("Schedule removed — validate on demand","info"); };

  // ── Empty state ──
  if(!contract) return (
    <>
      <div className="fadeIn" style={{padding:"64px 20px",textAlign:"center",maxWidth:520,margin:"0 auto"}}>
        <div style={{width:54,height:54,borderRadius:14,background:T.accentDim,display:"flex",alignItems:"center",justifyContent:"center",margin:"0 auto 16px",color:T.accent}}>
          <svg width="26" height="26" viewBox="0 0 24 24" fill="none"><path d="M7 3h7l5 5v13a0 0 0 01 0 0H7a2 2 0 01-2-2V5a2 2 0 012-2z" stroke="currentColor" strokeWidth="1.6"/><path d="M13 3v6h6M9 13l2 2 4-4" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"/></svg>
        </div>
        <div style={{fontSize:16,fontWeight:700,color:T.text,marginBottom:6}}>No data contract yet</div>
        <div style={{fontSize:13,color:T.textMuted,lineHeight:1.6,marginBottom:20}}>A data contract formalizes the agreement between producers and consumers — schema, semantics, quality tests, governance policies and SLAs — and is continuously validated against the live asset.</div>
        <Btn variant="primary" icon={Ic.plus(13)} onClick={()=>setWizard("create")}>Add Contract</Btn>
      </div>
      {wizard&&<ContractWizard asset={asset} onToast={onToast} onClose={()=>setWizard(false)} onSubmit={submitWizard}/>}
    </>
  );

  const v=validateContract(contract,asset);
  const sp=v.sections;
  const sc=CONTRACT_STATUS[contract.status]||CONTRACT_STATUS.Draft;
  const health=CONTRACT_HEALTH[contractHealthKey(v)];
  const failCount=v.failedSections.length;
  const TOTAL_CHECKS=Object.keys(v.sections).length;
  const allVersions=[{version:contract.version,at:contract.updated,by:(contract.owners||[])[0]||"—",current:true,note:contract.versionNote,schema:contract.schema,semantics:contract.semantics,quality:contract.quality,policies:contract.policies,sla:contract.sla},...(contract.versions||[])];

  const Section=({title,pass,children,action})=>(
    <Card2><div style={{padding:"15px 18px"}}>
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:12}}>
        <div style={{display:"flex",alignItems:"center",gap:8}}>
          <span style={{fontSize:13,fontWeight:700,color:T.text}}>{title}</span>
          {pass!=null&&<span style={{fontSize:10,fontWeight:700,padding:"2px 7px",borderRadius:5,background:pass?"#16a34a14":T.roseDim,color:pass?"#16a34a":T.rose,border:`1px solid ${pass?"#16a34a40":T.rose+"40"}`}}>{pass?"PASS":"FAIL"}</span>}
        </div>
        {action}
      </div>
      {children}
    </div></Card2>
  );
  const KV=({k,v})=>(
    <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"7px 0",borderBottom:`1px solid ${T.border}`,fontSize:12.5}}>
      <span style={{color:T.textMuted}}>{k}</span><span style={{...mono,color:T.text,fontWeight:600}}>{v}</span>
    </div>
  );

  return <div className="fadeIn" style={{display:"flex",flexDirection:"column",gap:16}}>
    {/* ── Header ── */}
    <Card2><div style={{padding:"16px 18px"}}>
      <div style={{display:"flex",alignItems:"flex-start",justifyContent:"space-between",gap:14,flexWrap:"wrap"}}>
        <div style={{minWidth:0}}>
          <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:6}}>
            <span style={{...mono,fontSize:16,fontWeight:700,color:T.text}}>{contract.name}</span>
            <span style={{fontSize:11,...mono,color:T.textMuted,padding:"2px 8px",background:T.bgElevated,borderRadius:5,border:`1px solid ${T.border}`}}>v{contract.version}</span>
          </div>
          <div style={{fontSize:12.5,color:T.textSub,lineHeight:1.6,maxWidth:680}}>{contract.description}</div>
        </div>
        <div style={{display:"flex",gap:8,flexShrink:0,alignItems:"center"}}>
          <ScheduleButton schedule={contract.schedule} onClick={()=>setScheduleModal(true)}/>
          <Btn small variant="primary" disabled={validating} icon={validating?<svg width="12" height="12" viewBox="0 0 24 24" fill="none" style={{animation:"spin 0.8s linear infinite"}}><circle cx="12" cy="12" r="9" stroke="currentColor" strokeWidth="2.5" strokeDasharray="20 40"/></svg>:<svg width="12" height="12" viewBox="0 0 16 16" fill="none"><path d="M4 3l9 5-9 5V3z" fill="currentColor"/></svg>} onClick={()=>runNow()}>{validating?"Running…":"Run now"}</Btn>
          <div style={{position:"relative"}}>
            <button onClick={()=>setSettingsOpen(o=>!o)} title="Contract settings" style={{width:30,height:30,borderRadius:8,background:settingsOpen?T.bgHover:"transparent",border:`1px solid ${T.border}`,color:T.textSub,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center"}}
              onMouseEnter={e=>{e.currentTarget.style.background=T.bgHover;e.currentTarget.style.color=T.text;}} onMouseLeave={e=>{if(!settingsOpen){e.currentTarget.style.background="transparent";e.currentTarget.style.color=T.textSub;}}}>
              <svg width="16" height="16" viewBox="0 0 16 16" fill="currentColor"><circle cx="8" cy="3" r="1.4"/><circle cx="8" cy="8" r="1.4"/><circle cx="8" cy="13" r="1.4"/></svg>
            </button>
            {settingsOpen&&<>
              <div onClick={()=>setSettingsOpen(false)} style={{position:"fixed",inset:0,zIndex:50}}/>
              <div style={{position:"absolute",top:"calc(100% + 5px)",right:0,zIndex:51,background:T.bgSurface,border:`1px solid ${T.border}`,borderRadius:10,boxShadow:"0 14px 36px rgba(0,0,0,.28)",padding:5,minWidth:170}}>
                {[
                  {k:"edit",label:"Edit contract",icon:<svg width="13" height="13" viewBox="0 0 16 16" fill="none"><path d="M10.5 2.5l3 3L6 13H3v-3l7.5-7.5z" stroke="currentColor" strokeWidth="1.3" strokeLinejoin="round"/></svg>,fn:()=>{setSettingsOpen(false);setWizard("edit");}},
                  {k:"del",label:"Delete contract",danger:true,icon:<svg width="13" height="13" viewBox="0 0 16 16" fill="none"><path d="M3 4.5h10M6.5 4V2.8h3V4M5 4.5l.5 8.5h5l.5-8.5" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round" strokeLinejoin="round"/></svg>,fn:()=>{setSettingsOpen(false);setDeleteConfirm(true);}},
                ].map(it=>(
                  <button key={it.k} onClick={it.fn} style={{display:"flex",alignItems:"center",gap:10,width:"100%",padding:"8px 10px",borderRadius:7,background:"transparent",border:"none",cursor:"pointer",textAlign:"left",color:it.danger?T.rose:T.text,fontSize:12.5,fontWeight:500}}
                    onMouseEnter={e=>e.currentTarget.style.background=it.danger?T.roseDim:T.bgHover} onMouseLeave={e=>e.currentTarget.style.background="transparent"}>
                    <span style={{display:"flex",color:it.danger?T.rose:T.textMuted}}>{it.icon}</span>{it.label}
                  </button>
                ))}
              </div>
            </>}
          </div>
        </div>
      </div>

      {/* Status (owner-set) + Health (computed) */}
      <div style={{display:"flex",gap:36,flexWrap:"wrap",marginTop:16,paddingTop:16,borderTop:`1px solid ${T.border}`}}>
        <div style={{minWidth:180}}>
          <div style={{fontSize:10,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:.6,marginBottom:8}}>Status</div>
          <div style={{position:"relative",display:"inline-block"}}>
            <button onClick={()=>setStatusOpen(o=>!o)} style={{display:"inline-flex",alignItems:"center",gap:8,padding:"6px 12px",borderRadius:8,background:sc.bg,color:sc.color,border:`1px solid ${sc.border}`,fontSize:12.5,fontWeight:700,cursor:"pointer"}}>
              <span style={{width:7,height:7,borderRadius:"50%",background:sc.color}}/>{sc.label}
              <svg width="9" height="9" viewBox="0 0 10 10" fill="none" style={{opacity:.7}}><path d="M2 4l3 3 3-3" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/></svg>
            </button>
            {statusOpen&&<>
              <div onClick={()=>setStatusOpen(false)} style={{position:"fixed",inset:0,zIndex:50}}/>
              <div style={{position:"absolute",top:"calc(100% + 5px)",left:0,zIndex:51,background:T.bgSurface,border:`1px solid ${T.border}`,borderRadius:10,boxShadow:"0 14px 36px rgba(0,0,0,.28)",padding:5,minWidth:230}}>
                {CONTRACT_STATES.map(st=>{const cfg=CONTRACT_STATUS[st];const on=contract.status===st;return (
                  <button key={st} onClick={()=>changeStatus(st)} style={{display:"flex",alignItems:"center",gap:10,width:"100%",padding:"8px 10px",borderRadius:8,background:on?T.bgElevated:"transparent",border:"none",cursor:"pointer",textAlign:"left"}}
                    onMouseEnter={e=>e.currentTarget.style.background=T.bgHover} onMouseLeave={e=>e.currentTarget.style.background=on?T.bgElevated:"transparent"}>
                    <span style={{width:8,height:8,borderRadius:"50%",background:cfg.color,flexShrink:0}}/>
                    <span style={{minWidth:0,flex:1}}><div style={{fontSize:12.5,fontWeight:600,color:T.text}}>{cfg.label}</div><div style={{fontSize:10.5,color:T.textMuted}}>{cfg.desc}</div></span>
                    {on&&<svg width="13" height="13" viewBox="0 0 16 16" fill="none" style={{color:T.accent,flexShrink:0}}><path d="M3.5 8.5l3 3 6-6.5" stroke="currentColor" strokeWidth="1.9" strokeLinecap="round" strokeLinejoin="round"/></svg>}
                  </button>);})}
              </div>
            </>}
          </div>
          <div style={{fontSize:10.5,color:T.textMuted,marginTop:7,maxWidth:200}}>{sc.desc}</div>
        </div>
        <div>
          <div style={{fontSize:10,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:.6,marginBottom:8}}>Validation</div>
          <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:6}}>
            {validating
              ? <><svg width="13" height="13" viewBox="0 0 24 24" fill="none" style={{animation:"spin 0.8s linear infinite",flexShrink:0}}><circle cx="12" cy="12" r="9" stroke={T.blue} strokeWidth="2.5" strokeDasharray="20 40"/></svg><span style={{fontSize:13,fontWeight:700,color:T.blue}}>Running {TOTAL_CHECKS} checks…</span></>
              : failCount>0
                ? <><span style={{width:8,height:8,borderRadius:"50%",background:T.rose,flexShrink:0}}/><span style={{fontSize:13,fontWeight:700,color:T.rose}}>{failCount} of {TOTAL_CHECKS} checks failing</span></>
                : <><span style={{width:8,height:8,borderRadius:"50%",background:"#16a34a",flexShrink:0}}/><span style={{fontSize:13,fontWeight:700,color:"#16a34a"}}>All {TOTAL_CHECKS} checks passing</span></>}
          </div>
          <div style={{display:"flex",alignItems:"center",gap:6,flexWrap:"wrap",marginBottom:8}}>
            {["Schema","Semantics","Quality","Policies","SLA"].map(s=>{
              const ok=sp[s];
              return <div key={s} style={{display:"flex",alignItems:"center",gap:5,padding:"3px 9px",borderRadius:6,background:ok?"#16a34a0e":T.roseDim,border:`1px solid ${ok?"#16a34a33":T.rose+"33"}`}}>
                <span style={{color:ok?"#16a34a":T.rose,display:"flex"}}>{ok?<svg width="11" height="11" viewBox="0 0 16 16" fill="none"><path d="M3.5 8.5l3 3 6-6.5" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"/></svg>:<svg width="11" height="11" viewBox="0 0 16 16" fill="none"><path d="M5 5l6 6M11 5l-6 6" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round"/></svg>}</span>
                <span style={{fontSize:11,fontWeight:600,color:ok?"#16a34a":T.rose}}>{s}</span>
              </div>;
            })}
          </div>
          <div style={{fontSize:10.5,color:T.textMuted,display:"flex",alignItems:"center",gap:5,flexWrap:"wrap"}}>
            <svg width="11" height="11" viewBox="0 0 16 16" fill="none" style={{flexShrink:0}}><circle cx="8" cy="8.5" r="5.5" stroke="currentColor" strokeWidth="1.3"/><path d="M8 5.5v3l2 1.2" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round"/></svg>
            {(contract.validationMode==="scheduled"&&contract.schedule&&contract.schedule.enabled!==false)
              ? <span>Auto-validates {contractScheduleLabel(contract.schedule)}</span>
              : (contract.validationMode==="scheduled"&&contract.schedule)
                ? <span>Schedule paused</span>
                : <span>On-demand</span>}
            <span style={{opacity:.5}}>·</span><span>Last run {contract.lastRun}</span>
          </div>
        </div>
      </div>

      {/* Owners + Stewards */}
      <div style={{display:"flex",gap:32,flexWrap:"wrap",marginTop:16,paddingTop:16,borderTop:`1px solid ${T.border}`}}>
        <div>
          <div style={{fontSize:10,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:.6,marginBottom:8}}>Owners</div>
          <div style={{display:"flex",gap:7,flexWrap:"wrap"}}>
            {(contract.owners||[]).length
              ? (contract.owners||[]).map(u=>(
                <span key={u} style={{display:"inline-flex",alignItems:"center",gap:6,padding:"3px 11px 3px 4px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:99,color:T.textSub,fontSize:12}}>
                  <span style={{width:20,height:20,borderRadius:6,background:"#b4530915",border:"1px solid #b4530933",display:"flex",alignItems:"center",justifyContent:"center",fontSize:9,fontWeight:700,color:"#b45309",flexShrink:0}}>{u.split(".").map(x=>x[0]?.toUpperCase()||"").join("").slice(0,2)}</span>{u}
                </span>))
              : <span style={{fontSize:12,color:T.textMuted,fontStyle:"italic"}}>None assigned</span>}
          </div>
        </div>
        <div>
          <div style={{fontSize:10,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:.6,marginBottom:8}}>Stewards</div>
          <div style={{display:"flex",gap:7,flexWrap:"wrap"}}>
            {(contract.stewards||[]).length
              ? (contract.stewards||[]).map(u=>(
                <span key={u} style={{display:"inline-flex",alignItems:"center",gap:6,padding:"3px 11px 3px 4px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:99,color:T.textSub,fontSize:12}}>
                  <span style={{width:20,height:20,borderRadius:6,background:"#0d948815",border:"1px solid #0d948833",display:"flex",alignItems:"center",justifyContent:"center",fontSize:9,fontWeight:700,color:"#0d9488",flexShrink:0}}>{u.split(".").map(x=>x[0]?.toUpperCase()||"").join("").slice(0,2)}</span>{u}
                </span>))
              : <span style={{fontSize:12,color:T.textMuted,fontStyle:"italic"}}>None assigned</span>}
          </div>
        </div>
        <div style={{marginLeft:"auto",alignSelf:"flex-end"}}>
          <span style={{fontSize:11,color:T.textMuted}}>Updated {contract.updated}</span>
        </div>
      </div>

      {/* ── Consumers — registered users who depend on this data. Owners are the producing party. ── */}
      <div style={{marginTop:16,paddingTop:16,borderTop:`1px solid ${T.border}`}}>
        <div style={{display:"flex",alignItems:"baseline",gap:8,marginBottom:8,flexWrap:"wrap"}}>
          <span style={{fontSize:10,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:.6}}>Consumers <span style={{fontWeight:600}}>({(contract.consumers||[]).length})</span></span>
          <span style={{fontSize:10.5,color:T.textMuted}}>notified when this contract changes · owners are the producing team</span>
        </div>
        <div style={{display:"flex",gap:7,flexWrap:"wrap"}}>
          {(contract.consumers||[]).length
            ? contract.consumers.map((u,i)=>(
              <span key={i} style={{display:"inline-flex",alignItems:"center",gap:6,padding:"3px 11px 3px 4px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:99,color:T.textSub,fontSize:12}}>
                <span style={{width:20,height:20,borderRadius:6,background:`${T.blue}15`,border:`1px solid ${T.blue}33`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:9,fontWeight:700,color:T.blue,flexShrink:0}}>{(u||"").split(".").map(x=>x[0]?.toUpperCase()||"").join("").slice(0,2)}</span>{u}
              </span>))
            : <span style={{fontSize:12,color:T.textMuted,fontStyle:"italic"}}>None registered</span>}
        </div>
      </div>

    </div></Card2>

    {/* ── Tabs: Contract · Runs · Version History (segmented, like Observability) ── */}
    <SegTabs active={tab} onChange={setTab} tabs={[
      {key:"contract",label:"Contract"},
      {key:"runs",label:"Runs",count:(contract.runs||[]).length||undefined},
      {key:"versions",label:"Version History",count:allVersions.length||undefined},
    ]}/>

    {/* ── Runs tab ── */}
    {tab==="runs"&&(()=>{ const runs=contract.runs||[]; return (
      <Card2 style={{padding:0,overflow:"hidden"}}>
        <div style={{padding:"13px 18px",borderBottom:`1px solid ${T.border}`,display:"flex",alignItems:"center",justifyContent:"space-between",gap:12,flexWrap:"wrap"}}>
          <div><div style={{fontSize:13,fontWeight:700,color:T.text}}>Validation Runs</div><div style={{fontSize:11.5,color:T.textMuted,marginTop:2}}>Every validation of this contract against the live asset, with per-check results.</div></div>
          <Btn small variant="primary" disabled={validating} onClick={()=>runNow()}>{validating?"Running…":"Run validation now"}</Btn>
        </div>
        {runs.length===0
          ? <div style={{padding:"44px 20px",textAlign:"center",color:T.textMuted,fontSize:13}}>No validation runs yet. Run one from the button above.</div>
          : <table style={{width:"100%",borderCollapse:"collapse"}}>
              <thead><tr style={{background:T.bgElevated}}>
                {["Result","Run","Trigger","Checks","Failed checks"].map(h=><th key={h} style={{padding:"9px 16px",fontSize:10.5,fontWeight:700,color:T.textMuted,textAlign:"left",textTransform:"uppercase",letterSpacing:.5,whiteSpace:"nowrap"}}>{h}</th>)}
              </tr></thead>
              <tbody>
                {runs.map((r,i)=>{
                  const hc=CONTRACT_RUN_STATUS[r.result]||CONTRACT_RUN_STATUS.Success;
                  const det=r.detail&&Object.keys(r.detail).length?r.detail:null;
                  const exp=expandedRun===i;
                  return <React.Fragment key={i}>
                  <tr onClick={()=>det&&setExpandedRun(exp?null:i)} style={{borderBottom:(!exp&&i<runs.length-1)?`1px solid ${T.border}`:"none",cursor:det?"pointer":"default",background:exp?T.bgElevated:"transparent"}}
                    onMouseEnter={e=>{if(det&&!exp)e.currentTarget.style.background=T.bgHover;}} onMouseLeave={e=>{if(!exp)e.currentTarget.style.background="transparent";}}>
                    <td style={{padding:"11px 16px"}}><span style={{display:"inline-flex",alignItems:"center",gap:7,fontSize:12,fontWeight:700,color:hc.color}}>{det&&<span style={{color:T.textMuted,fontSize:9,transform:exp?"rotate(90deg)":"none",transition:"transform .12s",display:"inline-block"}}>▶</span>}{r.running?<svg width="11" height="11" viewBox="0 0 24 24" fill="none" style={{animation:"spin 0.8s linear infinite"}}><circle cx="12" cy="12" r="9" stroke={hc.color} strokeWidth="2.5" strokeDasharray="20 40"/></svg>:<span style={{width:8,height:8,borderRadius:"50%",background:hc.color}}/>}{hc.label}</span></td>
                    <td style={{padding:"11px 16px",fontSize:12,...mono,color:T.textSub,whiteSpace:"nowrap"}}>{r.at}<span style={{color:T.textMuted}}> · {r.by}</span></td>
                    <td style={{padding:"11px 16px"}}><span style={{fontSize:10.5,fontWeight:600,padding:"2px 8px",borderRadius:5,background:T.bgElevated,border:`1px solid ${T.border}`,color:T.textSub}}>{r.trigger}</span></td>
                    <td style={{padding:"11px 16px",fontSize:12,...mono,color:r.running?T.blue:r.result==="Aborted"?T.textMuted:r.passed===r.total?"#16a34a":T.textSub,whiteSpace:"nowrap"}}>{r.running?"validating…":r.result==="Aborted"?"—":`${r.passed}/${r.total} passed`}</td>
                    <td style={{padding:"11px 16px"}}>{r.running?<span style={{color:T.textMuted,fontSize:12}}>—</span>:r.note?<span style={{fontSize:11.5,color:T.textMuted,fontStyle:"italic"}}>{r.note}</span>:(r.failed&&r.failed.length)?<div style={{display:"flex",gap:5,flexWrap:"wrap"}}>{r.failed.map(f=><span key={f} style={{fontSize:10.5,fontWeight:600,padding:"2px 8px",borderRadius:5,background:T.roseDim,color:T.rose,border:`1px solid ${T.rose}33`}}>{f}</span>)}</div>:<span style={{color:T.textMuted,fontSize:12}}>—</span>}</td>
                  </tr>
                  {exp&&det&&<tr style={{borderBottom:i<runs.length-1?`1px solid ${T.border}`:"none"}}><td colSpan={5} style={{padding:"4px 16px 14px 40px",background:T.bgElevated}}>
                    <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(180px,1fr))",gap:10}}>
                      {["Schema","Semantics","Quality","Policies","SLA"].map(sec=>{const d=det[sec];if(!d)return null;return (
                        <div key={sec} style={{padding:"9px 11px",background:T.bgSurface,border:`1px solid ${d.pass?T.border:T.rose+"33"}`,borderRadius:8}}>
                          <div style={{display:"flex",alignItems:"center",gap:7,marginBottom:(d.items&&d.items.length)?6:0}}>
                            <span style={{color:d.pass?"#16a34a":T.rose,display:"flex"}}>{d.pass?<svg width="12" height="12" viewBox="0 0 16 16" fill="none"><path d="M3.5 8.5l3 3 6-6.5" stroke="currentColor" strokeWidth="1.9" strokeLinecap="round" strokeLinejoin="round"/></svg>:<svg width="12" height="12" viewBox="0 0 16 16" fill="none"><path d="M5 5l6 6M11 5l-6 6" stroke="currentColor" strokeWidth="1.9" strokeLinecap="round"/></svg>}</span>
                            <span style={{fontSize:12,fontWeight:700,color:T.text}}>{sec}</span>
                          </div>
                          {(d.items&&d.items.length>0)&&<div style={{display:"flex",flexDirection:"column",gap:3,paddingLeft:19}}>{d.items.map((it,k)=><span key={k} style={{fontSize:11,color:T.rose}}>• {it}</span>)}</div>}
                        </div>);})}
                    </div>
                  </td></tr>}
                  </React.Fragment>;})}
              </tbody>
            </table>}
      </Card2>
    );})()}

    {/* ── Contract tab (definition) ── */}
    {tab==="contract"&&<>
    {/* ── 1. Schema ── */}
    {(()=>{
      const schemaMissing = v.schema.filter(c=>c.required&&!c.exists);
      const schemaFailing = schemaMissing.length > 0;
      return (
      <Section title="Schema" pass={schemaFailing?false:null}>
      {schemaFailing&&(
        <div style={{marginBottom:12,padding:"11px 14px",background:"rgba(239,68,68,.07)",border:`1px solid ${T.rose}33`,borderRadius:9}}>
          <div style={{display:"flex",alignItems:"flex-start",gap:10}}>
            <svg width="15" height="15" viewBox="0 0 16 16" fill="none" style={{color:T.rose,flexShrink:0,marginTop:1}}><circle cx="8" cy="8" r="6.5" stroke="currentColor" strokeWidth="1.4"/><path d="M8 5v3.5M8 10.5v.5" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round"/></svg>
            <div style={{flex:1,minWidth:0}}>
              <div style={{fontSize:12.5,fontWeight:700,color:T.rose,marginBottom:2}}>Schema mismatch detected</div>
              <div style={{fontSize:11.5,color:T.textSub,lineHeight:1.5}}>{schemaMissing.length} required column{schemaMissing.length>1?"s":""} missing from the live asset: <span style={{fontFamily:"'Geist Mono',monospace",fontWeight:600}}>{schemaMissing.map(c=>c.name).join(", ")}</span>. Investigate whether this is an intentional producer change or a breaking change.</div>
            </div>
          </div>
          <div style={{marginTop:8,paddingLeft:25}}>
            <span style={{fontSize:11,color:T.textMuted}}>Review this in your Workspace to take action.</span>
          </div>
        </div>
      )}
      <div style={{fontSize:11.5,color:T.textMuted,marginBottom:10}}>Producers cannot change these columns without publishing a new contract version.</div>
      <table style={{width:"100%",borderCollapse:"collapse"}}>
        <thead><tr style={{borderBottom:`1px solid ${T.border}`}}>
          {["Column","Data Type","Constraint","Required"].map(h=><th key={h} style={{padding:"7px 10px",fontSize:10,fontWeight:700,color:T.textMuted,textAlign:"left",textTransform:"uppercase",letterSpacing:.5}}>{h}</th>)}
        </tr></thead>
        <tbody>
          {v.schema.map((c,i)=>(
            <tr key={c.name} style={{borderBottom:i<v.schema.length-1?`1px solid ${T.border}`:"none"}}>
              <td style={{padding:"8px 10px",...mono,fontSize:12,fontWeight:600,color:T.text}}>{c.name}{c.required&&!c.exists&&<span style={{fontSize:9.5,fontWeight:700,color:T.rose,marginLeft:7,padding:"1px 6px",borderRadius:4,background:T.roseDim,border:`1px solid ${T.rose}33`}}>MISSING</span>}</td>
              <td style={{padding:"8px 10px",...mono,fontSize:11.5,color:T.blue}}>{c.type}</td>
              <td style={{padding:"8px 10px",fontSize:11.5,color:T.textSub}}>{c.constraint}</td>
              <td style={{padding:"8px 10px"}}>{c.required?<span style={{fontSize:10.5,fontWeight:700,color:"#16a34a"}}>Required</span>:<span style={{fontSize:10.5,color:T.textMuted}}>Optional</span>}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </Section>);})()}

    {/* ── 2 & 4: Quality + Semantics ── */}
    <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:16}}>
      <Section title="Quality Assertions" pass={sp.Quality}>
        {!sp.Quality&&v.quality.some(q=>!q.pass)&&(
          <div style={{marginBottom:12,padding:"11px 14px",background:"rgba(239,68,68,.07)",border:`1px solid ${T.rose}33`,borderRadius:9}}>
            <div style={{fontSize:12.5,fontWeight:700,color:T.rose,marginBottom:2}}>{v.quality.filter(q=>!q.pass).length} quality check{v.quality.filter(q=>!q.pass).length>1?"s":""} failing</div>
            <div style={{fontSize:11.5,color:T.textSub,marginBottom:10,lineHeight:1.5}}>Investigate the root cause before resolving. A DQ incident has been opened and your inbox has been notified.</div>
            <div style={{display:"flex",gap:8}}>
              <button onClick={()=>onToast&&onToast("Navigating to DQ Incidents — incident opened for this contract","info")}
                style={{display:"inline-flex",alignItems:"center",gap:6,padding:"6px 12px",borderRadius:7,background:T.bgSurface,border:`1px solid ${T.border}`,color:T.text,fontSize:12,fontWeight:600,cursor:"pointer"}}
                onMouseEnter={e=>e.currentTarget.style.background=T.bgHover} onMouseLeave={e=>e.currentTarget.style.background=T.bgSurface}>
                <svg width="12" height="12" viewBox="0 0 16 16" fill="none"><circle cx="8" cy="8" r="6" stroke="currentColor" strokeWidth="1.4"/><path d="M8 5v3.5M8 10.2v.5" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round"/></svg>
                View DQ Incident
              </button>
            </div>
          </div>
        )}
        <div style={{fontSize:11.5,color:T.textMuted,marginBottom:10}}>Linked to live data-quality test cases — status reflects the latest run.</div>
        <div style={{display:"flex",flexDirection:"column",gap:7}}>
          {v.quality.length===0&&<div style={{fontSize:12,color:T.textMuted,fontStyle:"italic"}}>No quality tests attached.</div>}
          {v.quality.map((qa,i)=>(
            <div key={i} style={{display:"flex",alignItems:"center",gap:9,padding:"7px 10px",background:T.bgElevated,borderRadius:8,border:`1px solid ${qa.pass?T.border:T.rose+"33"}`}}>
              <span style={{color:qa.pass?"#16a34a":T.rose,display:"flex",flexShrink:0}}>{qa.pass?<svg width="13" height="13" viewBox="0 0 16 16" fill="none"><path d="M3.5 8.5l3 3 6-6.5" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"/></svg>:<svg width="13" height="13" viewBox="0 0 16 16" fill="none"><path d="M5 5l6 6M11 5l-6 6" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round"/></svg>}</span>
              <span style={{fontSize:12.5,color:T.text,flex:1}}>{qa.name}</span>
              {qa.status&&<span style={{fontSize:10,fontWeight:700,color:qa.status==="Success"?"#16a34a":qa.status==="Failed"?T.rose:T.amber}}>{qa.status}</span>}
            </div>
          ))}
        </div>
      </Section>
      <Section title="Semantics" pass={sp.Semantics}>
        {!sp.Semantics&&(
          <div style={{marginBottom:12,padding:"11px 14px",background:"rgba(245,158,11,.07)",border:`1px solid ${T.amber}44`,borderRadius:9}}>
            <div style={{fontSize:12.5,fontWeight:700,color:T.amber,marginBottom:2}}>Semantic definitions incomplete</div>
            <div style={{fontSize:11.5,color:T.textSub,lineHeight:1.5}}>One or more required metadata fields are missing. Review this in your Workspace to take action.</div>
          </div>
        )}
        <div style={{fontSize:11.5,color:T.textMuted,marginBottom:10}}>Mandatory metadata — validated against this asset's live metadata.</div>
        <div style={{display:"flex",flexDirection:"column",gap:7}}>
          {v.semantics.map((s,i)=>(
            <div key={i} style={{display:"flex",alignItems:"center",gap:9}}>
              <span style={{color:s.pass?"#16a34a":T.rose,display:"flex"}}>{s.pass?<svg width="13" height="13" viewBox="0 0 16 16" fill="none"><path d="M3.5 8.5l3 3 6-6.5" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"/></svg>:<svg width="13" height="13" viewBox="0 0 16 16" fill="none"><path d="M5 5l6 6M11 5l-6 6" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round"/></svg>}</span>
              <span style={{fontSize:12.5,color:T.textSub}}>{s.rule}</span>
            </div>
          ))}
        </div>
      </Section>
    </div>

    {/* ── Policies (governance from Policy Manager) ── */}
    <Section title="Policies" pass={(contract.policies||[]).length?sp.Policies:null}>
      {(contract.policies||[]).length>0&&!sp.Policies&&(()=>{
        const breached=(v.policies||[]).filter(p=>!p.pass);
        return breached.length>0&&(
          <div style={{marginBottom:12,padding:"11px 14px",background:"rgba(239,68,68,.07)",border:`1px solid ${T.rose}33`,borderRadius:9}}>
            <div style={{fontSize:12.5,fontWeight:700,color:T.rose,marginBottom:2}}>{breached.length} policy breach{breached.length>1?"es":""} detected</div>
            <div style={{fontSize:11.5,color:T.textSub,marginBottom:10,lineHeight:1.5}}>The following policies have active violations: <span style={{fontWeight:600}}>{breached.map(p=>p.name).join(", ")}</span>. Review in Policy Manager or escalate to the domain owner.</div>
            <div style={{display:"flex",gap:8}}>
              <button onClick={()=>onToast&&onToast("Navigating to Policy Manager — review the breached policy violations","info")}
                style={{display:"inline-flex",alignItems:"center",gap:6,padding:"6px 12px",borderRadius:7,background:T.bgSurface,border:`1px solid ${T.border}`,color:T.text,fontSize:12,fontWeight:600,cursor:"pointer"}}
                onMouseEnter={e=>e.currentTarget.style.background=T.bgHover} onMouseLeave={e=>e.currentTarget.style.background=T.bgSurface}>
                <svg width="12" height="12" viewBox="0 0 16 16" fill="none"><path d="M8 1.5l5 2v4c0 3.2-2.1 5.6-5 6.5-2.9-.9-5-3.3-5-6.5v-4l5-2z" stroke="currentColor" strokeWidth="1.3" strokeLinejoin="round"/></svg>
                View Policy Violation
              </button>
            </div>
          </div>
        );
      })()}
      <div style={{fontSize:11.5,color:T.textMuted,marginBottom:10}}>Governance policies from Policy Manager that this contract enforces — a policy with open violations fails the check.</div>
      {(v.policies||[]).length===0
        ? <div style={{fontSize:12,color:T.textMuted,fontStyle:"italic"}}>No policies attached.</div>
        : <div style={{display:"flex",flexDirection:"column",gap:7}}>
            {(v.policies||[]).map((p,i)=>(
              <div key={i} style={{display:"flex",alignItems:"center",gap:10,padding:"9px 11px",background:T.bgElevated,borderRadius:8,border:`1px solid ${p.pass?T.border:T.rose+"33"}`}}>
                <span style={{display:"flex",color:p.pass?"#16a34a":T.rose,flexShrink:0}}>{p.pass?<svg width="13" height="13" viewBox="0 0 16 16" fill="none"><path d="M3.5 8.5l3 3 6-6.5" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"/></svg>:<svg width="13" height="13" viewBox="0 0 16 16" fill="none"><path d="M5 5l6 6M11 5l-6 6" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round"/></svg>}</span>
                <span style={{fontSize:12.5,fontWeight:600,color:T.text,flex:1}}>{p.name}</span>
                {p.category&&<span style={{fontSize:10.5,color:T.textMuted}}>{p.category}</span>}
                {p.violations>0&&<span style={{fontSize:9.5,fontWeight:700,padding:"1px 7px",borderRadius:5,background:T.roseDim,color:T.rose}}>{p.violations} violation{p.violations>1?"s":""}</span>}
              </div>
            ))}
          </div>}
    </Section>

    {/* ── SLA — each metric explained ── */}
    <Section title="SLA" pass={v.sla&&v.sla.evaluable?sp.SLA:null}>
      {/* Freshness result — the one SLA metric we actively validate against the live asset */}
      {v.sla&&(
        <div style={{marginBottom:12,padding:"11px 14px",borderRadius:9,
          background:!v.sla.evaluable?T.bgElevated:(v.sla.pass?"rgba(22,163,74,.07)":"rgba(239,68,68,.07)"),
          border:`1px solid ${!v.sla.evaluable?T.border:(v.sla.pass?"#16a34a33":T.rose+"33")}`}}>
          <div style={{display:"flex",alignItems:"flex-start",gap:9}}>
            <span style={{display:"flex",flexShrink:0,marginTop:1,color:!v.sla.evaluable?T.textMuted:(v.sla.pass?"#16a34a":T.rose)}}>
              {!v.sla.evaluable
                ? <svg width="14" height="14" viewBox="0 0 16 16" fill="none"><circle cx="8" cy="8" r="6.5" stroke="currentColor" strokeWidth="1.3"/><path d="M8 5v3.5M8 10.5v.5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round"/></svg>
                : v.sla.pass
                  ? <svg width="14" height="14" viewBox="0 0 16 16" fill="none"><path d="M3.5 8.5l3 3 6-6.5" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"/></svg>
                  : <svg width="14" height="14" viewBox="0 0 16 16" fill="none"><path d="M5 5l6 6M11 5l-6 6" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round"/></svg>}
            </span>
            <div style={{flex:1,minWidth:0}}>
              <div style={{fontSize:12.5,fontWeight:700,marginBottom:2,color:!v.sla.evaluable?T.textSub:(v.sla.pass?"#16a34a":T.rose)}}>
                {!v.sla.evaluable?"Freshness not evaluated":(v.sla.pass?"Freshness within SLA":"Freshness SLA breached")}
              </div>
              <div style={{fontSize:11.5,color:T.textSub,lineHeight:1.5}}>{v.sla.reason}{v.sla.evaluable&&v.sla.refreshColumn?<> · measured on <span style={{...mono,color:T.textSub}}>{v.sla.refreshColumn}</span></>:null}</div>
            </div>
          </div>
        </div>
      )}
      <div style={{fontSize:11.5,color:T.textMuted,marginBottom:12}}>The service-level guarantees consumers can rely on. Freshness is validated on each run; the rest are declared guarantees.</div>
      <div style={{display:"flex",flexDirection:"column",gap:10}}>
        {[
          {k:"Refresh Frequency", v:contract.sla.refreshInterval?`Every ${contract.sla.refreshInterval} ${contract.sla.refreshUnit}${contract.sla.refreshInterval>1?"s":""}`:"—", d:"How often the producer promises to update this data."},
          {k:"Max Latency", v:contract.sla.latencyValue!=null?`${contract.sla.latencyValue} ${contract.sla.latencyUnit}`:"—", d:"The longest acceptable delay between data being generated at the source and becoming available here."},
          {k:"Availability", v:contract.sla.availabilityTime?`${contract.sla.availabilityTime} ${contract.sla.availabilityTz}`:"—", d:"The time of day by which the refreshed data is guaranteed to be ready for consumers."},
          {k:"Retention", v:contract.sla.retentionPeriod!=null?`${contract.sla.retentionPeriod} ${contract.sla.retentionUnit}`:"—", d:"How long the data is kept before it is archived or purged."},
          {k:"Refresh Column", v:contract.sla.refreshColumn||"—", d:"The timestamp column used to measure freshness and detect whether a refresh actually landed."},
        ].map(row=>(
          <div key={row.k} style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",gap:16,paddingBottom:10,borderBottom:`1px solid ${T.border}`}}>
            <div style={{minWidth:0}}>
              <div style={{fontSize:12.5,fontWeight:600,color:T.text}}>{row.k}</div>
              <div style={{fontSize:11,color:T.textMuted,marginTop:2,lineHeight:1.5,maxWidth:520}}>{row.d}</div>
            </div>
            <span style={{...mono,fontSize:12.5,fontWeight:600,color:T.text,whiteSpace:"nowrap",flexShrink:0}}>{row.v}</span>
          </div>
        ))}
      </div>
    </Section>

    {/* ── Terms of Use ── */}
    {contract.terms&&<Section title="Terms of Use">
      {contract.terms.purpose&&<div style={{marginBottom:14}}>
        <div style={{fontSize:10.5,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:.5,marginBottom:5}}>Purpose</div>
        <div style={{fontSize:12.5,color:T.textSub,lineHeight:1.6}}>{contract.terms.purpose}</div>
      </div>}
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:16}}>
        <div>
          <div style={{fontSize:10.5,fontWeight:700,color:"#16a34a",textTransform:"uppercase",letterSpacing:.5,marginBottom:8}}>Allowed use cases</div>
          {(contract.terms.allowed||[]).map((a,i)=><div key={i} style={{fontSize:12,color:T.textSub,marginBottom:5}}>✓ {a}</div>)}
        </div>
        <div>
          <div style={{fontSize:10.5,fontWeight:700,color:T.rose,textTransform:"uppercase",letterSpacing:.5,marginBottom:8}}>Disallowed use cases</div>
          {(contract.terms.disallowed||[]).map((a,i)=><div key={i} style={{fontSize:12,color:T.textSub,marginBottom:5}}>✕ {a}</div>)}
        </div>
      </div>
    </Section>}
    </>}

    {/* ── Version History tab ── */}
    {tab==="versions"&&(
      <Section title="Version History">
      <div style={{fontSize:11.5,color:T.textMuted,marginBottom:14}}>Every revision is kept as a full snapshot. The newest version is current; each card shows what changed from the version before it.</div>
      <div style={{display:"flex",flexDirection:"column",gap:0}}>
        {allVersions.map((ver,i)=>{
          const older=allVersions[i+1];
          const changes=older?diffContracts(older,ver):[];
          const isLast=i===allVersions.length-1;
          const dc={add:{c:"#16a34a",s:"+",label:"added"},remove:{c:T.rose,s:"−",label:"removed"},change:{c:T.amber,s:"~",label:"changed"}};
          const counts={add:changes.filter(c=>c.t==="add").length,remove:changes.filter(c=>c.t==="remove").length,change:changes.filter(c=>c.t==="change").length};
          const snap=[
            {label:"Schema",val:`${(ver.schema||[]).length} columns`},
            {label:"Quality",val:`${(ver.quality||[]).length} tests`},
            {label:"Policies",val:`${(ver.policies||[]).length} policies`},
            {label:"SLA refresh",val:ver.sla?.refreshInterval?`every ${ver.sla.refreshInterval} ${ver.sla.refreshUnit}${ver.sla.refreshInterval>1?"s":""}`:"—"},
          ];
          return <div key={ver.version+i} style={{display:"flex",gap:14,paddingBottom:isLast?0:18}}>
            {/* rail */}
            <div style={{display:"flex",flexDirection:"column",alignItems:"center",flexShrink:0}}>
              <span style={{width:13,height:13,borderRadius:"50%",background:ver.current?T.accent:T.bgSurface,border:`2px solid ${ver.current?T.accent:T.borderLight}`,marginTop:5}}/>
              {!isLast&&<span style={{width:2,flex:1,background:T.border,marginTop:4}}/>}
            </div>
            {/* card */}
            <div style={{flex:1,minWidth:0,background:T.bgElevated,border:`1px solid ${ver.current?T.accent+"44":T.border}`,borderRadius:11,padding:"13px 15px"}}>
              <div style={{display:"flex",alignItems:"center",gap:8,flexWrap:"wrap"}}>
                <span style={{...mono,fontSize:14,fontWeight:700,color:T.text}}>v{ver.version}</span>
                {ver.current&&<span style={{fontSize:9.5,fontWeight:700,padding:"1px 7px",borderRadius:5,background:T.accentDim,color:T.accent,border:`1px solid ${T.accent}33`}}>CURRENT</span>}
                <span style={{flex:1}}/>
                <span style={{fontSize:11,color:T.textMuted}}>{ver.by} · {ver.at}</span>
              </div>
              {ver.note&&<div style={{fontSize:12,color:T.textSub,marginTop:5,lineHeight:1.5}}>{ver.note}</div>}
              {/* change summary chips */}
              {!isLast&&changes.length>0&&<div style={{display:"flex",gap:6,flexWrap:"wrap",marginTop:9}}>
                {["add","remove","change"].map(t=>counts[t]>0?<span key={t} style={{fontSize:10.5,fontWeight:700,padding:"2px 8px",borderRadius:5,background:dc[t].c+"14",color:dc[t].c,border:`1px solid ${dc[t].c}33`}}>{counts[t]} {dc[t].label}</span>:null)}
              </div>}
              {/* detailed diff */}
              <div style={{marginTop:10,display:"flex",flexDirection:"column",gap:4}}>
                {isLast
                  ? <div style={{fontSize:11.5,color:T.textMuted,fontStyle:"italic"}}>Initial version — baseline of the contract.</div>
                  : changes.length===0
                    ? <div style={{fontSize:11.5,color:T.textMuted,fontStyle:"italic"}}>No definition changes from the previous version.</div>
                    : changes.map((ch,k)=>(
                      <div key={k} style={{display:"flex",alignItems:"center",gap:8,fontSize:12}}>
                        <span style={{...mono,fontWeight:800,color:dc[ch.t].c,width:12,textAlign:"center",flexShrink:0}}>{dc[ch.t].s}</span>
                        <span style={{color:T.textSub}}>{ch.label}</span>
                      </div>
                    ))}
              </div>
              {/* snapshot summary */}
              <div style={{display:"flex",gap:20,flexWrap:"wrap",marginTop:12,paddingTop:11,borderTop:`1px solid ${T.border}`}}>
                {snap.map(s=>(
                  <div key={s.label}>
                    <div style={{fontSize:9.5,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:.5}}>{s.label}</div>
                    <div style={{fontSize:11.5,color:T.textSub,marginTop:2}}>{s.val}</div>
                  </div>
                ))}
              </div>
            </div>
          </div>;
        })}
      </div>
    </Section>
    )}

    {/* ── Edit / create wizard (left drawer) ── */}
    {wizard&&<ContractWizard asset={asset} onToast={onToast} existing={wizard==="edit"?contract:null} onClose={()=>setWizard(false)} onSubmit={submitWizard}/>}

    {/* ── Schedule validation modal ── */}
    {scheduleModal&&createPortal(<ScheduleControl title="Validation schedule" subtitle={`How often "${contract.name}" is validated against the live asset`} schedule={contract.schedule} onClose={()=>setScheduleModal(false)} onSave={saveSchedule} onRemove={removeSchedule} running={validating}/>,document.body)}

    {/* ── Delete confirm ── */}
    {deleteConfirm&&createPortal(
      <>
        <div onClick={()=>setDeleteConfirm(false)} style={{position:"fixed",inset:0,zIndex:1100,background:"rgba(0,0,0,.5)",backdropFilter:"blur(2px)"}}/>
        <div style={{position:"fixed",top:"50%",left:"50%",transform:"translate(-50%,-50%)",zIndex:1101,background:T.bgSurface,border:`1px solid ${T.border}`,borderRadius:16,boxShadow:"0 32px 80px rgba(0,0,0,.45)",width:420,overflow:"hidden"}}>
          <div style={{padding:"18px 20px"}}>
            <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:10}}>
              <span style={{width:34,height:34,borderRadius:9,background:T.roseDim,display:"flex",alignItems:"center",justifyContent:"center",color:T.rose,flexShrink:0}}><svg width="17" height="17" viewBox="0 0 16 16" fill="none"><path d="M3 4.5h10M6.5 4V2.8h3V4M5 4.5l.5 8.5h5l.5-8.5" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" strokeLinejoin="round"/></svg></span>
              <div style={{fontSize:15,fontWeight:700,color:T.text}}>Delete contract?</div>
            </div>
            <div style={{fontSize:12.5,color:T.textSub,lineHeight:1.6}}>This permanently removes <span style={{...mono,color:T.text}}>{contract.name}</span> and its entire version history. This cannot be undone.</div>
          </div>
          <div style={{padding:"12px 20px",borderTop:`1px solid ${T.border}`,display:"flex",justifyContent:"flex-end",gap:8}}>
            <Btn small ghost onClick={()=>setDeleteConfirm(false)}>Cancel</Btn>
            <Btn small variant="danger" onClick={doDelete}>Delete contract</Btn>
          </div>
        </div>
      </>
    ,document.body)}
  </div>;
};

// Schedule validation modal — identical pattern to the Connectors "Sync Schedule"
// ════════════════ SHARED SCHEDULE CONTROL ════════════════
// ONE schedule UI used everywhere (Data Quality, Policy, Data Contract, Connections) so
// the Run-now / Schedule experience is identical irrespective of section.
// Works on a structured schedule object {freq,time,day,cron,tz,enabled}; the caller's
// onSave(sched) decides how to persist (cron string, structured, etc).
const ScheduleControl = ({schedule,onClose,onSave,onRemove,title="Schedule",subtitle,onRunNow,running})=>{
  const [freq,setFreq]=useState(schedule?.freq||"daily");
  const [time,setTime]=useState(schedule?.time||"05:00");
  const [day,setDay]=useState(schedule?.day||"monday");
  const [cron,setCron]=useState(schedule?.cron||"0 5 * * *");
  const [tz,setTz]=useState(schedule?.tz||"UTC");
  const [enabled,setEnabled]=useState(schedule?.enabled!==false);
  const sched={freq,time,day,cron,tz,enabled};
  const cronStr=contractCron(sched);
  const nextRunLabel=()=>{
    if(freq==="once") return "After saving — one time only";
    if(freq==="hourly") return `Next run in ~1 hour (${tz})`;
    return `Next run: tomorrow ${freq==="weekly"?`(${day})`:""} ${time} ${tz}`;
  };
  return (
    <>
      <div onClick={onClose} style={{position:"fixed",inset:0,background:"rgba(0,0,0,.45)",zIndex:1300}}/>
      <div style={{position:"fixed",top:"50%",left:"50%",transform:"translate(-50%,-50%)",width:460,maxWidth:"94vw",background:T.bgSurface,border:`1.5px solid ${T.border}`,borderRadius:14,zIndex:1301,boxShadow:"0 20px 60px rgba(0,0,0,.4)",padding:"24px 24px 20px"}}>
        {/* Header */}
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:18}}>
          <div>
            <div style={{fontSize:15,fontWeight:700,color:T.text,marginBottom:4}}>{title}</div>
            {subtitle&&<div style={{fontSize:12,color:T.textMuted}}>{subtitle}</div>}
          </div>
          <div style={{display:"flex",alignItems:"center",gap:10}}>
            <div style={{display:"flex",alignItems:"center",gap:6}}>
              <span style={{fontSize:11,color:enabled?T.accent:T.textMuted,fontWeight:600}}>Automatic: {enabled?"On":"Off"}</span>
              <div onClick={()=>setEnabled(v=>!v)} style={{width:32,height:18,borderRadius:9,background:enabled?T.accent:T.border,cursor:"pointer",position:"relative",transition:"background .2s",flexShrink:0}}>
                <div style={{position:"absolute",top:2,left:enabled?14:2,width:14,height:14,borderRadius:"50%",background:"#fff",transition:"left .2s",boxShadow:"0 1px 3px rgba(0,0,0,.2)"}}/>
              </div>
            </div>
            <button onClick={onClose} style={{background:"none",border:"none",cursor:"pointer",color:T.textMuted,fontSize:18,lineHeight:1,padding:2}}>×</button>
          </div>
        </div>
        {/* Frequency */}
        <div style={{marginBottom:14}}>
          <div style={{fontSize:11,fontWeight:600,color:T.textSub,marginBottom:8,textTransform:"uppercase",letterSpacing:"0.06em"}}>Frequency</div>
          <div style={{display:"grid",gridTemplateColumns:"repeat(5,1fr)",gap:6}}>
            {CONTRACT_SCHED_FREQS.map(f=>(
              <button key={f.k} onClick={()=>setFreq(f.k)}
                style={{padding:"8px 4px",borderRadius:8,border:`1.5px solid ${freq===f.k?T.accent:T.border}`,background:freq===f.k?T.accentDim:"transparent",color:freq===f.k?T.accent:T.textSub,fontSize:11.5,fontWeight:freq===f.k?600:400,cursor:"pointer",fontFamily:"inherit",transition:"all .12s"}}>
                {f.l}
              </button>
            ))}
          </div>
        </div>
        {/* Time picker */}
        {(freq==="daily"||freq==="weekly")&&(
          <div style={{marginBottom:14}}>
            <div style={{fontSize:11,fontWeight:600,color:T.textSub,marginBottom:8,textTransform:"uppercase",letterSpacing:"0.06em"}}>Run At</div>
            <input type="time" value={time} onChange={e=>setTime(e.target.value)}
              style={{padding:"8px 12px",background:T.bgElevated,border:`1.5px solid ${T.border}`,borderRadius:8,color:T.text,fontSize:13,outline:"none",fontFamily:"'Geist Mono',monospace",width:"100%",boxSizing:"border-box"}}/>
          </div>
        )}
        {/* Day picker */}
        {freq==="weekly"&&(
          <div style={{marginBottom:14}}>
            <div style={{fontSize:11,fontWeight:600,color:T.textSub,marginBottom:8,textTransform:"uppercase",letterSpacing:"0.06em"}}>Day of Week</div>
            <div style={{display:"flex",gap:5,flexWrap:"wrap"}}>
              {CONTRACT_WEEKDAYS.map(d=>(
                <button key={d} onClick={()=>setDay(d)}
                  style={{padding:"5px 10px",borderRadius:6,border:`1.5px solid ${day===d?T.accent:T.border}`,background:day===d?T.accentDim:"transparent",color:day===d?T.accent:T.textSub,fontSize:11,fontWeight:day===d?600:400,cursor:"pointer",fontFamily:"inherit",textTransform:"capitalize"}}>
                  {d.slice(0,3)}
                </button>
              ))}
            </div>
          </div>
        )}
        {/* Custom cron */}
        {freq==="custom"&&(
          <div style={{marginBottom:14}}>
            <div style={{fontSize:11,fontWeight:600,color:T.textSub,marginBottom:8,textTransform:"uppercase",letterSpacing:"0.06em"}}>Cron Expression</div>
            <input value={cron} onChange={e=>setCron(e.target.value)} placeholder="0 5 * * 1-5"
              style={{width:"100%",padding:"8px 12px",background:T.bgElevated,border:`1.5px solid ${T.border}`,borderRadius:8,color:T.text,fontSize:13,outline:"none",fontFamily:"'Geist Mono',monospace",boxSizing:"border-box"}}/>
            <div style={{fontSize:10.5,color:T.textMuted,marginTop:5}}>Standard 5-field cron: minute hour day month weekday</div>
          </div>
        )}
        {/* Timezone */}
        {freq!=="once"&&(
          <div style={{marginBottom:14}}>
            <div style={{fontSize:11,fontWeight:600,color:T.textSub,marginBottom:8,textTransform:"uppercase",letterSpacing:"0.06em"}}>Timezone</div>
            <select value={tz} onChange={e=>setTz(e.target.value)}
              style={{width:"100%",padding:"8px 12px",background:T.bgElevated,border:`1.5px solid ${T.border}`,borderRadius:8,color:T.text,fontSize:12.5,outline:"none",cursor:"pointer",boxSizing:"border-box"}}>
              {CONTRACT_TZ_OPTS.map(z=><option key={z} value={z}>{z}</option>)}
            </select>
          </div>
        )}
        {/* Preview */}
        {freq!=="once"?(
          <div style={{padding:"10px 14px",borderRadius:8,background:T.bgElevated,border:`1px solid ${T.border}`,marginBottom:18}}>
            <div style={{fontSize:10.5,color:T.textMuted,marginBottom:4}}>Cron preview</div>
            <div style={{fontSize:12,fontFamily:"'Geist Mono',monospace",color:T.accent,marginBottom:4}}>{cronStr}</div>
            <div style={{fontSize:11,color:T.textMuted}}>Next run: <strong style={{color:T.text}}>{nextRunLabel()}</strong></div>
          </div>
        ):(
          <div style={{padding:"10px 14px",borderRadius:8,background:`${T.amber}0a`,border:`1px solid ${T.amber}30`,marginBottom:18,fontSize:11.5,color:T.textSub,lineHeight:1.5}}>
            This contract will validate one time immediately after saving. No recurring schedule will be set.
          </div>
        )}
        <div style={{display:"flex",gap:8,alignItems:"center"}}>
          {onRunNow&&<button onClick={()=>onRunNow()} disabled={running} title="Run once now, independent of the schedule" style={{display:"inline-flex",alignItems:"center",gap:6,padding:"8px 14px",borderRadius:8,border:`1px solid ${T.border}`,background:T.bgElevated,color:running?T.textMuted:T.textSub,fontSize:12,fontWeight:600,cursor:running?"default":"pointer",fontFamily:"inherit"}}>
            {running?<span style={{display:"inline-block",width:11,height:11,borderRadius:"50%",border:`1.5px solid ${T.textMuted}`,borderTopColor:"transparent",animation:"spin 0.7s linear infinite"}}/>:<svg width="11" height="11" viewBox="0 0 16 16" fill="none"><path d="M4 3l9 5-9 5V3z" fill="currentColor"/></svg>}
            {running?"Running…":"Run now"}
          </button>}
          <div style={{flex:1}}/>
          {schedule&&onRemove&&<button onClick={onRemove} style={{padding:"8px 14px",borderRadius:8,border:`1px solid ${T.rose}40`,background:"transparent",color:T.rose,fontSize:12,cursor:"pointer",fontFamily:"inherit"}}>Remove</button>}
          <button onClick={onClose} style={{padding:"8px 16px",borderRadius:8,border:`1px solid ${T.border}`,background:"transparent",color:T.textSub,fontSize:12,cursor:"pointer",fontFamily:"inherit"}}>Cancel</button>
          <button onClick={()=>onSave(sched)} style={{padding:"8px 20px",borderRadius:8,border:"none",background:T.accent,color:"#fff",fontSize:12,fontWeight:600,cursor:"pointer",fontFamily:"inherit"}}>Save Schedule</button>
        </div>
      </div>
    </>
  );
};

// Add/Edit-contract wizard (UI-based, no YAML — mirrors OpenMetadata)
// Standard governance metadata rules — consistent "<field> must be <verb>" wording, covering the full set we validate.
const CONTRACT_SEMANTIC_RULES=["Owners must be assigned","Stewards must be assigned","Description must be provided","Domain must be assigned","Tier must be classified","Tags must be applied"];
const SEMANTIC_KEY={"Owners must be assigned":"owners","Stewards must be assigned":"stewards","Description must be provided":"description","Domain must be assigned":"domain","Tier must be classified":"tier","Tags must be applied":"tags"};
const CONTRACT_SECTIONS=[
  {key:"details",label:"Contract Details"},
  {key:"schema",label:"Schema"},
  {key:"semantics",label:"Semantics"},
  {key:"quality",label:"Quality"},
  {key:"policies",label:"Policies"},
  {key:"sla",label:"SLA"},
  {key:"terms",label:"Terms of Use"},
];
// Directory used for the consumer picker (same handles used as owners/stewards).
const CONTRACT_USERS=["maya.chen","sarah.kim","alex.wu","dev.patel","lisa.ray","priya.nair","james.oh","arjun.sharma"];
// ── Validation schedule — same vocabulary & cron builder as the Connectors "Sync Schedule" ──
const CONTRACT_SCHED_FREQS=[{k:"hourly",l:"Hourly"},{k:"daily",l:"Daily"},{k:"weekly",l:"Weekly"},{k:"custom",l:"Custom"}];
const CONTRACT_TZ_OPTS=["UTC","US/Eastern","US/Central","US/Pacific","Europe/London","Asia/Kolkata","Asia/Singapore"];
const CONTRACT_WEEKDAYS=["monday","tuesday","wednesday","thursday","friday","saturday","sunday"];
function contractCron(s){
  if(!s) return "";
  if(s.freq==="once")   return "— run once —";
  if(s.freq==="hourly") return "0 * * * *";
  const [h,m]=(s.time||"05:00").split(":");
  if(s.freq==="daily")  return `${m||"0"} ${h||"5"} * * *`;
  if(s.freq==="weekly"){const days={monday:1,tuesday:2,wednesday:3,thursday:4,friday:5,saturday:6,sunday:0};return `${m||"0"} ${h||"5"} * * ${days[s.day]??1}`;}
  return s.cron||"0 5 * * *";
}
// Human "next run" label for sections that persist a cron string + nextRun (DQ, Policy, Connections).
function scheduleNextRun(s){
  if(!s||s.enabled===false) return "Paused — next run when re-enabled";
  if(s.freq==="hourly") return `Next run in ~1 hour (${s.tz||"UTC"})`;
  if(s.freq==="custom")  return `On cron ${s.cron||"0 5 * * *"} (${s.tz||"UTC"})`;
  if(s.freq==="weekly")  return `Next run: ${s.day||"monday"} ${s.time||"05:00"} ${s.tz||"UTC"}`;
  return `Next run: daily ${s.time||"05:00"} ${s.tz||"UTC"}`;
}
function contractScheduleLabel(s){
  if(!s) return "";
  if(s.freq==="once")   return "once, on demand";
  if(s.freq==="hourly") return `hourly (${s.tz||"UTC"})`;
  if(s.freq==="custom") return `on cron ${s.cron||"0 5 * * *"} (${s.tz||"UTC"})`;
  if(s.freq==="weekly") return `every ${s.day||"monday"} at ${s.time||"05:00"} ${s.tz||"UTC"}`;
  return `daily at ${s.time||"05:00"} ${s.tz||"UTC"}`;
}
function contractScheduleShort(s){
  if(!s) return "";
  if(s.freq==="hourly") return "hourly";
  if(s.freq==="weekly") return `weekly ${(s.day||"mon").slice(0,3)}`;
  if(s.freq==="custom") return "custom";
  if(s.freq==="once")   return "once";
  return `daily ${s.time||"05:00"}`;
}
// ── Shared Run-now / Schedule pattern button — reused across Contracts, Policy, Data Quality, Connections.
// Accepts either a structured contract `schedule` object, or explicit `state`/`label` (for cron-string sections).
const ScheduleButton = ({schedule, state, label, onClick, title="Schedule", small})=>{
  let st=state, lab=label;
  if(!st && schedule!==undefined){
    if(!schedule) st="none";
    else if(schedule.enabled===false) st="paused";
    else if(schedule.freq==="once"||!schedule.freq) st="none";
    else { st="on"; lab=lab||`Scheduled · ${contractScheduleShort(schedule)}`; }
  }
  st=st||"none";
  const on=st==="on", paused=st==="paused";
  const bg=on?"#16a34a14":paused?T.amberDim:T.bgElevated;
  const col=on?"#16a34a":paused?T.amber:T.textSub;
  const bd=on?"#16a34a40":paused?T.amber+"55":T.border;
  const text=lab||(on?"Scheduled":paused?"Schedule paused":"Schedule");
  return <button onClick={onClick} title={title} style={{display:"inline-flex",alignItems:"center",gap:6,padding:small?"5px 11px":"6px 12px",borderRadius:8,background:bg,color:col,border:`1px solid ${bd}`,fontSize:small?11.5:12.5,fontWeight:600,cursor:"pointer",fontFamily:"inherit",whiteSpace:"nowrap"}}>
    <svg width="13" height="13" viewBox="0 0 16 16" fill="none" style={{flexShrink:0}}><circle cx="8" cy="8.5" r="5.5" stroke="currentColor" strokeWidth="1.3"/><path d="M8 5.5v3l2 1.2" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round"/></svg>
    {text}
  </button>;
};
const ContractWizard = ({asset,existing,onClose,onSubmit,onToast})=>{
  const cols=(typeof ASSET_COLUMNS!=="undefined" && ASSET_COLUMNS[asset.name])||[];
  const assetCases=(typeof DQ_TEST_CASES!=="undefined"?DQ_TEST_CASES:[]).filter(t=>t.table.endsWith("."+asset.name)||t.table===asset.name);
  const allPolicies=(typeof POLICIES!=="undefined"?POLICIES:[]);
  const tagCtx=useTagCtx();
  const classDefs=((tagCtx&&tagCtx.tagDefs)||(typeof INITIAL_TAG_DEFS!=="undefined"?INITIAL_TAG_DEFS:[])).filter(t=>t.category==="sensitivity");
  const isEdit=!!existing;
  const [sec,setSec]=useState("details");
  const [doneSet,setDoneSet]=useState(()=>new Set());  // sections confirmed via Next — drives the rail dots
  const [name,setName]=useState(existing?.name||`${asset.name}_contract`);
  const [desc,setDesc]=useState(existing?.description||"");
  const [schemaCols,setSchemaCols]=useState(existing?existing.schema.map(c=>c.name):cols.slice(0,5));
  const [semantics,setSemantics]=useState(existing?existing.semantics.filter(s=>s.key&&s.key!=="custom"&&CONTRACT_SEMANTIC_RULES.includes(s.rule)).map(s=>s.rule):["Owners must be assigned","Description must be provided"]);
  const [quality,setQuality]=useState(existing?existing.quality.map(q=>q.tcId).filter(Boolean):assetCases.slice(0,4).map(t=>t.id));
  const [qualitySearch,setQualitySearch]=useState("");
  const [policies,setPolicies]=useState(existing?.policies?existing.policies.map(p=>p.policyId):[]);
  const [policySearch,setPolicySearch]=useState("");
  const [termsPurpose,setTermsPurpose]=useState(existing?.terms?.purpose||"");
  const [termsAllowed,setTermsAllowed]=useState(existing?.terms?.allowed||["Internal analytics","Reporting"]);
  const [termsDisallowed,setTermsDisallowed]=useState(existing?.terms?.disallowed||["External redistribution"]);
  const [refreshInterval,setRefreshInterval]=useState(existing?.sla?.refreshInterval??1);
  const [refreshUnit,setRefreshUnit]=useState(existing?.sla?.refreshUnit||"Day");
  const [latencyValue,setLatencyValue]=useState(existing?.sla?.latencyValue??2);
  const [latencyUnit,setLatencyUnit]=useState(existing?.sla?.latencyUnit||"Hours");
  const [availTime,setAvailTime]=useState(existing?.sla?.availabilityTime||"09:00");
  const [availTz,setAvailTz]=useState(existing?.sla?.availabilityTz||"UTC");
  const [retentionPeriod,setRetentionPeriod]=useState(existing?.sla?.retentionPeriod??365);
  const [retentionUnit,setRetentionUnit]=useState(existing?.sla?.retentionUnit||"Days");
  const [refreshColumn,setRefreshColumn]=useState(existing?.sla?.refreshColumn||"");
  // Consumers = users who depend on this data (owners are the producing party).
  // Normalize any legacy {name,...} shape to plain handles.
  const [consumers,setConsumers]=useState(()=>(existing?.consumers||[]).map(c=>typeof c==="string"?c:c.name).filter(Boolean));
  const toggle=(arr,set,v)=>set(arr.includes(v)?arr.filter(x=>x!==v):[...arr,v]);
  const Lbl=({children,sub})=><div style={{marginBottom:8}}><div style={{fontSize:11.5,fontWeight:700,color:T.text}}>{children}</div>{sub&&<div style={{fontSize:11,color:T.textMuted,marginTop:2}}>{sub}</div>}</div>;
  const Pill=({active,onClick,children})=><button onClick={onClick} style={{padding:"6px 13px",borderRadius:99,fontSize:12,fontWeight:active?600:400,cursor:"pointer",background:active?T.accent:T.bgElevated,color:active?"#fff":T.textSub,border:`1px solid ${active?T.accent:T.border}`}}>{children}</button>;
  const inp={width:"100%",boxSizing:"border-box",padding:"9px 11px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:8,color:T.text,fontSize:12.5,outline:"none"};

  // ── per-section completeness drives the rail dots, Next, and Save ──
  const complete={
    details: !!name.trim(),
    schema: schemaCols.length>0,
    semantics: semantics.length>0,
    quality: true,   // optional
    policies: true,  // optional
    sla: String(refreshInterval).trim()!=="" && String(latencyValue).trim()!=="" && String(retentionPeriod).trim()!=="",
    terms: true,     // optional
  };
  const required=["details","schema","semantics","sla"];
  const allComplete=required.every(k=>complete[k]);
  const curIdx=CONTRACT_SECTIONS.findIndex(s=>s.key===sec);
  const isLast=curIdx===CONTRACT_SECTIONS.length-1;
  const nextKey=CONTRACT_SECTIONS[curIdx+1]?.key;
  const prevKey=CONTRACT_SECTIONS[curIdx-1]?.key;

  const build=()=>{
    const exCol=(c)=>existing?.schema?.find(s=>s.name===c);
    return {
      name:name.trim()||`${asset.name}_contract`,version:existing?.version||"1.0.0",status:existing?.status||"Draft",
      owners:existing?.owners||asset.owners||[asset.owner].filter(Boolean),
      stewards:existing?.stewards||asset.stewards||[asset.steward].filter(Boolean),
      description:desc.trim()||`Data contract for ${asset.name}.`,updated:"Just now",lastRun:existing?.lastRun||"Not yet run",
      consumers: consumers,
      validationMode: existing?.schedule ? "scheduled" : "ondemand",
      schedule: existing?.schedule||null,
      schema:schemaCols.map(c=>({name:c,type:exCol(c)?.type||"—",constraint:exCol(c)?.constraint||"NOT NULL",required:true})),
      semantics:semantics.map(r=>({key:SEMANTIC_KEY[r],rule:r})),
      quality:assetCases.filter(t=>quality.includes(t.id)).map(t=>({tcId:t.id,name:t.name})),
      policies:allPolicies.filter(p=>policies.includes(p.id)).map(p=>({policyId:p.id,name:p.name})),
      sla:{refreshInterval:Number(refreshInterval)||1,refreshUnit,latencyValue:Number(latencyValue)||0,latencyUnit,availabilityTime:availTime,availabilityTz:availTz,retentionPeriod:Number(retentionPeriod)||0,retentionUnit,refreshColumn},
      terms:{purpose:termsPurpose.trim(),allowed:termsAllowed,disallowed:termsDisallowed},
      runs:existing?.runs,
      history:existing?existing.history:[{at:"Just now",by:"You",action:"Contract created",note:"Draft"}],
      versions:existing?.versions,
    };
  };
  const runCheck=()=>{ const res=validateContract(build(),asset); onToast&&onToast(res.allPass?`Validation passed — all ${Object.keys(res.sections).length} checks green`:`Validation: ${res.failedSections.length} failing — ${res.failedSections.join(", ")}`,res.allPass?"success":"error"); };

  return createPortal(
    <div onClick={onClose} className="fadeIn" style={{position:"fixed",inset:0,zIndex:1000,background:"rgba(0,0,0,.5)",backdropFilter:"blur(2px)"}}>
      <div onClick={e=>e.stopPropagation()} className="slideInRight" style={{position:"absolute",top:0,right:0,bottom:0,width:880,maxWidth:"96vw",background:T.bgSurface,borderLeft:`1px solid ${T.border}`,boxShadow:"-12px 0 48px rgba(0,0,0,.32)",display:"flex",flexDirection:"column"}}>
        {/* header */}
        <div style={{padding:"14px 20px",borderBottom:`1px solid ${T.border}`,display:"flex",alignItems:"center",justifyContent:"space-between",gap:12,flexShrink:0,background:T.bgElevated}}>
          <div style={{minWidth:0}}>
            <div style={{fontSize:14.5,fontWeight:700,color:T.text}}>{isEdit?"Edit Data Contract":"Add Contract Details"}</div>
            <div style={{fontSize:11.5,color:T.textMuted,marginTop:2}}>Define the agreement for <span style={{fontFamily:"'Geist Mono',monospace",color:T.textSub}}>{asset.name}</span></div>
          </div>
          <button onClick={onClose} style={{width:30,height:30,borderRadius:8,background:T.bgHover,border:`1px solid ${T.border}`,color:T.textMuted,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>{Ic.x(12)}</button>
        </div>
        {/* body: section rail + content */}
        <div style={{flex:1,display:"flex",minHeight:0}}>
          <div style={{width:212,flexShrink:0,borderRight:`1px solid ${T.border}`,overflowY:"auto",padding:"14px 10px",display:"flex",flexDirection:"column",gap:3,background:T.bg}}>
            {CONTRACT_SECTIONS.map(s=>{
              const on=sec===s.key, done=doneSet.has(s.key), req=required.includes(s.key);
              return <button key={s.key} onClick={()=>setSec(s.key)} style={{display:"flex",alignItems:"center",gap:9,width:"100%",padding:"9px 11px",borderRadius:8,background:on?T.bgSurface:"transparent",border:`1px solid ${on?T.border:"transparent"}`,color:on?T.text:T.textMuted,fontSize:12.5,fontWeight:on?700:500,cursor:"pointer",textAlign:"left",boxShadow:on?"0 1px 2px rgba(0,0,0,.06)":"none"}}>
                <span style={{width:8,height:8,borderRadius:"50%",flexShrink:0,background:done?T.accent:T.borderLight}}/>
                <span style={{flex:1}}>{s.label}</span>
                {req&&!done&&<span style={{fontSize:13,color:T.textMuted,lineHeight:1}}>*</span>}
              </button>;
            })}
          </div>
          <div style={{flex:1,overflowY:"auto",padding:"22px 26px"}}>
            {sec==="details"&&<div style={{display:"flex",flexDirection:"column",gap:18,maxWidth:560}}>
              <div><div style={{fontSize:15,fontWeight:700,color:T.text}}>Contract Details</div><div style={{fontSize:12,color:T.textMuted,marginTop:3}}>The key information that identifies this contract.</div></div>
              <div><Lbl>Contract name <span style={{color:T.rose}}>*</span></Lbl><input value={name} onChange={e=>setName(e.target.value)} style={inp}/></div>
              <div><Lbl>Description</Lbl><textarea value={desc} onChange={e=>setDesc(e.target.value)} rows={4} placeholder="What this contract guarantees, and for whom…" style={{...inp,resize:"vertical",fontFamily:"inherit"}}/></div>
              {(()=>{
                const personChip=(u)=>(<span key={u} style={{display:"inline-flex",alignItems:"center",gap:7,padding:"3px 11px 3px 4px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:99,color:T.textSub,fontSize:12}}>
                  <span style={{width:20,height:20,borderRadius:6,background:T.accentDim,border:`1px solid ${T.accent}33`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:9,fontWeight:700,color:T.accent,flexShrink:0}}>{(u||"").split(".").map(x=>x[0]?.toUpperCase()||"").join("").slice(0,2)}</span>{u}
                </span>);
                const owners=(existing?.owners||asset.owners||[asset.owner]).filter(Boolean);
                const stewards=(existing?.stewards||asset.stewards||[asset.steward]).filter(Boolean);
                return <div style={{display:"flex",gap:32,flexWrap:"wrap"}}>
                  <div><Lbl>Owners</Lbl><div style={{display:"flex",gap:7,flexWrap:"wrap"}}>{owners.length?owners.map(personChip):<span style={{fontSize:12,color:T.textMuted,fontStyle:"italic"}}>None</span>}</div></div>
                  <div><Lbl>Stewards</Lbl><div style={{display:"flex",gap:7,flexWrap:"wrap"}}>{stewards.length?stewards.map(personChip):<span style={{fontSize:12,color:T.textMuted,fontStyle:"italic"}}>None</span>}</div></div>
                </div>;
              })()}
              {/* ── Consumers: the users who depend on this data. Owners are the producing party. ── */}
              <div style={{paddingTop:16,borderTop:`1px solid ${T.border}`}}>
                <Lbl sub="Users who depend on this data — they are notified when the contract changes. The owners above are the producing team.">Consumers</Lbl>
                <RuleMultiSelect flat={CONTRACT_USERS} selected={consumers} onChange={setConsumers} placeholder="Select users who consume this data…" mono/>
              </div>
            </div>}

            {sec==="schema"&&<div style={{maxWidth:620}}>
              <div style={{marginBottom:14}}><div style={{fontSize:15,fontWeight:700,color:T.text}}>Schema</div><div style={{fontSize:12,color:T.textMuted,marginTop:3}}>Required columns locked by the contract ({schemaCols.length} of {cols.length}).</div></div>
              <div style={{display:"flex",flexWrap:"wrap",gap:8}}>{cols.map(c=><Pill key={c} active={schemaCols.includes(c)} onClick={()=>toggle(schemaCols,setSchemaCols,c)}>{c}</Pill>)}</div>
            </div>}

            {sec==="semantics"&&<div style={{maxWidth:560}}>
              <div style={{marginBottom:14}}><div style={{fontSize:15,fontWeight:700,color:T.text}}>Semantics</div><div style={{fontSize:12,color:T.textMuted,marginTop:3}}>The standard governance-metadata rules this contract requires. Each is validated against the live asset.</div></div>
              <div style={{display:"flex",flexDirection:"column",gap:8}}>{CONTRACT_SEMANTIC_RULES.map(r=>(
                <label key={r} style={{display:"flex",alignItems:"center",gap:10,padding:"10px 12px",background:semantics.includes(r)?T.accentDim:T.bgElevated,border:`1px solid ${semantics.includes(r)?T.accent+"55":T.border}`,borderRadius:9,cursor:"pointer"}}>
                  <input type="checkbox" checked={semantics.includes(r)} onChange={()=>toggle(semantics,setSemantics,r)} style={{accentColor:T.accent}}/>
                  <span style={{fontSize:12.5,color:T.text}}>{r}</span>
                </label>))}</div>
            </div>}

            {sec==="quality"&&(()=>{
              const filtered=assetCases.filter(t=>t.name.toLowerCase().includes(qualitySearch.toLowerCase().trim())||(t.dim||"").toLowerCase().includes(qualitySearch.toLowerCase().trim()));
              return <div style={{maxWidth:620}}>
              <div style={{marginBottom:14}}><div style={{fontSize:15,fontWeight:700,color:T.text}}>Quality Assertions</div><div style={{fontSize:12,color:T.textMuted,marginTop:3}}>Search and attach data-quality tests already assigned to <span style={{fontFamily:"'Geist Mono',monospace",color:T.textSub}}>{asset.name}</span> ({quality.length} selected). Optional.</div></div>
              {assetCases.length===0?<div style={{fontSize:12.5,color:T.textMuted,padding:"16px 0"}}>No test cases exist for this asset yet. Create them in Data Quality › Tests first.</div>:<>
              <input value={qualitySearch} onChange={e=>setQualitySearch(e.target.value)} placeholder="Search this table's quality tests…" style={{...inp,marginBottom:10}}/>
              <div style={{display:"flex",flexDirection:"column",gap:8}}>
                {filtered.length===0&&<div style={{fontSize:12,color:T.textMuted,fontStyle:"italic",padding:"8px 0"}}>No tests match "{qualitySearch}".</div>}
                {filtered.map(t=>(
                <label key={t.id} style={{display:"flex",alignItems:"center",gap:10,padding:"10px 12px",background:quality.includes(t.id)?T.accentDim:T.bgElevated,border:`1px solid ${quality.includes(t.id)?T.accent+"55":T.border}`,borderRadius:9,cursor:"pointer"}}>
                  <input type="checkbox" checked={quality.includes(t.id)} onChange={()=>toggle(quality,setQuality,t.id)} style={{accentColor:T.accent}}/>
                  <DQStatusDot status={t.status}/>
                  <span style={{fontSize:12.5,color:T.text,flex:1}}>{t.name}</span>
                  <span style={{fontSize:10.5,color:T.textMuted}}>{t.dim}</span>
                </label>))}</div></>}
            </div>;})()}

            {sec==="policies"&&(()=>{
              const filtered=allPolicies.filter(p=>p.name.toLowerCase().includes(policySearch.toLowerCase().trim())||(p.category||"").toLowerCase().includes(policySearch.toLowerCase().trim()));
              return <div style={{maxWidth:640}}>
              <div style={{marginBottom:14}}><div style={{fontSize:15,fontWeight:700,color:T.text}}>Governance Policies</div><div style={{fontSize:12,color:T.textMuted,marginTop:3}}>Search and attach governance policies that apply to <span style={{fontFamily:"'Geist Mono',monospace",color:T.textSub}}>{asset.name}</span> ({policies.length} selected). Optional.</div></div>
              <input value={policySearch} onChange={e=>setPolicySearch(e.target.value)} placeholder="Search policies assigned to this table…" style={{...inp,marginBottom:10}}/>
              <div style={{display:"flex",flexDirection:"column",gap:8}}>
                {filtered.length===0&&<div style={{fontSize:12,color:T.textMuted,fontStyle:"italic",padding:"8px 0"}}>No policies match "{policySearch}".</div>}
                {filtered.map(p=>(
                <label key={p.id} style={{display:"flex",alignItems:"center",gap:10,padding:"10px 12px",background:policies.includes(p.id)?T.accentDim:T.bgElevated,border:`1px solid ${policies.includes(p.id)?T.accent+"55":T.border}`,borderRadius:9,cursor:"pointer"}}>
                  <input type="checkbox" checked={policies.includes(p.id)} onChange={()=>toggle(policies,setPolicies,p.id)} style={{accentColor:T.accent}}/>
                  <span style={{fontSize:12.5,color:T.text,flex:1}}>{p.name}</span>
                  <span style={{fontSize:10.5,color:T.textMuted}}>{p.category}</span>
                  <span style={{fontSize:9.5,fontWeight:700,padding:"1px 7px",borderRadius:5,background:p.severity==="Critical"?T.roseDim:T.bgHover,color:p.severity==="Critical"?T.rose:T.textMuted}}>{p.severity}</span>
                </label>))}</div>
            </div>;})()}

            {sec==="sla"&&<div style={{maxWidth:760}}>
              <div style={{marginBottom:14}}><div style={{fontSize:15,fontWeight:700,color:T.text}}>SLA</div><div style={{fontSize:12,color:T.textMuted,marginTop:3}}>Service-level agreement expectations.</div></div>
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:14}}>
                <div style={{padding:"14px 16px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:10}}>
                  <Lbl sub="Expected frequency of data updates">Refresh Frequency</Lbl>
                  <div style={{display:"flex",gap:10}}>
                    <div style={{flex:1}}><div style={{fontSize:10.5,color:T.textMuted,marginBottom:4}}>Interval *</div><input type="number" min="1" value={refreshInterval} onChange={e=>setRefreshInterval(e.target.value)} style={inp}/></div>
                    <div style={{flex:1}}><div style={{fontSize:10.5,color:T.textMuted,marginBottom:4}}>Unit *</div><select value={refreshUnit} onChange={e=>setRefreshUnit(e.target.value)} style={inp}>{["Hour","Day","Week","Month"].map(o=><option key={o}>{o}</option>)}</select></div>
                  </div>
                </div>
                <div style={{padding:"14px 16px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:10}}>
                  <Lbl sub="Max delay between generation & availability">Max Latency</Lbl>
                  <div style={{display:"flex",gap:10}}>
                    <div style={{flex:1}}><div style={{fontSize:10.5,color:T.textMuted,marginBottom:4}}>Value *</div><input type="number" min="0" value={latencyValue} onChange={e=>setLatencyValue(e.target.value)} style={inp}/></div>
                    <div style={{flex:1}}><div style={{fontSize:10.5,color:T.textMuted,marginBottom:4}}>Unit *</div><select value={latencyUnit} onChange={e=>setLatencyUnit(e.target.value)} style={inp}>{["Minutes","Hours","Days"].map(o=><option key={o}>{o}</option>)}</select></div>
                  </div>
                </div>
                <div style={{padding:"14px 16px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:10}}>
                  <Lbl sub="Time of day data should be available">Availability Time</Lbl>
                  <div style={{display:"flex",gap:10}}>
                    <div style={{flex:1}}><div style={{fontSize:10.5,color:T.textMuted,marginBottom:4}}>Time</div><input value={availTime} onChange={e=>setAvailTime(e.target.value)} placeholder="09:00" style={inp}/></div>
                    <div style={{flex:1}}><div style={{fontSize:10.5,color:T.textMuted,marginBottom:4}}>Timezone</div><select value={availTz} onChange={e=>setAvailTz(e.target.value)} style={inp}>{["UTC","America/New_York","Europe/London","Asia/Kolkata"].map(o=><option key={o}>{o}</option>)}</select></div>
                  </div>
                </div>
                <div style={{padding:"14px 16px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:10}}>
                  <Lbl sub="How long data is retained">Retention</Lbl>
                  <div style={{display:"flex",gap:10}}>
                    <div style={{flex:1}}><div style={{fontSize:10.5,color:T.textMuted,marginBottom:4}}>Period *</div><input type="number" min="0" value={retentionPeriod} onChange={e=>setRetentionPeriod(e.target.value)} style={inp}/></div>
                    <div style={{flex:1}}><div style={{fontSize:10.5,color:T.textMuted,marginBottom:4}}>Unit *</div><select value={retentionUnit} onChange={e=>setRetentionUnit(e.target.value)} style={inp}>{["Days","Months","Years"].map(o=><option key={o}>{o}</option>)}</select></div>
                  </div>
                </div>
                <div style={{gridColumn:"1 / -1",padding:"14px 16px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:10}}>
                  <Lbl sub="Column that represents the refresh time of the data">Column</Lbl>
                  <select value={refreshColumn} onChange={e=>setRefreshColumn(e.target.value)} style={inp}><option value="">Select a column…</option>{cols.map(c=><option key={c} value={c}>{c}</option>)}</select>
                </div>
              </div>
            </div>}

            {sec==="terms"&&<div style={{maxWidth:620}}>
              <div style={{marginBottom:14}}><div style={{fontSize:15,fontWeight:700,color:T.text}}>Terms of Use</div><div style={{fontSize:12,color:T.textMuted,marginTop:3}}>How consumers may and may not use this data. Declarative — not auto-validated.</div></div>
              <div style={{marginBottom:16}}><div style={{fontSize:11.5,fontWeight:700,color:T.text,marginBottom:4}}>Purpose</div>
                <div style={{fontSize:11,color:T.textMuted,marginBottom:8,lineHeight:1.5}}>One sentence on <b>why</b> this data exists and the business intent it serves. The specific scenarios go in the use cases below.</div>
                <textarea value={termsPurpose} onChange={e=>setTermsPurpose(e.target.value)} rows={2} placeholder="e.g. Powers revenue, retention and BI reporting for the Commerce and Finance teams." style={{...inp,resize:"vertical",fontFamily:"inherit"}}/>
              </div>
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:14}}>
                <div><div style={{fontSize:11.5,fontWeight:700,color:T.text,marginBottom:4}}>Allowed use cases</div>
                  <div style={{fontSize:11,color:T.textMuted,marginBottom:8,lineHeight:1.5}}>Specific scenarios this data <b>may</b> be used for.</div>
                  {termsAllowed.map((a,i)=>(<div key={i} style={{display:"flex",alignItems:"center",gap:8,padding:"7px 11px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:8,marginBottom:6}}><span style={{fontSize:12,color:T.textSub,flex:1}}>{a}</span><button onClick={()=>setTermsAllowed(x=>x.filter((_,k)=>k!==i))} style={{background:"none",border:"none",cursor:"pointer",color:T.textMuted,display:"flex"}}>{Ic.x(10)}</button></div>))}
                  <input placeholder="Add allowed use case + Enter" onKeyDown={e=>{if(e.key==="Enter"&&e.target.value.trim()){setTermsAllowed(x=>[...x,e.target.value.trim()]);e.target.value="";}}} style={inp}/>
                </div>
                <div><div style={{fontSize:11.5,fontWeight:700,color:T.text,marginBottom:4}}>Disallowed use cases</div>
                  <div style={{fontSize:11,color:T.textMuted,marginBottom:8,lineHeight:1.5}}>Specific scenarios this data <b>must not</b> be used for.</div>
                  {termsDisallowed.map((a,i)=>(<div key={i} style={{display:"flex",alignItems:"center",gap:8,padding:"7px 11px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:8,marginBottom:6}}><span style={{fontSize:12,color:T.textSub,flex:1}}>{a}</span><button onClick={()=>setTermsDisallowed(x=>x.filter((_,k)=>k!==i))} style={{background:"none",border:"none",cursor:"pointer",color:T.textMuted,display:"flex"}}>{Ic.x(10)}</button></div>))}
                  <input placeholder="Add disallowed use case + Enter" onKeyDown={e=>{if(e.key==="Enter"&&e.target.value.trim()){setTermsDisallowed(x=>[...x,e.target.value.trim()]);e.target.value="";}}} style={inp}/>
                </div>
              </div>
            </div>}

          </div>
        </div>
        {/* footer: Back / Next / Save */}
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"14px 20px",borderTop:`1px solid ${T.border}`,flexShrink:0,background:T.bgSurface}}>
          <Btn small ghost onClick={()=>prevKey?setSec(prevKey):onClose()}>{prevKey?"← Back":"Cancel"}</Btn>
          <div style={{display:"flex",alignItems:"center",gap:10}}>
            {!allComplete&&isLast&&<span style={{fontSize:11,color:T.textMuted}}>Complete the required sections (*)</span>}
            {!complete[sec]&&required.includes(sec)&&!isLast&&<span style={{fontSize:11,color:T.textMuted}}>Complete this section to continue</span>}
            {isLast
              ? <div style={{display:"flex",gap:8}}>
                  <Btn small ghost disabled={!allComplete} icon={<svg width="12" height="12" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round"><circle cx="8" cy="8" r="6"/><path d="M8 5v3l2 1.5"/></svg>} onClick={()=>{setDoneSet(d=>new Set([...d,sec]));onSubmit(build(),"schedule");}}>Schedule</Btn>
                  <Btn small variant="primary" disabled={!allComplete} icon={<svg width="12" height="12" viewBox="0 0 16 16" fill="none"><path d="M4 3l9 5-9 5V3z" fill="currentColor"/></svg>} onClick={()=>{setDoneSet(d=>new Set([...d,sec]));onSubmit(build(),"run");}}>Run now</Btn>
                </div>
              : <Btn small variant="primary" disabled={!complete[sec]} onClick={()=>{setDoneSet(d=>new Set([...d,sec]));setSec(nextKey);}}>Next →</Btn>}
          </div>
        </div>
      </div>
    </div>
  ,document.body);
};

const AssetQualityTab = ({asset,onToast,onNav})=>{
  const [runningIds,setRunningIds]=useState(new Set());
  const [selectedIds,setSelectedIds]=useState(new Set());
  const [page,setPage]=useState(0);
  const PAGE_SIZE=10;
  const [runAllProgress,setRunAllProgress]=useState(null);
  const [tcDetail,setTcDetail]=useState(null);
  const [tcDetailEditing,setTcDetailEditing]=useState(false);
  const [tcDetailDraft,setTcDetailDraft]=useState(null);
  const [addTestOpen,setAddTestOpen]=useState(false);
  const [selectTestOpen,setSelectTestOpen]=useState(false);
  const [selectTestIds,setSelectTestIds]=useState(new Set());
  // Full DQ wizard state
  const [aqTcName,      setAqTcName]      = useState("");
  const [aqTcDesc,      setAqTcDesc]      = useState("");
  const [aqTcLevel,     setAqTcLevel]     = useState("table");
  const [aqTcSelCol,    setAqTcSelCol]    = useState("");
  const [aqTcSelType,   setAqTcSelType]   = useState(null);
  const [aqTcCustomSQL,        setAqTcCustomSQL]        = useState(false);
  const [aqTcSQLQuery,         setAqTcSQLQuery]         = useState("");
  const [aqTcSQLStrategy,      setAqTcSQLStrategy]      = useState("");
  const [aqTcSQLOperator,      setAqTcSQLOperator]      = useState("");
  const [aqTcSQLThreshold,     setAqTcSQLThreshold]     = useState("");
  const [aqTcSQLPartitionExpr, setAqTcSQLPartitionExpr] = useState("");
  const [aqTcParams,    setAqTcParams]    = useState({});
  const [aqTcTags,      setAqTcTags]      = useState([]);
  const [aqTcTagInput,  setAqTcTagInput]  = useState("");
  const [aqTcGlossary,  setAqTcGlossary]  = useState([]);
  const [aqTcDim,       setAqTcDim]       = useState("");
  const [aqTcGlInput,   setAqTcGlInput]   = useState("");
  const [localCases,setLocalCases]=useState(()=>{
    // match DQ test cases to this asset — table field is like "commerce.orders", asset.name is "orders"
    const matched=DQ_TEST_CASES.filter(t=>t.table.endsWith("."+asset.name)||t.table===asset.name);
    return matched.length>0?matched:DQ_TEST_CASES.slice(0,3);
  });
  const tcSuccess=localCases.filter(t=>t.status==="Success").length;
  const tcFailed=localCases.filter(t=>t.status==="Failed").length;
  const tcAborted=localCases.filter(t=>t.status==="Aborted").length;
  const trend=[91,94,93,96,94,92,95,97,94,96,94,asset.quality];
  const dimColor=(dim)=>({Accuracy:"#8b5cf6",Completeness:"#3b82f6",Consistency:"#06b6d4",Timeliness:"#f59e0b",Validity:"#10b981",Uniqueness:"#ec4899"}[dim]||T.textMuted);
  const TC_CFG={Success:{color:"#16a34a",bg:"#16a34a12"},Failed:{color:"#e11d48",bg:"rgba(225,29,72,.1)"},Aborted:{color:"#d97706",bg:"rgba(217,119,6,.1)"}};
  const totalPages=Math.ceil(localCases.length/PAGE_SIZE);
  const pagedCases=localCases.slice(page*PAGE_SIZE,(page+1)*PAGE_SIZE);

  const runTest=(id,onDone)=>{
    setRunningIds(p=>new Set([...p,id]));
    setTimeout(()=>{
      setRunningIds(p=>{const n=new Set(p);n.delete(id);return n;});
      setLocalCases(p=>p.map(t=>t.id===id?{...t,lastRun:"just now",status:t.status==="Aborted"?"Success":t.status}:t));
      setTcDetail(prev=>prev?.id===id?{...prev,lastRun:"just now",status:prev.status==="Aborted"?"Success":prev.status}:prev);
      onDone&&onDone();
    },1400+Math.floor(Math.random()*800));
  };
  const deleteTest=(id)=>setLocalCases(p=>p.filter(t=>t.id!==id));

  return <div className="fadeIn" style={{display:"flex",flexDirection:"column",gap:16}}>
    {/* Score cards */}
    <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:12}}>
      <Card2 style={{padding:"14px 16px"}}>
        <div style={{fontSize:10.5,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.07em",marginBottom:6}}>Quality Score</div>
        <div style={{fontSize:26,fontWeight:800,color:asset.quality>=90?"#16a34a":asset.quality>=70?T.amber:T.rose,fontFamily:"'Geist Mono',monospace"}}>{asset.quality}<span style={{fontSize:14,fontWeight:500,color:T.textMuted}}>%</span></div>
      </Card2>
      <Card2 style={{padding:"14px 16px"}}>
        <div style={{fontSize:10.5,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.07em",marginBottom:6}}>Tests</div>
        <div style={{fontSize:26,fontWeight:800,color:T.text,fontFamily:"'Geist Mono',monospace"}}>{localCases.length}</div>
      </Card2>
      <Card2 style={{padding:"14px 16px"}}>
        <div style={{fontSize:10.5,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.07em",marginBottom:6}}>Passing</div>
        <div style={{fontSize:26,fontWeight:800,color:"#16a34a",fontFamily:"'Geist Mono',monospace"}}>{tcSuccess}</div>
      </Card2>
      <Card2 style={{padding:"14px 16px",borderColor:tcFailed>0?T.rose+"55":""}}>
        <div style={{fontSize:10.5,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.07em",marginBottom:6}}>Failing</div>
        <div style={{fontSize:26,fontWeight:800,color:tcFailed>0?T.rose:T.textMuted,fontFamily:"'Geist Mono',monospace"}}>{tcFailed}</div>
      </Card2>
    </div>

    {/* Trend */}
    <Card2>
      <div style={{padding:"14px 16px"}}>
        <div style={{fontSize:11,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.06em",marginBottom:12}}>Quality Score Trend (12 runs)</div>
        <div style={{height:64,display:"flex",alignItems:"flex-end",gap:3}}>
          {trend.map((v,i)=>{
            const col=v>=90?"#16a34a":v>=70?T.amber:T.rose;
            return <div key={i} style={{flex:1,borderRadius:"3px 3px 0 0",background:col,opacity:i<trend.length-1?0.45:0.85,height:`${(v/100)*64}px`,transition:"opacity .15s"}}
              onMouseEnter={e=>e.currentTarget.style.opacity="1"} onMouseLeave={e=>e.currentTarget.style.opacity=i<trend.length-1?"0.45":"0.85"}/>;
          })}
        </div>
        <div style={{height:1,background:T.border,marginTop:4}}/>
        <div style={{display:"flex",justifyContent:"space-between",marginTop:5,fontSize:10,color:T.textMuted}}>
          <span>12 runs ago</span><span>Latest</span>
        </div>
      </div>
    </Card2>

    {/* Test Cases table */}
    <Card2 style={{padding:0,overflow:"hidden"}}>
      <div style={{padding:"11px 16px",borderBottom:`1px solid ${T.border}`,display:"flex",alignItems:"center",justifyContent:"space-between",background:T.bgElevated}}>
        <div style={{display:"flex",alignItems:"center",gap:10}}>
          <span style={{fontSize:11.5,fontWeight:700,color:T.text}}>Test Cases ({localCases.length})</span>
          <span style={{fontSize:11.5,color:T.textMuted}}>
            <span style={{color:"#16a34a",fontWeight:600}}>{tcSuccess} passing</span>
            {tcFailed>0&&<span style={{color:T.rose,fontWeight:600,marginLeft:8}}>{tcFailed} failing</span>}
            {tcAborted>0&&<span style={{color:T.amber,fontWeight:600,marginLeft:8}}>{tcAborted} aborted</span>}
          </span>
        </div>
        <div style={{display:"flex",gap:6,alignItems:"center"}}>
          {selectedIds.size>0&&(
            <button onClick={()=>{[...selectedIds].forEach(id=>runTest(id));setSelectedIds(new Set());}}
              style={{display:"inline-flex",alignItems:"center",gap:5,padding:"5px 12px",borderRadius:7,background:T.accentDim,border:`1px solid ${T.accent}33`,color:T.accent,fontSize:11.5,fontWeight:600,cursor:"pointer"}}>
              <svg width="9" height="9" viewBox="0 0 12 12" fill="none"><path d="M3 2l7 4-7 4V2z" fill="currentColor"/></svg>
              Run Selected ({selectedIds.size})
            </button>
          )}
          <button
            disabled={!!runAllProgress}
            onClick={()=>{
              if(runAllProgress)return;
              const ids=localCases.map(t=>t.id);
              const willPass=localCases.filter(t=>t.status!=="Failed").length;
              const willFail=localCases.filter(t=>t.status==="Failed").length;
              let done=0;
              setRunAllProgress({done:0,total:ids.length});
              ids.forEach(id=>runTest(id,()=>{
                done++;
                setRunAllProgress(prev=>({...prev,done}));
                if(done===ids.length){
                  setTimeout(()=>setRunAllProgress(null),800);
                  onToast&&onToast(`Run complete — ${willPass} passed · ${willFail} failed`,"success");
                }
              }));
            }}
            style={{display:"inline-flex",alignItems:"center",gap:5,padding:"5px 12px",borderRadius:7,background:T.bgSurface,border:`1px solid ${T.border}`,color:runAllProgress?T.accent:T.textSub,fontSize:11.5,fontWeight:500,cursor:runAllProgress?"not-allowed":"pointer",opacity:runAllProgress?0.75:1,transition:"all .15s"}}
            onMouseEnter={e=>{if(!runAllProgress){e.currentTarget.style.borderColor=T.accent;e.currentTarget.style.color=T.accent;}}} onMouseLeave={e=>{if(!runAllProgress){e.currentTarget.style.borderColor=T.border;e.currentTarget.style.color=T.textSub;}}}>
            {runAllProgress
              ?<><svg width="10" height="10" viewBox="0 0 24 24" fill="none" style={{animation:"spin 1s linear infinite"}}><circle cx="12" cy="12" r="9" stroke="currentColor" strokeWidth="2.5" strokeDasharray="20 40"/></svg>Running {runAllProgress.done}/{runAllProgress.total}…</>
              :<><svg width="9" height="9" viewBox="0 0 12 12" fill="none"><path d="M3 2l7 4-7 4V2z" fill="currentColor"/></svg>Run All</>
            }
          </button>
          <button onClick={()=>setSelectTestOpen(true)}
            style={{display:"inline-flex",alignItems:"center",gap:5,padding:"5px 12px",borderRadius:7,background:T.accent,border:`1px solid ${T.accent}`,color:"#fff",fontSize:11.5,fontWeight:600,cursor:"pointer"}}>
            Select Test
          </button>
        </div>
      </div>
      {addTestOpen&&createPortal(
        <div style={{position:"fixed",inset:0,zIndex:800,display:"flex",justifyContent:"flex-end"}} onClick={()=>setAddTestOpen(false)}>
          <div onClick={e=>e.stopPropagation()} className="slideIn" style={{width:480,height:"100%",background:T.bgSurface,borderLeft:`1px solid ${T.border}`,boxShadow:"-8px 0 32px rgba(0,0,0,.28)",display:"flex",flexDirection:"column",overflow:"hidden"}}>
            {/* Header */}
            <div style={{padding:"16px 20px",borderBottom:`1px solid ${T.border}`,display:"flex",alignItems:"center",justifyContent:"space-between",flexShrink:0,background:T.bgElevated}}>
              <div>
                <div style={{fontSize:14,fontWeight:700,color:T.text}}>Add Test Case</div>
                <div style={{fontSize:11,color:T.textMuted,marginTop:2}}>Asset: <span style={{color:T.textSub,fontWeight:500,fontFamily:"'Geist Mono',monospace"}}>{asset.name}</span></div>
              </div>
              <button onClick={()=>setAddTestOpen(false)} style={{width:30,height:30,borderRadius:8,background:T.bgHover,border:`1px solid ${T.border}`,color:T.textMuted,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center"}}>{Ic.x(11)}</button>
            </div>
            {/* Body */}
            <div style={{flex:1,overflowY:"auto",padding:"20px"}}>
              <div style={{display:"flex",flexDirection:"column",gap:16}}>

                {/* Name */}
                <div>
                  <label style={{display:"block",fontSize:11,fontWeight:600,color:T.textSub,marginBottom:6}}>Test Case Name <span style={{color:T.rose}}>*</span></label>
                  <Input2 placeholder="e.g. orders.amount value range check" value={aqTcName} onChange={e=>setAqTcName(e.target.value)}/>
                </div>

                {/* Description */}
                <div>
                  <label style={{display:"block",fontSize:11,fontWeight:600,color:T.textSub,marginBottom:6}}>Description</label>
                  <textarea value={aqTcDesc} onChange={e=>setAqTcDesc(e.target.value)} rows={2}
                    placeholder="What does this test validate and why is it important?"
                    style={{width:"100%",padding:"9px 12px",background:T.bgElevated,border:`1.5px solid ${T.border}`,borderRadius:9,color:T.text,fontSize:12.5,outline:"none",resize:"none",fontFamily:"inherit",lineHeight:1.6,boxSizing:"border-box"}}
                    onFocus={e=>e.target.style.borderColor=T.accent} onBlur={e=>e.target.style.borderColor=T.border}/>
                </div>

                {/* Test Level */}
                <div>
                  <div style={{fontSize:11,fontWeight:600,color:T.textSub,marginBottom:7}}>Test Level</div>
                  <div style={{display:"flex",gap:6}}>
                    {[{k:"table",l:"Table Level"},{k:"column",l:"Column Level"}].map(({k,l})=>(
                      <button key={k} onClick={()=>{setAqTcLevel(k);setAqTcSelType(null);setAqTcSelCol("");setAqTcCustomSQL(false);setAqTcSQLQuery("");}} style={{flex:1,padding:"9px 12px",borderRadius:9,border:`1.5px solid ${aqTcLevel===k?T.accent:T.border}`,background:aqTcLevel===k?`${T.accent}08`:T.bgElevated,cursor:"pointer",textAlign:"center",transition:"all .12s"}}>
                        <div style={{fontSize:12,fontWeight:700,color:aqTcLevel===k?T.accent:T.text}}>{l}</div>
                      </button>
                    ))}
                  </div>
                </div>

                {/* Column (if column level) */}
                {aqTcLevel==="column"&&(
                  <div>
                    <label style={{display:"block",fontSize:11,fontWeight:600,color:T.textSub,marginBottom:6}}>Column <span style={{color:T.rose}}>*</span></label>
                    <Input2 placeholder="e.g. amount, status, user_id…" value={aqTcSelCol} onChange={e=>{setAqTcSelCol(e.target.value);setAqTcSelType(null);}}/>
                  </div>
                )}

                {/* DQ Dimension */}
                <div>
                  <div style={{fontSize:11,fontWeight:600,color:T.textSub,marginBottom:6}}>DQ Dimension</div>
                  <select value={aqTcDim} onChange={e=>{setAqTcDim(e.target.value);setAqTcSelType(null);}}
                    style={{width:"100%",padding:"9px 12px",background:T.bgElevated,border:`1.5px solid ${aqTcDim?T.accent:T.border}`,borderRadius:9,color:aqTcDim?T.text:T.textMuted,fontSize:13,outline:"none",cursor:"pointer",boxSizing:"border-box"}}>
                    <option value="">All dimensions</option>
                    {["Accuracy","Completeness","Consistency","Timeliness","Validity","Uniqueness"].map(d=>(
                      <option key={d} value={d}>{d}</option>
                    ))}
                  </select>
                </div>

                {/* Test Source — Test Definition / Custom SQL toggle */}
                <div>
                  <div style={{fontSize:11,fontWeight:600,color:T.textSub,marginBottom:8}}>Test Source <span style={{color:T.rose}}>*</span></div>
                  <div style={{display:"inline-flex",borderRadius:8,overflow:"hidden",border:`1px solid ${T.border}`,marginBottom:10,background:T.bgElevated}}>
                    <button onClick={()=>{setAqTcCustomSQL(false);}}
                      style={{padding:"7px 16px",background:!aqTcCustomSQL?T.accent:"transparent",border:"none",color:!aqTcCustomSQL?"#fff":T.textSub,fontSize:11.5,fontWeight:!aqTcCustomSQL?700:400,cursor:"pointer",transition:"all .12s"}}>
                      Test Definition
                    </button>
                    <button onClick={()=>{setAqTcCustomSQL(true);setAqTcSelType(null);}}
                      style={{padding:"7px 16px",background:aqTcCustomSQL?T.accent:"transparent",border:"none",color:aqTcCustomSQL?"#fff":T.textSub,fontSize:11.5,fontWeight:aqTcCustomSQL?700:400,cursor:"pointer",transition:"all .12s"}}>
                      Custom SQL
                    </button>
                  </div>
                  {!aqTcCustomSQL&&(
                    <select value={aqTcSelType?.id||""} onChange={e=>{const def=DQ_TEST_DEFINITIONS.find(d=>d.id===e.target.value);setAqTcSelType(def||null);setAqTcParams({});}}
                      style={{width:"100%",padding:"9px 12px",background:T.bgElevated,border:`1.5px solid ${aqTcSelType?T.accent:T.border}`,borderRadius:9,color:aqTcSelType?T.text:T.textMuted,fontSize:13,outline:"none",cursor:"pointer",boxSizing:"border-box"}}>
                      <option value="">Choose a definition…</option>
                      {DQ_TEST_DEFINITIONS.filter(d=>(aqTcLevel==="column"?d.entityType==="COLUMN":d.entityType==="TABLE")&&(!aqTcDim||d.dim===aqTcDim||d.dim?.toLowerCase()===aqTcDim.toLowerCase())).map(def=>(
                        <option key={def.id} value={def.id}>{def.name}</option>
                      ))}
                    </select>
                  )}
                  {aqTcSelType&&!aqTcCustomSQL&&(
                    <div style={{marginTop:8,padding:"10px 14px",background:T.bgElevated,borderRadius:9,border:`1px solid ${T.border}`,fontSize:11.5,color:T.textSub,lineHeight:1.6}}>{aqTcSelType.desc}</div>
                  )}
                  {aqTcCustomSQL&&(
                    <div style={{display:"flex",flexDirection:"column",gap:12}}>
                      {/* SQL Expression — template */}
                      <div>
                        <label style={{display:"block",fontSize:11,fontWeight:600,color:T.textSub,marginBottom:6}}>SQL Expression <span style={{color:T.rose}}>*</span> <span style={{color:T.textMuted,fontWeight:400}}>(template)</span></label>
                        <textarea value={aqTcSQLQuery} onChange={e=>setAqTcSQLQuery(e.target.value)} rows={4}
                          placeholder={"SELECT {{ column_name }} AS col\nFROM {{ table_name }}\nWHERE {{ column_name }} < {{ min_value }}"}
                          style={{width:"100%",padding:"9px 12px",background:T.bgElevated,border:`1.5px solid ${aqTcSQLQuery?T.accent:T.border}`,borderRadius:9,color:T.text,fontSize:12,outline:"none",resize:"vertical",fontFamily:"'Geist Mono',monospace",lineHeight:1.6,boxSizing:"border-box"}}
                          onFocus={e=>e.target.style.borderColor=T.accent} onBlur={e=>e.target.style.borderColor=T.border}/>
                        <div style={{fontSize:10.5,color:T.textMuted,marginTop:4}}>Use <code style={{color:"#2dd4bf",fontFamily:"'Geist Mono',monospace"}}>{"{{ table_name }}"}</code> / <code style={{color:"#2dd4bf",fontFamily:"'Geist Mono',monospace"}}>{"{{ column_name }}"}</code> (auto-filled) and any <code style={{color:"#fbbf24",fontFamily:"'Geist Mono',monospace"}}>{"{{ token }}"}</code> to collect a value. Test passes when 0 rows are returned.</div>
                      </div>
                      {/* Parameters — reserved (auto) + user-defined values */}
                      {(()=>{
                        const tokens = extractSQLTokens(aqTcSQLQuery);
                        if(tokens.length===0) return null;
                        const reserved = tokens.filter(t=>RESERVED_SQL_PARAMS.includes(t));
                        const userTokens = tokens.filter(t=>!RESERVED_SQL_PARAMS.includes(t));
                        const colBound = aqTcLevel==="column"?aqTcSelCol:"";
                        const chip = (name,val,ok)=>(
                          <div key={name} style={{display:"flex",alignItems:"center",gap:7,fontSize:11.5,background:T.bgElevated,border:`1px solid ${ok?"#2dd4bf55":T.border}`,borderRadius:8,padding:"6px 10px"}}>
                            <svg width="12" height="12" viewBox="0 0 16 16" fill="none"><path d="M4 7V5a4 4 0 018 0v2m-9 0h10v6a1 1 0 01-1 1H4a1 1 0 01-1-1V7z" stroke={ok?"#2dd4bf":T.textMuted} strokeWidth="1.3"/></svg>
                            <span style={{fontFamily:"'Geist Mono',monospace",color:"#2dd4bf"}}>{name}</span>
                            <span style={{color:T.textMuted}}>· {ok?val:(name==="column_name"?"enter a column above":"—")}</span>
                          </div>
                        );
                        return (
                          <div>
                            <div style={{fontSize:11,fontWeight:600,color:T.textSub,marginBottom:7}}>Parameters</div>
                            <div style={{display:"flex",flexDirection:"column",gap:6}}>
                              {reserved.includes("table_name")&&chip("table_name",asset.name,!!asset.name)}
                              {reserved.includes("column_name")&&chip("column_name",colBound,!!colBound)}
                              {userTokens.map(name=>(
                                <div key={name} style={{display:"flex",alignItems:"center",gap:8,background:"#fbbf2410",border:"1px solid #fbbf2455",borderRadius:8,padding:"8px 10px"}}>
                                  <span style={{fontFamily:"'Geist Mono',monospace",fontSize:11.5,color:"#fbbf24",minWidth:90}}>{name}</span>
                                  <input value={aqTcParams[name]||""} onChange={e=>setAqTcParams(p=>({...p,[name]:e.target.value}))}
                                    placeholder="value"
                                    style={{flex:1,padding:"6px 9px",background:T.bgElevated,border:`1.5px solid ${aqTcParams[name]?T.accent:T.border}`,borderRadius:7,color:T.text,fontSize:12,outline:"none",boxSizing:"border-box",fontFamily:"'Geist Mono',monospace"}}/>
                                </div>
                              ))}
                            </div>
                          </div>
                        );
                      })()}
                      {/* Strategy */}
                      <div>
                        <label style={{display:"block",fontSize:11,fontWeight:600,color:T.textSub,marginBottom:6}}>Strategy <span style={{color:T.textMuted,fontWeight:400}}>(optional)</span></label>
                        <select value={aqTcSQLStrategy} onChange={e=>setAqTcSQLStrategy(e.target.value)}
                          style={{width:"100%",padding:"8px 12px",background:T.bgElevated,border:`1.5px solid ${aqTcSQLStrategy?T.accent:T.border}`,borderRadius:9,color:aqTcSQLStrategy?T.text:T.textMuted,fontSize:13,outline:"none",cursor:"pointer"}}>
                          <option value="">Select strategy…</option>
                          <option value="ROWS">ROWS — count returned rows</option>
                          <option value="COUNT">COUNT — use COUNT() in query</option>
                        </select>
                      </div>
                      {/* Operator + Threshold */}
                      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
                        <div>
                          <label style={{display:"block",fontSize:11,fontWeight:600,color:T.textSub,marginBottom:6}}>Operator <span style={{color:T.textMuted,fontWeight:400}}>(optional)</span></label>
                          <select value={aqTcSQLOperator} onChange={e=>setAqTcSQLOperator(e.target.value)}
                            style={{width:"100%",padding:"8px 12px",background:T.bgElevated,border:`1.5px solid ${aqTcSQLOperator?T.accent:T.border}`,borderRadius:9,color:aqTcSQLOperator?T.text:T.textMuted,fontSize:13,outline:"none",cursor:"pointer"}}>
                            <option value="">Select…</option>
                            <option value="==">== equals</option>
                            <option value=">">&gt; greater than</option>
                            <option value=">=">&gt;= greater or equal</option>
                            <option value="<">&lt; less than</option>
                            <option value="<=">&lt;= less or equal</option>
                            <option value="!=">!= not equal</option>
                          </select>
                        </div>
                        <div>
                          <label style={{display:"block",fontSize:11,fontWeight:600,color:T.textSub,marginBottom:6}}>Threshold <span style={{color:T.textMuted,fontWeight:400}}>(default: 0)</span></label>
                          <input type="number" value={aqTcSQLThreshold} onChange={e=>setAqTcSQLThreshold(e.target.value)}
                            placeholder="0"
                            style={{width:"100%",padding:"8px 12px",background:T.bgElevated,border:`1.5px solid ${aqTcSQLThreshold!==""?T.accent:T.border}`,borderRadius:9,color:T.text,fontSize:13,outline:"none",boxSizing:"border-box"}}
                            onFocus={e=>e.target.style.borderColor=T.accent} onBlur={e=>e.target.style.borderColor=T.border}/>
                        </div>
                      </div>
                      {/* Partition Expression */}
                      <div>
                        <label style={{display:"block",fontSize:11,fontWeight:600,color:T.textSub,marginBottom:6}}>Partition Expression <span style={{color:T.textMuted,fontWeight:400}}>(optional)</span></label>
                        <input value={aqTcSQLPartitionExpr} onChange={e=>setAqTcSQLPartitionExpr(e.target.value)}
                          placeholder="e.g. created_date"
                          style={{width:"100%",padding:"8px 12px",background:T.bgElevated,border:`1.5px solid ${aqTcSQLPartitionExpr?T.accent:T.border}`,borderRadius:9,color:T.text,fontSize:12,outline:"none",boxSizing:"border-box",fontFamily:"'Geist Mono',monospace"}}
                          onFocus={e=>e.target.style.borderColor=T.accent} onBlur={e=>e.target.style.borderColor=T.border}/>
                        <div style={{fontSize:10.5,color:T.textMuted,marginTop:4}}>SQL expression to group results for row-level analysis.</div>
                      </div>
                    </div>
                  )}
                </div>

                {/* Parameters */}
                {aqTcSelType&&(aqTcSelType.params||[]).length>0&&(
                  <div>
                    <div style={{fontSize:11,fontWeight:600,color:T.textSub,marginBottom:10}}>Parameters</div>
                    <div style={{display:"flex",flexDirection:"column",gap:8}}>
                      {aqTcSelType.params.map(p=>(
                        <div key={p}>
                          <label style={{display:"block",fontSize:11,color:T.textMuted,marginBottom:4,textTransform:"capitalize"}}>{p.replace(/([A-Z])/g," $1").replace(/^./,s=>s.toUpperCase())}</label>
                          <Input2 placeholder={p} value={aqTcParams[p]||""} onChange={e=>setAqTcParams(prev=>({...prev,[p]:e.target.value}))}/>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* Tags */}
                <div>
                  <label style={{display:"block",fontSize:11,fontWeight:600,color:T.textSub,marginBottom:6}}>Tags</label>
                  <div style={{display:"flex",gap:5,flexWrap:"wrap",marginBottom:aqTcTags.length>0?8:0}}>
                    {aqTcTags.map((tag,i)=>(
                      <span key={i} style={{display:"inline-flex",alignItems:"center",gap:4,fontSize:11.5,padding:"3px 9px",borderRadius:99,background:T.accentDim,border:`1px solid ${T.accent}33`,color:T.accent}}>
                        {tag}
                        <button onClick={()=>setAqTcTags(p=>p.filter((_,j)=>j!==i))} style={{background:"none",border:"none",cursor:"pointer",color:T.accent,padding:0,lineHeight:1}}>{Ic.x(8)}</button>
                      </span>
                    ))}
                  </div>
                  <div style={{display:"flex",gap:6}}>
                    <Input2 placeholder="Add tag…" value={aqTcTagInput} onChange={e=>setAqTcTagInput(e.target.value)}
                      onKeyDown={e=>{if(e.key==="Enter"&&aqTcTagInput.trim()){setAqTcTags(p=>[...p,aqTcTagInput.trim()]);setAqTcTagInput("");}}}/>
                    <button onClick={()=>{if(aqTcTagInput.trim()){setAqTcTags(p=>[...p,aqTcTagInput.trim()]);setAqTcTagInput("");}}} style={{padding:"0 12px",borderRadius:7,background:T.bgElevated,border:`1px solid ${T.border}`,color:T.textSub,fontSize:12,cursor:"pointer",flexShrink:0}}>Add</button>
                  </div>
                </div>

                {/* Glossary Terms */}
                <div>
                  <label style={{display:"block",fontSize:11,fontWeight:600,color:T.textSub,marginBottom:6}}>Glossary Terms</label>
                  <div style={{display:"flex",gap:5,flexWrap:"wrap",marginBottom:aqTcGlossary.length>0?8:0}}>
                    {aqTcGlossary.map((term,i)=>(
                      <span key={i} style={{display:"inline-flex",alignItems:"center",gap:4,fontSize:11.5,padding:"3px 9px",borderRadius:99,background:T.bgElevated,border:`1px solid ${T.border}`,color:T.textSub}}>
                        {term}
                        <button onClick={()=>setAqTcGlossary(p=>p.filter((_,j)=>j!==i))} style={{background:"none",border:"none",cursor:"pointer",color:T.textMuted,padding:0,lineHeight:1}}>{Ic.x(8)}</button>
                      </span>
                    ))}
                  </div>
                  <div style={{display:"flex",gap:6}}>
                    <Input2 placeholder="Add glossary term…" value={aqTcGlInput} onChange={e=>setAqTcGlInput(e.target.value)}
                      onKeyDown={e=>{if(e.key==="Enter"&&aqTcGlInput.trim()){setAqTcGlossary(p=>[...p,aqTcGlInput.trim()]);setAqTcGlInput("");}}}/>
                    <button onClick={()=>{if(aqTcGlInput.trim()){setAqTcGlossary(p=>[...p,aqTcGlInput.trim()]);setAqTcGlInput("");}}} style={{padding:"0 12px",borderRadius:7,background:T.bgElevated,border:`1px solid ${T.border}`,color:T.textSub,fontSize:12,cursor:"pointer",flexShrink:0}}>Add</button>
                  </div>
                </div>

              </div>
            </div>
            {/* Footer */}
            <div style={{padding:"14px 20px",borderTop:`1px solid ${T.border}`,display:"flex",gap:8,flexShrink:0,background:T.bgSurface}}>
              <button onClick={()=>{
                if(!aqTcName.trim()) return;
                const def=aqTcSelType||{id:"custom",name:"Custom SQL",dim:"Consistency"};
                const newCase={id:`tc_new_${Date.now()}`,name:aqTcName.trim(),suiteId:"ts1",table:asset.name,col:aqTcLevel==="column"?aqTcSelCol||"column_name":null,defId:def.id,defName:def.name,dim:def.dim,status:"Success",lastVal:"—",expected:Object.entries(aqTcParams).map(([k,v])=>`${k}: ${v}`).join(", ")||"—",lastRun:"just now",history:[],params:aqTcParams,failedReason:"",incidentId:null};
                setLocalCases(p=>[...p,newCase]);
                setAddTestOpen(false);
                onToast&&onToast("Test case created — running now…","success");
              }}
                disabled={!aqTcName.trim()||(!aqTcSelType&&!aqTcCustomSQL)||(aqTcCustomSQL&&!aqTcSQLQuery.trim())}
                style={{flex:1,display:"flex",alignItems:"center",justifyContent:"center",gap:7,padding:"9px",borderRadius:9,background:(aqTcName.trim()&&(aqTcSelType||(aqTcCustomSQL&&aqTcSQLQuery.trim())))?T.accent:"rgba(100,100,120,.3)",border:"none",color:"#fff",fontSize:13,fontWeight:700,cursor:(aqTcName.trim()&&(aqTcSelType||(aqTcCustomSQL&&aqTcSQLQuery.trim())))?"pointer":"default",transition:"background .15s"}}>
                <svg width="12" height="12" viewBox="0 0 16 16" fill="none"><path d="M4 3l9 5-9 5V3z" fill="currentColor"/></svg>Run now
              </button>
              <button onClick={()=>setAddTestOpen(false)} style={{padding:"9px 18px",borderRadius:9,background:"transparent",border:`1px solid ${T.border}`,color:T.textSub,fontSize:12.5,cursor:"pointer"}}>Cancel</button>
            </div>
          </div>
        </div>,
        document.body
      )}
      {selectTestOpen&&createPortal(
        <div style={{position:"fixed",inset:0,zIndex:900,background:"rgba(0,0,0,.45)"}} onClick={()=>{setSelectTestOpen(false);setSelectTestIds(new Set());}}>
          <div onClick={e=>e.stopPropagation()} className="slideIn" style={{position:"absolute",right:0,top:0,width:440,height:"100%",background:T.bgSurface,borderLeft:`1px solid ${T.border}`,boxShadow:"-8px 0 32px rgba(0,0,0,.28)",display:"flex",flexDirection:"column",overflow:"hidden"}}>
            {/* Header */}
            <div style={{padding:"16px 20px",borderBottom:`1px solid ${T.border}`,display:"flex",alignItems:"center",justifyContent:"space-between",flexShrink:0,background:T.bgElevated}}>
              <div>
                <div style={{fontSize:14,fontWeight:700,color:T.text}}>Select Test Cases</div>
                <div style={{fontSize:11,color:T.textMuted,marginTop:2}}>Table: <span style={{color:T.textSub,fontWeight:500,fontFamily:"'Geist Mono',monospace"}}>{asset.name}</span></div>
              </div>
              <button onClick={()=>{setSelectTestOpen(false);setSelectTestIds(new Set());}} style={{width:30,height:30,borderRadius:8,background:T.bgHover,border:`1px solid ${T.border}`,color:T.textMuted,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center"}}>{Ic.x(11)}</button>
            </div>
            {/* List */}
            <div style={{flex:1,overflowY:"auto",padding:16,display:"flex",flexDirection:"column",gap:8}}>
              {(()=>{
                const allForTable=DQ_TEST_CASES.filter(t=>t.table.endsWith("."+asset.name)||t.table===asset.name);
                const existIds=new Set(localCases.map(t=>t.id));
                const available=allForTable.filter(t=>!existIds.has(t.id));
                if(available.length===0) return (
                  <div style={{textAlign:"center",padding:"40px 20px"}}>
                    <div style={{fontSize:28,marginBottom:10}}>🔍</div>
                    <div style={{fontSize:13,fontWeight:600,color:T.textSub,marginBottom:6}}>No test cases found</div>
                    <div style={{fontSize:11.5,color:T.textMuted,lineHeight:1.6}}>No test cases found for this table.<br/>Create them in the DQ section first.</div>
                  </div>
                );
                const dimC={Accuracy:"#8b5cf6",Completeness:"#3b82f6",Consistency:"#06b6d4",Timeliness:"#f59e0b",Validity:"#10b981",Uniqueness:"#ec4899"};
                const SC2={Success:"#16a34a",Failed:"#e11d48",Aborted:"#d97706"};
                return available.map(t=>{
                  const isSel=selectTestIds.has(t.id);
                  return (
                    <div key={t.id} onClick={()=>setSelectTestIds(p=>{const n=new Set(p);isSel?n.delete(t.id):n.add(t.id);return n;})}
                      style={{background:isSel?T.accentDim:T.bgElevated,border:`1.5px solid ${isSel?T.accent:T.border}`,borderRadius:9,padding:"10px 12px",cursor:"pointer",transition:"all .15s"}}>
                      <div style={{display:"flex",alignItems:"flex-start",gap:10}}>
                        <input type="checkbox" checked={isSel} onChange={()=>{}} style={{marginTop:2,accentColor:T.accent,cursor:"pointer"}}/>
                        <div style={{flex:1,minWidth:0}}>
                          <div style={{fontSize:12,fontWeight:600,color:T.text,marginBottom:4}}>{t.name}</div>
                          <div style={{display:"flex",gap:5,flexWrap:"wrap"}}>
                            <span style={{fontSize:10,fontWeight:700,color:SC2[t.status]||T.textMuted,background:`${SC2[t.status]||T.bgSurface}18`,padding:"1px 6px",borderRadius:4,border:`1px solid ${SC2[t.status]||T.border}33`}}>{t.status}</span>
                            <span style={{fontSize:10,padding:"1px 6px",borderRadius:4,background:`${dimC[t.dim]||T.textMuted}12`,color:dimC[t.dim]||T.textMuted,fontWeight:600,border:`1px solid ${dimC[t.dim]||T.textMuted}22`}}>{t.dim}</span>
                            {t.col&&<span style={{fontSize:10,color:T.textMuted,background:T.bgSurface,padding:"1px 6px",borderRadius:4,border:`1px solid ${T.border}`,fontFamily:"'Geist Mono',monospace"}}>{t.col}</span>}
                          </div>
                          <div style={{fontSize:10,color:T.textMuted,marginTop:4}}>Last run: {t.lastRun}</div>
                        </div>
                      </div>
                    </div>
                  );
                });
              })()}
            </div>
            {/* Footer */}
            <div style={{padding:"14px 20px",borderTop:`1px solid ${T.border}`,display:"flex",gap:8,flexShrink:0,background:T.bgSurface}}>
              <button disabled={selectTestIds.size===0}
                onClick={()=>{
                  const toAdd=DQ_TEST_CASES.filter(t=>selectTestIds.has(t.id));
                  setLocalCases(p=>{const existIds=new Set(p.map(x=>x.id));return [...p,...toAdd.filter(t=>!existIds.has(t.id))];});
                  setSelectTestOpen(false);setSelectTestIds(new Set());
                }}
                style={{flex:1,padding:"9px",borderRadius:9,background:selectTestIds.size>0?T.accent:"rgba(100,100,120,.3)",border:"none",color:"#fff",fontSize:13,fontWeight:700,cursor:selectTestIds.size>0?"pointer":"default",transition:"background .15s"}}>
                Add Selected ({selectTestIds.size})
              </button>
              <button onClick={()=>{setSelectTestOpen(false);setSelectTestIds(new Set());}} style={{padding:"9px 18px",borderRadius:9,background:"transparent",border:`1px solid ${T.border}`,color:T.textSub,fontSize:12.5,cursor:"pointer"}}>Cancel</button>
            </div>
          </div>
        </div>,
        document.body
      )}
      {localCases.length===0
        ? <div style={{padding:"40px",textAlign:"center",color:T.textMuted,fontSize:13}}>No test cases found for this table. Click <b>Select Test</b> to add test cases.</div>
        : <><table style={{width:"100%",borderCollapse:"collapse"}}>
            <thead>
              <tr style={{background:T.bgElevated,borderBottom:`1px solid ${T.border}`}}>
                <th style={{padding:"8px 8px 8px 14px",width:28}}>
                  <input type="checkbox" checked={selectedIds.size===localCases.length&&localCases.length>0}
                    onChange={e=>setSelectedIds(e.target.checked?new Set(localCases.map(t=>t.id)):new Set())}
                    style={{cursor:"pointer",accentColor:T.accent}}/>
                </th>
                {["Status","Name","Column","Dimension","Last Run","Incident","Actions"].map((h,i)=>(
                  <th key={i} style={{padding:"8px 14px",fontSize:10.5,fontWeight:700,color:T.textMuted,textAlign:"left",textTransform:"uppercase",letterSpacing:".05em",whiteSpace:"nowrap"}}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {pagedCases.map((t,i)=>{
                const cfg=TC_CFG[t.status]||TC_CFG.Success;
                const isRunning=runningIds.has(t.id);
                const isSel=selectedIds.has(t.id);
                return (
                  <tr key={t.id} style={{borderBottom:i<pagedCases.length-1?`1px solid ${T.border}`:"none",transition:"background .1s",background:isSel?T.accentDim:"transparent",cursor:"pointer"}}
                    onClick={e=>{if(e.target.type!=="checkbox")setTcDetail(t);}}
                    onMouseEnter={e=>{if(!isSel)e.currentTarget.style.background=T.bgHover;}} onMouseLeave={e=>{if(!isSel)e.currentTarget.style.background=isSel?T.accentDim:"transparent";}}>
                    <td style={{padding:"10px 8px 10px 14px",width:28}} onClick={e=>e.stopPropagation()}>
                      <input type="checkbox" checked={isSel} onChange={e=>setSelectedIds(p=>{const n=new Set(p);e.target.checked?n.add(t.id):n.delete(t.id);return n;})} style={{cursor:"pointer",accentColor:T.accent}}/>
                    </td>
                    <td style={{padding:"10px 14px",width:44}}>
                      <DQStatusDot status={isRunning?"Aborted":t.status}/>
                    </td>
                    <td style={{padding:"10px 14px"}}>
                      <div style={{display:"flex",alignItems:"center",gap:6,flexWrap:"wrap"}}>
                        <span style={{fontSize:12.5,fontWeight:600,color:T.text}}>{t.name}</span>
                        <TestSourceChip source={t.source}/>
                      </div>
                      {t.source==="dbt"&&t.dbtTest&&<div style={{fontSize:10.5,color:T.textMuted,fontFamily:"'Geist Mono',monospace",marginTop:3}}>{t.dbtTest}</div>}
                      {(()=>{const l=tcPolicyLink(t);return l?<div style={{marginTop:4}}><PolicyChip link={l} onNav={onNav} compact/></div>:null;})()}
                    </td>
                    <td style={{padding:"10px 14px"}}>
                      {t.col?<span style={{fontSize:11.5,fontFamily:"'Geist Mono',monospace",color:T.textSub}}>{t.col}</span>:<span style={{color:T.textMuted,fontSize:12}}>—</span>}
                    </td>
                    <td style={{padding:"10px 14px"}}>
                      <span style={{fontSize:11,padding:"2px 8px",borderRadius:5,background:`${dimColor(t.dim)}12`,color:dimColor(t.dim),fontWeight:600,border:`1px solid ${dimColor(t.dim)}22`}}>{t.dim}</span>
                    </td>
                    <td style={{padding:"10px 14px",fontSize:11.5,fontFamily:"'Geist Mono',monospace",color:T.textMuted,whiteSpace:"nowrap"}}>{isRunning?"Running…":t.lastRun}</td>
                    <td style={{padding:"10px 14px"}} onClick={e=>e.stopPropagation()}>
                      {t.incidentId
                        ?<button onClick={e=>{e.stopPropagation();window.__dqPendingInc=t.incidentId;onNav&&onNav("quality");}}
                            style={{fontSize:11,padding:"3px 9px",borderRadius:6,background:T.roseDim,border:`1px solid ${T.rose}30`,color:T.rose,cursor:"pointer",fontWeight:600,whiteSpace:"nowrap"}}
                            onMouseEnter={e=>e.currentTarget.style.opacity=".75"} onMouseLeave={e=>e.currentTarget.style.opacity="1"}>
                            🔴 View
                          </button>
                        :<span style={{color:T.textMuted,fontSize:12}}>—</span>
                      }
                    </td>
                    <td style={{padding:"8px 14px"}} onClick={e=>e.stopPropagation()}>
                      <div style={{display:"flex",gap:4}}>
                        <button title={t.source==="dbt"?"Declared in the dbt repo — run it from dbt Cloud, not here":isRunning?"Running…":"Run now"} disabled={isRunning||t.source==="dbt"} onClick={e=>{e.stopPropagation();if(t.source==="dbt"){onToast&&onToast("This test is owned by dbt — trigger it from the dbt Cloud job","info");return;}!isRunning&&runTest(t.id);}}
                          style={{width:28,height:28,borderRadius:7,display:"flex",alignItems:"center",justifyContent:"center",background:T.accentDim,border:`1px solid ${T.accent}33`,color:T.accent,cursor:(isRunning||t.source==="dbt")?"not-allowed":"pointer",opacity:(isRunning||t.source==="dbt")?0.4:1,transition:"opacity .1s"}}
                          onMouseEnter={e=>{if(!isRunning&&t.source!=="dbt")e.currentTarget.style.opacity=".7";}} onMouseLeave={e=>{if(!isRunning&&t.source!=="dbt")e.currentTarget.style.opacity="1";}}>
                          <svg width="10" height="10" viewBox="0 0 12 12" fill="none"><path d="M3 2l7 4-7 4V2z" fill="currentColor"/></svg>
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
          {totalPages>1&&(
            <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",padding:"10px 16px",borderTop:`1px solid ${T.border}`,background:T.bgElevated}}>
              <span style={{fontSize:11.5,color:T.textMuted}}>
                Showing {page*PAGE_SIZE+1}{"–"}{Math.min((page+1)*PAGE_SIZE,localCases.length)} of {localCases.length}
              </span>
              <div style={{display:"flex",gap:4,alignItems:"center"}}>
                <button disabled={page===0} onClick={()=>setPage(p=>p-1)}
                  style={{padding:"3px 10px",borderRadius:6,fontSize:11.5,fontWeight:500,cursor:page===0?"not-allowed":"pointer",opacity:page===0?0.4:1,background:T.bgSurface,border:`1px solid ${T.border}`,color:T.textSub}}>
                  ← Prev
                </button>
                {Array.from({length:totalPages},(_,i)=>(
                  <button key={i} onClick={()=>setPage(i)}
                    style={{width:26,height:26,borderRadius:6,fontSize:11.5,fontWeight:page===i?700:400,cursor:"pointer",background:page===i?T.accent:T.bgSurface,border:`1px solid ${page===i?T.accent:T.border}`,color:page===i?"#fff":T.textSub}}>
                    {i+1}
                  </button>
                ))}
                <button disabled={page===totalPages-1} onClick={()=>setPage(p=>p+1)}
                  style={{padding:"3px 10px",borderRadius:6,fontSize:11.5,fontWeight:500,cursor:page===totalPages-1?"not-allowed":"pointer",opacity:page===totalPages-1?0.4:1,background:T.bgSurface,border:`1px solid ${T.border}`,color:T.textSub}}>
                  Next →
                </button>
              </div>
            </div>
          )}
      </>}
    </Card2>

    {/* ── Test Case Detail Panel ── */}
    {tcDetail&&createPortal(
      <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,.45)",zIndex:900,backdropFilter:"blur(3px)"}} onClick={()=>{setTcDetail(null);setTcDetailEditing(false);setTcDetailDraft(null);}}>
        <div onClick={e=>e.stopPropagation()} style={{position:"absolute",top:0,right:0,bottom:0,width:500,background:T.bgSurface,borderLeft:`1px solid ${T.border}`,display:"flex",flexDirection:"column",boxShadow:"-24px 0 64px rgba(0,0,0,.3)"}}>
          {/* Header */}
          <div style={{padding:"20px 24px 16px",borderBottom:`1px solid ${T.border}`,flexShrink:0}}>
            <div style={{display:"flex",alignItems:"flex-start",justifyContent:"space-between",gap:12}}>
              <div style={{flex:1}}>
                {tcDetailEditing
                  ? <input value={tcDetailDraft?.name||""} onChange={e=>setTcDetailDraft(d=>({...d,name:e.target.value}))}
                      style={{fontSize:15,fontWeight:700,color:T.text,background:T.bgElevated,border:`1.5px solid ${T.accent}`,borderRadius:7,padding:"4px 8px",outline:"none",width:"100%",boxSizing:"border-box",marginBottom:7}}/>
                  : <div style={{fontSize:15,fontWeight:700,color:T.text,marginBottom:7}}>{tcDetail.name}</div>
                }
                <div style={{display:"flex",alignItems:"center",gap:6,flexWrap:"wrap"}}>
                  <DQStatusBadge status={tcDetail.status} size="lg"/>
                  <span style={{fontSize:11.5,padding:"2px 8px",borderRadius:5,background:`${dimColor(tcDetail.dim)}12`,color:dimColor(tcDetail.dim),fontWeight:600,border:`1px solid ${dimColor(tcDetail.dim)}22`}}>{tcDetail.dim}</span>
                  <span style={{fontSize:11,color:T.textMuted,fontFamily:"'Geist Mono',monospace"}}>{tcDetail.table}{tcDetail.col?`.${tcDetail.col}`:""}</span>
                </div>
              </div>
              <button onClick={()=>{setTcDetail(null);setTcDetailEditing(false);setTcDetailDraft(null);}} style={{width:30,height:30,borderRadius:8,background:T.bgHover,border:`1px solid ${T.border}`,color:T.textMuted,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>{Ic.x(11)}</button>
            </div>
          </div>
          {/* Body */}
          <div style={{flex:1,overflowY:"auto",padding:"20px 24px",display:"flex",flexDirection:"column",gap:20}}>
            {/* Latest result banner */}
            {(()=>{
              const sc=TC_STATUS_CFG[tcDetail.status]||TC_STATUS_CFG.Success;
              return (
                <div style={{padding:"14px 16px",background:sc.bg,border:`1.5px solid ${sc.color}28`,borderRadius:10}}>
                  <div style={{display:"flex",alignItems:"center",gap:8}}>
                    <DQStatusDot status={tcDetail.status}/>
                    <span style={{fontSize:11,fontWeight:700,color:sc.color}}>{sc.label}</span>
                    <span style={{fontSize:11,color:T.textMuted,marginLeft:"auto"}}>{tcDetail.lastRun}</span>
                  </div>
                  {tcDetail.failedReason&&(
                    <div style={{marginTop:8,fontSize:12.5,color:sc.color,lineHeight:1.6,padding:"8px 12px",background:`${sc.color}10`,borderRadius:7,border:`1px solid ${sc.color}22`}}>{tcDetail.failedReason}</div>
                  )}
                </div>
              );
            })()}
            {/* Result History */}
            <div>
              <div style={{fontSize:10.5,fontWeight:700,color:T.textMuted,letterSpacing:.5,marginBottom:10,textTransform:"uppercase"}}>Result History — Last 15 Runs</div>
              <div style={{display:"flex",gap:3,alignItems:"flex-end",height:40,marginBottom:4}}>
                {(tcDetail.history||[]).map((v,i)=>{
                  const col=v===0?T.rose:v<1?T.amber:"#16a34a";
                  return <div key={i} title={v===0?"Fail":v<1?"Warning":"Pass"} style={{flex:1,borderRadius:"3px 3px 0 0",background:col,height:`${Math.max(v===0?1:v,0.12)*100}%`,minHeight:5,opacity:i<10?0.55:0.85,cursor:"default",transition:"opacity .15s"}}
                    onMouseEnter={e=>e.currentTarget.style.opacity="1"} onMouseLeave={e=>e.currentTarget.style.opacity=i<10?"0.55":"0.85"}/>;
                })}
              </div>
              <div style={{height:1,background:T.border,marginBottom:4}}/>
              <div style={{display:"flex",justifyContent:"space-between",fontSize:10,color:T.textMuted}}>
                <span>15 runs ago</span><span>Latest</span>
              </div>
            </div>
            {(()=>{const l=tcPolicyLink(tcDetail);return l?(
              <div>
                <div style={{fontSize:10.5,fontWeight:700,color:T.textMuted,letterSpacing:.5,marginBottom:8,textTransform:"uppercase"}}>Governance</div>
                <PolicyChip link={l} onNav={typeof onNav!=="undefined"?onNav:undefined}/>
                <div style={{fontSize:11,color:T.textMuted,marginTop:6,lineHeight:1.5}}>A failure on this test traces up to the policy it enforces.</div>
              </div>
            ):null;})()}
            {/* Test Definition */}
            <div>
              <div style={{fontSize:10.5,fontWeight:700,color:T.textMuted,letterSpacing:.5,marginBottom:8,textTransform:"uppercase"}}>Test Definition</div>
              <div style={{padding:"13px 16px",background:T.bgElevated,borderRadius:10,border:`1px solid ${T.border}`}}>
                <div style={{fontSize:13,fontWeight:600,color:T.text,marginBottom:3}}>{tcDetail.defName}</div>
                <code style={{fontSize:11,color:T.violet,fontFamily:"'Geist Mono',monospace"}}>{DQ_TEST_DEFINITIONS.find(d=>d.id===tcDetail.defId)?.fn||""}</code>
              </div>
            </div>
            {/* Parameters */}
            {Object.keys(tcDetail.params||{}).length>0&&(
              <div>
                <div style={{fontSize:10.5,fontWeight:700,color:T.textMuted,letterSpacing:.5,marginBottom:8,textTransform:"uppercase"}}>Parameters</div>
                <div style={{display:"flex",flexDirection:"column",gap:6}}>
                  {Object.entries(tcDetailEditing?tcDetailDraft?.params||tcDetail.params:tcDetail.params).map(([k,v])=>(
                    <div key={k} style={{display:"flex",gap:12,padding:"9px 13px",background:T.bgElevated,borderRadius:8,border:`1px solid ${tcDetailEditing?T.accent:T.border}`,alignItems:"center"}}>
                      <span style={{fontSize:11.5,fontFamily:"'Geist Mono',monospace",color:T.textMuted,minWidth:130,flexShrink:0}}>{k}</span>
                      {tcDetailEditing
                        ? <input value={Array.isArray(v)?v.join(", "):String(v)}
                            onChange={e=>setTcDetailDraft(d=>({...d,params:{...(d.params||tcDetail.params),[k]:e.target.value}}))}
                            style={{flex:1,padding:"3px 8px",background:T.bgSurface,border:`1px solid ${T.border}`,borderRadius:5,color:T.text,fontSize:12,fontFamily:"'Geist Mono',monospace",outline:"none"}}
                            onFocus={e=>e.target.style.borderColor=T.accent} onBlur={e=>e.target.style.borderColor=T.border}/>
                        : <span style={{fontSize:12,fontFamily:"'Geist Mono',monospace",color:T.violet,flex:1}}>{Array.isArray(v)?v.join(", "):String(v)}</span>
                      }
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
          {/* Footer */}
          <div style={{padding:"12px 20px",borderTop:`1px solid ${T.border}`,flexShrink:0,background:T.bgElevated,display:"flex",alignItems:"center",gap:8}}>
            {tcDetailEditing ? <>
              <button onClick={()=>{
                setLocalCases(prev=>prev.map(t=>t.id===tcDetail.id?{...t,...tcDetailDraft}:t));
                setTcDetail(prev=>({...prev,...tcDetailDraft}));
                setTcDetailEditing(false);setTcDetailDraft(null);
                onToast&&onToast("Test case updated","success");
              }} style={{display:"inline-flex",alignItems:"center",gap:6,padding:"7px 18px",borderRadius:8,background:T.accent,border:"none",color:"#fff",fontSize:12,fontWeight:700,cursor:"pointer"}}>Save Changes</button>
              <button onClick={()=>{setTcDetailEditing(false);setTcDetailDraft(null);}}
                style={{display:"inline-flex",alignItems:"center",gap:6,padding:"7px 14px",borderRadius:8,background:"transparent",border:`1px solid ${T.border}`,color:T.textSub,fontSize:12,cursor:"pointer"}}>Cancel</button>
            </> : <>
              <button disabled={runningIds.has(tcDetail.id)} onClick={()=>runTest(tcDetail.id)}
                style={{display:"inline-flex",alignItems:"center",gap:6,padding:"7px 16px",borderRadius:8,background:T.accentDim,border:`1px solid ${T.accent}33`,color:T.accent,fontSize:12,fontWeight:600,cursor:runningIds.has(tcDetail.id)?"not-allowed":"pointer",opacity:runningIds.has(tcDetail.id)?0.5:1,whiteSpace:"nowrap"}}>
                <svg width="11" height="11" viewBox="0 0 12 12" fill="none"><path d="M3 2l7 4-7 4V2z" fill="currentColor"/></svg>
                {runningIds.has(tcDetail.id)?"Running…":"Run now"}
              </button>
              <button onClick={()=>{setTcDetailEditing(true);setTcDetailDraft({name:tcDetail.name,params:{...(tcDetail.params||{})}});}}
                style={{display:"inline-flex",alignItems:"center",gap:6,padding:"7px 16px",borderRadius:8,background:T.bgSurface,border:`1px solid ${T.border}`,color:T.textSub,fontSize:12,fontWeight:500,cursor:"pointer",whiteSpace:"nowrap"}}>
                <svg width="11" height="11" viewBox="0 0 12 12" fill="none"><path d="M8.5 1.5l2 2-7 7H1.5v-2l7-7z" stroke="currentColor" strokeWidth="1.2" strokeLinejoin="round"/></svg>
                Edit
              </button>
            </>}
            <button onClick={()=>{setLocalCases(prev=>prev.filter(t=>t.id!==tcDetail.id));setTcDetail(null);onToast&&onToast("Test case removed","error");}}
              style={{display:"inline-flex",alignItems:"center",gap:6,padding:"7px 14px",borderRadius:8,background:"transparent",border:`1px solid ${T.border}`,color:T.rose,fontSize:12,cursor:"pointer",marginLeft:"auto",whiteSpace:"nowrap"}}
              onMouseEnter={e=>{e.currentTarget.style.background=T.roseDim;e.currentTarget.style.borderColor=T.rose+"44";}} onMouseLeave={e=>{e.currentTarget.style.background="transparent";e.currentTarget.style.borderColor=T.border;}}>
              <svg width="11" height="11" viewBox="0 0 12 12" fill="none"><path d="M2 3h8M5 3V2h2v1M4 3v7h4V3" stroke="currentColor" strokeWidth="1.2" strokeLinecap="round" strokeLinejoin="round"/></svg>
              Remove
            </button>
          </div>
        </div>
      </div>,
      document.body
    )}
  </div>;
}
const AssetTagsTab = ({assetId, onToast}) => {
  const { tagDefs, getAssetAssignments, applyTag, removeTag, resolveInboxItem, getTagDef, startPropagation, getPropagationJobs, propagationJobs } = useTagCtx();
  const navigate = useNav();
  const [selectedAsgn, setSelectedAsgn] = useState(null);
  const [applyModalOpen, setApplyModalOpen] = useState(false);
  const [modalSearch, setModalSearch] = useState('');
  const [selectedTagId, setSelectedTagId] = useState(null);
  const [removeNote, setRemoveNote] = useState('');
  const [removingId, setRemovingId] = useState(null);
  const [propModal, setPropModal] = useState(null);   // assignment being propagated
  const [propScope, setPropScope] = useState('both'); // hierarchy | lineage | both

  // Estimated blast radius per scope (prototype heuristic; real impl walks the graph).
  const PROP_SCOPE_META = {
    hierarchy: { label:'Only hierarchy', desc:'Cascades to child objects in this schema / container.',                      color:T.amber, est:6  },
    lineage:   { label:'Only lineage',   desc:'Follows the lineage graph downstream — can cross connections.',              color:T.blue,  est:11 },
    both:      { label:'Hierarchy + lineage', desc:'Schema children AND downstream lineage assets. Maximum coverage.',       color:T.violet,est:15 },
  };

  const assignments = getAssetAssignments(assetId);
  const active = assignments.filter(a => a.status !== 'rejected');

  const catColors = { sensitivity:{bg:T.accentDim,color:T.accent}, regulatory:{bg:T.blueDim,color:T.blue}, business:{bg:T.amberDim,color:T.amber}, custom:{bg:T.bgElevated,color:T.textSub} };

  const catOrder = ['sensitivity','regulatory','business','custom'];
  const filteredTagDefs = modalSearch ? tagDefs.filter(td=>td.name.toLowerCase().includes(modalSearch.toLowerCase())) : tagDefs;
  const groupedTags = catOrder.map(cat=>({cat, tags:filteredTagDefs.filter(td=>td.category===cat)})).filter(g=>g.tags.length>0);

  const selectedTagDef = tagDefs.find(t=>t.id===selectedTagId);
  const impactCount = selectedTagId ? parseInt(selectedTagId.replace('t',''))*3+5 : 0;
  const propText = { none:'Applies to this asset only.', hierarchy:'Cascades to all child assets in this schema or domain.', lineage:'Cascades to all downstream assets in the data lineage graph.', both:'Maximum coverage — schema children AND downstream lineage assets.' };

  const handleApply = () => {
    if (!selectedTagId) return;
    applyTag(assetId, selectedTagId, { origin:'manual', appliedBy:'Current User' });
    setApplyModalOpen(false);
    setSelectedTagId(null);
    setModalSearch('');
    const def = getTagDef(selectedTagId);
    onToast(def?.governanceRequired ? `${def.name} submitted for approval` : `${def?.name} applied`,'success');
  };

  const handleRemove = (asgn) => {
    const def = getTagDef(asgn.tagId);
    if (def && (def.category==='sensitivity'||def.category==='regulatory')) {
      setRemovingId(asgn.id);
    } else {
      removeTag(assetId, asgn.id);
    }
  };

  const confirmRemove = () => {
    removeTag(assetId, removingId, removeNote);
    setRemovingId(null);
    setRemoveNote('');
  };

  const originText = (o, src) => {
    if (o==='manual') return `Applied manually`;
    if (o==='synced') return `Synced from ${src||'source'}`;
    if (o==='propagated_hierarchy') return 'Inherited via catalog hierarchy';
    if (o==='propagated_lineage') return 'Inherited via data lineage from upstream asset';
    if (o==='propagated_both') return 'Inherited via hierarchy and lineage';
    return o;
  };

  const selAsgn = active.find(a=>a.id===selectedAsgn);
  const selDef  = selAsgn ? getTagDef(selAsgn.tagId) : null;

  return (
    <div className="fadeIn">
      {/* Applied tags */}
      <div style={{marginBottom:4}}>
        <div style={{fontSize:10.5,fontWeight:700,color:T.textMuted,textTransform:'uppercase',letterSpacing:'0.06em',marginBottom:10}}>Applied tags</div>
        {active.length===0 ? (
          <div style={{fontSize:12,color:T.textMuted,marginBottom:10}}>No tags applied. Click + Add tag to get started.</div>
        ) : (
          <div style={{display:'flex',flexWrap:'wrap',gap:8,marginBottom:12}}>
            {active.map(a=>{
              const def = getTagDef(a.tagId);
              if (!def) return null;
              return (
                <TagPill key={a.id} tagDef={def} assignment={a} size='md'
                  onClick={()=>setSelectedAsgn(selectedAsgn===a.id?null:a.id)}
                  onRemove={()=>handleRemove(a)}/>
              );
            })}
          </div>
        )}
        <button onClick={()=>{setApplyModalOpen(true);setModalSearch('');setSelectedTagId(null);}} style={{fontSize:12,color:T.accent,background:'none',border:'none',cursor:'pointer',padding:0}}>+ Add tag</button>
      </div>

      {/* Remove confirm for governance tags */}
      {removingId&&(
        <div style={{background:T.amberDim,border:`1px solid ${T.amber}44`,borderRadius:8,padding:14,margin:'12px 0'}}>
          <div style={{fontSize:12.5,fontWeight:600,color:T.amber,marginBottom:8}}>This tag is governance-controlled. Add a note:</div>
          <textarea value={removeNote} onChange={e=>setRemoveNote(e.target.value)} rows={2} placeholder="Reason for removal…" style={{width:'100%',padding:'6px 9px',borderRadius:6,border:`1px solid ${T.border}`,background:T.bgSurface,color:T.text,fontSize:12,outline:'none',resize:'vertical',marginBottom:8}}/>
          <div style={{display:'flex',gap:8}}>
            <button onClick={confirmRemove} style={{padding:'5px 14px',background:T.rose,color:'#fff',border:'none',borderRadius:5,fontSize:12,cursor:'pointer'}}>Remove</button>
            <button onClick={()=>{setRemovingId(null);setRemoveNote('');}} style={{padding:'5px 14px',background:'transparent',border:`1px solid ${T.border}`,color:T.textSub,borderRadius:5,fontSize:12,cursor:'pointer'}}>Cancel</button>
          </div>
        </div>
      )}

      {/* Tag detail panel */}
      {selAsgn&&selDef&&(
        <div style={{background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:8,padding:14,marginTop:16}}>
          {[
            {l:'Tag',        v:<TagPill tagDef={selDef} assignment={selAsgn} size='md'/>},
            {l:'Category',   v:<span style={{fontSize:11,padding:'2px 8px',borderRadius:4,background:catColors[selDef.category]?.bg,color:catColors[selDef.category]?.color,fontWeight:500,textTransform:'capitalize'}}>{selDef.category}</span>},
            {l:'Origin',     v:<span style={{fontSize:12,color:T.textSub}}>{originText(selAsgn.origin,selAsgn.sourceSystem)}</span>},
            {l:'Confirmed by',v:selAsgn.sourceSystems?.length>0?<div style={{display:'flex',gap:4,flexWrap:'wrap'}}>{selAsgn.sourceSystems.map(s=><span key={s} style={{fontSize:10,padding:'2px 6px',borderRadius:3,background:T.bgSurface,border:`1px solid ${T.border}`,color:T.textSub}}>{s}</span>)}</div>:<span style={{fontSize:12,color:T.textMuted}}>—</span>},
            {l:'Propagation', v:<span style={{fontSize:12,color:T.textSub}}>{selDef.propagationMode==='none'?'None — this asset only':selDef.propagationMode==='hierarchy'?'Hierarchy — schema children':selDef.propagationMode==='lineage'?'Lineage — downstream assets':'H+L — maximum coverage'}</span>},
            {l:'Status',      v:<span style={{fontSize:12,fontWeight:500,color:selAsgn.status==='active'?T.green:selAsgn.status==='pending'?T.amber:selAsgn.status==='conflict'?T.rose:T.textMuted}}>{selAsgn.status==='active'?'Active':selAsgn.status==='pending'?'Pending approval':selAsgn.status==='conflict'?'Conflict':'Rejected'}</span>},
            {l:'Steward',     v:<span style={{fontSize:12,color:T.textSub}}>{selDef.managedBy||'—'}</span>},
            {l:'Applied',     v:<span style={{fontSize:12,color:T.textSub}}>{selAsgn.appliedAt?selAsgn.appliedAt.slice(0,10):'—'}</span>},
          ].map((row,i,arr)=>(
            <div key={row.l} style={{display:'grid',gridTemplateColumns:'110px 1fr',gap:8,padding:'7px 0',borderBottom:i<arr.length-1?`1px solid ${T.border}`:'none',alignItems:'start'}}>
              <span style={{fontSize:11,color:T.textMuted,fontWeight:500}}>{row.l}</span>
              {row.v}
            </div>
          ))}
          {selAsgn.stewardNote&&<div style={{background:T.amberDim,border:`1px solid ${T.amber}33`,borderRadius:6,padding:'8px 12px',marginTop:10,fontSize:11.5,color:T.amber}}>Steward note: "{selAsgn.stewardNote}"</div>}
          {/* Steward actions */}
          <div style={{marginTop:12,display:'flex',gap:8,flexWrap:'wrap'}}>
            {selAsgn.status==='pending'&&<><button onClick={()=>{resolveInboxItem('i'+assetId,'approve');onToast('Tag approved','success');}} style={{padding:'5px 12px',background:'transparent',border:`1px solid ${T.accent}`,color:T.accent,borderRadius:5,fontSize:12,cursor:'pointer'}}>Approve</button><button onClick={()=>{removeTag(assetId,selAsgn.id,'Rejected by steward');onToast('Tag rejected','success');setSelectedAsgn(null);}} style={{padding:'5px 12px',background:'none',border:'none',color:T.textMuted,fontSize:12,cursor:'pointer'}}>Reject</button></>}
            {selAsgn.status==='conflict'&&<><button onClick={()=>{}} style={{padding:'5px 12px',background:'transparent',border:`1px solid ${T.accent}`,color:T.accent,borderRadius:5,fontSize:12,cursor:'pointer'}}>Keep override</button><button onClick={()=>{}} style={{padding:'5px 12px',background:'transparent',border:`1px solid ${T.border}`,color:T.textSub,borderRadius:5,fontSize:12,cursor:'pointer'}}>Accept source</button></>}
          </div>
          {/* Propagate — explicit, tracked background job */}
          <div style={{marginTop:12,paddingTop:12,borderTop:`1px solid ${T.border}`}}>
            {(()=>{
              const jobs = getPropagationJobs(assetId, selAsgn.tagId);
              const latest = jobs[0];
              return (
                <div style={{display:'flex',alignItems:'center',gap:10,flexWrap:'wrap'}}>
                  <button onClick={()=>{ const m=selDef.propagationMode; setPropScope((m==='hierarchy'||m==='lineage'||m==='both')?m:'both'); setPropModal(selAsgn); }}
                    style={{display:'inline-flex',alignItems:'center',gap:6,padding:'6px 12px',borderRadius:6,background:T.accentDim,border:`1px solid ${T.accent}44`,color:T.accent,fontSize:12,fontWeight:600,cursor:'pointer'}}>
                    ⇄ Propagate…
                  </button>
                  {latest&&(
                    <span style={{fontSize:11.5,color:latest.status==='done'?T.green:T.amber,display:'inline-flex',alignItems:'center',gap:6}}>
                      {latest.status==='done'
                        ? <>✓ Last propagated {latest.scope} · {latest.updated} object{latest.updated!==1?'s':''}</>
                        : <><span style={{width:9,height:9,borderRadius:'50%',border:`2px solid ${T.amber}`,borderTopColor:'transparent',display:'inline-block',animation:'spin 1s linear infinite'}}/> Propagating {latest.scope}… {latest.updated}/{latest.target}</>}
                    </span>
                  )}
                </div>
              );
            })()}
          </div>
          {!selDef.propagationLocked ? (
            <button onClick={()=>{handleRemove(selAsgn);setSelectedAsgn(null);}} style={{fontSize:12,color:T.rose,background:'none',border:'none',cursor:'pointer',marginTop:10,padding:0}}>Remove this tag</button>
          ) : (
            <div style={{fontSize:11,color:T.textMuted,marginTop:10}}>Tag is governance-locked. Contact your admin to remove.</div>
          )}
        </div>
      )}

      {/* Apply Modal */}
      {applyModalOpen&&(
        <div style={{position:'absolute',top:0,left:0,right:0,bottom:0,background:'rgba(0,0,0,0.5)',zIndex:50,display:'flex',alignItems:'center',justifyContent:'center',borderRadius:8}}>
          <div style={{background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:8,width:420,maxHeight:'80vh',display:'flex',flexDirection:'column',boxShadow:'0 16px 48px rgba(0,0,0,0.4)'}}>
            <div style={{padding:'14px 16px',borderBottom:`1px solid ${T.border}`,display:'flex',alignItems:'center',justifyContent:'space-between'}}>
              <div style={{fontSize:13,fontWeight:700,color:T.text}}>Apply tag</div>
              <button onClick={()=>setApplyModalOpen(false)} style={{background:'none',border:'none',color:T.textMuted,cursor:'pointer',fontSize:16}}>×</button>
            </div>
            <div style={{padding:'10px 12px',borderBottom:`1px solid ${T.border}`}}>
              <input value={modalSearch} onChange={e=>setModalSearch(e.target.value)} placeholder="Search tags…" autoFocus style={{width:'100%',padding:'7px 10px',borderRadius:6,border:`1px solid ${T.border}`,background:T.bgSurface,color:T.text,fontSize:12,outline:'none'}}/>
            </div>
            <div style={{flex:1,overflowY:'auto',padding:'8px 0'}}>
              {groupedTags.map(({cat,tags})=>(
                <div key={cat}>
                  <div style={{padding:'6px 14px 3px',fontSize:10,fontWeight:700,color:T.textMuted,textTransform:'uppercase',letterSpacing:'0.08em'}}>{cat}</div>
                  {tags.map(td=>{
                    const alreadyApplied = active.some(a=>a.tagId===td.id);
                    const isSelected = selectedTagId===td.id;
                    return (
                      <div key={td.id} onClick={()=>!alreadyApplied&&setSelectedTagId(td.id)}
                        style={{display:'flex',alignItems:'center',gap:10,padding:'7px 14px',cursor:alreadyApplied?'default':'pointer',background:isSelected?T.bgHover:'transparent',opacity:alreadyApplied?0.5:1,transition:'background .1s'}}
                        onMouseEnter={e=>{if(!alreadyApplied&&!isSelected)e.currentTarget.style.background=T.bgHover;}}
                        onMouseLeave={e=>{if(!isSelected)e.currentTarget.style.background='transparent';}}>
                        <TagPill tagDef={td} size='sm'/>
                        <span style={{flex:1,fontSize:11.5,color:T.textSub,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{td.description}</span>
                        {alreadyApplied&&<span style={{fontSize:10,color:T.green}}>✓ Applied</span>}
                      </div>
                    );
                  })}
                </div>
              ))}
            </div>
            {selectedTagDef&&(
              <div style={{padding:12,borderTop:`1px solid ${T.border}`,background:T.bgSurface,borderRadius:'0 0 8px 8px'}}>
                <div style={{display:'flex',alignItems:'center',gap:8,marginBottom:8}}>
                  <TagPill tagDef={selectedTagDef} size='sm'/>
                  <span style={{fontSize:11,padding:'2px 7px',borderRadius:4,background:T.bgElevated,color:T.textSub}}>{selectedTagDef.propagationMode}</span>
                </div>
                <div style={{fontSize:11.5,color:T.textSub,marginBottom:4}}>{propText[selectedTagDef.propagationMode]}</div>
                <div style={{fontSize:11,color:T.textMuted,marginBottom:selectedTagDef.governanceRequired?8:0}}>Estimated impact: ~{impactCount} assets</div>
                {selectedTagDef.governanceRequired&&<div style={{background:T.amberDim,border:`1px solid ${T.amber}33`,borderRadius:5,padding:'6px 10px',fontSize:11.5,color:T.amber}}>Governance required — needs steward approval</div>}
              </div>
            )}
            <div style={{padding:'10px 12px',borderTop:`1px solid ${T.border}`}}>
              <button onClick={handleApply} disabled={!selectedTagId} style={{width:'100%',padding:'8px',background:selectedTagId?T.accent:T.bgHover,color:selectedTagId?'#fff':T.textMuted,border:'none',borderRadius:6,fontSize:13,fontWeight:600,cursor:selectedTagId?'pointer':'default',marginBottom:6}}>Apply tag</button>
              <button onClick={()=>setApplyModalOpen(false)} style={{display:'block',width:'100%',background:'none',border:'none',color:T.textMuted,fontSize:12,cursor:'pointer',textAlign:'center'}}>Cancel</button>
            </div>
          </div>
        </div>
      )}

      {/* Propagate Modal — explicit scope + tracked background job + history */}
      {propModal&&(()=>{
        const pDef = getTagDef(propModal.tagId);
        if(!pDef) return null;
        const locked = pDef.propagationLocked;
        const lockedScope = (pDef.propagationMode==='hierarchy'||pDef.propagationMode==='lineage'||pDef.propagationMode==='both')?pDef.propagationMode:'both';
        const scope = locked ? lockedScope : propScope;
        const est = PROP_SCOPE_META[scope].est;
        const crossConn = scope==='lineage'||scope==='both';
        const history = getPropagationJobs(assetId, propModal.tagId);
        return (
          <div style={{position:'absolute',top:0,left:0,right:0,bottom:0,background:'rgba(0,0,0,0.5)',zIndex:60,display:'flex',alignItems:'center',justifyContent:'center',borderRadius:8}} onClick={()=>setPropModal(null)}>
            <div onClick={e=>e.stopPropagation()} style={{background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:10,width:460,maxHeight:'86vh',display:'flex',flexDirection:'column',boxShadow:'0 16px 48px rgba(0,0,0,0.4)'}}>
              <div style={{padding:'14px 16px',borderBottom:`1px solid ${T.border}`,display:'flex',alignItems:'center',justifyContent:'space-between'}}>
                <div style={{display:'flex',alignItems:'center',gap:8}}><span style={{fontSize:13,fontWeight:700,color:T.text}}>Propagate</span><TagPill tagDef={pDef} size='sm'/></div>
                <button onClick={()=>setPropModal(null)} style={{background:'none',border:'none',color:T.textMuted,cursor:'pointer',fontSize:16}}>×</button>
              </div>

              <div style={{padding:'16px',overflowY:'auto',display:'flex',flexDirection:'column',gap:16}}>
                {/* Scope picker */}
                <div>
                  <div style={{fontSize:10.5,fontWeight:700,color:T.textMuted,textTransform:'uppercase',letterSpacing:'0.06em',marginBottom:8}}>Propagation scope</div>
                  {locked ? (
                    <div style={{display:'flex',alignItems:'center',gap:8,padding:'9px 12px',borderRadius:7,background:T.bgSurface,border:`1px solid ${T.border}`}}>
                      <span style={{fontSize:12.5,fontWeight:600,color:PROP_SCOPE_META[scope].color}}>{PROP_SCOPE_META[scope].label}</span>
                      <span style={{fontSize:11,color:T.textMuted}}>🔒 locked by governance policy</span>
                    </div>
                  ) : (
                    <div style={{display:'flex',gap:6}}>
                      {['hierarchy','lineage','both'].map(s=>{
                        const sm=PROP_SCOPE_META[s]; const sel=propScope===s;
                        return (
                          <button key={s} onClick={()=>setPropScope(s)} style={{flex:1,padding:'8px 6px',borderRadius:7,border:`1.5px solid ${sel?sm.color:T.border}`,background:sel?`${sm.color}18`:'transparent',color:sel?sm.color:T.textSub,fontSize:11.5,fontWeight:sel?700:500,cursor:'pointer',transition:'all .12s'}}>{sm.label}</button>
                        );
                      })}
                    </div>
                  )}
                  <div style={{fontSize:11.5,color:T.textMuted,marginTop:8,lineHeight:1.5}}>{PROP_SCOPE_META[scope].desc}</div>
                </div>

                {/* Blast-radius preview */}
                <div style={{padding:'12px 14px',background:T.bgSurface,border:`1px solid ${T.border}`,borderRadius:8}}>
                  <div style={{display:'flex',alignItems:'center',gap:8}}>
                    <span style={{fontSize:18,fontWeight:800,color:PROP_SCOPE_META[scope].color,fontFamily:"'Geist Mono',monospace"}}>~{est}</span>
                    <span style={{fontSize:12.5,color:T.textSub}}>object{est!==1?'s':''} will inherit this tag</span>
                  </div>
                  {crossConn && <div style={{fontSize:11,color:T.blue,marginTop:6,display:'flex',alignItems:'center',gap:5}}>↗ Lineage can cross connections — downstream assets in other sources will be tagged (flagged with provenance).</div>}
                </div>

                <div style={{fontSize:11,color:T.textMuted,display:'flex',alignItems:'flex-start',gap:6,lineHeight:1.5}}>
                  <span style={{flexShrink:0}}>ℹ</span> Propagation runs as a background job. You can track its status and history below.
                </div>

                {/* History */}
                {history.length>0&&(
                  <div>
                    <div style={{fontSize:10.5,fontWeight:700,color:T.textMuted,textTransform:'uppercase',letterSpacing:'0.06em',marginBottom:8}}>Propagation history</div>
                    <div style={{border:`1px solid ${T.border}`,borderRadius:8,overflow:'hidden'}}>
                      {history.slice(0,5).map((j,i)=>(
                        <div key={j.id} style={{display:'flex',alignItems:'center',gap:8,padding:'8px 12px',borderBottom:i<Math.min(history.length,5)-1?`1px solid ${T.border}`:'none',background:i%2?T.bgSurface:'transparent'}}>
                          <span style={{width:7,height:7,borderRadius:'50%',background:j.status==='done'?T.green:T.amber,flexShrink:0}}/>
                          <span style={{fontSize:11.5,color:T.textSub,textTransform:'capitalize',flex:1}}>{j.scope} · {j.status==='done'?`${j.updated} object${j.updated!==1?'s':''}`:`${j.updated}/${j.target} …`}</span>
                          <span style={{fontSize:10.5,color:T.textMuted,fontFamily:"'Geist Mono',monospace"}}>{(j.startedAt||'').slice(0,10)}</span>
                          <span style={{fontSize:10.5,color:T.textMuted}}>{j.by}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>

              <div style={{padding:'12px 16px',borderTop:`1px solid ${T.border}`,display:'flex',gap:8,justifyContent:'flex-end'}}>
                <button onClick={()=>setPropModal(null)} style={{padding:'8px 14px',background:'transparent',border:`1px solid ${T.border}`,color:T.textSub,borderRadius:7,fontSize:12.5,cursor:'pointer'}}>Cancel</button>
                <button onClick={()=>{ startPropagation(assetId, propModal.tagId, scope, {target:est, by:'Current User'}); onToast(`Propagating ${pDef.name} (${scope}) — running in background`,'success'); setPropModal(null); }}
                  style={{padding:'8px 18px',background:T.accent,border:'none',color:'#fff',borderRadius:7,fontSize:12.5,fontWeight:700,cursor:'pointer'}}>Propagate now</button>
              </div>
            </div>
          </div>
        );
      })()}
    </div>
  );
};

