// ASSET DETAIL
// ─────────────────────────────────────────────
// ── Container asset detail (Database / Catalog / Schema / Bucket / Container / Folder) ──
const ContainerAssetDetail = ({asset, assetStack, onBack, onAsset, onToast}) => {
  const navFn = useNav();
  const [tab,          setTab]         = useState("overview");
  const [data,         setData]        = useState({...asset, owners:asset.owners||[asset.owner], stewards:asset.stewards||(asset.steward?[asset.steward]:[]), tags:[...(asset.tags||[])]});
  const [certOpen,       setCertOpen]       = useState(false);
  const [editModal,      setEditModal]      = useState(null);
  const [certModal,      setCertModal]      = useState(false);
  const [certNote,       setCertNote]       = useState("");
  const [domainOpen,     setDomainOpen]     = useState(false);
  const [domainSearch,   setDomainSearch]   = useState("");
  const [ownersOpen,     setOwnersOpen]     = useState(false);
  const [ownersSearch,   setOwnersSearch]   = useState("");
  const [stewardsOpen,   setStewardsOpen]   = useState(false);
  const [stewardsSearch, setStewardsSearch] = useState("");
  const [tagsOpen,       setTagsOpen]       = useState(false);
  const [tagsSearch,     setTagsSearch]     = useState("");
  const [showAllOwners,  setShowAllOwners]  = useState(false);
  const [showAllStewards,setShowAllStewards]= useState(false);
  const [showAllTags,    setShowAllTags]    = useState(false);
  const [assetGlTerms,   setAssetGlTerms]  = useState([]);
  const [assetGlOpen,    setAssetGlOpen]   = useState(false);
  const [assetGlSearch,  setAssetGlSearch] = useState("");
  const [editDesc,       setEditDesc]       = useState(false);
  const [descVal,      setDescVal]     = useState(asset.description||"");
  const [editNotes,    setEditNotes]   = useState(false);
  const [notesVal,     setNotesVal]    = useState(`The ${asset.name} ${asset.type.toLowerCase()} is part of the ${asset.domain||"Platform"} domain.\n\nManaged by ${asset.owner||"the data team"} and refreshed on a ${asset.slaFreshness||"regular"} schedule.`);
  const [contSearch,   setContSearch]  = useState("");

  const children  = ASSETS.filter(a=>a.parentId===asset.id);
  const stackCrumbs = assetStack.slice(0,-1);

  const DOMAINS_LIST = ["Commerce","Finance","Product","Marketing","ML","Engineering"];
  const USERS_LIST   = ["maya.chen","sarah.kim","alex.wu","dev.patel","lisa.ray","priya.nair","james.oh"];
  const ava = name => (name||"?").split(".").map(s=>s[0]?.toUpperCase()||"").join("");

  const CMETA = {
    "Draft":      {color:"#6b7280",bg:"rgba(107,114,128,.1)", border:"rgba(107,114,128,.25)",icon:"◐"},
    "In Review":  {color:"#d97706",bg:"rgba(217,119,6,.12)",  border:"rgba(217,119,6,.3)",   icon:"⏳"},
    "Approved":   {color:"#16a34a",bg:"rgba(22,163,74,.12)",  border:"rgba(22,163,74,.3)",   icon:"✓"},
    "Rejected":   {color:"#e11d48",bg:"rgba(225,29,72,.12)",  border:"rgba(225,29,72,.3)",   icon:"✕"},
    "Deprecated": {color:"#7c3aed",bg:"rgba(124,58,237,.1)",  border:"rgba(124,58,237,.25)", icon:"—"},
  };
  const cm = CMETA[data.cert]||CMETA["Draft"];
  const owners   = Array.isArray(data.owners)  ? data.owners   : (data.owner   ? [data.owner]   : []);
  const stewards = Array.isArray(data.stewards) ? data.stewards : (data.steward ? [data.steward] : []);
  // Who can assign the roster directly (owner/admin) vs. who must request (everyone else).
  const {role:_rbacRole, roleCfg:_rcfg} = useRole();
  const meHandle = ((_rcfg&&_rcfg.email)||"you@jnj").split("@")[0];
  const _roleReqsAll = useRoleReqs();
  const canAssign = _rbacRole==="admin" || owners.includes(meHandle) || data.owner===meHandle;
  const pendingFor = (r)=>_roleReqsAll.filter(x=>x.kind==="asset"&&x.status==="pending"&&x.asset===data.name&&x.role===r);
  const myPending  = (r)=>pendingFor(r).some(x=>x.requestedBy===meHandle);
  const requestRole = (r)=>{ addRoleRequest({kind:"asset",asset:data.name,role:r,requestedBy:meHandle,note:"Requested via asset profile",approver:owners[0]||data.owner||"the domain owner"}); onToast&&onToast(`${r==="owner"?"Ownership":"Stewardship"} requested — pending approval`,"success"); };

  useEffect(()=>{
    if(!certOpen) return;
    const close=()=>setCertOpen(false);
    document.addEventListener("mousedown",close);
    return ()=>document.removeEventListener("mousedown",close);
  },[certOpen]);

  const handleCertify = () => { setData(d=>({...d,cert:"Approved"})); setCertModal(false); onToast(`${asset.name} status set to Approved`,"success"); };

  const MetaLabel = ({children,onEdit,cta})=>(
    <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:8}}>
      <div style={{fontSize:10.5,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.08em"}}>{children}</div>
      {onEdit&&(cta
        ? <button onClick={onEdit} style={{background:"none",border:`1px solid ${T.border}`,cursor:"pointer",color:T.textSub,fontSize:10,fontWeight:700,letterSpacing:"0.03em",padding:"2px 9px",borderRadius:6,transition:"all .12s"}}
            onMouseEnter={e=>{e.currentTarget.style.borderColor=T.accent;e.currentTarget.style.color=T.accent;}}
            onMouseLeave={e=>{e.currentTarget.style.borderColor=T.border;e.currentTarget.style.color=T.textSub;}}>{cta}</button>
        : <button onClick={onEdit} style={{background:"none",border:"none",cursor:"pointer",color:T.textMuted,padding:"2px 3px",display:"flex",borderRadius:4,transition:"all .12s"}}
            onMouseEnter={e=>{e.currentTarget.style.color=T.accent;e.currentTarget.style.background=T.accentDim;}}
            onMouseLeave={e=>{e.currentTarget.style.color=T.textMuted;e.currentTarget.style.background="none";}}>
            <svg width="11" height="11" viewBox="0 0 14 14" fill="none"><path d="M9.5 2.5l2 2L4 12H2v-2L9.5 2.5z" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round" strokeLinejoin="round"/></svg>
          </button>)}
    </div>
  );

  const FILE_FORMAT_COLORS = {CSV:"#16a34a",Parquet:"#0891b2",JSON:"#d97706",ORC:"#7c3aed"};
  const TAG_C = {
    PII:{bg:"rgba(225,29,72,.1)",color:"#e11d48",border:"rgba(225,29,72,.25)"},
    revenue:{bg:"rgba(37,99,235,.08)",color:"#2563eb",border:"rgba(37,99,235,.2)"},
    finance:{bg:"rgba(37,99,235,.08)",color:"#2563eb",border:"rgba(37,99,235,.2)"},
    KPI:{bg:"rgba(22,163,74,.08)",color:"#16a34a",border:"rgba(22,163,74,.2)"},
    sensitive:{bg:"rgba(124,58,237,.08)",color:"#7c3aed",border:"rgba(124,58,237,.2)"},
    events:{bg:"rgba(6,182,212,.08)",color:"#0891b2",border:"rgba(6,182,212,.2)"},
    model:{bg:"rgba(99,102,241,.08)",color:"#6366f1",border:"rgba(99,102,241,.2)"},
    etl:{bg:"rgba(245,158,11,.08)",color:"#d97706",border:"rgba(245,158,11,.2)"},
  };
  const tc = tag => TAG_C[tag]||{bg:T.bgElevated,color:T.textSub,border:T.border};

  const CHILD_COLS = [
    {key:"name", label:"Name", render:(v,r)=>(
      <div style={{display:"flex",alignItems:"center",gap:8}}>
        <ServiceIcon service={r.service} size={16}/>
        <div style={{flex:1,minWidth:0}}>
          <div style={{display:"flex",alignItems:"center",gap:5}}>
            <span style={{fontSize:12.5,fontWeight:500,color:T.text,fontFamily:"'Geist Mono',monospace"}}>{v}</span>
            {r.fileFormat&&<span style={{fontSize:9,fontWeight:700,padding:"1px 4px",borderRadius:3,background:`${FILE_FORMAT_COLORS[r.fileFormat]||T.textMuted}18`,color:FILE_FORMAT_COLORS[r.fileFormat]||T.textMuted,border:`1px solid ${FILE_FORMAT_COLORS[r.fileFormat]||T.textMuted}33`}}>{r.fileFormat}</span>}
            {CONTAINER_TYPES.has(r.type)&&<span style={{fontSize:9,fontWeight:700,padding:"1px 6px",borderRadius:3,background:T.accentDim,color:T.accent,border:`1px solid ${T.accent}33`,letterSpacing:"0.03em"}}>Browse →</span>}
          </div>
          {r.db&&<div style={{fontSize:10,color:T.textMuted,fontFamily:"'Geist Mono',monospace"}}>{r.db}</div>}
        </div>
      </div>
    )},
    {key:"type",    label:"Type",    render:v=><TypeBadge type={v}/>},
    {key:"domain",  label:"Domain",  render:v=><span style={{fontSize:11.5,color:T.textSub}}>{v}</span>},
    {key:"owner",   label:"Owner",   render:v=><span style={{fontSize:11.5,color:T.textMuted,fontFamily:"'Geist Mono',monospace"}}>{v}</span>},
    {key:"cert",    label:"Cert",    render:(v,r)=>["Object","Blob","Folder"].includes(r.type)?<span style={{color:T.textMuted}}>—</span>:<CertBadge cert={v}/>},
    {key:"quality", label:"Quality", render:v=><QScore score={v}/>},
    {key:"size",    label:"Size",    render:(v,r)=>v&&v!=="—"?<span style={{fontSize:11,fontFamily:"'Geist Mono',monospace",color:T.textSub}}>{v}</span>:r.rows&&r.rows!=="—"?<span style={{fontSize:11,fontFamily:"'Geist Mono',monospace",color:T.textSub}}>{r.rows} rows</span>:<span style={{color:T.textMuted}}>—</span>},
    {key:"updated", label:"Updated", render:v=><span style={{fontSize:11,color:T.textMuted}}>{v}</span>},
  ];

  const filteredChildren = children.filter(c=>
    !contSearch || c.name.toLowerCase().includes(contSearch.toLowerCase()) || (c.type||"").toLowerCase().includes(contSearch.toLowerCase())
  );

  // child quality stats
  const scoredChildren = children.filter(c=>Number.isFinite(c.quality)&&c.quality>0);
  const avgQuality = scoredChildren.length ? Math.round(scoredChildren.reduce((s,c)=>s+c.quality,0)/scoredChildren.length) : null;
  const childTypeCounts = children.reduce((acc,c)=>{ acc[c.type]=(acc[c.type]||0)+1; return acc; },{});

  return (
    <div className="fadeUp" style={{height:"100%",display:"flex",flexDirection:"column"}}>
      <Topbar breadcrumb={[
        {label:"Data Catalog", onClick:()=>{ onBack(); stackCrumbs.forEach(()=>onBack()); }},
        ...stackCrumbs.map((a,i)=>({label:a.name, onClick:()=>{ const popCount=assetStack.length-1-i; for(let j=0;j<popCount;j++) onBack(); }})),
        {label:asset.name}
      ]}/>

      {/* ── Asset header ── */}
      <div style={{background:T.bgSurface,borderBottom:`1px solid ${T.border}`,flexShrink:0,padding:"16px 28px 0"}}>
        <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:8}}>
          <TypeBadge type={asset.type}/>
          <span style={{fontSize:11.5,color:T.textMuted,fontFamily:"'Geist Mono',monospace"}}>{asset.db||asset.connectionLabel}</span>
        </div>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:12,marginBottom:14}}>
          <h2 style={{fontSize:22,fontWeight:700,fontFamily:"'Geist Mono',monospace",color:T.text,letterSpacing:"-0.04em",margin:0}}>{data.name}</h2>
          <div style={{display:"flex",gap:7,alignItems:"center",flexShrink:0}}>
            {data.cert!=="Approved"&&(
              <button onClick={()=>setCertModal(true)}
                style={{display:"inline-flex",alignItems:"center",gap:6,padding:"6px 14px",borderRadius:8,background:"#16a34a12",border:"1px solid rgba(22,163,74,.3)",color:"#16a34a",fontSize:12.5,fontWeight:600,cursor:"pointer",transition:"opacity .1s"}}
                onMouseEnter={e=>e.currentTarget.style.opacity=".8"} onMouseLeave={e=>e.currentTarget.style.opacity="1"}>
                {Ic.cert(12)} Set status
              </button>
            )}
            <button onClick={()=>onToast("Edit panel coming soon","success")}
              style={{display:"inline-flex",alignItems:"center",gap:6,padding:"6px 14px",borderRadius:8,background:T.bgElevated,border:`1px solid ${T.border}`,color:T.textSub,fontSize:12.5,fontWeight:500,cursor:"pointer",transition:"all .1s"}}
              onMouseEnter={e=>{e.currentTarget.style.borderColor=T.accent;e.currentTarget.style.color=T.accent;}}
              onMouseLeave={e=>{e.currentTarget.style.borderColor=T.border;e.currentTarget.style.color=T.textSub;}}>
              {Ic.edit(11)} Edit
            </button>
          </div>
        </div>
        <div style={{display:"flex",marginBottom:-1}}>
          {[{k:"overview",l:"Overview"},{k:"assets",l:`Assets (${children.length})`},{k:"customprops",l:"Custom Properties"}].map(t=>(
            <button key={t.k} onClick={()=>setTab(t.k)}
              style={{padding:"9px 16px",background:"transparent",border:"none",borderBottom:`2px solid ${tab===t.k?T.accent:"transparent"}`,color:tab===t.k?T.text:T.textMuted,fontSize:13,fontWeight:tab===t.k?600:400,cursor:"pointer",transition:"all .12s",whiteSpace:"nowrap"}}>
              {t.l}
            </button>
          ))}
        </div>
      </div>

      {/* ── Body ── */}
      <div style={{flex:1,display:"flex",overflow:"hidden"}}>

        {/* Main content */}
        <div style={{flex:1,overflowY:"auto",padding:24,minWidth:0}}>

          {tab==="customprops"&&(
            <CustomPropsPanel entity={data.type} objectId={data.name} objectName={data.name} owners={data.owners||[]} stewards={data.stewards||[]} onToast={onToast}/>
          )}

          {tab==="overview"&&(
            <div style={{display:"flex",flexDirection:"column",gap:16,maxWidth:900}}>

              {/* Description */}
              <Card2>
                <div style={{padding:"14px 16px"}}>
                  <SH title="Description" action={
                    editDesc
                      ? <div style={{display:"flex",gap:6}}>
                          <Btn small ghost onClick={()=>{setData(d=>({...d,description:descVal}));setEditDesc(false);onToast("Description saved","success");}}>Save</Btn>
                          <Btn small ghost onClick={()=>{setDescVal(data.description||asset.description||"");setEditDesc(false);}}>Cancel</Btn>
                        </div>
                      : <Btn small ghost icon={Ic.edit(11)} onClick={()=>setEditDesc(true)}>Edit</Btn>
                  }/>
                  {editDesc
                    ? <textarea value={descVal} onChange={e=>setDescVal(e.target.value)} rows={3}
                        style={{width:"100%",padding:"9px 12px",background:T.bgElevated,border:`1.5px solid ${T.accent}`,borderRadius:8,color:T.text,fontSize:13,outline:"none",resize:"vertical",lineHeight:1.7,fontFamily:"inherit",boxSizing:"border-box"}}/>
                    : <p style={{fontSize:13,color:descVal?T.textSub:T.textMuted,lineHeight:1.8,margin:0,fontStyle:descVal?"normal":"italic"}}>{descVal||"No description. Click Edit to add one."}</p>
                  }
                </div>
              </Card2>

              {/* Contents summary */}
              {children.length>0&&(
                <Card2>
                  <div style={{padding:"14px 16px"}}>
                    <SH title="Asset Summary"/>
                    <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(120px,1fr))",gap:10,marginBottom:16}}>
                      <div style={{background:T.bgElevated,borderRadius:8,padding:"12px 14px",border:`1px solid ${T.border}`}}>
                        <div style={{fontSize:22,fontWeight:700,color:T.text,fontFamily:"'Geist Mono',monospace",lineHeight:1}}>{children.length}</div>
                        <div style={{fontSize:11,color:T.textMuted,marginTop:4}}>Direct children</div>
                      </div>
                      {avgQuality!==null&&(
                        <div style={{background:T.bgElevated,borderRadius:8,padding:"12px 14px",border:`1px solid ${T.border}`}}>
                          <div style={{fontSize:22,fontWeight:700,color:avgQuality>=80?T.green:avgQuality>=60?"#d97706":T.rose,fontFamily:"'Geist Mono',monospace",lineHeight:1}}>{avgQuality}</div>
                          <div style={{fontSize:11,color:T.textMuted,marginTop:4}}>Avg quality</div>
                        </div>
                      )}
                      <div style={{background:T.bgElevated,borderRadius:8,padding:"12px 14px",border:`1px solid ${T.border}`}}>
                        <div style={{fontSize:22,fontWeight:700,color:T.green,fontFamily:"'Geist Mono',monospace",lineHeight:1}}>{children.filter(c=>c.cert==="Approved").length}</div>
                        <div style={{fontSize:11,color:T.textMuted,marginTop:4}}>Approved</div>
                      </div>
                    </div>
                    {Object.keys(childTypeCounts).length>0&&(
                      <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
                        {Object.entries(childTypeCounts).map(([type,count])=>(
                          <button key={type} onClick={()=>setTab("assets")}
                            style={{display:"inline-flex",alignItems:"center",gap:6,padding:"4px 10px",borderRadius:6,background:T.bgElevated,border:`1px solid ${T.border}`,cursor:"pointer",transition:"all .1s"}}
                            onMouseEnter={e=>{e.currentTarget.style.borderColor=T.accent;e.currentTarget.style.background=T.accentDim;}}
                            onMouseLeave={e=>{e.currentTarget.style.borderColor=T.border;e.currentTarget.style.background=T.bgElevated;}}>
                            <TypeBadge type={type}/>
                            <span style={{fontSize:12,color:T.textSub,fontWeight:500}}>{count}</span>
                          </button>
                        ))}
                      </div>
                    )}
                  </div>
                </Card2>
              )}

              {/* Governance */}
              {(()=>{
                const govPols = DEMO_POLICIES_GLOBAL.filter(p=>{
                  const domainMatch = (p.scope?.domains||[]).includes(asset.domain);
                  const nameMatch   = (p.links||[]).some(l=>l.target===asset.name);
                  return domainMatch||nameMatch;
                });
                if(!govPols.length) return null;
                const LC_COLOR = {Active:T.green,"In Review":T.amber,Draft:T.textMuted,Approved:T.blue,Deprecated:T.rose};
                const govRegs = [...new Set(govPols.flatMap(p=>p.regulations||[]))];
                const regMeta = r => REGS_META.find(rm=>rm.name===r||rm.name.startsWith(r)||r.toLowerCase().includes(rm.id));
                const REG_TYPE_COLOR = {Privacy:T.violet,Healthcare:T.rose,Financial:T.amber,Security:T.blue};
                return (
                  <Card2>
                    <div style={{padding:"14px 16px"}}>
                      <SH title="Governance"/>
                      <div style={{marginBottom:12}}>
                        <div style={{fontSize:10,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.07em",marginBottom:8}}>Governing Policies</div>
                        {govPols.map(p=>{
                          const lcc = LC_COLOR[p.lifecycle]||T.textMuted;
                          return (
                            <div key={p.id}
                              onClick={()=>navFn("policymanager",{policyId:p.id})}
                              onMouseEnter={e=>e.currentTarget.style.background=T.bgHover}
                              onMouseLeave={e=>e.currentTarget.style.background=T.bgElevated}
                              style={{display:"flex",alignItems:"center",gap:10,padding:"9px 12px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:8,marginBottom:6,cursor:"pointer",transition:"background .1s"}}>
                              <div style={{width:7,height:7,borderRadius:"50%",background:lcc,flexShrink:0}}/>
                              <div style={{flex:1,minWidth:0}}>
                                <div style={{fontSize:12,fontWeight:600,color:T.text,lineHeight:1.4}}>{p.name}</div>
                                <div style={{fontSize:10.5,color:T.textMuted,marginTop:1}}>{p.category} · {p.severity} severity</div>
                              </div>
                              <span style={{fontSize:10,fontWeight:700,padding:"2px 7px",borderRadius:99,background:`${lcc}15`,color:lcc,border:`1px solid ${lcc}25`,flexShrink:0,whiteSpace:"nowrap"}}>{p.lifecycle}</span>
                              <svg width="12" height="12" viewBox="0 0 12 12" fill="none" style={{flexShrink:0,color:T.textMuted}}><path d="M2.5 6h7M6.5 3l3 3-3 3" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" strokeLinejoin="round"/></svg>
                            </div>
                          );
                        })}
                      </div>
                      {govRegs.length>0&&(
                        <div>
                          <div style={{fontSize:10,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.07em",marginBottom:8}}>Applicable Regulations</div>
                          <div style={{display:"flex",flexWrap:"wrap",gap:6}}>
                            {govRegs.map(r=>{
                              const rm = regMeta(r);
                              const rc = rm ? REG_TYPE_COLOR[rm.type]||T.accent : T.accent;
                              return (
                                <span key={r} style={{display:"inline-flex",alignItems:"center",gap:5,fontSize:11.5,padding:"4px 10px",borderRadius:6,background:`${rc}12`,color:rc,border:`1px solid ${rc}25`,fontWeight:600}}>
                                  <svg width="10" height="10" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.4"><path d="M8 1L2 4v4c0 3.5 2.7 5.5 6 6.5C11.3 13.5 14 11.5 14 8V4L8 1z"/></svg>
                                  {r}{rm&&<span style={{fontSize:9.5,color:`${rc}99`,fontWeight:400,marginLeft:1}}>· {rm.jurisdiction}</span>}
                                </span>
                              );
                            })}
                          </div>
                        </div>
                      )}
                    </div>
                  </Card2>
                );
              })()}

              {/* Notes */}
              <Card2>
                <div style={{padding:"14px 16px"}}>
                  <SH title="Notes" action={
                    editNotes
                      ? <div style={{display:"flex",gap:6}}>
                          <Btn small ghost onClick={()=>{setEditNotes(false);onToast("Notes saved","success");}}>Save</Btn>
                          <Btn small ghost onClick={()=>setEditNotes(false)}>Cancel</Btn>
                        </div>
                      : <Btn small ghost icon={Ic.edit(11)} onClick={()=>setEditNotes(true)}>Edit</Btn>
                  }/>
                  {editNotes
                    ? <textarea value={notesVal} onChange={e=>setNotesVal(e.target.value)} rows={5}
                        style={{width:"100%",padding:"9px 12px",background:T.bgElevated,border:`1.5px solid ${T.accent}`,borderRadius:8,color:T.text,fontSize:13,outline:"none",resize:"vertical",lineHeight:1.75,fontFamily:"'Geist Mono',monospace",boxSizing:"border-box"}}/>
                    : <div style={{fontSize:13,color:T.textSub,lineHeight:1.9,whiteSpace:"pre-wrap"}}>{notesVal}</div>
                  }
                </div>
              </Card2>

            </div>
          )}

          {tab==="assets"&&(
            <div style={{display:"flex",flexDirection:"column",gap:12}}>
              <div style={{position:"relative",maxWidth:400}}>
                <svg width="13" height="13" viewBox="0 0 14 14" fill="none" style={{position:"absolute",left:9,top:"50%",transform:"translateY(-50%)",color:T.textMuted,pointerEvents:"none"}}><circle cx="6" cy="6" r="4.5" stroke="currentColor" strokeWidth="1.3"/><path d="M10 10l2.5 2.5" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round"/></svg>
                <input value={contSearch} onChange={e=>setContSearch(e.target.value)} placeholder={`Search ${children.length} assets…`}
                  style={{width:"100%",padding:"7px 10px 7px 28px",background:T.bgElevated,border:`1.5px solid ${contSearch?T.accent:T.border}`,borderRadius:8,color:T.text,fontSize:12.5,outline:"none",boxSizing:"border-box",transition:"border-color .15s"}}
                  onFocus={e=>e.target.style.borderColor=T.accent} onBlur={e=>e.target.style.borderColor=contSearch?T.accent:T.border}/>
                {contSearch&&<button onClick={()=>setContSearch("")} style={{position:"absolute",right:8,top:"50%",transform:"translateY(-50%)",background:"none",border:"none",cursor:"pointer",color:T.textMuted,fontSize:16,lineHeight:1}}>×</button>}
              </div>
              {filteredChildren.length===0
                ? <div style={{textAlign:"center",padding:"40px 0",color:T.textMuted,fontSize:13}}>{contSearch?"No assets match your search":"No child assets found"}</div>
                : <Card2 style={{padding:0,overflow:"hidden"}}>
                    <DataTable cols={CHILD_COLS} rows={filteredChildren} onRowClick={r=>onAsset(r)}/>
                  </Card2>
              }
            </div>
          )}
        </div>

        {/* ── Right metadata sidebar — Overview tab only ── */}
        {tab==="overview"&&<div style={{width:260,flexShrink:0,borderLeft:`1px solid ${T.border}`,background:T.bgSurface,overflowY:"auto"}}>

          {/* DETAILS */}
          <div style={{padding:"16px",borderBottom:`1px solid ${T.border}`}}>
            <MetaLabel>Details</MetaLabel>
            {[
              {l:"Connection", v:<div style={{display:"flex",alignItems:"center",gap:6}}><ServiceIcon service={asset.service} size={14}/><span style={{fontSize:12,color:T.textSub}}>{asset.connectionLabel}</span></div>},
              {l:"Size",       v:<span style={{fontSize:12,fontFamily:"'Geist Mono',monospace",color:T.text}}>{data.size||"—"}</span>},
              {l:"Children",   v:<span style={{fontSize:12,fontFamily:"'Geist Mono',monospace",color:T.text}}>{children.length}</span>},
              {l:"Freshness",  v:<span style={{fontSize:12,color:T.textSub}}>{data.slaFreshness||"—"}</span>},
              {l:"Updated",    v:<span style={{fontSize:12,color:T.textMuted}}>{data.updated||"—"}</span>},
            ].map(m=>(
              <div key={m.l} style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:8,fontSize:12}}>
                <span style={{color:T.textMuted}}>{m.l}</span>{m.v}
              </div>
            ))}
          </div>

          {/* CERTIFICATE */}
          <div style={{padding:"16px",borderBottom:`1px solid ${T.border}`}}>
            <MetaLabel onEdit={()=>setEditModal("cert")}>Status</MetaLabel>
            <div style={{display:"inline-flex",alignItems:"center",gap:6,padding:"4px 12px 4px 9px",borderRadius:5,background:cm.bg,borderTop:`1px solid ${cm.border}`,borderRight:`1px solid ${cm.border}`,borderBottom:`1px solid ${cm.border}`,borderLeft:`3px solid ${cm.color}`}}>
              <span style={{fontSize:13}}>{cm.icon}</span>
              <span style={{fontSize:12,color:cm.color,fontWeight:600}}>{data.cert||"Draft"}</span>
            </div>
          </div>

          {/* DOMAIN */}
          <div style={{padding:"16px",borderBottom:`1px solid ${T.border}`}}>
            <MetaLabel onEdit={()=>{setDomainOpen(p=>!p);setDomainSearch("");}}>Domain</MetaLabel>
            {data.domain?(
              <div style={{display:"inline-flex",alignItems:"center",padding:"4px 12px 4px 9px",borderRadius:5,background:`${T.accent}0f`,borderTop:`1px solid ${T.accent}20`,borderRight:`1px solid ${T.accent}20`,borderBottom:`1px solid ${T.accent}20`,borderLeft:`3px solid ${T.accent}`}}>
                <span style={{fontSize:12,color:T.accent,fontWeight:600}}>{data.domain}</span>
              </div>
            ):(
              <span style={{fontSize:12,color:T.textMuted,fontStyle:"italic"}}>No domain set</span>
            )}
            {domainOpen&&(
              <div style={{marginTop:8,background:T.bgSurface,border:`1px solid ${T.accent}40`,borderRadius:8,overflow:"hidden",boxShadow:"0 4px 12px rgba(0,0,0,.12)"}}>
                <div style={{padding:"6px 8px",borderBottom:`1px solid ${T.border}`}}>
                  <input autoFocus placeholder="Search domains…" value={domainSearch} onChange={e=>setDomainSearch(e.target.value)}
                    style={{width:"100%",padding:"5px 8px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:6,color:T.text,fontSize:12,outline:"none",boxSizing:"border-box"}}
                    onFocus={e=>e.target.style.borderColor=T.accent} onBlur={e=>e.target.style.borderColor=T.border}/>
                </div>
                <div style={{maxHeight:180,overflowY:"auto"}}>
                  {DOMAINS_LIST.filter(d=>!domainSearch||d.toLowerCase().includes(domainSearch.toLowerCase())).map(d=>(
                    <button key={d} onClick={()=>{setData(dd=>({...dd,domain:d}));setDomainOpen(false);onToast(`Domain set to ${d}`,"success");}}
                      style={{width:"100%",display:"flex",alignItems:"center",justifyContent:"space-between",padding:"8px 12px",background:data.domain===d?T.accentDim:"transparent",border:"none",cursor:"pointer",fontSize:12.5,color:data.domain===d?T.accent:T.textSub,fontWeight:data.domain===d?600:400,transition:"background .1s"}}
                      onMouseEnter={e=>{if(data.domain!==d)e.currentTarget.style.background=T.bgHover;}} onMouseLeave={e=>{if(data.domain!==d)e.currentTarget.style.background="transparent";}}>
                      {d}
                      {data.domain===d&&<svg width="12" height="12" viewBox="0 0 14 14" fill="none"><path d="M2.5 7.5l3 3 6-6" stroke={T.accent} strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"/></svg>}
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* OWNERS */}
          <div style={{padding:"16px",borderBottom:`1px solid ${T.border}`}}>
            <MetaLabel onEdit={()=>{ if(canAssign){setOwnersOpen(p=>!p);setOwnersSearch("");} else if(!myPending("owner")) requestRole("owner"); }} cta={canAssign?null:(myPending("owner")?"Pending":"Request")}>Owners</MetaLabel>
            <div style={{display:"flex",flexWrap:"wrap",gap:5}}>
              {owners.length===0&&<span style={{fontSize:12,color:T.textMuted,fontStyle:"italic"}}>No owners assigned</span>}
              {(showAllOwners?owners:owners.slice(0,3)).map((o,i)=>(
                <div key={i} style={{display:"inline-flex",alignItems:"center",gap:5,padding:"3px 10px 3px 6px",borderRadius:5,background:`${T.accent}0f`,borderTop:`1px solid ${T.accent}20`,borderRight:`1px solid ${T.accent}20`,borderBottom:`1px solid ${T.accent}20`,borderLeft:`3px solid ${T.accent}`}}>
                  <div style={{width:18,height:18,borderRadius:3,background:T.accentDim,display:"flex",alignItems:"center",justifyContent:"center",fontSize:7,fontWeight:700,color:T.accent,flexShrink:0}}>{ava(o)}</div>
                  <span style={{fontSize:12,color:T.accent,fontWeight:500}}>{o}</span>
                </div>
              ))}
              {owners.length>3&&!showAllOwners&&<span onClick={()=>setShowAllOwners(true)} style={{display:"inline-flex",alignItems:"center",fontSize:11.5,padding:"3px 10px",borderRadius:5,background:T.bgElevated,border:`1px solid ${T.border}`,color:T.textMuted,cursor:"pointer",fontWeight:600}}>+{owners.length-3} more</span>}
              {owners.length>3&&showAllOwners&&<span onClick={()=>setShowAllOwners(false)} style={{display:"inline-flex",alignItems:"center",fontSize:11.5,padding:"3px 10px",borderRadius:5,background:T.bgElevated,border:`1px solid ${T.border}`,color:T.textMuted,cursor:"pointer",fontWeight:600}}>− less</span>}
            </div>
            {ownersOpen&&(
              <div style={{marginTop:8,background:T.bgSurface,border:`1px solid ${T.accent}40`,borderRadius:8,overflow:"hidden",boxShadow:"0 4px 12px rgba(0,0,0,.12)"}}>
                <div style={{padding:"6px 8px",borderBottom:`1px solid ${T.border}`}}>
                  <input autoFocus placeholder="Search users…" value={ownersSearch} onChange={e=>setOwnersSearch(e.target.value)}
                    style={{width:"100%",padding:"5px 8px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:6,color:T.text,fontSize:12,outline:"none",boxSizing:"border-box"}}
                    onFocus={e=>e.target.style.borderColor=T.accent} onBlur={e=>e.target.style.borderColor=T.border}/>
                </div>
                <div style={{maxHeight:180,overflowY:"auto"}}>
                  {USERS_LIST.filter(u=>!ownersSearch||u.toLowerCase().includes(ownersSearch.toLowerCase())).map(u=>{
                    const sel=owners.includes(u);
                    return <button key={u} onClick={()=>{if(sel){const no=owners.filter(x=>x!==u);setData(d=>({...d,owners:no,owner:no[0]||""}));}else setData(d=>({...d,owners:[...owners,u],owner:owners[0]||u}));}}
                      style={{width:"100%",display:"flex",alignItems:"center",gap:8,padding:"7px 12px",background:sel?T.accentDim:"transparent",border:"none",cursor:"pointer",textAlign:"left",transition:"background .1s"}}
                      onMouseEnter={e=>{if(!sel)e.currentTarget.style.background=T.bgHover;}} onMouseLeave={e=>{if(!sel)e.currentTarget.style.background="transparent";}}>
                      <div style={{width:22,height:22,borderRadius:5,background:T.accentDim,border:`1px solid ${T.accent}33`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:8,fontWeight:700,color:T.accent,flexShrink:0}}>{ava(u)}</div>
                      <span style={{flex:1,fontSize:12,color:sel?T.accent:T.text,fontWeight:sel?600:400}}>{u}</span>
                      {sel&&<svg width="12" height="12" viewBox="0 0 14 14" fill="none"><path d="M2.5 7.5l3 3 6-6" stroke={T.accent} strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"/></svg>}
                    </button>;
                  })}
                </div>
                <div style={{padding:"6px 8px",borderTop:`1px solid ${T.border}`,display:"flex",justifyContent:"flex-end"}}>
                  <button onClick={()=>setOwnersOpen(false)} style={{padding:"4px 12px",borderRadius:5,background:T.accent,border:"none",color:"#fff",fontSize:11.5,fontWeight:600,cursor:"pointer"}}>Done</button>
                </div>
              </div>
            )}
          </div>

          {/* STEWARDS */}
          <div style={{padding:"16px",borderBottom:`1px solid ${T.border}`}}>
            <MetaLabel onEdit={()=>{ if(canAssign){setStewardsOpen(p=>!p);setStewardsSearch("");} else if(!myPending("steward")) requestRole("steward"); }} cta={canAssign?null:(myPending("steward")?"Pending":"Request")}>Stewards</MetaLabel>
            <div style={{display:"flex",flexWrap:"wrap",gap:5}}>
              {stewards.length===0&&<span style={{fontSize:12,color:T.textMuted,fontStyle:"italic"}}>No stewards assigned</span>}
              {(showAllStewards?stewards:stewards.slice(0,3)).map((s,i)=>(
                <div key={i} style={{display:"inline-flex",alignItems:"center",gap:5,padding:"3px 10px 3px 6px",borderRadius:5,background:"rgba(217,119,6,.08)",borderTop:"1px solid rgba(217,119,6,.2)",borderRight:"1px solid rgba(217,119,6,.2)",borderBottom:"1px solid rgba(217,119,6,.2)",borderLeft:"3px solid #d97706"}}>
                  <div style={{width:18,height:18,borderRadius:"50%",background:"rgba(217,119,6,.15)",display:"flex",alignItems:"center",justifyContent:"center",fontSize:7,fontWeight:700,color:"#d97706",flexShrink:0}}>{ava(s)}</div>
                  <span style={{fontSize:12,color:"#d97706",fontWeight:500}}>{s}</span>
                </div>
              ))}
              {stewards.length>3&&!showAllStewards&&<span onClick={()=>setShowAllStewards(true)} style={{display:"inline-flex",alignItems:"center",fontSize:11.5,padding:"3px 10px",borderRadius:5,background:T.bgElevated,border:`1px solid ${T.border}`,color:T.textMuted,cursor:"pointer",fontWeight:600}}>+{stewards.length-3} more</span>}
              {stewards.length>3&&showAllStewards&&<span onClick={()=>setShowAllStewards(false)} style={{display:"inline-flex",alignItems:"center",fontSize:11.5,padding:"3px 10px",borderRadius:5,background:T.bgElevated,border:`1px solid ${T.border}`,color:T.textMuted,cursor:"pointer",fontWeight:600}}>− less</span>}
            </div>
            {stewardsOpen&&(
              <div style={{marginTop:8,background:T.bgSurface,border:"1px solid rgba(217,119,6,.3)",borderRadius:8,overflow:"hidden",boxShadow:"0 4px 12px rgba(0,0,0,.12)"}}>
                <div style={{padding:"6px 8px",borderBottom:`1px solid ${T.border}`}}>
                  <input autoFocus placeholder="Search users…" value={stewardsSearch} onChange={e=>setStewardsSearch(e.target.value)}
                    style={{width:"100%",padding:"5px 8px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:6,color:T.text,fontSize:12,outline:"none",boxSizing:"border-box"}}
                    onFocus={e=>e.target.style.borderColor="#d97706"} onBlur={e=>e.target.style.borderColor=T.border}/>
                </div>
                <div style={{maxHeight:180,overflowY:"auto"}}>
                  {USERS_LIST.filter(u=>!stewardsSearch||u.toLowerCase().includes(stewardsSearch.toLowerCase())).map(u=>{
                    const sel=stewards.includes(u);
                    return <button key={u} onClick={()=>{if(sel){const ns=stewards.filter(x=>x!==u);setData(d=>({...d,stewards:ns,steward:ns[0]||""}));}else setData(d=>({...d,stewards:[...stewards,u],steward:stewards[0]||u}));}}
                      style={{width:"100%",display:"flex",alignItems:"center",gap:8,padding:"7px 12px",background:sel?"rgba(217,119,6,.08)":"transparent",border:"none",cursor:"pointer",textAlign:"left",transition:"background .1s"}}
                      onMouseEnter={e=>{if(!sel)e.currentTarget.style.background=T.bgHover;}} onMouseLeave={e=>{if(!sel)e.currentTarget.style.background="transparent";}}>
                      <div style={{width:22,height:22,borderRadius:"50%",background:"rgba(217,119,6,.15)",display:"flex",alignItems:"center",justifyContent:"center",fontSize:8,fontWeight:700,color:"#d97706",flexShrink:0}}>{ava(u)}</div>
                      <span style={{flex:1,fontSize:12,color:sel?"#d97706":T.text,fontWeight:sel?600:400}}>{u}</span>
                      {sel&&<svg width="12" height="12" viewBox="0 0 14 14" fill="none"><path d="M2.5 7.5l3 3 6-6" stroke="#d97706" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"/></svg>}
                    </button>;
                  })}
                </div>
                <div style={{padding:"6px 8px",borderTop:`1px solid ${T.border}`,display:"flex",justifyContent:"flex-end"}}>
                  <button onClick={()=>setStewardsOpen(false)} style={{padding:"4px 12px",borderRadius:5,background:"#d97706",border:"none",color:"#fff",fontSize:11.5,fontWeight:600,cursor:"pointer"}}>Done</button>
                </div>
              </div>
            )}
          </div>

          {/* TAGS */}
          <div style={{padding:"16px",borderBottom:`1px solid ${T.border}`}}>
            <MetaLabel onEdit={()=>{setTagsOpen(p=>!p);setTagsSearch("");}}>Tags</MetaLabel>
            <div style={{display:"flex",flexWrap:"wrap",gap:5}}>
              {(data.tags||[]).length===0&&<span style={{fontSize:12,color:T.textMuted,fontStyle:"italic"}}>No tags added</span>}
              {(showAllTags?data.tags||[]:(data.tags||[]).slice(0,3)).map(t=>{const c=tc(t);return(
                <span key={t} style={{display:"inline-flex",alignItems:"center",fontSize:11.5,padding:"4px 10px 4px 9px",borderRadius:5,background:c.bg,borderTop:`1px solid ${c.border}`,borderRight:`1px solid ${c.border}`,borderBottom:`1px solid ${c.border}`,borderLeft:`3px solid ${c.color}`,color:c.color,fontWeight:600}}>{t}</span>
              );})}
              {(data.tags||[]).length>3&&!showAllTags&&<span onClick={()=>setShowAllTags(true)} style={{display:"inline-flex",alignItems:"center",fontSize:11.5,padding:"3px 10px",borderRadius:5,background:T.bgElevated,border:`1px solid ${T.border}`,color:T.textMuted,cursor:"pointer",fontWeight:600}}>+{(data.tags||[]).length-3} more</span>}
              {(data.tags||[]).length>3&&showAllTags&&<span onClick={()=>setShowAllTags(false)} style={{display:"inline-flex",alignItems:"center",fontSize:11.5,padding:"3px 10px",borderRadius:5,background:T.bgElevated,border:`1px solid ${T.border}`,color:T.textMuted,cursor:"pointer",fontWeight:600}}>− less</span>}
            </div>
            {tagsOpen&&(
              <div style={{marginTop:8,background:T.bgSurface,border:`1px solid ${T.border}`,borderRadius:8,overflow:"hidden",boxShadow:"0 4px 12px rgba(0,0,0,.12)"}}>
                <div style={{padding:"6px 8px",borderBottom:`1px solid ${T.border}`}}>
                  <input autoFocus placeholder="Search tags…" value={tagsSearch} onChange={e=>setTagsSearch(e.target.value)}
                    style={{width:"100%",padding:"5px 8px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:6,color:T.text,fontSize:12,outline:"none",boxSizing:"border-box"}}
                    onFocus={e=>e.target.style.borderColor=T.accent} onBlur={e=>e.target.style.borderColor=T.border}/>
                </div>
                <div style={{padding:"8px",display:"flex",flexWrap:"wrap",gap:5,maxHeight:160,overflowY:"auto"}}>
                  {["PII","revenue","finance","KPI","events","sensitive","dimension","model","etl","marketing"]
                    .filter(s=>!tagsSearch||s.toLowerCase().includes(tagsSearch.toLowerCase()))
                    .map(s=>{
                      const sel=(data.tags||[]).includes(s); const c=tc(s);
                      return <button key={s} onClick={()=>setData(d=>({...d,tags:sel?d.tags.filter(x=>x!==s):[...(d.tags||[]),s]}))}
                        style={{display:"inline-flex",alignItems:"center",gap:4,padding:"4px 10px",borderRadius:5,fontSize:11.5,cursor:"pointer",transition:"all .1s",background:sel?c.bg:T.bgElevated,borderTop:`1px solid ${sel?c.border:T.border}`,borderRight:`1px solid ${sel?c.border:T.border}`,borderBottom:`1px solid ${sel?c.border:T.border}`,borderLeft:`3px solid ${sel?c.color:T.border}`,color:sel?c.color:T.textSub,fontWeight:sel?600:400}}>
                        {sel&&<svg width="10" height="10" viewBox="0 0 14 14" fill="none"><path d="M2.5 7.5l3 3 6-6" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"/></svg>}
                        {s}
                      </button>;
                    })}
                </div>
                <div style={{padding:"6px 8px",borderTop:`1px solid ${T.border}`,display:"flex",justifyContent:"flex-end"}}>
                  <button onClick={()=>setTagsOpen(false)} style={{padding:"4px 12px",borderRadius:5,background:T.accent,border:"none",color:"#fff",fontSize:11.5,fontWeight:600,cursor:"pointer"}}>Done</button>
                </div>
              </div>
            )}
          </div>

          {/* BUSINESS GLOSSARY */}
          <div style={{padding:"16px",borderBottom:`1px solid ${T.border}`}}>
            <MetaLabel onEdit={()=>{setAssetGlOpen(p=>!p);setAssetGlSearch("");}}>Business Glossary</MetaLabel>
            <div style={{display:"flex",flexWrap:"wrap",gap:5}}>
              {assetGlTerms.length===0&&<span style={{fontSize:12,color:T.textMuted,fontStyle:"italic"}}>No terms linked</span>}
              {assetGlTerms.slice(0,3).map((t,i)=><span key={i} title={t} style={{display:"inline-flex",alignItems:"center",gap:4,fontSize:11.5,padding:"4px 10px 4px 9px",borderRadius:5,background:"rgba(139,92,246,.08)",borderTop:"1px solid rgba(139,92,246,.2)",borderRight:"1px solid rgba(139,92,246,.2)",borderBottom:"1px solid rgba(139,92,246,.2)",borderLeft:"3px solid #8b5cf6",color:"#8b5cf6",fontWeight:600}}>{t.length>10?t.slice(0,10)+"…":t}<button onClick={()=>setAssetGlTerms(prev=>prev.filter((_,j)=>j!==i))} style={{background:"none",border:"none",cursor:"pointer",color:"inherit",padding:0,lineHeight:1,display:"flex",opacity:.6}} onMouseEnter={e=>e.currentTarget.style.opacity="1"} onMouseLeave={e=>e.currentTarget.style.opacity=".6"}>{Ic.x(7)}</button></span>)}
              {assetGlTerms.length>3&&<span title={assetGlTerms.slice(3).join(", ")} style={{display:"inline-flex",alignItems:"center",fontSize:11.5,padding:"3px 10px",borderRadius:5,background:T.bgElevated,border:`1px solid ${T.border}`,color:T.textMuted,cursor:"default",fontWeight:600}}>+{assetGlTerms.length-3}</span>}
            </div>
            {assetGlOpen&&(
              <div style={{marginTop:8,background:T.bgSurface,border:"1px solid rgba(139,92,246,.3)",borderRadius:8,overflow:"hidden",boxShadow:"0 4px 12px rgba(0,0,0,.12)"}}>
                <div style={{padding:"6px 8px",borderBottom:`1px solid ${T.border}`}}>
                  <input autoFocus placeholder="Search glossary terms…" value={assetGlSearch} onChange={e=>setAssetGlSearch(e.target.value)}
                    style={{width:"100%",padding:"5px 8px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:6,color:T.text,fontSize:12,outline:"none",boxSizing:"border-box"}}
                    onFocus={e=>e.target.style.borderColor="#8b5cf6"} onBlur={e=>e.target.style.borderColor=T.border}/>
                </div>
                <div style={{maxHeight:200,overflowY:"auto"}}>
                  {GLOSSARY_TERMS.filter(t=>!assetGlSearch||t.term.toLowerCase().includes(assetGlSearch.toLowerCase())||t.abbr?.toLowerCase().includes(assetGlSearch.toLowerCase())).map(t=>{
                    const sel=assetGlTerms.includes(t.term);
                    return(<button key={t.id} onClick={()=>setAssetGlTerms(prev=>sel?prev.filter(x=>x!==t.term):[...prev,t.term])}
                      style={{width:"100%",display:"flex",alignItems:"center",gap:8,padding:"8px 12px",background:sel?"rgba(139,92,246,.06)":"transparent",border:"none",cursor:"pointer",textAlign:"left",transition:"background .1s"}}
                      onMouseEnter={e=>{if(!sel)e.currentTarget.style.background=T.bgHover;}} onMouseLeave={e=>{if(!sel)e.currentTarget.style.background="transparent";}}>
                      <div style={{flex:1,minWidth:0}}>
                        <div style={{fontSize:12,fontWeight:600,color:sel?"#8b5cf6":T.text}}>{t.term}</div>
                        <div style={{fontSize:10.5,color:T.textMuted,display:"flex",gap:5,marginTop:1}}>
                          {t.abbr&&t.abbr!=="—"&&<span style={{fontFamily:"'Geist Mono',monospace"}}>{t.abbr}</span>}
                          <span>{t.domain}</span>
                        </div>
                      </div>
                      {sel&&<svg width="12" height="12" viewBox="0 0 14 14" fill="none"><path d="M2.5 7.5l3 3 6-6" stroke="#8b5cf6" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"/></svg>}
                    </button>);
                  })}
                  {GLOSSARY_TERMS.filter(t=>!assetGlSearch||t.term.toLowerCase().includes(assetGlSearch.toLowerCase())).length===0&&<div style={{padding:"12px",fontSize:12,color:T.textMuted,textAlign:"center"}}>No terms match</div>}
                </div>
                <div style={{padding:"6px 8px",borderTop:`1px solid ${T.border}`,display:"flex",justifyContent:"flex-end"}}>
                  <button onClick={()=>setAssetGlOpen(false)} style={{padding:"4px 12px",borderRadius:5,background:"#8b5cf6",border:"none",color:"#fff",fontSize:11.5,fontWeight:600,cursor:"pointer"}}>Done</button>
                </div>
              </div>
            )}
          </div>

          {/* ACTIONS */}
          <div style={{padding:"16px"}}>
            <MetaLabel>Actions</MetaLabel>
            {[
              {l:"Request Access", fn:()=>onToast("Access request sent","success")},
              {l:"Copy Link",      fn:()=>onToast("Link copied","success")},
              {l:"Browse Assets",fn:()=>setTab("assets")},
            ].map((a,i,arr)=>(
              <button key={i} onClick={a.fn}
                style={{width:"100%",display:"flex",alignItems:"center",justifyContent:"space-between",padding:"8px 0",background:"none",border:"none",borderBottom:i<arr.length-1?`1px solid ${T.border}`:"none",color:T.textSub,fontSize:12.5,cursor:"pointer",transition:"color .1s"}}
                onMouseEnter={e=>e.currentTarget.style.color=T.accent} onMouseLeave={e=>e.currentTarget.style.color=T.textSub}>
                {a.l}
                <svg width="9" height="9" viewBox="0 0 10 10" fill="none"><path d="M3 2l4 3-4 3" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round"/></svg>
              </button>
            ))}
          </div>

        </div>}
      </div>

      {/* Status edit modal (centered — cert is a single-step action) */}
      {editModal==="cert"&&(
        <>
          <div onClick={()=>setEditModal(null)} style={{position:"fixed",inset:0,zIndex:500,background:"rgba(0,0,0,.4)"}}/>
          <div style={{position:"fixed",top:"50%",left:"50%",transform:"translate(-50%,-50%)",zIndex:501,background:T.bgSurface,border:`1px solid ${T.border}`,borderRadius:14,boxShadow:"0 24px 64px rgba(0,0,0,.4)",width:280,display:"flex",flexDirection:"column",overflow:"hidden"}}>
            <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",padding:"14px 16px",borderBottom:`1px solid ${T.border}`}}>
              <span style={{fontSize:13.5,fontWeight:700,color:T.text}}>Edit Status</span>
              <button onClick={()=>setEditModal(null)} style={{background:"none",border:"none",cursor:"pointer",color:T.textMuted,padding:3,display:"flex",borderRadius:5}} onMouseEnter={e=>e.currentTarget.style.color=T.text} onMouseLeave={e=>e.currentTarget.style.color=T.textMuted}>
                <svg width="12" height="12" viewBox="0 0 10 10" fill="none"><path d="M1.5 1.5l7 7M8.5 1.5l-7 7" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round"/></svg>
              </button>
            </div>
            <div style={{overflowY:"auto"}}>
              {Object.entries(CMETA).map(([c,m])=>(
                <button key={c} onClick={()=>{setData(d=>({...d,cert:c}));setEditModal(null);onToast(`Status set to ${c}`,"success");}}
                  style={{width:"100%",display:"flex",alignItems:"center",gap:12,padding:"11px 16px",background:data.cert===c?m.bg:"transparent",border:"none",cursor:"pointer",transition:"background .1s"}}
                  onMouseEnter={e=>{if(data.cert!==c)e.currentTarget.style.background=T.bgHover;}}
                  onMouseLeave={e=>{if(data.cert!==c)e.currentTarget.style.background="transparent";}}>
                  <span style={{fontSize:16}}>{m.icon}</span>
                  <span style={{flex:1,fontSize:13,fontWeight:600,color:m.color}}>{c}</span>
                  {data.cert===c&&<svg width="13" height="13" viewBox="0 0 14 14" fill="none"><path d="M2.5 7.5l3 3 6-6" stroke={m.color} strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"/></svg>}
                </button>
              ))}
            </div>
          </div>
        </>
      )}

      {/* Certification Modal */}
      <Modal open={certModal} onClose={()=>setCertModal(false)} title={`Set status — ${asset.name}`}>
        <p style={{fontSize:13,color:T.textSub,marginBottom:16}}>Setting the status to Approved marks this asset as trusted and production-ready. This action is logged and visible to all users.</p>
        <div style={{display:"flex",flexDirection:"column",gap:12}}>
          {[
            {label:"Description documented", done:!!(descVal)},
            {label:"Owner assigned",          done:owners.length>0},
            {label:"Steward assigned",        done:stewards.length>0},
            {label:"Domain set",              done:!!(data.domain)},
          ].map((c,i)=>(
            <div key={i} style={{display:"flex",alignItems:"center",gap:10,padding:"8px 12px",background:c.done?T.accentDim:T.bgElevated,border:`1px solid ${c.done?"rgba(238,36,36,0.2)":T.border}`,borderRadius:8}}>
              <span style={{color:c.done?T.accent:T.textMuted}}>{c.done?Ic.check(14):Ic.x(14)}</span>
              <span style={{fontSize:13,color:c.done?T.text:T.textSub}}>{c.label}</span>
              {!c.done&&<span style={{fontSize:11,color:T.amber,marginLeft:"auto"}}>Required</span>}
            </div>
          ))}
        </div>
        <div style={{marginTop:16}}>
          <div style={{fontSize:12,color:T.textSub,marginBottom:6}}>Status notes</div>
          <Input2 multiline rows={3} placeholder="Add notes for the certification record…" value={certNote} onChange={e=>setCertNote(e.target.value)}/>
        </div>
        <div style={{display:"flex",gap:8,marginTop:20,justifyContent:"flex-end"}}>
          <Btn onClick={()=>setCertModal(false)}>Cancel</Btn>
          <Btn variant="primary" icon={Ic.cert(13)} onClick={handleCertify}>Set status to Approved</Btn>
        </div>
      </Modal>
    </div>
  );
};

// ── Detail page for file assets (Object / Blob) ──
const FileAssetDetail = ({asset, onBack, onToast}) => {
  const [desc,      setDesc]      = useState(asset.description||"");
  const [editing,   setEditing]   = useState(false);
  const [tab,       setTab]       = useState("overview");
  const FILE_FORMAT_COLORS = {CSV:"#16a34a",Parquet:"#0891b2",JSON:"#d97706",JSON_LINES:"#d97706",ORC:"#7c3aed",Avro:"#0891b2",Delta:"#ff3621"};
  const fc = FILE_FORMAT_COLORS[asset.fileFormat]||"#6b7280";
  // tag-color helper (this component previously referenced `tc` without defining it → crash on tagged files)
  const TAG_C = {PII:{bg:"rgba(225,29,72,.1)",color:"#e11d48",border:"rgba(225,29,72,.25)"},revenue:{bg:"rgba(37,99,235,.08)",color:"#2563eb",border:"rgba(37,99,235,.2)"},finance:{bg:"rgba(37,99,235,.08)",color:"#2563eb",border:"rgba(37,99,235,.2)"},KPI:{bg:"rgba(22,163,74,.08)",color:"#16a34a",border:"rgba(22,163,74,.2)"},sensitive:{bg:"rgba(124,58,237,.08)",color:"#7c3aed",border:"rgba(124,58,237,.2)"},events:{bg:"rgba(6,182,212,.08)",color:"#0891b2",border:"rgba(6,182,212,.2)"}};
  const tc = tag => TAG_C[tag]||{bg:T.bgElevated,color:T.textSub,border:T.border};

  const SLabel = ({children})=>(
    <div style={{fontSize:10,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.07em",marginBottom:7}}>{children}</div>
  );
  const MetaRow = ({label,value,mono})=>(
    <div style={{display:"flex",alignItems:"flex-start",justifyContent:"space-between",padding:"8px 0",borderBottom:`1px solid ${T.border}`,fontSize:12,gap:16}}>
      <span style={{color:T.textMuted,flexShrink:0}}>{label}</span>
      <span style={{color:T.text,textAlign:"right",fontFamily:mono?"'Geist Mono',monospace":"inherit",fontSize:mono?11.5:12}}>{value||"—"}</span>
    </div>
  );
  const Avatar = ({name,size=22})=>{
    const initials = (name||"").split(".").map(s=>s[0]?.toUpperCase()||"").join("").slice(0,2);
    return <div style={{width:size,height:size,borderRadius:Math.floor(size/3),background:T.accentDim,border:`1px solid ${T.accent}33`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:size*0.32,fontWeight:700,color:T.accent,flexShrink:0}}>{initials}</div>;
  };

  // The last tab shows where the object physically sits, not what produced it - calling
  // a storage path "Lineage" promised data lineage this connector does not report.
  const TABS = [{id:"overview",label:"Overview"},{id:"properties",label:"Properties"},{id:"customprops",label:"Custom Properties"},{id:"lineage",label:"Storage Path"}];

  const formatDate = (iso) => {
    if(!iso) return "—";
    try { return new Date(iso).toLocaleDateString("en-US",{month:"short",day:"numeric",year:"numeric",hour:"2-digit",minute:"2-digit"}); }
    catch{ return iso; }
  };

  const usageColor = {High:T.accent,Med:T.amber,Low:T.textMuted}[asset.usage]||T.textMuted;

  return (
    <div className="fadeUp" style={{height:"100%",display:"flex",flexDirection:"column"}}>
      <Topbar breadcrumb={[{label:"Catalog",onClick:onBack},{label:asset.name}]}/>

      {/* ── Hero header ── */}
      <div style={{background:T.bgSurface,borderBottom:`1px solid ${T.border}`,flexShrink:0,padding:"20px 28px 0"}}>
        <div style={{display:"flex",alignItems:"flex-start",gap:16,marginBottom:16}}>
          {/* Service icon */}
          <div style={{width:52,height:52,borderRadius:13,background:`${fc}12`,border:`1.5px solid ${fc}30`,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,marginTop:2}}>
            <ServiceIcon service={asset.service} size={30}/>
          </div>
          <div style={{flex:1,minWidth:0}}>
            <div style={{display:"flex",alignItems:"center",gap:7,marginBottom:6,flexWrap:"wrap"}}>
              <TypeBadge type={asset.type}/>
              {asset.fileFormat&&<span style={{fontSize:10,fontWeight:700,padding:"2px 7px",borderRadius:4,background:`${fc}18`,color:fc,border:`1px solid ${fc}33`}}>{asset.fileFormat}</span>}
              <CertBadge cert={asset.cert}/>
              <TierBadge tier={asset.tier}/>
              {asset.usage&&<span style={{fontSize:10,fontWeight:600,padding:"2px 8px",borderRadius:4,background:T.bgElevated,color:usageColor,border:`1px solid ${T.border}`}}>Usage: {asset.usage}</span>}
              {asset.slaFreshness&&<span style={{fontSize:10,fontWeight:600,padding:"2px 8px",borderRadius:4,background:"rgba(99,102,241,.08)",color:T.accent,border:`1px solid ${T.accent}22`}}>SLA {asset.slaFreshness}</span>}
            </div>
            <h2 style={{fontSize:18,fontWeight:700,fontFamily:"'Geist Mono',monospace",color:T.text,letterSpacing:"-0.03em",margin:"0 0 6px",lineHeight:1.2}}>{asset.name}</h2>
            {/* Path breadcrumb */}
            <div style={{display:"flex",alignItems:"center",gap:4,flexWrap:"wrap"}}>
              <span style={{fontSize:11,color:T.textMuted}}>{asset.connectionLabel}</span>
              {(asset.path||[]).map((seg,i)=>(
                <React.Fragment key={i}>
                  <svg width="8" height="8" viewBox="0 0 10 10" fill="none" style={{color:T.textMuted,flexShrink:0,opacity:.5}}><path d="M3 2l4 3-4 3" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round"/></svg>
                  <span style={{fontSize:11,fontFamily:"'Geist Mono',monospace",color:T.textMuted}}>{seg}</span>
                </React.Fragment>
              ))}
              <svg width="8" height="8" viewBox="0 0 10 10" fill="none" style={{color:T.textMuted,flexShrink:0,opacity:.5}}><path d="M3 2l4 3-4 3" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round"/></svg>
              <span style={{fontSize:11,fontFamily:"'Geist Mono',monospace",color:T.text,fontWeight:600}}>{asset.name}</span>
            </div>
          </div>
          <div style={{display:"flex",gap:6,flexShrink:0,marginTop:4}}>
            <Btn ghost small onClick={()=>onToast("Copied link","success")}>Copy Link</Btn>
            <Btn variant="primary" small onClick={()=>onToast("Editing…","info")}>Edit</Btn>
          </div>
        </div>

        {/* Tab bar */}
        <div style={{display:"flex",gap:0,borderTop:`1px solid ${T.border}`,marginLeft:-28,marginRight:-28,paddingLeft:28}}>
          {TABS.map(t=>(
            <button key={t.id} onClick={()=>setTab(t.id)} style={{padding:"10px 16px",background:"transparent",border:"none",marginBottom:-1,borderBottom:`2px solid ${tab===t.id?T.accent:"transparent"}`,color:tab===t.id?T.text:T.textSub,fontSize:12.5,fontWeight:tab===t.id?600:400,cursor:"pointer",transition:"all .12s",whiteSpace:"nowrap"}}>
              {t.label}
            </button>
          ))}
        </div>
      </div>

      {/* ── Body ── */}
      <div style={{flex:1,overflow:"auto",padding:"24px 28px",display:"flex",gap:22,alignItems:"flex-start"}}>

        {/* ── CUSTOM PROPERTIES TAB ── */}
        {tab==="customprops"&&(
          <div style={{flex:1,minWidth:0}}>
            <CustomPropsPanel entity={asset.type} objectId={asset.name} objectName={asset.name} owners={asset.owners||(asset.owner?[asset.owner]:[])} stewards={asset.stewards||(asset.steward?[asset.steward]:[])} onToast={onToast}/>
          </div>
        )}

        {/* ── OVERVIEW TAB ── */}
        {tab==="overview"&&<>
          <div style={{flex:1,minWidth:0,display:"flex",flexDirection:"column",gap:14}}>

            {/* Description */}
            <Card2 style={{padding:"16px 18px"}}>
              <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:10}}>
                <span style={{fontSize:13,fontWeight:600,color:T.text}}>Description</span>
                <button onClick={()=>{ if(editing)onToast("Description saved","success"); setEditing(e=>!e); }}
                  style={{fontSize:11.5,color:editing?T.accent:T.textMuted,background:"none",border:`1px solid ${editing?T.accent:T.border}`,borderRadius:6,cursor:"pointer",padding:"3px 10px",transition:"all .15s"}}>
                  {editing?"Save":"Edit"}
                </button>
              </div>
              {editing
                ? <textarea value={desc} onChange={e=>setDesc(e.target.value)} rows={4}
                    style={{width:"100%",background:T.bgElevated,border:`1.5px solid ${T.accent}`,borderRadius:7,color:T.text,fontSize:13,padding:"9px 11px",resize:"vertical",outline:"none",boxSizing:"border-box",fontFamily:"inherit",lineHeight:1.6}}/>
                : <p style={{fontSize:13,color:desc?T.textSub:T.textMuted,lineHeight:1.7,margin:0,fontStyle:desc?"normal":"italic"}}>{desc||"No description yet — click Edit to add one."}</p>
              }
            </Card2>

            {/* Tags */}
            <Card2 style={{padding:"16px 18px"}}>
              <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:10}}>
                <span style={{fontSize:13,fontWeight:600,color:T.text}}>Tags</span>
                <button onClick={()=>onToast("Tag editor coming soon","info")} style={{fontSize:11,color:T.textMuted,background:"none",border:`1px solid ${T.border}`,borderRadius:6,cursor:"pointer",padding:"2px 8px",display:"flex",alignItems:"center",gap:4}}>
                  <svg width="9" height="9" viewBox="0 0 10 10" fill="none"><path d="M5 1v8M1 5h8" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round"/></svg> Add
                </button>
              </div>
              {(asset.tags||[]).length===0
                ? <span style={{fontSize:12,color:T.textMuted,fontStyle:"italic"}}>No tags applied</span>
                : <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
                    {asset.tags.map(t=>{const c=tc(t);return(
                      <span key={t} style={{display:"inline-flex",alignItems:"center",fontSize:11.5,padding:"4px 10px 4px 9px",borderRadius:5,background:c.bg,borderTop:`1px solid ${c.border}`,borderRight:`1px solid ${c.border}`,borderBottom:`1px solid ${c.border}`,borderLeft:`3px solid ${c.color}`,color:c.color,fontWeight:600}}>{t}</span>
                    );})}
                  </div>
              }
            </Card2>

            {/* Ownership */}
            <Card2 style={{padding:"16px 18px"}}>
              <span style={{fontSize:13,fontWeight:600,color:T.text,display:"block",marginBottom:12}}>Ownership</span>
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:16}}>
                <div>
                  <SLabel>Owners</SLabel>
                  <div style={{display:"flex",flexDirection:"column",gap:6}}>
                    {(asset.owners||[asset.owner]).map(o=>(
                      <div key={o} style={{display:"flex",alignItems:"center",gap:8}}>
                        <Avatar name={o}/>
                        <span style={{fontSize:12,color:T.textSub}}>{o}</span>
                      </div>
                    ))}
                  </div>
                </div>
                <div>
                  <SLabel>Stewards</SLabel>
                  <div style={{display:"flex",flexDirection:"column",gap:6}}>
                    {(asset.stewards||[asset.steward]).filter(Boolean).map(s=>(
                      <div key={s} style={{display:"flex",alignItems:"center",gap:8}}>
                        <Avatar name={s}/>
                        <span style={{fontSize:12,color:T.textSub}}>{s}</span>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </Card2>
          </div>

          {/* Sidebar */}
          <div style={{width:234,flexShrink:0,display:"flex",flexDirection:"column",gap:12}}>
            <Card2 style={{padding:"14px 16px"}}>
              <SLabel>Connection</SLabel>
              <div style={{display:"flex",alignItems:"center",gap:9}}>
                <ServiceIcon service={asset.service} size={22}/>
                <span style={{fontSize:12,color:T.textSub,lineHeight:1.3}}>{asset.connectionLabel}</span>
              </div>
            </Card2>
            <Card2 style={{padding:"14px 16px"}}>
              <SLabel>File Info</SLabel>
              {asset.fileFormat&&<div style={{display:"flex",justifyContent:"space-between",marginBottom:7}}>
                <span style={{fontSize:12,color:T.textMuted}}>Format</span>
                <span style={{fontSize:11.5,fontWeight:700,padding:"1px 7px",borderRadius:4,background:`${fc}15`,color:fc,border:`1px solid ${fc}30`,fontFamily:"'Geist Mono',monospace"}}>{asset.fileFormat}</span>
              </div>}
              <div style={{display:"flex",justifyContent:"space-between",marginBottom:7}}>
                <span style={{fontSize:12,color:T.textMuted}}>Size</span>
                <span style={{fontSize:12,color:T.text,fontFamily:"'Geist Mono',monospace"}}>{asset.size||"—"}</span>
              </div>
              {asset.storageClass&&<div style={{display:"flex",justifyContent:"space-between",marginBottom:7}}>
                <span style={{fontSize:12,color:T.textMuted}}>Storage Class</span>
                <span style={{fontSize:11.5,color:T.textSub,fontFamily:"'Geist Mono',monospace"}}>{asset.storageClass}</span>
              </div>}
              {asset.accessTier&&<div style={{display:"flex",justifyContent:"space-between",marginBottom:7}}>
                <span style={{fontSize:12,color:T.textMuted}}>Access Tier</span>
                <span style={{fontSize:11.5,color:T.textSub,fontFamily:"'Geist Mono',monospace"}}>{asset.accessTier}</span>
              </div>}
              <div style={{display:"flex",justifyContent:"space-between"}}>
                <span style={{fontSize:12,color:T.textMuted}}>Modified</span>
                <span style={{fontSize:11,color:T.textSub}}>{asset.updated}</span>
              </div>
            </Card2>
            <Card2 style={{padding:"14px 16px"}}>
              <SLabel>Classification</SLabel>
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:8}}>
                <span style={{fontSize:12,color:T.textMuted}}>Domain</span>
                <span style={{fontSize:11.5,fontWeight:600,color:T.text}}>{asset.domain}</span>
              </div>
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:8}}>
                <span style={{fontSize:12,color:T.textMuted}}>Cert</span>
                <CertBadge cert={asset.cert}/>
              </div>
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"center"}}>
                <span style={{fontSize:12,color:T.textMuted}}>Tier</span>
                <TierBadge tier={asset.tier}/>
              </div>
            </Card2>
          </div>
        </>}

        {/* ── PROPERTIES TAB ── */}
        {tab==="properties"&&(
          <div style={{flex:1,maxWidth:700}}>
            <Card2 style={{padding:"18px 20px"}}>
              <h3 style={{fontSize:13,fontWeight:600,color:T.text,margin:"0 0 4px"}}>File Properties</h3>
              <MetaRow label="File Name"      value={asset.name}        mono/>
              <MetaRow label="Format"         value={asset.fileFormat}  mono/>
              <MetaRow label="Size"           value={asset.size}        mono/>
              <MetaRow label="Last Modified"  value={formatDate(asset.lastModified)} mono/>
              {asset.storageClass&&<MetaRow label="Storage Class" value={asset.storageClass} mono/>}
              {asset.accessTier&&<MetaRow label="Access Tier"     value={asset.accessTier}   mono/>}
              <MetaRow label="Domain"         value={asset.domain}/>
              <MetaRow label="Owner"          value={asset.owner}/>
              <MetaRow label="Steward"        value={asset.steward}/>
              <MetaRow label="Status"  value={asset.cert}/>
              <MetaRow label="Tier"           value={asset.tier ? `Tier ${asset.tier}` : null}/>
              <MetaRow label="Usage"          value={asset.usage}/>
              <MetaRow label="SLA Freshness"  value={asset.slaFreshness}/>
              <MetaRow label="Connection"     value={asset.connectionLabel}/>
              <div style={{display:"flex",alignItems:"flex-start",justifyContent:"space-between",padding:"8px 0",fontSize:12,gap:16}}>
                <span style={{color:T.textMuted,flexShrink:0}}>Full Path</span>
                <span style={{fontFamily:"'Geist Mono',monospace",fontSize:11,color:T.text,textAlign:"right",wordBreak:"break-all"}}>{asset.db}</span>
              </div>
            </Card2>
          </div>
        )}

        {/* ── LINEAGE TAB ── */}
        {tab==="lineage"&&(
          <div style={{flex:1}}>
            <Card2 style={{padding:"18px 20px"}}>
              <h3 style={{fontSize:13,fontWeight:600,color:T.text,margin:"0 0 16px"}}>Storage Path</h3>
              <div style={{display:"flex",alignItems:"center",gap:0,flexWrap:"wrap",padding:"16px",background:T.bgElevated,borderRadius:8,border:`1px solid ${T.border}`}}>
                {/* Connection node */}
                <div style={{display:"flex",flexDirection:"column",alignItems:"center",gap:6}}>
                  <div style={{width:44,height:44,borderRadius:11,background:`${fc}12`,border:`1.5px solid ${fc}30`,display:"flex",alignItems:"center",justifyContent:"center"}}>
                    <ServiceIcon service={asset.service} size={24}/>
                  </div>
                  <span style={{fontSize:10,color:T.textMuted,textAlign:"center",maxWidth:80,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{asset.connectionLabel}</span>
                </div>
                {/* Path segments */}
                {(asset.path||[]).map((seg,i)=>(
                  <React.Fragment key={i}>
                    <div style={{width:32,height:1,background:T.border,flexShrink:0,margin:"0 4px",marginBottom:20}}/>
                    <div style={{display:"flex",flexDirection:"column",alignItems:"center",gap:6}}>
                      <div style={{width:44,height:44,borderRadius:11,background:T.bgSurface,border:`1.5px solid ${T.border}`,display:"flex",alignItems:"center",justifyContent:"center",color:T.textMuted}}>
                        <svg width="18" height="18" viewBox="0 0 20 20" fill="none"><path d="M3 6a1 1 0 011-1h4l2 2h6a1 1 0 011 1v7a1 1 0 01-1 1H4a1 1 0 01-1-1V6z" stroke="currentColor" strokeWidth="1.4" strokeLinejoin="round"/></svg>
                      </div>
                      <span style={{fontSize:10,color:T.textMuted,textAlign:"center",maxWidth:80,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",fontFamily:"'Geist Mono',monospace"}}>{seg}</span>
                    </div>
                  </React.Fragment>
                ))}
                {/* File node (current) */}
                <div style={{width:32,height:1,background:T.accent,flexShrink:0,margin:"0 4px",marginBottom:20,opacity:.6}}/>
                <div style={{display:"flex",flexDirection:"column",alignItems:"center",gap:6}}>
                  <div style={{width:44,height:44,borderRadius:11,background:`${fc}15`,border:`2px solid ${fc}55`,display:"flex",alignItems:"center",justifyContent:"center",color:fc,boxShadow:`0 0 0 3px ${fc}10`}}>
                    <svg width="18" height="18" viewBox="0 0 20 20" fill="none"><path d="M5 3h7l4 4v10a1 1 0 01-1 1H5a1 1 0 01-1-1V4a1 1 0 011-1z" stroke="currentColor" strokeWidth="1.4" strokeLinejoin="round"/><path d="M12 3v4h4" stroke="currentColor" strokeWidth="1.4" strokeLinejoin="round"/></svg>
                  </div>
                  <span style={{fontSize:10,color:T.text,fontWeight:700,textAlign:"center",maxWidth:100,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",fontFamily:"'Geist Mono',monospace"}}>{asset.name}</span>
                </div>
              </div>
              <div style={{marginTop:16,padding:"12px 16px",background:T.bgElevated,borderRadius:8,border:`1px solid ${T.border}`}}>
                <div style={{fontSize:11,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.07em",marginBottom:8}}>Full Path</div>
                <div style={{fontSize:12,fontFamily:"'Geist Mono',monospace",color:T.textSub,wordBreak:"break-all",lineHeight:1.6}}>{asset.db}</div>
              </div>
            </Card2>
          </div>
        )}
      </div>
    </div>
  );
};

const CONTAINER_TYPES = new Set(["Database","Catalog","Schema","Bucket","Container","Folder"]);
const AssetDetail = ({asset, assetStack=[], onBack, onAsset, onToast, onNav}) => {
  if(CONTAINER_TYPES.has(asset.type)) return <ContainerAssetDetail asset={asset} assetStack={assetStack} onBack={onBack} onAsset={onAsset} onToast={onToast}/>;
  if(asset.type==="Object"||asset.type==="Blob") return <FileAssetDetail asset={asset} onBack={onBack} onToast={onToast}/>;
  return <AssetDetailFull asset={asset} assetStack={assetStack} onBack={onBack} onAsset={onAsset} onToast={onToast} onNav={onNav}/>;
};

// ═══════════════════════════════════════════════════════════════════════════
// TABLEAU (BI) ASSET PROFILE — object-appropriate detail. A dashboard is not a
// table: no columns/row-counts/SLA, no DQ/Contract tabs. Instead: project path,
// certification, popularity, source link, extract status, fields (data sources),
// formula (calc fields), and clear upstream/downstream relationships.
// ═══════════════════════════════════════════════════════════════════════════

// Per-object profile content (keyed by asset name). props = labelled key/values;
// rel = relationships surfaced in the overview (parent / contains / upstream / downstream).
const TABLEAU_PROFILE = {
  "Analytics":         {props:[["Object type","Site"],["Projects","1"],["Data sources","2"],["Source","Tableau Cloud"]],
                        rel:{contains:[{name:"Finance",type:"Project"}]}},
  "Finance":           {props:[["Object type","Project"],["Site","Analytics"],["Top-level","Yes"],["Contents","1 workbook · 1 data source · 1 flow"]],
                        rel:{parent:{name:"Analytics",type:"Site"},contains:[{name:"Revenue_Reporting",type:"Project"},{name:"Revenue_Analytics",type:"Workbook"},{name:"Orders_Certified",type:"Data Source"},{name:"Orders_Prep_Flow",type:"Flow"}]}},
  "Revenue_Analytics": {props:[["Object type","Workbook"],["Project","Analytics / Finance"],["Contents","1 dashboard · 1 worksheet · 1 embedded source"],["Popularity","1,240 views (30d)"],["Source","Open in Tableau ↗"]],
                        rel:{parent:{name:"Finance",type:"Project"},contains:[{name:"Revenue_Dashboard",type:"Dashboard"},{name:"Revenue_by_Region",type:"Worksheet"},{name:"Revenue_Story",type:"Story"},{name:"Revenue_Extract",type:"Data Source"}]}},
  "Revenue_Dashboard": {props:[["Object type","Dashboard"],["Project","Analytics / Finance"],["Workbook","Revenue_Analytics"],["Popularity","980 views (30d)"],["Last refresh","1h ago"],["Source","Open in Tableau ↗"]],
                        rel:{contains:[{name:"Revenue_by_Region",type:"Worksheet"}],upstream:[{name:"Orders_Certified",type:"Data Source"}]}},
  "Revenue_by_Region": {props:[["Object type","Worksheet (view)"],["Workbook","Revenue_Analytics"],["Fields used","revenue, region"],["Popularity","640 views (30d)"],["Source","Open in Tableau ↗"]],
                        rel:{upstream:[{name:"Orders_Certified",type:"Data Source"}],downstream:[{name:"Revenue_Dashboard",type:"Dashboard"}]}},
  "Orders_Certified":  {props:[["Object type","Published data source"],["Publish state","Published (reusable, owned)"],["Project","Analytics / Finance"],["Tableau certified","Yes · by alex.wu — “Governed revenue surface, use this one”"],["Connection","Live (hasExtracts: false)"],["Fields","4 (1 calculated)"],["Upstream","SNOWFLAKE_PROD / COMMERCE / orders_fact"]],
                        rel:{upstream:[{name:"orders_fact",type:"Table"}],downstream:[{name:"Revenue_by_Region",type:"Worksheet"},{name:"Revenue_Dashboard",type:"Dashboard"}]}},
  "Revenue_Extract":   {props:[["Object type","Embedded data source"],["Publish state","Embedded in a workbook - no independent usage stats"],["Workbook","Revenue_Analytics"],["Connection","Extract, 420 MB (hasExtracts: true)"],["Fields","2"],["Upstream","SNOWFLAKE_PROD / COMMERCE / orders_fact"]],
                        rel:{parent:{name:"Revenue_Analytics",type:"Workbook"},upstream:[{name:"orders_fact",type:"Table"}]}},
  "Revenue_Story":     {props:[["Object type","Story"],["Workbook","Revenue_Analytics"],["Sheets in sequence","3"],["Popularity","210 views (30d)"],["Source","Open in Tableau \u2197"]],
                        rel:{parent:{name:"Revenue_Analytics",type:"Workbook"},upstream:[{name:"Revenue_by_Region",type:"Worksheet"}]}},
  "Revenue_Reporting": {props:[["Object type","Project (nested)"],["Top-level","No"],["Parent project","Finance"],["Site","Analytics"],["Permissions","Inherited from Finance"],["Contents","empty - created for the FY27 pack"]],
                        rel:{parent:{name:"Finance",type:"Project"}}},
  "Orders_Prep_Flow":  {props:[["Object type","Prep flow"],["Project","Analytics / Finance"],["Inputs","app_orders (MySQL)"],["Outputs","a Prep staging table, not crawled"],["Schedule","Daily 02:00 UTC"],["Lineage","Not reported \u2014 Tableau exposes no lineage for Prep flows"]],
                        rel:{parent:{name:"Finance",type:"Project"}}},
  "Daily_Revenue":     {legacy:true,props:[["Object type","Metric (legacy)"],["Project","Analytics / Finance"],["Status","Retired — unavailable in Tableau API 3.22+"],["Lineage","Not reported for Tableau metrics"]],
                        rel:{}},
};

// Fields exposed by each Tableau data source (the "schema" equivalent for a BI source).
// Fields exposed by each Tableau data source - the "schema" equivalent for a BI source.
// `logic` states whether the definition lives in Tableau or is a passthrough, which is the
// governance question a calculated field raises: business logic outside the warehouse.
const TABLEAU_FIELDS = {
  "Orders_Certified":[
    {name:"revenue",        dataType:"decimal",    role:"Measure",   calc:false, upstream:"orders_fact.revenue",    logic:"Passthrough", desc:"Recognised revenue, passed straight through from the Snowflake column. No Tableau-side logic."},
    {name:"yoy_growth_pct", dataType:"percentage", role:"Measure",   calc:true,  dependsOn:"revenue",               logic:"Defined in Tableau only", desc:"Year-on-year growth. The definition exists nowhere but this data source, so it cannot be governed at the warehouse.", formula:"(SUM([revenue]) − LOOKUP(SUM([revenue]), −1))\n/ ABS(LOOKUP(SUM([revenue]), −1))"},
    {name:"region",         dataType:"string",     role:"Dimension", calc:false, upstream:"orders_fact.region",     logic:"Passthrough", desc:"Sales region, resolved upstream by the dbt country_codes seed."},
    {name:"order_date",     dataType:"date",       role:"Dimension", calc:false, upstream:"orders_fact.order_date", logic:"Passthrough", desc:"Order date. Time grain for every revenue view."},
  ],
  "Revenue_Extract":[
    {name:"order_amount",   dataType:"decimal",    role:"Measure",   calc:false, upstream:"orders_fact.revenue",    logic:"Passthrough", desc:"Duplicates the certified data source's revenue measure under a different name - a governance smell worth surfacing."},
    {name:"region",         dataType:"string",     role:"Dimension", calc:false, upstream:"orders_fact.region",     logic:"Passthrough", desc:"Sales region."},
  ],
};

// Relationship row — a labelled reference to a related Tableau/DB object (read-only, honest: no dead links).
const TbRelRow = ({name,type,rel})=>(
  <div style={{display:"flex",alignItems:"center",gap:10,padding:"9px 12px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:8,marginBottom:6}}>
    <TypeBadge type={type}/>
    <span style={{fontSize:12,fontFamily:"'Geist Mono',monospace",color:T.text,flex:1,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{name}</span>
    <span style={{fontSize:11,color:T.textMuted,whiteSpace:"nowrap"}}>{rel}</span>
  </div>
);

const TableauAssetOverview = ({asset,data,setData,onToast})=>{
  const navFn = useNav();
  const P = TABLEAU_PROFILE[asset.name] || {props:[["Object type",asset.type],["Path",asset.db]],rel:{}};
  const rel = P.rel||{};
  const [editingDesc,setEditingDesc]=useState(false);
  const [descVal,setDescVal]=useState(data.description||asset.description||"");
  const fields = TABLEAU_FIELDS[asset.name];

  return (
  <div style={{display:"flex",flexDirection:"column",gap:16,maxWidth:900}}>

    {/* Description */}
    <Card2>
      <div style={{padding:"14px 16px"}}>
        <SH title="Description" action={
          editingDesc
            ? <div style={{display:"flex",gap:6}}>
                <Btn small ghost onClick={()=>{setData(d=>({...d,description:descVal}));setEditingDesc(false);onToast&&onToast("Description saved","success");}}>Save</Btn>
                <Btn small ghost onClick={()=>{setDescVal(data.description||asset.description||"");setEditingDesc(false);}}>Cancel</Btn>
              </div>
            : <Btn small ghost icon={Ic.edit(11)} onClick={()=>setEditingDesc(true)}>Edit</Btn>
        }/>
        {editingDesc
          ? <textarea value={descVal} onChange={e=>setDescVal(e.target.value)} rows={3}
              style={{width:"100%",padding:"9px 12px",background:T.bgElevated,border:`1.5px solid ${T.accent}`,borderRadius:8,color:T.text,fontSize:13,outline:"none",resize:"vertical",lineHeight:1.7,fontFamily:"inherit",boxSizing:"border-box"}}/>
          : <p style={{fontSize:13,color:T.textSub,lineHeight:1.8,margin:0}}>{descVal}</p>
        }
      </div>
    </Card2>

    {/* Tableau properties */}
    <Card2>
      <div style={{padding:"14px 16px"}}>
        <SH title="Properties"/>
        <div style={{background:T.bgElevated,borderRadius:8,border:`1px solid ${T.border}`,overflow:"hidden"}}>
          {P.props.map((row,i)=>{
            const isSource = /open in tableau/i.test(String(row[1]));
            return (
              <div key={row[0]} style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:12,padding:"9px 12px",borderBottom:i<P.props.length-1?`1px solid ${T.border}`:"none"}}>
                <span style={{fontSize:11.5,color:T.textMuted}}>{row[0]}</span>
                {isSource
                  ? <button onClick={()=>onToast&&onToast("Opens in Tableau (mock)","success")} style={{background:"none",border:"none",cursor:"pointer",color:T.blue,fontSize:12,fontWeight:600,fontFamily:"'Geist Mono',monospace",padding:0}}>{row[1]}</button>
                  : <span style={{fontSize:12,color:T.textSub,fontFamily:"'Geist Mono',monospace",textAlign:"right",wordBreak:"break-word"}}>{row[1]}</span>}
              </div>
            );
          })}
        </div>
      </div>
    </Card2>

    {/* Calculation (calculated field only) */}
    {P.formula&&(
      <Card2>
        <div style={{padding:"14px 16px"}}>
          <SH title="Calculation"/>
          <pre style={{margin:0,padding:"12px 14px",background:"#0f172a",color:"#e2e8f0",borderRadius:8,fontSize:12,fontFamily:"'Geist Mono',monospace",lineHeight:1.7,overflowX:"auto",whiteSpace:"pre-wrap"}}>{P.formula}</pre>
        </div>
      </Card2>
    )}

    {/* Relationships — parent / contains / upstream / downstream */}
    {(rel.parent||rel.contains||rel.upstream||rel.downstream)&&(
      <Card2>
        <div style={{padding:"14px 16px"}}>
          <SH title="Relationships"/>
          {rel.parent&&<>
            <div style={{fontSize:10,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.07em",margin:"2px 0 8px"}}>Parent</div>
            <TbRelRow name={rel.parent.name} type={rel.parent.type} rel="Contained in"/>
          </>}
          {rel.upstream&&<>
            <div style={{fontSize:10,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.07em",margin:"10px 0 8px"}}>Upstream — feeds this object</div>
            {rel.upstream.map(r=><TbRelRow key={r.name} name={r.name} type={r.type} rel="Source"/>)}
          </>}
          {rel.contains&&<>
            <div style={{fontSize:10,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.07em",margin:"10px 0 8px"}}>Contains</div>
            {rel.contains.map(r=><TbRelRow key={r.name} name={r.name} type={r.type} rel="Child"/>)}
          </>}
          {rel.downstream&&<>
            <div style={{fontSize:10,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.07em",margin:"10px 0 8px"}}>Downstream — consumes this object</div>
            {rel.downstream.map(r=><TbRelRow key={r.name} name={r.name} type={r.type} rel="Consumer"/>)}
          </>}
          <div style={{fontSize:11,color:T.textMuted,marginTop:6}}>See the <b style={{color:T.textSub}}>Lineage</b> tab for the full column-level graph.</div>
        </div>
      </Card2>
    )}

    {/* Fields (data sources only) */}
    {fields&&(
      <Card2>
        <div style={{padding:"14px 16px"}}>
          <SH title={`Fields (${fields.length})`}/>
          <div style={{background:T.bgElevated,borderRadius:8,border:`1px solid ${T.border}`,overflow:"hidden"}}>
            {fields.map((f,i)=>(
              <div key={f.name} style={{display:"flex",alignItems:"center",gap:10,padding:"9px 12px",borderBottom:i<fields.length-1?`1px solid ${T.border}`:"none"}}>
                <span style={{fontSize:12,fontFamily:"'Geist Mono',monospace",color:T.text,flex:1,minWidth:0,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{f.name}</span>
                {f.calc&&<span style={{fontSize:9.5,fontWeight:700,color:"#d97706",background:"rgba(217,119,6,.1)",border:"1px solid rgba(217,119,6,.25)",borderRadius:4,padding:"1px 6px"}}>ƒ calc</span>}
                <span style={{fontSize:10,fontWeight:600,color:f.role==="Measure"?"#16a34a":"#2563eb",background:f.role==="Measure"?"rgba(22,163,74,.1)":"rgba(37,99,235,.1)",borderRadius:4,padding:"1px 7px"}}>{f.role}</span>
                <span style={{fontSize:11,color:T.textMuted,fontFamily:"'Geist Mono',monospace",width:78,textAlign:"right"}}>{f.dataType}</span>
              </div>
            ))}
          </div>
        </div>
      </Card2>
    )}

    {/* Governance — policies/regulations that apply via the object's domain */}
    {(()=>{
      const govPols = DEMO_POLICIES_GLOBAL.filter(p=>(p.scope?.domains||[]).includes(asset.domain)||(p.links||[]).some(l=>l.target===asset.name));
      if(!govPols.length) return null;
      const LC_COLOR = {Active:T.green,"In Review":T.amber,Draft:T.textMuted,Approved:T.blue,Deprecated:T.rose};
      const govRegs = [...new Set(govPols.flatMap(p=>p.regulations||[]))];
      return (
        <Card2>
          <div style={{padding:"14px 16px"}}>
            <SH title="Governance"/>
            <div style={{fontSize:10,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.07em",marginBottom:8}}>Governing Policies</div>
            {govPols.map(p=>{
              const lcc = LC_COLOR[p.lifecycle]||T.textMuted;
              return (
                <div key={p.id} onClick={()=>navFn("policymanager",{policyId:p.id})}
                  onMouseEnter={e=>e.currentTarget.style.background=T.bgHover} onMouseLeave={e=>e.currentTarget.style.background=T.bgElevated}
                  style={{display:"flex",alignItems:"center",gap:10,padding:"9px 12px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:8,marginBottom:6,cursor:"pointer",transition:"background .1s"}}>
                  <div style={{width:7,height:7,borderRadius:"50%",background:lcc,flexShrink:0}}/>
                  <div style={{flex:1,minWidth:0}}>
                    <div style={{fontSize:12,fontWeight:600,color:T.text,lineHeight:1.4}}>{p.name}</div>
                    <div style={{fontSize:10.5,color:T.textMuted,marginTop:1}}>{p.category} · {p.severity} severity</div>
                  </div>
                  <span style={{fontSize:10,fontWeight:700,padding:"2px 7px",borderRadius:99,background:`${lcc}15`,color:lcc,border:`1px solid ${lcc}25`,flexShrink:0,whiteSpace:"nowrap"}}>{p.lifecycle}</span>
                </div>
              );
            })}
            {govRegs.length>0&&(
              <div style={{marginTop:6}}>
                <div style={{fontSize:10,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.07em",marginBottom:8}}>Applicable Regulations</div>
                <div style={{display:"flex",flexWrap:"wrap",gap:6}}>
                  {govRegs.map(r=>(
                    <span key={r} style={{display:"inline-flex",alignItems:"center",gap:5,fontSize:11.5,padding:"4px 10px",borderRadius:6,background:`${T.accent}12`,color:T.accent,border:`1px solid ${T.accent}25`,fontWeight:600}}>{r}</span>
                  ))}
                </div>
              </div>
            )}
          </div>
        </Card2>
      );
    })()}

    {/* Activity — Tableau-appropriate events */}
    <Card2>
      <div style={{padding:"14px 16px"}}>
        <SH title="Activity"/>
        <div style={{position:"relative",paddingLeft:18}}>
          {[
            {ts:"2026-08-18",who:"alex.wu",  action:`Certification set to ${data.cert||"Approved"}`, color:T.green},
            {ts:"2026-08-18",who:"ai-bot",   action:`Refreshed from source (${asset.slaFreshness&&asset.slaFreshness!=="—"?asset.slaFreshness:"scheduled"})`, color:T.amber},
            {ts:"2026-08-15",who:"james.oh", action:`Steward assigned`, color:T.blue},
            {ts:"2026-08-12",who:"ai-bot",   action:`${asset.name} crawled from Tableau Cloud`, color:T.textMuted},
          ].map((h,i,arr)=>(
            <div key={i} style={{position:"relative",paddingBottom:14}}>
              <div style={{position:"absolute",left:-14,top:4,width:8,height:8,borderRadius:"50%",background:h.color,border:`2px solid ${T.bgSurface}`}}/>
              {i<arr.length-1&&<div style={{position:"absolute",left:-11,top:13,bottom:0,width:1,background:T.border}}/>}
              <div style={{fontSize:12.5,color:T.text,marginBottom:2}}>{h.action}</div>
              <div style={{fontSize:11,color:T.textMuted}}>{h.ts} · <span style={{fontFamily:"'Geist Mono',monospace"}}>{h.who}</span></div>
            </div>
          ))}
        </div>
      </div>
    </Card2>
  </div>
  );
};

// Fields tab for a Tableau data source (the schema equivalent).
const TableauFieldsPanel = ({asset})=>{
  const fields = TABLEAU_FIELDS[asset.name]||[];
  const [q,setQ]=useState("");
  const [open,setOpen]=useState(null);   // a field expands in place - it is not its own page
  const filtered = fields.filter(f=>!q||f.name.toLowerCase().includes(q.toLowerCase()));
  return (
    <div className="fadeIn">
      <Card2 style={{overflow:"hidden",padding:0}}>
        <div style={{padding:"12px 16px",borderBottom:`1px solid ${T.border}`,display:"flex",gap:12,alignItems:"center"}}>
          <div style={{position:"relative",flex:1,minWidth:160}}>
            <svg width="13" height="13" viewBox="0 0 14 14" fill="none" style={{position:"absolute",left:9,top:"50%",transform:"translateY(-50%)",color:T.textMuted,pointerEvents:"none"}}><circle cx="6" cy="6" r="4.5" stroke="currentColor" strokeWidth="1.3"/><path d="M10 10l2.5 2.5" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round"/></svg>
            <input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search fields…"
              style={{width:"100%",padding:"6px 10px 6px 28px",background:T.bgElevated,border:`1.5px solid ${q?T.accent:T.border}`,borderRadius:7,color:T.text,fontSize:12,outline:"none",boxSizing:"border-box"}}/>
          </div>
          <span style={{fontSize:11.5,color:T.textMuted}}>{fields.length} fields · {fields.filter(f=>f.calc).length} calculated</span>
        </div>
        <div style={{display:"grid",gridTemplateColumns:"1.4fr 0.7fr 0.8fr 1.6fr",padding:"9px 16px",borderBottom:`1px solid ${T.border}`,fontSize:10,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.06em"}}>
          <span>Field</span><span>Role</span><span>Data type</span><span>Upstream / formula</span>
        </div>
        {filtered.map((f,i)=>(
          <React.Fragment key={f.name}>
          <div onClick={()=>setOpen(open===f.name?null:f.name)}
            title={open===f.name?"Hide details":"Show details"}
            style={{cursor:"pointer",background:open===f.name?T.bgHover:"transparent",display:"grid",gridTemplateColumns:"1.4fr 0.7fr 0.8fr 1.6fr",alignItems:"center",padding:"10px 16px",borderBottom:(open===f.name||i<filtered.length-1)?`1px solid ${T.border}`:"none"}}>
            <span style={{display:"inline-flex",alignItems:"center",gap:6,fontSize:12.5,fontFamily:"'Geist Mono',monospace",color:T.text,minWidth:0}}>
              <span style={{overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{f.name}</span>
              {f.calc&&<span style={{fontSize:9,fontWeight:700,color:"#d97706",background:"rgba(217,119,6,.1)",border:"1px solid rgba(217,119,6,.25)",borderRadius:4,padding:"0 5px",flexShrink:0}}>ƒ</span>}
            </span>
            <span><span style={{fontSize:10.5,fontWeight:600,color:f.role==="Measure"?"#16a34a":"#2563eb",background:f.role==="Measure"?"rgba(22,163,74,.1)":"rgba(37,99,235,.1)",borderRadius:4,padding:"2px 8px"}}>{f.role}</span></span>
            <span style={{fontSize:11.5,color:T.textMuted,fontFamily:"'Geist Mono',monospace"}}>{f.dataType}</span>
            <span style={{fontSize:11,color:T.textSub,fontFamily:"'Geist Mono',monospace",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}} title={f.calc?f.formula:f.upstream}>{f.calc?f.formula:f.upstream}</span>
          </div>
          {open===f.name&&(
            <div style={{padding:"12px 16px 14px",background:T.bgElevated,borderBottom:i<filtered.length-1?`1px solid ${T.border}`:"none",
              display:"flex",flexDirection:"column",gap:10}}>
              <div style={{fontSize:12,color:T.textSub,lineHeight:1.6,maxWidth:640}}>{f.desc}</div>
              <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(150px,1fr))",gap:"10px 18px"}}>
                {[["Role",f.role],["Data type",f.dataType],["Definition",f.logic],
                  ...(f.upstream?[["Upstream column",f.upstream]]:[]),
                  ...(f.dependsOn?[["Depends on",f.dependsOn]]:[])].map(([k,v])=>(
                  <div key={k}>
                    <div style={{fontSize:9.5,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:".06em",marginBottom:3}}>{k}</div>
                    <div style={{fontSize:11.5,color:T.text,fontFamily:"'Geist Mono',monospace",wordBreak:"break-word"}}>{v}</div>
                  </div>
                ))}
              </div>
              {f.calc&&(
                <div>
                  <div style={{fontSize:9.5,fontWeight:700,color:"#c2410c",textTransform:"uppercase",letterSpacing:".06em",marginBottom:5}}>Calculation — lives only in Tableau</div>
                  <pre style={{margin:0,padding:11,background:"#0f172a",color:"#e2e8f0",borderRadius:7,fontSize:11,
                    fontFamily:"'Geist Mono',monospace",lineHeight:1.6,overflowX:"auto",whiteSpace:"pre"}}>{f.formula}</pre>
                </div>
              )}
            </div>
          )}
          </React.Fragment>
        ))}
        {filtered.length===0&&<div style={{padding:"28px",textAlign:"center",fontSize:12,color:T.textMuted}}>No fields match.</div>}
      </Card2>
    </div>
  );
};

// ===========================================================================
// BigID - a CONTRIBUTOR, not an asset family. BigID's own inventory is the objects
// and columns its scans discover, which are the tables this catalog already holds,
// so it creates no assets. What it adds is column-level classification with a
// confidence score, and those arrive as PROPOSALS a steward accepts or rejects -
// never as tags applied silently. Accepted ones land in the existing tag model
// with origin "synced" and sourceSystem "BigID".
// ===========================================================================
const BIGID_FINDINGS = {
  "customers":{
    scan:"weekly_pii_scan", lastScan:"3h ago", duration:"18m 40s", scanned:"3.1M rows sampled (1,000 per column)",
    columns:[
      {col:"email",         classifier:"Email Address",  confidence:99, samples:1000, matched:998, status:"accepted", tag:"PII",       note:""},
      {col:"phone",         classifier:"Phone Number",   confidence:96, samples:1000, matched:961, status:"accepted", tag:"PII",       note:""},
      {col:"date_of_birth", classifier:"Date of Birth",  confidence:93, samples:1000, matched:930, status:"proposed", tag:null,        note:"No EDG classification mapped yet \u2014 waiting on a steward in the Inbox."},
      {col:"address",       classifier:"Street Address", confidence:88, samples:1000, matched:884, status:"proposed", tag:"PII",       note:"The Street Address classifier is mapped to PII, so this is the tag it would apply \u2014 a steward still has to accept the finding on this column."},
      {col:"customer_id",   classifier:"National ID",    confidence:41, samples:1000, matched:412, status:"rejected", tag:null,        note:"Rejected by priya.nair \u2014 the pattern matches an internal surrogate key, not a national ID. Low confidence was the tell."},
    ],
    policies:[
      {name:"GDPR Art. 9 \u2014 special category data", status:"hit",   detail:"date_of_birth is unmasked in 2 downstream views. Masking is enforced on the table but not on the views built from it."},
      {name:"Retention \u2014 contact data 7 years",     status:"clear", detail:"No records older than the retention window."},
    ]},
  "orders":{
    scan:"weekly_pii_scan", lastScan:"3h ago", duration:"18m 40s", scanned:"48.6M rows sampled (1,000 per column)",
    columns:[
      {col:"customer_id",      classifier:"Cross-reference to PII", confidence:97, samples:1000, matched:970, status:"accepted", tag:"PII", note:"Correlated to customers.customer_id, so this column is an indirect identifier."},
      {col:"shipping_address", classifier:"Street Address",         confidence:91, samples:1000, matched:912, status:"accepted", tag:"PII", note:""},
    ],
    policies:[
      {name:"GDPR Art. 5 \u2014 minimisation", status:"hit", detail:"shipping_address is retained on every historical order; only the latest is needed downstream."},
    ]},
};

const BIGID_STATUS_C = {
  accepted:{c:"#16a34a", bg:"rgba(22,163,74,.1)",  label:"Accepted"},
  proposed:{c:"#d97706", bg:"rgba(217,119,6,.12)", label:"Proposed"},
  rejected:{c:"#6b7280", bg:"rgba(107,114,128,.1)",label:"Rejected"},
};

// The BigID tab on a scanned asset.
const BigIdOnAssetPanel = ({asset,onToast})=>{
  const f=BIGID_FINDINGS[asset.name];
  if(!f) return <div className="fadeIn" style={{fontSize:12.5,color:T.textMuted}}>No BigID scan has covered this asset.</div>;
  const counts=["accepted","proposed","rejected"].map(k=>({k,n:f.columns.filter(c=>c.status===k).length}));
  return (
    <div className="fadeIn" style={{display:"flex",flexDirection:"column",gap:16,maxWidth:940}}>

      <Card2><div style={{padding:"14px 16px"}}>
        <SH title="Scanned by BigID" sub="BigID creates no catalog assets — it classifies the columns of assets EDG already holds"/>
        <div style={{display:"flex",alignItems:"center",gap:12,padding:"11px 13px",background:"rgba(18,183,106,.06)",
          border:"1px solid rgba(18,183,106,.25)",borderRadius:9,marginBottom:12}}>
          <ServiceIcon service="bigid" size={22}/>
          <div style={{flex:1,minWidth:0}}>
            <div style={{fontSize:13,fontWeight:700,color:T.text,fontFamily:"'Geist Mono',monospace"}}>{f.scan}</div>
            <div style={{fontSize:11,color:T.textMuted,marginTop:1}}>Last scan {f.lastScan} {"\u00b7"} {f.duration} {"\u00b7"} {f.scanned}</div>
          </div>
        </div>
        <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
          {counts.map(({k,n})=>{
            const c=BIGID_STATUS_C[k];
            return <span key={k} style={{fontSize:11,fontWeight:600,padding:"3px 10px",borderRadius:6,background:c.bg,color:c.c,border:`1px solid ${c.c}33`}}>{n} {c.label.toLowerCase()}</span>;
          })}
        </div>
      </div></Card2>

      <Card2 style={{overflow:"hidden"}}>
        <div style={{padding:"14px 16px 10px"}}>
          <SH title="Column classifications" sub="A finding is a proposal until a steward accepts it. Confidence is BigID's, not ours."/>
        </div>
        <table style={{width:"100%",borderCollapse:"collapse"}}>
          <thead><tr style={{background:T.bgElevated}}>
            {["Column","BigID classifier","Confidence","Matched","EDG classification","State"].map(h=>(
              <th key={h} style={{padding:"8px 14px",textAlign:"left",fontSize:10,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:".06em",borderBottom:`1px solid ${T.border}`}}>{h}</th>
            ))}
          </tr></thead>
          <tbody>
            {f.columns.map((c,i)=>{
              const st=BIGID_STATUS_C[c.status];
              const conf=c.confidence>=90?"#16a34a":c.confidence>=70?"#d97706":"#e11d48";
              return (
                <React.Fragment key={c.col}>
                  <tr style={{borderBottom:c.note?"none":(i<f.columns.length-1?`1px solid ${T.border}`:"none")}}>
                    <td style={{padding:"9px 14px",fontSize:12,fontFamily:"'Geist Mono',monospace",color:T.text,fontWeight:600}}>{c.col}</td>
                    <td style={{padding:"9px 14px",fontSize:11.5,color:T.textSub}}>{c.classifier}</td>
                    <td style={{padding:"9px 14px"}}>
                      <div style={{display:"flex",alignItems:"center",gap:7}}>
                        <div style={{width:52,height:5,borderRadius:3,background:T.border,overflow:"hidden",flexShrink:0}}>
                          <div style={{width:`${c.confidence}%`,height:"100%",background:conf}}/>
                        </div>
                        <span style={{fontSize:11.5,color:conf,fontWeight:600,fontVariantNumeric:"tabular-nums"}}>{c.confidence}%</span>
                      </div>
                    </td>
                    <td style={{padding:"9px 14px",fontSize:11.5,color:T.textMuted,fontFamily:"'Geist Mono',monospace",fontVariantNumeric:"tabular-nums"}}>{c.matched}/{c.samples}</td>
                    <td style={{padding:"9px 14px"}}>
                      {c.tag
                        ? <span style={{fontSize:10.5,fontWeight:600,padding:"2px 8px",borderRadius:4,background:T.bgElevated,color:T.textSub,border:`1px solid ${T.border}`,fontFamily:"'Geist Mono',monospace"}}>{c.tag}</span>
                        : <span style={{fontSize:11,color:T.textMuted}}>{"\u2014"}</span>}
                    </td>
                    <td style={{padding:"9px 14px",whiteSpace:"nowrap"}}>
                      <span style={{fontSize:10,fontWeight:700,padding:"2px 8px",borderRadius:5,background:st.bg,color:st.c,border:`1px solid ${st.c}33`,textTransform:"uppercase",letterSpacing:".05em"}}>{st.label}</span>
                      {c.status==="proposed"&&(
                        <button onClick={()=>onToast&&onToast(`${c.col} sent to the steward inbox for review`,"success")}
                          style={{marginLeft:8,fontSize:10.5,fontWeight:600,padding:"2px 8px",borderRadius:5,background:"transparent",
                            color:T.accent,border:`1px solid ${T.accent}55`,cursor:"pointer",fontFamily:"inherit"}}>Review</button>
                      )}
                    </td>
                  </tr>
                  {c.note&&<tr style={{borderBottom:i<f.columns.length-1?`1px solid ${T.border}`:"none"}}>
                    <td colSpan={6} style={{padding:"0 14px 9px",fontSize:11,color:T.textMuted,fontStyle:"italic"}}>{c.note}</td>
                  </tr>}
                </React.Fragment>
              );
            })}
          </tbody>
        </table>
      </Card2>

      <Card2><div style={{padding:"14px 16px"}}>
        <SH title="Policy findings" sub="BigID evaluates its own policies over what it found; EDG policies stay separate"/>
        <div style={{display:"flex",flexDirection:"column",gap:7}}>
          {f.policies.map(p=>{
            const hit=p.status==="hit";
            return (
              <div key={p.name} style={{display:"flex",gap:10,padding:"9px 11px",background:T.bgElevated,
                border:`1px solid ${hit?"rgba(225,29,72,.28)":T.border}`,borderRadius:8,alignItems:"flex-start"}}>
                <span style={{fontSize:9.5,fontWeight:700,padding:"2px 7px",borderRadius:4,marginTop:1,whiteSpace:"nowrap",
                  background:hit?"rgba(225,29,72,.1)":"rgba(22,163,74,.1)",color:hit?"#e11d48":"#16a34a",
                  border:`1px solid ${hit?"#e11d48":"#16a34a"}33`,textTransform:"uppercase",letterSpacing:".05em"}}>{hit?"Hit":"Clear"}</span>
                <div style={{minWidth:0}}>
                  <div style={{fontSize:12,fontWeight:600,color:T.text}}>{p.name}</div>
                  <div style={{fontSize:11.5,color:T.textSub,lineHeight:1.55,marginTop:2}}>{p.detail}</div>
                </div>
              </div>
            );
          })}
        </div>
        <div style={{marginTop:12,paddingTop:10,borderTop:`1px solid ${T.border}`,fontSize:10.5,color:T.textMuted,lineHeight:1.6}}>
          Ingested from BigID, not authored in EDG: scan results, classifier names and confidence scores.
          Accepted classifications flow into the EDG tag model with origin <span style={{fontFamily:"'Geist Mono',monospace"}}>synced</span> and
          source <span style={{fontFamily:"'Geist Mono',monospace"}}>BigID</span>. Reverse sync is off — EDG never writes a classification back.
        </div>
      </div></Card2>
    </div>
  );
};

// ===========================================================================
// AWS GLUE - what a Glue table adds over a warehouse table. Glue introduces no new
// object types (Atlan maps it onto Database/Schema/Table/View/Column), so the only
// extra surface is the ETL side: the job or crawler that produced the table, and
// where it physically sits on S3. Jobs are orchestration, so they are attributes
// with run history here rather than governed assets - the same call as dbt Cloud jobs.
// ===========================================================================
const GLUE_RUNS = {
  "sessionize_clickstream":{
    kind:"ETL job", trigger:"EventBridge, hourly", worker:"G.2X · 10 workers", glueVersion:"4.0",
    script:"s3://jnj-glue-scripts/sessionize_clickstream.py", bookmark:"Enabled",
    runs:[
      {id:"jr_8841", status:"succeeded", started:"55m ago", duration:"11m 20s", read:"1.8B rows", written:"412M rows", note:""},
      {id:"jr_8840", status:"succeeded", started:"1h 55m ago", duration:"10m 48s", read:"1.8B rows", written:"411M rows", note:""},
      {id:"jr_8839", status:"failed",    started:"2h 55m ago", duration:"2m 04s",  read:"—", written:"—", note:"Job bookmark hit a schema change: payload.utm.campaign appeared mid-run. Re-ran after the crawler refreshed the table definition."},
      {id:"jr_8838", status:"succeeded", started:"3h 55m ago", duration:"10m 12s", read:"1.7B rows", written:"408M rows", note:""},
    ]},
  "clickstream_crawler":{
    kind:"Crawler", trigger:"Schedule, every 6 hours", worker:"—", glueVersion:"—",
    script:"—", bookmark:"—",
    runs:[
      {id:"cr_2210", status:"succeeded", started:"1h ago",  duration:"3m 41s", read:"—", written:"2 columns added", note:"Detected payload.utm.source and payload.utm.campaign. Schema drift on a Draft table."},
      {id:"cr_2209", status:"succeeded", started:"7h ago",  duration:"3m 12s", read:"—", written:"no change", note:""},
    ]},
};

const GLUE_RUN_C = {succeeded:{c:"#16a34a",bg:"rgba(22,163,74,.1)"},failed:{c:"#e11d48",bg:"rgba(225,29,72,.1)"},running:{c:"#d97706",bg:"rgba(217,119,6,.12)"}};

// The "Glue" tab on a Glue table: what built it, where it lives, and its run history.
const GlueOnTablePanel = ({asset})=>{
  const name=asset.glueJob||asset.glueCrawler;
  const g=GLUE_RUNS[name];
  if(!g) return <div className="fadeIn" style={{fontSize:12.5,color:T.textMuted}}>No Glue job or crawler is associated with this table.</div>;
  const isJob=!!asset.glueJob;
  return (
    <div className="fadeIn" style={{display:"flex",flexDirection:"column",gap:16,maxWidth:900}}>
      <Card2><div style={{padding:"14px 16px"}}>
        <SH title={isJob?"Built by a Glue ETL job":"Discovered by a Glue crawler"}
          sub={isJob
            ? "A Glue job writes this table. The job is an attribute here, not a catalog asset \u2014 orchestration is not a data object."
            : "A crawler discovered this table definition from S3. It does not write the data; it infers the schema."}/>
        <div style={{display:"flex",alignItems:"center",gap:12,padding:"11px 13px",background:"rgba(140,79,255,.06)",
          border:"1px solid rgba(140,79,255,.25)",borderRadius:9}}>
          <ServiceIcon service="glue" size={22}/>
          <div style={{flex:1,minWidth:0}}>
            <div style={{fontSize:13,fontWeight:700,color:T.text,fontFamily:"'Geist Mono',monospace"}}>{name}</div>
            <div style={{fontSize:11,color:T.textMuted,marginTop:1}}>{g.kind} {"\u00b7"} {g.trigger}</div>
          </div>
        </div>
      </div></Card2>

      <Card2><div style={{padding:"14px 16px"}}>
        <SH title="Glue" sub="Ingested from the Glue Data Catalog and the job run API"/>
        <DbtProps rows={[
          ["S3 location",asset.s3Location||"—"],
          ["Glue version",g.glueVersion],
          ["Worker type",g.worker],
          ["Trigger",g.trigger],
          ["Job bookmark",g.bookmark],
          ["Script",g.script],
        ]}/>
        <div style={{marginTop:12,paddingTop:10,borderTop:`1px solid ${T.border}`,fontSize:10.5,color:T.textMuted,lineHeight:1.6}}>
          Ingested from AWS, not authored in EDG: <span style={{fontFamily:"'Geist Mono',monospace"}}>GetTable</span> (schema, S3 location, parameters)
          {" \u00b7 "}<span style={{fontFamily:"'Geist Mono',monospace"}}>GetJobRuns</span> (run history, rows read and written)
          {" \u00b7 "}<span style={{fontFamily:"'Geist Mono',monospace"}}>GetDataflowGraph</span> (the table-to-table edge on the Lineage tab)
          {asset.glueCrawler?<>{" \u00b7 "}<span style={{fontFamily:"'Geist Mono',monospace"}}>GetCrawlerMetrics</span> (schema drift)</>:null}
        </div>
      </div></Card2>

      <Card2 style={{overflow:"hidden"}}>
        <div style={{padding:"14px 16px 10px"}}><SH title="Run history" sub={"Recent "+(isJob?"job":"crawler")+" runs from the Glue API"}/></div>
        <table style={{width:"100%",borderCollapse:"collapse"}}>
          <thead><tr style={{background:T.bgElevated}}>
            {["Run","Status","Started","Duration","Read","Written"].map(h=>(
              <th key={h} style={{padding:"7px 14px",textAlign:"left",fontSize:10,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:".06em",borderBottom:`1px solid ${T.border}`}}>{h}</th>
            ))}
          </tr></thead>
          <tbody>
            {g.runs.map((r,i)=>{
              const c=GLUE_RUN_C[r.status]||{c:T.textMuted,bg:T.bgHover};
              return (
                <React.Fragment key={r.id}>
                  <tr style={{borderBottom:r.note?"none":(i<g.runs.length-1?`1px solid ${T.border}`:"none")}}>
                    <td style={{padding:"8px 14px",fontSize:12,fontFamily:"'Geist Mono',monospace",color:T.text,fontWeight:600}}>{r.id}</td>
                    <td style={{padding:"8px 14px"}}><span style={{fontSize:10,fontWeight:700,padding:"2px 8px",borderRadius:5,background:c.bg,color:c.c,border:`1px solid ${c.c}33`,textTransform:"uppercase",letterSpacing:".05em"}}>{r.status}</span></td>
                    <td style={{padding:"8px 14px",fontSize:11.5,color:T.textMuted,whiteSpace:"nowrap"}}>{r.started}</td>
                    <td style={{padding:"8px 14px",fontSize:11.5,color:T.textSub,fontFamily:"'Geist Mono',monospace"}}>{r.duration}</td>
                    <td style={{padding:"8px 14px",fontSize:11.5,color:T.textSub,fontFamily:"'Geist Mono',monospace"}}>{r.read}</td>
                    <td style={{padding:"8px 14px",fontSize:11.5,color:T.textSub,fontFamily:"'Geist Mono',monospace"}}>{r.written}</td>
                  </tr>
                  {r.note&&<tr style={{borderBottom:i<g.runs.length-1?`1px solid ${T.border}`:"none"}}>
                    <td colSpan={6} style={{padding:"0 14px 8px",fontSize:11,color:T.textMuted,fontStyle:"italic"}}>{r.note}</td>
                  </tr>}
                </React.Fragment>
              );
            })}
          </tbody>
        </table>
      </Card2>
    </div>
  );
};

// ===========================================================================
// POWER BI ASSET PROFILE - object-appropriate detail per Atlan's crawl model.
// A dataset is not a table: what matters is its tables/columns/DAX measures, its
// endorsement, and what binds to it. Parts live inside, never as catalog rows.
// ===========================================================================

// The parts of a Power BI dataset or dataflow. A DAX measure is the interesting one to
// govern: like a Tableau calculated field, its logic exists only in the BI tool.
const POWERBI_PARTS = {
  "Revenue_Model":[
    {kind:"Table",   name:"orders_fact",   type:"import",  expr:"",  source:"SNOWFLAKE_PROD.COMMERCE.orders_fact", logic:"Passthrough",          desc:"Imported table backing the model. Refreshed with the dataset."},
    {kind:"Column",  name:"revenue",       type:"decimal", expr:"",  source:"orders_fact.revenue",                 logic:"Passthrough",          desc:"Recognised revenue, straight from the warehouse column."},
    {kind:"Column",  name:"region",        type:"string",  expr:"",  source:"orders_fact.region",                  logic:"Passthrough",          desc:"Sales region, resolved upstream by the dbt country_codes seed."},
    {kind:"Column",  name:"order_date",    type:"date",    expr:"",  source:"orders_fact.order_date",              logic:"Passthrough",          desc:"Order date. Drives the model's date hierarchy."},
    {kind:"Measure", name:"Total Revenue", type:"DAX",     expr:"SUM(orders_fact[revenue])",                       source:"orders_fact.revenue", logic:"Defined in Power BI only", desc:"The measure every finance visual reads. One definition, held in the dataset rather than the warehouse."},
    {kind:"Measure", name:"YoY Growth %",  type:"DAX",     expr:"DIVIDE(\n  [Total Revenue] - CALCULATE([Total Revenue], SAMEPERIODLASTYEAR('orders_fact'[order_date])),\n  CALCULATE([Total Revenue], SAMEPERIODLASTYEAR('orders_fact'[order_date]))\n)", source:"Total Revenue", logic:"Defined in Power BI only", desc:"Year-on-year growth. Exists nowhere but this dataset, so it cannot be governed at the warehouse - the same exposure as the Tableau yoy_growth_pct field."},
  ],
  "Orders_Prep":[
    {kind:"Entity column", name:"order_id",   type:"Int64",    expr:"", source:"Snowflake_COMMERCE.order_id",   logic:"Passthrough", desc:"Order key carried through Power Query."},
    {kind:"Entity column", name:"revenue",    type:"Decimal",  expr:"", source:"Snowflake_COMMERCE.revenue",    logic:"Passthrough", desc:"Revenue, unchanged by the dataflow."},
    {kind:"Entity column", name:"region",     type:"Text",     expr:"", source:"Snowflake_COMMERCE.region",     logic:"Passthrough", desc:"Region, trimmed and upper-cased in Power Query."},
    {kind:"Entity column", name:"order_date", type:"Date",     expr:"", source:"Snowflake_COMMERCE.order_date", logic:"Passthrough", desc:"Order date, cast from timestamp."},
  ],
};

const POWERBI_PART_C = {Table:"#0891b2", Column:"#64748b", Measure:"#a855f7", "Entity column":"#0ea5e9"};

// Per-object properties and relationships.
const POWERBI_PROFILE = {
  "Finance_Insights":{props:[["Object type","Power BI App"],["Workspace","Finance_Analytics"],["Audience","Finance leadership (read-only)"],["Contents","1 dashboard · 1 report"],["Published","2h ago"]],
    rel:{contains:[{name:"Revenue_Overview",type:"Power BI Dashboard"},{name:"Revenue_Detail",type:"Power BI Report"}]}},
  "Finance_Analytics":{props:[["Object type","Power BI Workspace"],["Capacity","Premium P1"],["Permission boundary","Yes · workspace roles govern everything inside"],["Contents","1 dataset · 1 dataflow · 1 report · 1 dashboard · 1 datasource"]],
    rel:{contains:[{name:"Snowflake_COMMERCE",type:"Power BI Datasource"},{name:"Orders_Prep",type:"Power BI Dataflow"},{name:"Revenue_Model",type:"Power BI Dataset"},{name:"Revenue_Detail",type:"Power BI Report"},{name:"Revenue_Overview",type:"Power BI Dashboard"}]}},
  "Snowflake_COMMERCE":{props:[["Object type","Power BI Datasource"],["Connection type","Snowflake via on-premises gateway"],["Physical location","SNOWFLAKE_PROD / COMMERCE"],["Mode","Import"],["Last connected","40m ago"]],
    rel:{parent:{name:"Finance_Analytics",type:"Power BI Workspace"},upstream:[{name:"orders_fact",type:"Table"}],downstream:[{name:"Orders_Prep",type:"Power BI Dataflow"}]}},
  "Orders_Prep":{props:[["Object type","Power BI Dataflow"],["Power BI endorsement","Promoted"],["Refresh schedule","Every 4 hours · 02:00 UTC first run"],["Entities","1 (4 entity columns)"],["Storage","3.4 GB in the workspace"],["Last refresh","1h ago · success"]],
    rel:{parent:{name:"Finance_Analytics",type:"Power BI Workspace"},upstream:[{name:"Snowflake_COMMERCE",type:"Power BI Datasource"}],downstream:[{name:"Revenue_Model",type:"Power BI Dataset"}]}},
  "Revenue_Model":{props:[["Object type","Power BI Dataset"],["Power BI endorsement","Certified · by sarah.kim"],["Storage mode","Import"],["Refresh schedule","Every 4 hours"],["Parts","1 table · 3 columns · 2 DAX measures"],["Bound reports","1"],["Last refresh","1h ago · success"]],
    rel:{parent:{name:"Finance_Analytics",type:"Power BI Workspace"},upstream:[{name:"Orders_Prep",type:"Power BI Dataflow"}],downstream:[{name:"Revenue_Detail",type:"Power BI Report"},{name:"Revenue_KPI",type:"Power BI Tile"}]}},
  "Revenue_Detail":{props:[["Object type","Power BI Report"],["Power BI endorsement","Certified · by sarah.kim"],["Dataset","Revenue_Model"],["Pages","1"],["Views (30d)","1,840"],["Source","Open in Power BI \u2197"]],
    rel:{parent:{name:"Finance_Analytics",type:"Power BI Workspace"},upstream:[{name:"Revenue_Model",type:"Power BI Dataset"}],downstream:[{name:"Regional_Breakdown",type:"Power BI Page"}]}},
  "Regional_Breakdown":{props:[["Object type","Power BI Page"],["Report","Revenue_Detail"],["Visuals","4"],["Measures used","Total Revenue, YoY Growth %"],["Crawl note","Pages need workspace-level access · the scanner API alone does not catalog them"]],
    rel:{parent:{name:"Revenue_Detail",type:"Power BI Report"},upstream:[{name:"Revenue_Detail",type:"Power BI Report"}]}},
  "Revenue_Overview":{props:[["Object type","Power BI Dashboard"],["Workspace","Finance_Analytics"],["Tiles","1"],["Views (30d)","2,410"],["Source","Open in Power BI \u2197"]],
    rel:{parent:{name:"Finance_Analytics",type:"Power BI Workspace"},upstream:[{name:"Revenue_KPI",type:"Power BI Tile"}]}},
  "Revenue_KPI":{props:[["Object type","Power BI Tile"],["Dashboard","Revenue_Overview"],["Pinned from","Revenue_Model"],["Shows","Total Revenue"],["Visual","KPI card"]],
    rel:{parent:{name:"Revenue_Overview",type:"Power BI Dashboard"},upstream:[{name:"Revenue_Model",type:"Power BI Dataset"}],downstream:[{name:"Revenue_Overview",type:"Power BI Dashboard"}]}},
};

// Parts tab for a Power BI dataset or dataflow. Rows expand in place - a part is not a page.
const PowerBiPartsPanel = ({asset})=>{
  const parts=POWERBI_PARTS[asset.name]||[];
  const [open,setOpen]=useState(null);
  const [q,setQ]=useState("");
  const shown=parts.filter(p=>!q||p.name.toLowerCase().includes(q.toLowerCase()));
  return (
    <div className="fadeIn" style={{display:"flex",flexDirection:"column",gap:14}}>
      <Card2><div style={{padding:"12px 16px",display:"flex",alignItems:"center",gap:10}}>
        <svg width="15" height="15" viewBox="0 0 16 16" fill="none" style={{flexShrink:0,color:"#a855f7"}}><circle cx="8" cy="8" r="6.5" stroke="currentColor" strokeWidth="1.3"/><path d="M8 5v4M8 11h.01" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round"/></svg>
        <div style={{fontSize:12,color:T.textSub,lineHeight:1.55}}>
          Power BI holds these inside the {asset.type==="Power BI Dataflow"?"dataflow":"dataset"}, so they are its parts &mdash; the same
          kind of thing as a table&rsquo;s columns. Like columns they are not catalog assets. Select one for its detail.
        </div>
      </div></Card2>
      <Card2 style={{overflow:"hidden",padding:0}}>
        <div style={{padding:"12px 16px",borderBottom:`1px solid ${T.border}`,display:"flex",gap:12,alignItems:"center"}}>
          <input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search parts&hellip;"
            style={{flex:1,padding:"6px 10px",borderRadius:7,border:`1px solid ${T.border}`,background:T.bgElevated,color:T.text,fontSize:12,fontFamily:"inherit",outline:"none",boxSizing:"border-box"}}/>
          <span style={{fontSize:11,color:T.textMuted,whiteSpace:"nowrap"}}>{parts.length} parts · {parts.filter(p=>p.kind==="Measure").length} DAX measures</span>
        </div>
        <table style={{width:"100%",borderCollapse:"collapse"}}>
          <thead><tr style={{background:T.bgElevated}}>
            {["Part","Kind","Type","Definition","Description"].map(h=>(
              <th key={h} style={{padding:"8px 14px",textAlign:"left",fontSize:10,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:".06em",borderBottom:`1px solid ${T.border}`}}>{h}</th>
            ))}
          </tr></thead>
          <tbody>
            {shown.map((p,i)=>{
              const col=POWERBI_PART_C[p.kind]||T.textMuted;
              const isOpen=open===p.name;
              return (
                <React.Fragment key={p.name}>
                  <tr onClick={()=>setOpen(isOpen?null:p.name)} title={isOpen?"Hide detail":"Show detail"}
                    style={{cursor:"pointer",background:isOpen?T.bgHover:"transparent",borderBottom:(isOpen||i<shown.length-1)?`1px solid ${T.border}`:"none"}}>
                    <td style={{padding:"9px 14px",fontSize:12,fontFamily:"'Geist Mono',monospace",color:T.text,fontWeight:600}}>{p.name}</td>
                    <td style={{padding:"9px 14px"}}><span style={{fontSize:10,fontWeight:700,padding:"2px 8px",borderRadius:5,background:`${col}16`,color:col,border:`1px solid ${col}33`,whiteSpace:"nowrap"}}>{p.kind}</span></td>
                    <td style={{padding:"9px 14px",fontSize:11.5,color:T.textSub,fontFamily:"'Geist Mono',monospace"}}>{p.type}</td>
                    <td style={{padding:"9px 14px",fontSize:11,color:p.logic==="Passthrough"?T.textMuted:"#a855f7",fontWeight:p.logic==="Passthrough"?400:600}}>{p.logic}</td>
                    <td style={{padding:"9px 14px",fontSize:11.5,color:T.textSub,maxWidth:260}}>{p.desc}</td>
                  </tr>
                  {isOpen&&(
                    <tr><td colSpan={5} style={{padding:"12px 14px 14px",background:T.bgElevated,borderBottom:i<shown.length-1?`1px solid ${T.border}`:"none"}}>
                      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(160px,1fr))",gap:"10px 18px",marginBottom:p.expr?12:0}}>
                        {[["Kind",p.kind],["Type",p.type],["Definition",p.logic],["Source",p.source],[asset.type==="Power BI Dataflow"?"Dataflow":"Dataset",asset.name]].map(([k,v])=>(
                          <div key={k}>
                            <div style={{fontSize:9.5,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:".06em",marginBottom:3}}>{k}</div>
                            <div style={{fontSize:11.5,color:T.text,fontFamily:"'Geist Mono',monospace",wordBreak:"break-word"}}>{v}</div>
                          </div>
                        ))}
                      </div>
                      {p.expr&&(
                        <div>
                          <div style={{fontSize:9.5,fontWeight:700,color:"#a855f7",textTransform:"uppercase",letterSpacing:".06em",marginBottom:5}}>DAX — lives only in Power BI</div>
                          <pre style={{margin:0,padding:11,background:"#0f172a",color:"#e2e8f0",borderRadius:7,fontSize:11,fontFamily:"'Geist Mono',monospace",lineHeight:1.6,overflowX:"auto",whiteSpace:"pre"}}>{p.expr}</pre>
                        </div>
                      )}
                    </td></tr>
                  )}
                </React.Fragment>
              );
            })}
            {shown.length===0&&<tr><td colSpan={5} style={{padding:28,textAlign:"center",fontSize:12.5,color:T.textMuted}}>No parts match "{q}"</td></tr>}
          </tbody>
        </table>
      </Card2>
    </div>
  );
};

// Overview for any Power BI object.
const PowerBiOverview = ({asset,data,setData,onToast,onAsset})=>{
  const Pr=POWERBI_PROFILE[asset.name]||{props:[["Object type",asset.type],["Path",asset.db]],rel:{}};
  const rel=Pr.rel||{};
  const [editingDesc,setEditingDesc]=useState(false);
  const [descVal,setDescVal]=useState(data.description||asset.description||"");
  return (
  <div style={{display:"flex",flexDirection:"column",gap:16,maxWidth:900}}>
    <Card2><div style={{padding:"14px 16px"}}>
      <SH title="Description" sub="Synced from the Power BI description on every crawl"
        action={editingDesc
          ? <div style={{display:"flex",gap:6}}>
              <Btn small ghost onClick={()=>{setData(d=>({...d,description:descVal}));setEditingDesc(false);onToast&&onToast("Description saved","success");}}>Save</Btn>
              <Btn small ghost onClick={()=>{setDescVal(data.description||asset.description||"");setEditingDesc(false);}}>Cancel</Btn>
            </div>
          : <Btn small ghost icon={Ic.edit(11)} onClick={()=>setEditingDesc(true)}>Edit</Btn>}/>
      {editingDesc
        ? <textarea value={descVal} onChange={e=>setDescVal(e.target.value)} rows={3}
            style={{width:"100%",padding:10,borderRadius:8,border:`1px solid ${T.border}`,background:T.bgElevated,color:T.text,fontSize:12.5,fontFamily:"inherit",resize:"vertical",boxSizing:"border-box"}}/>
        : <div style={{fontSize:12.5,color:T.textSub,lineHeight:1.65}}>{data.description||asset.description}</div>}
    </div></Card2>

    <Card2><div style={{padding:"14px 16px"}}>
      <SH title="Properties"/>
      <DbtProps rows={Pr.props}/>
    </div></Card2>

    {/* Power BI's own endorsement is not EDG certification - both are shown, separately. */}
    {asset.pbiEndorsement&&(
      <Card2><div style={{padding:"14px 16px"}}>
        <SH title="Power BI endorsement" sub="Set in Power BI, ingested read-only. EDG certification is separate and lives in the rail."/>
        <div style={{display:"flex",alignItems:"center",gap:10}}>
          <span style={{fontSize:11,fontWeight:700,padding:"3px 10px",borderRadius:6,
            background:asset.pbiEndorsement==="Certified"?"rgba(22,163,74,.12)":"rgba(217,119,6,.12)",
            color:asset.pbiEndorsement==="Certified"?"#16a34a":"#d97706",
            border:`1px solid ${asset.pbiEndorsement==="Certified"?"#16a34a":"#d97706"}33`}}>{asset.pbiEndorsement}</span>
          <span style={{fontSize:12,color:T.textSub}}>
            {asset.pbiEndorsement==="Certified"
              ? "Marked Certified in Power BI \u2014 the tenant treats this as an approved, reusable source."
              : "Marked Promoted in Power BI \u2014 recommended by its owner, but not tenant-certified."}
          </span>
        </div>
      </div></Card2>
    )}

    {(rel.parent||rel.contains||rel.upstream||rel.downstream)&&(
      <Card2><div style={{padding:"14px 16px"}}>
        <SH title="Relationships" sub="Where this object sits in the Power BI hierarchy"/>
        {rel.parent&&<DbtRelRow name={rel.parent.name} type={rel.parent.type} rel="Parent" onAsset={onAsset}/>}
        {(rel.upstream||[]).map(r=><DbtRelRow key={r.name} name={r.name} type={r.type} rel="Upstream" onAsset={onAsset}/>)}
        {(rel.downstream||[]).map(r=><DbtRelRow key={r.name} name={r.name} type={r.type} rel="Downstream" onAsset={onAsset}/>)}
        {(rel.contains||[]).map(r=><DbtRelRow key={r.name} name={r.name} type={r.type} rel="Contains" onAsset={onAsset}/>)}
      </div></Card2>
    )}
  </div>
  );
};

// ===========================================================================
// dbt ASSET PROFILE - object-appropriate detail for every dbt object type.
// A dbt model is not a table: what matters is how it is materialized, what it
// refs, which tests guard it, when it last ran, and the SQL that defines it -
// raw (with Jinja) and compiled. Follows Atlan's dbt asset pages; the compiled/
// raw SQL pairing and description propagation come from OpenMetadata's dbt tab.
// ===========================================================================

