// Raw (Jinja) and compiled SQL for each dbt node. OpenMetadata surfaces exactly this pair.
const DBT_SQL = {
  "stg_customers":{
    raw:`{{ config(materialized='view') }}

select
    customer_id,
    lower(trim(email))                        as email,
    first_name || ' ' || last_name            as customer_name,
    segment,
    country
from {{ source('snowflake_raw', 'customers') }}
where customer_id is not null`,
    compiled:`create or replace view COMMERCE_STG.stg_customers as (
  select
      customer_id,
      lower(trim(email))                      as email,
      first_name || ' ' || last_name          as customer_name,
      segment,
      country
  from SNOWFLAKE_PROD.COMMERCE.customers
  where customer_id is not null
);`},
  "mart_order_summary":{
    raw:`{{ config(materialized='view', alias='vw_order_summary') }}

select
    f.order_id,
    f.customer_id,
    c.customer_name,
    p.product_id,
    f.revenue                                 as total_amount,
    round(o.discount / nullif(o.amount, 0) * 100, 2) as discount_pct,
    f.region,
    f.order_date
from {{ ref('fct_revenue') }} f
left join {{ ref('stg_customers') }} c on f.customer_id = c.customer_id
left join {{ ref('stg_orders') }}    o on f.order_id    = o.order_id
left join {{ source('snowflake_raw', 'dim_products') }} p on o.product_id = p.product_id`,
    compiled:`create or replace view SNOWFLAKE_PROD.COMMERCE.vw_order_summary as (
  select
      f.order_id,
      f.customer_id,
      c.customer_name,
      p.product_id,
      f.revenue                               as total_amount,
      round(o.discount / nullif(o.amount, 0) * 100, 2) as discount_pct,
      f.region,
      f.order_date
  from SNOWFLAKE_PROD.COMMERCE.orders_fact f
  left join COMMERCE_STG.stg_customers c on f.customer_id = c.customer_id
  left join COMMERCE_STG.stg_orders    o on f.order_id    = o.order_id
  left join SNOWFLAKE_PROD.COMMERCE.dim_products p on o.product_id = p.product_id
);`},
  "stg_orders":{
    raw:`{{ config(materialized='view') }}

with source as (
    select * from {{ source('snowflake_raw', 'orders') }}
)

select
    order_id,
    customer_id,
    amount,
    lower(status)             as status,
    created_at::date          as order_date,
    region
from source
where amount is not null`,
    compiled:`create or replace view COMMERCE_STG.stg_orders as (
  with source as (
      select * from postgresql_prod.PRODUCT.orders
  )
  select
      order_id,
      customer_id,
      amount,
      lower(status)           as status,
      created_at::date        as order_date,
      region
  from source
  where amount is not null
);`},
  "int_orders_enriched":{
    raw:`{{ config(
    materialized='incremental',
    unique_key='order_id',
    incremental_strategy='merge'
) }}

select
    o.order_id,
    o.customer_id,
    o.amount * 1.0            as gross_revenue,
    o.status,
    o.order_date,
    coalesce(c.region, o.region) as region,
    s.customer_tier
from {{ ref('stg_orders') }} o
left join {{ ref('customers_snapshot') }} s
    on o.customer_id = s.customer_id
   and s.valid_to is null
left join {{ ref('country_codes') }} c
    on o.region = c.country_code

{% if is_incremental() %}
where o.order_date >= (select max(order_date) from {{ this }})
{% endif %}`,
    compiled:`merge into COMMERCE_INT.int_orders_enriched as target
using (
  select
      o.order_id,
      o.customer_id,
      o.amount * 1.0          as gross_revenue,
      o.status,
      o.order_date,
      coalesce(c.region, o.region) as region,
      s.customer_tier
  from COMMERCE_STG.stg_orders o
  left join COMMERCE_SNAP.customers_snapshot s
      on o.customer_id = s.customer_id and s.valid_to is null
  left join REFERENCE.country_codes c
      on o.region = c.country_code
  where o.order_date >= (select max(order_date) from COMMERCE_INT.int_orders_enriched)
) as source
on target.order_id = source.order_id
when matched then update set ...
when not matched then insert ...;`},
  "fct_revenue":{
    raw:`{{ config(materialized='table', alias='orders_fact') }}

select
    order_id,
    customer_id,
    gross_revenue             as revenue,
    status                    as order_status,
    order_date,
    region
from {{ ref('int_orders_enriched') }}
where status != 'cancelled'`,
    compiled:`create or replace table SNOWFLAKE_PROD.COMMERCE.orders_fact as (
  select
      order_id,
      customer_id,
      gross_revenue           as revenue,
      status                  as order_status,
      order_date,
      region
  from COMMERCE_INT.int_orders_enriched
  where status != 'cancelled'
);`},
  "customers_snapshot":{
    raw:`{% snapshot customers_snapshot %}
{{ config(
    target_schema='COMMERCE_SNAP',
    unique_key='customer_id',
    strategy='timestamp',
    updated_at='updated_at'
) }}

select customer_id, customer_tier, updated_at
from {{ source('snowflake_raw', 'customers') }}
{% endsnapshot %}`,
    compiled:`-- dbt snapshot: type-2 merge into COMMERCE_SNAP.customers_snapshot
-- adds dbt_valid_from / dbt_valid_to on every change to updated_at`},
};

