// Left step rail — same shape as the Data Contract / Policy / Add-Connection rails
// (width 212, T.bg background, 8px dot = done), with a mode sub-label.
const KLStepRail = ({steps,cur,onPick,doneSet}) => (
  <div style={{width:212,flexShrink:0,borderRight:`1px solid ${T.border}`,overflowY:"auto",padding:"14px 10px",display:"flex",flexDirection:"column",gap:3,background:T.bg}}>
    {steps.map((s,i)=>{
      const on = i===cur, done = doneSet.has(i);
      return (
        <button key={s.t} onClick={()=>onPick(i)} style={{display:"flex",alignItems:"flex-start",gap:9,width:"100%",padding:"9px 11px",borderRadius:8,
          background:on?T.bgSurface:"transparent",border:`1px solid ${on?T.border:"transparent"}`,color:on?T.text:T.textMuted,
          fontSize:12.5,fontWeight:on?700:500,cursor:"pointer",textAlign:"left",fontFamily:"inherit",
          boxShadow:on?"0 1px 2px rgba(0,0,0,.06)":"none"}}>
          <span style={{width:8,height:8,borderRadius:"50%",flexShrink:0,marginTop:5,background:done?T.accent:T.borderLight}}/>
          <span style={{flex:1,minWidth:0}}>
            <span style={{display:"block"}}>{s.t}</span>
            <span style={{display:"block",fontSize:9.5,fontWeight:700,letterSpacing:"0.05em",textTransform:"uppercase",marginTop:3,
              color:s.decide===false?T.green:s.mode==="auto"?T.blue:T.textMuted}}>
              {s.decide===false ? "Automatic" : s.needs ? `${s.needs} waiting on you` : "Requires input"}
            </span>
          </span>
        </button>
      );
    })}
  </div>
);

// ── The Knowledge Layer's governed state lives OUTSIDE the view ──
// Decisions, certified terms, the trust dial and generated builds are governed objects, not
// screen state: they must survive a walk to the Glossary and back. Same module-store + subscribe
// pattern the policies, glossary and notification stores already use.
let _klState = {
  src: KL_SRC_SEED, x: KL_X_SEED, measures: KL_MEASURES, trust: KL_TRUST_DEFAULT, builds: {},
  layerHist: [{at:"2026-08-19 09:00", by:"alex.rivera", kind:"human", action:"Trust dial set",
    detail:"Entity match 0.90 · Column classification 0.85 · Business term 0.80 · review by default"}],
};
const _klStateSubs = new Set();
const klStoreSet = (patch)=>{
  _klState = {..._klState, ...(typeof patch==="function" ? patch(_klState) : patch)};
  _klStateSubs.forEach(f=>f());
};
const useKLStore = ()=>{
  const [,f] = useState(0);
  useEffect(()=>{ const fn=()=>f(n=>n+1); _klStateSubs.add(fn); return ()=>{_klStateSubs.delete(fn);}; },[]);
  return _klState;
};

// ═══════════════════════════════════════════════════════════════════════════
// THE STEWARD SURFACES
// One rule holds across all of them: the machine proposes and shows its work;
// a person decides; and the decision is written down with their name on it.
// ═══════════════════════════════════════════════════════════════════════════

// ── C1 · the audit trail, reachable from every governed object ──
const KLHistoryDrawer = ({open, onClose, title, kicker, entries}) => {
  if(!open) return null;
  return createPortal(
    <div onClick={onClose} className="fadeIn" style={{position:"fixed",inset:0,zIndex:1000,background:"rgba(0,0,0,.5)",backdropFilter:"blur(2px)"}}>
      <div onClick={e=>e.stopPropagation()} className="slideInRight"
        style={{position:"absolute",top:0,right:0,bottom:0,width:520,maxWidth:"96vw",background:T.bgSurface,
          borderLeft:`1px solid ${T.border}`,boxShadow:"-12px 0 48px rgba(0,0,0,.32)",display:"flex",flexDirection:"column"}}>
        <div style={{padding:"14px 20px",borderBottom:`1px solid ${T.border}`,display:"flex",alignItems:"center",justifyContent:"space-between",gap:12,flexShrink:0,background:T.bgElevated}}>
          <div style={{minWidth:0}}>
            <div style={{fontSize:10.5,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.07em"}}>{kicker||"Change history"}</div>
            <div style={{fontSize:14.5,fontWeight:700,color:T.text,marginTop:2}}>{title}</div>
          </div>
          <button onClick={onClose} style={{width:30,height:30,borderRadius:8,background:T.bgHover,border:`1px solid ${T.border}`,color:T.textMuted,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>{Ic.x(12)}</button>
        </div>
        <div style={{flex:1,overflowY:"auto",padding:"18px 22px"}}>
          <div style={{fontSize:12,color:T.textSub,lineHeight:1.65,marginBottom:16}}>
            Append-only. Nothing here is edited or removed, and a human decision is never
            overwritten by automation without a new entry recording it.
          </div>
          {(entries||[]).length===0
            ? <div style={{fontSize:12.5,color:T.textMuted}}>No changes recorded yet.</div>
            : (entries||[]).map((h,i)=>(
              <div key={i} style={{display:"flex",gap:11,paddingBottom:16,position:"relative"}}>
                <div style={{display:"flex",flexDirection:"column",alignItems:"center",flexShrink:0}}>
                  <span style={{width:9,height:9,borderRadius:"50%",marginTop:4,flexShrink:0,
                    background:h.kind==="ai"?T.violet:T.accent, border:`2px solid ${T.bgSurface}`,
                    boxShadow:`0 0 0 1.5px ${h.kind==="ai"?T.violet:T.accent}55`}}/>
                  {i<entries.length-1&&<span style={{flex:1,width:1.5,background:T.border,marginTop:3}}/>}
                </div>
                <div style={{minWidth:0,flex:1}}>
                  <div style={{display:"flex",alignItems:"center",gap:7,flexWrap:"wrap"}}>
                    <span style={{fontSize:12.6,fontWeight:700,color:T.text}}>{h.action}</span>
                    <span style={{fontSize:9.5,fontWeight:700,letterSpacing:"0.05em",textTransform:"uppercase",padding:"2px 6px",borderRadius:4,
                      background:h.kind==="ai"?T.violetDim:T.accentDim, color:h.kind==="ai"?T.violet:T.accent,
                      border:`1px solid ${(h.kind==="ai"?T.violet:T.accent)}33`}}>{h.kind==="ai"?"automation":"person"}</span>
                  </div>
                  <div style={{fontSize:11.8,color:T.textSub,lineHeight:1.6,marginTop:3}}>{h.detail}</div>
                  <div style={{fontSize:10.5,color:T.textMuted,marginTop:4,fontFamily:"'Geist Mono',monospace"}}>{h.by} · {h.at}</div>
                </div>
              </div>
            ))}
        </div>
      </div>
    </div>, document.body);
};

// ── C1 · the envelope, rendered the same way on every object ──
const KLEnvelope = ({env}) => {
  if(!env) return null;
  const isAi = env.by==="ai";
  return (
    <span style={{display:"inline-flex",alignItems:"center",gap:6,flexWrap:"wrap"}}>
      <span title={env.src} style={{display:"inline-flex",alignItems:"center",gap:5,fontSize:10.5,fontWeight:700,padding:"3px 8px",borderRadius:5,
        background:isAi?T.violetDim:T.accentDim, color:isAi?T.violet:T.accent, border:`1px solid ${(isAi?T.violet:T.accent)}33`}}>
        {isAi?"AI":"Steward"} · {env.src}
      </span>
      {env.conf!=null&&env.conf<1&&(
        <span style={{fontSize:10.5,fontWeight:700,padding:"3px 8px",borderRadius:5,fontFamily:"'Geist Mono',monospace",
          background:env.conf>=0.9?T.green+"1a":T.amber+"1a", color:env.conf>=0.9?T.green:T.amber,
          border:`1px solid ${(env.conf>=0.9?T.green:T.amber)}44`}}>{env.conf.toFixed(2)}</span>
      )}
    </span>
  );
};

// ── C5 · the trust dial ──
// The automation boundary, made explicit and tunable. One threshold per object type,
// because a match decision and a column classification are not equally expensive to get wrong.
const KLTrustDial = ({trust, setTrust, items, canApply, onRequest, onApply}) => {
  const [draft,setDraft] = useState(trust);
  const [open,setOpen]   = useState(false);
  useEffect(()=>{ setDraft(trust); },[trust]);
  const dirty = KL_TRUST_TYPES.some(t=>draft[t.k]!==trust[t.k]) || draft.posture!==trust.posture;
  const prev  = klDialPreview(items, draft.match);
  const now   = klDialPreview(items, trust.match);
  const delta = prev.auto - now.auto;
  return (
    <Card2 style={{padding:16,marginBottom:14}}>
      <SH title="Trust dial"
        sub="Above the threshold the resolver confirms and stamps itself as the decider. Below it, the decision waits for you."
        action={<Btn small ghost onClick={()=>setOpen(o=>!o)}>{open?"Hide":"Adjust"}</Btn>}/>
      <div style={{display:"flex",gap:9,flexWrap:"wrap",alignItems:"center"}}>
        {KL_TRUST_TYPES.map(t=>(
          <span key={t.k} title={t.d} style={{display:"inline-flex",alignItems:"center",gap:7,padding:"6px 11px",borderRadius:8,
            background:T.bgElevated,border:`1px solid ${T.border}`}}>
            <span style={{fontSize:11.5,color:T.textSub}}>{t.l}</span>
            <b style={{fontSize:12.5,color:T.text,fontFamily:"'Geist Mono',monospace"}}>{trust[t.k].toFixed(2)}</b>
          </span>
        ))}
        <span style={{display:"inline-flex",alignItems:"center",gap:7,padding:"6px 11px",borderRadius:8,
          background:T.bgElevated,border:`1px solid ${T.border}`}}>
          <span style={{fontSize:11.5,color:T.textSub}}>Default posture</span>
          <b style={{fontSize:12,color:trust.posture==="review"?T.amber:T.green}}>
            {trust.posture==="review"?"Review by default":"Approve by default"}</b>
        </span>
        {!canApply&&<span style={{fontSize:11,color:T.textMuted,marginLeft:"auto"}}>Changing the dial needs an admin or the layer owner.</span>}
      </div>

      {open&&(
        <div style={{marginTop:14,paddingTop:14,borderTop:`1px solid ${T.border}`}}>
          {KL_TRUST_TYPES.map(t=>(
            <div key={t.k} style={{display:"flex",alignItems:"center",gap:13,flexWrap:"wrap",marginBottom:11}}>
              <span style={{minWidth:170}}>
                <span style={{display:"block",fontSize:12.3,fontWeight:600,color:T.text}}>{t.l}</span>
                <span style={{display:"block",fontSize:10.8,color:T.textMuted,marginTop:1}}>{t.d}</span>
              </span>
              <input type="range" min="0.5" max="1" step="0.01" value={draft[t.k]}
                onChange={e=>setDraft(d=>({...d,[t.k]:parseFloat(e.target.value)}))}
                style={{flex:1,minWidth:170,accentColor:T.accent,cursor:"pointer"}}/>
              <b style={{fontSize:13,color:draft[t.k]!==trust[t.k]?T.accent:T.text,fontFamily:"'Geist Mono',monospace",minWidth:42,textAlign:"right"}}>
                {draft[t.k].toFixed(2)}</b>
            </div>
          ))}
          <div style={{display:"flex",alignItems:"center",gap:11,flexWrap:"wrap",marginTop:6,marginBottom:12}}>
            <span style={{fontSize:12.3,fontWeight:600,color:T.text,minWidth:170}}>Default posture</span>
            <select value={draft.posture} onChange={e=>setDraft(d=>({...d,posture:e.target.value}))}
              style={{padding:"6px 10px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:8,color:T.text,fontSize:12.5,cursor:"pointer"}}>
              <option value="review">Review by default — anything below the threshold waits for a person</option>
              <option value="approve">Approve by default — apply and notify, a person can still reverse it</option>
            </select>
          </div>

          {/* Forward preview — nothing is applied until it is applied. */}
          <div style={{display:"flex",gap:13,flexWrap:"wrap",alignItems:"center",padding:"11px 14px",borderRadius:9,
            background:dirty?T.accentDim:T.bgElevated, border:`1px solid ${dirty?T.accent+"44":T.border}`}}>
            <span style={{fontSize:12.4,color:T.textSub,lineHeight:1.6}}>
              At <b style={{color:T.text,fontFamily:"'Geist Mono',monospace"}}>{draft.match.toFixed(2)}</b> the resolver would
              auto-confirm <b style={{color:T.green,fontFamily:"'Geist Mono',monospace"}}>{prev.auto}</b> open decision{prev.auto===1?"":"s"}
              {" "}({klMoney(prev.autoMoney)}) and leave <b style={{color:T.amber,fontFamily:"'Geist Mono',monospace"}}>{prev.wait}</b> for you
              {" "}({klMoney(prev.waitMoney)}).
              {delta!==0&&<> That is <b style={{color:delta>0?T.amber:T.green}}>{delta>0?`${delta} more`:`${-delta} fewer`}</b> than today.</>}
            </span>
            <span style={{marginLeft:"auto",display:"flex",gap:7}}>
              <Btn small ghost onClick={()=>setDraft(trust)}>Reset</Btn>
              {canApply
                ? <Btn small variant="primary" disabled={!dirty} onClick={()=>{onApply(draft);setOpen(false);}}>Apply</Btn>
                : <Btn small variant="primary" disabled={!dirty} onClick={()=>{onRequest(draft);setOpen(false);}}>Send for approval</Btn>}
            </span>
          </div>
          <div style={{fontSize:11,color:T.textMuted,marginTop:9}}>
            Applying the dial changes governed state. The change is recorded in the audit trail with
            your name, the old value and the new one.
          </div>
        </div>
      )}
    </Card2>
  );
};

// ── C3 · one decision in the queue ──
// Rank, the money it governs, the evidence, the values that disagree, and the verbs.
// Everything a person needs to decide, without leaving the row.
const KLDecisionCard = ({it, rank, srcById, selected, onSelect, onVerb, onHistory, canCurate,
                        showGraph, onOpenGraph}) => {
  const [open,setOpen]   = useState(rank===1);
  const [why,setWhy]     = useState("");
  const [asking,setAsk]  = useState(null);   // which verb is collecting a reason
  const cls    = KL_CONF_CLASS[it.cls]||{l:it.cls,d:""};
  const done   = it.state!=="open";
  const fields = [...new Set((it.members||[]).flatMap(m=>Object.keys(m.vals||{})))];
  const differs = f => new Set((it.members||[]).map(m=>m.vals?.[f])).size>1;
  const th = {padding:"7px 11px",fontSize:10,fontWeight:700,color:T.textMuted,textAlign:"left",
              textTransform:"uppercase",letterSpacing:"0.06em",borderBottom:`1px solid ${T.border}`};
  const STATE_STYLE = {
    confirmed:{l:"Confirmed as one record", c:T.green},
    held:     {l:"Held for later",          c:T.amber},
    split:    {l:"Kept as separate records",c:T.blue},
    rejected: {l:"Rejected",                c:T.rose},
    single:   {l:"Accepted as single-source",c:T.blue},
    auto:     {l:"Auto-confirmed",          c:T.green},
  };
  const st = STATE_STYLE[it.state];
  const verb = (label, v, danger, needsReason) => (
    <Btn small ghost={!danger&&v!=="confirm"} variant={v==="confirm"?"primary":danger?"danger":undefined}
      onClick={()=>{ if(needsReason){ setAsk(v); } else { onVerb(it, v, null); } }}>{label}</Btn>
  );

  return (
    <Card2 style={{padding:0,marginBottom:10,opacity:done?0.72:1,
      borderColor:selected?T.accent+"66":done?T.border:T.border}}>
      <div style={{display:"flex",alignItems:"center",gap:12,flexWrap:"wrap",padding:"13px 15px",cursor:"pointer"}}
        onClick={()=>setOpen(o=>!o)}>
        {canCurate&&!done&&(
          <span onClick={e=>{e.stopPropagation();onSelect(it.id);}}
            style={{width:17,height:17,borderRadius:5,flexShrink:0,display:"flex",alignItems:"center",justifyContent:"center",
              fontSize:11,color:"#fff",background:selected?T.accent:"transparent",
              border:`1.5px solid ${selected?T.accent:T.borderLight}`}}>{selected?"✓":""}</span>
        )}
        <span style={{fontSize:10.5,fontWeight:800,color:T.textMuted,fontFamily:"'Geist Mono',monospace",minWidth:22}}>#{rank}</span>
        <span style={{minWidth:0,flex:"1 1 190px"}}>
          <span style={{display:"flex",alignItems:"center",gap:8,flexWrap:"wrap"}}>
            <b style={{fontSize:13.5,color:T.text}}>{it.name}</b>
            <KLChip kind="plain">{it.entity}</KLChip>
            {/* In the estate-wide queue the graph is the missing context: without it the list
                reads as a repeat of one graph's exceptions rather than a span across all of them. */}
            {showGraph&&(
              <button onClick={e=>{e.stopPropagation();onOpenGraph&&onOpenGraph(it.xgId);}}
                style={{display:"inline-flex",alignItems:"center",gap:5,fontSize:10.5,fontWeight:600,padding:"2px 8px",
                  borderRadius:5,cursor:"pointer",fontFamily:"inherit",
                  background:T.bgElevated,border:`1px solid ${T.border}`,color:T.textMuted}}>
                {Ic.knowledge(10)}{it.xgName}
              </button>
            )}
            {st&&<span style={{fontSize:10.5,fontWeight:700,padding:"2px 7px",borderRadius:5,background:st.c+"1a",color:st.c,border:`1px solid ${st.c}44`}}>{st.l}</span>}
          </span>
          <span style={{display:"block",fontSize:11.5,color:done?T.textMuted:T.amber,marginTop:3}}>{it.issue}</span>
        </span>
        {/* the money the decision governs — the whole reason this row is where it is */}
        <span style={{textAlign:"right",minWidth:104}}>
          <span style={{display:"block",fontSize:15,fontWeight:800,color:T.text,fontFamily:"'Geist Mono',monospace"}}>{klMoney(it.governs)}</span>
          <span style={{display:"block",fontSize:10,color:T.textMuted}}>across {it.apps} source{it.apps===1?"":"s"}</span>
        </span>
        <span title={cls.d} style={{display:"flex",flexDirection:"column",alignItems:"center",minWidth:66}}>
          <span style={{fontSize:12.5,fontWeight:800,fontFamily:"'Geist Mono',monospace",
            color:it.conf>=0.9?T.green:it.conf>=0.7?T.amber:T.rose}}>{it.conf.toFixed(2)}</span>
          <span style={{fontSize:9.5,color:T.textMuted,whiteSpace:"nowrap"}}>{cls.l}</span>
        </span>
        <span style={{color:T.textMuted,display:"flex",transform:open?"rotate(90deg)":"none",transition:"transform .15s"}}>{Ic.chevRight(12)}</span>
      </div>

      {open&&(
        <div style={{padding:"0 15px 14px",borderTop:`1px solid ${T.border}`}}>
          <div style={{display:"flex",gap:9,padding:"11px 13px",margin:"12px 0",borderRadius:9,
            background:T.bgElevated,border:`1px solid ${T.border}`,fontSize:12.2,color:T.textSub,lineHeight:1.65}}>
            <span style={{color:T.violet,display:"flex",flexShrink:0,marginTop:1}}>{Ic.bot(13)}</span>
            <div><b style={{color:T.text}}>Why the resolver is unsure.</b> {it.evidence}</div>
          </div>

          {fields.length>0&&(
            <div style={{overflowX:"auto",marginBottom:12}}>
              <table style={{width:"100%",borderCollapse:"collapse"}}>
                <thead><tr style={{background:T.bgElevated}}>
                  <th style={th}>Field</th>
                  {(it.members||[]).map(m=><th key={m.srcId+m.pk} style={th}>{srcById(m.srcId)?.name||m.srcId}</th>)}
                </tr></thead>
                <tbody>
                  {fields.map(f=>{
                    const bad = differs(f);
                    return (
                      <tr key={f}>
                        <td style={{padding:"8px 11px",fontSize:11.5,color:T.textSub,borderBottom:`1px solid ${T.border}`,whiteSpace:"nowrap"}}>{f}</td>
                        {(it.members||[]).map(m=>(
                          <td key={m.srcId+m.pk} style={{padding:"8px 11px",fontSize:11.5,borderBottom:`1px solid ${T.border}`,
                            fontFamily:"'Geist Mono',monospace", background:bad?T.amber+"14":"transparent",
                            color:bad?T.amber:T.textSub, fontWeight:bad?700:400}}>{m.vals?.[f]||"—"}</td>
                        ))}
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}

          <div style={{display:"flex",gap:6,flexWrap:"wrap",marginBottom:12}}>
            {(it.members||[]).map(m=>(
              <span key={m.srcId+m.pk} style={{display:"inline-flex",alignItems:"center",gap:6,fontSize:10.5,padding:"3px 8px",borderRadius:6,
                background:T.bgElevated,border:`1px solid ${T.border}`,color:T.textMuted}}>
                <ServiceIcon service={srcById(m.srcId)?.service} size={11}/>
                {srcById(m.srcId)?.opEntity||srcById(m.srcId)?.name} · {m.table} · {m.pk}
              </span>
            ))}
          </div>

          {done ? (
            <div style={{display:"flex",gap:10,alignItems:"center",flexWrap:"wrap",padding:"10px 13px",borderRadius:9,
              background:T.bgElevated,border:`1px solid ${T.border}`,fontSize:12,color:T.textSub}}>
              <span>Decided by <b style={{color:T.text}}>{it.decidedBy}</b> on {it.decidedAt}
                {it.reason?<> — “{it.reason}”</>:null}. This decision survives re-resolution.</span>
              <span style={{marginLeft:"auto",display:"flex",gap:6}}>
                <Btn small ghost onClick={()=>onHistory(it)}>History</Btn>
                {canCurate&&<Btn small ghost onClick={()=>onVerb(it,"reopen",null)}>Reopen</Btn>}
              </span>
            </div>
          ) : asking ? (
            <div style={{padding:"12px 13px",borderRadius:9,background:T.bgElevated,border:`1px solid ${T.amber}44`}}>
              <div style={{fontSize:11.5,fontWeight:700,color:T.text,marginBottom:7}}>
                {asking==="reject"?"Why is this not a match?":"Why are you keeping these separate?"}
              </div>
              <div style={{fontSize:11,color:T.textMuted,marginBottom:9,lineHeight:1.6}}>
                The reason is stored with the decision and, once the learning loop ships, stops this
                pair from ever being proposed again.
              </div>
              <Input2 value={why} onChange={e=>setWhy(e.target.value)} placeholder="e.g. two subsidiaries that legitimately share a filing ID"/>
              <div style={{display:"flex",gap:7,marginTop:10,justifyContent:"flex-end"}}>
                <Btn small ghost onClick={()=>{setAsk(null);setWhy("");}}>Cancel</Btn>
                <Btn small variant="primary" disabled={!why.trim()}
                  onClick={()=>{onVerb(it,asking,why.trim());setAsk(null);setWhy("");}}>Record decision</Btn>
              </div>
            </div>
          ) : canCurate ? (
            <div style={{display:"flex",gap:6,flexWrap:"wrap",alignItems:"center"}}>
              {it.kind==="conflict" ? (<>
                {verb("Confirm as one record","confirm")}
                {verb("Keep separate","split",false,true)}
                {verb("Hold","hold")}
                {verb("Not a match","reject",true,true)}
              </>) : (<>
                {verb("Accept as single-source","single")}
                {verb("Hold","hold")}
                {verb("Not a real entity","reject",true,true)}
              </>)}
              <span style={{marginLeft:"auto"}}><Btn small ghost onClick={()=>onHistory(it)}>History</Btn></span>
            </div>
          ) : (
            <div style={{fontSize:11.5,color:T.textMuted}}>
              Your role can review this decision but not make it. Curation verbs are open to stewards, owners and admins.
            </div>
          )}
        </div>
      )}
    </Card2>
  );
};

// ── C7 · certifying a measure ──
// The steward's verb is confirm-or-edit, never blank-form authoring: the definition and the
// per-application bindings arrive drafted, with the disagreement between sources made explicit.
const KLTermCard = ({m, srcById, onCertify, onPick, canCertify}) => {
  const [open,setOpen] = useState(m.state!=="certified");
  const certified = m.state==="certified";
  const bySrc = {};
  (m.bindings||[]).forEach(b=>{ (bySrc[b.srcId]=bySrc[b.srcId]||[]).push(b); });
  return (
    <Card2 style={{padding:0,marginBottom:10}}>
      <div onClick={()=>setOpen(o=>!o)} style={{display:"flex",alignItems:"center",gap:11,flexWrap:"wrap",padding:"13px 15px",cursor:"pointer"}}>
        <span style={{minWidth:0,flex:"1 1 200px"}}>
          <span style={{display:"flex",alignItems:"center",gap:8,flexWrap:"wrap"}}>
            <b style={{fontSize:13.5,color:T.text}}>{m.name}</b>
            <KLChip kind="plain">{m.entity}</KLChip>
            {certified
              ? <span style={{fontSize:10.5,fontWeight:700,padding:"2px 7px",borderRadius:5,background:T.green+"1a",color:T.green,border:`1px solid ${T.green}44`}}>Certified</span>
              : <span style={{fontSize:10.5,fontWeight:700,padding:"2px 7px",borderRadius:5,background:T.amber+"1a",color:T.amber,border:`1px solid ${T.amber}44`}}>Candidate</span>}
            {m.drafted==="ai"&&!certified&&(
              <span style={{fontSize:10.5,fontWeight:700,padding:"2px 7px",borderRadius:5,background:T.violetDim,color:T.violet,border:`1px solid ${T.violet}33`}}>
                AI-drafted · {m.conf.toFixed(2)}</span>)}
          </span>
          <span style={{display:"block",fontSize:11.5,color:T.textMuted,marginTop:3}}>
            {(m.bindings||[]).filter(b=>b.chosen).length} of {(m.bindings||[]).length} candidate sources chosen
            {certified?` · certified by ${m.certifiedBy} on ${m.certifiedAt}`:""}
          </span>
        </span>
        <span style={{color:T.textMuted,display:"flex",transform:open?"rotate(90deg)":"none",transition:"transform .15s"}}>{Ic.chevRight(12)}</span>
      </div>
      {open&&(
        <div style={{padding:"0 15px 14px",borderTop:`1px solid ${T.border}`}}>
          <div style={{fontSize:12.5,color:T.text,lineHeight:1.7,margin:"12px 0 4px"}}>{m.definition}</div>
          {m.note&&<div style={{fontSize:11.5,color:T.amber,lineHeight:1.6,marginBottom:10}}>{m.note}</div>}
          <div style={{display:"flex",gap:9,flexWrap:"wrap",marginBottom:12}}>
            <span style={{fontSize:11,color:T.textSub,padding:"5px 10px",borderRadius:7,background:T.bgElevated,border:`1px solid ${T.border}`}}>
              <b style={{color:T.text}}>Owner</b> · {m.owner}</span>
            <span style={{fontSize:11,color:T.textSub,padding:"5px 10px",borderRadius:7,background:T.bgElevated,border:`1px solid ${T.border}`}}>
              <b style={{color:T.text}}>Currency</b> · {m.currency}</span>
            <span style={{fontSize:11,color:T.textSub,padding:"5px 10px",borderRadius:7,background:T.bgElevated,border:`1px solid ${T.border}`}}>
              <b style={{color:T.text}}>Domain</b> · {m.domain}</span>
          </div>

          <div style={{fontSize:10.5,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.07em",marginBottom:7}}>
            Which source answers this, per application
          </div>
          {Object.keys(bySrc).map(sid=>{
            const g = srcById(sid);
            const many = bySrc[sid].length>1;
            return (
              <div key={sid} style={{marginBottom:9}}>
                <div style={{display:"flex",alignItems:"center",gap:7,marginBottom:5}}>
                  <ServiceIcon service={g?.service} size={14}/>
                  <span style={{fontSize:12,fontWeight:600,color:T.text}}>{g?.name||sid}</span>
                  {g?.opEntity&&<span style={{fontSize:10.5,color:T.textMuted}}>· {g.opEntity}</span>}
                  {many&&<span style={{fontSize:10.5,color:T.amber,fontWeight:600}}>· {bySrc[sid].length} candidate definitions disagree</span>}
                </div>
                {bySrc[sid].map((b,bi)=>(
                  <div key={bi} onClick={()=>!certified&&canCertify&&onPick(m.id,b)}
                    style={{display:"flex",gap:10,padding:"9px 11px",marginBottom:5,borderRadius:9,
                      cursor:(!certified&&canCertify)?"pointer":"default",
                      background:b.chosen?T.accentDim:T.bgSurface,
                      border:`1px solid ${b.chosen?T.accent+"55":T.border}`}}>
                    <span style={{width:14,height:14,borderRadius:"50%",flexShrink:0,marginTop:2,
                      border:`1.5px solid ${b.chosen?T.accent:T.borderLight}`,display:"flex",alignItems:"center",justifyContent:"center"}}>
                      {b.chosen&&<span style={{width:6,height:6,borderRadius:"50%",background:T.accent}}/>}
                    </span>
                    <span style={{minWidth:0}}>
                      <span style={{display:"block",fontSize:12.2,fontWeight:600,color:T.text}}>{b.label}</span>
                      <span style={{display:"block",fontSize:11,color:T.textSub,fontFamily:"'Geist Mono',monospace",marginTop:2}}>{b.expr}</span>
                      <span style={{display:"block",fontSize:11,color:T.textMuted,marginTop:3,lineHeight:1.55}}>{b.why}</span>
                    </span>
                  </div>
                ))}
              </div>
            );
          })}

          {!certified&&(
            <div style={{display:"flex",gap:9,alignItems:"center",flexWrap:"wrap",padding:"11px 13px",marginTop:6,borderRadius:9,
              background:T.bgElevated,border:`1px solid ${T.border}`}}>
              <span style={{fontSize:11.8,color:T.textSub,lineHeight:1.6}}>
                Certifying changes what the live answer engine returns, and compiles this definition into
                every generated build. It does not change any source system.
              </span>
              <span style={{marginLeft:"auto"}}>
                {canCertify
                  ? <Btn small variant="primary" onClick={()=>onCertify(m.id)}>Certify</Btn>
                  : <span style={{fontSize:11,color:T.textMuted}}>Stewards and owners certify.</span>}
              </span>
            </div>
          )}
        </div>
      )}
    </Card2>
  );
};

// ── C8 · Mode 2 — generate the governed build ──
// The build is a governed object, not a button: it is generated from the XKG, every artifact
// is traceable to the decision that produced it, and a governance change upstream produces a
// reviewed diff against the accepted baseline — never a destructive rebuild.
const KLBuildPane = ({xg, build, srcGraphs, measures, canApprove, canGenerate,
                      onGenerate, onApprove, onDiscard, onCustom, onDownload, onHistory}) => {
  const [intent,setIntent] = useState((build&&build.intent)||"bi");
  const [target,setTarget] = useState((build&&build.target)||"databricks");
  const [selFile,setSelFile] = useState(null);
  const [editing,setEditing] = useState(null);
  const [draft,setDraft]     = useState("");

  const files    = (build&&(build.proposed||build.baseline))||null;
  const isProposed = !!(build&&build.proposed);
  const diff     = isProposed ? klDiff(build.baseline, build.proposed) : null;
  const cur      = files && (files.find(f=>f.path===selFile) || files[0]);
  useEffect(()=>{ if(files && !files.some(f=>f.path===selFile)) setSelFile(files[0].path); },[build]);

  if(!build){
    const ir = klBuildIR(xg, srcGraphs, measures, {intent,target});
    return (
      <>
        <Card2 style={{padding:18,marginBottom:14}}>
          <SH title="Generate the governed build"
            sub="This graph is already the build spec. Generating turns it into readable pipeline code you own, with the governance compiled in."/>
          <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(230px,1fr))",gap:12,marginTop:4}}>
            <div>
              <div style={{fontSize:10.5,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.07em",marginBottom:7}}>
                What are you building this for?
              </div>
              {KL_INTENTS.map(o=>(
                <div key={o.k} onClick={()=>setIntent(o.k)}
                  style={{display:"flex",gap:9,padding:"9px 11px",marginBottom:5,cursor:"pointer",borderRadius:9,
                    background:intent===o.k?T.accentDim:T.bgElevated, border:`1px solid ${intent===o.k?T.accent+"55":T.border}`}}>
                  <span style={{width:14,height:14,borderRadius:"50%",flexShrink:0,marginTop:2,
                    border:`1.5px solid ${intent===o.k?T.accent:T.borderLight}`,display:"flex",alignItems:"center",justifyContent:"center"}}>
                    {intent===o.k&&<span style={{width:6,height:6,borderRadius:"50%",background:T.accent}}/>}</span>
                  <span><span style={{display:"block",fontSize:12.3,fontWeight:600,color:T.text}}>{o.l}</span>
                    <span style={{display:"block",fontSize:11,color:T.textMuted,marginTop:2}}>{o.d}</span></span>
                </div>
              ))}
              <div style={{fontSize:11,color:T.textMuted,marginTop:6}}>The shape is your call. We do not guess it.</div>
            </div>
            <div>
              <div style={{fontSize:10.5,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.07em",marginBottom:7}}>
                Where does it land?
              </div>
              {KL_TARGETS.map(o=>(
                <div key={o.k} onClick={()=>o.ready&&setTarget(o.k)}
                  style={{display:"flex",gap:9,padding:"9px 11px",marginBottom:5,cursor:o.ready?"pointer":"default",borderRadius:9,opacity:o.ready?1:.55,
                    background:target===o.k?T.accentDim:T.bgElevated, border:`1px solid ${target===o.k?T.accent+"55":T.border}`}}>
                  <span style={{width:14,height:14,borderRadius:"50%",flexShrink:0,marginTop:2,
                    border:`1.5px solid ${target===o.k?T.accent:T.borderLight}`,display:"flex",alignItems:"center",justifyContent:"center"}}>
                    {target===o.k&&<span style={{width:6,height:6,borderRadius:"50%",background:T.accent}}/>}</span>
                  <span><span style={{display:"block",fontSize:12.3,fontWeight:600,color:T.text}}>{o.l}{!o.ready&&" — planned"}</span>
                    <span style={{display:"block",fontSize:11,color:T.textMuted,marginTop:2}}>{o.d}</span></span>
                </div>
              ))}
              <div style={{fontSize:11,color:T.textMuted,marginTop:6}}>
                One intermediate representation, thin adapters. The same governed model lands anywhere.
              </div>
            </div>
          </div>
        </Card2>

        <Card2 style={{padding:18,marginBottom:14}}>
          <SH title="What will be compiled in" sub="Read from this graph — nothing here is typed by hand."/>
          <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(160px,1fr))",gap:12}}>
            <Metric label="Source systems"    value={String(ir.sources.length)} sub={ir.sources.map(s=>s.opEntity).filter(Boolean).join(" · ")}/>
            <Metric label="Auto-confirmed"    value={ir.autoApplied.toLocaleString()} color={T.green} sub="resolver decided"/>
            <Metric label="Steward-adjudicated" value={String(ir.crosswalk.filter(c=>c.status!=="open").length)} sub="named in the artifacts"/>
            <Metric label="Still open"        value={String(ir.crosswalk.filter(c=>c.status==="open").length)}
              color={ir.crosswalk.some(c=>c.status==="open")?T.amber:T.green} sub="ship as unresolved"/>
            <Metric label="Certified metrics" value={String(ir.metrics.length)}
              color={ir.metrics.length?T.green:T.textMuted} sub={ir.metrics.length?undefined:"certify a term first"}/>
          </div>
          {ir.metrics.length===0&&(
            <KLNote tone="quiet">
              No certified term covers <b>{xg.entity}</b> yet, so <b>metrics.yml</b> will generate empty.
              Certify one in the <b>Worklist › Terms</b> and regenerate — the diff will show exactly what changed.
            </KLNote>
          )}
          {ir.crosswalk.some(c=>c.status==="open")&&(
            <KLNote>
              {ir.crosswalk.filter(c=>c.status==="open").length} decisions are still open. They will be generated
              with status <b>open</b> and no decider — the build never pretends a decision was made.
            </KLNote>
          )}
        </Card2>

        <div style={{display:"flex",gap:9,alignItems:"center",flexWrap:"wrap"}}>
          {canGenerate
            ? <Btn variant="primary" small icon={Ic.workflow(12)} onClick={()=>onGenerate(intent,target)}>Generate governed build</Btn>
            : <span style={{fontSize:12,color:T.textMuted}}>Generating a build is open to data engineers, owners and admins.</span>}
          <span style={{fontSize:11.5,color:T.textMuted}}>Generation is itself an audited, governed act.</span>
        </div>
      </>
    );
  }

  return (
    <>
      {/* the regeneration diff — the make-or-break of the whole promise */}
      {isProposed&&(
        <Card2 style={{padding:16,marginBottom:14,background:T.amberDim,borderColor:T.amber+"55"}}>
          <SH title={diff.count===0?"Regenerated — nothing changed":`Proposed build · ${diff.count} artifact${diff.count===1?"":"s"} changed`}
            sub={diff.count===0
              ? "Governance has not moved since the accepted baseline, so this proposes nothing. Discard it."
              : "Reviewed diff against the accepted baseline. Your custom sections are already carried over."}/>
          {diff.count>0&&(
            <div style={{display:"flex",gap:6,flexWrap:"wrap",marginBottom:12}}>
              {diff.changed.map(f=><span key={f} onClick={()=>setSelFile(f)} style={{cursor:"pointer",fontSize:11,fontFamily:"'Geist Mono',monospace",padding:"4px 9px",borderRadius:6,background:T.amber+"1a",color:T.amber,border:`1px solid ${T.amber}44`}}>~ {f}</span>)}
              {diff.added.map(f=><span key={f} onClick={()=>setSelFile(f)} style={{cursor:"pointer",fontSize:11,fontFamily:"'Geist Mono',monospace",padding:"4px 9px",borderRadius:6,background:T.green+"1a",color:T.green,border:`1px solid ${T.green}44`}}>+ {f}</span>)}
              {diff.removed.map(f=><span key={f} style={{fontSize:11,fontFamily:"'Geist Mono',monospace",padding:"4px 9px",borderRadius:6,background:T.rose+"1a",color:T.rose,border:`1px solid ${T.rose}44`}}>− {f}</span>)}
            </div>
          )}
          {diff.count>0&&cur&&(()=>{
            const before = (build.baseline||[]).find(f=>f.path===cur.path);
            const ld = klLineDiff(before&&before.body, cur.body);
            if(!ld.added.length&&!ld.removed.length) return null;
            return (
              <div style={{background:T.bg,border:`1px solid ${T.border}`,borderRadius:9,padding:"10px 12px",marginBottom:12,overflowX:"auto"}}>
                <div style={{fontSize:10.5,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.06em",marginBottom:6}}>
                  {cur.path}
                </div>
                {ld.removed.map((l,i)=><div key={"r"+i} style={{fontSize:11,fontFamily:"'Geist Mono',monospace",color:T.rose,whiteSpace:"pre"}}>− {l}</div>)}
                {ld.added.map((l,i)=><div key={"a"+i} style={{fontSize:11,fontFamily:"'Geist Mono',monospace",color:T.green,whiteSpace:"pre"}}>+ {l}</div>)}
              </div>
            );
          })()}
          <div style={{display:"flex",gap:8,flexWrap:"wrap",alignItems:"center"}}>
            {/* Nothing changed means there is nothing to approve — bumping the baseline for a
                no-op would put a version in the trail that governs no decision. */}
            {diff.count===0
              ? <><Btn small variant="primary" onClick={onDiscard}>Dismiss</Btn>
                  <span style={{fontSize:11,color:T.textMuted}}>The accepted baseline already reflects current governance.</span></>
              : canApprove
              ? <><Btn small variant="primary" onClick={onApprove}>Approve — make this the new baseline</Btn>
                  <Btn small ghost onClick={onDiscard}>Discard — keep the baseline</Btn></>
              : <><Btn small variant="primary" onClick={onApprove}>Send for approval</Btn>
                  <Btn small ghost onClick={onDiscard}>Discard</Btn>
                  <span style={{fontSize:11,color:T.textMuted}}>Approving a build is the owner's or an admin's call.</span></>}
          </div>
        </Card2>
      )}

      <div style={{display:"flex",gap:12,flexWrap:"wrap",alignItems:"center",padding:"11px 14px",marginBottom:14,
        background:T.bgSurface,border:`1px solid ${T.border}`,borderRadius:10}}>
        <span style={{fontSize:12.4,color:T.textSub}}>
          Baseline <b style={{color:T.text}}>v{build.version}</b> · intent <b style={{color:T.text}}>{(KL_INTENTS.find(i=>i.k===build.intent)||{}).l}</b>
          {" · "}target <b style={{color:T.text}}>{(KL_TARGETS.find(t=>t.k===build.target)||{}).l}</b>
          {build.approvedBy?<> · accepted by <b style={{color:T.text}}>{build.approvedBy}</b> on {build.approvedAt}</>:null}
        </span>
        <span style={{marginLeft:"auto",display:"flex",gap:7,flexWrap:"wrap"}}>
          <Btn small ghost onClick={onHistory}>Build history</Btn>
          <Btn small ghost icon={Ic.copy(11)} onClick={onDownload}>Download</Btn>
          {canGenerate&&!isProposed&&<Btn small variant="primary" icon={Ic.refresh(11)} onClick={()=>onGenerate(build.intent,build.target)}>Regenerate</Btn>}
        </span>
      </div>

      {/* file rail + body — the artifacts are the product, so they get the room */}
      <div style={{display:"flex",gap:0,border:`1px solid ${T.border}`,borderRadius:10,overflow:"hidden",minHeight:430}}>
        <div style={{width:266,flexShrink:0,borderRight:`1px solid ${T.border}`,background:T.bg,overflowY:"auto",padding:"10px 8px"}}>
          {["staging","mart","seed","metrics","config","doc"].map(k=>{
            const group = files.filter(f=>f.kind===k);
            if(!group.length) return null;
            const LABEL = {staging:"Staging models",mart:"Marts",seed:"Seeds",metrics:"Metrics",config:"Project",doc:"Docs"};
            return (
              <div key={k} style={{marginBottom:9}}>
                <div style={{fontSize:9.5,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.07em",padding:"4px 8px"}}>{LABEL[k]}</div>
                {group.map(f=>{
                  const on = cur&&cur.path===f.path;
                  const ch = diff&&(diff.changed.includes(f.path)||diff.added.includes(f.path));
                  return (
                    <button key={f.path} onClick={()=>setSelFile(f.path)}
                      style={{display:"flex",alignItems:"center",gap:7,width:"100%",padding:"6px 8px",borderRadius:7,textAlign:"left",cursor:"pointer",
                        fontFamily:"'Geist Mono',monospace",fontSize:10.8,
                        background:on?T.bgSurface:"transparent",border:`1px solid ${on?T.border:"transparent"}`,
                        color:on?T.text:T.textMuted}}>
                      {ch&&<span style={{width:6,height:6,borderRadius:"50%",background:T.amber,flexShrink:0}}/>}
                      <span style={{overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{f.path.split("/").pop()}</span>
                    </button>
                  );
                })}
              </div>
            );
          })}
        </div>
        <div style={{flex:1,minWidth:0,display:"flex",flexDirection:"column"}}>
          <div style={{display:"flex",alignItems:"center",gap:9,padding:"9px 13px",borderBottom:`1px solid ${T.border}`,background:T.bgElevated,flexWrap:"wrap"}}>
            <span style={{fontSize:11.5,fontFamily:"'Geist Mono',monospace",color:T.textSub}}>{cur&&cur.path}</span>
            {cur&&cur.path.endsWith(".sql")&&canGenerate&&(
              <span style={{marginLeft:"auto"}}>
                <Btn small ghost icon={Ic.edit(11)} onClick={()=>{
                  setEditing(cur.path);
                  const b = cur.body.split(KL_CUSTOM_OPEN)[1];
                  const inner = b ? b.split(KL_CUSTOM_CLOSE)[0].trim() : "";
                  setDraft(inner.startsWith("-- (nothing yet")?"":inner);
                }}>Custom section</Btn>
              </span>
            )}
          </div>
          {editing===((cur&&cur.path)||null) && editing ? (
            <div style={{padding:14}}>
              <div style={{fontSize:12,color:T.textSub,lineHeight:1.65,marginBottom:9}}>
                Anything you write here is <b style={{color:T.text}}>carried into every future generation</b>.
                Everything above the marker is generated and will be rewritten.
              </div>
              <Input2 multiline rows={9} value={draft} onChange={e=>setDraft(e.target.value)}
                placeholder="-- your own SQL, joins, tests or comments"
                style={{fontFamily:"'Geist Mono',monospace",fontSize:11.5}}/>
              <div style={{display:"flex",gap:7,marginTop:10,justifyContent:"flex-end"}}>
                <Btn small ghost onClick={()=>setEditing(null)}>Cancel</Btn>
                <Btn small variant="primary" onClick={()=>{onCustom(editing,draft);setEditing(null);}}>Save custom section</Btn>
              </div>
            </div>
          ) : (
            <pre style={{flex:1,margin:0,padding:"13px 15px",overflow:"auto",background:T.bg,
              fontFamily:"'Geist Mono',monospace",fontSize:11.3,lineHeight:1.65,color:T.textSub,whiteSpace:"pre"}}>
              {(cur&&cur.body)||""}
            </pre>
          )}
        </div>
      </div>
      <KLNote tone="quiet">
        Honest boundary: this generates staging models, the conformed dimension, the decision-stamped
        crosswalk and metrics. Fact tables and load patterns (bulk, CDC, streaming) are the next phase.
      </KLNote>
    </>
  );
};

// Who can be named an owner or steward here. The same list the rest of the product uses.
const KL_PEOPLE = ["maya.chen","priya.nair","dev.patel","sarah.kim","alex.wu","lisa.ray","james.oh"];
const KL_DOMAINS = [...new Set(["Procurement","Sales","Finance","Supply Chain","HR",
  ...DOMAIN_LIST_DATA.map(d=>d.name)])];

const KnowledgeLayerView = ({onToast, onNav}) => {
  const klS = useKLStore();
  const srcGraphs = klS.src, xGraphs = klS.x, measures = klS.measures,
        trust = klS.trust, builds = klS.builds, layerHist = klS.layerHist;
  const setSrcGraphs = u => klStoreSet(st=>({src:      typeof u==="function"?u(st.src):u}));
  const setXGraphs   = u => klStoreSet(st=>({x:        typeof u==="function"?u(st.x):u}));
  const setMeasures  = u => klStoreSet(st=>({measures: typeof u==="function"?u(st.measures):u}));
  const setTrust     = u => klStoreSet(st=>({trust:    typeof u==="function"?u(st.trust):u}));
  const setBuilds    = u => klStoreSet(st=>({builds:   typeof u==="function"?u(st.builds):u}));
  const setLayerHist = u => klStoreSet(st=>({layerHist:typeof u==="function"?u(st.layerHist):u}));
  const [tab,       setTab]       = useState("overview");   // overview | sources | cross
  const [selSrc,    setSelSrc]    = useState(null);
  const [selX,      setSelX]      = useState(null);
  const [wiz,       setWiz]       = useState(null);          // null | "src" | "cross"
  const [step,      setStep]      = useState(0);
  const [doneSet,   setDoneSet]   = useState(()=>new Set());
  const [ai,        setAi]        = useState({});
  const [srcTab,    setSrcTab]    = useState("overview");
  const [xTab,      setXTab]      = useState("overview");
  const [scanFor,   setScanFor]   = useState(null);          // cross graph id awaiting scan consent
  const [scanMode,  setScanMode]  = useState("sample");
  // list controls
  const [sq,  setSq]  = useState(""); const [sStatus,setSStatus] = useState("all"); const [sSort,setSSort] = useState("name");
  const [xq,  setXq]  = useState(""); const [xStatus,setXStatus] = useState("all"); const [xSort,setXSort] = useState("name");
  // wizard choices
  const [wConn,     setWConn]     = useState(KL_UNMAPPED[0]);
  const [wEntity,   setWEntity]   = useState(KL_DEFAULT_ENTITY);
  const [wSrcIds,   setWSrcIds]   = useState(()=>KL_READY_FOR(KL_SRC_SEED, KL_DEFAULT_ENTITY));
  const [wScan,     setWScan]     = useState("later");        // later | sample | full
  const [wKeys,     setWKeys]     = useState([]);
  const [wBeliefs,  setWBeliefs]  = useState({});
  // Sources are chosen before anything else: which systems, then which of their imported
  // graphs. The entity comes after, on the stage where its match keys are, because the keys
  // belong to the entity and choosing one without seeing the other is guesswork.
  const [wSystems,  setWSystems]  = useState([]);
  const [wOwners,   setWOwners]   = useState([]);
  const [wStewards, setWStewards] = useState([]);
  const [wDomain,   setWDomain]   = useState("Procurement");
  const [wTags,     setWTags]     = useState([]);
  const [wTerms,    setWTerms]    = useState([]);

  // ── Who is looking, and what they may decide (C10 / §12.1) ──
  // Curation is the steward's job. Materialisation is the engineer's. The dial and the
  // acceptance of a build are the owner's or an admin's. Nobody is asked to sign off on
  // their own request — that is the whole point of routing it to the Inbox.
  const {role:klRole, roleCfg:klRoleCfg} = useRole();
  const me            = ((klRoleCfg&&klRoleCfg.email)||"you@jnj").split("@")[0];
  const isAdmin       = klRole==="admin";
  const canCurate     = isAdmin || klRole==="steward";
  const canDial       = isAdmin;
  const canGenerate   = isAdmin || klRole==="engineer";
  const canApproveFor = g => isAdmin || (g && g.owner===me);
  const [, setGTerms] = useGlossaryTerms();     // certifying a measure writes through to the Glossary

  // ── C1 · governed-object state ──
  const [hist,     setHist]     = useState(null); // {title, kicker, entries}
  // worklist controls
  const [wSub,  setWSub]  = useState("decisions");
  const [wq,    setWq]    = useState("");
  const [wKind, setWKind] = useState("all");
  const [wSel,  setWSel]  = useState(()=>new Set());

  const stamp = () => new Date().toISOString().slice(0,16).replace("T"," ");

  // Append-only. Every writer below goes through these two, so no verb can quietly skip the trail.
  const logX = (xgId, entry) =>
    setXGraphs(gs=>gs.map(x=>x.id===xgId?{...x, history:[{at:stamp(), by:me, ...entry}, ...(x.history||[])]}:x));
  const logS = (sgId, entry) =>
    setSrcGraphs(gs=>gs.map(g=>g.id===sgId?{...g, history:[{at:stamp(), by:me, ...entry}, ...(g.history||[])]}:g));

  // ── The curation verbs ──
  // confirm · split · hold · reject · single · reopen. Each one writes the state, the decider,
  // the timestamp and (where it matters) the reason — and the prior value is never discarded.
  const VERB_STATE = {confirm:"confirmed", split:"split", hold:"held", reject:"rejected", single:"single", reopen:"open"};
  const VERB_WORD  = {confirm:"Confirmed as one record", split:"Kept as separate records", hold:"Held for later",
                      reject:"Rejected — not a match", single:"Accepted as single-source", reopen:"Reopened"};
  const applyVerb = (it, verb, reason) => {
    const next = VERB_STATE[verb];
    const patch = r => r.id!==it.id ? r : (verb==="reopen"
      ? {...r, state:"open", decidedBy:null, decidedAt:null, reason:null}
      : {...r, state:next, decidedBy:me, decidedAt:stamp(), reason:reason||r.reason||null});
    setXGraphs(gs=>gs.map(x=>x.id!==it.xgId ? x : {
      ...x,
      conflicts:(x.conflicts||[]).map(patch),
      unmatched:(x.unmatched||[]).map(patch),
      history:[{at:stamp(), by:me, kind:"human", action:VERB_WORD[verb],
                detail:`${it.name} · ${klMoneyFull(it.governs)} governed · confidence ${it.conf.toFixed(2)}${reason?` — “${reason}”`:""}`},
               ...(x.history||[])],
    }));
    setWSel(s=>{ const n=new Set(s); n.delete(it.id); return n; });
    if(verb!=="reopen")
      pushNotif({category:"Knowledge Layer", type:"field_updated",
        title:`${VERB_WORD[verb]} · ${it.name}`,
        body:`${me} decided a ${klMoney(it.governs)} ${it.entity.toLowerCase()} match in ${it.xgName}`,
        nav:"knowledgelayer"});
    toast(`${VERB_WORD[verb]} — ${it.name}`);
  };

  // Bulk confirm is ONE transaction with ONE audit row, not N silent writes.
  const bulkConfirm = (items) => {
    if(!items.length) return;
    const ids = new Set(items.map(i=>i.id));
    const money = items.reduce((n,i)=>n+(i.governs||0),0);
    const byGraph = {};
    items.forEach(i=>{ (byGraph[i.xgId]=byGraph[i.xgId]||[]).push(i); });
    const patch = r => ids.has(r.id) ? {...r, state:"confirmed", decidedBy:me, decidedAt:stamp()} : r;
    setXGraphs(gs=>gs.map(x=>!byGraph[x.id] ? x : {
      ...x,
      conflicts:(x.conflicts||[]).map(patch),
      unmatched:(x.unmatched||[]).map(patch),
      history:[{at:stamp(), by:me, kind:"human", action:"Bulk confirm",
                detail:`${byGraph[x.id].length} decision${byGraph[x.id].length===1?"":"s"} confirmed in one transaction · ${klMoneyFull(byGraph[x.id].reduce((n,i)=>n+(i.governs||0),0))} governed`},
               ...(x.history||[])],
    }));
    setWSel(new Set());
    toast(`${items.length} decisions confirmed — ${klMoney(money)} governed`);
  };

  // ── Durable decisions across re-resolution (C1, normative) ──
  // The rehearsal, one level down, of the regeneration contract: re-running the resolver
  // must never cost a person the work they already did.
  const reResolve = (xgId) => {
    const x = xGraphs.find(g=>g.id===xgId); if(!x) return;
    const kept = klExceptions(x).filter(i=>i.state!=="open").length;
    logX(xgId, {kind:"ai", action:"Re-resolved",
      detail:`Matching re-run across ${x.srcIds.length} sources. ${kept} human decision${kept===1?"":"s"} preserved and re-applied; golden-record IDs unchanged, so the audit trail stayed attached.`});
    toast(kept
      ? `Re-resolved — ${kept} human decision${kept===1?"":"s"} preserved`
      : "Re-resolved — no human decisions to preserve yet");
  };

  // ── C5 · the dial ──
  const applyDial = (next, byWho, onBehalfOf) => {
    const who = byWho||me;
    const before = KL_TRUST_TYPES.map(t=>`${t.l} ${trust[t.k].toFixed(2)}`).join(" · ");
    const after  = KL_TRUST_TYPES.map(t=>`${t.l} ${next[t.k].toFixed(2)}`).join(" · ");
    setTrust(next);
    setLayerHist(h=>[{at:stamp(), by:who, kind:"human", action:"Trust dial changed",
      detail:`From ${before} (${trust.posture} by default) to ${after} (${next.posture} by default)`
             + (onBehalfOf&&onBehalfOf!==who ? ` — approved by ${who}, requested by ${onBehalfOf}` : "")}, ...h]);
    toast("Trust dial applied — the change is in the audit trail");
  };
  const requestDial = (next) => {
    requestKLApproval({kind:"dial", name:"Knowledge Layer", targetId:"layer", payload:next, requestedBy:me,
      body:`${me} proposes entity match ${next.match.toFixed(2)}, classification ${next.classify.toFixed(2)}, term ${next.term.toFixed(2)} — ${next.posture} by default. Applying the dial changes governed state.`});
    pushNotif({category:"Knowledge Layer", type:"alert", title:"Trust-dial change requested",
      body:`${me} proposed new thresholds — awaiting an admin`, nav:"knowledgelayer"});
    toast("Sent to the owner's Inbox for approval");
  };

  // ── C7 · certify a measure, and write through to the Glossary ──
  const pickBinding = (mId, binding) => setMeasures(ms=>ms.map(m=>m.id!==mId?m:{
    ...m, bindings:m.bindings.map(b=>b.srcId!==binding.srcId ? b : {...b, chosen:b===binding||b.label===binding.label})}));
  const certifyMeasure = (mId) => {
    const m = measures.find(x=>x.id===mId); if(!m) return;
    setMeasures(ms=>ms.map(x=>x.id!==mId?x:{...x, state:"certified", certifiedBy:me, certifiedAt:stamp().slice(0,10), conf:1}));
    // one certified definition, in the one glossary the rest of the product already reads
    setGTerms(p=>p.some(t=>t.term===m.name) ? p : [...p, {
      id:"t-kl-"+mId, term:m.name, abbr:"", glossary:"g1", category:"", domain:m.domain,
      owner:m.owner, steward:me, linked:(m.bindings||[]).filter(b=>b.chosen).length,
      cert:"Approved", status:"Approved", synonyms:[], definition:m.definition,
      relatedTerms:[], tags:[], refs:[], linkedAssets:[], readme:"",
      activity:[{user:me, avatar:(m.owner||me).slice(0,2).toUpperCase(),
                 action:"Certified from the Knowledge Layer", time:"Just now"}],
    }]);
    setLayerHist(h=>[{at:stamp(), by:me, kind:"human", action:"Term certified",
      detail:`${m.name} — canonical source chosen per application. Live answers and every generated build now use this one definition.`}, ...h]);
    pushNotif({category:"Knowledge Layer", type:"cert", title:`Term certified · ${m.name}`,
      body:`${me} certified this measure — live answers now use one definition`, nav:"glossary"});
    toast(`${m.name} certified — the Glossary and every generated build now agree`);
  };

  // ── C8 · Mode 2 ──
  const genBuild = (xgId, intent, target) => {
    const x = xGraphs.find(g=>g.id===xgId); if(!x) return;
    const prev = builds[xgId];
    const ir   = klBuildIR(x, srcGraphs, measures, {intent, target});
    const files= klCompile(ir, stamp(), (prev&&prev.customs)||{});
    if(!prev){
      setBuilds(b=>({...b,[xgId]:{baseline:files, proposed:null, customs:{}, intent, target,
        version:1, approvedBy:me, approvedAt:stamp().slice(0,10),
        history:[{at:stamp(), by:me, kind:"human", action:"Build generated",
          detail:`Baseline v1 · intent ${intent} · target ${target} · ${files.length} artifacts`}]}}));
      logX(xgId,{kind:"human", action:"Governed build generated",
        detail:`Baseline v1 compiled from this graph — ${files.length} artifacts, intent ${intent}, target ${target}`});
      toast("Governed build generated — this is your accepted baseline");
    } else {
      const d = klDiff(prev.baseline, files);
      setBuilds(b=>({...b,[xgId]:{...prev, proposed:files,
        history:[{at:stamp(), by:me, kind:"human", action:"Regenerated",
          detail:d.count?`${d.count} artifact${d.count===1?"":"s"} differ from the accepted baseline`:"Nothing changed — governance has not moved"}, ...prev.history]}}));
      toast(d.count ? `Regenerated — ${d.count} artifact${d.count===1?"":"s"} changed` : "Regenerated — nothing changed");
    }
  };
  const approveBuild = (xgId, _payload, byWho, onBehalfOf) => {
    const who = byWho||me;
    setBuilds(b=>{
      const cur = b[xgId]; if(!cur||!cur.proposed) return b;
      return {...b,[xgId]:{...cur, baseline:cur.proposed, proposed:null, version:cur.version+1,
        approvedBy:who, approvedAt:stamp().slice(0,10),
        history:[{at:stamp(), by:who, kind:"human", action:"Proposed build approved",
          detail:`v${cur.version+1} is now the accepted baseline. Custom sections carried forward.`
                 + (onBehalfOf&&onBehalfOf!==who ? ` Regenerated by ${onBehalfOf}, approved by ${who}.` : "")}, ...cur.history]}};
    });
    logX(xgId,{kind:"human", action:"Governed build approved", detail:"The proposed build became the accepted baseline"});
    toast("Approved — this is the new baseline");
  };
  const requestBuildApproval = (xgId) => {
    const x = xGraphs.find(g=>g.id===xgId);
    const d = klDiff(builds[xgId].baseline, builds[xgId].proposed);
    requestKLApproval({kind:"build", name:x.name, targetId:xgId, requestedBy:me,
      body:`${me} regenerated the governed build for ${x.name}. ${d.count} artifact${d.count===1?"":"s"} differ from the accepted baseline: ${[...d.changed,...d.added].join(", ")||"none"}.`});
    pushNotif({category:"Knowledge Layer", type:"alert", title:`Build approval requested · ${x.name}`,
      body:`${me} proposed a regenerated build — awaiting the owner`, nav:"knowledgelayer"});
    toast("Sent to the owner's Inbox for approval");
  };
  const discardBuild = (xgId) => {
    setBuilds(b=>{
      const cur = b[xgId]; if(!cur) return b;
      return {...b,[xgId]:{...cur, proposed:null,
        history:[{at:stamp(), by:me, kind:"human", action:"Proposed build discarded",
          detail:"The accepted baseline stands unchanged."}, ...cur.history]}};
    });
    toast("Discarded — the accepted baseline stands");
  };
  const saveCustom = (xgId, path, body) => {
    setBuilds(b=>{
      const cur = b[xgId]; if(!cur) return b;
      const customs = {...cur.customs, [path]:body};
      const files = (cur.proposed||cur.baseline).map(f=>{
        if(f.path!==path) return f;
        const head = f.body.split(KL_CUSTOM_OPEN)[0];
        return {...f, body: head + KL_CUSTOM_OPEN + "\n" + (body||"-- (nothing yet — use “Custom section” to add your own SQL here)") + "\n" + KL_CUSTOM_CLOSE + "\n"};
      });
      return {...b,[xgId]:{...cur, customs, ...(cur.proposed?{proposed:files}:{baseline:files}),
        history:[{at:stamp(), by:me, kind:"human", action:"Custom section saved",
          detail:`${path} — this block is now carried into every future generation`}, ...cur.history]}};
    });
    toast("Saved — your block will survive every regeneration");
  };
  const downloadBuild = (xgId) => {
    const cur = builds[xgId]; if(!cur) return;
    const files = cur.proposed||cur.baseline;
    const bundle = files.map(f=>`${"=".repeat(78)}\n${f.path}\n${"=".repeat(78)}\n${f.body}`).join("\n\n");
    const url = URL.createObjectURL(new Blob([bundle],{type:"text/plain"}));
    const a = document.createElement("a");
    a.href = url; a.download = `xkg_${klSlug((xGraphs.find(g=>g.id===xgId)||{}).entity||"build")}_build.txt`;
    document.body.appendChild(a); a.click(); a.remove(); URL.revokeObjectURL(url);
    toast(`${files.length} artifacts downloaded`);
  };

  // Inbox approvals write back into the layer through this bridge.
  useEffect(()=>{ registerKLApply({
    applyDial:(_id,payload,reqBy,approvedBy)=>applyDial(payload,approvedBy||reqBy,reqBy),
    approveBuild:(id,payload,reqBy,approvedBy)=>approveBuild(id,payload,approvedBy||reqBy,reqBy),
  }); },[trust,builds,xGraphs,measures]);

  // ── Derived, over the WHOLE estate — never over a loaded page ──
  const wlAll   = klWorklist(xGraphs);
  const wlOpen  = wlAll.filter(i=>i.state==="open");
  const ready   = klReadiness(xGraphs);
  const openMeasures = measures.filter(m=>m.state!=="certified");
  const wlFiltered = wlAll.filter(i=>{
    const q = wq.trim().toLowerCase();
    const hitQ = !q || [i.name,i.entity,i.xgName,i.issue].filter(Boolean).some(v=>String(v).toLowerCase().includes(q));
    const hitK = wKind==="all" ? i.state==="open"
               : wKind==="decided" ? i.state!=="open"
               : wKind==="conflict" ? (i.kind==="conflict"&&i.state==="open")
               : wKind==="unmatched" ? (i.kind==="unmatched"&&i.state==="open")
               : true;
    return hitQ && hitK;
  });
  const selItems = wlOpen.filter(i=>wSel.has(i.id));

  const srcById = id => srcGraphs.find(s=>s.id===id);
  const unmapped = KL_UNMAPPED.filter(c => !srcGraphs.some(g=>g.name===c));
  const steps   = wiz==="src" ? KL_SRC_STEPS : KL_X_STEPS;
  const aiKey   = `${wiz}-${step}`;
  const aiOn    = ai[aiKey] !== false;
  const toast   = m => onToast && onToast(m);

  // Candidate keys are the identifier concepts the source graphs agreed on, each carrying the
  // per-source column it binds to and how populated that column is. A concept present in only
  // one source is still listed, because being alone IS the reason it is a weak choice.
  const keyEvidence = (ids, entity) => klKeyEvidence(srcGraphs, ids, entity);
  const keyExclusions = (ids, entity) => klKeyExclusions(srcGraphs, ids, entity);
  const keyCounts = (ids, entity) => {
    const c = {};
    keyEvidence(ids, entity).forEach(e => { c[e.key] = e.sources.length; });
    return c;
  };
  const defaultKeys = (ids, entity) => {
    const c = keyCounts(ids, entity);
    const all = Object.keys(c).filter(k=>c[k]===ids.length);
    return all.length ? all : Object.keys(c);
  };
  const reseed = (ids, entity) => { setWSrcIds(ids); setWKeys(defaultKeys(ids, entity)); setWBeliefs({}); };
  // A cross-source graph is governed like any other asset, so it draws on the same
  // classification and glossary vocabularies the rest of EDG uses.
  const klTagNames  = (useTagCtx().tagDefs||[]).map(t=>t.name);
  const klTermNames = GLOSSARY_TERMS.map(t=>t.term);

  const totals = {
    published: srcGraphs.filter(s=>s.status==="Published").length,
    records:   xGraphs.reduce((n,x)=>n+x.records,0),
    review:    xGraphs.reduce((n,x)=>n+klOpen(x),0),
    drift:     srcGraphs.filter(s=>s.drift>0).length,
    proposed:  srcGraphs.reduce((n,s)=>n+s.bind.proposed,0),
    invented:  srcGraphs.reduce((n,s)=>n+s.bind.invented,0),
    tables:    srcGraphs.reduce((n,s)=>n+s.tables,0),
  };
  // Entity × source matrix — answers "what can we master next, and what is blocking it".
  const entityMatrix = KL_ENTITIES.map(e=>{
    const ready = KL_READY_FOR(srcGraphs, e);
    return {entity:e, ready, mastered: xGraphs.some(x=>x.entity===e)};
  });

  const openWizard = (kind, entity) => {
    setWiz(kind); setStep(0); setAi({}); setDoneSet(new Set()); setSelSrc(null); setSelX(null);
    if(kind==="cross"){
      // The entity the caller clicked wins. Falling straight through to "first entity with
      // two sources" meant every door opened on the same one, whichever was clicked.
      const e = entity || KL_ENTITIES.find(x=>KL_READY_FOR(srcGraphs,x).length>=2) || KL_ENTITIES[0];
      const ids = KL_READY_FOR(srcGraphs,e);
      setWEntity(e); reseed(ids, e); setWScan("later");
      setWSystems([...new Set(ids.map(i=>srcGraphs.find(g=>g.id===i)?.name).filter(Boolean))]);
      setWOwners([me]); setWStewards([]); setWDomain("Procurement"); setWTags([]); setWTerms([e]);
    } else {
      const free = KL_UNMAPPED.filter(c => !srcGraphs.some(g=>g.name===c));
      setWConn(free[0] || "");
    }
  };
  const closeWizard = () => { setWiz(null); setStep(0); setDoneSet(new Set()); };

  const openSrc = (id,t="overview") => { setHist(null); setSelSrc(id); setSelX(null); setSrcTab(t); };
  const openX   = (id,t="overview") => { setHist(null); setSelX(id); setSelSrc(null); setXTab(t); };
  // the history drawer is scoped to whatever you were looking at — leaving closes it
  useEffect(()=>{ setHist(null); },[tab, selSrc, selX]);

  // Graph builders live here, unconditionally — the profiles below return early, so a hook
  // declared inside one of those branches would change hook order between list and profile.
  // Stable identities also stop the canvas from rebuilding its node array every render.
  const sgSel  = selSrc ? srcById(selSrc) : null;
  const xgSel  = selX ? xGraphs.find(x=>x.id===selX) : null;
  const buildSrcGraph = useCallback(
    o => sgSel ? klBuildSourceGraph(sgSel,o) : {nodes:[],edges:[]}, [sgSel]);
  const buildXGraph = useCallback(
    o => xgSel ? klBuildCrossGraph(xgSel,srcGraphs,o) : {nodes:[],edges:[]},
    [xgSel,srcGraphs]);
  // A cross graph always opens at entity level; record level needs a completed data scan.
  const xScanned = xgSel?.scan?.state==="done";
  const runScan = (id,mode) => {
    setXGraphs(gs=>gs.map(x=>x.id===id
      ? {...x, scan:{state:"done", mode, at:"2026-08-24", rows:mode==="full"?184200:5000,
                     approvedBy:"alex.rivera", stale:false}}
      : x));
    setScanFor(null);
    toast(`Data scan queued (${mode}) — see Settings › Background Jobs`);
  };

  const finishSrc = () => {
    const id = "sg_"+wConn.toLowerCase().replace(/[^a-z0-9]+/g,"_");
    if(srcGraphs.some(g=>g.id===id)){ closeWizard(); setTab("sources"); openSrc(id); return; }
    setSrcGraphs(g=>[...g,{id, key:"SKG-"+(1004+g.length), name:wConn, service:wConn.toLowerCase().includes("sales")?"salesforce":"postgres",
      connection:wConn.toLowerCase().replace(/[^a-z0-9]+/g,"-"), domain:"Procurement",
      tables:214, cols:1642, words:100, entities:["Supplier","Customer"],
      drift:0, status:"Published", owner:me, stewards:[], from:"EDG", step:10,
      built:stamp().slice(0,10), version:"v1", opEntity:null,
      env:{by:"human", src:"EDG · Knowledge Layer builder", conf:1, state:"published"},
      history:[{at:stamp(), by:me, kind:"human", action:"Source graph published",
                detail:`Mapped from the ${wConn} connection`}],
      bind:{tags:38, termed:214, proposed:0, invented:0},
      masters:[{table:"SUPPLIER_MASTER", entity:"Supplier", keys:["Tax ID","Legal Name"], ready:true,
                rule:{pk:"SUPPLIER_ID", name:"SUPPLIER_NAME", tax:"TAX_ID", cls:"party", by:"ai:heuristic-v1.1", conf:0.86}},
               {table:"CUSTOMER_MASTER", entity:"Customer", keys:["Tax ID","Name"],       ready:true,
                rule:{pk:"CUSTOMER_ID", name:"CUSTOMER_NAME", tax:"TAX_ID", cls:"party", by:"ai:heuristic-v1.1", conf:0.84}}],
      assets:[{n:"SUPPLIER_MASTER", t:"Table", role:"master",      entity:"Supplier", term:"Supplier", cols:44, tags:["Tax ID","PII"]},
              {n:"CUSTOMER_MASTER", t:"Table", role:"master",      entity:"Customer", term:"Customer", cols:51, tags:["Tax ID","PII"]},
              {n:"ORDER_HEADER",    t:"Table", role:"transaction", term:"Purchase Order",              cols:38, tags:[]}],
      rels:[["ORDER_HEADER","SUPPLIER_MASTER","vendor"]]}]);
    closeWizard(); setTab("sources"); openSrc(id);
    toast(`Source Knowledge Graph published — ${wConn}`);
  };

  const finishCross = () => {
    const id = "xg_"+wEntity.toLowerCase().replace(/[^a-z0-9]+/g,"_")+"_"+xGraphs.length;
    const base = `${wEntity} Master`;
    const dupes = xGraphs.filter(x=>x.name===base||x.name.startsWith(base+" (")).length;
    const name = dupes ? `${base} (${dupes+1})` : base;
    const fallback = srcById(wSrcIds[0])?.name || "—";
    setXGraphs(g=>[...g,{id, key:"XKG-"+(2003+g.length), name, entity:wEntity, srcIds:[...wSrcIds],
      records:0, autoApplied:0, clean:0, owner:wOwners[0]||me, owners:[...wOwners], stewards:[...wStewards],
      status:"Published", tags:[...wTags], terms:[...wTerms],
      domain:wDomain, built:stamp().slice(0,10), version:"v1", policy:null,
      env:{by:"human", src:"EDG · Knowledge Layer builder", conf:1, state:"published"},
      conflicts:[], unmatched:[],
      history:[{at:stamp(), by:me, kind:"human", action:"Cross-source graph published",
                detail:`Entity ${wEntity} · ${wSrcIds.length} source graphs · match keys ${wKeys.join(", ")||"none"}`}],
      scan:{state:wScan==="later"?"none":"done", mode:wScan==="later"?null:wScan,
            at:wScan==="later"?null:"2026-08-24", rows:wScan==="full"?184200:wScan==="sample"?5000:0,
            approvedBy:wScan==="later"?null:"alex.rivera", stale:false},
      keys:[...wKeys],
      beliefs:[...wKeys,"Address"].map(f=>({f, s:wBeliefs[f] ?? fallback})),
      golden:[]}]);
    closeWizard(); setTab("cross"); openX(id);
    toast(`Cross-Source Knowledge Graph published — ${name}`);
  };

  // ══════════════ CREATE WIZARD (drawer + section rail) ══════════════
  const renderWizard = () => {
    const s = steps[step];
    const last = step===steps.length-1;
    const canAI = !!s.uses;
    const readySrc = srcGraphs.filter(g=>g.status==="Published");
    // A stage that completes on its own stays in the rail and stays inspectable, but the flow
    // does not stop and wait on it. "Next" jumps to the next stage that actually needs a person
    // and says where it is going, so nobody clicks through four screens that had nothing to ask.
    const needsInput = steps.map((x,i)=>x.decide!==false?i:-1).filter(i=>i>=0);
    const autoCount  = steps.length - needsInput.length;
    const nextInput  = needsInput.find(i=>i>step);
    // A scan reads rows, so every system in scope has to be connected in EDG before one
    // can be chosen. Publishing the model only needs no connection at all.
    const scanBlockers = wSrcIds.map(id=>srcById(id)).filter(g=>g&&g.srcConnected===false);
    const blocked = (wiz==="cross" && step===2 && (wOwners.length===0 || (wScan!=="later" && scanBlockers.length>0)))
                 || (wiz==="cross" && step===0 && wSrcIds.length<2)
                 || (wiz==="cross" && step===1 && wKeys.length===0)
                 || (wiz==="src" && !wConn);
    return createPortal(
      <div onClick={closeWizard} className="fadeIn" style={{position:"fixed",inset:0,zIndex:1000,background:"rgba(0,0,0,.5)",backdropFilter:"blur(2px)"}}>
        <div onClick={e=>e.stopPropagation()} className="slideInRight" style={{position:"absolute",top:0,right:0,bottom:0,width:880,maxWidth:"96vw",background:T.bgSurface,borderLeft:`1px solid ${T.border}`,boxShadow:"-12px 0 48px rgba(0,0,0,.32)",display:"flex",flexDirection:"column"}}>
          <div style={{padding:"14px 20px",borderBottom:`1px solid ${T.border}`,display:"flex",alignItems:"center",justifyContent:"space-between",gap:12,flexShrink:0,background:T.bgElevated}}>
            <div style={{minWidth:0}}>
              <div style={{fontSize:14.5,fontWeight:700,color:T.text}}>
                {wiz==="src"?"New Source Knowledge Graph":"New Cross-Source Knowledge Graph"}
              </div>
              <div style={{fontSize:11.5,color:T.textMuted,marginTop:2}}>
                {wiz==="src"
                  ? "Ten steps. Each one draws on vocabulary already governed in EDG"
                  : <>{wSrcIds.length} knowledge graph{wSrcIds.length===1?"":"s"}{step>0?<> · <span style={{fontFamily:"'Geist Mono',monospace",color:T.textSub}}>{wEntity}</span></>:null}</>}
              </div>
            </div>
            <button onClick={closeWizard} style={{width:30,height:30,borderRadius:8,background:T.bgHover,border:`1px solid ${T.border}`,color:T.textMuted,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>{Ic.x(12)}</button>
          </div>
          <div style={{flex:1,display:"flex",minHeight:0}}>
            <KLStepRail steps={steps} cur={step} onPick={setStep} doneSet={doneSet}/>
            <div style={{flex:1,overflowY:"auto",padding:"22px 26px"}}>
              <div style={{display:"flex",alignItems:"center",gap:10,flexWrap:"wrap",marginBottom:6}}>
                <div style={{fontSize:16,fontWeight:700,color:T.text}}>Stage {step+1} · {s.t}</div>
                <KLModeTag mode={s.mode}/>
                <div style={{marginLeft:"auto",display:"flex",alignItems:"center",gap:9}}>
                  {canAI ? (<>
                    <span style={{fontSize:11.5,fontWeight:700,color:T.violet}}>AI assist</span>
                    <Toggle on={aiOn} onChange={()=>setAi(a=>({...a,[aiKey]:!aiOn}))}/>
                    <span style={{fontSize:11.5,color:T.textSub,fontWeight:600,width:22}}>{aiOn?"On":"Off"}</span>
                  </>) : <span style={{fontSize:11.5,color:T.textMuted}}>Not applicable</span>}
                </div>
              </div>
              <div style={{display:"flex",gap:14,flexWrap:"wrap",marginBottom:10}}>
                <span style={{fontSize:11,fontWeight:700,color:s.uses?T.green:T.textMuted}}>
                  {s.uses ? `Reads: ${s.uses}` : "No governed inputs required"}
                </span>
                {s.writes && (
                  <span style={{fontSize:11,fontWeight:700,color:T.violet}}>Proposes into: {s.writes}</span>
                )}
              </div>
              {s.decide===false && (
                <div style={{display:"flex",gap:9,alignItems:"center",padding:"9px 12px",marginBottom:12,borderRadius:9,
                  background:T.green+"12",border:`1px solid ${T.green}33`,fontSize:12.2,color:T.textSub}}>
                  <span style={{color:T.green,fontWeight:700}}>&#10003;</span>
                  <div>Completed automatically. Shown so you can inspect it — nothing here is waiting on a decision.</div>
                </div>
              )}
              {s.edgNew && (
                <div style={{display:"flex",gap:9,alignItems:"baseline",padding:"9px 12px",marginBottom:12,borderRadius:9,
                  background:T.accentDim,border:`1px solid ${T.accent}33`,fontSize:12.2,color:T.text,lineHeight:1.6}}>
                  <b style={{whiteSpace:"nowrap"}}>New in EDG</b>
                  <div>The source builder has no equivalent stage. This is the one thing the catalog cannot
                    infer, and the only thing cross-source matching depends on.</div>
                </div>
              )}
              {(s.auto>0 || s.needs>0) && (
                <div style={{display:"flex",gap:18,flexWrap:"wrap",padding:"8px 12px",marginBottom:14,borderRadius:9,
                  background:T.bgElevated,border:`1px solid ${T.border}`,fontSize:11.8}}>
                  <span style={{color:T.textSub}}><b style={{color:T.green,fontFamily:"'Geist Mono',monospace"}}>{s.auto}</b> accepted automatically</span>
                  <span style={{color:T.textSub}}><b style={{color:s.needs?T.amber:T.green,fontFamily:"'Geist Mono',monospace"}}>{s.needs}</b> waiting on you</span>
                </div>
              )}
              <div style={{fontSize:12.8,color:T.textSub,lineHeight:1.65,maxWidth:760,marginBottom:16}}>{s.d}</div>

              {wiz==="src" && step===0 && (
                <div style={{maxWidth:560}}>
                  {unmapped.length===0 ? (
                    <div style={{padding:"18px 16px",borderRadius:9,background:T.bgElevated,border:`1px solid ${T.border}`,fontSize:12.5,color:T.textSub}}>
                      Every connected system already has a Source Knowledge Graph. Add a connection in
                      <b style={{color:T.text}}> Catalog › Connections</b> first, then come back here to map it.
                    </div>
                  ) : (<>
                    <div style={{fontSize:11.5,fontWeight:600,color:T.textSub,marginBottom:6}}>Connection</div>
                    <select value={wConn} onChange={e=>setWConn(e.target.value)}
                      style={{width:"100%",padding:"8px 10px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:8,color:T.text,fontSize:12.5,cursor:"pointer",marginBottom:14}}>
                      {unmapped.map(c=><option key={c} value={c}>{c}</option>)}
                    </select>
                    <KLRow nm="Scope"    chip="3 schemas · 214 tables" kind="exist" cf={aiOn?"Suggested by AI":"Selected manually"} acts="cc" onAct={()=>toast("Scope confirmed")}/>
                    <KLRow nm="Look for" chip="Supplier · Customer"    kind="exist" cf="From Business Entities" acts="cc" onAct={()=>toast("Entities confirmed")}/>
                  </>)}
                </div>
              )}

              {wiz==="cross" && step===0 && (()=>{
                const sysOpts   = [...new Set(srcGraphs.map(g=>g.name))];
                const sysGraphs = srcGraphs.filter(g=>wSystems.includes(g.name));
                const pickSys = v => {
                  setWSystems(v);
                  // Dropping a system drops its graphs with it, or the selection would keep
                  // a graph the user can no longer see.
                  const keep = srcGraphs.filter(g=>v.includes(g.name)).map(g=>g.id);
                  setWSrcIds(ids=>ids.filter(i=>keep.includes(i)));
                };
                return (
                <div style={{maxWidth:800}}>
                  <div style={{fontSize:11.5,fontWeight:600,color:T.textSub,marginBottom:6}}>Source systems</div>
                  <CatFieldDropdown label={null} placeholder="Select the systems to join…"
                    options={sysOpts} selected={wSystems} onChange={pickSys}/>
                  <div style={{fontSize:10.5,color:T.textMuted,marginTop:5,lineHeight:1.5}}>
                    Only systems with a knowledge graph imported from Data Sense appear here.
                  </div>

                  <div style={{fontSize:10.5,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.07em",margin:"18px 0 7px"}}>
                    Knowledge graphs to join
                  </div>
                  {wSystems.length===0
                    ? <div style={{fontSize:12,color:T.textMuted,padding:"12px 0"}}>Choose a system above to see its graphs.</div>
                    : sysGraphs.map(g=>{
                        const on = wSrcIds.includes(g.id);
                        const ok = g.status==="Published";
                        const ents = [...new Set((g.masters||[]).map(m=>m.entity))];
                        return (
                          <div key={g.id} onClick={()=>ok&&setWSrcIds(ids=>on?ids.filter(i=>i!==g.id):[...ids,g.id])}
                            style={{display:"flex",alignItems:"center",gap:11,flexWrap:"wrap",padding:"11px 12px",marginBottom:8,
                              cursor:ok?"pointer":"default",background:T.bgSurface,
                              border:`1px ${ok?"solid":"dashed"} ${on?T.accent+"66":T.border}`,borderRadius:9,opacity:ok?1:.55}}>
                            <span style={{width:17,height:17,borderRadius:5,flexShrink:0,display:"flex",alignItems:"center",justifyContent:"center",fontSize:11,color:"#fff",
                              background:on?T.accent:"transparent",border:`1.5px solid ${on?T.accent:T.borderLight}`}}>{on?"\u2713":""}</span>
                            <ServiceIcon service={g.service} size={16}/>
                            <span style={{fontSize:12.5,fontWeight:600,color:T.text,minWidth:118}}>{g.name}</span>
                            <span style={{fontSize:10.5,color:T.textMuted,fontFamily:"'Geist Mono',monospace"}}>{g.key} · {g.version}</span>
                            {ok
                              ? <span style={{fontSize:10.5,color:T.textMuted}}>{ents.join(" \u00b7 ")}</span>
                              : <KLChip kind="plain">Draft in Data Sense</KLChip>}
                            <span style={{fontSize:10.5,color:T.textMuted,marginLeft:"auto"}}>
                              {ok?`${g.tables} tables`:"Publish it in Data Sense to join it here"}
                            </span>
                          </div>
                        );
                      })}
                  <div style={{fontSize:11.5,color:wSrcIds.length>=2?T.textMuted:T.amber,marginTop:4}}>
                    {wSrcIds.length>=2
                      ? `${wSrcIds.length} knowledge graphs selected`
                      : "Select at least two. A single source cannot be cross-referenced."}
                  </div>
                </div>
                );
              })()}

              {wiz==="cross" && step===1 && (()=>{
                // Entities the CHOSEN graphs actually carry. Offering the full vocabulary here
                // would invite someone to pick one no selected graph describes.
                const offered = [...new Set(wSrcIds.flatMap(id=>(srcById(id)?.masters||[]).map(m=>m.entity)))];
                const opts    = offered.length ? offered : KL_ENTITIES;
                const readyIn = en => wSrcIds.filter(id=>{
                  const g = srcById(id); return g && g.masters.some(m=>m.entity===en && m.ready);
                }).length;
                const ev = keyEvidence(wSrcIds, wEntity);
                const ex = keyExclusions(wSrcIds, wEntity);
                const pickEntity = v => { setWEntity(v); setWKeys(defaultKeys(wSrcIds, v)); setWBeliefs({}); };
                return (
                  <div style={{maxWidth:760}}>
                    <div style={{fontSize:11.5,fontWeight:600,color:T.textSub,marginBottom:6}}>What to master</div>
                    <select value={wEntity} onChange={e=>pickEntity(e.target.value)}
                      style={{width:"100%",padding:"8px 10px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:8,color:T.text,fontSize:12.5,cursor:"pointer"}}>
                      {opts.map(c=>{
                        const n = readyIn(c);
                        return <option key={c} value={c}>{c}{n>=2?` \u00b7 ready in ${n} of ${wSrcIds.length}`:n===1?" \u00b7 ready in only 1 graph":" \u00b7 not ready in any"}</option>;
                      })}
                    </select>

                    {ev.length===0 ? (
                      <div style={{fontSize:12.5,color:T.amber,lineHeight:1.7,marginTop:16}}>
                        No identifier roles are confirmed for {wEntity} on the graphs you chose, so there is
                        nothing to match on. Declare them on the graph, not here.
                      </div>
                    ) : (
                    <>
                      <div style={{fontSize:10.5,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.07em",margin:"20px 0 4px"}}>
                        Match on
                      </div>
                      <div style={{fontSize:11.5,color:T.textMuted,marginBottom:9,lineHeight:1.5}}>
                        A key is a business concept bound to a different column in each system. Tick the ones to match on.
                      </div>
                      {/* One tick-able row per key. The affordance is the row, not a button at the
                          far right of it - selection was there before and nobody found it. */}
                      {ev.map(e=>{
                        const on = wKeys.includes(e.key);
                        const all = e.sources.length===wSrcIds.length;
                        const weak = e.minFill<80;
                        const role = KL_ID_ROLES[e.role]||{};
                        return (
                          <div key={e.key} onClick={()=>setWKeys(ks=>on?ks.filter(x=>x!==e.key):[...ks,e.key])}
                            style={{padding:"10px 12px",marginBottom:7,cursor:"pointer",background:on?T.accentDim:T.bgSurface,
                              border:`1px solid ${on?T.accent+"66":T.border}`,borderRadius:9}}>
                            <div style={{display:"flex",alignItems:"center",gap:10,flexWrap:"wrap"}}>
                              <span style={{width:16,height:16,borderRadius:4,flexShrink:0,display:"flex",alignItems:"center",justifyContent:"center",fontSize:10.5,color:"#fff",
                                background:on?T.accent:"transparent",border:`1.5px solid ${on?T.accent:T.borderLight}`}}>{on?"\u2713":""}</span>
                              <span style={{fontSize:12.5,fontWeight:700,color:T.text}}>{e.key}</span>
                              <span style={{fontSize:11,color:T.textMuted}}>{role.l} · {role.match} match</span>
                              {!all && <KLChip kind="new">In {e.sources.length} of {wSrcIds.length}</KLChip>}
                              <span style={{marginLeft:"auto",fontSize:11,fontWeight:700,fontFamily:"'Geist Mono',monospace",
                                color:weak?T.amber:T.green}}>{e.minFill}% at its weakest</span>
                            </div>
                            <div style={{fontSize:10.5,color:T.textMuted,marginTop:5,paddingLeft:26,lineHeight:1.5}}>
                              {e.sources.map(x=>`${x.src} ${x.col} ${x.fill}%`).join("  \u00b7  ")}
                              {weak && all && `  \u00b7  blank in ~${100-e.minFill}% of rows somewhere, so pair it with a second key`}
                              {!all && `  \u00b7  rows in the other source fall through to another key`}
                            </div>
                          </div>
                        );
                      })}
                      <div style={{fontSize:11.5,color:wKeys.length?T.textMuted:T.amber,marginTop:2}}>
                        {wKeys.length?`${wKeys.length} key${wKeys.length===1?"":"s"} selected`:"Select at least one key"}
                      </div>
                      {ex.length>0 && (
                        <div style={{fontSize:11,color:T.textMuted,marginTop:10,lineHeight:1.6}}>
                          <b style={{color:T.textSub}}>Held back:</b> {ex.map(x=>x.key).join(", ")} — valid inside one
                          system only, so matching on them would merge unrelated records. Change that on the graph.
                        </div>
                      )}

                      <div style={{fontSize:10.5,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.07em",margin:"22px 0 4px"}}>
                        When sources disagree
                      </div>
                      <div style={{fontSize:11.5,color:T.textMuted,marginBottom:9}}>
                        The one thing metadata cannot answer: which system do we believe.
                      </div>
                      {wKeys.length===0
                        ? <div style={{fontSize:12,color:T.textMuted}}>Select a key first — those are the fields that can disagree.</div>
                        : [...wKeys,"Address"].map(f=>{
                            const val = wBeliefs[f] ?? (srcById(wSrcIds[0])?.name||"");
                            return (
                              <div key={f} style={{display:"flex",alignItems:"center",gap:11,padding:"8px 12px",marginBottom:6,
                                background:T.bgSurface,border:`1px solid ${T.border}`,borderRadius:9}}>
                                <span style={{fontSize:12,fontWeight:600,color:T.text,minWidth:120}}>{f}</span>
                                <select value={val} onChange={e=>setWBeliefs(b=>({...b,[f]:e.target.value}))}
                                  style={{marginLeft:"auto",padding:"5px 9px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:7,color:T.text,fontSize:12,cursor:"pointer"}}>
                                  {wSrcIds.map(id=><option key={id} value={srcById(id)?.name}>{srcById(id)?.name}</option>)}
                                  <option value="Most recently updated">Most recently updated</option>
                                </select>
                              </div>
                            );
                          })}
                    </>)}
                  </div>
                );
              })()}

              {wiz==="cross" && step===2 && (
                <div style={{maxWidth:800}}>
                  {/* A cross-source graph is a governed asset like any other, so it is named,
                      owned, placed in a domain and given its business context here. */}
                  <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:13}}>
                    <div>
                      <label style={{display:"block",fontSize:11.5,fontWeight:600,color:T.textSub,marginBottom:6}}>Owners <span style={{color:"#ee2424"}}>*</span></label>
                      <CatFieldDropdown label={null} placeholder="Select owners…" options={KL_PEOPLE} selected={wOwners} onChange={setWOwners}/>
                      <div style={{fontSize:10.5,color:T.textMuted,marginTop:5}}>Accountable for the master. Approves merges above the trust threshold.</div>
                    </div>
                    <div>
                      <label style={{display:"block",fontSize:11.5,fontWeight:600,color:T.textSub,marginBottom:6}}>Stewards</label>
                      <CatFieldDropdown label={null} placeholder="Select stewards…" options={KL_PEOPLE} selected={wStewards} onChange={setWStewards}/>
                      <div style={{fontSize:10.5,color:T.textMuted,marginTop:5}}>Clear the exceptions the resolver holds back.</div>
                    </div>
                    <div>
                      <label style={{display:"block",fontSize:11.5,fontWeight:600,color:T.textSub,marginBottom:6}}>Domain</label>
                      <select value={wDomain} onChange={e=>setWDomain(e.target.value)}
                        style={{width:"100%",padding:"9px 11px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:8,color:T.text,fontSize:12.5,cursor:"pointer",boxSizing:"border-box"}}>
                        {KL_DOMAINS.map(d=><option key={d} value={d}>{d}</option>)}
                      </select>
                      <div style={{fontSize:10.5,color:T.textMuted,marginTop:5}}>Where this master rolls up for reporting and access.</div>
                    </div>
                    <div>
                      <label style={{display:"block",fontSize:11.5,fontWeight:600,color:T.textSub,marginBottom:6}}>Classifications</label>
                      <CatFieldDropdown label={null} placeholder="Select classifications…" options={klTagNames} selected={wTags} onChange={setWTags}/>
                      <div style={{fontSize:10.5,color:T.textMuted,marginTop:5}}>Policies already targeting these apply to the master automatically.</div>
                    </div>
                    <div style={{gridColumn:"1 / -1"}}>
                      <label style={{display:"block",fontSize:11.5,fontWeight:600,color:T.textSub,marginBottom:6}}>Glossary terms</label>
                      <CatFieldDropdown label={null} placeholder="Select terms…" options={klTermNames} selected={wTerms} onChange={setWTerms}/>
                      <div style={{fontSize:10.5,color:T.textMuted,marginTop:5}}>What this master means in business language. Certified terms carry their definition with them.</div>
                    </div>
                  </div>

                  <div style={{fontSize:10.5,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.07em",margin:"20px 0 7px"}}>
                    On publish
                  </div>
                  {[
                    {v:"later",  l:"Publish the model only (recommended)", d:"The governed entity-level graph. No data is read. Records can be resolved later."},
                    {v:"sample", l:"Scan a sample (5,000 rows per source)", d:"Validates matching with minimal data exposure."},
                    {v:"full",   l:"Scan all rows",                         d:"Complete records. Longer runtime, and reads every row including PII."},
                  ].map(o=>(
                    <div key={o.v} onClick={()=>setWScan(o.v)}
                      style={{display:"flex",gap:10,padding:"10px 12px",marginBottom:6,cursor:"pointer",borderRadius:9,
                        background:wScan===o.v?T.accentDim:T.bgSurface,
                        border:`1px solid ${wScan===o.v?T.accent+"55":T.border}`}}>
                      <span style={{width:15,height:15,borderRadius:"50%",flexShrink:0,marginTop:2,
                        border:`1.5px solid ${wScan===o.v?T.accent:T.borderLight}`,display:"flex",alignItems:"center",justifyContent:"center"}}>
                        {wScan===o.v&&<span style={{width:7,height:7,borderRadius:"50%",background:T.accent}}/>}
                      </span>
                      <span>
                        <span style={{display:"block",fontSize:12.5,fontWeight:600,color:T.text}}>{o.l}</span>
                        <span style={{display:"block",fontSize:11.5,color:T.textMuted,marginTop:2}}>{o.d}</span>
                      </span>
                    </div>
                  ))}
                  {/* The check that used to be asked at connect time, asked where it can
                      actually be answered: against the systems this master will read. */}
                  {wScan!=="later" && scanBlockers.length>0 && (
                    <div style={{display:"flex",gap:9,alignItems:"flex-start",padding:"11px 13px",marginTop:8,borderRadius:9,
                      background:T.amberDim,border:`1px solid ${T.amber}44`,fontSize:12,color:T.text,lineHeight:1.6}}>
                      <span style={{color:T.amber,display:"flex"}}><svg width="13" height="13" viewBox="0 0 16 16" fill="none" style={{flexShrink:0,marginTop:2}}><path d="M8 2.2l6 11.6H2L8 2.2z" stroke="currentColor" strokeWidth="1.3" strokeLinejoin="round"/><path d="M8 6.6v3.2M8 11.6v.5" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round"/></svg></span>
                      <div>
                        A scan reads rows, and {scanBlockers.map(g=>g.name).join(" and ")} {scanBlockers.length===1?"is":"are"} not
                        connected in EDG \u2014 the knowledge graph was imported, but the data behind it was not.
                        {" "}<b>Connect {scanBlockers.length===1?"it":"them"} first, or publish the model only.</b>
                      </div>
                    </div>
                  )}
                  {wScan!=="later" && scanBlockers.length===0 && (
                    <div style={{fontSize:11.5,color:T.textMuted,marginTop:8,lineHeight:1.6}}>
                      Reads {wSrcIds.map(id=>srcById(id)?.name).filter(Boolean).join(", ")} through their EDG connections.
                      Approved as <b style={{color:T.textSub}}>{me}</b>, run as a background job, recorded in the audit log.
                    </div>
                  )}
                </div>
              )}

              {wiz==="src" && step===6 && (()=>{
                const props = KL_ID_PROPOSAL[wConn] || [];
                if(!props.length) return (
                  <KLNote tone="quiet">Profiling has not proposed an entity for this connection yet. Complete
                    Profile &amp; Classify first, then return here.</KLNote>
                );
                return (
                  <div style={{maxWidth:900}}>
                    {props.map(ms=>{
                      const keys = klMatchKeys(ms), usable = klUsableKeys(ms);
                      const ex = klExcluded(ms).filter(c=>c.key), pol = klMasterPolicies(ms), con = klPolicyConflicts(ms);
                      const weakest = keys.map(k=>klFill(ms,k)).filter(v=>v!=null).sort((a,b)=>a-b)[0];
                      return (
                        <Card2 key={ms.table} style={{padding:15,marginBottom:12}}>
                          <div style={{display:"flex",alignItems:"center",gap:10,flexWrap:"wrap",marginBottom:12}}>
                            <span style={{fontSize:12.8,fontWeight:700,color:T.text,fontFamily:"'Geist Mono',monospace"}}>{ms.table}</span>
                            <span style={{color:T.textMuted}}>&rarr;</span>
                            <KLChip kind="exist">{ms.entity}</KLChip>
                            <span style={{marginLeft:"auto",fontSize:11,fontWeight:700,color:usable.length?T.green:T.amber}}>
                              {usable.length
                                ? `Matchable on ${usable.join(", ")}`
                                : "Not matchable across sources"}
                            </span>
                          </div>
                          <div style={{overflowX:"auto"}}>
                            <table style={{width:"100%",borderCollapse:"collapse"}}>
                              <thead><tr style={{background:T.bgElevated}}>
                                {["Column","Identifier role","Identifies","Populated","Distinct","Classification","Proposed from"].map(h=>(
                                  <th key={h} style={{padding:"7px 10px",fontSize:10,fontWeight:700,color:T.textMuted,textAlign:"left",
                                    textTransform:"uppercase",letterSpacing:"0.06em",borderBottom:`1px solid ${T.border}`,whiteSpace:"nowrap"}}>{h}</th>
                                ))}
                              </tr></thead>
                              <tbody>
                                {klIdCols(ms).map(c=>{
                                  const r = KL_ID_ROLES[c.role]||{};
                                  const ok = r.cross && c.key;
                                  const weak = c.fill!=null && c.fill<80;
                                  return (
                                    <tr key={c.c}>
                                      <td style={{padding:"8px 10px",fontSize:11.5,fontFamily:"'Geist Mono',monospace",color:T.text,borderBottom:`1px solid ${T.border}`,whiteSpace:"nowrap"}}>{c.c}</td>
                                      <td style={{padding:"8px 10px",borderBottom:`1px solid ${T.border}`}}>
                                        <select defaultValue={c.role} title={r.hint}
                                          onChange={e=>toast(`${c.c} set to ${(KL_ID_ROLES[e.target.value]||{}).l} — match keys recalculated`)}
                                          style={{padding:"3px 7px",borderRadius:6,background:T.bgElevated,border:`1px solid ${T.border}`,color:T.text,fontSize:11.5,cursor:"pointer",fontFamily:"inherit"}}>
                                          {Object.entries(KL_ID_ROLES).map(([k,v])=><option key={k} value={k}>{v.l}</option>)}
                                        </select>
                                      </td>
                                      <td style={{padding:"8px 10px",fontSize:11.5,borderBottom:`1px solid ${T.border}`,
                                        color:ok?T.green:T.textMuted,fontWeight:ok?600:400,whiteSpace:"nowrap"}}>{c.key||"—"}</td>
                                      <td style={{padding:"8px 10px",fontSize:11.5,borderBottom:`1px solid ${T.border}`,fontFamily:"'Geist Mono',monospace",
                                        color:weak?T.amber:T.textSub,fontWeight:weak?700:400}}>{c.fill!=null?c.fill+"%":"—"}</td>
                                      <td style={{padding:"8px 10px",fontSize:11.5,borderBottom:`1px solid ${T.border}`,fontFamily:"'Geist Mono',monospace",color:T.textSub}}>{c.distinct!=null?c.distinct+"%":"—"}</td>
                                      <td style={{padding:"8px 10px",fontSize:11.5,borderBottom:`1px solid ${T.border}`}}>
                                        {(c.cls||[]).length
                                          ? (c.cls||[]).map(t=><Badge key={t} bg={T.amber+"1a"} color={T.amber} border={T.amber+"44"}>{t}</Badge>)
                                          : <span style={{color:T.textMuted}}>none</span>}
                                      </td>
                                      <td style={{padding:"8px 10px",fontSize:10.5,borderBottom:`1px solid ${T.border}`,color:T.textMuted,whiteSpace:"nowrap"}}>
                                        {((KL_ID_SIGNALS.find(x=>x.k===c.by))||{}).l||"—"}
                                      </td>
                                    </tr>
                                  );
                                })}
                              </tbody>
                            </table>
                          </div>

                          {ex.length>0 && (
                            <div style={{marginTop:11,padding:"9px 12px",borderRadius:8,background:T.bgElevated,border:`1px solid ${T.border}`}}>
                              <div style={{fontSize:10,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.06em",marginBottom:5}}>
                                Held back from cross-source matching
                              </div>
                              {ex.map(c=>(
                                <div key={c.c} style={{fontSize:11.5,color:T.textSub,lineHeight:1.65}}>
                                  <b style={{color:T.text,fontFamily:"'Geist Mono',monospace"}}>{c.c}</b>
                                  <span style={{color:T.textMuted}}> as {c.key} &mdash; {c.why}</span>
                                </div>
                              ))}
                            </div>
                          )}

                          {pol.length>0 && (
                            <div style={{marginTop:9,fontSize:11.5,color:T.textSub,lineHeight:1.75}}>
                              <span style={{fontSize:10,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.06em"}}>Policies already governing these columns</span>
                              {pol.map(p=>(
                                <div key={p.name}>
                                  <b style={{color:T.text}}>{p.name}</b>
                                  <span style={{color:T.textMuted}}> on {p.cols.join(", ")} &mdash; {p.d}
                                    {p.resolverExempt && p.exempt ? ` ${p.exempt}.` : ""}</span>
                                </div>
                              ))}
                            </div>
                          )}

                          {con.map(c=>(
                            <div key={c.key} style={{display:"flex",gap:9,alignItems:"baseline",padding:"10px 12px",marginTop:9,borderRadius:9,
                              background:T.amberDim,border:`1px solid ${T.amber}44`,fontSize:12,color:T.text,lineHeight:1.65}}>
                              <b style={{color:T.amber,whiteSpace:"nowrap"}}>{c.key} blocked</b>
                              <div>{c.why}</div>
                            </div>
                          ))}

                          {weakest!=null && weakest<80 && (
                            <KLNote>The weakest key on this table is populated {weakest}% of the time. A key that is
                              blank will not match, and every row it misses arrives as an exception for someone to clear
                              by hand — so it is worth fixing here rather than in the worklist later.</KLNote>
                          )}
                        </Card2>
                      );
                    })}
                    <KLNote tone="quiet">A role is proposed from five signals: {KL_ID_SIGNALS.map(x=>x.l).join(" · ")}.
                      A classification is one of those signals, not the answer — a vendor code identifies a supplier
                      while carrying no classification at all, and a Tax ID classification says the column is sensitive,
                      not that it is safe to match on.</KLNote>
                  </div>
                );
              })()}

              {wiz==="src" && step===10 && (
                <div style={{maxWidth:780}}>
                  <KLRow nm="Owner"      chip="Alex Rivera" kind="exist" cf="Sign-off required"/>
                  <KLRow nm="Domain"     chip="Procurement" kind="exist" cf="From Domains" acts="cc" onAct={()=>toast("Domain confirmed")}/>
                  <KLRow nm="Available to" chip="Data Ask · AI copilot · Cross-source graphs" kind="plain" cf="After publishing"/>
                </div>
              )}

              {s.rows && (
                <div style={{maxWidth:860}}>
                  {s.rows.map(r=>(
                    <KLRow key={r.nm} {...r} cf={aiOn?r.cf:"Selected manually"} onAct={()=>toast("Confirmed")}/>
                  ))}
                </div>
              )}

              {canAI && !aiOn && (
                <KLNote tone="quiet">
                  <b style={{color:T.text}}>AI assist is off.</b> Select from your governed lists manually.
                  The available options are unchanged.
                </KLNote>
              )}
              {s.note && s.note[0] && <KLNote>{s.note[0]}</KLNote>}
            </div>
          </div>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"14px 20px",borderTop:`1px solid ${T.border}`,flexShrink:0,background:T.bgSurface}}>
            <Btn small ghost onClick={()=>step>0?setStep(step-1):closeWizard()}>{step>0?"← Back":"Cancel"}</Btn>
            <div style={{display:"flex",alignItems:"center",gap:10}}>
              {wiz==="cross" && step===0 && wSrcIds.length<2 && <span style={{fontSize:11,color:T.textMuted}}>Pick at least two knowledge graphs</span>}
              {wiz==="cross" && step===2 && wOwners.length===0 && <span style={{fontSize:11,color:T.textMuted}}>Name an owner</span>}
              {wiz==="cross" && step===1 && wKeys.length===0 && <span style={{fontSize:11,color:T.textMuted}}>Select at least one match key</span>}
              {wiz==="src" && !wConn && <span style={{fontSize:11,color:T.textMuted}}>No unmapped connection available</span>}
              <span style={{fontSize:11,color:T.textMuted}}>
                Stage {step+1} of {steps.length}{autoCount?` · ${autoCount} automatic`:""}
              </span>
              <Btn small variant="primary" disabled={blocked}
                onClick={()=>{
                  // every automatic stage we jump over is genuinely complete, so mark it done
                  const target = nextInput!=null ? nextInput : steps.length;
                  setDoneSet(d=>{ const n=new Set(d); for(let i=step;i<target;i++) n.add(i); return n; });
                  if(nextInput!=null) { setStep(nextInput); return; }
                  wiz==="src" ? finishSrc() : finishCross();
                }}>
                {nextInput!=null
                  ? (nextInput===step+1 ? "Next →" : `Next: ${steps[nextInput].t} →`)
                  : "Publish"}
              </Btn>
            </div>
          </div>
        </div>
      </div>,
      document.body
    );
  };

  // ══════════════ SOURCE GRAPH PROFILE ══════════════
  const sg = selSrc && srcById(selSrc);
  if(sg){
    const usedBy = xGraphs.filter(x=>x.srcIds.includes(sg.id));
    const ready  = sg.masters.filter(m=>m.ready).length;
    return (
      <div className="fadeUp" style={{height:"100%",display:"flex",flexDirection:"column"}}>
        <Topbar breadcrumb={[
          {label:"Knowledge Layer",onClick:()=>{setSelSrc(null);setTab("overview");}},
          {label:"Source Knowledge Graphs",onClick:()=>{setSelSrc(null);setTab("sources");}},
          {label:sg.name},
        ]} actions={<>
          <Btn ghost small icon={Ic.audit(12)} onClick={()=>setHist({title:sg.name, kicker:`Source Knowledge Graph · ${sg.key}`, entries:sg.history})}>History</Btn>
          <Btn ghost small icon={Ic.lineage(12)} onClick={()=>onNav&&onNav("catalog")}>Open in Lineage</Btn>
          <Btn ghost small icon={Ic.refresh(12)} onClick={()=>toast("Re-scan queued — see Settings › Background Jobs")}>Re-scan</Btn>
        </>}/>
        <div style={{flex:1,overflowY:"auto",padding:24}}>
          <KLProfileHead
            icon={<ServiceIcon service={sg.service} size={38}/>}
            kicker={`Source Knowledge Graph · ${sg.key}`}
            title={sg.name}
            badges={<>
              <Badge bg={sg.status==="Published"?T.green+"1a":T.amber+"1a"} color={sg.status==="Published"?T.green:T.amber} border={(sg.status==="Published"?T.green:T.amber)+"55"}>{sg.status}</Badge>
              <Badge bg={T.bgElevated} color={T.textSub} border={T.border}>{sg.version}</Badge>
              {sg.from==="EDG" && <Badge bg={T.accentDim} color={T.accent} border={T.accent+"44"}>built in EDG</Badge>}
              <KLEnvelope env={sg.env}/>
            </>}
            props={[
              {l:"Connection",   v:sg.connection},
              {l:"Serves",       v:sg.opEntity||"unmapped", c:sg.opEntity?T.text:T.amber},
              {l:"Domain",     v:sg.domain},
              {l:"Owner",      v:sg.owner},
              {l:"Tables",     v:sg.tables},
              {l:"Columns",    v:sg.cols},
              {l:"Entities",   v:`${ready} matchable`},
              {l:"Last built", v:sg.built},
              {l:"Freshness",  v:sg.drift>0?`${sg.drift} new columns`:"current", c:sg.drift>0?T.amber:T.green},
            ]}/>

          {sg.drift>0 && (
            <div style={{display:"flex",gap:9,alignItems:"center",padding:"11px 14px",marginBottom:16,borderRadius:9,
              background:T.amberDim,border:`1px solid ${T.amber}44`,fontSize:12.5,color:T.text}}>
              <span style={{color:T.amber,display:"flex"}}><svg width="13" height="13" viewBox="0 0 16 16" fill="none" style={{flexShrink:0,marginTop:1}}><path d="M8 2.2l6 11.6H2L8 2.2z" stroke="currentColor" strokeWidth="1.3" strokeLinejoin="round"/><path d="M8 6.6v3.2M8 11.6v.5" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round"/></svg></span>
              <div><b>Source schema has changed.</b> {sg.drift} column{sg.drift===1?"":"s"} added since this graph was last built. Dependent graphs may be out of date.</div>
              <Btn small variant="primary" onClick={()=>toast("Drift review opened in your Inbox")}>Review changes</Btn>
            </div>
          )}

          <Tabs2 tabs={[
            {key:"overview", label:"Overview"},
            {key:"graph",    label:"Knowledge Graph"},
            {key:"assets",   label:`Tables (${(sg.assets||[]).length})`},
            {key:"feeds",    label:`Used by (${usedBy.length})`},
          ]} active={srcTab} onChange={setSrcTab}/>

          {srcTab==="overview" && (
            <>
              <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(170px,1fr))",gap:12,marginBottom:18}}>
                <Metric label="Tables described" value={String(sg.tables)}/>
                <Metric label="Using EDG words"  value={sg.words+"%"} color={sg.words===100?T.green:T.amber}/>
                <Metric label="Labels invented"  value={String(sg.bind.invented)} color={T.green} sub="must stay zero"/>
                <Metric label="Awaiting approval" value={String(sg.bind.proposed)} color={sg.bind.proposed?T.amber:T.text}/>
                <Metric label="Feeds cross-source" value={String(usedBy.length)}/>
              </div>
              <div style={{display:"grid",gridTemplateColumns:"1.4fr 1fr",gap:14,alignItems:"start"}}>
                <Card2 style={{padding:16}}>
                  <SH title="Coverage" sub="What this graph describes, and how much of it is governed."/>
                  <KLRow nm="Business entities" chip={sg.entities.join(" · ")||"None"} kind={sg.entities.length?"exist":"plain"} cf="Available for cross-source matching"/>
                  <KLRow nm="Columns classified" chip={`${sg.cols} columns · ${sg.bind.tags} classifications`} kind="exist" cf="Classifications & Tags"/>
                  <KLRow nm="Tables given meaning" chip={`${sg.bind.termed} of ${sg.tables}`} kind="exist" cf="Business Glossary"/>
                  <KLRow nm="New terms proposed" chip={sg.bind.proposed?`${sg.bind.proposed} awaiting approval`:"None pending"} kind={sg.bind.proposed?"new":"exist"} cf="Standard glossary approval"/>
                  <div style={{marginTop:14,paddingTop:13,borderTop:`1px solid ${T.border}`,display:"flex",alignItems:"baseline",gap:12}}>
                    <div style={{fontSize:28,fontWeight:800,color:T.green,fontFamily:"'Geist Mono',monospace"}}>{sg.bind.invented}</div>
                    <div style={{fontSize:12,color:T.textSub}}>labels created outside EDG governance. Target: 0.<br/>
                      <span style={{color:T.textMuted}}>A non-zero value means this graph has introduced vocabulary EDG does not govern.</span></div>
                  </div>
                  <Btn ghost small style={{marginTop:12}} onClick={()=>setSrcTab("graph")}>Open knowledge graph</Btn>
                </Card2>
                <div style={{display:"flex",flexDirection:"column",gap:14,minWidth:0}}>
                <Card2 style={{padding:16}}>
                  <SH title="Resolution rules" sub="What makes each master matchable across sources."/>
                  {(sg.masters||[]).map(m=>(
                    <div key={m.table} style={{display:"flex",alignItems:"center",gap:9,flexWrap:"wrap",padding:"9px 0",borderBottom:`1px solid ${T.border}`}}>
                      <span style={{minWidth:0,flex:"1 1 120px"}}>
                        <b style={{display:"block",fontSize:12,color:T.text,fontFamily:"'Geist Mono',monospace"}}>{m.table}</b>
                        <span style={{display:"block",fontSize:10.5,color:T.textMuted,marginTop:1}}>{m.entity}</span>
                      </span>
                      {m.ready
                        ? <KLChip kind="exist">{m.keys.join(", ")}</KLChip>
                        : <KLChip kind="new">Not resolvable yet</KLChip>}
                      {m.rule
                        ? <span style={{fontSize:10,color:T.textMuted,fontFamily:"'Geist Mono',monospace"}}>{m.rule.by}</span>
                        : <Btn small ghost onClick={()=>toast(m.blocked
                            ? "Not generatable — see the reason on the Tables tab"
                            : "Rule generated — this master can now be matched")}>Generate rule</Btn>}
                    </div>
                  ))}
                  {(sg.masters||[]).some(m=>!m.ready)&&(
                    <KLNote tone="quiet">
                      A master with no rule is reported as <b>not resolvable, and why</b> — it is never
                      silently skipped. {(sg.masters||[]).filter(m=>!m.ready).length} here.
                    </KLNote>
                  )}
                </Card2>
                <Card2 style={{padding:16}}>
                  <SH title="Ownership"/>
                  <div style={{fontSize:12.5,color:T.textSub,lineHeight:2}}>
                    <div><b style={{color:T.text}}>Owner</b> · {sg.owner}</div>
                    <div><b style={{color:T.text}}>Stewards</b> · {sg.stewards.length?sg.stewards.join(", "):"None assigned"}</div>
                    <div><b style={{color:T.text}}>Domain</b> · {sg.domain}</div>
                    <div><b style={{color:T.text}}>Created in</b> · {sg.from}</div>
                    <div><b style={{color:T.text}}>Serves</b> · {sg.opEntity||"unmapped"}</div>
                  </div>
                </Card2>
                </div>
              </div>
            </>
          )}

          {srcTab==="graph" && (
            <KLGraphCanvas build={buildSrcGraph} height={540}
              emptyMsg="No tables mapped in this source graph yet."/>
          )}

          {srcTab==="assets" && (
            <DataTable
              cols={[
                {key:"n",     label:"Table / View", render:v=><span style={{fontWeight:600,fontFamily:"'Geist Mono',monospace"}}>{v}</span>},
                {key:"t",     label:"Type", render:v=><TypeBadge type={v}/>},
                {key:"role",  label:"Role", render:v=><span style={{fontSize:11.5,color:T.textSub,textTransform:"capitalize"}}>{v||"—"}</span>},
                {key:"entity",label:"Entity", render:v=>v?<KLChip kind="exist">{v}</KLChip>:<span style={{color:T.textMuted}}>—</span>},
                {key:"term",  label:"Business term", render:v=>v?<span style={{fontSize:11.5,color:T.green,fontWeight:600}}>{v}</span>:<span style={{color:T.textMuted}}>—</span>},
                {key:"cols",  label:"Columns", render:v=><span style={{fontFamily:"'Geist Mono',monospace",fontSize:11.5}}>{v}</span>},
                {key:"tags",  label:"Classifications", render:v=>v.length?<span style={{display:"flex",gap:4,flexWrap:"wrap"}}>{v.map(t=><Badge key={t} bg={T.amber+"1a"} color={T.amber} border={T.amber+"44"}>{t}</Badge>)}</span>:<span style={{color:T.textMuted}}>—</span>},
                {key:"n2",    label:"Match keys", render:(v,r)=>{
                  const m = sg.masters.find(x=>x.table===r.n);
                  if(!m) return <span style={{color:T.textMuted}}>—</span>;
                  return m.ready
                    ? <span style={{fontSize:11,color:T.green,fontWeight:600}}>{m.keys.join(", ")}</span>
                    : <span style={{fontSize:11,color:T.amber,fontWeight:600}}>None classified</span>;
                }},
              ]}
              rows={sg.assets||[]} emptyMsg="No tables mapped yet."/>
          )}

          {srcTab==="feeds" && (
            usedBy.length===0
              ? <KLEmpty icon={Ic.knowledge(34)} title="Not joined into a cross-source graph"
                  sub={`Join this graph with another published source that shares a business entity.`}
                  action={<Btn small variant="primary" onClick={()=>{setSelSrc(null);setTab("cross");openWizard("cross");}}>Create cross-source graph</Btn>}/>
              : <DataTable
                  cols={[
                    {key:"name",   label:"Cross-Source Graph", render:v=><span style={{fontWeight:600}}>{v}</span>},
                    {key:"entity", label:"Entity", render:v=><KLChip kind="exist">{v}</KLChip>},
                    {key:"records",label:"Trusted records", render:v=><span style={{fontFamily:"'Geist Mono',monospace"}}>{v.toLocaleString()}</span>},
                    {key:"srcIds", label:"Sources joined", render:v=><span style={{fontSize:11.5,color:T.textSub}}>{v.length}</span>},
                    {key:"owner",  label:"Owner", render:v=><span style={{fontSize:11.5,color:T.textSub}}>{v}</span>},
                  ]}
                  rows={usedBy} onRowClick={r=>openX(r.id)}/>
          )}
        </div>
        <KLHistoryDrawer open={!!hist} onClose={()=>setHist(null)}
          title={hist?.title} kicker={hist?.kicker} entries={hist?.entries}/>
      </div>
    );
  }

  // ══════════════ CROSS-SOURCE PROFILE ══════════════
  const xg = selX && xGraphs.find(x=>x.id===selX);
  if(xg){
    return (
      <div className="fadeUp" style={{height:"100%",display:"flex",flexDirection:"column"}}>
        <Topbar breadcrumb={[
          {label:"Knowledge Layer",onClick:()=>{setSelX(null);setTab("overview");}},
          {label:"Cross-Source Knowledge Graphs",onClick:()=>{setSelX(null);setTab("cross");}},
          {label:xg.name},
        ]} actions={<>
          <Btn ghost small icon={Ic.audit(12)} onClick={()=>setHist({title:xg.name, kicker:`Cross-Source Knowledge Graph · ${xg.key}`, entries:xg.history})}>History</Btn>
          <Btn ghost small icon={Ic.refresh(12)} onClick={()=>reResolve(xg.id)}>Re-resolve</Btn>
        </>}/>
        <div style={{flex:1,overflowY:"auto",padding:24}}>
          <KLProfileHead
            icon={<div style={{width:38,height:38,borderRadius:9,background:T.accentDim,border:`1px solid ${T.accent}33`,display:"flex",alignItems:"center",justifyContent:"center",color:T.accent,flexShrink:0}}>{Ic.knowledge(20)}</div>}
            kicker={`Cross-Source Knowledge Graph · ${xg.key}`}
            title={xg.name}
            badges={<>
              <Badge bg={T.green+"1a"} color={T.green} border={T.green+"55"}>{xg.status}</Badge>
              <Badge bg={T.bgElevated} color={T.textSub} border={T.border}>{xg.version}</Badge>
              {klOpen(xg)>0 && <Badge bg={T.amber+"1a"} color={T.amber} border={T.amber+"55"}>{klOpen(xg)} require review</Badge>}
              <KLEnvelope env={xg.env}/>
            </>}
            props={[
              {l:"Entity",          v:xg.entity},
              {l:"Built on",        v:`${xg.srcIds.length} source graphs`},
              {l:"Match keys",      v:xg.keys.length?xg.keys.join(", "):"—"},
              {l:"Data scan",       v:xScanned?(xg.scan.stale?"Out of date":`${xg.scan.mode==="full"?"All rows":"Sample"} · ${xg.scan.at}`):"Not run",
                                    c:xScanned?(xg.scan.stale?T.amber:T.green):T.textMuted},
              {l:"Trusted records", v:xScanned?xg.records.toLocaleString():"—",
                                    c:xScanned?T.text:T.textMuted},
              {l:"Owner",           v:xg.owner},
              {l:"Domain",          v:xg.domain},
              {l:"Policy",          v:xg.policy||"none"},
            ]}/>

          <Tabs2 tabs={[
            {key:"overview", label:"Overview"},
            {key:"graph",    label:"Knowledge Graph"},
            {key:"records",  label:klOpen(xg)?`Trusted records (${klOpen(xg)})`:"Trusted records"},
            {key:"rules",    label:"Rules"},
            // Mode 2 (generate the governed build) is parked. The scope is producing a
            // trustworthy master; materialising it into dbt/DLT comes after that is right.
            // KLBuildPane and its logic stay in place, reachable again by restoring this tab.
          ]} active={xTab} onChange={setXTab}/>

          {xTab==="build" && (
            <KLBuildPane xg={xg} build={builds[xg.id]} srcGraphs={srcGraphs} measures={measures}
              canGenerate={canGenerate} canApprove={canApproveFor(xg)}
              onGenerate={(intent,target)=>genBuild(xg.id,intent,target)}
              onApprove={()=>canApproveFor(xg)?approveBuild(xg.id):requestBuildApproval(xg.id)}
              onDiscard={()=>discardBuild(xg.id)}
              onCustom={(path,body)=>saveCustom(xg.id,path,body)}
              onDownload={()=>downloadBuild(xg.id)}
              onHistory={()=>setHist({title:xg.name, kicker:"Governed build · change history",
                                      entries:builds[xg.id]?.history||[]})}/>
          )}

          {xTab==="overview" && (
            <>
              <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(170px,1fr))",gap:12,marginBottom:18}}>
                <Metric label="Source graphs joined" value={String(xg.srcIds.length)}/>
                <Metric label="Match keys" value={String(xg.keys.length)} sub={xg.keys.join(", ")}/>
                <Metric label="Trusted records" value={xScanned?xg.records.toLocaleString():"—"}
                  sub={xScanned?undefined:"Requires a data scan"} color={xScanned?T.text:T.textMuted}/>
                <Metric label="Requires review" value={xScanned?String(klOpen(xg)):"—"}
                  sub={xScanned?`${(xg.clean||0).toLocaleString()} resolved without conflict`:undefined}
                  color={xScanned&&klOpen(xg)?T.amber:xScanned?T.green:T.textMuted}/>
              </div>

              {/* the metadata/data boundary, stated once, at the top of the profile */}
              <div style={{display:"flex",gap:10,alignItems:"center",padding:"12px 14px",marginBottom:14,borderRadius:10,
                background:xScanned?(xg.scan.stale?T.amberDim:T.bgSurface):T.bgElevated,
                border:`1px solid ${xScanned?(xg.scan.stale?T.amber+"44":T.border):T.border}`}}>
                <span style={{fontSize:15}}>{xScanned?(xg.scan.stale?"!":"✓"):"·"}</span>
                <div style={{fontSize:12.4,color:T.textSub,lineHeight:1.6}}>
                  {!xScanned && <>
                    <b style={{color:T.text}}>Model only.</b> This graph describes how {xg.entity} is represented in each
                    source, using metadata alone. Resolving individual records requires reading data, which needs an
                    approved data scan.
                  </>}
                  {xScanned && !xg.scan.stale && <>
                    <b style={{color:T.text}}>Records resolved.</b> {xg.scan.mode==="full"?"All rows":"Sample"} scan of{" "}
                    {xg.scan.rows.toLocaleString()} rows on {xg.scan.at}, approved by <b>{xg.scan.approvedBy}</b>.
                  </>}
                  {xScanned && xg.scan.stale && <>
                    <b style={{color:T.text}}>Records may be out of date.</b> A source has changed since the{" "}
                    {xg.scan.mode==="full"?"all rows":"sample"} scan on {xg.scan.at}. Re-scan to refresh them.
                  </>}
                </div>
                <div style={{marginLeft:"auto"}}>
                  <Btn small variant={xScanned&&!xg.scan.stale?undefined:"primary"} ghost={xScanned&&!xg.scan.stale}
                    onClick={()=>setScanFor(xg.id)}>{xScanned?"Re-scan":"Run data scan"}</Btn>
                </div>
              </div>
              <Card2 style={{padding:16,marginBottom:14}}>
                <SH title="Source graphs" sub="This graph reads only from the source graphs below."/>
                <div style={{display:"flex",gap:10,flexWrap:"wrap"}}>
                  {xg.srcIds.map(id=>{
                    const g=srcById(id); if(!g) return null;
                    return (
                      <button key={id} onClick={()=>openSrc(id)} style={{display:"flex",alignItems:"center",gap:9,padding:"10px 13px",borderRadius:9,cursor:"pointer",
                        background:T.bgElevated,border:`1px solid ${T.border}`,fontFamily:"inherit",textAlign:"left"}}>
                        <ServiceIcon service={g.service} size={18}/>
                        <span>
                          <span style={{display:"block",fontSize:12.5,fontWeight:600,color:T.text}}>{g.name}</span>
                          <span style={{display:"block",fontSize:10.5,color:T.textMuted}}>{g.masters.find(m=>m.entity===xg.entity)?.table||"—"}</span>
                        </span>
                      </button>
                    );
                  })}
                </div>
              </Card2>
              {xScanned && klOpen(xg)>0 && (()=>{
                const top = klExceptions(xg).filter(i=>i.state==="open").sort((a,b)=>klScore(b)-klScore(a));
                return (
                  <Card2 style={{padding:16}}>
                    <SH title={`Requires a decision (${top.length})`}
                      sub={`${klMoney(top.reduce((n,i)=>n+i.governs,0))} of ${xg.entity.toLowerCase()} spend is governed by decisions nobody has made yet.`}
                      action={<Btn small ghost onClick={()=>setXTab("records")}>Open Trusted records</Btn>}/>
                    {top.slice(0,3).map((it,i)=>(
                      <div key={it.id} onClick={()=>setXTab("records")}
                        style={{display:"flex",alignItems:"center",gap:12,flexWrap:"wrap",padding:"10px 12px",marginBottom:8,cursor:"pointer",
                          background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:9}}>
                        <span style={{fontSize:10.5,fontWeight:800,color:T.textMuted,fontFamily:"'Geist Mono',monospace"}}>#{i+1}</span>
                        <span style={{minWidth:0,flex:"1 1 150px"}}>
                          <b style={{display:"block",fontSize:12.5,color:T.text}}>{it.name}</b>
                          <span style={{display:"block",fontSize:11,color:T.amber,marginTop:2}}>{it.issue}</span>
                        </span>
                        <span style={{fontSize:13.5,fontWeight:800,color:T.text,fontFamily:"'Geist Mono',monospace"}}>{klMoney(it.governs)}</span>
                        <span style={{fontSize:11.5,fontWeight:700,fontFamily:"'Geist Mono',monospace",
                          color:it.conf>=0.9?T.green:it.conf>=0.7?T.amber:T.rose}}>{it.conf.toFixed(2)}</span>
                      </div>
                    ))}
                    {top.length>3&&<div style={{fontSize:11.5,color:T.textMuted}}>and {top.length-3} more, ranked the same way.</div>}
                  </Card2>
                );
              })()}
            </>
          )}

          {xTab==="graph" && (
            <>
              <div style={{display:"flex",gap:9,alignItems:"center",padding:"10px 13px",marginBottom:10,borderRadius:9,
                background:T.bgElevated,border:`1px solid ${T.border}`,fontSize:12.3,color:T.textSub}}>
                <span style={{color:T.textMuted,display:"flex"}}><svg width="13" height="13" viewBox="0 0 16 16" fill="none" style={{flexShrink:0,marginTop:1}}><circle cx="8" cy="8" r="6.2" stroke="currentColor" strokeWidth="1.3"/><path d="M8 7.2v4M8 4.9v.6" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round"/></svg></span>
                <div>Shows how <b style={{color:T.text}}>{xg.entity}</b> is represented in each source and the match keys that
                  link them. Individual records are listed under <b style={{color:T.text}}>Trusted records</b>.</div>
                <Btn small ghost onClick={()=>setXTab("records")}>Trusted records →</Btn>
              </div>
              <KLGraphCanvas build={buildXGraph} height={560}
                emptyMsg="Nothing to draw — this graph has no source graphs joined yet."/>
            </>
          )}

          {xTab==="records" && !xScanned && (
            <KLEmpty icon={Ic.shield(34)} title="No data scan has been run"
              sub={`This graph describes how ${xg.entity} maps across ${xg.srcIds.length} sources. Resolving individual records requires reading data.`}
              action={<Btn small variant="primary" onClick={()=>setScanFor(xg.id)}>Run data scan</Btn>}/>
          )}

          {xTab==="records" && xScanned && (()=>{
            // Object-scoped view of the SAME decisions the Worklist ranks globally, rendered by
            // the same component — so a verb, its evidence and its audit trail behave identically
            // wherever a steward happens to be standing.
            const ex   = klExceptions(xg).sort((a,b)=>klScore(b)-klScore(a));
            const open = ex.filter(i=>i.state==="open");
            const done = ex.filter(i=>i.state!=="open");
            return (
              <>
                {/* the point of this tab: almost everything is fine — here is what is not */}
                <div style={{display:"flex",gap:14,flexWrap:"wrap",alignItems:"center",padding:"12px 15px",marginBottom:14,
                  background:T.bgSurface,border:`1px solid ${T.border}`,borderRadius:10}}>
                  <span style={{fontSize:12.8,color:T.textSub}}>
                    <b style={{color:T.text,fontFamily:"'Geist Mono',monospace"}}>{xg.records.toLocaleString()}</b> records resolved ·{" "}
                    <b style={{color:T.green,fontFamily:"'Geist Mono',monospace"}}>{(xg.autoApplied||xg.clean||0).toLocaleString()}</b> auto-confirmed by the resolver
                  </span>
                  <span style={{width:1,height:16,background:T.border}}/>
                  <span style={{fontSize:12.8,color:open.length?T.amber:T.green,fontWeight:600}}>
                    {open.length?`${open.length} need you · ${klMoney(open.reduce((n,i)=>n+i.governs,0))} governed`:"No exceptions"}
                  </span>
                  {done.length>0&&<span style={{fontSize:12.8,color:T.textSub}}>· <b style={{color:T.text}}>{done.length}</b> you decided</span>}
                  <span style={{marginLeft:"auto",fontSize:11,color:T.textMuted}}>
                    {xg.scan.mode==="full"?"All rows":"Sample"} scan · {xg.scan.at}{xg.scan.stale?" · may be out of date":""}
                  </span>
                  <Btn small ghost onClick={()=>setScanFor(xg.id)}>Re-scan</Btn>
                </div>

                {ex.length===0 && (
                  <KLEmpty icon={Ic.check(34)} title="No exceptions"
                    sub="All records resolved without conflict, and none were left unmatched."/>
                )}

                {open.length>0 && (
                  <SH title={`Needs a decision (${open.length})`}
                    sub="Ranked by the money each decision governs. Records accepted automatically are not listed."
                    action={<Btn small ghost onClick={()=>{setSelX(null);setTab("worklist");}}>See the whole estate →</Btn>}/>
                )}
                {open.map((it,i)=>(
                  <KLDecisionCard key={it.id} it={it} rank={i+1} srcById={srcById} canCurate={canCurate}
                    selected={false} onSelect={()=>{}} onVerb={applyVerb}
                    onHistory={()=>setHist({title:it.name, kicker:`Decision · ${xg.name}`, entries:xg.history})}/>
                ))}

                {done.length>0 && (<>
                  <SH title={`Decided (${done.length})`}
                    sub="Kept permanently, with the decider's name. These survive re-resolution untouched."/>
                  {done.map((it,i)=>(
                    <KLDecisionCard key={it.id} it={it} rank={open.length+i+1} srcById={srcById} canCurate={canCurate}
                      selected={false} onSelect={()=>{}} onVerb={applyVerb}
                      onHistory={()=>setHist({title:it.name, kicker:`Decision · ${xg.name}`, entries:xg.history})}/>
                  ))}
                </>)}
              </>
            );
          })()}

          {scanFor===xg.id && (
            <Modal open onClose={()=>setScanFor(null)} title={`Run a data scan — ${xg.name}`} width={580}>
              <p style={{fontSize:13,color:T.textSub,lineHeight:1.75,marginBottom:14}}>
                Everything so far has used <b style={{color:T.text}}>metadata only</b>. Resolving
                {" "}{xg.entity.toLowerCase()} records requires <b style={{color:T.text}}>reading rows</b> from the tables
                below. This access is attributed to you and recorded in the audit log.
              </p>
              <div style={{fontSize:10.5,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.07em",marginBottom:7}}>Data in scope</div>
              {xg.srcIds.map(id=>{
                const g=srcById(id); if(!g) return null;
                const m=g.masters.find(x=>x.entity===xg.entity);
                const pii=(g.assets||[]).find(a=>a.n===m?.table)?.tags||[];
                return (
                  <div key={id} style={{display:"flex",alignItems:"center",gap:9,padding:"8px 11px",marginBottom:6,
                    background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:8}}>
                    <ServiceIcon service={g.service} size={15}/>
                    <span style={{fontSize:12,fontWeight:600,color:T.text,minWidth:104}}>{g.name}</span>
                    <span style={{fontSize:11.5,color:T.textSub,fontFamily:"'Geist Mono',monospace"}}>{m?m.table:"—"}</span>
                    <span style={{marginLeft:"auto",display:"flex",gap:4}}>
                      {pii.map(t=><Badge key={t} bg={T.amber+"1a"} color={T.amber} border={T.amber+"44"}>{t}</Badge>)}
                    </span>
                  </div>
                );
              })}
              <div style={{fontSize:10.5,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.07em",margin:"14px 0 7px"}}>Scan scope</div>
              {[
                {v:"sample", l:"Sample — 5,000 rows per source", d:"Validates matching with minimal data exposure. Recommended."},
                {v:"full",   l:"All rows",                       d:"Produces complete records. Longer runtime, and reads all rows including PII."},
              ].map(o=>(
                <div key={o.v} onClick={()=>setScanMode(o.v)}
                  style={{display:"flex",gap:10,padding:"10px 12px",marginBottom:6,cursor:"pointer",borderRadius:9,
                    background:scanMode===o.v?T.accentDim:T.bgElevated,
                    border:`1px solid ${scanMode===o.v?T.accent+"55":T.border}`}}>
                  <span style={{width:15,height:15,borderRadius:"50%",flexShrink:0,marginTop:2,
                    border:`1.5px solid ${scanMode===o.v?T.accent:T.borderLight}`,display:"flex",alignItems:"center",justifyContent:"center"}}>
                    {scanMode===o.v&&<span style={{width:7,height:7,borderRadius:"50%",background:T.accent}}/>}
                  </span>
                  <span>
                    <span style={{display:"block",fontSize:12.5,fontWeight:600,color:T.text}}>{o.l}</span>
                    <span style={{display:"block",fontSize:11.5,color:T.textMuted,marginTop:2}}>{o.d}</span>
                  </span>
                </div>
              ))}
              <div style={{display:"flex",gap:9,alignItems:"center",padding:"10px 13px",marginTop:12,borderRadius:9,
                background:T.amberDim,border:`1px solid ${T.amber}44`,fontSize:12,color:T.text,lineHeight:1.6}}>
                <span style={{color:T.amber,display:"flex"}}><svg width="13" height="13" viewBox="0 0 16 16" fill="none" style={{flexShrink:0,marginTop:1}}><path d="M8 2.2l6 11.6H2L8 2.2z" stroke="currentColor" strokeWidth="1.3" strokeLinejoin="round"/><path d="M8 6.6v3.2M8 11.6v.5" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round"/></svg></span>
                <div>Approved as <b>alex.rivera</b>. Runs as a background job and is recorded in the audit log. Resolved
                  records remain governed by <b>{xg.policy||"this graph's policy"}</b>.</div>
              </div>
              <div style={{display:"flex",gap:8,marginTop:18,justifyContent:"flex-end"}}>
                <Btn onClick={()=>setScanFor(null)}>Cancel</Btn>
                <Btn variant="primary" onClick={()=>runScan(xg.id,scanMode)}>Approve and run scan</Btn>
              </div>
            </Modal>
          )}

          {xTab==="rules" && (
            <>
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:14,marginBottom:14}}>
                <Card2 style={{padding:18}}>
                  <SH title="Match keys" sub="The business concepts this graph matches on. Each one binds to a different column in every source."/>
                  {xg.keys.length===0
                    ? <div style={{fontSize:12.5,color:T.textMuted}}>No match keys recorded for this graph.</div>
                    : xg.keys.map(k=><KLRow key={k} nm={k} chip="In use" kind="exist" cf="From your classifications"/>)}
                </Card2>
                <Card2 style={{padding:18}}>
                  <SH title="Precedence" sub="Which source takes precedence per field when values disagree."/>
                  {xg.beliefs.map(b=><KLRow key={b.f} nm={b.f} chip={b.s} kind="exist" cf="Steward decision" acts="cc" onAct={()=>toast("Rule updated")}/>)}
                </Card2>
              </div>

              {/* The resolution rule is a STRUCTURED DESCRIPTOR, never stored SQL. The resolver
                  compiles its own SELECT from catalog-validated identifiers — free-form SQL that a
                  resolver executes verbatim is an injection vector, so it is not storable here. */}
              <SH title="Resolution rules"
                sub="One per source. The descriptor is the contract; the SELECT below is compiled from it, not stored."/>
              {xg.srcIds.map(id=>{
                const g = srcById(id); if(!g) return null;
                const m = g.masters.find(x=>x.entity===xg.entity);
                const sql = m && klRuleSQL(m, g.name);
                return (
                  <Card2 key={id} style={{padding:16,marginBottom:10}}>
                    <div style={{display:"flex",alignItems:"center",gap:10,flexWrap:"wrap",marginBottom:10}}>
                      <ServiceIcon service={g.service} size={17}/>
                      <b style={{fontSize:13,color:T.text}}>{g.name}</b>
                      {g.opEntity&&<KLChip kind="plain">{g.opEntity}</KLChip>}
                      <span style={{fontSize:11.5,color:T.textSub,fontFamily:"'Geist Mono',monospace"}}>{m?m.table:"—"}</span>
                      {m&&m.rule
                        ? <span style={{marginLeft:"auto",display:"flex",gap:6,alignItems:"center"}}>
                            <KLEnvelope env={{by:"ai", src:m.rule.by, conf:m.rule.conf}}/>
                          </span>
                        : <span style={{marginLeft:"auto"}}><KLChip kind="new">Not generatable</KLChip></span>}
                    </div>
                    {m&&m.rule ? (<>
                      <div style={{display:"flex",gap:7,flexWrap:"wrap",marginBottom:10}}>
                        {[["Primary key",m.rule.pk],["Name",m.rule.name],["Tax ID",m.rule.tax],
                          ["Entity code",m.rule.code],["Serial",m.rule.serial],["Asset tag",m.rule.tag]]
                          .filter(([,v])=>v).map(([l,v])=>(
                          <span key={l} style={{fontSize:11,color:T.textSub,padding:"4px 9px",borderRadius:6,
                            background:T.bgElevated,border:`1px solid ${T.border}`}}>
                            {l} · <b style={{color:T.text,fontFamily:"'Geist Mono',monospace"}}>{v}</b>
                          </span>
                        ))}
                        <span style={{fontSize:11,color:T.textSub,padding:"4px 9px",borderRadius:6,
                          background:T.bgElevated,border:`1px solid ${T.border}`}}>
                          Entity class · <b style={{color:T.text}}>{m.rule.cls}</b>
                        </span>
                      </div>
                      {m.rule.guard&&(
                        <div style={{display:"flex",gap:9,padding:"9px 12px",marginBottom:10,borderRadius:8,
                          background:T.amberDim,border:`1px solid ${T.amber}44`,fontSize:11.5,color:T.text,lineHeight:1.6}}>
                          <b style={{flexShrink:0}}>Generator guard</b><span>{m.rule.guard}</span>
                        </div>
                      )}
                      <pre style={{margin:0,padding:"11px 13px",borderRadius:8,background:T.bg,border:`1px solid ${T.border}`,
                        fontFamily:"'Geist Mono',monospace",fontSize:11.2,lineHeight:1.6,color:T.textSub,overflowX:"auto"}}>{sql}</pre>
                    </>) : (
                      <div style={{fontSize:12,color:T.amber,lineHeight:1.65}}>
                        {(m&&m.blocked)||`No ${xg.entity} master is classified in this source, so it cannot take part in matching.`}
                      </div>
                    )}
                  </Card2>
                );
              })}
            </>
          )}
        </div>
        <KLHistoryDrawer open={!!hist} onClose={()=>setHist(null)}
          title={hist?.title} kicker={hist?.kicker} entries={hist?.entries}/>
      </div>
    );
  }

  // ══════════════ LIST / OVERVIEW ══════════════
  const srcFiltered = srcGraphs.filter(g=>{
    const q = sq.trim().toLowerCase();
    const hitQ = !q || [g.name,g.key,g.connection,g.owner,g.domain,...(g.entities||[])]
      .filter(Boolean).some(v=>String(v).toLowerCase().includes(q));
    const hitS = sStatus==="all" || (sStatus==="drift" ? g.drift>0 : g.status===sStatus);
    return hitQ && hitS;
  }).sort((a,b)=> sSort==="name" ? a.name.localeCompare(b.name)
                : sSort==="tables" ? b.tables-a.tables
                : sSort==="built" ? String(b.built).localeCompare(String(a.built))
                : 0);

  const xFiltered = xGraphs.filter(x=>{
    const q = xq.trim().toLowerCase();
    const names = x.srcIds.map(i=>srcById(i)?.name).filter(Boolean);
    const hitQ = !q || [x.name,x.key,x.entity,x.owner,x.domain,...names]
      .filter(Boolean).some(v=>String(v).toLowerCase().includes(q));
    const hitS = xStatus==="all" || (xStatus==="review" ? klOpen(x)>0 : x.status===xStatus);
    return hitQ && hitS;
  }).sort((a,b)=> xSort==="name" ? a.name.localeCompare(b.name)
                : xSort==="records" ? b.records-a.records
                : xSort==="review" ? klOpen(b)-klOpen(a)
                : 0);

  return (
    <div className="fadeUp" style={{height:"100%",display:"flex",flexDirection:"column"}}>
      {/* EDG does not build source knowledge graphs. Data Sense does, and they arrive
          through the Solix EAI connector - so the action on that tab is to go and connect
          it, never to open a builder. The one thing created in this module is the
          cross-source master, which is EDG's own work: deciding that records held in
          different systems are the same real-world thing. */}
      <Topbar breadcrumb={[{label:"Knowledge Layer"}]} actions={
        tab==="sources"
          ? <Btn variant="primary" small icon={Ic.plus(11)} onClick={()=>onNav&&onNav("settings")}>Import from Solix EAI</Btn>
          : <Btn variant="primary" small icon={Ic.plus(11)} onClick={()=>openWizard("cross")}>New Cross-Source Graph</Btn>
      }/>
      <div style={{flex:1,overflowY:"auto",padding:24}}>
        <Tabs2 tabs={[
          {key:"overview", label:"Overview"},
          {key:"worklist", label:`Worklist${(wlOpen.length+openMeasures.length)?` (${wlOpen.length+openMeasures.length})`:""}`},
          {key:"sources",  label:`Source Knowledge Graphs (${srcGraphs.length})`},
          {key:"cross",    label:`Cross-Source Knowledge Graphs (${xGraphs.length})`},
        ]} active={tab} onChange={setTab}/>

        {/* ───────── OVERVIEW ───────── */}
        {tab==="overview" && (
          <>
            {(()=>{
              const top = wlOpen[0];
              const nba = top
                ? {h:`Decide ${top.name}`, s:`${klMoneyFull(top.governs)} of ${top.entity.toLowerCase()} value hangs on this one match, and the resolver is only ${top.conf.toFixed(2)} sure. It is the most expensive doubt in the estate.`,
                   b:"Open the Worklist", go:()=>setTab("worklist")}
                : openMeasures.length
                ? {h:`Certify ${openMeasures[0].name}`, s:`${openMeasures.length} term${openMeasures.length===1?"":"s"} still answer differently depending on how the question is phrased. Certifying fixes one definition everywhere, including in generated builds.`,
                   b:"Open Terms", go:()=>{setTab("worklist");setWSub("terms");}}
                : totals.drift
                ? {h:"Refresh a stale source graph", s:`${totals.drift} source${totals.drift===1?"":"s"} changed since their graphs were built. Dependent cross-source graphs may be answering from an old shape.`,
                   b:"Open Source Graphs", go:()=>setTab("sources")}
                : {h:"Nothing is waiting on you", s:"Every exception is decided, every term is certified and every source graph is current. Browse the model, or generate a governed build.",
                   b:"Open Cross-Source Graphs", go:()=>setTab("cross")};
              return (
                <Card2 style={{padding:"15px 18px",marginBottom:16,display:"flex",gap:14,alignItems:"center",flexWrap:"wrap",
                  background:top?T.accentDim:T.bgSurface, borderColor:top?T.accent+"44":T.border}}>
                  <span style={{width:34,height:34,borderRadius:9,flexShrink:0,display:"flex",alignItems:"center",justifyContent:"center",
                    background:T.bgSurface,border:`1px solid ${T.border}`,color:top?T.accent:T.green}}>
                    {top?Ic.alert(17):Ic.check(17)}</span>
                  <span style={{minWidth:0,flex:"1 1 320px"}}>
                    <span style={{display:"block",fontSize:10.5,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.07em"}}>
                      Next best action</span>
                    <span style={{display:"block",fontSize:14,fontWeight:700,color:T.text,marginTop:3}}>{nba.h}</span>
                    <span style={{display:"block",fontSize:12,color:T.textSub,marginTop:3,lineHeight:1.6}}>{nba.s}</span>
                  </span>
                  <Btn small variant="primary" onClick={nba.go}>{nba.b}</Btn>
                </Card2>
              );
            })()}

            <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(165px,1fr))",gap:12,marginBottom:20}}>
              <Metric label="Source graphs published" value={`${totals.published} of ${srcGraphs.length}`}/>
              <Metric label="Tables described" value={totals.tables.toLocaleString()}/>
              <Metric label="Trusted records" value={totals.records.toLocaleString()}
                sub={`${ready.autoApplied.toLocaleString()} auto-confirmed`}/>
              <Metric label="Waiting on you" value={String(wlOpen.length+openMeasures.length)}
                color={(wlOpen.length+openMeasures.length)?T.amber:T.green}
                sub={wlOpen.length
                  ? `${wlOpen.length} decision${wlOpen.length===1?"":"s"} (${klMoney(ready.waitingMoney)}) · ${openMeasures.length} term${openMeasures.length===1?"":"s"}`
                  : openMeasures.length ? `${openMeasures.length} term${openMeasures.length===1?"":"s"} to certify` : "nothing outstanding"}/>
              <Metric label="Ungoverned labels" value={String(totals.invented)} color={T.green} sub="Target: 0"/>
            </div>

            <div style={{display:"grid",gridTemplateColumns:"1.25fr 1fr",gap:14,marginBottom:20}}>
              {/* how the layer is built */}
              <Card2 style={{padding:16}}>
                <SH title="How the Knowledge Layer is built" sub="Each layer builds on the one before it."/>
                {[
                  {n:"1", c:T.green,  h:"Governed vocabulary",  s:"Classifications, glossary terms, domains and owners already defined in EDG.", v:"38 tags · 214 terms"},
                  {n:"2", c:T.blue,   h:"Source Knowledge Graphs", s:"One per application, built in Data Sense and imported through the Solix EAI connector. EDG governs it and watches it for change; it never edits it.", v:`${totals.published} imported`},
                  {n:"3", c:T.accent, h:"Cross-Source Knowledge Graphs", s:"Joins two or more source graphs into one trusted record per real-world entity.", v:`${xGraphs.length} graphs`},
                ].map((r,i)=>(
                  <div key={r.n} style={{display:"flex",gap:11,padding:"10px 0",borderTop:i?`1px solid ${T.border}`:"none"}}>
                    <span style={{width:22,height:22,borderRadius:"50%",flexShrink:0,display:"flex",alignItems:"center",justifyContent:"center",
                      fontSize:10.5,fontWeight:700,background:r.c+"1a",color:r.c,border:`1px solid ${r.c}44`,fontFamily:"'Geist Mono',monospace"}}>{r.n}</span>
                    <div style={{minWidth:0,flex:1}}>
                      <div style={{fontSize:12.8,fontWeight:700,color:T.text}}>{r.h}</div>
                      <div style={{fontSize:11.5,color:T.textMuted,lineHeight:1.55,marginTop:2}}>{r.s}</div>
                    </div>
                    <span style={{fontSize:11,color:T.textSub,fontFamily:"'Geist Mono',monospace",whiteSpace:"nowrap"}}>{r.v}</span>
                  </div>
                ))}
              </Card2>

              {/* entity coverage matrix + who each system serves */}
              <Card2 style={{padding:16}}>
                <SH title="Entity coverage" sub="An entity requires two or more published source graphs with classified identifying columns."/>
                {entityMatrix.map(e=>(
                  <div key={e.entity} style={{display:"flex",alignItems:"center",gap:9,padding:"8px 0",borderBottom:`1px solid ${T.border}`}}>
                    <span style={{fontSize:12.3,fontWeight:600,color:T.text,minWidth:88}}>{e.entity}</span>
                    <div style={{display:"flex",gap:3,flex:1}}>
                      {srcGraphs.map(g=>(
                        <span key={g.id} title={`${g.name}: ${e.ready.includes(g.id)?"ready":"not tagged"}`}
                          style={{width:16,height:7,borderRadius:2,background:e.ready.includes(g.id)?T.green:T.bgHover,
                            border:`1px solid ${e.ready.includes(g.id)?T.green:T.border}`}}/>
                      ))}
                    </div>
                    {e.mastered
                      ? <Badge bg={T.green+"1a"} color={T.green} border={T.green+"55"}>Mastered</Badge>
                      : e.ready.length>=2
                        ? <Btn small ghost onClick={()=>{setTab("cross");openWizard("cross", e.entity);}}>Create graph</Btn>
                        : <span style={{fontSize:10.5,color:T.textMuted}}>{e.ready.length} of 2 required</span>}
                  </div>
                ))}
              </Card2>
            </div>

            <Card2 style={{padding:16,marginBottom:20}}>
              <SH title="Operating entities"
                sub="Which part of the business each system serves, so people can ask about the division rather than the application."/>
              <div style={{display:"flex",gap:10,flexWrap:"wrap"}}>
                {KL_OP_ENTITIES.map(oe=>{
                  const gs = srcGraphs.filter(g=>g.opEntity===oe.name);
                  return (
                    <div key={oe.id} style={{flex:"1 1 210px",minWidth:0,padding:"12px 14px",borderRadius:9,
                      background:T.bgElevated,border:`1px solid ${T.border}`}}>
                      <div style={{fontSize:12.8,fontWeight:700,color:T.text}}>{oe.name}</div>
                      <div style={{fontSize:10.8,color:T.textMuted,marginTop:2}}>{oe.region} · owner {oe.owner}</div>
                      <div style={{display:"flex",gap:6,flexWrap:"wrap",marginTop:9}}>
                        {gs.length
                          ? gs.map(g=>(
                            <button key={g.id} onClick={()=>openSrc(g.id)}
                              style={{display:"inline-flex",alignItems:"center",gap:6,fontSize:11,padding:"4px 9px",borderRadius:6,cursor:"pointer",
                                background:T.bgSurface,border:`1px solid ${T.border}`,color:T.textSub,fontFamily:"inherit"}}>
                              <ServiceIcon service={g.service} size={12}/>{g.name}
                            </button>))
                          : <span style={{fontSize:11,color:T.textMuted}}>No system mapped yet</span>}
                      </div>
                    </div>
                  );
                })}
                {srcGraphs.some(g=>!g.opEntity)&&(
                  <div style={{flex:"1 1 210px",padding:"12px 14px",borderRadius:9,background:T.amberDim,border:`1px solid ${T.amber}44`}}>
                    <div style={{fontSize:12.8,fontWeight:700,color:T.text}}>Unmapped</div>
                    <div style={{fontSize:11.5,color:T.textSub,marginTop:4,lineHeight:1.55}}>
                      {srcGraphs.filter(g=>!g.opEntity).map(g=>g.name).join(", ")} — questions about the business
                      cannot reach these until they are mapped.
                    </div>
                  </div>
                )}
              </div>
            </Card2>

            <SH title="Requires attention" sub="Items accepted automatically are not listed."/>
            {(totals.review+totals.drift+totals.proposed+openMeasures.length)===0
              ? <KLEmpty icon={Ic.check(34)} title="Nothing requires attention" sub="The Knowledge Layer is up to date."/>
              : <DataTable
                  cols={[
                    {key:"kind",  label:"Type", render:v=><Badge bg={T.amber+"1a"} color={T.amber} border={T.amber+"44"}>{v}</Badge>},
                    {key:"obj",   label:"Object", render:v=><span style={{fontWeight:600}}>{v}</span>},
                    {key:"detail",label:"Detail"},
                    {key:"where", label:"Where", render:v=><span style={{fontSize:11.5,color:T.textMuted}}>{v}</span>},
                    {key:"act",   label:"", render:(v,r)=><Btn small variant="primary" onClick={r.go}>Review</Btn>},
                  ]}
                  rows={[
                    ...xGraphs.filter(x=>klOpen(x)>0).map(x=>{
                      const open = klExceptions(x).filter(i=>i.state==="open");
                      return {kind:"Match decision", obj:x.name,
                        detail:`${open.length} open · ${klMoney(open.reduce((n,i)=>n+i.governs,0))} governed`,
                        where:"Worklist", go:()=>setTab("worklist")};
                    }),
                    ...openMeasures.map(m=>({kind:"Term to certify", obj:m.name,
                      detail:`${(m.bindings||[]).length} candidate sources still disagree`,
                      where:"Worklist › Terms", go:()=>{setTab("worklist");setWSub("terms");}})),
                    ...srcGraphs.filter(s=>s.drift>0).map(s=>({kind:"Source drift", obj:s.name,
                      detail:`${s.drift} columns added since last build`, where:"Source graph", go:()=>openSrc(s.id)})),
                    ...srcGraphs.filter(s=>s.bind.proposed>0).map(s=>({kind:"Term approval", obj:s.name,
                      detail:`${s.bind.proposed} new terms proposed`, where:"Glossary", go:()=>openSrc(s.id,"bindings")})),
                  ]}/>}

            <KLNote tone="quiet">
              Confidence thresholds are set on the <b>Trust dial</b> at the top of the Worklist, where you can
              see what a change would do before applying it. Refresh schedules live in
              <b> Settings › Knowledge Layer</b>; run history in <b>Settings › Background Jobs</b>.
            </KLNote>
          </>
        )}

        {/* ───────── WORKLIST — the "what needs me" surface ───────── */}
        {tab==="worklist" && (
          <>
            {/* The one line that answers "what's done, what's pending, what's mine to decide". */}
            <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(165px,1fr))",gap:12,marginBottom:14}}>
              <Metric label="Auto-applied by the resolver" value={ready.autoApplied.toLocaleString()} color={T.green}
                sub={`of ${ready.resolved.toLocaleString()} records resolved`}/>
              <Metric label="Waiting on you" value={String(ready.waiting)} color={ready.waiting?T.amber:T.green}
                sub={ready.waiting?`${klMoney(ready.waitingMoney)} governed`:"nothing outstanding"}/>
              <Metric label="You decided" value={String(ready.decided)} sub="preserved across re-resolution"/>
              <Metric label="Terms to certify" value={String(openMeasures.length)}
                color={openMeasures.length?T.amber:T.green} sub={openMeasures.length?"answers still differ by phrasing":"one definition everywhere"}/>
              <Metric label="Automation rate"
                value={ready.resolved?`${Math.round(ready.autoApplied/ready.resolved*1000)/10}%`:"—"}
                color={T.green} sub="the machine does the bulk"/>
            </div>

            <KLTrustDial trust={trust} setTrust={setTrust} items={wlAll} canApply={canDial}
              onApply={applyDial} onRequest={requestDial}/>

            <div style={{display:"flex",gap:10,alignItems:"center",flexWrap:"wrap",marginBottom:14}}>
              <SegTabs tabs={[
                {key:"decisions", label:`Decisions${wlOpen.length?` (${wlOpen.length})`:""}`},
                {key:"terms",     label:`Terms${openMeasures.length?` (${openMeasures.length})`:""}`},
              ]} active={wSub} onChange={setWSub}/>
              <span style={{fontSize:11.5,color:T.textMuted,marginLeft:"auto"}}>
                Ranked by the money the decision governs × how unsure the resolver is.
              </span>
              <Btn small ghost onClick={()=>setHist({title:"Knowledge Layer", kicker:"Layer settings · change history", entries:layerHist})}>
                Layer history
              </Btn>
            </div>

            {wSub==="decisions" && (<>
              <div style={{display:"flex",gap:9,alignItems:"center",flexWrap:"wrap",marginBottom:11}}>
                <div style={{flex:1,minWidth:220}}>
                  <Input2 value={wq} onChange={e=>setWq(e.target.value)} icon={Ic.search(12)}
                    placeholder="Search decisions by name, entity, graph or issue…"/>
                </div>
                <span style={{fontSize:11.5,color:T.textMuted,fontFamily:"'Geist Mono',monospace",whiteSpace:"nowrap"}}>
                  {wlFiltered.length}/{wlAll.length}
                </span>
              </div>
              {(()=>{
                // The one line that explains why this surface is not a repeat of a graph's tab.
                const byGraph = {};
                wlOpen.forEach(i=>{ (byGraph[i.xgId]=byGraph[i.xgId]||{name:i.xgName,n:0,m:0}); byGraph[i.xgId].n++; byGraph[i.xgId].m+=i.governs||0; });
                const gs = Object.entries(byGraph).sort((a,b)=>b[1].m-a[1].m);
                if(gs.length===0) return null;
                return (
                  <div style={{display:"flex",gap:10,alignItems:"center",flexWrap:"wrap",padding:"10px 13px",marginBottom:12,
                    borderRadius:9,background:T.bgElevated,border:`1px solid ${T.border}`}}>
                    <span style={{fontSize:12,color:T.textSub}}>
                      {wlOpen.length} open decision{wlOpen.length===1?"":"s"} across{" "}
                      <b style={{color:T.text}}>{gs.length} cross-source graph{gs.length===1?"":"s"}</b> —
                      ranked together so the most expensive doubt wins, whichever graph it sits in.
                    </span>
                    <span style={{marginLeft:"auto",display:"flex",gap:6,flexWrap:"wrap"}}>
                      {gs.map(([id,g])=>(
                        <button key={id} onClick={()=>openX(id,"records")}
                          style={{display:"inline-flex",alignItems:"center",gap:6,fontSize:11,padding:"4px 9px",borderRadius:6,cursor:"pointer",
                            background:T.bgSurface,border:`1px solid ${T.border}`,color:T.textSub,fontFamily:"inherit"}}>
                          {g.name}
                          <b style={{fontFamily:"'Geist Mono',monospace",color:T.text}}>{g.n}</b>
                          <span style={{fontFamily:"'Geist Mono',monospace",color:T.textMuted}}>{klMoney(g.m)}</span>
                        </button>
                      ))}
                    </span>
                  </div>
                );
              })()}

              <div style={{display:"flex",gap:6,flexWrap:"wrap",alignItems:"center",marginBottom:14}}>
                {[
                  {v:"all",       l:"Needs a decision", n:wlOpen.length, c:T.amber},
                  {v:"conflict",  l:"Conflicting values", n:wlOpen.filter(i=>i.kind==="conflict").length},
                  {v:"unmatched", l:"Unmatched", n:wlOpen.filter(i=>i.kind==="unmatched").length},
                  {v:"decided",   l:"You decided", n:wlAll.filter(i=>i.state!=="open").length, c:T.green},
                ].map(f=>{
                  const on = wKind===f.v;
                  return (
                    <button key={f.v} onClick={()=>setWKind(f.v)}
                      style={{display:"inline-flex",alignItems:"center",gap:6,padding:"5px 13px",borderRadius:99,fontSize:11.5,cursor:"pointer",fontFamily:"inherit",
                        fontWeight:on?700:500,border:`1px solid ${on?(f.c||T.accent):T.border}`,
                        background:on?(f.c?f.c+"1a":T.accentDim):"transparent",color:on?(f.c||T.accent):T.textSub}}>
                      {f.l}<span style={{fontSize:10,fontFamily:"'Geist Mono',monospace",opacity:.75}}>{f.n}</span>
                    </button>
                  );
                })}
                {(wq||wKind!=="all")&&<button onClick={()=>{setWq("");setWKind("all");}}
                  style={{fontSize:11,color:T.textMuted,background:"none",border:"none",cursor:"pointer",marginLeft:2}}>Clear</button>}
              </div>

              {/* bulk — one transaction, one audit row */}
              {canCurate && wSel.size>0 && (
                <div style={{display:"flex",gap:12,alignItems:"center",flexWrap:"wrap",padding:"11px 15px",marginBottom:12,
                  borderRadius:10,background:T.accentDim,border:`1px solid ${T.accent}44`}}>
                  <span style={{fontSize:12.5,color:T.text}}>
                    <b style={{fontFamily:"'Geist Mono',monospace"}}>{wSel.size}</b> selected ·{" "}
                    <b style={{fontFamily:"'Geist Mono',monospace"}}>{klMoney(selItems.reduce((n,i)=>n+(i.governs||0),0))}</b> governed
                  </span>
                  <span style={{marginLeft:"auto",display:"flex",gap:7}}>
                    <Btn small ghost onClick={()=>setWSel(new Set())}>Clear selection</Btn>
                    <Btn small variant="primary" onClick={()=>bulkConfirm(selItems)}>Confirm all as one record each</Btn>
                  </span>
                </div>
              )}
              {canCurate && wSel.size===0 && wlFiltered.some(i=>i.state==="open") && (
                <div style={{display:"flex",gap:10,alignItems:"center",flexWrap:"wrap",marginBottom:12}}>
                  <Btn small ghost onClick={()=>setWSel(new Set(wlFiltered.filter(i=>i.state==="open").map(i=>i.id)))}>
                    Select all shown
                  </Btn>
                  <Btn small ghost onClick={()=>setWSel(new Set(wlFiltered.filter(i=>i.state==="open"&&i.conf>=trust.match).map(i=>i.id)))}>
                    Select everything above the dial ({wlFiltered.filter(i=>i.state==="open"&&i.conf>=trust.match).length})
                  </Btn>
                </div>
              )}

              {wlFiltered.length===0
                ? <KLEmpty icon={Ic.check(34)}
                    title={wKind==="decided"?"No decisions recorded yet":"Nothing is waiting on you"}
                    sub={wKind==="decided"
                      ? "Confirm, hold or reject something and it will be listed here — permanently."
                      : "Every exception across every cross-source graph has been decided."}/>
                : wlFiltered.map((it,i)=>(
                    <KLDecisionCard key={it.id} it={it} rank={i+1} srcById={srcById}
                      selected={wSel.has(it.id)} canCurate={canCurate}
                      showGraph onOpenGraph={id=>openX(id,"records")}
                      onSelect={id=>setWSel(s=>{const n=new Set(s); n.has(id)?n.delete(id):n.add(id); return n;})}
                      onVerb={applyVerb}
                      onHistory={item=>{
                        const g = xGraphs.find(x=>x.id===item.xgId);
                        setHist({title:item.name, kicker:`Decision · ${g?g.name:""}`,
                          entries:(g?.history||[]).filter(h=>!h.detail||h.detail.includes(item.name)||h.action==="Resolution complete")});
                      }}/>
                  ))}
            </>)}

            {wSub==="terms" && (<>
              <div style={{display:"flex",gap:9,padding:"11px 14px",marginBottom:14,borderRadius:10,
                background:T.bgElevated,border:`1px solid ${T.border}`,fontSize:12.3,color:T.textSub,lineHeight:1.65}}>
                <span style={{color:T.violet,display:"flex",flexShrink:0,marginTop:1}}>{Ic.bot(13)}</span>
                <div>Definitions and per-application bindings arrive <b style={{color:T.text}}>drafted</b>. Your
                  verb is confirm or edit — never authoring from a blank form. Certifying changes what the live
                  answer engine returns and compiles the definition into every generated build.</div>
              </div>
              {measures.map(m=>(
                <KLTermCard key={m.id} m={m} srcById={srcById} canCertify={canCurate}
                  onPick={pickBinding} onCertify={certifyMeasure}/>
              ))}
            </>)}
          </>
        )}

        {/* ───────── SOURCE GRAPHS ───────── */}
        {tab==="sources" && (
          <>
            <KLToolbar q={sq} setQ={setSq} placeholder="Search by name, ID, connection, entity or owner…"
              statuses={[
                {v:"all",       l:"All",         n:srcGraphs.length},
                {v:"Published", l:"Published",   n:srcGraphs.filter(g=>g.status==="Published").length, c:T.green},
                {v:"In review", l:"In review",   n:srcGraphs.filter(g=>g.status==="In review").length, c:T.amber},
                {v:"drift",     l:"Needs attention", n:totals.drift, c:T.rose},
              ]}
              status={sStatus} setStatus={setSStatus}
              sort={sSort} setSort={setSSort}
              sortOpts={[{v:"name",l:"Sort: Name"},{v:"tables",l:"Sort: Most tables"},{v:"built",l:"Sort: Recently built"}]}
              shown={srcFiltered.length} total={srcGraphs.length}
              onClear={()=>{setSq("");setSStatus("all");}}/>
            {/* Ready to master. Two or more imported graphs describing the same entity, and
                nothing joining them yet - which means the estate holds two or more separate
                supplier lists and nobody has said which rows are the same company. */}
            {(()=>{
              // An entity is worth mentioning when more than one imported graph describes it
              // and nothing joins them - which means the estate holds two or more separate
              // lists of the same real-world thing. Both answers matter: the ones that can be
              // mastered now, and the ones that cannot, with the reason. A row that only says
              // "not ready" and makes someone go hunting for why is the version of this screen
              // that gets ignored.
              const rows = KL_ENTITIES.map(en=>{
                // A graph "describes" an entity when it carries a master table for it. The
                // summary entities list is a display field and can lag: Oracle EBS holds an
                // MTL_SYSTEM_ITEMS_B master for Material but does not list Material, which
                // is exactly the case this row exists to surface.
                const inGraphs = srcGraphs.filter(g=>
                  (g.masters||[]).some(m=>m.entity===en) || (g.entities||[]).includes(en));
                if(inGraphs.length<2 || xGraphs.some(x=>x.entity===en)) return null;
                const ready = KL_READY_FOR(srcGraphs, en);
                if(ready.length>=2) return {en, inGraphs, ready, why:null};
                const why = inGraphs.filter(g=>!ready.includes(g.id)).map(g=>{
                  if(g.status!=="Published") return `${g.name} is still a draft in Data Sense`;
                  const m = (g.masters||[]).find(m=>m.entity===en);
                  if(m&&m.blocked)  return `${g.name}: ${m.blocked}`;
                  if(!m)            return `${g.name} declares ${en} but has no master table for it`;
                  return `${g.name} has no identifier for ${en} that is valid outside its own system`;
                });
                return {en, inGraphs, ready, why};
              }).filter(Boolean);
              if(rows.length===0) return null;
              const list = gs => {
                const ns = gs.map(g=>g.name);
                return ns.length<2 ? ns.join("") : ns.slice(0,-1).join(", ")+" and "+ns[ns.length-1];
              };
              return (
                <Card2 style={{padding:"14px 16px",marginBottom:14,borderLeft:`3px solid ${T.accent}`}}>
                  <SH title="Described in more than one system, not yet joined"
                    sub="Each of these is one real-world thing held as separate lists. Joining them is what a cross-source master does."/>
                  {rows.map((r,i)=>(
                    <div key={r.en} style={{display:"flex",alignItems:"flex-start",gap:12,padding:"10px 0",
                      borderTop:i?`1px solid ${T.border}`:"none"}}>
                      <div style={{minWidth:0,flex:1}}>
                        <span style={{fontSize:12.6,color:T.textSub,lineHeight:1.6}}>
                          <strong style={{color:T.text,fontWeight:700}}>{r.en}</strong> appears in {list(r.inGraphs)}.
                          {" "}Nothing connects them, so the estate holds {r.inGraphs.length} separate lists.
                        </span>
                        {r.why && r.why.map((w,j)=>(
                          <div key={j} style={{fontSize:11.3,color:T.textMuted,lineHeight:1.55,marginTop:5,
                            paddingLeft:10,borderLeft:`2px solid ${T.amber}66`}}>{w}</div>
                        ))}
                      </div>
                      {r.why
                        ? <Badge bg={T.amber+"1a"} color={T.amber} border={T.amber+"55"}>Cannot be joined yet</Badge>
                        : <Btn small variant="primary"
                            onClick={()=>{setSelSrc(null);setTab("cross");openWizard("cross", r.en);}}>
                            Create cross-source master
                          </Btn>}
                    </div>
                  ))}
                </Card2>
              );
            })()}
            {srcGraphs.length===0
              ? <KLEmpty icon={Ic.knowledge(34)} title="No knowledge graphs imported yet"
                  sub="Data Sense builds a knowledge graph per application. Connect Solix EAI to import them as governed objects."
                  action={<Btn small variant="primary" onClick={()=>onNav&&onNav("settings")}>Import from Solix EAI</Btn>}/>
              : srcFiltered.length===0
              ? <KLEmpty icon={Ic.knowledge(34)} title="No source graphs match your search"
                  action={<Btn small ghost onClick={()=>{setSq("");setSStatus("all");}}>Clear filters</Btn>}/>
              : <DataTable
                  cols={[
                    {key:"name", label:"Source graph", render:(v,r)=>(
                      <span style={{display:"inline-flex",alignItems:"center",gap:9}}>
                        <ServiceIcon service={r.service} size={18}/>
                        <span>
                          <span style={{display:"block",fontWeight:600}}>{v}</span>
                          <span style={{display:"block",fontSize:10.5,color:T.textMuted,fontFamily:"'Geist Mono',monospace"}}>{r.key} · {r.connection}</span>
                        </span>
                      </span>)},
                    {key:"tables", label:"Scope", render:(v,r)=><span style={{fontSize:11.5,color:T.textSub}}>{v} tables · {r.cols} columns</span>},
                    {key:"words",  label:"Governed", render:v=><Badge bg={(v===100?T.green:T.amber)+"1a"} color={v===100?T.green:T.amber} border={(v===100?T.green:T.amber)+"55"}>{v}%</Badge>},
                    {key:"entities", label:"Entities", render:v=>v.length?<span style={{fontSize:11.5,color:T.textSub}}>{v.join(" · ")}</span>:<span style={{color:T.textMuted}}>none yet</span>},
                    {key:"drift",  label:"Freshness", render:v=>v>0
                      ? <span style={{color:T.amber,fontSize:11.5,fontWeight:600}}>{v} columns added</span>
                      : <span style={{color:T.green,fontSize:11.5}}>Current</span>},
                    {key:"from",   label:"Imported from", render:(v,r)=>(
                      <span style={{fontSize:11.5,color:T.textSub}}>Solix EAI<span style={{color:T.textMuted}}> · {r.version}</span></span>)},
                    // A graph EDG did not build has no build step to report. What matters is
                    // whether Data Sense has published it - a draft is still being edited
                    // upstream, so anything resolved against it would move underneath.
                    {key:"status", label:"Status", render:(v,r)=>v==="Published"
                      ? <Badge bg={T.green+"1a"} color={T.green} border={T.green+"55"}>Published</Badge>
                      : <Badge bg={T.amber+"1a"} color={T.amber} border={T.amber+"55"}>Draft upstream</Badge>},
                  ]}
                  rows={srcFiltered} onRowClick={r=>openSrc(r.id)}/>}
            {unmapped.length>0 && (
              <div style={{marginTop:12,fontSize:11.5,color:T.textMuted}}>
                {unmapped.length} connected system{unmapped.length===1?" has":"s have"} no source graph: {unmapped.join(", ")}.
              </div>
            )}
          </>
        )}

        {/* ───────── CROSS-SOURCE ───────── */}
        {tab==="cross" && (
          <>
            <KLToolbar q={xq} setQ={setXq} placeholder="Search by name, ID, entity, owner or source…"
              statuses={[
                {v:"all",       l:"All",           n:xGraphs.length},
                {v:"Published", l:"Published",     n:xGraphs.filter(x=>x.status==="Published").length, c:T.green},
                {v:"review",    l:"Needs decision",n:xGraphs.filter(x=>klOpen(x)>0).length, c:T.amber},
              ]}
              status={xStatus} setStatus={setXStatus}
              sort={xSort} setSort={setXSort}
              sortOpts={[{v:"name",l:"Sort: Name"},{v:"records",l:"Sort: Most records"},{v:"review",l:"Sort: Most to review"}]}
              shown={xFiltered.length} total={xGraphs.length}
              onClear={()=>{setXq("");setXStatus("all");}}/>
            {xGraphs.length===0
              ? <KLEmpty icon={Ic.knowledge(34)} title="No cross-source knowledge graphs yet"
                  sub="Join two published source graphs on a shared business entity."
                  action={<Btn small variant="primary" onClick={()=>openWizard("cross")}>New Cross-Source Graph</Btn>}/>
              : xFiltered.length===0
                ? <KLEmpty icon={Ic.knowledge(34)} title="No cross-source graphs match your search"
                    action={<Btn small ghost onClick={()=>{setXq("");setXStatus("all");}}>Clear filters</Btn>}/>
                : <DataTable
                    cols={[
                      {key:"name", label:"Cross-source graph", render:(v,r)=>(
                        <span>
                          <span style={{display:"block",fontWeight:600}}>{v}</span>
                          <span style={{display:"block",fontSize:10.5,color:T.textMuted,fontFamily:"'Geist Mono',monospace"}}>{r.key}</span>
                        </span>)},
                      {key:"entity", label:"Entity", render:v=><KLChip kind="exist">{v}</KLChip>},
                      {key:"srcIds", label:"Built on", render:v=>(
                        <span style={{display:"inline-flex",alignItems:"center",gap:5}}>
                          {v.map(id=>{const g=srcById(id); return g?<ServiceIcon key={id} service={g.service} size={14}/>:null;})}
                          <span style={{fontSize:11.5,color:T.textSub,marginLeft:3}}>{v.length} sources</span>
                        </span>)},
                      {key:"records",label:"Trusted records", render:(v,r)=>(
                        <span style={{display:"inline-flex",alignItems:"center",gap:7}}>
                          <b style={{fontFamily:"'Geist Mono',monospace"}}>{r.scan?.state==="done"?v.toLocaleString():"—"}</b>
                          {klOpen(r)>0&&<Badge bg={T.amber+"1a"} color={T.amber} border={T.amber+"55"}>{klOpen(r)} need a look</Badge>}
                        </span>)},
                      {key:"owner",  label:"Owner", render:v=><span style={{fontSize:11.5,color:T.textSub}}>{v}</span>},
                      {key:"status", label:"Status", render:v=><Badge bg={T.green+"1a"} color={T.green} border={T.green+"55"}>{v}</Badge>},
                    ]}
                    rows={xFiltered} onRowClick={r=>openX(r.id)}/>}
          </>
        )}
      </div>
      {wiz && renderWizard()}
      <KLHistoryDrawer open={!!hist} onClose={()=>setHist(null)}
        title={hist?.title} kicker={hist?.kicker} entries={hist?.entries}/>
    </div>
  );
};

// ─────────────────────────────────────────────
// SEARCH
// ─────────────────────────────────────────────
const SearchView = ({onAsset})=>{
  const tagCtx = useTagCtx();
  const [q,setQ]=useState("");
  const [selTagIds,setSelTagIds]=useState(new Set());
  const [tagGroupOpen,setTagGroupOpen]=useState({sensitivity:true,regulatory:false,business:false,custom:false});

  const TAG_CATEGORIES = ["sensitivity","regulatory","business","custom"];
  const tagsByCat = cat => tagCtx ? tagCtx.tagDefs.filter(td=>td.category===cat) : [];
  const assetTagIds = a => tagCtx ? tagCtx.getAssetAssignments(a.id).filter(asn=>asn.status!=='rejected').map(asn=>asn.tagId) : [];
  const countForTag = tid => ASSETS.filter(a=>assetTagIds(a).includes(tid)).length;

  const toggleTag = tid => setSelTagIds(prev=>{const n=new Set(prev);n.has(tid)?n.delete(tid):n.add(tid);return n;});

  const baseAssets = ASSETS.filter(a=>{
    const mq = q.length<2||a.name.toLowerCase().includes(q.toLowerCase())||(a.db&&a.db.toLowerCase().includes(q.toLowerCase()))||a.tags.some(t=>t.toLowerCase().includes(q.toLowerCase()));
    if(!mq) return false;
    if(selTagIds.size===0) return true;
    const aids = assetTagIds(a);
    return [...selTagIds].every(tid=>aids.includes(tid)); // AND logic
  });
  const gResults=q.length>1?GLOSSARY_TERMS.filter(t=>t.term.toLowerCase().includes(q.toLowerCase())):[];

  const activePills = tagCtx ? [...selTagIds].map(tid=>tagCtx.getTagDef(tid)).filter(Boolean) : [];

  return <div className="fadeUp" style={{height:"100%",display:"flex",flexDirection:"column"}}>
    <Topbar breadcrumb={[{label:"Search & Discovery"}]}/>
    <div style={{flex:1,display:"flex",overflow:"hidden"}}>
      {/* Tag filter sidebar */}
      <div style={{width:200,flexShrink:0,borderRight:`1px solid ${T.border}`,background:T.bgSurface,overflowY:"auto",display:"flex",flexDirection:"column"}}>
        <div style={{padding:"10px 14px 8px",borderBottom:`1px solid ${T.border}`,display:"flex",alignItems:"center",gap:6}}>
          {Ic.tag(11)}<span style={{fontSize:11.5,fontWeight:700,color:T.text}}>Tags</span>
          {selTagIds.size>0&&<span style={{fontSize:9.5,fontWeight:700,padding:"1px 5px",borderRadius:99,background:T.accentDim,color:T.accent,border:`1px solid ${T.accent}33`,marginLeft:"auto"}}>{selTagIds.size}</span>}
        </div>
        {TAG_CATEGORIES.map(cat=>{
          const tags = tagsByCat(cat);
          const open = tagGroupOpen[cat];
          const selCount = tags.filter(td=>selTagIds.has(td.id)).length;
          return (
            <div key={cat} style={{borderBottom:`1px solid ${T.border}`}}>
              <button onClick={()=>setTagGroupOpen(p=>({...p,[cat]:!p[cat]}))} style={{width:"100%",display:"flex",alignItems:"center",gap:7,padding:"8px 14px",background:"transparent",border:"none",cursor:"pointer",textAlign:"left"}}
                onMouseEnter={e=>e.currentTarget.style.background=T.bgHover} onMouseLeave={e=>e.currentTarget.style.background="transparent"}>
                <span style={{flex:1,fontSize:11,fontWeight:600,color:T.text,textTransform:"capitalize"}}>{cat}</span>
                {selCount>0&&<span style={{fontSize:9,fontWeight:700,padding:"1px 4px",borderRadius:99,background:T.accentDim,color:T.accent}}>{selCount}</span>}
                <svg width="9" height="9" viewBox="0 0 10 10" fill="none" style={{color:T.textMuted,transform:open?"none":"rotate(-90deg)",transition:"transform .15s"}}><path d="M1.5 3.5l3.5 3.5 3.5-3.5" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round"/></svg>
              </button>
              {open&&tags.map(td=>{
                const active = selTagIds.has(td.id);
                const cnt = countForTag(td.id);
                return (
                  <button key={td.id} onClick={()=>toggleTag(td.id)} style={{width:"100%",display:"flex",alignItems:"center",gap:7,padding:"4px 14px 4px 20px",background:active?T.accentDim:"transparent",border:"none",cursor:"pointer",transition:"background .1s"}}
                    onMouseEnter={e=>{if(!active)e.currentTarget.style.background=T.bgHover;}} onMouseLeave={e=>{if(!active)e.currentTarget.style.background="transparent";}}>
                    <div style={{width:12,height:12,borderRadius:3,flexShrink:0,display:"flex",alignItems:"center",justifyContent:"center",background:active?T.accent:"transparent",border:`1.5px solid ${active?T.accent:T.borderLight}`,transition:"all .12s"}}>
                      {active&&<svg width="6" height="6" viewBox="0 0 8 8" fill="none"><path d="M1 4l2 2.5L7 1.5" stroke="white" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/></svg>}
                    </div>
                    <span style={{flex:1,fontSize:11,color:active?T.text:T.textSub,fontWeight:active?600:400,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{td.name}</span>
                    <span style={{fontSize:10,color:active?T.accent:T.textMuted,fontWeight:active?700:400}}>{cnt}</span>
                  </button>
                );
              })}
              {open&&tags.length===0&&<div style={{padding:"4px 20px 6px",fontSize:10.5,color:T.textMuted,fontStyle:"italic"}}>No tags</div>}
            </div>
          );
        })}
        {selTagIds.size>0&&<button onClick={()=>setSelTagIds(new Set())} style={{margin:"8px 14px",padding:"5px 10px",borderRadius:6,background:"transparent",border:`1px solid ${T.border}`,color:T.textMuted,fontSize:11,cursor:"pointer",textAlign:"center"}}
          onMouseEnter={e=>e.currentTarget.style.color=T.rose} onMouseLeave={e=>e.currentTarget.style.color=T.textMuted}>Clear tag filters</button>}
      </div>

      {/* Main results */}
      <div style={{flex:1,overflowY:"auto",padding:28}}>
        <div style={{marginBottom:20}}>
          <Input2 placeholder="Search by name, fully qualified name, or tag…" value={q} onChange={e=>setQ(e.target.value)} icon={Ic.search(16)}/>
          {(q.length>0||selTagIds.size>0)&&<div style={{fontSize:11,color:T.textMuted,marginTop:6}}>{baseAssets.length+gResults.length} result{baseAssets.length+gResults.length!==1?"s":""}{q.length>1?` for "${q}"`:""}</div>}
        </div>

        {/* Active tag filter pills */}
        {activePills.length>0&&(
          <div style={{display:"flex",gap:5,flexWrap:"wrap",marginBottom:14,alignItems:"center"}}>
            <span style={{fontSize:10.5,color:T.textMuted,fontWeight:600}}>Filtering by:</span>
            {activePills.map(td=>(
              <TagPill key={td.id} tagDef={td} size="sm" onRemove={()=>toggleTag(td.id)}/>
            ))}
          </div>
        )}

        {q.length===0&&selTagIds.size===0&&<>
          <div style={{fontSize:11,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.08em",marginBottom:10}}>Recent Searches</div>
          <div style={{display:"flex",gap:8,flexWrap:"wrap",marginBottom:24}}>
            {["orders","PII","Commerce","CLV","customers","ml_churn"].map(s=><button key={s} onClick={()=>setQ(s)} style={{padding:"5px 14px",borderRadius:99,background:T.bgElevated,border:`1px solid ${T.border}`,color:T.textSub,fontSize:12,cursor:"pointer"}}>{s}</button>)}
          </div>
          <div style={{fontSize:11,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.08em",marginBottom:10}}>Browse by Type</div>
          <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:8,marginBottom:24}}>
            {["Table","Dashboard","Pipeline","ML Model","Database","Data Product"].map(t=>(
              <button key={t} onClick={()=>setQ(t.toLowerCase())} style={{display:"flex",alignItems:"center",gap:9,padding:"10px 14px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:9,cursor:"pointer",color:T.textSub,fontSize:12,textAlign:"left",transition:"all .15s"}}
                onMouseEnter={e=>{e.currentTarget.style.borderColor=T.blue;e.currentTarget.style.color=T.text;}}
                onMouseLeave={e=>{e.currentTarget.style.borderColor=T.border;e.currentTarget.style.color=T.textSub;}}>
                <TypeBadge type={t}/>{t}
              </button>
            ))}
          </div>
          <div style={{fontSize:11,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.08em",marginBottom:10}}>Browse by Domain</div>
          <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
            {["Commerce","Finance","Product","ML","Marketing"].map(d=>(
              <button key={d} onClick={()=>setQ(d.toLowerCase())} style={{padding:"6px 14px",borderRadius:99,background:T.bgElevated,border:`1px solid ${T.border}`,color:T.textSub,fontSize:12,cursor:"pointer",transition:"all .15s"}}
                onMouseEnter={e=>{e.currentTarget.style.color=T.text;}}
                onMouseLeave={e=>{e.currentTarget.style.color=T.textSub;}}>{d}</button>
            ))}
          </div>
        </>}

        {(q.length>1||selTagIds.size>0)&&baseAssets.length>0&&<div style={{marginBottom:20}}>
          <div style={{fontSize:11,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.08em",marginBottom:10}}>Assets ({baseAssets.length})</div>
          <Card2 style={{overflow:"hidden",padding:0}}>
            {baseAssets.map((a,i)=>{
              const asns = tagCtx ? tagCtx.getAssetAssignments(a.id).filter(asn=>asn.status!=='rejected') : [];
              return (
                <div key={a.id} style={{display:"flex",alignItems:"center",gap:12,padding:"12px 16px",borderBottom:i<baseAssets.length-1?`1px solid ${T.border}`:"none",cursor:"pointer",transition:"background .1s"}}
                  onClick={()=>onAsset(a)}
                  onMouseEnter={e=>e.currentTarget.style.background=T.bgHover}
                  onMouseLeave={e=>e.currentTarget.style.background="transparent"}>
                  <TypeBadge type={a.type}/>
                  <div style={{flex:1}}>
                    <div style={{fontSize:13,fontFamily:"'Geist Mono',monospace",color:T.text}}>{a.name}</div>
                    <div style={{fontSize:11,color:T.textMuted}}>{a.db} · {a.domain}</div>
                    {asns.length>0&&(
                      <div style={{display:"flex",gap:3,flexWrap:"wrap",marginTop:4}} onClick={e=>e.stopPropagation()}>
                        {asns.slice(0,4).map(asn=>{
                          const td=tagCtx.getTagDef(asn.tagId);
                          return td?<TagPill key={asn.tagId} tagDef={td} assignment={asn} size="sm"/>:null;
                        })}
                        {asns.length>4&&<span style={{fontSize:10,padding:"1px 6px",borderRadius:99,background:T.bgElevated,color:T.textSub,border:`1px solid ${T.border}`,fontWeight:600}}>+{asns.length-4}</span>}
                      </div>
                    )}
                  </div>
                  <CertBadge cert={a.cert}/><QScore score={a.quality}/>{Ic.chevRight(12)}
                </div>
              );
            })}
          </Card2>
        </div>}
        {(q.length>1||selTagIds.size>0)&&baseAssets.length===0&&<div style={{padding:"40px 0",textAlign:"center",color:T.textMuted,fontSize:13}}>No assets match your search{selTagIds.size>0?" and tag filters":""}.</div>}

        {gResults.length>0&&<div>
          <div style={{fontSize:11,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.08em",marginBottom:10}}>Glossary ({gResults.length})</div>
          <Card2 style={{overflow:"hidden",padding:0}}>
            {gResults.map((t,i)=>(
              <div key={t.id} style={{display:"flex",alignItems:"center",gap:12,padding:"12px 16px",borderBottom:i<gResults.length-1?`1px solid ${T.border}`:"none",cursor:"pointer",transition:"background .1s"}}
                onMouseEnter={e=>e.currentTarget.style.background=T.bgHover}
                onMouseLeave={e=>e.currentTarget.style.background="transparent"}>
                <span style={{fontSize:18}}>📖</span>
                <div style={{flex:1}}><div style={{fontSize:13,fontWeight:500,color:T.text}}>{t.term}</div><div style={{fontSize:11,color:T.textMuted,lineHeight:1.6}}>{t.definition.slice(0,80)}…</div></div>
                <Badge color={t.status==="Approved"?T.green:T.amber}>{t.status}</Badge>
              </div>
            ))}
          </Card2>
        </div>}
      </div>
    </div>
  </div>;
};

// ─────────────────────────────────────────────
// TEAMS
// ─────────────────────────────────────────────
const TeamsView = ({onToast})=>{
  const [inviteModal,setInviteModal]=useState(false);
  const [form,setForm]=useState({email:"",role:"Data Analyst"});
  return <div className="fadeUp" style={{height:"100%",display:"flex",flexDirection:"column"}}>
    <Topbar breadcrumb={[{label:"Teams"}]}/>
    <div style={{flex:1,overflowY:"auto",padding:28}}>
      <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:12,marginBottom:24}}>
        <Metric label="Total Members" value={String(TEAMS_DATA.length)} color={T.accent}/>
        <Metric label="Active" value={String(TEAMS_DATA.filter(t=>t.status==="Active").length)} color={T.green}/>
        <Metric label="Domains" value="5" color={T.blue}/>
      </div>
      <div style={{display:"flex",justifyContent:"flex-end",marginBottom:12}}>
        <Btn icon={Ic.plus(12)} variant="primary" onClick={()=>setInviteModal(true)}>Invite Member</Btn>
      </div>
      <Card2 style={{overflow:"hidden",padding:0}}>
        <DataTable cols={[
          {key:"name",label:"User",render:(v,r)=><div style={{display:"flex",alignItems:"center",gap:9}}><div style={{width:30,height:30,borderRadius:8,background:T.bgHover,display:"flex",alignItems:"center",justifyContent:"center",fontSize:11,fontWeight:700,color:T.accent}}>{v[0].toUpperCase()}</div><div><div style={{fontSize:12,fontWeight:500,color:T.text}}>{v}</div><div style={{fontSize:11,color:T.textMuted}}>{r.email}</div></div></div>},
          {key:"role",label:"Role",render:v=><Badge color={T.violet} bg={T.violetDim}>{v}</Badge>},
          {key:"domain",label:"Domain",render:v=><span style={{fontSize:12,color:T.textSub}}>{v}</span>},
          {key:"assets",label:"Owned Assets",render:v=><span style={{fontFamily:"'Geist Mono',monospace",fontSize:12,color:T.blue}}>{v}</span>},
          {key:"joined",label:"Joined",render:v=><span style={{fontSize:11,color:T.textMuted}}>{v}</span>},
          {key:"status",label:"Status",render:v=><span style={{display:"flex",alignItems:"center",gap:5,fontSize:12}}><SDot status={v}/>{v}</span>},
          {key:"name",label:"",render:()=><div style={{display:"flex",gap:5}}><Btn small ghost>Edit</Btn><Btn small variant="danger">Remove</Btn></div>},
        ]} rows={TEAMS_DATA}/>
      </Card2>
    </div>
    <Modal open={inviteModal} onClose={()=>setInviteModal(false)} title="Invite Team Member">
      <div style={{display:"flex",flexDirection:"column",gap:12}}>
        <div><div style={{fontSize:12,color:T.textSub,marginBottom:6}}>Email Address</div><Input2 placeholder="user@solix.com" value={form.email} onChange={e=>setForm({...form,email:e.target.value})}/></div>
        <div><div style={{fontSize:12,color:T.textSub,marginBottom:6}}>Role</div>
          <select value={form.role} onChange={e=>setForm({...form,role:e.target.value})} style={{width:"100%",padding:"8px 12px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:7,color:T.text,fontSize:13,outline:"none"}}>
            {["Data Engineer","Data Analyst","Data Steward","Compliance Officer","ML Engineer","Business User"].map(r=><option key={r}>{r}</option>)}
          </select>
        </div>
        <div style={{display:"flex",gap:8,justifyContent:"flex-end",marginTop:8}}><Btn onClick={()=>setInviteModal(false)}>Cancel</Btn><Btn variant="primary" onClick={()=>{setInviteModal(false);onToast("Invitation sent","success");}}>Send Invite</Btn></div>
      </div>
    </Modal>
  </div>;
};

