const cpReqSet = (u)=>{ _cpReqs = typeof u==="function"?u(_cpReqs):u; _cpReqSubs.forEach(f=>f()); };
const requestPropChange = (req)=>cpReqSet(prev=>[{id:"cp-"+Date.now(), status:"pending", at:"just now", ...req}, ...prev]);
