const useCustomPropReqs = ()=>{ const [,f]=useState(0); useEffect(()=>{const fn=()=>f(n=>n+1);_cpReqSubs.add(fn);return()=>{_cpReqSubs.delete(fn);};},[]); return _cpReqs; };

// ── Shared bits for Custom Property value rendering ──
const cpIsEmpty = (v)=> v==null || v==="" || (Array.isArray(v)&&v.length===0);
// A stored value is invalid if its option was later removed from the definition's allowed values.
const cpValueValid = (def,v)=>{ if(cpIsEmpty(v)) return true; if(def.type==="enum") return (def.vals||[]).includes(v); if(def.type==="enumMulti"){ const arr=Array.isArray(v)?v:String(v).split(",").map(s=>s.trim()).filter(Boolean); return arr.every(x=>(def.vals||[]).includes(x)); } return true; };
// Level-2 format validation, checked on Save — catches paste / edge values the typed control can't.
// Returns an error string, or null when the value is fine (empty is allowed; Required is separate & advisory).
const cpValidate = (def,v)=>{
  if(cpIsEmpty(v)) return null;
  const s=String(v).trim();
  if(def.type==="integer") return /^-?\d+$/.test(s) ? null : "Enter a whole number.";
  if(def.type==="number")  return (s!=="" && !isNaN(Number(s))) ? null : "Enter a valid number.";
  if(def.type==="email")   return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s) ? null : "Enter a valid email address.";
  if(def.type==="date")    return isNaN(Date.parse(s)) ? "Enter a valid date (YYYY-MM-DD)." : null;
  if(def.type==="enum")      return (def.vals||[]).includes(s) ? null : "Select a value from the list.";
  if(def.type==="enumMulti"){ const arr=Array.isArray(v)?v:s.split(",").map(x=>x.trim()).filter(Boolean); return arr.every(x=>(def.vals||[]).includes(x)) ? null : "Remove options that are no longer allowed."; }
  return null;
};
const cpInitials = (h)=> String(h||"").split(/[.\s_@]/).filter(Boolean).map(x=>x[0]).slice(0,2).join("").toUpperCase();

// Read-only, formatted display of a value (chips / avatar / text) — no form controls.
const CPValueDisplay = ({def,value})=>{
  if(cpIsEmpty(value)) return <span style={{fontSize:12.5,color:T.textMuted,fontStyle:"italic"}}>Not set</span>;
  const chip=(txt)=><span style={{display:"inline-block",background:T.accentDim,color:T.accent,borderRadius:6,padding:"3px 9px",fontSize:12,fontWeight:600}}>{txt}</span>;
  const staleChip=(txt)=><span title="No longer an allowed value" style={{display:"inline-flex",alignItems:"center",gap:4,background:`${T.rose}12`,color:T.rose,border:`1px solid ${T.rose}40`,borderRadius:6,padding:"3px 9px",fontSize:12,fontWeight:600}}>{txt} ⚠</span>;
  if(def.type==="enum") return (def.vals||[]).includes(value)?chip(value):staleChip(value);
  if(def.type==="enumMulti"){ const arr=Array.isArray(value)?value:String(value).split(",").map(s=>s.trim()).filter(Boolean); return <span style={{display:"flex",flexWrap:"wrap",gap:6}}>{arr.map(v=><span key={v}>{(def.vals||[]).includes(v)?chip(v):staleChip(v)}</span>)}</span>; }
  if(def.type==="user") return <span style={{display:"inline-flex",alignItems:"center",gap:7,background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:20,padding:"3px 11px 3px 4px",fontSize:12,fontWeight:600,color:T.text}}><span style={{width:18,height:18,borderRadius:"50%",background:T.accent,color:"#fff",display:"flex",alignItems:"center",justifyContent:"center",fontSize:9}}>{cpInitials(value)}</span>{value}</span>;
  if(def.type==="markdown") return <span style={{fontSize:12.5,color:T.text,lineHeight:1.6,whiteSpace:"pre-wrap"}}>{value}</span>;
  return <span style={{fontSize:13,color:T.text,fontWeight:500}}>{value}</span>;
};

// Editable, typed control for one value.
const CPValueInput = ({def,value,onChange,invalid})=>{
  const baseS={width:"100%",maxWidth:340,padding:"8px 11px",background:T.bgElevated,border:`1.5px solid ${invalid?T.rose:T.border}`,borderRadius:8,color:T.text,fontSize:12.5,outline:"none",boxSizing:"border-box",fontFamily:"inherit"};
  const onF=e=>e.target.style.borderColor=T.accent, onB=e=>e.target.style.borderColor=invalid?T.rose:T.border;
  if(def.type==="enum"){
    const stale = value && !(def.vals||[]).includes(value);
    return <select value={value||""} onChange={e=>onChange(e.target.value)} style={{...baseS,cursor:"pointer",appearance:"auto",color:value?T.text:T.textMuted}} onFocus={onF} onBlur={onB}><option value="">Select…</option>{stale&&<option value={value}>{value} (no longer allowed)</option>}{(def.vals||[]).map(v=><option key={v} value={v}>{v}</option>)}</select>;
  }
  if(def.type==="enumMulti"){
    const arr=Array.isArray(value)?value:(value?String(value).split(",").map(s=>s.trim()).filter(Boolean):[]);
    return <div style={{display:"flex",flexWrap:"wrap",gap:6}}>{(def.vals||[]).map(v=>{ const on=arr.includes(v); return <button key={v} type="button" onClick={()=>onChange(on?arr.filter(x=>x!==v):[...arr,v])} style={{padding:"5px 11px",borderRadius:20,fontSize:11.5,fontWeight:600,cursor:"pointer",border:`1px solid ${on?T.accent:T.border}`,background:on?T.accentDim:T.bgElevated,color:on?T.accent:T.textSub}}>{on?"✓ ":""}{v}</button>; })}</div>;
  }
  if(def.type==="user")
    return <select value={value||""} onChange={e=>onChange(e.target.value)} style={{...baseS,cursor:"pointer",appearance:"auto",color:value?T.text:T.textMuted}} onFocus={onF} onBlur={onB}><option value="">Select…</option>{STEWARD_POOL.map(u=><option key={u} value={u}>{u}</option>)}</select>;
  if(def.type==="markdown")
    return <textarea value={value||""} onChange={e=>onChange(e.target.value)} rows={3} placeholder="Add a value…" style={{...baseS,maxWidth:"100%",resize:"vertical",lineHeight:1.5}} onFocus={onF} onBlur={onB}/>;
  const inputType=(def.type==="integer"||def.type==="number")?"number":def.type==="date"?"date":def.type==="email"?"email":"text";
  return <input type={inputType} value={value==null?"":value} onChange={e=>onChange(e.target.value)} placeholder="Add a value…" style={baseS} onFocus={onF} onBlur={onB}/>;
};

// The Custom Properties value panel shown on an asset/tag/domain detail page.
const CustomPropsPanel = ({entity,objectId,objectName,owners=[],stewards=[],onToast})=>{
  const allDefs=useCustomPropDefs();
  const vals=useCustomPropVals();
  const reqs=useCustomPropReqs();
  const {role:cpRole,roleCfg:cpCfg}=useRole();
  const me=((cpCfg&&cpCfg.email)||"you@jnj").split("@")[0];
  const defs=allDefs.filter(d=>d.entity===entity && !d.archived);
  const key=entity+"::"+objectId;
  const stored=vals[key]||{};
  const isOwner  = cpRole==="admin" || owners.includes(me) || owners[0]===me;
  const isSteward= stewards.includes(me);
  const readOnly = !isOwner && !isSteward;
  const [draft,setDraft]=useState(stored);
  const [showErrors,setShowErrors]=useState(false);
  const storedKey=JSON.stringify(stored);
  useEffect(()=>{ setDraft(vals[key]||{}); setShowErrors(false); },[key,storedKey]); // resync when object changes or a value is approved
  const setField=(id,v)=>setDraft(d=>({...d,[id]:v}));
  const same=(a,b)=>JSON.stringify(a??"")===JSON.stringify(b??"");
  const pendingFor=(id)=>reqs.find(r=>r.status==="pending"&&r.entity===entity&&r.targetId===objectId&&r.propId===id);
  const changed=defs.filter(d=>!pendingFor(d.id)&&!same(draft[d.id],stored[d.id]));
  const errorFor=(d)=>cpValidate(d,draft[d.id]);
  const blockedByErrors=()=>{ if(changed.some(d=>errorFor(d))){ setShowErrors(true); onToast&&onToast("Some values need fixing before saving","error"); return true; } return false; };
  const saveDirect=()=>{ if(blockedByErrors())return; changed.forEach(d=>setPropValue(entity,objectId,d.id,draft[d.id])); setShowErrors(false); onToast&&onToast(`Saved ${changed.length} propert${changed.length===1?"y":"ies"}`,"success"); };
  const sendRequests=()=>{ if(blockedByErrors())return; changed.forEach(d=>{ requestPropChange({entity,targetId:objectId,name:objectName,propId:d.id,propName:d.name,requestedValue:draft[d.id],requestedBy:me,note:"Requested via detail page",owner:owners[0]||null}); pushNotif({category:"Property",type:"field_updated",title:`Property change requested · ${objectName}`,body:`${me} requested ${d.name} → ${Array.isArray(draft[d.id])?draft[d.id].join(", "):draft[d.id]}`,nav:entity==="Tag"?"tags":entity==="Domain"?"domains":"catalog"}); }); onToast&&onToast(`Sent ${changed.length} change${changed.length===1?"":"s"} to the owner's Inbox`,"success"); setDraft(stored); setShowErrors(false); };
  const gate = readOnly
    ? {c:T.textMuted, ic:Ic.lock?Ic.lock(13):"🔒", txt:`Read-only — you're neither an owner nor a steward of this ${entity.toLowerCase()}.`}
    : isOwner
    ? {c:T.green, ic:"✓", txt:`You own this ${entity.toLowerCase()} — changes save directly.`}
    : {c:T.amber, ic:"✎", txt:"You're a steward — changes are sent to the owner's Inbox for approval."};

  if(defs.length===0)
    return <div style={{padding:"44px 20px",textAlign:"center",color:T.textMuted,fontSize:13,background:T.bgSurface,border:`1px dashed ${T.border}`,borderRadius:10,maxWidth:720}}>
      No custom properties defined for <b style={{color:T.textSub}}>{entity}</b> yet.<br/>An admin can add them in <b style={{color:T.textSub}}>Settings › Custom Properties</b>.
    </div>;

  return <div style={{maxWidth:720}}>
    <div style={{display:"flex",alignItems:"center",gap:9,padding:"10px 13px",borderRadius:9,background:`${gate.c}12`,border:`1px solid ${gate.c}33`,marginBottom:20}}>
      <span style={{color:gate.c,flexShrink:0,fontSize:13,display:"flex"}}>{gate.ic}</span>
      <span style={{fontSize:12.5,color:T.textSub}}>{gate.txt}</span>
    </div>
    <div style={{background:T.bgSurface,border:`1px solid ${T.border}`,borderRadius:11,overflow:"hidden"}}>
      {defs.map((d,idx)=>{ const pend=pendingFor(d.id); const editable=!readOnly&&!pend; const empty=cpIsEmpty(draft[d.id]); return (
        <div key={d.id} style={{display:"grid",gridTemplateColumns:"220px 1fr",gap:20,padding:"15px 18px",borderBottom:idx<defs.length-1?`1px solid ${T.border}`:"none",alignItems:"start"}}>
          <div>
            <div style={{display:"flex",alignItems:"center",gap:7,flexWrap:"wrap"}}>
              <span style={{fontSize:12.5,fontWeight:600,color:T.text}}>{d.name}</span>
              {d.required&&<span title="Required" style={{color:T.rose,fontSize:13,lineHeight:1}}>*</span>}
            </div>
            <div style={{display:"flex",alignItems:"center",gap:6,marginTop:5}}>
              <span style={{fontSize:9.5,fontWeight:700,textTransform:"uppercase",letterSpacing:"0.04em",color:T.textMuted,background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:4,padding:"2px 6px"}}>{CP_TYPE_LABEL[d.type]||d.type}</span>
              {pend&&<span style={{fontSize:9,fontWeight:700,color:T.amber,background:`${T.amber}14`,border:`1px solid ${T.amber}33`,borderRadius:20,padding:"2px 7px"}}>PENDING</span>}
            </div>
            {d.desc&&<div style={{fontSize:11,color:T.textMuted,marginTop:6,lineHeight:1.5}}>{d.desc}</div>}
          </div>
          <div style={{minWidth:0,paddingTop:1}}>
            {editable
              ? <CPValueInput def={d} value={draft[d.id]} onChange={v=>setField(d.id,v)} invalid={showErrors&&!!errorFor(d)}/>
              : <CPValueDisplay def={d} value={stored[d.id]}/>}
            {editable&&showErrors&&errorFor(d)&&<div style={{fontSize:10.5,color:T.rose,marginTop:5}}>{errorFor(d)}</div>}
            {editable&&d.required&&empty&&!(showErrors&&errorFor(d))&&<div style={{fontSize:10.5,color:T.rose,marginTop:5}}>This field is required.</div>}
            {!cpValueValid(d, editable?draft[d.id]:stored[d.id])&&<div style={{fontSize:10.5,color:T.rose,marginTop:5}}>Value is no longer an allowed option — please reselect.</div>}
            {pend&&<div style={{fontSize:10.5,color:T.amber,marginTop:5}}>A change to “{Array.isArray(pend.requestedValue)?pend.requestedValue.join(", "):pend.requestedValue}” is awaiting owner approval.</div>}
          </div>
        </div>
      );})}
    </div>
    {!readOnly&&changed.length>0&&(
      <div style={{display:"flex",alignItems:"center",gap:12,marginTop:16,padding:"12px 16px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:10}}>
        <span style={{fontSize:12.5,color:T.textSub,flex:1}}><b style={{color:T.text}}>{changed.length}</b> unsaved change{changed.length===1?"":"s"}{!isOwner&&" — will be sent for approval"}</span>
        <Btn ghost small onClick={()=>setDraft(stored)}>Discard</Btn>
        {isOwner
          ? <Btn variant="primary" small onClick={saveDirect}>Save change{changed.length===1?"":"s"}</Btn>
          : <Btn variant="primary" small onClick={sendRequests}>Send for approval</Btn>}
      </div>
    )}
  </div>;
};

// Admin editor (Settings) for a single custom-property DEFINITION — right-side drawer.
const newCPDraft = ()=>({id:"",name:"",machine:"",type:"string",entity:"Table",required:false,vals:[],refTarget:"Steward",desc:""});
const CustomPropDefEditor = ({editing,onClose,onToast})=>{
  const [d,setD]=useState(editing?{...editing,vals:editing.vals||[]}:newCPDraft());
  useEffect(()=>{ setD(editing?{...editing,vals:editing.vals||[]}:newCPDraft()); },[editing]);
  const set=(k,v)=>setD(p=>({...p,[k]:v}));
  const setName=v=>set("name",v);
  const isEnum=d.type==="enum"||d.type==="enumMulti";
  const inp={width:"100%",padding:"8px 11px",background:T.bgElevated,border:`1.5px solid ${T.border}`,borderRadius:8,color:T.text,fontSize:12.5,outline:"none",boxSizing:"border-box",fontFamily:"inherit"};
  const selS={...inp,cursor:"pointer",appearance:"auto"};
  const lbl={display:"block",fontSize:11,fontWeight:600,color:T.textSub,marginBottom:5};
  const opt={fontWeight:400,textTransform:"none",color:T.textMuted,fontSize:10.5};
  const onF=e=>e.target.style.borderColor=T.accent, onB=e=>e.target.style.borderColor=T.border;
  const save=()=>{
    const name = d.name.trim();
    if(!name){ onToast&&onToast("Give the property a name","error"); return; }
    if(_cpDefs.some(x=>x.id!==d.id && x.entity===d.entity && (x.name||"").trim().toLowerCase()===name.toLowerCase())){ onToast&&onToast(`A property "${name}" already exists for ${d.entity}`,"error"); return; }
    const vals = isEnum ? Array.from(new Set((Array.isArray(d.vals)?d.vals:String(d.vals).split(",")).map(s=>s.trim()).filter(Boolean))) : [];
    if(isEnum && vals.length===0){ onToast&&onToast("Add at least one allowed value","error"); return; }
    const def = {...d, id:d.id||("cp"+Date.now()), name, machine:cpSlug(name), vals, refTarget:d.type==="user"?d.refTarget:""};
    upsertPropDef(def);
    onToast&&onToast(editing?"Property updated":"Property added","success");
    onClose();
  };
  return <>
    <div onClick={onClose} style={{position:"fixed",inset:0,background:"rgba(0,0,0,.4)",zIndex:1200}}/>
    <div className="slideInRight" style={{position:"fixed",right:0,top:0,height:"100vh",width:460,maxWidth:"96vw",background:T.bgSurface,borderLeft:`1px solid ${T.border}`,zIndex:1201,display:"flex",flexDirection:"column",boxShadow:"-16px 0 48px rgba(0,0,0,.28)"}}>
      {/* Header */}
      <div style={{padding:"14px 22px",borderBottom:`1px solid ${T.border}`,flexShrink:0,display:"flex",justifyContent:"space-between",alignItems:"center",background:T.bgElevated}}>
        <div style={{display:"flex",alignItems:"center",gap:10}}>
          <div style={{width:30,height:30,borderRadius:7,background:T.accentDim,display:"flex",alignItems:"center",justifyContent:"center",color:T.accent}}>{Ic.props(15)}</div>
          <div>
            <div style={{fontSize:14.5,fontWeight:700,color:T.text}}>{editing?"Edit Custom Property":"New Custom Property"}</div>
            <div style={{fontSize:11.5,color:T.textMuted,marginTop:2}}>{editing?`Applies to every ${d.entity.toLowerCase()}.`:"A typed field that appears on every object of a type."}</div>
          </div>
        </div>
        <button onClick={onClose} style={{width:30,height:30,borderRadius:8,background:T.bgHover,border:`1px solid ${T.border}`,color:T.textMuted,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>{Ic.x(12)}</button>
      </div>

      {/* Body */}
      <div style={{flex:1,overflowY:"auto",minHeight:0,padding:"20px 22px"}}>
        <div style={{marginBottom:16}}>
          <label style={lbl}>Name <span style={{color:T.rose}}>*</span></label>
          <input value={d.name} onChange={e=>setName(e.target.value)} autoFocus placeholder="e.g. Data Retention Class" style={inp} onFocus={onF} onBlur={onB}/>
        </div>
        <div style={{marginBottom:16}}>
          <label style={lbl}>Applies to {editing&&<span style={opt}>· locked after creation</span>}</label>
          <select value={d.entity} disabled={!!editing} onChange={e=>set("entity",e.target.value)} style={{...selS,opacity:editing?0.55:1,cursor:editing?"not-allowed":"pointer"}}>{CP_ENTITY_GROUPS.map(g=><optgroup key={g.group} label={g.group}>{g.items.map(en=><option key={en} value={en}>{en}</option>)}</optgroup>)}</select>
        </div>
        <div style={{marginBottom:16}}>
          <label style={lbl}>Data type {editing&&<span style={opt}>· locked after creation</span>}</label>
          <select value={d.type} disabled={!!editing} onChange={e=>set("type",e.target.value)} style={{...selS,opacity:editing?0.55:1,cursor:editing?"not-allowed":"pointer"}}>{CP_TYPES.map(ty=><option key={ty.t} value={ty.t}>{ty.label} — {ty.hint}</option>)}</select>
          <div style={{fontSize:11,color:T.textMuted,marginTop:5}}>{editing?"Type and scope can't change once the property exists — create a new one to change them.":`Controls how the value is entered on every ${d.entity.toLowerCase()}.`}</div>
        </div>
        {isEnum&&<div style={{marginBottom:16}}>
          <label style={lbl}>Allowed values <span style={opt}>· comma separated</span></label>
          <input value={Array.isArray(d.vals)?d.vals.join(", "):d.vals} onChange={e=>set("vals",e.target.value.split(",").map(s=>s.trimStart()))} placeholder="Public, Internal, Confidential, Restricted" style={inp} onFocus={onF} onBlur={onB}/>
        </div>}
        {d.type==="user"&&<div style={{marginBottom:16}}>
          <label style={lbl}>Reference target</label>
          <select value={d.refTarget} onChange={e=>set("refTarget",e.target.value)} style={selS}><option>User</option><option>Team</option><option>Steward</option></select>
        </div>}
        <div style={{marginBottom:16}}>
          <label style={lbl}>Description <span style={opt}>· optional</span></label>
          <textarea value={d.desc} onChange={e=>set("desc",e.target.value)} rows={2} placeholder="Explain what this property captures." style={{...inp,resize:"vertical"}} onFocus={onF} onBlur={onB}/>
        </div>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",padding:"11px 13px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:8}}>
          <div><div style={{fontSize:12.5,fontWeight:600,color:T.text}}>Required</div><div style={{fontSize:11,color:T.textMuted}}>Flag instances that leave this empty.</div></div>
          <Toggle on={d.required} onChange={()=>set("required",!d.required)}/>
        </div>
      </div>

      {/* Footer */}
      <div style={{padding:"14px 22px",borderTop:`1px solid ${T.border}`,flexShrink:0,background:T.bgElevated,display:"flex",gap:8,justifyContent:"flex-end"}}>
        <Btn ghost onClick={onClose}>Cancel</Btn>
        <Btn variant="primary" onClick={save}>{editing?"Save":"Add"}</Btn>
      </div>
    </div>
  </>;
};

const InboxView = ({onToast}) => {
  const onNav = useNav();
  const { roleCfg: ibxRoleCfg } = useRole();
  const meHandle = ((ibxRoleCfg&&ibxRoleCfg.email)||"you@jnj").split("@")[0];
  const tagCtx = useTagCtx(); // tags live in TagProvider context — the tags "shared store"
  const contractApprovals = useContractApprovals();
  const [items,      setItems]      = useState([...POLICY_VIOLATION_INBOX, ...TAG_REVIEW_INBOX, ...CERT_REVIEW_INBOX, ...ORPHAN_INBOX, ...TERM_REVIEW_INBOX, ...INBOX_DATA.filter(i=>i.type!=="stewardship_request")]);
  const [filter,     setFilter]     = useState("action"); // action | activity | done
  const [viewMode,   setViewMode]   = useState("list");   // list | kanban
  const [roleScope,  setRoleScope]  = useState("all");    // all | steward | owner
  const [search,     setSearch]     = useState("");       // inbox search — applies to list + kanban
  const [sel,          setSel]          = useState(null);
  const [assignOpen,   setAssignOpen]   = useState(false);
  const [resolveOpen,  setResolveOpen]  = useState(false);  // inline resolve form (DQ + violations)
  const [resolveNote,  setResolveNote]  = useState("");     // resolution reason captured in the inbox
  const [resolveMode,  setResolveMode]  = useState("remediate"); // violations: remediate | exception
  const [bulkOpen,     setBulkOpen]     = useState(false);  // bulk-assign orphans picker
  const [filterOpen,   setFilterOpen]   = useState(false);
  const [roleOpen,     setRoleOpen]     = useState(false);
  const [secFilters,   setSecFilters]   = useState(new Set()); // section multiselect
  const closeForms = ()=>{ [setAssignOpen,setResolveOpen].forEach(f=>f(false)); setResolveNote(""); setResolveMode("remediate"); };

  // ── Two questions: things to DO vs things to KNOW ──
  // action   = open work needing a decision (steward fixes / owner sign-offs)
  // activity = passive FYI feed (field changes, assignments) — no action needed
  // done     = resolved action items (the archive)
  const secFilterActive = secFilters.size > 0;
  // bottom-up role requests (asset owner/steward) → owner approval items, merged live
  const roleReqs = useRoleReqs();
  const ROLE_REQ_ITEMS = roleReqs.filter(r=>r.status==="pending").map(r=> r.kind==="rbac" ? ({
    id:"rbq-"+r.id, type:"rbac_request", severity:"medium", section:"connections", timeAgo:r.at||"just now",
    asset:{name:r.requestedBy, path:"Platform role · "+r.targetRole, type:"Role"},
    body:`Requests the ${r.targetRole} platform role — "${r.note}"`,
    requestedBy:r.requestedBy, targetRole:r.targetRole, reqId:r.id, readAt:null,
  }) : ({
    id:"rrq-"+r.id, type:"stewardship_request", severity:"medium", section:"catalog", timeAgo:r.at||"just now",
    asset:{name:r.asset, path:r.asset, type:"Table"}, body:`${r.requestedBy} requested to be ${r.role} — "${r.note}"`,
    requestedBy:r.requestedBy, requestedRole:r.role==="owner"?"Owner":"Steward", reqId:r.id, readAt:null,
  }));
  // top-down status-change requests (tag/domain — assets keep their own certification flow) → steward approval items
  const statusReqs = useStatusReqs();
  const STATUS_REQ_ITEMS = statusReqs.filter(r=>r.status==="pending").map(r=>({
    id:"srq-"+r.id, type:"certification_review", severity:"medium", section:r.kind==="tag"?"tags":r.kind==="policy"?"policy":r.kind==="term"?"glossary":"catalog", timeAgo:r.at||"just now",
    asset:{name:r.name, path:r.kind==="tag"?"Tag · Classifications":r.kind==="policy"?"Policy · Policy Manager":r.kind==="term"?"Term · Glossary":r.kind==="cert"?"Status · Catalog":"Domain · Data Domains", type:r.kind==="tag"?"Tag":r.kind==="policy"?"Policy":r.kind==="term"?"Term":r.kind==="cert"?"Table":"Domain"},
    body:`${r.requestedBy} requested status → ${r.requestedStatus} — "${r.note||""}"`,
    requestedBy:r.requestedBy, requestedStatus:r.requestedStatus, reqKind:r.kind, reqTargetId:r.targetId, reqId:r.id, readAt:null,
  }));
  // top-down deletion requests (tag/domain) → owner approval items
  const deleteReqs = useDeleteReqs();
  const DELETE_REQ_ITEMS = deleteReqs.filter(r=>r.status==="pending").map(r=>({
    id:"drq-"+r.id, type:"delete_request", severity:"high", section:r.kind==="tag"?"tags":r.kind==="term"?"glossary":"catalog", timeAgo:r.at||"just now",
    asset:{name:r.name, path:r.kind==="tag"?"Tag · Classifications":r.kind==="term"?"Term · Glossary":"Domain · Data Domains", type:r.kind==="tag"?"Tag":r.kind==="term"?"Term":"Domain"},
    body:`${r.requestedBy} requested to delete this ${r.kind} — "${r.note||""}"`,
    requestedBy:r.requestedBy, reqKind:r.kind, reqTargetId:r.targetId, reqId:r.id, readAt:null,
  }));
  // enforcement approval requests (Policy Manager rules with "Enforce in place") → table owner approval items
  const enfReqs = useEnfApprovals();
  const ENF_APPROVAL_ITEMS = enfReqs.filter(r=>r.status==="pending").map(r=>({
    id:"eaq-"+r.id, type:"enforcement_approval", severity:"medium", section:"policy", timeAgo:r.at||"just now",
    title:r.action==="Unhold" ? `Approve release of legal hold on ${r.table}`
        : r.action==="Partial Unhold" ? `Approve partial unhold on ${r.table} · ${r.count||(r.keys||[]).length} record${((r.count||(r.keys||[]).length)>1)?"s":""}`
        : `Approve ${r.action} on ${r.table}`,
    asset:{name:r.table||"asset", path:r.table||"asset", type:"Table"},
    body:r.action==="Unhold"
      ? `${r.policyName} requests release of the legal hold on ${r.table}. Requested by ${r.requestedBy}.`
      : r.action==="Partial Unhold"
      ? `${r.policyName} requests release of ${r.count||(r.keys||[]).length} record${((r.count||(r.keys||[]).length)>1)?"s":""} from the legal hold on ${r.table}${r.reason?` — "${r.reason}"`:""}. The rest of the hold stays active. Requested by ${r.requestedBy}.`
      : `${r.policyName} wants to ${(r.action||"enforce").toLowerCase()} on ${r.table}. Requested by ${r.requestedBy}.`,
    requestedBy:r.requestedBy, action:r.action, policyId:r.policyId, ruleId:r.ruleId, baseRuleId:r.baseRuleId, keys:r.keys, reason:r.reason, count:r.count, reqId:r.id, readAt:null,
  }));
  // custom-property value-change requests (steward → owner approval)
  const propReqs = useCustomPropReqs();
  const PROP_REQ_ITEMS = propReqs.filter(r=>r.status==="pending").map(r=>({
    id:"cpq-"+r.id, type:"property_change", severity:"medium", section:r.entity==="Tag"?"tags":r.entity==="Domain"?"domains":"catalog", timeAgo:r.at||"just now",
    asset:{name:r.name, path:`${r.propName} · Custom Property`, type:r.entity},
    body:`${r.requestedBy} set ${r.propName} → "${Array.isArray(r.requestedValue)?r.requestedValue.join(", "):r.requestedValue}" — "${r.note||""}"`,
    requestedBy:r.requestedBy, entity:r.entity, reqTargetId:r.targetId, propId:r.propId, propName:r.propName, requestedValue:r.requestedValue, reqId:r.id, readAt:null,
  }));
  // Knowledge Layer approvals — a proposed governed build, or a trust-dial change
  // a non-admin wants applied. Both are decided by the owner/admin, not the requester.
  const klReqs = useKLReqs();
  const KL_REQ_ITEMS = klReqs.filter(r=>r.status==="pending").map(r=>({
    id:"klq-"+r.id, type:r.kind==="dial"?"kl_dial_approval":"kl_build_approval", severity:"medium",
    section:"knowledge", timeAgo:r.at||"just now",
    asset:{name:r.name, path:r.kind==="dial"?"Trust dial · Knowledge Layer":`Governed build · ${r.name}`,
           type:r.kind==="dial"?"Setting":"Knowledge Graph"},
    body:r.body, requestedBy:r.requestedBy, klKind:r.kind, klTargetId:r.targetId,
    klPayload:r.payload, reqId:r.id, readAt:null,
  }));
  const allItems = [...contractApprovals.filter(ca=>!items.some(i=>i.id===ca.id)), ...ROLE_REQ_ITEMS, ...STATUS_REQ_ITEMS, ...DELETE_REQ_ITEMS, ...ENF_APPROVAL_ITEMS, ...PROP_REQ_ITEMS, ...KL_REQ_ITEMS, ...items];
  const isActionItem   = i => itemRole(i)!=="fyi" && !i.readAt;
  const isActivityItem = i => itemRole(i)==="fyi";
  const isDoneItem     = i => itemRole(i)!=="fyi" && !!i.readAt;
  const actionItems   = allItems.filter(isActionItem);
  const activityItems = allItems.filter(isActivityItem);
  const doneItems     = allItems.filter(isDoneItem);
  const roleMatch = i => roleScope==="all" || itemRole(i)===roleScope;
  const secMatch  = i => !secFilterActive || secFilters.has(i.section);
  const _q = search.trim().toLowerCase();
  const searchMatch = i => !_q || ((i.title||"")+" "+(i.asset?.name||"")+" "+(i.asset?.path||"")+" "+(i.asset?.fqn||i.asset?.path||"")).toLowerCase().includes(_q);
  const counts = {
    action:   actionItems.length,
    activity: activityItems.filter(i=>!i.readAt).length,
    done:     doneItems.length,
  };
  const isDoneFilter = filter==="done";
  const shown =
      filter==="activity" ? activityItems.filter(secMatch).filter(searchMatch)
    : filter==="done"     ? []
    :                       actionItems.filter(roleMatch).filter(secMatch).filter(searchMatch);
  const doneShown = doneItems.filter(secMatch).filter(searchMatch);
  const SECTIONS = [
    {k:"catalog",  l:"Catalog"},
    {k:"quality",  l:"Data Quality"},
    {k:"policy",   l:"Policy"},
    {k:"glossary", l:"Glossary"},
    {k:"tags",     l:"Tags"},
    {k:"knowledge",l:"Knowledge Layer"},
  ];
  const toggleSec = s => setSecFilters(prev=>{ const n=new Set(prev); n.has(s)?n.delete(s):n.add(s); return n; });

  const selItem = allItems.find(i=>i.id===sel)||null;
  const selIdx  = shown.findIndex(i=>i.id===sel);
  const navPrev = ()=>{ if(selIdx>0) { setSel(shown[selIdx-1].id); closeForms(); }};
  const navNext = ()=>{ if(selIdx<shown.length-1) { setSel(shown[selIdx+1].id); closeForms(); }};

  const ack     = (id,msg)=>{ setItems(p=>p.map(i=>i.id===id?{...i,readAt:new Date().toISOString()}:i)); _contractApprovalItems=_contractApprovalItems.map(i=>i.id===id?{...i,readAt:new Date().toISOString()}:i); _contractApprovalSubs.forEach(fn=>fn()); setSel(null); closeForms(); onToast(msg||"Acknowledged","success"); };
  const dism    = id      =>{ setItems(p=>p.map(i=>i.id===id?{...i,readAt:new Date().toISOString()}:i)); _contractApprovalItems=_contractApprovalItems.map(i=>i.id===id?{...i,readAt:new Date().toISOString()}:i); _contractApprovalSubs.forEach(fn=>fn()); setSel(null); closeForms(); };
  const markAll = ()      =>{ setItems(p=>p.map(i=>({...i,readAt:i.readAt||new Date().toISOString()}))); setSel(null); closeForms(); onToast("All caught up","success"); };
  // Assignee display only — real reassignment isn't implemented yet (add when there's a
  // real workflow behind it, not just a label that resets on reload).
  const effAssignee = (item)=> itemAssignee(item) || "unassigned";

  const SEV = {
    high:  {c:T.rose,    bg:`${T.rose}12`,         label:"HIGH"},
    medium:{c:T.amber,   bg:`${T.amber}12`,         label:"MED"},
    low:   {c:T.blue,    bg:`${T.blue}0d`,          label:"INFO"},
    info:  {c:"#8b5cf6", bg:"rgba(139,92,246,.1)",  label:"NEW"},
  };
  const TYPE_META = {
    dq_alert:            {icon:sz=>Ic.quality(sz||12),  label:"DQ Alert",       shortLabel:"DQ Alert"},
    field_updated:       {icon:sz=>Ic.edit(sz||12),     label:"Field Updated",  shortLabel:"Updated"},
    assigned:            {icon:sz=>Ic.steward(sz||12),  label:"New Assignment", shortLabel:"Assigned"},
    needs_attention:     {icon:sz=>Ic.alert(sz||12),    label:"Needs Steward",  shortLabel:"Action"},
    stewardship_request: {icon:sz=>Ic.persona(sz||12),  label:"Role Request",   shortLabel:"Request"},
    rbac_request:        {icon:sz=>Ic.access(sz||12),   label:"Platform Role",  shortLabel:"Role"},
    policy_violation:    {icon:sz=>Ic.policies(sz||12), label:"Policy Violation",shortLabel:"Violation"},
    tag_review:          {icon:sz=>Ic.tag(sz||12),     label:"Tag Review",     shortLabel:"Tag"},
    certification_review:{icon:sz=>Ic.cert(sz||12),    label:"Status change",  shortLabel:"Status"},
    orphan_assignment:   {icon:sz=>Ic.steward(sz||12), label:"Orphan — Assign Owner", shortLabel:"Orphan"},
    term_review:         {icon:sz=>Ic.glossary(sz||12),label:"Term Review",     shortLabel:"Term"},
    contract_approval:   {icon:sz=>Ic.contracts(sz||12),label:"Contract Approval",shortLabel:"Contract"},
    delete_request:      {icon:sz=>Ic.trash(sz||12),    label:"Deletion Request", shortLabel:"Delete"},
    enforcement_approval:{icon:sz=>Ic.policies(sz||12), label:"Enforcement Approval", shortLabel:"Enforce"},
    property_change:     {icon:sz=>Ic.props(sz||12),    label:"Property Change",  shortLabel:"Property"},
    kl_build_approval:   {icon:sz=>Ic.knowledge(sz||12),label:"Governed Build",   shortLabel:"Build"},
    kl_dial_approval:    {icon:sz=>Ic.knowledge(sz||12),label:"Trust Dial",       shortLabel:"Dial"},
  };

  /* ── Action row — only inside detail panel ── */
  const ActionRow = ({item}) => {
    const btn = (label,onClick,primary=false,danger=false)=>(
      <button onClick={onClick} style={{padding:"7px 18px",borderRadius:7,background:primary?T.accent:"transparent",border:primary?"none":danger?`1px solid ${T.rose}55`:`1px solid ${T.border}`,color:primary?"#fff":danger?T.rose:T.textSub,fontSize:12,fontWeight:primary?600:500,cursor:"pointer",whiteSpace:"nowrap",transition:"opacity .1s"}}
        onMouseEnter={e=>e.currentTarget.style.opacity="0.8"} onMouseLeave={e=>e.currentTarget.style.opacity="1"}>
        {label}
      </button>
    );
    // Consistent action template for every event:
    //   [ Primary action ] · [ Secondary: Reject (approvals) / Dismiss (alerts) / domain action ] · [ Open in {section} ]
    const openIn = (label,nav,arg)=>btn(label,()=>{onNav&&onNav(nav,arg);});
    if(item.type==="kl_build_approval" || item.type==="kl_dial_approval"){
      const isDial = item.type==="kl_dial_approval";
      return <>{btn(isDial?"Approve change":"Approve build",()=>{
          (isDial ? _klApply.applyDial : _klApply.approveBuild)?.(item.klTargetId, item.klPayload, item.requestedBy, meHandle);
          resolveKLRequest(item.reqId,"approved");
          pushNotif({category:"Knowledge Layer", type:"cert",
            title:isDial?`Trust dial applied · ${item.asset.name}`:`Governed build approved · ${item.asset.name}`,
            body:`Approved by ${meHandle||"owner"} — ${item.requestedBy} notified`, nav:"knowledgelayer"});
          ack(item.id, isDial?"Trust dial applied — requester notified":"Build approved and set as the new baseline");
        },true)}
        {btn("Reject",()=>{
          resolveKLRequest(item.reqId,"rejected");
          pushNotif({category:"Knowledge Layer", type:"field_updated",
            title:`Request rejected · ${item.asset.name}`,
            body:`${item.requestedBy}'s request was declined — nothing changed`, nav:"knowledgelayer"});
          ack(item.id,"Rejected — the existing baseline stands");
        },false,true)}
        {openIn("Open in Knowledge Layer","knowledgelayer")}</>;
    }
    if(item.type==="dq_alert")
      return <>{btn("Resolve",()=>setResolveOpen(true),true)}{btn("Dismiss",()=>dism(item.id))}{openIn("Open in Data Quality","quality")}</>;
    if(item.type==="policy_violation")
      return <>{btn("Resolve",()=>setResolveOpen(true),true)}{btn("Dismiss",()=>dism(item.id))}{openIn("Open in Policy Manager","policymanager",{policyId:item.policyId})}</>;
    if(item.type==="tag_review")
      return <>{btn("Approve",()=>{
        if(item.tagType==="new_source_tag"){ tagCtx?.createTagDef({name:item.tagName,category:'business',description:'Promoted from source tag via Inbox.',propagationMode:'hierarchy',governanceRequired:false,managedBy:'Current User',color:'#fbbf24',sourceAliases:[item.tagName]}); tagCtx?.resolveInboxItem(item.tagInboxId,'promoted'); }
        else { tagCtx?.resolveInboxItem(item.tagInboxId,'approve'); }
        ack(item.id,`${item.tagName} approved`);
      },true)}{btn("Reject",()=>{tagCtx?.resolveInboxItem(item.tagInboxId,'reject');ack(item.id,"Tag rejected");},false,true)}{openIn("Open in Classifications","tags")}</>;
    if(item.type==="term_review")
      return <>{btn("Approve",()=>{setTermStatus(item.termId,"Approved");ack(item.id,`${item.asset.name} approved & published`);},true)}{btn("Reject",()=>{setTermStatus(item.termId,"Draft");ack(item.id,"Term sent back to draft");},false,true)}{openIn("Open in Glossary","glossary")}</>;
    if(item.type==="certification_review"){
      if(item.reqKind==="tag")
        return <>{btn("Approve",()=>{tagCtx?.updateTagDef(item.reqTargetId,{cert:item.requestedStatus});if(item.reqId)resolveStatusRequest(item.reqId,"approved");pushNotif({category:"Status",type:"cert",title:`Status changed to ${item.requestedStatus} · ${item.asset.name}`,body:`Approved by ${meHandle||"steward"}`,nav:"tags",navArg:{tagId:item.reqTargetId}});ack(item.id,`${item.asset.name} status → ${item.requestedStatus} — requester notified`);},true)}{btn("Reject",()=>{tagCtx?.updateTagDef(item.reqTargetId,{cert:"Draft"});if(item.reqId)resolveStatusRequest(item.reqId,"rejected");pushNotif({category:"Status",type:"field_updated",title:`Status change rejected · ${item.asset.name}`,body:`${item.requestedBy}'s request was sent back to Draft`,nav:"tags",navArg:{tagId:item.reqTargetId}});ack(item.id,"Status change rejected — sent back to Draft");},false,true)}{openIn("Open in Classifications","tags")}</>;
      if(item.reqKind==="domain")
        return <>{btn("Approve",()=>{domainsSet(prev=>prev.map(d=>d.id===item.reqTargetId?{...d,cert:item.requestedStatus}:d));if(item.reqId)resolveStatusRequest(item.reqId,"approved");pushNotif({category:"Status",type:"cert",title:`Status changed to ${item.requestedStatus} · ${item.asset.name}`,body:`Approved by ${meHandle||"steward"}`,nav:"domains",navArg:{domainId:item.reqTargetId}});ack(item.id,`${item.asset.name} status → ${item.requestedStatus} — requester notified`);},true)}{btn("Reject",()=>{domainsSet(prev=>prev.map(d=>d.id===item.reqTargetId?{...d,cert:"Draft"}:d));if(item.reqId)resolveStatusRequest(item.reqId,"rejected");pushNotif({category:"Status",type:"field_updated",title:`Status change rejected · ${item.asset.name}`,body:`${item.requestedBy}'s request was sent back to Draft`,nav:"domains",navArg:{domainId:item.reqTargetId}});ack(item.id,"Status change rejected — sent back to Draft");},false,true)}{openIn("Open in Domains","domains")}</>;
      if(item.reqKind==="policy")
        return <>{btn("Approve",()=>{
          polSet(prev=>prev.map(pp=>pp.id===item.reqTargetId?{...pp,lifecycle:item.requestedStatus,updated:new Date().toISOString().slice(0,10),history:[{when:new Date().toISOString().slice(0,10),who:meHandle||"steward",action:item.requestedStatus},...(pp.history||[])]}:pp));
          if(item.reqId)resolveStatusRequest(item.reqId,"approved");
          pushNotif({category:"Status",type:"cert",title:`Status changed to ${item.requestedStatus} · ${item.asset.name}`,body:`Approved by ${meHandle||"steward"}`,nav:"policymanager",navArg:{policyId:item.reqTargetId}});
          ack(item.id,`${item.asset.name} status → ${item.requestedStatus} — requester notified`);
        },true)}{btn("Reject",()=>{
          polSet(prev=>prev.map(pp=>pp.id===item.reqTargetId?{...pp,lifecycle:"Draft",updated:new Date().toISOString().slice(0,10),history:[{when:new Date().toISOString().slice(0,10),who:meHandle||"steward",action:"Rejected — sent back to draft"},...(pp.history||[])]}:pp));
          if(item.reqId)resolveStatusRequest(item.reqId,"rejected");
          pushNotif({category:"Status",type:"field_updated",title:`Status change rejected · ${item.asset.name}`,body:`${item.requestedBy}'s request was sent back to Draft`,nav:"policymanager",navArg:{policyId:item.reqTargetId}});
          ack(item.id,"Status change rejected — sent back to Draft");
        },false,true)}{openIn("Open in Policy Manager","policymanager",{policyId:item.reqTargetId})}</>;
      if(item.reqKind==="term")
        return <>{btn("Approve",()=>{
          setTermStatus(item.reqTargetId,item.requestedStatus);
          if(item.reqId)resolveStatusRequest(item.reqId,"approved");
          pushNotif({category:"Status",type:"cert",title:`Status changed to ${item.requestedStatus} · ${item.asset.name}`,body:`Approved by ${meHandle||"steward"}`,nav:"glossary",navArg:{termId:item.reqTargetId}});
          ack(item.id,`${item.asset.name} status → ${item.requestedStatus} — requester notified`);
        },true)}{btn("Reject",()=>{
          setTermStatus(item.reqTargetId,"Draft");
          if(item.reqId)resolveStatusRequest(item.reqId,"rejected");
          pushNotif({category:"Status",type:"field_updated",title:`Status change rejected · ${item.asset.name}`,body:`${item.requestedBy}'s request was sent back to Draft`,nav:"glossary",navArg:{termId:item.reqTargetId}});
          ack(item.id,"Status change rejected — sent back to Draft");
        },false,true)}{openIn("Open in Glossary","glossary")}</>;
      if(item.reqKind==="cert")
        return <>{btn("Approve",()=>{
          certSet(prev=>prev.map(c=>c.id===item.reqTargetId?{...c,status:item.requestedStatus,certifier:item.requestedStatus==="Approved"?(meHandle||"steward"):c.certifier,date:item.requestedStatus==="Approved"?new Date().toISOString().slice(0,10):c.date}:c));
          if(item.reqId)resolveStatusRequest(item.reqId,"approved");
          pushNotif({category:"Status",type:"cert",title:`Status changed to ${item.requestedStatus} · ${item.asset.name}`,body:`Approved by ${meHandle||"steward"}`,nav:"catalog"});
          ack(item.id,`${item.asset.name} status → ${item.requestedStatus} — requester notified`);
        },true)}{btn("Reject",()=>{
          certSet(prev=>prev.map(c=>c.id===item.reqTargetId?{...c,status:"Draft",certifier:null,date:null}:c));
          if(item.reqId)resolveStatusRequest(item.reqId,"rejected");
          pushNotif({category:"Status",type:"field_updated",title:`Status change rejected · ${item.asset.name}`,body:`${item.requestedBy}'s request was sent back to Draft`,nav:"catalog"});
          ack(item.id,"Status change rejected — sent back to Draft");
        },false,true)}{openIn("Open in Catalog","catalog")}</>;
      return <>{btn("Approve",()=>{certifyByAsset(item.asset.name);certifyAsset(item.asset.name);ack(item.id,`${item.asset.name} status → Approved`);},true)}{btn("Reject",()=>{certSet(prev=>prev.map(c=>c.asset===item.asset.name?{...c,status:"Rejected",certifier:null,date:null}:c));ack(item.id,"Status change rejected");},false,true)}{openIn("Open in Catalog","catalog")}</>;
    }
    if(item.type==="stewardship_request")
      return <>{btn("Approve",()=>{const role=item.requestedRole==="Owner"?"owner":"steward";assignOwnership(item.asset.name,item.requestedBy,role);if(item.reqId)resolveRoleRequest(item.reqId,"approved");ack(item.id,`${item.requestedBy} added as ${item.requestedRole} of ${item.asset.name} — requester notified`);},true)}{btn("Reject",()=>{if(item.reqId)resolveRoleRequest(item.reqId,"rejected");ack(item.id,"Request rejected — requester notified");},false,true)}{openIn("Open in Catalog","catalog")}</>;
    if(item.type==="rbac_request")
      return <>{btn("Grant role",()=>{if(item.reqId)resolveRoleRequest(item.reqId,"approved");ack(item.id,`${item.targetRole} role granted to ${item.requestedBy} — requester notified`);},true)}{btn("Reject",()=>{if(item.reqId)resolveRoleRequest(item.reqId,"rejected");ack(item.id,"Role request rejected — requester notified");},false,true)}{openIn("Open in Access","access")}</>;
    if(item.type==="delete_request"){
      if(item.reqKind==="tag")
        return <>{btn("Approve deletion",()=>{tagCtx?.deleteTagDef(item.reqTargetId);if(item.reqId)resolveDeleteRequest(item.reqId,"approved");pushNotif({category:"Ownership",type:"alert",title:`${item.asset.name} deleted (tag)`,body:`Deletion approved by ${meHandle||"owner"}`,nav:"tags"});ack(item.id,`${item.asset.name} deleted — requester notified`);},true)}{btn("Reject",()=>{if(item.reqId)resolveDeleteRequest(item.reqId,"rejected");pushNotif({category:"Ownership",type:"field_updated",title:`Deletion request rejected · ${item.asset.name}`,body:`${item.requestedBy}'s request to delete this tag was declined`,nav:"tags",navArg:{tagId:item.reqTargetId}});ack(item.id,"Deletion request rejected — requester notified");},false,true)}{openIn("Open in Classifications","tags")}</>;
      if(item.reqKind==="domain")
        return <>{btn("Approve deletion",()=>{domainsSet(prev=>prev.filter(d=>d.id!==item.reqTargetId));if(item.reqId)resolveDeleteRequest(item.reqId,"approved");pushNotif({category:"Ownership",type:"alert",title:`${item.asset.name} deleted (domain)`,body:`Deletion approved by ${meHandle||"owner"}`,nav:"domains"});ack(item.id,`${item.asset.name} deleted — requester notified`);},true)}{btn("Reject",()=>{if(item.reqId)resolveDeleteRequest(item.reqId,"rejected");pushNotif({category:"Ownership",type:"field_updated",title:`Deletion request rejected · ${item.asset.name}`,body:`${item.requestedBy}'s request to delete this domain was declined`,nav:"domains",navArg:{domainId:item.reqTargetId}});ack(item.id,"Deletion request rejected — requester notified");},false,true)}{openIn("Open in Domains","domains")}</>;
      if(item.reqKind==="term")
        return <>{btn("Approve deletion",()=>{gtSet(prev=>prev.filter(t=>t.id!==item.reqTargetId));if(item.reqId)resolveDeleteRequest(item.reqId,"approved");pushNotif({category:"Ownership",type:"alert",title:`${item.asset.name} deleted (term)`,body:`Deletion approved by ${meHandle||"owner"}`,nav:"glossary"});ack(item.id,`${item.asset.name} deleted — requester notified`);},true)}{btn("Reject",()=>{if(item.reqId)resolveDeleteRequest(item.reqId,"rejected");pushNotif({category:"Ownership",type:"field_updated",title:`Deletion request rejected · ${item.asset.name}`,body:`${item.requestedBy}'s request to delete this term was declined`,nav:"glossary",navArg:{termId:item.reqTargetId}});ack(item.id,"Deletion request rejected — requester notified");},false,true)}{openIn("Open in Glossary","glossary")}</>;
      return null;
    }
    if(item.type==="property_change"){
      const navTo = item.entity==="Tag"?"tags":item.entity==="Domain"?"domains":"catalog";
      const openLabel = item.entity==="Tag"?"Open in Classifications":item.entity==="Domain"?"Open in Domains":"Open in Catalog";
      const valTxt = Array.isArray(item.requestedValue)?item.requestedValue.join(", "):item.requestedValue;
      return <>{btn("Approve",()=>{
        setPropValue(item.entity,item.reqTargetId,item.propId,item.requestedValue);
        if(item.reqId)resolvePropRequest(item.reqId,"approved");
        pushNotif({category:"Property",type:"cert",title:`${item.propName} updated · ${item.asset.name}`,body:`Approved by ${meHandle||"owner"} — set to ${valTxt}`,nav:navTo});
        ack(item.id,`${item.propName} → ${valTxt} — requester notified`);
      },true)}{btn("Reject",()=>{
        if(item.reqId)resolvePropRequest(item.reqId,"rejected");
        pushNotif({category:"Property",type:"field_updated",title:`Property change rejected · ${item.asset.name}`,body:`${item.requestedBy}'s change to ${item.propName} was declined`,nav:navTo});
        ack(item.id,"Property change rejected — requester notified");
      },false,true)}{openIn(openLabel,navTo)}</>;
    }
    if(item.type==="enforcement_approval"){
      if(item.action==="Unhold"){
        const baseRuleId = (item.ruleId||"").replace(/-unhold$/,"");
        return <>{btn("Approve release",()=>{
          if(item.reqId)resolveEnfApproval(item.reqId,"approved");
          polSet(prev=>prev.map(pp=>pp.id===item.policyId?{...pp,rules:(pp.rules||[]).filter(r=>r.id!==baseRuleId)}:pp));
          pushNotif({category:"Policy",type:"cert",title:`Legal hold released · ${item.asset.name}`,body:`The hold on ${item.asset.name} was released by ${meHandle||"owner"} — the table is no longer under legal hold.`,nav:"policymanager",navArg:{policyId:item.policyId}});
          ack(item.id,`Legal hold released on ${item.asset.name} — requester notified`);
        },true)}{btn("Reject",()=>{
          if(item.reqId)resolveEnfApproval(item.reqId,"rejected");
          polSet(prev=>prev.map(pp=>pp.id===item.policyId?{...pp,rules:(pp.rules||[]).map(r=>r.id===baseRuleId?{...r,pendingUnhold:false}:r)}:pp));
          pushNotif({category:"Policy",type:"field_updated",title:`Unhold rejected · ${item.asset.name}`,body:`${item.requestedBy}'s request to release the legal hold on ${item.asset.name} was declined — the hold remains in place.`,nav:"policymanager",navArg:{policyId:item.policyId}});
          ack(item.id,"Unhold rejected — hold remains in place");
        },false,true)}{openIn("Open in Policy Manager","policymanager",{policyId:item.policyId})}</>;
      }
      if(item.action==="Partial Unhold"){
        const cnt = item.count||(item.keys||[]).length;
        return <>{btn("Approve release",()=>{
          if(item.reqId)resolveEnfApproval(item.reqId,"approved");
          polSet(prev=>prev.map(pp=>pp.id===item.policyId?{...pp,rules:(pp.rules||[]).map(r=>r.id===item.baseRuleId?{...r,releasedKeys:Array.from(new Set([...(r.releasedKeys||[]),...(item.keys||[])]))}:r)}:pp));
          pushNotif({category:"Policy",type:"cert",title:`Records released from hold · ${item.asset.name}`,body:`${cnt} record${cnt>1?"s":""} released from the legal hold on ${item.asset.name} by ${meHandle||"owner"} — the hold remains active for the rest.`,nav:"policymanager",navArg:{policyId:item.policyId}});
          ack(item.id,`${cnt} record${cnt>1?"s":""} released on ${item.asset.name} — requester notified`);
        },true)}{btn("Reject",()=>{
          if(item.reqId)resolveEnfApproval(item.reqId,"rejected");
          pushNotif({category:"Policy",type:"field_updated",title:`Partial unhold rejected · ${item.asset.name}`,body:`${item.requestedBy}'s request to release ${cnt} record${cnt>1?"s":""} from the legal hold on ${item.asset.name} was declined — all records remain held.`,nav:"policymanager",navArg:{policyId:item.policyId}});
          ack(item.id,"Partial unhold rejected — records remain held");
        },false,true)}{openIn("Open in Policy Manager","policymanager",{policyId:item.policyId})}</>;
      }
      return <>{btn("Approve",()=>{
        if(item.reqId)resolveEnfApproval(item.reqId,"approved");
        pushNotif({category:"Policy",type:"cert",title:`Enforcement approved · ${item.asset.name}`,body:`${item.action} approved by ${meHandle||"owner"}`,nav:"policymanager",navArg:{policyId:item.policyId}});
        ack(item.id,`Enforcement approved — ${item.action} on ${item.asset.name}`);
      },true)}{btn("Reject",()=>{
        if(item.reqId)resolveEnfApproval(item.reqId,"rejected");
        pushNotif({category:"Policy",type:"field_updated",title:`Enforcement rejected · ${item.asset.name}`,body:`${item.requestedBy}'s request to ${(item.action||"enforce").toLowerCase()} was declined`,nav:"policymanager",navArg:{policyId:item.policyId}});
        ack(item.id,"Enforcement rejected — requester notified");
      },false,true)}{openIn("Open in Policy Manager","policymanager",{policyId:item.policyId})}</>;
    }
    if(item.type==="orphan_assignment")
      return <>{btn("Assign owner",()=>setAssignOpen(a=>!a),true)}{btn("Deprecate",()=>ack(item.id,"Asset deprecated"),false,true)}{openIn("Open in Catalog","catalog")}</>;
    if(item.type==="needs_attention")
      return <>{btn("Assign steward",()=>setAssignOpen(a=>!a),true)}{btn("Dismiss",()=>dism(item.id))}{openIn("Open in Catalog","catalog")}</>;
    if(item.type==="field_updated")
      return <>{btn("Acknowledge",()=>ack(item.id),true)}{openIn("Open in Catalog","catalog")}</>;
    if(item.type==="assigned")
      return <>{btn("Acknowledge",()=>ack(item.id),true)}{openIn("Open in Catalog","catalog")}</>;
    if(item.type==="contract_approval"){
      const isDelete = (item.action||"").includes("deletion");
      return <>{btn(isDelete?"Approve deletion":"Approve",()=>{
        // activate or delete the contract in the store
        if(isDelete){ CONTRACT_STORE[item.assetName]=null; }
        else { const c=CONTRACT_STORE[item.assetName]; if(c) CONTRACT_STORE[item.assetName]={...c,status:"Active",updated:"Just now"}; }
        ack(item.id, isDelete?`Contract on ${item.assetName} deleted`:`Contract "${item.contractName}" approved — now Active`);
      },true)}{btn("Reject",()=>ack(item.id,`Contract "${item.contractName}" rejected — returned to Draft`),false,true)}{openIn("Open in Catalog","catalog")}</>;
    }
    return null;
  };

  /* ── Shared detail content (list + kanban) ── */
  const DetailContent = ({item}) => {
    if(!item) return null;
    const person = item.changedBy||item.assignedBy||item.requestedBy||null;
    const initials = person ? person.split(".").map(s=>s[0]?.toUpperCase()||"").join("").slice(0,2) : "?";
    const personRole = item.type==="field_updated"?"Made a field update":item.type==="assigned"?"Assigned this to you":item.type==="stewardship_request"?"Requested steward access":item.type==="needs_attention"?"Flagged for attention":"Last activity";
    return (
      <div style={{display:"flex",flexDirection:"column",height:"100%",overflow:"hidden"}}>
        {/* Scrollable body */}
        <div style={{flex:1,overflowY:"auto",padding:"16px 18px"}}>
          {/* Asset type + time row */}
          <div style={{display:"flex",alignItems:"center",gap:6,flexWrap:"wrap",marginBottom:14}}>
            <TypeBadge type={item.asset.type}/>
            <span style={{fontSize:11,color:T.textMuted}}>{item.timeAgo}</span>
          </div>

          {/* Person row */}
          {person&&(
            <div style={{display:"flex",alignItems:"center",gap:10,padding:"10px 13px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:8,marginBottom:16}}>
              <div style={{width:28,height:28,borderRadius:"50%",background:T.accent+"22",border:`1px solid ${T.accent}44`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:10,fontWeight:700,color:T.accent,flexShrink:0}}>{initials}</div>
              <div>
                <div style={{fontSize:12,fontWeight:600,color:T.text}}>{person}</div>
                <div style={{fontSize:10.5,color:T.textMuted,marginTop:1}}>{personRole}</div>
              </div>
            </div>
          )}

          {/* Body text */}
          {item.body&&<div style={{fontSize:12.5,color:T.textSub,lineHeight:1.65,marginBottom:16}}>{item.body}</div>}


          {/* Assignee — display only for now; see effAssignee comment above. */}
          {itemRole(item)!=="fyi"&&(()=>{const a=effAssignee(item);const ini=a==="unassigned"?"?":a.split(".").map(s=>s[0]?.toUpperCase()||"").join("").slice(0,2);return (
            <div style={{marginBottom:16,background:T.bgElevated,borderRadius:8,padding:"10px 13px",border:`1px solid ${T.border}`}}>
              <div style={{display:"flex",alignItems:"center",gap:10}}>
                <div style={{width:28,height:28,borderRadius:"50%",background:T.accent+"22",border:`1px solid ${T.accent}44`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:10,fontWeight:700,color:T.accent,flexShrink:0}}>{ini}</div>
                <div style={{flex:1,minWidth:0}}>
                  <div style={{fontSize:9.5,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.06em",fontWeight:700}}>Assignee</div>
                  <div style={{fontSize:12.5,fontWeight:600,color:T.text}}>{a}</div>
                </div>
              </div>
            </div>
          );})()}

          {/* DQ failures */}
          {item.failures&&(
            <div style={{marginBottom:16,background:`${T.rose}08`,borderRadius:8,padding:"12px 14px",border:`1px solid ${T.rose}22`}}>
              <div style={{fontSize:10,fontWeight:700,color:T.rose,textTransform:"uppercase",letterSpacing:"0.08em",marginBottom:9}}>Failed Checks</div>
              {item.failures.map((f,fi)=>(
                <div key={fi} style={{display:"flex",alignItems:"flex-start",gap:8,fontSize:12,color:T.textSub,marginBottom:fi<item.failures.length-1?8:0}}>
                  <span style={{width:5,height:5,borderRadius:"50%",background:T.rose,flexShrink:0,marginTop:5}}/>
                  {f}
                </div>
              ))}
            </div>
          )}

          {/* Field diff */}
          {item.diff&&(
            <div style={{marginBottom:16,background:T.bgElevated,borderRadius:8,padding:"12px 14px",border:`1px solid ${T.border}`}}>
              <div style={{fontSize:10,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.08em",marginBottom:9}}>{item.diff.field} changed</div>
              <div style={{display:"flex",flexDirection:"column",gap:6}}>
                <div style={{fontSize:12,color:T.rose,background:`${T.rose}0d`,borderRadius:5,padding:"7px 11px",borderLeft:`2px solid ${T.rose}`}}>
                  <span style={{fontSize:9.5,fontWeight:700,color:T.textMuted,marginRight:8,textTransform:"uppercase"}}>Before</span>{item.diff.before}
                </div>
                <div style={{fontSize:12,color:"#16a34a",background:"rgba(22,163,74,.08)",borderRadius:5,padding:"7px 11px",borderLeft:"2px solid #16a34a"}}>
                  <span style={{fontSize:9.5,fontWeight:700,color:T.textMuted,marginRight:8,textTransform:"uppercase"}}>After</span>{item.diff.after}
                </div>
              </div>
            </div>
          )}

          {/* Assign picker — needs_attention (steward) + orphan_assignment (owner) */}
          {(item.type==="needs_attention"||item.type==="orphan_assignment")&&assignOpen&&(()=>{
            const role = item.type==="orphan_assignment" ? "owner" : "steward";
            const roleL = role==="owner" ? "Owner" : "Steward";
            return (
            <div style={{marginBottom:16,background:T.bgElevated,borderRadius:8,padding:"12px 14px",border:`1px solid ${T.border}`}}>
              <div style={{fontSize:11,color:T.textSub,marginBottom:10}}>Assign {role} to <b style={{color:T.text}}>{item.asset.name}</b></div>
              <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
                {["priya.nair","dev.patel","maya.chen","sarah.kim","alex.wu","james.oh"].map(u=>(
                  <button key={u} onClick={()=>{const ok=assignOwnership(item.asset.name,u,role);closeForms();ack(item.id,ok?`${u} assigned as ${roleL} of ${item.asset.name}`:`${u} assigned as ${roleL}`);}}
                    style={{padding:"5px 13px",borderRadius:6,background:T.bgSurface,border:`1px solid ${T.border}`,color:T.textSub,fontSize:12,cursor:"pointer",transition:"all .1s"}}
                    onMouseEnter={e=>{e.currentTarget.style.borderColor=T.accent;e.currentTarget.style.color=T.accent;}}
                    onMouseLeave={e=>{e.currentTarget.style.borderColor=T.border;e.currentTarget.style.color=T.textSub;}}>
                    {u}
                  </button>
                ))}
              </div>
            </div>
            );
          })()}

          {/* Inline resolution form — DQ + violations capture the reason HERE; violations can remediate or request an exception */}
          {(item.type==="dq_alert"||item.type==="policy_violation")&&resolveOpen&&(()=>{
            const isViol = item.type==="policy_violation";
            const exception = isViol && resolveMode==="exception";
            const ok = resolveNote.trim().length>0;
            return (
              <div style={{marginBottom:16,background:T.bgElevated,borderRadius:8,padding:"12px 14px",border:`1px solid ${T.border}`}}>
                {isViol&&(
                  <div style={{display:"flex",gap:8,marginBottom:10}}>
                    {[["remediate","Remediated"],["exception","Request exception → owner"]].map(([k,l])=>(
                      <button key={k} onClick={()=>setResolveMode(k)} style={{flex:1,padding:"7px 10px",borderRadius:7,background:resolveMode===k?T.accentDim:"transparent",border:`1px solid ${resolveMode===k?T.accent:T.border}`,color:resolveMode===k?T.accent:T.textSub,fontSize:11.5,fontWeight:resolveMode===k?700:500,cursor:"pointer",whiteSpace:"nowrap"}}>{l}</button>
                    ))}
                  </div>
                )}
                <div style={{fontSize:11,fontWeight:700,color:T.textSub,marginBottom:8}}>{exception?"Reason for exception":isViol?"Remediation note":"Resolution reason"} <span style={{color:T.rose}}>*</span></div>
                <textarea value={resolveNote} onChange={e=>setResolveNote(e.target.value)} rows={3} placeholder={exception?"Why should this violation be waived? The owner will review.":isViol?"Describe how the violation was remediated…":"Describe the root cause and how it was resolved…"}
                  style={{width:"100%",padding:"9px 11px",background:T.bgSurface,border:`1.5px solid ${ok?T.accent:T.border}`,borderRadius:8,color:T.text,fontSize:12.5,lineHeight:1.6,outline:"none",resize:"vertical",fontFamily:"inherit",boxSizing:"border-box"}}/>
                <div style={{display:"flex",gap:8,marginTop:10}}>
                  <button disabled={!ok} onClick={()=>{
                    if(!ok) return;
                    if(item.type==="dq_alert"){ resolveIncidentsForAsset(item.asset.path,item.asset.name,resolveNote.trim()); ack(item.id,`${item.asset.name} quality incident resolved`); }
                    else if(exception){ pvSet(prev=>prev.map(v=>v.id===item.violId?{...v,status:"Exception Requested",resolutionNote:resolveNote.trim()}:v)); ack(item.id,"Exception requested — sent to owner"); }
                    else { pvSet(prev=>prev.map(v=>v.id===item.violId?{...v,status:"Resolved",resolutionNote:resolveNote.trim()}:v)); ack(item.id,`${item.asset.name} violation remediated`); }
                  }} style={{padding:"7px 16px",borderRadius:7,background:ok?T.accent:T.bgHover,border:"none",color:ok?"#fff":T.textMuted,fontSize:12,fontWeight:600,cursor:ok?"pointer":"default"}}>{exception?"Send to owner":"Confirm resolution"}</button>
                  <button onClick={()=>{setResolveOpen(false);setResolveNote("");setResolveMode("remediate");}} style={{padding:"7px 16px",borderRadius:7,background:"transparent",border:`1px solid ${T.border}`,color:T.textSub,fontSize:12,cursor:"pointer"}}>Cancel</button>
                </div>
                <div style={{fontSize:10.5,color:T.textMuted,marginTop:8}}>{exception?"Goes to the asset owner to approve or deny.":`Recorded on the ${isViol?"violation":"incident"} and shown in ${isViol?"Policy Manager":"Data Quality"} as history.`}</div>
              </div>
            );
          })()}
        </div>

        {/* Sticky action footer */}
        <div style={{borderTop:`1px solid ${T.border}`,padding:"12px 22px",display:"flex",gap:8,flexWrap:"wrap",flexShrink:0,background:T.bgSurface}}>
          <ActionRow item={item}/>
        </div>
      </div>
    );
  };

  /* ── Compact list tile (click to open detail, no inline actions) ── */
  const Tile = ({item, done=false}) => {
    const sev  = SEV[item.severity]||SEV.low;
    const meta = TYPE_META[item.type]||TYPE_META.field_updated;
    const isSel = sel===item.id;
    const rm = ROLE_META[itemRole(item)]||ROLE_META.steward;
    /* done = reviewed/completed — shown with a green indicator */
    const iconColor  = done ? T.green : sev.c;
    const labelColor = done ? T.green : sev.c;
    const titleColor = done ? T.textSub : T.text;
    const titleWeight= done ? 500 : 600;
    const catColor   = (CATEGORY_META[itemCategory(item)]||CATEGORY_META.curation).color;
    const borderLeft = done ? `3px solid ${T.green}` : `3px solid ${catColor}`;
    return (
      <div onClick={()=>{ setSel(isSel?null:item.id); closeForms(); }}
        style={{display:"flex",alignItems:"stretch",background:isSel?`${T.accent}08`:T.bgSurface,border:`1px solid ${isSel?T.accent+"44":T.border}`,borderLeft,borderRadius:8,cursor:"pointer",transition:"all .12s",overflow:"hidden",minHeight:64,opacity:1}}
        onMouseEnter={e=>{ if(!isSel)e.currentTarget.style.background=T.bgElevated; }}
        onMouseLeave={e=>{ if(!isSel)e.currentTarget.style.background=T.bgSurface; }}>
        <div style={{flex:1,padding:"10px 14px",minWidth:0}}>
          {/* Row 1: role chip + type label + done chip + time */}
          <div style={{display:"flex",alignItems:"center",gap:5,marginBottom:4}}>
            {!done&&<span style={{fontSize:8.5,fontWeight:800,letterSpacing:"0.04em",color:rm.color,background:rm.bg,borderRadius:4,padding:"1.5px 5px",flexShrink:0}}>{rm.label}</span>}
            <span style={{color:iconColor,display:"flex",alignItems:"center",flexShrink:0}}>{meta.icon()}</span>
            <span style={{fontSize:10.5,fontWeight:600,color:labelColor}}>{meta.label}</span>
            {done&&(
              <span style={{display:"flex",alignItems:"center",gap:3,fontSize:9.5,fontWeight:700,color:T.green,background:`${T.green}14`,border:`1px solid ${T.green}40`,borderRadius:4,padding:"1px 5px"}}>
                <svg width="8" height="8" viewBox="0 0 10 10" fill="none"><path d="M1.5 5.5L3.8 7.8L8.5 2.5" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"/></svg>
                Done
              </span>
            )}
            <div style={{flex:1}}/>
            <span style={{fontSize:10.5,color:T.textMuted,flexShrink:0}}>{item.timeAgo}</span>
          </div>
          {/* Row 2: title */}
          <div style={{fontSize:12.5,fontWeight:titleWeight,color:titleColor,lineHeight:1.35,marginBottom:4,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{itemTitle(item)}</div>
          {/* Row 3: asset path + assignee + type badge */}
          <div style={{display:"flex",alignItems:"center",gap:6}}>
            <span style={{fontSize:10.5,fontFamily:"'Geist Mono',monospace",color:T.textMuted,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",flex:1}}>{item.asset.path}</span>
            {(()=>{const a=effAssignee(item);return (a&&a!=="unassigned")?<span title={`Assignee: ${a}`} style={{display:"flex",alignItems:"center",gap:3,flexShrink:0}}><span style={{width:15,height:15,borderRadius:"50%",background:T.accent+"22",color:T.accent,fontSize:7.5,fontWeight:700,display:"flex",alignItems:"center",justifyContent:"center"}}>{a.split(".").map(s=>s[0]?.toUpperCase()||"").join("").slice(0,2)}</span><span style={{fontSize:10,color:T.textMuted}}>{a}</span></span>:null;})()}
            <TypeBadge type={item.asset.type}/>
          </div>
        </div>
        {/* Selected indicator strip */}
        {isSel&&<div style={{width:3,background:T.accent,flexShrink:0}}/>}
      </div>
    );
  };

  /* ── Compact kanban card (click to open detail, no inline actions) ── */
  const KCard = ({item,colC}) => {
    const sev  = SEV[item.severity]||SEV.low;
    const meta = TYPE_META[item.type]||TYPE_META.field_updated;
    const rm   = ROLE_META[itemRole(item)]||ROLE_META.steward;
    const isSel = sel===item.id;
    return (
      <div onClick={()=>{ setSel(isSel?null:item.id); closeForms(); }}
        style={{background:isSel?`${T.accent}0d`:T.bgSurface,border:`1px solid ${isSel?T.accent+"55":T.border}`,borderTop:`2px solid ${colC}`,borderRadius:8,padding:"11px 12px",marginBottom:7,cursor:"pointer",transition:"all .12s"}}
        onMouseEnter={e=>{ if(!isSel){e.currentTarget.style.boxShadow=`0 3px 12px rgba(0,0,0,.09)`;e.currentTarget.style.transform="translateY(-1px)";}}}
        onMouseLeave={e=>{e.currentTarget.style.boxShadow="none";e.currentTarget.style.transform="none";}}>
        {/* Type + time */}
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:6}}>
          <div style={{display:"flex",alignItems:"center",gap:5}}>
            <div style={{width:16,height:16,borderRadius:4,background:sev.bg,display:"flex",alignItems:"center",justifyContent:"center",color:sev.c,flexShrink:0}}>{meta.icon()}</div>
            <span style={{fontSize:10,fontWeight:700,color:sev.c}}>{meta.shortLabel}</span>
            <span style={{fontSize:8,fontWeight:800,letterSpacing:"0.03em",color:rm.color,background:rm.bg,borderRadius:3,padding:"1px 4px"}}>{rm.label}</span>
          </div>
          <span style={{fontSize:10,color:T.textMuted}}>{item.timeAgo}</span>
        </div>
        {/* Title */}
        <div style={{fontSize:12,fontWeight:600,color:T.text,lineHeight:1.4,marginBottom:5,display:"-webkit-box",WebkitLineClamp:2,WebkitBoxOrient:"vertical",overflow:"hidden"}}>{itemTitle(item)}</div>
        {/* Asset path */}
        <div style={{fontSize:10.5,fontFamily:"'Geist Mono',monospace",color:T.textMuted,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{item.asset.path}</div>
        {(()=>{const a=effAssignee(item);return (a&&a!=="unassigned")?<div style={{display:"flex",alignItems:"center",gap:4,marginTop:6}}><span style={{width:15,height:15,borderRadius:"50%",background:T.accent+"22",color:T.accent,fontSize:7.5,fontWeight:700,display:"flex",alignItems:"center",justifyContent:"center"}}>{a.split(".").map(s=>s[0]?.toUpperCase()||"").join("").slice(0,2)}</span><span style={{fontSize:10,color:T.textMuted}}>{a}</span></div>:null;})()}
        {/* Failure count badge */}
        {item.failures&&<div style={{marginTop:6,fontSize:10.5,color:T.rose,fontWeight:500}}>{item.failures.length} failed check{item.failures.length!==1?"s":""}</div>}
      </div>
    );
  };

  /* ── Kanban columns ── */
  const KANBAN_COLS = [
    {id:"violation", label:"Violations", c:"#dc2626", cats:["violation"]},
    {id:"approval",  label:"Approvals",  c:"#2563eb", cats:["approval"]},
    {id:"ownership", label:"Ownership",  c:"#0d9488", cats:["ownership"]},
    {id:"done",      label:"Done",       c:"#16a34a", done:true},
  ];

  /* ── Detail panel header — matches ServicePanel pattern ── */
  const DetailHeader = () => {
    if(!selItem) return null;
    const sev  = SEV[selItem.severity]||SEV.low;
    const meta = TYPE_META[selItem.type]||TYPE_META.field_updated;
    return (
      <div style={{padding:"16px 18px 14px",borderBottom:`1px solid ${T.border}`,flexShrink:0}}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:10}}>
          {/* Left: icon + title + subtitle */}
          <div style={{display:"flex",alignItems:"center",gap:10,minWidth:0}}>
            <div style={{width:36,height:36,borderRadius:9,background:sev.bg,border:`1px solid ${sev.c}22`,display:"flex",alignItems:"center",justifyContent:"center",color:sev.c,flexShrink:0}}>
              {meta.icon(15)}
            </div>
            <div style={{minWidth:0}}>
              <div style={{fontSize:13,fontWeight:700,color:T.text,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{itemTitle(selItem)}</div>
              <div style={{display:"flex",alignItems:"center",gap:6,marginTop:3}}>
                {(()=>{const rm=ROLE_META[itemRole(selItem)]||ROLE_META.steward;return <span style={{fontSize:8.5,fontWeight:800,letterSpacing:"0.04em",color:rm.color,background:rm.bg,borderRadius:4,padding:"1.5px 5px",flexShrink:0}}>{rm.label}</span>;})()}
                <span style={{fontSize:10.5,color:T.textMuted,fontFamily:"'Geist Mono',monospace",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{meta.label} · {selItem.asset.path}</span>
              </div>
            </div>
          </div>
          {/* Right: prev/next + close */}
          <div style={{display:"flex",gap:5,alignItems:"center",flexShrink:0}}>
            <button onClick={navPrev} disabled={selIdx<=0}
              style={{width:26,height:26,borderRadius:6,background:T.bgHover,border:`1px solid ${T.border}`,display:"flex",alignItems:"center",justifyContent:"center",cursor:selIdx<=0?"default":"pointer",opacity:selIdx<=0?0.35:1,color:T.textSub,transition:"all .1s"}}
              onMouseEnter={e=>{if(selIdx>0)e.currentTarget.style.borderColor=T.accent;}}
              onMouseLeave={e=>e.currentTarget.style.borderColor=T.border}>
              <svg width="7" height="10" viewBox="0 0 7 10" fill="none"><path d="M5 1.5L2 5l3 3.5" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" strokeLinejoin="round"/></svg>
            </button>
            <button onClick={navNext} disabled={selIdx>=shown.length-1}
              style={{width:26,height:26,borderRadius:6,background:T.bgHover,border:`1px solid ${T.border}`,display:"flex",alignItems:"center",justifyContent:"center",cursor:selIdx>=shown.length-1?"default":"pointer",opacity:selIdx>=shown.length-1?0.35:1,color:T.textSub,transition:"all .1s"}}
              onMouseEnter={e=>{if(selIdx<shown.length-1)e.currentTarget.style.borderColor=T.accent;}}
              onMouseLeave={e=>e.currentTarget.style.borderColor=T.border}>
              <svg width="7" height="10" viewBox="0 0 7 10" fill="none"><path d="M2 1.5L5 5 2 8.5" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" strokeLinejoin="round"/></svg>
            </button>
            <button onClick={()=>{setSel(null);closeForms();}}
              style={{width:26,height:26,borderRadius:6,background:T.bgHover,border:`1px solid ${T.border}`,display:"flex",alignItems:"center",justifyContent:"center",cursor:"pointer",color:T.textMuted,transition:"all .1s"}}
              onMouseEnter={e=>{e.currentTarget.style.borderColor=T.rose+"66";e.currentTarget.style.color=T.rose;}}
              onMouseLeave={e=>{e.currentTarget.style.borderColor=T.border;e.currentTarget.style.color=T.textMuted;}}>
              <svg width="10" height="10" viewBox="0 0 12 12" fill="none"><path d="M2 2l8 8M10 2L2 10" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round"/></svg>
            </button>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="fadeUp" style={{height:"100%",display:"flex",flexDirection:"column"}}>
      {/* Topbar — breadcrumb only */}
      <Topbar breadcrumb={[{label:"Workspace"}]}/>

      {/* Primary toolbar — search + role filter + section filter */}
      <div style={{padding:"8px 20px 8px 28px",borderBottom:`1px solid ${T.border}`,display:"flex",alignItems:"center",gap:10,flexShrink:0,background:T.bgSurface,minHeight:46}}>

        {/* Search */}
        <div style={{position:"relative",flex:1,maxWidth:340}}>
          <span style={{position:"absolute",left:10,top:"50%",transform:"translateY(-50%)",color:T.textMuted,display:"flex",pointerEvents:"none"}}>
            <svg width="13" height="13" viewBox="0 0 14 14" fill="none"><circle cx="6" cy="6" r="4.5" stroke="currentColor" strokeWidth="1.4"/><path d="M9.5 9.5l3 3" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round"/></svg>
          </span>
          <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search by asset name, FQN or title…"
            style={{width:"100%",boxSizing:"border-box",padding:"6px 28px 6px 30px",borderRadius:7,border:`1px solid ${T.border}`,background:T.bgElevated,color:T.text,fontSize:12.5,outline:"none"}}
            onFocus={e=>e.target.style.borderColor=T.accent} onBlur={e=>e.target.style.borderColor=T.border}/>
          {search&&<button onClick={()=>setSearch("")} style={{position:"absolute",right:8,top:"50%",transform:"translateY(-50%)",background:"none",border:"none",cursor:"pointer",color:T.textMuted,display:"flex",padding:2}}><svg width="10" height="10" viewBox="0 0 10 10" fill="none"><path d="M1.5 1.5l7 7M8.5 1.5l-7 7" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round"/></svg></button>}
        </div>

        <div style={{flex:1}}/>

        {/* Role filter — button style matching Section */}
        <div style={{position:"relative"}}>
          <button onClick={()=>{setRoleOpen(o=>!o);setFilterOpen(false);}}
            style={{display:"flex",alignItems:"center",gap:5,padding:"5px 10px",borderRadius:7,background:roleOpen||roleScope!=="all"?T.accentDim:"transparent",border:`1px solid ${roleOpen||roleScope!=="all"?T.accent:T.border}`,color:roleOpen||roleScope!=="all"?T.accent:T.textSub,cursor:"pointer",fontSize:12,fontWeight:500,transition:"all .12s"}}>
            <svg width="12" height="12" viewBox="0 0 14 14" fill="none"><path d="M1 3h12M3 7h8M5 11h4" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round"/></svg>
            Role{roleScope!=="all"&&<span style={{fontWeight:700,marginLeft:2}}>{roleScope==="steward"?"· Steward":"· Owner"}</span>}
          </button>
          {roleOpen&&(
            <div style={{position:"absolute",top:"calc(100% + 6px)",right:0,zIndex:300,background:T.bgSurface,border:`1px solid ${T.border}`,borderRadius:10,boxShadow:"0 8px 24px rgba(0,0,0,.15)",minWidth:160,padding:"6px 0"}}
              onClick={e=>e.stopPropagation()}>
              <div style={{padding:"4px 14px 8px",fontSize:10,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.08em"}}>Filter by Role</div>
              {[["all","All"],["steward","Steward"],["owner","Owner"]].map(([k,l])=>{
                const active = roleScope===k;
                return (
                  <button key={k} onClick={()=>{setRoleScope(k);setSel(null);setRoleOpen(false);}}
                    style={{width:"100%",display:"flex",alignItems:"center",gap:9,padding:"7px 14px",background:active?T.accentDim:"transparent",border:"none",cursor:"pointer",fontSize:12.5,color:active?T.accent:T.text,fontWeight:active?700:400,textAlign:"left",transition:"background .1s"}}
                    onMouseEnter={e=>{if(!active)e.currentTarget.style.background=T.bgHover;}}
                    onMouseLeave={e=>{if(!active)e.currentTarget.style.background="transparent";}}>
                    {active&&<svg width="9" height="9" viewBox="0 0 10 10" fill="none"><path d="M1.5 5.5L3.8 7.8L8.5 2.5" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"/></svg>}
                    {!active&&<span style={{width:9}}/>}
                    {l}
                  </button>
                );
              })}
            </div>
          )}
        </div>

        {/* Section filter */}
        <div style={{position:"relative"}}>
          <button onClick={()=>{setFilterOpen(o=>!o);setRoleOpen(false);}}
            style={{display:"flex",alignItems:"center",gap:5,padding:"5px 10px",borderRadius:7,background:filterOpen||secFilterActive?T.accentDim:"transparent",border:`1px solid ${filterOpen||secFilterActive?T.accent:T.border}`,color:filterOpen||secFilterActive?T.accent:T.textSub,cursor:"pointer",fontSize:12,fontWeight:500,transition:"all .12s"}}>
            <svg width="12" height="12" viewBox="0 0 14 14" fill="none"><path d="M1 3h12M3 7h8M5 11h4" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round"/></svg>
            Section
            {secFilterActive&&<span style={{fontSize:10,fontWeight:700,background:T.accent,color:"#fff",borderRadius:99,padding:"1px 6px",marginLeft:2}}>{secFilters.size}</span>}
          </button>
          {filterOpen&&(
            <div style={{position:"absolute",top:"calc(100% + 6px)",right:0,zIndex:300,background:T.bgSurface,border:`1px solid ${T.border}`,borderRadius:10,boxShadow:"0 8px 24px rgba(0,0,0,.15)",minWidth:200,padding:"10px 0"}}
              onClick={e=>e.stopPropagation()}>
              <div style={{padding:"4px 14px 8px",fontSize:10,fontWeight:700,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.08em"}}>Filter by Section</div>
              {SECTIONS.map(({k,l})=>{
                const checked = secFilters.has(k);
                return (
                  <label key={k} style={{display:"flex",alignItems:"center",gap:9,padding:"7px 14px",cursor:"pointer",transition:"background .1s"}}
                    onMouseEnter={e=>e.currentTarget.style.background=T.bgHover}
                    onMouseLeave={e=>e.currentTarget.style.background="transparent"}>
                    <div onClick={()=>toggleSec(k)} style={{width:15,height:15,borderRadius:4,border:`1.5px solid ${checked?T.accent:T.border}`,background:checked?T.accent:"transparent",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,transition:"all .12s"}}>
                      {checked&&<svg width="9" height="9" viewBox="0 0 10 10" fill="none"><path d="M1.5 5.5L3.8 7.8L8.5 2.5" stroke="#fff" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"/></svg>}
                    </div>
                    <span onClick={()=>toggleSec(k)} style={{fontSize:12.5,color:T.text}}>{l}</span>
                  </label>
                );
              })}
              {secFilterActive&&(
                <div style={{borderTop:`1px solid ${T.border}`,marginTop:6,padding:"8px 14px 2px"}}>
                  <button onClick={()=>setSecFilters(new Set())} style={{background:"none",border:"none",cursor:"pointer",color:T.rose,fontSize:12,padding:0}}>Clear filters</button>
                </div>
              )}
            </div>
          )}
        </div>
      </div>

      {/* Tabs — Inbox / Done */}
      <div style={{padding:"0 20px 0 28px",borderBottom:`1px solid ${T.border}`,display:"flex",alignItems:"center",flexShrink:0,background:T.bgSurface,minHeight:42}}>
          {[["action","Inbox"],["done","Done"]].map(([k,l])=>(
            <button key={k} onClick={()=>{ setFilter(k); setSel(null); closeForms(); setFilterOpen(false); }}
              style={{padding:"11px 14px",background:"transparent",border:"none",borderBottom:`2px solid ${filter===k?T.accent:"transparent"}`,color:filter===k?T.text:T.textMuted,fontSize:12.5,fontWeight:filter===k?600:400,cursor:"pointer",display:"flex",alignItems:"center",gap:5,transition:"all .12s",whiteSpace:"nowrap"}}>
              {l}
              {counts[k]>0&&<span style={{fontSize:10,fontWeight:700,borderRadius:10,padding:"1px 6px",
                background: k==="done"?"rgba(22,163,74,.1)":k==="action"?`${T.rose}18`:T.bgHover,
                color:      k==="done"?"#16a34a"           :k==="action"?T.rose        :T.textMuted}}>
                {counts[k]}
              </span>}
            </button>
          ))}
      </div>

      {/* ── Main content + unified detail panel ── */}
      <div style={{flex:1,display:"flex",overflow:"hidden"}}>

        {/* Left: list or kanban (both fill flex:1) */}
        <div style={{flex:1,overflow:"hidden",display:"flex",flexDirection:"column"}}>

          {/* ── LIST VIEW ── */}
          {viewMode==="list"&&(
            <div style={{flex:1,overflowY:"auto",padding:"20px 24px"}} onClick={()=>filterOpen&&setFilterOpen(false)}>

              {/* Active section filter chips */}
              {secFilterActive&&(
                <div style={{display:"flex",alignItems:"center",gap:6,flexWrap:"wrap",marginBottom:14}}>
                  <span style={{fontSize:11,color:T.textMuted}}>Filtered by:</span>
                  {[...secFilters].map(s=>{
                    const label = SECTIONS.find(x=>x.k===s)?.l||s;
                    return (
                      <span key={s} style={{display:"flex",alignItems:"center",gap:4,fontSize:11.5,fontWeight:500,padding:"3px 10px",borderRadius:99,background:T.accentDim,border:`1px solid ${T.accent}44`,color:T.accent}}>
                        {label}
                        <button onClick={()=>toggleSec(s)} style={{background:"none",border:"none",cursor:"pointer",color:T.accent,fontSize:14,lineHeight:1,padding:0,marginLeft:2}}>×</button>
                      </span>
                    );
                  })}
                  <button onClick={()=>setSecFilters(new Set())} style={{background:"none",border:"none",cursor:"pointer",color:T.textMuted,fontSize:11.5,textDecoration:"underline",padding:0}}>Clear all</button>
                </div>
              )}

              {/* Done tab */}
              {isDoneFilter&&(
                doneShown.length===0?(
                  <div style={{display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",height:220,gap:12}}>
                    <div style={{width:44,height:44,borderRadius:12,background:T.bgElevated,border:`1px solid ${T.border}`,display:"flex",alignItems:"center",justifyContent:"center",color:T.textMuted}}>
                      <svg width="20" height="20" viewBox="0 0 22 22" fill="none"><path d="M3 12L8 17L19 6" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"/></svg>
                    </div>
                    <div style={{fontSize:13,fontWeight:600,color:T.textSub}}>Nothing completed yet</div>
                    <div style={{fontSize:12,color:T.textMuted}}>Completed tasks will appear here</div>
                  </div>
                ):(
                  <div style={{display:"flex",flexDirection:"column",gap:5,maxWidth:sel?9999:820}}>
                    {doneShown.map(item=><Tile key={item.id} item={item} done={true}/>)}
                  </div>
                )
              )}

              {/* All / Tasks / Alerts / Assigned tabs */}
              {!isDoneFilter&&(
                shown.length===0?(
                  <div style={{display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",height:220,gap:12}}>
                    <div style={{width:44,height:44,borderRadius:12,background:T.bgElevated,border:`1px solid ${T.border}`,display:"flex",alignItems:"center",justifyContent:"center",color:T.textMuted}}>{Ic.inbox(20)}</div>
                    <div style={{fontSize:13,fontWeight:600,color:T.textSub}}>You're all caught up</div>
                    <div style={{fontSize:12,color:T.textMuted}}>No pending items</div>
                  </div>
                ):(
                  <div style={{display:"flex",flexDirection:"column",gap:5,maxWidth:sel?9999:820}}>
                    {(()=>{const orphans=shown.filter(i=>i.type==="orphan_assignment");return orphans.length>=2?(
                      <div style={{background:T.accentDim,border:`1px solid ${T.accent}44`,borderRadius:8,padding:"10px 14px",marginBottom:6}}>
                        <div style={{display:"flex",alignItems:"center",gap:8,flexWrap:"wrap"}}>
                          <span style={{fontSize:12.5,fontWeight:600,color:T.text}}>{orphans.length} unowned assets need an owner</span>
                          <span style={{fontSize:11.5,color:T.textMuted}}>— assign them all at once instead of one by one</span>
                          <div style={{flex:1}}/>
                          <button onClick={()=>setBulkOpen(o=>!o)} style={{padding:"5px 12px",borderRadius:7,background:T.accent,border:"none",color:"#fff",fontSize:11.5,fontWeight:600,cursor:"pointer"}}>Assign all ▾</button>
                        </div>
                        {bulkOpen&&(
                          <div style={{marginTop:10,paddingTop:10,borderTop:`1px solid ${T.accent}33`}}>
                            <div style={{fontSize:11,color:T.textSub,marginBottom:8}}>Assign all {orphans.length} as owner to:</div>
                            <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
                              {STEWARD_POOL.map(u=>(
                                <button key={u} onClick={()=>{orphans.forEach(o=>assignOwnership(o.asset.name,u,"owner"));const ids=orphans.map(o=>o.id);setItems(p=>p.map(i=>ids.includes(i.id)?{...i,readAt:new Date().toISOString()}:i));setBulkOpen(false);setSel(null);onToast(`${orphans.length} assets assigned to ${u}`,"success");}}
                                  style={{padding:"5px 12px",borderRadius:6,background:T.bgSurface,border:`1px solid ${T.border}`,color:T.textSub,fontSize:12,cursor:"pointer"}}
                                  onMouseEnter={e=>{e.currentTarget.style.borderColor=T.accent;e.currentTarget.style.color=T.accent;}} onMouseLeave={e=>{e.currentTarget.style.borderColor=T.border;e.currentTarget.style.color=T.textSub;}}>{u}</button>
                              ))}
                            </div>
                          </div>
                        )}
                      </div>
                    ):null;})()}
                    {shown.map(item=><Tile key={item.id} item={item}/>)}
                  </div>
                )
              )}
            </div>
          )}

          {/* ── KANBAN VIEW ── */}
          {viewMode==="kanban"&&(
            <div style={{flex:1,overflowX:"auto",overflowY:"hidden",padding:"18px 20px",display:"flex",gap:12,alignItems:"flex-start"}}>
              {KANBAN_COLS.map(col=>{
                const colItems = col.done
                  ? doneItems.filter(i=>roleMatch(i) && secMatch(i) && searchMatch(i))
                  : actionItems.filter(i=>col.cats.includes(itemCategory(i)) && roleMatch(i) && secMatch(i) && searchMatch(i));
                return (
                  <div key={col.id} style={{width:248,flexShrink:0,display:"flex",flexDirection:"column",height:"100%"}}>
                    <div style={{display:"flex",alignItems:"center",gap:7,padding:"9px 12px",background:T.bgSurface,border:`1px solid ${T.border}`,borderTop:`3px solid ${col.c}`,borderRadius:"8px 8px 0 0",flexShrink:0}}>
                      <span style={{fontSize:12,fontWeight:700,color:T.text,flex:1}}>{col.label}</span>
                      <span style={{fontSize:10,fontWeight:700,background:colItems.length>0?`${col.c}18`:T.bgElevated,color:colItems.length>0?col.c:T.textMuted,borderRadius:10,padding:"1px 7px",border:`1px solid ${colItems.length>0?col.c+"33":T.border}`}}>{colItems.length}</span>
                    </div>
                    <div style={{flex:1,overflowY:"auto",background:T.bgElevated,border:`1px solid ${T.border}`,borderTop:"none",borderRadius:"0 0 8px 8px",padding:"9px 8px 4px"}}>
                      {colItems.length===0?(
                        <div style={{display:"flex",alignItems:"center",justifyContent:"center",height:80,opacity:0.4}}>
                          <span style={{fontSize:11,color:T.textMuted}}>No items</span>
                        </div>
                      ):(
                        colItems.map(item=><KCard key={item.id} item={item} colC={col.c}/>)
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>

        {/* Right: unified detail panel — same width + same header for both list and kanban */}
        {sel&&selItem&&(
          <div className="slideIn" style={{width:440,flexShrink:0,borderLeft:`1px solid ${T.border}`,display:"flex",flexDirection:"column",background:T.bgSurface,overflow:"hidden",boxShadow:"-4px 0 16px rgba(0,0,0,.06)"}}>
            <DetailHeader/>
            <DetailContent item={selItem}/>
          </div>
        )}

      </div>
    </div>
  );
};

const WorkflowView = ({onToast}) => {
  const [cat,      setCat]      = useState("All");
  const [selected, setSelected] = useState(null);
  const [search,   setSearch]   = useState("");
  const [running,  setRunning]  = useState({});

  const wf = selected ? WF_DATA.find(w=>w.id===selected) : null;

  const filtered = WF_DATA.filter(w =>
    (cat==="All" || w.category===cat) &&
    w.name.toLowerCase().includes(search.toLowerCase())
  );

  const statusColor = {success:T.green, running:T.blue, warning:T.amber, failed:T.red};
  const statusBg    = {success:"rgba(74,222,128,.1)", running:"rgba(125,211,252,.1)", warning:"rgba(251,191,36,.1)", failed:"rgba(248,113,113,.1)"};
  const catColor    = {Ingestion:T.blue, Quality:T.amber, Lineage:T.violet, Governance:T.accent, Analytics:T.rose};

  const triggerRun = (id) => {
    setRunning(r=>({...r,[id]:true}));
    onToast("Workflow triggered — running now","success");
    setTimeout(()=>setRunning(r=>{const n={...r};delete n[id];return n;}),3000);
  };

  const StageBar = ({stages, current}) => (
    <div style={{display:"flex",gap:2,marginTop:8}}>
      {stages.map((s,i)=>{
        const done = current===null ? true : i < current;
        const active = i===current;
        return (
          <div key={s} style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center",gap:3}}>
            <div style={{height:3,width:"100%",background:active?T.blue:done?T.accent:T.bgHover,borderRadius:2,transition:"background .3s"}}/>
            <span style={{fontSize:9,color:active?T.blue:done?T.accent:T.textMuted,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis",maxWidth:"100%"}}>{s}</span>
          </div>
        );
      })}
    </div>
  );

  return (
    <div className="fadeUp" style={{height:"100%",display:"flex",flexDirection:"column"}}>
      <Topbar breadcrumb={[{label:"Workflow Center"}]} actions={
        <div style={{display:"flex",gap:8}}>
          <Btn small ghost icon={Ic.refresh(12)} onClick={()=>onToast("Workflows refreshed","success")}>Refresh</Btn>
          <Btn icon={Ic.plus(12)} variant="primary" onClick={()=>onToast("New workflow dialog","success")}>New Workflow</Btn>
        </div>
      }/>

      {/* Top stats bar */}
      <div style={{display:"grid",gridTemplateColumns:"repeat(5,1fr)",gap:12,padding:"16px 28px",borderBottom:`1px solid ${T.border}`,flexShrink:0}}>
        {[
          {label:"Total Workflows", value:String(WF_DATA.length),           color:T.text},
          {label:"Running Now",     value:String(WF_DATA.filter(w=>w.status==="running").length), color:T.blue},
          {label:"Healthy",         value:String(WF_DATA.filter(w=>w.status==="success").length), color:T.green},
          {label:"Warnings",        value:String(WF_DATA.filter(w=>w.status==="warning").length), color:T.amber},
          {label:"Failed",          value:String(WF_DATA.filter(w=>w.status==="failed").length),  color:T.red},
        ].map(m=>(
          <div key={m.label} style={{textAlign:"center"}}>
            <div style={{fontSize:22,fontWeight:700,color:m.color,fontFamily:"'Geist Mono',monospace",letterSpacing:"-0.04em"}}>{m.value}</div>
            <div style={{fontSize:10.5,color:T.textMuted,marginTop:2,textTransform:"uppercase",letterSpacing:"0.06em"}}>{m.label}</div>
          </div>
        ))}
      </div>

      <div style={{flex:1,display:"flex",overflow:"hidden"}}>

        {/* ── Left: workflow list ── */}
        <div style={{width:wf?320:undefined,flex:wf?undefined:1,borderRight:wf?`1px solid ${T.border}`:"none",display:"flex",flexDirection:"column",overflow:"hidden"}}>
          {/* Search + category filter */}
          <div style={{padding:"12px 16px",borderBottom:`1px solid ${T.border}`,flexShrink:0}}>
            <div style={{marginBottom:10}}>
              <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search workflows…"
                style={{width:"100%",padding:"7px 12px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:7,color:T.text,fontSize:12,outline:"none",boxSizing:"border-box"}}
                onFocus={e=>e.target.style.borderColor=T.accent} onBlur={e=>e.target.style.borderColor=T.border}/>
            </div>
            <div style={{display:"flex",gap:4,flexWrap:"wrap"}}>
              {WF_CATS.map(c=>(
                <button key={c} onClick={()=>setCat(c)} style={{padding:"3px 10px",fontSize:11,fontWeight:500,borderRadius:99,border:`1px solid ${cat===c?catColor[c]||T.accent:T.border}`,background:cat===c?`rgba(${cat===c&&catColor[c]?catColor[c].replace(/[^\d,]/g,""):"110,231,183"},.12)`:"transparent",color:cat===c?catColor[c]||T.accent:T.textSub,cursor:"pointer",transition:"all .15s"}}>
                  {c}
                </button>
              ))}
            </div>
          </div>

          {/* Workflow cards */}
          <div style={{flex:1,overflowY:"auto",padding:"8px 0"}}>
            {filtered.map(w=>{
              const isSelected = selected===w.id;
              const isRunning  = running[w.id] || w.status==="running";
              return (
                <div key={w.id} onClick={()=>setSelected(isSelected?null:w.id)}
                  style={{padding:"12px 16px",borderBottom:`1px solid ${T.border}`,cursor:"pointer",background:isSelected?T.bgHover:"transparent",borderLeft:`3px solid ${isSelected?T.accent:"transparent"}`,transition:"all .15s"}}
                  onMouseEnter={e=>{if(!isSelected)e.currentTarget.style.background=T.bgElevated;}}
                  onMouseLeave={e=>{if(!isSelected)e.currentTarget.style.background="transparent";}}>

                  <div style={{display:"flex",alignItems:"flex-start",justifyContent:"space-between",gap:8,marginBottom:6}}>
                    <div style={{flex:1,minWidth:0}}>
                      <div style={{fontSize:12.5,fontWeight:600,color:T.text,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{w.name}</div>
                      <div style={{fontSize:10.5,color:T.textMuted,marginTop:1}}>{w.scheduleLabel} · {w.owner}</div>
                    </div>
                    <div style={{display:"flex",alignItems:"center",gap:5,padding:"2px 8px",borderRadius:99,background:statusBg[isRunning?"running":w.status],border:`1px solid ${statusColor[isRunning?"running":w.status]}30`,flexShrink:0}}>
                      {isRunning&&<span style={{width:6,height:6,borderRadius:"50%",background:T.blue,display:"inline-block",animation:"pulse2 1.2s ease infinite"}}/>}
                      <span style={{fontSize:10.5,fontWeight:600,color:statusColor[isRunning?"running":w.status]}}>{isRunning?"Running":w.status}</span>
                    </div>
                  </div>

                  <div style={{display:"flex",gap:12,fontSize:11,color:T.textMuted,marginBottom:6}}>
                    <span>Last: <b style={{color:T.textSub}}>{w.lastRun}</b></span>
                    <span>Next: <b style={{color:T.textSub}}>{w.nextRun}</b></span>
                  </div>

                  {/* Success rate bar */}
                  <div style={{display:"flex",alignItems:"center",gap:6}}>
                    <div style={{flex:1,height:3,background:T.bgHover,borderRadius:2}}>
                      <div style={{height:"100%",width:`${w.successRate}%`,background:w.successRate>=95?T.green:w.successRate>=80?T.amber:T.red,borderRadius:2}}/>
                    </div>
                    <span style={{fontSize:10.5,color:w.successRate>=95?T.green:w.successRate>=80?T.amber:T.red,fontFamily:"'Geist Mono',monospace",minWidth:28,textAlign:"right"}}>{w.successRate}%</span>
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        {/* ── Right: workflow detail ── */}
        {wf && (
          <div className="slideIn" style={{flex:1,display:"flex",flexDirection:"column",overflow:"hidden"}}>
            {/* Detail header */}
            <div style={{padding:"16px 24px",borderBottom:`1px solid ${T.border}`,flexShrink:0}}>
              <div style={{display:"flex",alignItems:"flex-start",justifyContent:"space-between",gap:12}}>
                <div>
                  <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:4}}>
                    <span style={{padding:"2px 8px",fontSize:11,fontWeight:600,borderRadius:99,background:`${catColor[wf.category]||T.accent}18`,color:catColor[wf.category]||T.accent,border:`1px solid ${catColor[wf.category]||T.accent}30`}}>{wf.category}</span>
                    {wf.tags.map(t=><span key={t} style={{padding:"2px 7px",fontSize:10,borderRadius:99,background:T.bgHover,color:T.textMuted,border:`1px solid ${T.border}`}}>{t}</span>)}
                  </div>
                  <div style={{fontSize:16,fontWeight:700,color:T.text,marginBottom:3}}>{wf.name}</div>
                  <div style={{fontSize:12,color:T.textSub,lineHeight:1.6}}>{wf.description}</div>
                </div>
                <div style={{display:"flex",gap:8,flexShrink:0}}>
                  <Btn small ghost onClick={()=>onToast("Workflow paused","success")}>Pause</Btn>
                  <Btn small ghost onClick={()=>onToast("Schedule editor opened","success")}>Schedule</Btn>
                  <Btn small variant="primary" icon={Ic.refresh(12)} onClick={()=>triggerRun(wf.id)}>Run now</Btn>
                </div>
              </div>

              {/* Stage pipeline */}
              <div style={{marginTop:14,padding:"10px 14px",background:T.bgElevated,border:`1px solid ${T.border}`,borderRadius:8}}>
                <div style={{fontSize:10.5,color:T.textMuted,marginBottom:6,textTransform:"uppercase",letterSpacing:"0.07em"}}>Pipeline Stages</div>
                <StageBar stages={wf.stages} current={wf.currentStage}/>
              </div>
            </div>

            <div style={{flex:1,overflowY:"auto",padding:"16px 24px"}}>

              {/* Stats row */}
              <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:10,marginBottom:20}}>
                {[
                  {l:"Success Rate", v:`${wf.successRate}%`, c:wf.successRate>=95?T.green:wf.successRate>=80?T.amber:T.red},
                  {l:"Total Runs",   v:wf.totalRuns,         c:T.blue},
                  {l:"Last Duration",v:wf.duration,          c:T.text},
                  {l:"Owner",        v:wf.owner,             c:T.textSub},
                ].map(s=>(
                  <Card2 key={s.l} style={{padding:"10px 14px"}}>
                    <div style={{fontSize:10,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.07em",marginBottom:4}}>{s.l}</div>
                    <div style={{fontSize:14,fontWeight:700,color:s.c,fontFamily:"'Geist Mono',monospace"}}>{s.v}</div>
                  </Card2>
                ))}
              </div>

              {/* Run History */}
              <div style={{marginBottom:16}}>
                <div style={{fontSize:12,fontWeight:600,color:T.text,marginBottom:10}}>Run History</div>
                <Card2 style={{overflow:"hidden",padding:0}}>
                  {wf.history.map((r,i)=>(
                    <div key={i} style={{display:"flex",alignItems:"center",gap:12,padding:"10px 16px",borderBottom:i<wf.history.length-1?`1px solid ${T.border}`:"none"}}>
                      {/* Status dot */}
                      <div style={{width:8,height:8,borderRadius:"50%",background:statusColor[r.status],flexShrink:0}}/>
                      {/* Timestamp */}
                      <span style={{fontSize:12,color:T.textSub,minWidth:120,fontFamily:"'Geist Mono',monospace"}}>{r.ts}</span>
                      {/* Status label */}
                      <span style={{fontSize:11,fontWeight:600,color:statusColor[r.status],minWidth:60}}>{r.status}</span>
                      {/* Duration */}
                      <span style={{fontSize:11,color:T.textMuted,minWidth:70,fontFamily:"'Geist Mono',monospace"}}>{r.duration}</span>
                      {/* Records */}
                      {r.records>0&&<span style={{fontSize:11,color:T.textMuted,fontFamily:"'Geist Mono',monospace"}}>{r.records.toLocaleString()} records</span>}
                      {/* Error msg */}
                      {r.msg&&<span style={{fontSize:11,color:T.amber,flex:1,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>⚠ {r.msg}</span>}
                      {/* Spacer */}
                      {!r.msg&&<div style={{flex:1}}/>}
                      {/* Logs btn */}
                      <button style={{background:"transparent",color:T.textMuted,cursor:"pointer",fontSize:11,padding:"2px 8px",borderRadius:5,border:`1px solid ${T.border}`}} onClick={()=>onToast("Opening run logs…","success")}>Logs</button>
                    </div>
                  ))}
                </Card2>
              </div>

              {/* Config */}
              <div>
                <div style={{fontSize:12,fontWeight:600,color:T.text,marginBottom:10}}>Configuration</div>
                <Card2>
                  <div style={{padding:16}}>
                    {[
                      {l:"Source",    v:wf.source},
                      {l:"Schedule",  v:wf.schedule},
                      {l:"Schedule (human)", v:wf.scheduleLabel},
                      {l:"Category",  v:wf.category},
                      {l:"Owner",     v:wf.owner},
                    ].map(c=>(
                      <div key={c.l} style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"7px 0",borderBottom:`1px solid ${T.border}`,fontSize:12}}>
                        <span style={{color:T.textMuted}}>{c.l}</span>
                        <span style={{color:T.text,fontFamily:"'Geist Mono',monospace"}}>{c.v}</span>
                      </div>
                    ))}
                    <div style={{marginTop:14,display:"flex",gap:8}}>
                      <Btn small icon={Ic.edit(11)} onClick={()=>onToast("Config editor opened","success")}>Edit Config</Btn>
                      <Btn small variant="danger" onClick={()=>onToast("Workflow deleted","error")}>Delete Workflow</Btn>
                    </div>
                  </div>
                </Card2>
              </div>
            </div>
          </div>
        )}

        {/* Empty state when no workflow selected */}
        {!wf && (
          <div style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",color:T.textMuted,gap:12}}>
            {Ic.workflow(40)}
            <div style={{fontSize:14,fontWeight:500,color:T.textSub}}>Select a workflow to view details</div>
            <div style={{fontSize:12,color:T.textMuted}}>Click any workflow in the list to inspect runs, config, and history</div>
          </div>
        )}
      </div>
    </div>
  );
};

// ─────────────────────────────────────────────
